#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096
#define SENSITIVITY 0.001

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
}

// Function to configure the ADS1115
int configure_ads1115(int i2c_handle) {
    // Single-shot mode, AIN0, ±4.096V, 128 SPS
    uint16_t config = 0x4003; //0b0100000000000011
    uint8_t buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = config & 0xFF;
    buf[2] = (config >> 8) & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the conversion register
int16_t read_conversion_register(int i2c_handle) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading conversion register: %d\n", result);
        return -1;
    }

    // Byte order: MSB first
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to convert raw ADC value to amperes
float convert_to_amperes(int16_t raw_value) {
    return (float)raw_value * SENSITIVITY;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115(i2c_handle) != 0) {
        fprintf(stderr, "Error configuring ADS1115\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read conversion register
        int16_t raw_value = read_conversion_register(i2c_handle);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading conversion value\n");
            break; // Exit loop on error
        }

        // Convert to amperes
        float current = convert_to_amperes(raw_value);

        // Log the current value
        printf("Current: %.3f A\n", current);

        // Wait 500ms
        gpioDelay(500000); // microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

