#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define FLAME_SENSOR_GPIO 4
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define CSV_FILE "flame_data.csv"

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize();
int read_flame_sensor();
int read_mcp3008(int channel);
float calculate_temperature(int adc_value);
int log_data(int flame_detected, float temperature);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int flame_gpio;
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    char *csv_file;
} Config;

Config config = {FLAME_SENSOR_GPIO, SPI_CHANNEL, SPI_SPEED, MCP3008_CHANNEL, CSV_FILE};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (program_running) {
        int flame_detected = read_flame_sensor();
        int adc_value = read_mcp3008(config.mcp3008_channel);
        float temperature = calculate_temperature(adc_value);

        if (log_data(flame_detected, temperature) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        gpioDelay(1000); // 1-second interval
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();
    if (fp != NULL) {
        fclose(fp);
    }

    printf("Program terminated gracefully.\n");
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set flame sensor GPIO as input
    gpioSetMode(config.flame_gpio, PI_INPUT);

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for appending
    fp = fopen(config.csv_file, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,FlameDetected,Temperature\n");
    }
    rewind(fp);

    return 0;
}

int read_flame_sensor() {
    // Read digital output from flame sensor
    int value = gpioRead(config.flame_gpio);
    return value;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

float calculate_temperature(int adc_value) {
    // Simple linear approximation (replace with actual calibration data)
    // Assuming 0V = 20°C, 3.3V = 50°C
    float temperature = (float)adc_value / 1023.0 * 3.3 * 10.0 + 20.0;
    return temperature;
}

int log_data(int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Check if the file is open before writing
    if (fp == NULL) {
        fprintf(stderr, "CSV file is not open for writing.\n");
        return 1;
    }

    fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

