#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPi.h>

// Constants
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define TEMP_THRESHOLD 60.0
#define BUZZER_DURATION 2 // seconds
#define DEBOUNCE_DELAY 50 // milliseconds

// Global variables
static volatile bool running = true;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int init_i2c(int bus, int address);
int16_t read_adc(int fd, int channel);
float convert_to_celsius(int16_t raw_value);
void log_event(const char *message);
void signal_handler(int signal);
void flame_detected_callback(void);
void heat_detected_callback(void);

// I2C Initialization
int init_i2c(int bus, int address) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0, +/- 4.096V, 128 SPS
    uint8_t config[3];
    config[0] = CONFIG_REG;
    config[1] = 0x83; // Single-shot mode, AIN0, +/-4.096V
    config[2] = 0x83; // 128 SPS

    if (write(fd, config, 3) != 3) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// ADC Reading
int16_t read_adc(int fd, int channel) {
    uint8_t write_data[1];
    uint8_t read_data[2];

    // Set the channel (not strictly needed for single-ended)
    // For differential, you'd set the mux bits here

    // Start a conversion
    write_data[0] = CONVERSION_REG;
    if (write(fd, write_data, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device for conversion start: %s\n", strerror(errno));
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion result
    write_data[0] = CONVERSION_REG;
