#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <bcm2835.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define FAN_GPIO RPI_GPIO_P1_12 // GPIO18 (BCM)
#define CURRENT_THRESHOLD 5.0 // Amps
#define LOG_FILE "current_log.txt"

// Global variables
static int spi_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, uint32_t speed, uint8_t mode, uint8_t bits_per_word);
int spi_read_adc(int channel);
float adc_to_current(int adc_value);
void log_current(float current);
void control_fan(float current);
void cleanup(int signal);

// Signal handler
void cleanup(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (bcm2835_init()) {
        bcm2835_gpio_write(FAN_GPIO, LOW);
        bcm2835_close();
    }

    exit(0);
}

// SPI initialization function
int spi_init(const char *device, uint32_t speed, uint8_t mode, uint8_t bits_per_word) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI read ADC function
int spi_read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// ADC to current conversion function
float adc_to_current(int adc_value) {
    // Assuming 0V = 0A, 3.3V = 10A (example linear relationship)
    // Adjust these values based on your sensor's datasheet and calibration
    float current = (float)adc_value / 1023.0 * 10.0;
    return current;
}

// Log current function
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    FILE *fp;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, current);
    fclose(fp);
}

// Control fan function
void control_fan(float current) {
    if (current > CURRENT_THRESHOLD) {
        bcm2835_gpio_write(FAN_GPIO, HIGH);
    } else {
        bcm2835_gpio_write(FAN_GPIO, LOW);
    }
}

int main() {
    // Initialize BCM2835 library
    if (!bcm2835_init()) {
        fprintf(stderr, "bcm2835_init failed. Are you running as root?\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_SPEED, SPI_MODE, SPI_BITS_PER_WORD);
    if (spi_fd < 0) {
        bcm2835_close();
        return 1;
    }

    // Configure FAN_GPIO as output
    bcm2835_gpio_fsel(FAN_GPIO, BCM2835_GPIO_FSEL_OUTP);
    bcm2835_gpio_write(FAN_GPIO, LOW); // Ensure fan is off initially

    // Set up signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = spi_read_adc(0); // Read from channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        float current = adc_to_current(adc_value);
        log_current(current);
        control_fan(current);

        printf("Current: %.2f A\n", current);

        sleep(1); // Sample every 1 second
    }

    return 0;
}

