#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_GPIO 4
#define MCP3008_CE0 8
#define MCP3008_CE1 7 // Using CE1 for the second sensor
#define MCP3008_SCLK 11
#define MCP3008_MOSI 10
#define MCP3008_MISO 9

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define CSV file name
#define CSV_FILE "flame_data.csv"

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_flame_sensor();
int read_temperature_sensor(int channel);
int log_data(int flame_presence, int temperature);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int flame_presence;
    int temperature;
} sensor_data_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    if (gpioSetMode(MCP3008_CE0, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", MCP3008_CE0);
        return -1;
    }
    if (gpioSetMode(MCP3008_CE1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", MCP3008_CE1);
        return -1;
    }
    if (gpioSetMode(MCP3008_SCLK, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", MCP3008_SCLK);
        return -1;
    }
    if (gpioSetMode(MCP3008_MOSI, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", MCP3008_MOSI);
        return -1;
    }
    if (gpioSetMode(MCP3008_MISO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", MCP3008_MISO);
        return -1;
    }
    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_GPIO);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    return value;
}

// Function to read the temperature sensor
int read_temperature_sensor(int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];
    int adc_value;

    // MCP3008 command to read a single-ended channel
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CE0, 0); // Select the MCP3008
    gpioWrite(MCP3008_CE1, 1);

    int spi_result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (spi_result != 3) {
        fprintf(stderr, "Error during SPI transfer: %d\n", spi_result);
        gpioWrite(MCP3008_CE0, 1);
        gpioWrite(MCP3008_CE1, 1);
        return -1;
    }

    gpioWrite(MCP3008_CE0, 1); // Deselect the MCP3008
    gpioWrite(MCP3008_CE1, 1);

    adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to log data to CSV file
int log_data(int flame_presence, int temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s\n", CSV_FILE);
        return -1;
    }

    fprintf(fp, "%s,%d,%d\n", timestamp, flame_presence, temperature);
    fclose(fp);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Flame sensor data logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int flame_presence = read_flame_sensor();
        int temperature = read_temperature_sensor(0); // Read from channel 0

        if (flame_presence == -1 || temperature == -1) {
            fprintf(stderr, "Error reading sensor data. Skipping entry.\n");
        } else {
            if (log_data(flame_presence, temperature) != 0) {
                fprintf(stderr, "Error logging data. Skipping entry.\n");
            }
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

