#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_ADDR 0x4A
#define I2C_BUS 1
#define CO_LOG_FILE "co_log.txt"
#define ALERT_LOG_FILE "alert_log.txt"
#define ALERT_THRESHOLD 25.0
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t co;
    uint16_t no2;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
float convert_to_ppm(uint16_t adc_value);
int log_co_data(float co_ppm);
int check_alert_threshold(float co_ppm);
int log_alert(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from MICS-4514
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Error reading from I2C: %d\n", bytes_read);
        return -1;
    }

    data->co = (buf[0] << 8) | buf[1];
    data->no2 = (buf[2] << 8) | buf[3];

    return 0;
}

// Convert ADC value to CO concentration (ppm)
float convert_to_ppm(uint16_t adc_value) {
    // Simple linear conversion (replace with actual calibration data)
    return (float)adc_value * 0.01; // Example: 1 ADC unit = 0.01 ppm
}

// Log CO data to file
int log_co_data(float co_ppm) {
    FILE *fp = fopen(CO_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CO log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f ppm\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);

    fclose(fp);
    return 0;
}

// Check if CO concentration exceeds alert threshold
int check_alert_threshold(float co_ppm) {
    return (co_ppm >= ALERT_THRESHOLD);
}

// Log alert to file
int log_alert(float co_ppm) {
    FILE *fp = fopen(ALERT_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alert log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, CO concentration exceeded %.2f ppm\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);

    fclose(fp);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
