#define ALERT_LOG_FILE "alert_log.txt"
#define ALERT_THRESHOLD 25.0
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t co;
    uint16_t no2;
} sensor_data_t;

