int init_i2c();
int read_sensor_data(sensor_data_t *data);
float convert_to_ppm(uint16_t adc_value);
int log_co_data(float co_ppm);
int check_alert_threshold(float co_ppm);
int log_alert(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from MICS-4514
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Error reading from I2C: %d\n", bytes_read);
        return -1;
    }

    data->co = (buf[0] << 8) | buf[1];
    data->no2 = (buf[2] << 8) | buf[3];

    return 0;
}

// Convert ADC value to CO concentration (ppm)
float convert_to_ppm(uint16_t adc_value) {
    // Simple linear conversion (replace with actual calibration data)
    return (float)adc_value * 0.01; // Example: 1 ADC unit = 0.01 ppm
}

// Log CO data to file
int log_co_data(float co_ppm) {
