#define REG_WHO_AM_I 0x0F
#define REG_CTRL_REG1 0x20
#define REG_OUT_L 0x28
#define REG_OUT_H 0x29

// Define scaling factor (adjust based on datasheet)
#define SCALE_FACTOR 0.1 // Example scaling factor

// Define sampling interval (in milliseconds)
#define SAMPLING_INTERVAL 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
typedef struct {
    float level;
    int error;
} MicrophoneData;

// Function prototypes
int initialize_i2c();
MicrophoneData read_microphone(int i2c_handle, int reg);
float calculate_average(float level1, float level2);
void log_data(float average_level);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Example: Check WHO_AM_I register (adjust based on datasheet)
    int who_am_i = i2cReadByteData(i2c_handle, REG_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        i2cClose(i2c_handle);
        return -1;
    }
    printf("WHO_AM_I register value: 0x%X\n", who_am_i);

    // Example: Configure CTRL_REG1 (adjust based on datasheet)
    int status = i2cWriteByteData(i2c_handle, REG_CTRL_REG1, 0x80); // Example value
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", status);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read microphone data
MicrophoneData read_microphone(int i2c_handle, int reg) {
    MicrophoneData data;
    data.error = 0;

    int low_byte = i2cReadByteData(i2c_handle, reg);
    if (low_byte < 0) {
        fprintf(stderr, "Error reading low byte from register 0x%X: %d\n", reg, low_byte);
        data.level = -999.0;
        data.error = -1;
        return data;
    }

    int high_byte = i2cReadByteData(i2c_handle, reg + 1);
    if (high_byte < 0) {
        fprintf(stderr, "Error reading high byte from register 0x%X: %d\n", reg + 1, high_byte);
        data.level = -999.0;
        data.error = -1;
        return data;
    }

    // Combine bytes to form 16-bit value
    short raw_value = (high_byte << 8) | low_byte;

    // Convert to dB (example)
    data.level = (float)raw_value * SCALE_FACTOR;

    return data;
}

// Function to calculate average level
float calculate_average(float level1, float level2) {
    return (level1 + level2) / 2.0;
}

