        return 1;
    }

    // Set GPIO pins as output (for I2C emulation)
    gpioSetMode(SDA_PIN, PI_OUTPUT);
    gpioSetMode(SCL_PIN, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read microphone data
        MicrophoneData mic1_data = read_microphone(i2c_handle, REG_OUT_L);
        MicrophoneData mic2_data = read_microphone(i2c_handle, REG_OUT_L + 2); // Assuming second microphone is at a different register

        float mic1_level = mic1_data.level;
        float mic2_level = mic2_data.level;

        // Calculate average level
        float average_level = calculate_average(mic1_level, mic2_level);

        // Log data
        log_data(average_level);

        // Wait for sampling interval
        gpioDelay(SAMPLING_INTERVAL * 1000); // Convert ms to us
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

