#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define CE0_PIN 8
#define CE1_PIN 9
#define MISO_PIN 9
#define MOSI_PIN 10
#define SCLK_PIN 11
#define LED_PIN 27

// Define SPI channel
#define SPI_CHANNEL 0

// Define RMS threshold
#define RMS_THRESHOLD 500

// Define LED on time (milliseconds)
#define LED_ON_TIME 500

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold audio data
typedef struct {
    int mic1_data[100];
    int mic2_data[100];
} AudioData;

// Function prototypes
int initialize();
int read_mcp3008(int channel, int ce_pin);
float calculate_rms(int *data, int num_samples);
void log_data(float rms1, float rms2);
void control_led(int rms1, int rms2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the system
int initialize() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(CE0_PIN, PI_OUTPUT);
    gpioSetMode(CE1_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, 1000000, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }

    return 0;
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel, int ce_pin) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(ce_pin, 0); // Select the chip
    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(ce_pin, 1); // Deselect the chip

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate RMS level
float calculate_rms(int *data, int num_samples) {
    long sum_of_squares = 0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (long)data[i] * data[i];
    }
    return sqrt((float)sum_of_squares / num_samples);
}

// Function to log data to file
void log_data(float rms1, float rms2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, rms1, rms2);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to control LED
void control_led(int rms1, int rms2) {
    if (rms1 > RMS_THRESHOLD || rms2 > RMS_THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn LED on
        gpioDelay(LED_ON_TIME * 1000); // Wait for 500ms
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize system
    if (initialize()) {
        return 1;
    }

    AudioData audio_data;

    // Main loop
    while (!terminate) {
        // Read audio data from microphones
        for (int i = 0; i < 100; i++) {
            audio_data.mic1_data[i] = read_mcp3008(0, CE0_PIN);
            audio_data.mic2_data[i] = read_mcp3008(0, CE1_PIN);
            gpioDelay(1); // 1ms delay
        }

        // Calculate RMS levels
        float rms1 = calculate_rms(audio_data.mic1_data, 100);
        float rms2 = calculate_rms(audio_data.mic2_data, 100);

        // Log data
        log_data(rms1, rms2);

        // Control LED
        control_led(rms1, rms2);
    }

    // Clean up resources
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

