// Function to calculate RMS level
float calculate_rms(int *data, int num_samples) {
    long sum_of_squares = 0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (long)data[i] * data[i];
    }
    return sqrt((float)sum_of_squares / num_samples);
}

// Function to log data to file
void log_data(float rms1, float rms2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, rms1, rms2);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to control LED
void control_led(int rms1, int rms2) {
    if (rms1 > RMS_THRESHOLD || rms2 > RMS_THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn LED on
        gpioDelay(LED_ON_TIME * 1000); // Wait for 500ms
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize system
    if (initialize()) {
        return 1;
    }

    AudioData audio_data;

    // Main loop
    while (!terminate) {
        // Read audio data from microphones
        for (int i = 0; i < 100; i++) {
            audio_data.mic1_data[i] = read_mcp3008(0, CE0_PIN);
            audio_data.mic2_data[i] = read_mcp3008(0, CE1_PIN);
            gpioDelay(1); // 1ms delay
        }

        // Calculate RMS levels
        float rms1 = calculate_rms(audio_data.mic1_data, 100);
        float rms2 = calculate_rms(audio_data.mic2_data, 100);

        // Log data
        log_data(rms1, rms2);

        // Control LED
        control_led(rms1, rms2);
    }

    // Clean up resources
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

