#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define WARNING_LED_GPIO 17
#define BUFFER_SIZE 100
#define SAMPLE_RATE 10.0 // Hz
#define VREF 4.096       // Reference voltage
#define SENSITIVITY 0.100 // Current sensitivity (A/V)

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_i2c();
int16_t read_ads1115();
float convert_to_current(int16_t raw_value);
void update_circular_buffer(float current);
float calculate_average_current();
void control_warning_led(float average_current);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw ADC value from ADS1115
int16_t read_ads1115() {
    char buf[2];
    int16_t raw_value;

    // Configure ADS1115 for single-ended A0, 4.096V, 128 SPS, single conversion
    char config[3];
    config[0] = CONFIG_REG;
    config[1] = 0x40; // Single-shot mode, AIN0, +/-4.096V
    config[2] = 0x83; // 128 SPS, 16-bit

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing to config register\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read conversion register
    buf[0] = CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to conversion register\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from conversion register\n");
        return -1;
    }

    raw_value = (buf[0] << 8) | buf[1];
    return raw_value;
}

// Convert raw ADC value to current
float convert_to_current(int16_t raw_value) {
    float current = (float)raw_value * VREF / 32768.0 * SENSITIVITY;
    return current;
}

// Update circular buffer with new current reading
void update_circular_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate average current from circular buffer
float calculate_average_current() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Control warning LED based on average current
void control_warning_led(float average_current) {
    if (average_current > 50.0) {
        gpioWrite(WARNING_LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(WARNING_LED_GPIO, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set warning LED GPIO as output
    gpioSetMode(WARNING_LED_GPIO, PI_OUTPUT);
    gpioWrite(WARNING_LED_GPIO, 0); // Initially turn LED off

    // Main loop
    while (!terminate) {
        int16_t raw_value = read_ads1115();
        if (raw_value == -1) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        float current = convert_to_current(raw_value);
        update_circular_buffer(current);
        float average_current = calculate_average_current();
        control_warning_led(average_current);

        printf("Current: %.3f A, Average Current: %.3f A\n", current, average_current);

        gpioDelay(1000000 / SAMPLE_RATE); // Delay to achieve desired sampling rate
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(WARNING_LED_GPIO, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

