#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// TCS34725 I2C address
#define TCS34725_I2C_ADDR 0x29

// TCS34725 register addresses
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x90
#define TCS34725_RDATA 0x92
#define TCS34725_GDATA 0x94
#define TCS34725_BDATA 0x96

// Expected sensor ID
#define TCS34725_ID 0x44

// File to log data to
#define LOG_FILE "color_log.csv"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    unsigned int clear;
    unsigned int red;
    unsigned int green;
    unsigned int blue;
} sensor_data_t;

// Function prototypes
int init_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

// Initialize the sensor
int init_sensor() {
    int retries = 3;
    int status;

    // Enable the sensor
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03); // Power on and enable RGBC
        if (status >= 0) break;
        fprintf(stderr, "Error enabling sensor: %d, retrying...\n", status);
        gpioDelay(1000); // Wait 1ms before retrying
        retries--;
    }
    if (status < 0) {
        fprintf(stderr, "Failed to enable sensor after multiple retries.\n");
        return -1;
    }

    // Set integration time (ATIME).  A longer integration time gives better color resolution.
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xD5); // 2.4ms integration time
        if (status >= 0) break;
        fprintf(stderr, "Error setting integration time: %d, retrying...\n", status);
        gpioDelay(1000); // Wait 1ms before retrying
        retries--;
    }
    if (status < 0) {
        fprintf(stderr, "Failed to set integration time after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int status;

    // Read clear data
    status = i2cReadWordData(i2c_handle, TCS34725_CDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading clear data: %d\n", status);
        data.clear = 0; // Set to 0 to avoid garbage values
    } else {
        data.clear = (unsigned int)status;
    }

    // Read red data
    status = i2cReadWordData(i2c_handle, TCS34725_RDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading red data: %d\n", status);
        data.red = 0; // Set to 0 to avoid garbage values
    } else {
        data.red = (unsigned int)status;
    }

    // Read green data
    status = i2cReadWordData(i2c_handle, TCS34725_GDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading green data: %d\n", status);
        data.green = 0; // Set to 0 to avoid garbage values
    } else {
        data.green = (unsigned int)status;
    }

    // Read blue data
    status = i2cReadWordData(i2c_handle, TCS34725_BDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading blue data: %d\n", status);
        data.blue = 0; // Set to 0 to avoid garbage values
    } else {
        data.blue = (unsigned int)status;
    }

    return data;
}

// Log data to file
void log_data(sensor_data_t data) {
    FILE *fp = fopen(LOG_FILE, "a+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,clear,red,green,blue\n");
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Write data to file
    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, data.clear, data.red, data.green, data.blue);

    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Get sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, 0x12); // Read ID register
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (sensor_id != TCS34725_ID) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X (expected 0x%02X)\n", sensor_id, TCS34725_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t data = read_sensor_data();

        // Log data
        log_data(data);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup
    cleanup();

    return 0;
}

