#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MLX90817_ADDR 0x60
#define PRESSURE_REG 0x00 // Example register address
#define LOG_FILE "pressure_log.csv"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure_kPa;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_pressure(float *pressure);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read pressure from sensor
int read_pressure(float *pressure) {
    char buf[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
        if (result >= 0) {
            // Convert raw data to pressure (example conversion)
            int raw_pressure = (buf[0] << 8) | buf[1];
            *pressure = (float)raw_pressure * 0.1; // Example scaling
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", PRESSURE_REG, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read pressure after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Log data to file
int log_data(sensor_data_t data) {
    struct tm *tm_info;
    char timestamp_str[30];

    tm_info = gmtime(&data.timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return -1;
        }
        fprintf(log_file, "timestamp,pressure_kPa\n"); // Header
    }

    fprintf(log_file, "%s,%.2f\n", timestamp_str, data.pressure_kPa);
    fflush(log_file); // Flush to disk

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t data;
        float pressure;

        // Read pressure
        if (read_pressure(&pressure) == 0) {
            // Get timestamp
            data.timestamp = time(NULL);
            data.pressure_kPa = pressure;

            // Log data
            if (log_data(data) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read pressure.\n");
        }

        sleep(1); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

