#include <wiringPiSPI.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define ALARM_THRESHOLD 1000.0 // ppm
#define LOG_FILE "methane_log.txt"

// Global variables
static volatile int keepRunning = 1;
static int spiFd = -1;
static FILE *logFile = NULL;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_ppm(int adc_value);
void log_data(float ppm_value);
void alarm_check(float ppm_value);
void signal_handler(int signal);
int setup();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = -1;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1; // Indicate SPI transfer failure
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to convert ADC value to ppm (example linear conversion)
float adc_to_ppm(int adc_value) {
    // Assuming 0-1023 maps to 0-1000 ppm (example)
    return (float)adc_value * 1000.0 / 1023.0;
}

// Function to log data to file
void log_data(float ppm_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (logFile != NULL) {
        fprintf(logFile, "%s, %.2f ppm\n", timestamp, ppm_value);
        fflush(logFile); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Function to check for alarm condition
void alarm_check(float ppm_value) {
    if (ppm_value > ALARM_THRESHOLD) {
        fprintf(stderr, "ALARM: Methane concentration exceeds %.2f ppm!\n", ALARM_THRESHOLD);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    keepRunning = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Setup function
int setup() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed: %s\n", strerror(errno));
        return -1;
    }

    // Initialize SPI
    spiFd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spiFd == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return -1;
