#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define FULL_SCALE_VOLTAGE 4.096
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 100.0
#define SAMPLE_RATE_HZ 1
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int i2c_bus;
    int ads1115_address;
    double full_scale_voltage;
    double pressure_min;
    double pressure_max;
    int sample_rate_hz;
    char *log_file;
} Config;

// Function prototypes
int initialize_i2c(int bus, int addr);
int configure_ads1115(int handle, int i2c_bus, int ads1115_address);
int read_ads1115(int handle, int i2c_bus, int ads1115_address, int16_t *raw_value);
double convert_to_pressure(int16_t raw_value, double full_scale_voltage);
int validate_pressure(double pressure, double pressure_min, double pressure_max);
int log_pressure(double pressure, const char *timestamp, const char *filename);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02x: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Configure ADS1115
int configure_ads1115(int handle, int i2c_bus, int ads1115_address) {
    // Configure register settings for single-shot mode, AIN0, +/-4.096V, 128 SPS
    uint16_t config = 0x4003; // Single-shot mode, AIN0, +/-4.096V, 128 SPS
    config |= (0x03 << 12); // 128 SPS
    config |= (0x03 << 9);  // +/-4.096V
    config |= (0x4000);     // Start single conversion

    int result = i2cWriteWordData(handle, CONFIG_REG, config);
    if (result < 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read ADS1115
int read_ads1115(int handle, int i2c_bus, int ads1115_address, int16_t *raw_value) {
    int result = i2cReadWordData(handle, CONVERSION_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading from conversion register: %d\n", result);
        return -1;
    }
    *raw_value = (int16_t)result;
    return 0;
}

// Convert to pressure
double convert_to_pressure(int16_t raw_value, double full_scale_voltage) {
    double voltage = (double)raw_value * (full_scale_voltage / 32768.0);
    return (voltage - 0.1) / 0.00435; // Linear approximation
}

// Validate pressure
int validate_pressure(double pressure, double pressure_min, double pressure_max) {
    if (pressure >= pressure_min && pressure <= pressure_max) {
        return 0; // Valid
    } else {
        return -1; // Invalid
    }
}

// Log pressure
int log_pressure(double pressure, const char *timestamp, const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", filename);
        return -1;
    }
    fprintf(fp, "%s,%.2f\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Configuration
    Config config = {
        .i2c_bus = I2C_BUS,
        .ads1115_address = ADS1115_ADDR,
        .full_scale_voltage = FULL_SCALE_VOLTAGE,
        .pressure_min = PRESSURE_MIN,
        .pressure_max = PRESSURE_MAX,
        .sample_rate_hz = SAMPLE_RATE_HZ,
        .log_file = LOG_FILE
    };

    // Initialize I2C
    i2c_handle = initialize_i2c(config.i2c_bus, config.ads1115_address);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115(i2c_handle, config.i2c_bus, config.ads1115_address) < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int16_t raw_value;
        if (read_ads1115(i2c_handle, config.i2c_bus, config.ads1115_address, &raw_value) == 0) {
            double pressure = convert_to_pressure(raw_value, config.full_scale_voltage);
            if (validate_pressure(pressure, config.pressure_min, config.pressure_max) == 0) {
                // Get timestamp
                time_t now = time(NULL);
                struct tm *tstruct = localtime(&now);
                char timestamp[80];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tstruct);

                // Log pressure
                if (log_pressure(pressure, timestamp, config.log_file) != 0) {
                    fprintf(stderr, "Error logging pressure\n");
                }
            } else {
                fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Error reading ADS1115\n");
        }

        gpioDelay(1000000 / config.sample_rate_hz); // Delay for 1Hz
    }

    // Cleanup
    cleanup();
    return 0;
}

