#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define HUMIDITY_CHANNEL 0
#define TEMPERATURE_CHANNEL 1
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com" // Replace with actual email

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_adc(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
int log_data(float humidity, float temperature);
int send_email_alert(float humidity, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from specified channel
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3208 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calculate humidity from ADC value
float calculate_humidity(int adc_value) {
    // HIH-4602-A humidity calculation (from datasheet)
    float humidity = ((float)adc_value / 1023.0) * 100.0;
    return humidity;
}

// Calculate temperature from ADC value
float calculate_temperature(int adc_value) {
    // HIH-4602-A temperature calculation (from datasheet)
    float temperature = ((float)adc_value / 1023.0) * 165.0 - 40.0;
    return temperature;
}

// Log data to file
int log_data(float humidity, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Send email alert
int send_email_alert(float humidity, float temperature) {
    char command[256];
    snprintf(command, sizeof(command), "echo \"Humidity: %.2f%%, Temperature: %.2f°C\nPotential leak detected!\" | ssmtp -t %s", humidity, temperature, EMAIL_RECIPIENT);
    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error sending email\n");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC values
        int humidity_adc = read_adc(HUMIDITY_CHANNEL);
        int temperature_adc = read_adc(TEMPERATURE_CHANNEL);

        if (humidity_adc == -1 || temperature_adc == -1) {
            fprintf(stderr, "Error reading ADC values\n");
            continue; // Skip to the next iteration
        }

        // Calculate humidity and temperature
        float humidity = calculate_humidity(humidity_adc);
        float temperature = calculate_temperature(temperature_adc);

        // Log data
        log_data(humidity, temperature);

        // Check for alert condition
        if (humidity > HUMIDITY_THRESHOLD) {
            printf("Alert: Humidity exceeds threshold!\n");
            send_email_alert(humidity, temperature);
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Clean up
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Humidity monitoring stopped.\n");
    return 0;
}

