#include <pigpio.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define ADC_VREF 3.3
#define ADC_RESOLUTION 12
#define TEMPERATURE_MIN -40.0
#define TEMPERATURE_MAX 125.0
#define LOG_FILE "temperature_log.csv"
#define SAMPLE_RATE 1 // Hz

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_open(const char *device);
int spi_configure(int fd, int mode, int bits_per_word, int speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_adc(int fd, int channel);
float convert_to_celsius(int adc_value);
int log_temperature(float temperature);
void signal_handler(int signal);
int gpio_export(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);

// SPI open function
int spi_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }
    return fd;
}

// SPI configure function
int spi_configure(int fd, int mode, int bits_per_word, int speed) {
    int ret;

    ret = ioctl(fd, SPI_IOC_WR_MODE, &mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        return -1;
    }

    ret = ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word);
    if (ret == -1) {
        perror("Error setting SPI bits per word");
        return -1;
    }

    ret = ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error setting SPI speed");
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &transfer);
    if (ret < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read ADC function
int read_adc(int fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message (MCP3208 datasheet)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error during ADC read\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Convert to Celsius function
float convert_to_celsius(int adc_value) {
    float voltage = (adc_value / (float)((1 << ADC_RESOLUTION) - 1)) * ADC_VREF;
    float temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

// Log temperature function
int log_temperature(float temperature) {
    time_t now = time(NULL);
