    if (write(fd, value ? "1" : "0", 1) < 0) {
        perror("gpio/value");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Export and configure GPIO pins
    if (gpio_export(8) < 0 || gpio_export(11) < 0 || gpio_export(10) < 0 || gpio_export(9) < 0) {
        gpioTerminate();
        return 1;
    }
    gpioSetMode(8, PI_OUTPUT); // CE0
    gpioSetMode(11, PI_OUTPUT); // SCLK
    gpioSetMode(10, PI_OUTPUT); // MOSI
    gpioSetMode(9, PI_INPUT);  // MISO

