// Structure for SPI configuration (optional)
typedef struct {
    int channel;
    int speed;
    int ce_pin;
} spi_config_t;

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;           // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    gpioWrite(CE_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CE_PIN, 1); // Deselect the MCP3008

    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to log data to file
void log_data(int x, int y, int z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written immediately
}

// Function to check for impact
void check_impact(int x, int y, int z) {
    if (abs(x) > IMPACT_THRESHOLD || abs(y) > IMPACT_THRESHOLD || abs(z) > IMPACT_THRESHOLD) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s,IMPACT DETECTED\n", timestamp);
        fflush(log_file);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CE pin as output
    gpioSetMode(CE_PIN, PI_OUTPUT);
    gpioWrite(CE_PIN, 1); // Deselect MCP3008 initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Monitoring for impact... Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int x = read_mcp3008(0);
        int y = read_mcp3008(1);
        int z = read_mcp3008(2);

        if (x == -1 || y == -1 || z == -1) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        log_data(x, y, z);
        check_impact(x, y, z);

        gpioDelay(SAMPLE_PERIOD); // Delay to achieve 100Hz sampling rate
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

