#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 5.0
#define LOG_FILE "flow_log.csv"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
static volatile int keepRunning = 1;
static FILE *logFile = NULL;

// Function prototypes
int init_spi();
int read_adc(int channel);
float convert_to_flow_rate(int adc_value);
int validate_flow_rate(float flow_rate);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, exiting gracefully.\n", signal);
    keepRunning = 0;
}

// Initialize SPI
int init_spi() {
    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "Error initializing SPI: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read ADC value
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char buffer[3];
    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    int adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Convert ADC value to flow rate (L/min)
float convert_to_flow_rate(int adc_value) {
    // Assuming a linear relationship between ADC value and flow rate
    // You'll need to calibrate this based on your sensor's datasheet
    // and the characteristics of your experimental setup.
    // This is a placeholder; replace with your actual calibration data.
    float flow_rate = (float)adc_value / 1023.0 * 5.0; // Assuming 0-5V range
    return flow_rate;
}

// Validate flow rate
int validate_flow_rate(float flow_rate) {
    if (flow_rate < FLOW_RATE_MIN || flow_rate > FLOW_RATE_MAX) {
        fprintf(stderr, "Invalid flow rate: %.2f L/min\n", flow_rate);
        return -1;
    }
    return 0;
}

// Log flow rate to file
int log_flow_rate(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", (long int)(time(NULL) * 1000000) % 1000000);

    fprintf(logFile, "%s,%.2f\n", timestamp, flow_rate);
    fflush(logFile); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (init_spi() == -1) {
        return 1;
    }

    // Open log file
    logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Starting flow rate measurement...\n");

    while (keepRunning) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert to flow rate
        float flow_rate = convert_to_flow_rate(adc_value);

        // Validate flow rate
        if (validate_flow_rate(flow_rate) == -1) {
            fprintf(stderr, "Invalid flow rate, skipping logging.\n");
            continue; // Skip to the next iteration
        }

        // Log flow rate
        log_flow_rate(flow_rate);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    if (logFile != NULL) {
        fclose(logFile);
    }

    return 0;
}

