            sleep(RETRY_DELAY_SEC);
            continue;
        }

        // Verify checksum
        if (verify_checksum(raw_data) != 0) {
            fprintf(stderr, "Checksum verification failed, skipping data point.\n");
            continue;
        }

        // Process data
        data = process_data(raw_data);

        // Log data
        log_data(data);

        // Display data
        display_data(data);

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

