        printf("Timestamp: %s, ADC Value: %d\n", timestamp, adc_value);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL * 1000000); // Delay in microseconds
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

