#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float read_ambient_temperature();
float compensate_voltage(int raw_adc, float temperature);
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (3 bytes)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Dummy byte

    // Perform SPI transfer
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to read ambient temperature from file
float read_ambient_temperature() {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open ambient temperature file, using default temperature (25.0°C)\n");
        return 25.0;
    }

    float temperature;
    if (fscanf(fp, "%f", &temperature) != 1) {
        fprintf(stderr, "Warning: Could not read temperature from file, using default temperature (25.0°C)\n");
        fclose(fp);
        return 25.0;
    }

    fclose(fp);
    return temperature;
}

// Function to compensate voltage
float compensate_voltage(int raw_adc, float temperature) {
    // Simple linear compensation (adjust as needed)
    return (float)raw_adc * (3.3 / 1023.0) * (1 + (temperature - 25.0) / 10.0); // Example compensation
}

// Function to log data to file
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.1f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off initially

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off buzzer
    gpioWrite(BUZZER_GPIO, 0);

    // Close SPI channel
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    float temperature = read_ambient_temperature();
    int raw_adc, retries;
    float voltage, compensated_voltage;
    int flame_detected;

    while (!terminate) {
        retries = 0;
        do {
            raw_adc = read_mcp3008(0);
            if (raw_adc < 0) {
                fprintf(stderr, "Error: Failed to read ADC value, retrying (%d/%d)\n", retries + 1, MAX_RETRIES);
                retries++;
                gpioDelay(100); // Wait before retrying
            } else {
                break; // Exit retry loop if read is successful
            }
        } while (retries <= MAX_RETRIES && !terminate);

        if (raw_adc >= 0) {
            voltage = (float)raw_adc * (3.3 / 1023.0);
            compensated_voltage = compensate_voltage(raw_adc, temperature);
            flame_detected = (raw_adc > 500) ? 1 : 0; // Example threshold

            log_data(raw_adc, voltage, compensated_voltage, temperature, flame_detected);

            if (flame_detected) {
                gpioWrite(BUZZER_GPIO, 1); // Turn on buzzer
            } else {
                gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
            }
        } else {
            fprintf(stderr, "Error: Failed to read ADC value after multiple retries\n");
        }

        gpioDelay(500); // Sample every 500ms
    }

    cleanup();
    return 0;
}

