    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d,%.3f,%.3f,%.1f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off initially

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    // Turn off buzzer
    gpioWrite(BUZZER_GPIO, 0);

    // Close SPI channel
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    float temperature = read_ambient_temperature();
    int raw_adc, retries;
    float voltage, compensated_voltage;
    int flame_detected;

    while (!terminate) {
        retries = 0;
        do {
            raw_adc = read_mcp3008(0);
            if (raw_adc < 0) {
                fprintf(stderr, "Error: Failed to read ADC value, retrying (%d/%d)\n", retries + 1, MAX_RETRIES);
                retries++;
                gpioDelay(100); // Wait before retrying
            } else {
                break; // Exit retry loop if read is successful
            }
        } while (retries <= MAX_RETRIES && !terminate);

        if (raw_adc >= 0) {
            voltage = (float)raw_adc * (3.3 / 1023.0);
            compensated_voltage = compensate_voltage(raw_adc, temperature);
            flame_detected = (raw_adc > 500) ? 1 : 0; // Example threshold

            log_data(raw_adc, voltage, compensated_voltage, temperature, flame_detected);

            if (flame_detected) {
                gpioWrite(BUZZER_GPIO, 1); // Turn on buzzer
            } else {
                gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
            }
        } else {
            fprintf(stderr, "Error: Failed to read ADC value after multiple retries\n");
        }

        gpioDelay(500); // Sample every 500ms
    }

    cleanup();
    return 0;
}

