#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define MIN_CALIBRATION 300
#define MAX_CALIBRATION 700
#define MOISTURE_THRESHOLD 30
#define LOGGING_INTERVAL 60
#define EMAIL_RECIPIENT "recipient@example.com"
#define MSMTP_CONFIG_FILE "/etc/msmtprc"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value, int min_calibration, int max_calibration);
void log_data(float moisture_percentage);
void send_email_alert(float moisture_percentage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value, int min_calibration, int max_calibration) {
    if (adc_value < min_calibration) {
        return 0.0;
    } else if (adc_value > max_calibration) {
        return 100.0;
    } else {
        return 100.0 - ((float)(adc_value - min_calibration) / (float)(max_calibration - min_calibration) * 100.0);
    }
}

// Function to log data to file
void log_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percentage);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to send email alert
void send_email_alert(float moisture_percentage) {
    char command[256];
    char body[256];
    FILE *pipe;

    snprintf(body, sizeof(body), "Subject: Low Soil Moisture Alert\n\nPlant moisture is below threshold (%.2f%%).", moisture_percentage);
    snprintf(command, sizeof(command), "echo \"%s\" | msmtp -t %s -C %s", body, EMAIL_RECIPIENT, MSMTP_CONFIG_FILE);

    pipe = popen(command, "r");
    if (pipe == NULL) {
        fprintf(stderr, "Error: Failed to execute msmtp command\n");
        return;
    }

    int status = pclose(pipe);
    if (status != 0) {
        fprintf(stderr, "Error: msmtp command failed with status %d\n", status);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, 500000, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("plant_data.txt", "a");
    if (log_file == NULL) {
