    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - ADC Value: %d\n", timestamp, adc_value);
}

// Signal Handler Function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Setup signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed, exiting...\n");
        return 1;
    }

    // Open SPI device
    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        return 1;
    }

    printf("Soil Moisture Sensor Reader\n");

    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
        } else {
            // Log data
            log_data(adc_value);

            // Check for sensor errors
            if (adc_value == 0 || adc_value == 1023) {
                fprintf(stderr, "Warning: Sensor may be absent or wiring may be faulty. ADC value: %d\n", adc_value);
            }
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close SPI device
    if (spi_close(spi_fd) < 0) {
        return 1;
    }

    printf("Program finished.\n");

    return 0;
}

