#define MCP3008_START_BIT 0x01
#define MCP3008_SINGLE_ENDED 0x08
#define MCP3008_CHANNEL_MASK 0x07

// Global variable for SPI handle
int spi_handle = -1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message
    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = MCP3008_START_BIT;
    tx_buffer[1] = MCP3008_SINGLE_ENDED | (channel & MCP3008_CHANNEL_MASK);
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    // Map ADC value (0-1023) to moisture percentage (0-100)
    float moisture_percentage = (float)adc_value / 1023.0 * 100.0;
    return moisture_percentage;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI device
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    printf("Soil Moisture Sensor Reader\n");

    // Main loop
    while (1) {
        // Read ADC value from channel 0
