    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(data_file, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, voltages[0], voltages[1], voltages[2], voltages[3]);
    fflush(data_file); // Ensure data is written to disk immediately

    return 0;
}

// Close SPI device
int spi_close(void) {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
    return 0;
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open data file
    data_file = fopen("environmental_data.csv", "a");
    if (data_file == NULL) {
        perror("Error opening data file");
        spi_close();
        return 1;
    }

    // Write header if the file is newly created
    fseek(data_file, 0, SEEK_END);
    long file_size = ftell(data_file);
    if (file_size == 0) {
        fprintf(data_file, "Timestamp,Voltage0,Voltage1,Voltage2,Voltage3\n");
    }
    rewind(data_file);

    printf("Starting data acquisition...\n");

    while (!terminate) {
        float voltages[NUM_SENSORS];
        int adc_value;

        // Read sensor values
        for (int i = 0; i < NUM_SENSORS; i++) {
            adc_value = read_mcp3008(i);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading sensor %d. Skipping.\n", i);
                voltages[i] = -1.0; // Indicate error
            } else {
                voltages[i] = convert_to_voltage(adc_value);
            }
        }

        // Log data
        if (log_data(voltages) < 0) {
            fprintf(stderr, "Error logging data. \n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(data_file);
    spi_close();

    printf("Exiting.\n");
    return 0;
}

