int read_register(int handle, int reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a register
int write_register(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the sensor
int initialize_sensor(int handle) {
    int part_id = read_register(handle, PART_ID_REG);
    if (part_id < 0) return -1;
    if (part_id != 0x15) {
        fprintf(stderr, "Error: Invalid Part ID: 0x%02X\n", part_id);
