#define RELAY_PULSE_DURATION 3.0 // seconds
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_INTERVAL 50 // milliseconds
#define SAMPLE_INTERVAL 200 // milliseconds
#define LOG_FILE "/var/log/door_events.log"

