static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
int i2c_write_word(int fd, uint8_t reg, uint16_t value);
int read_ads1115(int fd);
float calibrate_distance(int fd);
int read_reed_sensor(int gpio);
void log_event(const char *message);
void signal_handler(int signal);

// I2C read function
int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// I2C write function
int i2c_write_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Read ADS1115 ADC value
int read_ads1115(int fd) {
    uint16_t config = ADS1115_CONFIG_DEFAULT | 0x8000; // Start single conversion
    if (i2c_write_word(fd, ADS1115_CONFIG_REG, config) < 0) {
        return -1;
    }
    gpioDelay(10); // Wait for conversion
    int16_t value = i2c_read_word(fd, ADS1115_CONVERSION_REG);
    if (value < 0) {
        return -1;
    }
    return value;
}

// Calibrate distance sensor
float calibrate_distance(int fd) {
    long sum = 0;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int reading = read_ads1115(fd);
        if (reading < 0) {
            fprintf(stderr, "Error reading ADC during calibration, using default value.\n");
            return 100.0; // Default value
        }
        sum += reading;
        gpioDelay(CALIBRATION_INTERVAL);
    }
    return (float)sum / CALIBRATION_SAMPLES;
}

// Read reed sensor
int read_reed_sensor(int gpio) {
    return gpioRead(gpio);
}

