void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure relay GPIO
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is initially off

    // Configure door sensor GPIO
    gpioSetMode(DOOR_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(DOOR_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Calibrate distance sensor
    float baseline_distance = calibrate_distance(i2c_fd);
    printf("Baseline distance: %.2f\n", baseline_distance);

    // Main loop
    while (!terminate) {
        // Read distance sensor
        int adc_value = read_ads1115(i2c_fd);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, skipping.\n");
            gpioDelay(SAMPLE_INTERVAL);
            continue;
        }

        // Calculate distance (example formula, adjust as needed)
        float distance = baseline_distance - (float)adc_value * 0.5; // Example conversion

        // Check if distance is below threshold
        if (distance < DISTANCE_THRESHOLD) {
            printf("Distance below threshold: %.2f mm\n", distance);

            // Activate relay
            gpioWrite(RELAY_GPIO, 1);
            printf("Relay activated\n");

            // Wait for relay pulse duration
            gpioDelay(RELAY_PULSE_DURATION * 1000); // Convert seconds to milliseconds

            // Deactivate relay
            gpioWrite(RELAY_GPIO, 0);
            printf("Relay deactivated\n");

            // Read reed sensor
            int door_open = read_reed_sensor(DOOR_SENSOR_GPIO);

            // Log event
            if (door_open == 0) {
                log_event("door opened");
                printf("Door opened\n");
            } else {
                log_event("door not opened");
                printf("Door not opened\n");
            }
        }

        // Wait for next sample
        gpioDelay(SAMPLE_INTERVAL);
    }

    // Cleanup
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

