    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
    }
    rewind(log_file);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor values
        sensor1 = read_mcp3008(0, CS0_PIN);
        sensor2 = read_mcp3008(0, CS1_PIN);
        sensor3 = read_mcp3008(0, CS2_PIN);

        // Log data
        if (sensor1 == -1 || sensor2 == -1 || sensor3 == -1) {
            fprintf(stderr, "Error reading sensor data, logging -1\n");
            log_data(-1, -1, -1);
        } else {
            log_data(sensor1, sensor2, sensor3);
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

