// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 18
#define DEFAULT_THRESHOLD 30.0
#define DEFAULT_PUMP_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
double threshold = DEFAULT_THRESHOLD;
int pump_duration = DEFAULT_PUMP_DURATION;
int sleep_interval = DEFAULT_SLEEP_INTERVAL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double calculate_moisture_percentage(int adc_value);
void control_pump(int state);
void log_message(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int count, adc_value;

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;

    for (count = 0; count < MAX_RETRIES; count++) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 3) {
            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            log_message("SPI communication error. Retrying...");
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    log_message("SPI communication failed after multiple retries.");
    return -1; // Indicate error
}

// Function to calculate moisture percentage
double calculate_moisture_percentage(int adc_value) {
    return ((double)adc_value / 1023.0) * 100.0;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    if (state == 1) {
        log_message("Pump turned ON");
    } else {
        log_message("Pump turned OFF");
    }
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message("Received signal, shutting down...");
    terminate = 1;
    control_pump(0); // Turn off the pump
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 'd':
                pump_duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d pump_duration] [-s sleep_interval]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    control_pump(0); // Ensure pump is off initially

    // Open log file
    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Irrigation system started");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            double moisture_percentage = calculate_moisture_percentage(adc_value);
            char message[100];
            snprintf(message, sizeof(message), "Moisture level: %.2f%% (ADC: %d)", moisture_percentage, adc_value);
            log_message(message);

            if (moisture_percentage < threshold) {
                log_message("Moisture level below threshold, activating pump");
                control_pump(1);
                gpioDelay(pump_duration * 1000); // Pump duration in milliseconds
                control_pump(0);
            }
        } else {
            log_message("Failed to read moisture level");
        }

        gpioDelay(sleep_interval * 1000); // Sleep interval in milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_pump(0);
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

