#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define PEAK_THRESHOLD 500
#define SAMPLE_INTERVAL_MS 10
#define LOG_FILE "/var/log/sound_events.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
int detect_peak(int value, int threshold);
void log_event(int value);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to detect peak
int detect_peak(int value, int threshold) {
    return (value > threshold) ? 1 : 0;
}

// Function to log event to file
void log_event(int value) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Value: %d\n", buf, value);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Could not open log file for writing.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file for writing\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int peak_detected = 0;
    int current_value, previous_value = 0;

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        current_value = read_adc(ADC_CHANNEL);
        if (current_value < 0) {
            fprintf(stderr, "Error: ADC read failed\n");
            break; // Exit loop on ADC read error
        }

        if (detect_peak(current_value, PEAK_THRESHOLD)) {
            if (!peak_detected) {
                log_event(current_value);
                peak_detected = 1;
            }
        } else {
            peak_detected = 0;
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 10ms
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Sound level monitoring stopped.\n");

    return 0;
}

