#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48
#define PCF8591_CONTROL_BYTE 0x40 // Enable ADC, AIN0

int i2c_fd = -1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, cleaning up...\n");
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        exit(0);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Dummy read
        if (write(i2c_fd, &PCF8591_CONTROL_BYTE, 1) != 1) {
            perror("Error writing to I2C device");
            close(i2c_fd);
            return 1;
        }
        uint8_t dummy_read;
        if (read(i2c_fd, &dummy_read, 1) != 1) {
            perror("Error reading from I2C device");
            close(i2c_fd);
            return 1;
        }

        // Read ADC value
        if (write(i2c_fd, &PCF8591_CONTROL_BYTE, 1) != 1) {
            perror("Error writing to I2C device");
            close(i2c_fd);
            return 1;
        }
        uint8_t adc_value;
        if (read(i2c_fd, &adc_value, 1) != 1) {
            perror("Error reading from I2C device");
            close(i2c_fd);
            return 1;
        }

        // Print ADC value
        printf("ADC Value: %d\n", adc_value);

        // Delay
        usleep(100000); // 100ms
    }

    return 0;
}

