// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float magnetic_field_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize();
int read_ads1115();
float convert_to_magnetic_field(int16_t raw_value);
void update_circular_buffer(float magnetic_field);
float calculate_rolling_average();
void check_threshold(float rolling_average);
void shutdown_gpio();
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %d", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO27 as output
    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, PI_LOW);

    // Initialize syslog
    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);

    syslog(LOG_INFO, "Initialization complete");
    return 0;
}

// Function to read from ADS1115
int read_ads1115() {
    char config[3];
    char buffer[2];
    int16_t raw_value;

    // Configure ADS1115 for single-ended AIN0, 4.096V, 128 SPS, single conversion
    config[0] = CONFIG_REG;
    config[1] = 0xC3; // 0b11000011
    config[2] = 0x83; // 0b10000011

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        syslog(LOG_ERR, "Failed to write configuration to ADS1115");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read conversion register
    config[0] = CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        syslog(LOG_ERR, "Failed to write conversion register address to ADS1115");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        syslog(LOG_ERR, "Failed to read conversion data from ADS1115");
        return -1;
    }

    raw_value = (buffer[0] << 8) | buffer[1];
    return raw_value;
}

