float convert_to_magnetic_field(int16_t raw_value) {
    float voltage = (float)raw_value * VREF / 32768.0; // 2^15 -1
    float magnetic_field = voltage / SENSITIVITY;
    return magnetic_field;
}

// Function to update circular buffer
void update_circular_buffer(float magnetic_field) {
    magnetic_field_buffer[buffer_index] = magnetic_field;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate rolling average
float calculate_rolling_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += magnetic_field_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to check threshold and trigger shutdown
void check_threshold(float rolling_average) {
    if (fabs(rolling_average) > GAUSS_THRESHOLD) {
        syslog(LOG_WARNING, "Threshold exceeded! Rolling average: %.2f Gauss", rolling_average);
        shutdown_gpio();
    }
}

// Function to shutdown GPIO
void shutdown_gpio() {
    gpioWrite(GPIO_SHUTDOWN, PI_HIGH);
    syslog(LOG_ERR, "GPIO %d set HIGH to initiate shutdown", GPIO_SHUTDOWN);
}

// Cleanup function
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    i2cClose(i2c_handle);
    gpioWrite(GPIO_SHUTDOWN, PI_LOW);
    gpioTerminate();
    closelog();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        int raw_value = read_ads1115();
        if (raw_value != -1) {
            float magnetic_field = convert_to_magnetic_field(raw_value);
            update_circular_buffer(magnetic_field);
            float rolling_average = calculate_rolling_average();
            check_threshold(rolling_average);
            syslog(LOG_INFO, "Magnetic field: %.2f Gauss, Rolling average: %.2f Gauss", magnetic_field, rolling_average);
        } else {
            syslog(LOG_WARNING, "Failed to read ADC value, skipping sample");
        }

        gpioDelay(1000000); // 1 Hz
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

