#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000

// Define rain sensor channel
#define RAIN_SENSOR_CHANNEL 0

// Define rainfall intensity mapping
#define MIN_ADC_VALUE 0
#define MAX_ADC_VALUE 1023
#define MIN_INTENSITY 0
#define MAX_INTENSITY 100

// Global variable for SPI handle
int spi_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to map ADC value to rainfall intensity
int map_adc_to_intensity(int adc_value) {
    if (adc_value < MIN_ADC_VALUE) {
        return MIN_INTENSITY;
    }
    if (adc_value > MAX_ADC_VALUE) {
        return MAX_INTENSITY;
    }

    // Linear mapping
    return (int)(((float)(adc_value - MIN_ADC_VALUE) / (MAX_ADC_VALUE - MIN_ADC_VALUE)) * (MAX_INTENSITY - MIN_INTENSITY) + MIN_INTENSITY);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value from rain sensor
        int adc_value = read_mcp3008(RAIN_SENSOR_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, skipping this reading\n");
            gpioDelay(1000); // Wait 1 second before next attempt
            continue;
        }

        // Map ADC value to rainfall intensity
        int intensity = map_adc_to_intensity(adc_value);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Print timestamp, raw ADC value, and rainfall intensity
        printf("%s, ADC: %d, Intensity: %d%%\n", timestamp, adc_value, intensity);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

