// Function to map ADC value to rainfall intensity
int map_adc_to_intensity(int adc_value) {
    if (adc_value < MIN_ADC_VALUE) {
        return MIN_INTENSITY;
    }
    if (adc_value > MAX_ADC_VALUE) {
        return MAX_INTENSITY;
    }

    // Linear mapping
    return (int)(((float)(adc_value - MIN_ADC_VALUE) / (MAX_ADC_VALUE - MIN_ADC_VALUE)) * (MAX_INTENSITY - MIN_INTENSITY) + MIN_INTENSITY);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value from rain sensor
        int adc_value = read_mcp3008(RAIN_SENSOR_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, skipping this reading\n");
            gpioDelay(1000); // Wait 1 second before next attempt
            continue;
        }

        // Map ADC value to rainfall intensity
        int intensity = map_adc_to_intensity(adc_value);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Print timestamp, raw ADC value, and rainfall intensity
        printf("%s, ADC: %d, Intensity: %d%%\n", timestamp, adc_value, intensity);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

