#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0
#define SENSITIVITY 0.001 // 1 mV/Gauss
#define SUPPLY_VOLTAGE 4.096

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;

// Function prototypes
int init_i2c();
int read_ads1115(int *raw_value);
double convert_to_gauss(int raw_value);
void blink_led();
void signal_handler(int signal);

// Structure for configuration
typedef struct {
    int pga;
    double sensitivity;
} sensor_config_t;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw ADC value from ADS1115
int read_ads1115(int *raw_value) {
    char config[3];
    char buffer[2];

    // Configure for single-ended AIN0, PGA = 4.096V, continuous conversion, start single conversion
    config[0] = CONFIG_REG;
    config[1] = 0x83; // 0b10000011
    config[2] = 0x83; // 0b10000011

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for PGA = 4.096V)
    gpioDelay(10000); // 10 ms

    // Read conversion register
    config[0] = CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Convert raw ADC value to Gauss
double convert_to_gauss(int raw_value) {
    return (double)raw_value * SENSITIVITY;
}

// Blink LED for 1 second
void blink_led() {
    gpioWrite(LED_GPIO, 1); // Turn LED on
    gpioDelay(500000);      // 500 ms
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioDelay(500000);      // 500 ms
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    int opt;
    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int raw_value;
    double gauss_value;

    // Main loop
    while (1) {
        if (read_ads1115(&raw_value) == 0) {
            gauss_value = convert_to_gauss(raw_value);
            printf("Magnetic field: %.2f Gauss\n", gauss_value);

            if (gauss_value > threshold) {
                blink_led();
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(100000); // 100 ms
    }

    return 0;
}

