#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_BROKER "localhost" // Change to your broker address
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "soil_monitor"
#define MQTT_TOPIC "soil_moisture"
#define MQTT_CONTROL_TOPIC "pump_control"
#define MQTT_STATUS_TOPIC "pump_status"
#define SENSOR_TIMEOUT 5 // Seconds

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_pump(int state);
void publish_moisture(float moisture);
void on_connect(struct mosquitto *mosq, void *userdata, int result);
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int sig);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00;

    spiXfer(spi_handle, tx_buf, rx_buf, 3);

    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    syslog(LOG_INFO, "Pump set to %s", state ? "ON" : "OFF");
}

// Function to publish moisture data to MQTT
void publish_moisture(float moisture) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%.2f", moisture);
    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish moisture: %s", mosquitto_strerror(ret));
    }
}

// MQTT connect callback
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_CONTROL_TOPIC, 0);
    } else {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_strerror(result));
    }
}

// MQTT message callback
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        if (strcmp(message->payload, "pump_on") == 0) {
            control_pump(1);
        } else if (strcmp(message->payload, "pump_off") == 0) {
            control_pump(0);
        } else {
            syslog(LOG_WARNING, "Unknown command: %s", message->payload);
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

int main() {
    // Initialize syslog
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    control_pump(0); // Ensure pump is off initially

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI initialisation failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "MQTT initialisation failed");
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);

    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connection failed: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int pump_state = 0; // 0 = off, 1 = on
    time_t last_read_time = time(NULL);
    int sensor_present = 1; // Assume sensor is present initially

    // Main loop
    while (!terminate) {
        // Read sensor data
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            // Consider setting pump_state to 0 to prevent unexpected behavior
            // control_pump(0); // Turn off pump on error
            sensor_present = 0; // Mark sensor as absent
        } else {
            float moisture = calculate_moisture(adc_value);
            syslog(LOG_INFO, "Moisture: %.2f%%", moisture);

            // Publish moisture data
            publish_moisture(moisture);

            // Hysteresis control
            if (moisture < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
                control_pump(1);
                pump_state = 1;
            } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
                control_pump(0);
                pump_state = 0;
            }

            sensor_present = 1; // Reset sensor absent flag
            last_read_time = time(NULL);
        }

        // Check for sensor timeout
        if (sensor_present && (time(NULL) - last_read_time) > SENSOR_TIMEOUT) {
            syslog(LOG_ERR, "Sensor timeout, turning pump off");
            control_pump(0);
            pump_state = 0;
            sensor_present = 0; // Mark sensor as absent
        }

        sleep(60); // Publish data every 60 seconds
    }

    // Cleanup
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    spiClose(spi_handle);
    control_pump(0); // Turn off pump
    gpioTerminate();
    closelog();

    return 0;
}

