#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define NOISE_THRESHOLD 500
#define PWM_FREQUENCY 100 // Hz
#define PWM_RANGE 1024 // Adjust for desired resolution
#define VIBRATION_LOG_FILE "vibration_log.txt"

// Global variables
static volatile int keepRunning = 1;
static int spiFd = -1;
static FILE *logFile = NULL;

// Function prototypes
int initSPI();
int readMCP3008(int channel);
void controlMotors(int motor1Value, int motor2Value);
void logVibrationEvent(int noiseLevel);
void signalHandler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    keepRunning = 0;
}

// Initialize SPI communication
int initSPI() {
    if ((spiFd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED)) < 0) {
        fprintf(stderr, "Error initializing SPI: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int readMCP3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t spiData[3];
    spiData[0] = 0x01; // Start bit
    spiData[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spiData[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, spiData, 3) == -1) {
        fprintf(stderr, "SPI read/write error: %s\n", strerror(errno));
