    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C channel
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open CSV file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float sound_level = -1.0;
        float light_level = -1.0;
        int error_code = 0;

        // Read sound level from MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read sound level\n");
            error_code |= 0x01; // Set error bit for sound level
        } else {
            // Convert ADC value to dB (example conversion, adjust as needed)
            sound_level = (float)adc_value * 0.1; // Example scaling
        }

        // Read light level from BH1750
        light_level = read_bh1750();
        if (light_level < 0) {
            fprintf(stderr, "Error: Failed to read light level\n");
            error_code |= 0x02; // Set error bit for light level
        }

        // Log data
        log_data(sound_level, light_level, error_code);

        // Tamper detection
        if (sound_level > SOUND_THRESHOLD || light_level > LIGHT_THRESHOLD) {
            printf("Tamper detected! Sound: %.2f dB, Light: %.2f Lux\n", sound_level, light_level);
        }

        gpioDelay(LOG_INTERVAL * 1000); // Wait for LOG_INTERVAL seconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

