            adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed. Retry %d/%d\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(1000); // Wait 1ms before retrying
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries. Returning -1.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the water pump
void control_pump(float moisture) {
    if (moisture < MOISTURE_THRESHOLD && !pump_state) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump on
        pump_state = true;
        printf("Pump ON (Moisture: %.2f%%)\n", moisture);
    } else if (moisture >= MOISTURE_THRESHOLD && pump_state) {
        gpioWrite(PUMP_GPIO, 0); // Turn pump off
        pump_state = false;
        printf("Pump OFF (Moisture: %.2f%%)\n", moisture);
    }
}

// Function to log data with timestamp
void log_data(float moisture) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Moisture: %.2f%%\n", timestamp, moisture);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d. Shutting down...\n", signal);
    gpioWrite(PUMP_GPIO, 0); // Turn pump off
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int adc_value = read_mcp3008(0);
        if (adc_value != -1) {
            float moisture = calculate_moisture(adc_value);
            log_data(moisture);
            control_pump(moisture);
        } else {
            fprintf(stderr, "Failed to read ADC value. Skipping pump control.\n");
        }

        gpioDelay(60000); // Wait 60 seconds
    }

    return 0; // This line will never be reached due to the infinite loop
}

