#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // VH400 connected to channel 0
#define VALVE_GPIO 17       // BCM GPIO 17
#define PWM_FREQUENCY 100  // 100 Hz
#define PWM_RANGE 100       // 0-100
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL 5   // 5 seconds

// Global variables
static volatile int keepRunning = 1;
static FILE *logFile = NULL;

// Function prototypes
int read_mcp3008(int channel);
float calculate_average(int *samples, int num_samples);
int set_valve_position(int position);
void log_data(int adc1, int adc2, int adc3, float avg, int valve_position);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
  unsigned char buffer[3];
  int adc_value = -1; // Initialize to an error value

  buffer[0] = 0x01; // Start bit
  buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
  buffer[2] = 0x00; // Don't care

  if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
    fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
    return -1; // Indicate error
  }

  adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

  return adc_value;
}

// Function to calculate the average of ADC values
float calculate_average(int *samples, int num_samples) {
  float sum = 0.0;
  int valid_count = 0;

  for (int i = 0; i < num_samples; i++) {
    if (samples[i] != -1) { // Skip invalid readings
      sum += samples[i];
      valid_count++;
    }
  }

  if (valid_count > 0) {
    return sum / valid_count;
  } else {
    return -1.0; // Indicate no valid readings
  }
}

// Function to set the valve position using PWM
int set_valve_position(int position) {
  if (position < 0 || position > 100) {
    fprintf(stderr, "Invalid valve position: %d\n", position);
    return -1;
  }

  pwmWrite(VALVE_GPIO, position);
  return 0;
}

// Function to log data to file
void log_data(int adc1, int adc2, int adc3, float avg, int valve_position) {
  time_t rawtime;
  struct tm *timeinfo;
  char timestamp[80];

  time(&rawtime);
  timeinfo = localtime(&rawtime);

  strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

  fprintf(logFile, "%s, ADC1: %d, ADC2: %d, ADC3: %d, Average: %.2f, Valve Position: %d\n",
          timestamp, adc1, adc2, adc3, avg, valve_position);
  fflush(logFile); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
  printf("Caught signal %d, exiting gracefully...\n", signal);
  keepRunning = 0;
  set_valve_position(0); // Set valve to 0
  if (logFile != NULL) {
    fclose(logFile);
  }
  exit(0);
}

int main() {
