#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 200.0    // cm
#define MIN_FREQUENCY 200.0   // Hz
#define MAX_FREQUENCY 2000.0  // Hz
#define MIN_VOLUME 0.0        // 0%
#define MAX_VOLUME 100.0      // 100%
#define DEFAULT_DISTANCE 50.0  // cm
#define DEFAULT_VOLUME 50.0    // 50%

// Define error values
#define ERROR_DISTANCE -1.0
#define ERROR_VOLUME -1.0

// Define calibration parameters
typedef struct {
    float distance;
    float volume;
} CalibrationParams;

// Global variables
static int spi_handle;
static CalibrationParams calibration_params = {DEFAULT_DISTANCE, DEFAULT_VOLUME};
static volatile int running = 1;

// Function prototypes
float read_distance();
float read_ldr();
float map_distance_to_frequency(float distance);
float map_ldr_to_volume(float ldr_value);
void set_pwm_frequency(float frequency);
void set_pwm_dutycycle(float volume);
void signal_handler(int signal);
int load_calibration_params(CalibrationParams *params);
int save_calibration_params(const CalibrationParams *params);
void cleanup();

// Function to read distance from HC-SR04 sensor
float read_distance() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIG_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high (with timeout)
    int timeout = 1000; // Timeout after 1000 attempts (adjust as needed)
    while (gpioRead(ECHO_PIN) == 0 && timeout > 0) {
        timeout--;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (timeout == 0) {
        fprintf(stderr, "Error: Echo signal not received (timeout).\n");
        return ERROR_DISTANCE;
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    timeout = 1000;
    while (gpioRead(ECHO_PIN) == 1 && timeout > 0) {
        timeout--;
        gpioDelay(1);
    }

    if (timeout == 0) {
        fprintf(stderr, "Error: Echo signal not received (timeout).\n");
        return ERROR_DISTANCE;
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float time_taken = (float)diff / 1000000.0; // Time in seconds
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance in cm

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Error: Distance out of range (%f cm).\n", distance);
        return ERROR_DISTANCE;
    }

    return distance;
}

// Function to read LDR value from MCP3008 ADC
float read_ldr() {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // MCP3008 configuration: single-ended, channel 0
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = 0x80; // Single-ended, channel 0 (0b10000000)
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed.\n");
        return ERROR_VOLUME;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    // Convert ADC value to voltage (assuming 3.3V reference)
    float voltage = (float)adc_value / 1023.0 * 3.3;

    return voltage;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    if (distance == ERROR_DISTANCE) {
        return calibration_params.distance; // Use last valid distance
    }

    float frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);

    // Ensure frequency is within valid range
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    }
    if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    return frequency;
}

// Function to map LDR value to volume
float map_ldr_to_volume(float ldr_value) {
    if (ldr_value == ERROR_VOLUME) {
        return calibration_params.volume; // Use last valid volume
    }

    float volume = MAX_VOLUME - (ldr_value / 3.3) * MAX_VOLUME; // Invert and scale

    // Ensure volume is within valid range
    if (volume < MIN_VOLUME) {
        volume = MIN_VOLUME;
    }
    if (volume > MAX_VOLUME) {
        volume = MAX_VOLUME;
    }

    return volume;
}

// Function to set PWM frequency
void set_pwm_frequency(float frequency) {
    if (frequency == ERROR_DISTANCE) {
        return; // Do not change frequency if distance is invalid
    }

    // Calculate PWM period (in microseconds) for the desired frequency
    int period_us = 1000000 / frequency; // Period in microseconds

    // Set PWM period and duty cycle (adjust as needed)
    gpioSetPWMfrequency(PWM_PIN, frequency); // Set frequency directly
    gpioSetPWMrange(PWM_PIN, 1000); // Set range to 1000 for 0-100% duty cycle
    gpioPWM(PWM_PIN, 500); // Set initial duty cycle to 50% (optional)
}

// Function to set PWM duty cycle
void set_pwm_dutycycle(float volume) {
    if (volume == ERROR_VOLUME) {
        return; // Do not change duty cycle if volume is invalid
    }

    // Calculate duty cycle (0-1000)
    int duty_cycle = (int)(volume / MAX_VOLUME * 1000.0);

    // Set PWM duty cycle
    gpioPWM(PWM_PIN, duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    running = 0;
}

// Function to load calibration parameters from file
int load_calibration_params(CalibrationParams *params) {
    FILE *fp = fopen("theremin_config.txt", "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open calibration file, using default values.\n");
        return -1; // Indicate failure, but continue with default values
    }

    if (fscanf(fp, "%f %f", &params->distance, &params->volume) != 2) {
        fprintf(stderr, "Warning: Could not read calibration parameters from file, using default values.\n");
        fclose(fp);
        return -1; // Indicate failure, but continue with default values
    }

    fclose(fp);
    printf("Calibration parameters loaded: distance=%f, volume=%f\n", params->distance, params->volume);
    return 0;
}

// Function to save calibration parameters to file
int save_calibration_params(const CalibrationParams *params) {
    FILE *fp = fopen("theremin_config.txt", "w");
