#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define MOTOR1_ENABLE 18
#define MOTOR2_ENABLE 24
#define MOTOR1_DIRECTION 23
#define MOTOR2_DIRECTION 25
#define SPI_CE 8
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define PWM parameters
#define PWM_FREQUENCY 1000 // 1 kHz

// Define constants
#define ACCELERATION_TIME 1.0 // seconds
#define CONSTANT_SPEED_TIME 2.0 // seconds
#define DECELERATION_TIME 1.0 // seconds
#define PAUSE_TIME 5.0 // seconds
#define REVERSE_DELAY 0.5 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int map_potentiometer_to_speed(int potentiometer_value);
void set_motor_speed(int motor_number, int speed);
void set_motor_direction(int motor_number, int direction);
void accelerate(int motor_number, int target_speed);
void constant_speed(int motor_number, int target_speed);
void decelerate(int motor_number, int target_speed);
void reverse_directions();
void cleanup();
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to map potentiometer value to motor speed
int map_potentiometer_to_speed(int potentiometer_value) {
    // Map potentiometer value (0-1023) to motor speed (0-255)
    return (int)(((float)potentiometer_value / 1023.0) * 255.0);
}

// Function to set motor speed using PWM
void set_motor_speed(int motor_number, int speed) {
    if (motor_number != 1 && motor_number != 2) {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor_number);
        return;
    }

    int gpio_pin = (motor_number == 1) ? MOTOR1_ENABLE : MOTOR2_ENABLE;
    gpioPWM(gpio_pin, speed);
}

// Function to set motor direction
void set_motor_direction(int motor_number, int direction) {
    if (motor_number != 1 && motor_number != 2) {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor_number);
        return;
    }

    int gpio_pin = (motor_number == 1) ? MOTOR1_DIRECTION : MOTOR2_DIRECTION;

    if (direction == 0) {
        gpioWrite(gpio_pin, 0); // Forward
    } else {
        gpioWrite(gpio_pin, 1); // Backward
    }
}

// Function to accelerate motor
void accelerate(int motor_number, int target_speed) {
    int current_speed = 0;
    int increment = 5; // Increment speed by 5 each time

    while (current_speed <= target_speed) {
        set_motor_speed(motor_number, current_speed);
        current_speed += increment;
        gpioDelay(ACCELERATION_TIME * 1000000 / 255); // Delay for acceleration time
    }
}

// Function to maintain constant speed
void constant_speed(int motor_number, int target_speed) {
    set_motor_speed(motor_number, target_speed);
    gpioDelay(CONSTANT_SPEED_TIME * 1000000); // Delay for constant speed time
}

// Function to decelerate motor
void decelerate(int motor_number, int target_speed) {
    int current_speed = target_speed;
    int decrement = 5; // Decrement speed by 5 each time

    while (current_speed >= 0) {
        set_motor_speed(motor_number, current_speed);
        current_speed -= decrement;
        gpioDelay(DECELERATION_TIME * 1000000 / 255); // Delay for deceleration time
    }
}

// Function to reverse motor directions
void reverse_directions() {
    int motor1_direction = gpioRead(MOTOR1_DIRECTION);
    int motor2_direction = gpioRead(MOTOR2_DIRECTION);

    // Toggle motor directions
    gpioWrite(MOTOR1_DIRECTION, !motor1_direction);
    gpioWrite(MOTOR2_DIRECTION, !motor2_direction);

    gpioDelay(REVERSE_DELAY * 1000000); // Delay for reverse direction
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Stop motors
    gpioPWM(MOTOR1_ENABLE, 0);
    gpioPWM(MOTOR2_ENABLE, 0);

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received: %d. Terminating...\n", signal);
    terminate = 1;
    cleanup();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Configure GPIO pins
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENABLE, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENABLE, PWM_FREQUENCY);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        cleanup();
    }

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read potentiometer values
        int potentiometer1_value = read_mcp3008(0);
        int potentiometer2_value = read_mcp3008(1);

        if (potentiometer1_value == -1 || potentiometer2_value == -1) {
            fprintf(stderr, "Error: Failed to read potentiometer values. Skipping cycle.\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

