        int motor1_speed = map_potentiometer_to_speed(potentiometer1_value);
        int motor2_speed = map_potentiometer_to_speed(potentiometer2_value);

        // Set motor directions
        set_motor_direction(1, 0); // Motor 1 forward
        set_motor_direction(2, 1); // Motor 2 backward

        // Accelerate and maintain constant speed for Motor 1
        accelerate(1, motor1_speed);
        constant_speed(1, motor1_speed);

        // Accelerate and maintain constant speed for Motor 2
        accelerate(2, motor2_speed);
        constant_speed(2, motor2_speed);

        // Decelerate both motors
        decelerate(1, 0);
        decelerate(2, 0);

        // Pause for 5 seconds
        gpioDelay(PAUSE_TIME * 1000000);

        // Reverse motor directions
        reverse_directions();
    }

    cleanup();

    return 0;
}

