#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define debounce time
#define DEBOUNCE_TIME 10 // 10 ms

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_mcp3008(int channel);
int calibrate_noise_level();
int compare_to_threshold(int sample, int baseline);
void control_led(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Exiting gracefully...\n");
        terminate = 1;
    }
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", LED_PIN);
        return 1;
    }
    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", SPI_CHANNEL, spi_handle);
        return 1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calibrate noise level
int calibrate_noise_level() {
    int sum = 0;
    int num_samples = 0;
    int sample;

    printf("Calibrating noise level for 5 seconds...\n");
    sleep(5);

    for (int i = 0; i < 100; i++) {
        sample = read_mcp3008(0);
        if (sample >= 0) {
            sum += sample;
            num_samples++;
        }
        gpioDelay(50); // 50 ms delay
    }

    if (num_samples == 0) {
        fprintf(stderr, "Error: No valid samples read during calibration.\n");
        return -1;
    }

    return sum / num_samples;
}

// Compare sample to threshold
int compare_to_threshold(int sample, int baseline) {
    int threshold = baseline * 1.2; // 20% above baseline
    return (sample > threshold) ? 1 : 0;
}

// Control LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Calibrate noise level
    int baseline = calibrate_noise_level();
    if (baseline < 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Noise level calibrated. Baseline: %d\n", baseline);

    int led_state = 0; // 0 = off, 1 = on
    int last_led_state = -1; // Initialize to an invalid state
    int last_change_time = 0;

    // Main loop
    while (!terminate) {
        int sample = read_mcp3008(0);
        if (sample >= 0) {
            int above_threshold = compare_to_threshold(sample, baseline);

            if (above_threshold && (led_state == 0)) {
                // Debounce logic
                int current_time = gpioTick();
                if ((current_time - last_change_time) > DEBOUNCE_TIME * 1000) { // Convert ms to us
                    led_state = 1;
                    control_led(led_state);
                    last_change_time = current_time;
                }
            } else if (!above_threshold && (led_state == 1)) {
                // Debounce logic
                int current_time = gpioTick();
                if ((current_time - last_change_time) > DEBOUNCE_TIME * 1000) { // Convert ms to us
                    led_state = 0;
                    control_led(led_state);
                    last_change_time = current_time;
                }
            }

            if (led_state != last_led_state) {
                last_led_state = led_state;
            }
        } else {
            fprintf(stderr, "Error reading MCP3008. Retrying...\n");
        }

        gpioDelay(10); // 10 ms delay
    }

    // Cleanup
    control_led(0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

