#define GPIO_BASE 0xFE200000 // Physical base address of GPIO registers
#define GPIO_SIZE 4096       // Size of GPIO memory region

// Global variables
static int spi_fd = -1;
static int gpio_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;
static uint32_t *gpio_map = NULL; // Memory-mapped GPIO registers

// Function prototypes
int spi_init(const char *device);
int gpio_init(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_write(int pin, int value);
int read_adc(int channel);
void log_data(uint64_t timestamp_ns, int raw_adc_value);
void signal_handler(int sig);
void cleanup();
void *map_gpio_memory();
void unmap_gpio_memory();

// Structure to hold GPIO configuration
typedef struct {
    int pin;
    char direction[5]; // "in" or "out"
} gpio_config_t;

// Function to map GPIO memory
void *map_gpio_memory() {
    int mem_fd = open("/dev/mem", O_RDWR | O_SYNC);
    if (mem_fd < 0) {
        perror("Failed to open /dev/mem");
        return MAP_FAILED;
    }

    void *gpio_map = mmap(NULL, GPIO_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, mem_fd, GPIO_BASE);
    close(mem_fd);

    if (gpio_map == MAP_FAILED) {
        perror("mmap error");
        return MAP_FAILED;
    }

    return gpio_map;
}

// Function to unmap GPIO memory
void unmap_gpio_memory() {
    if (gpio_map != MAP_FAILED) {
        if (munmap(gpio_map, GPIO_SIZE) == -1) {
            perror("munmap error");
        }
        gpio_map = MAP_FAILED; // Reset to indicate unmapped
    }
}

// Function to initialize SPI
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI_MODE_0
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Failed to set bits per word");
        close(fd);
        return -1;
    }

    // Configure max speed Hz
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Failed to set max speed Hz");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to initialize GPIO
int gpio_init(int pin) {
    char buffer[64];
    int fd;

    // Export GPIO pin
    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("Failed to open /sys/class/gpio/export");
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("Failed to write to /sys/class/gpio/export");
        close(fd);
        return -1;
    }
    close(fd);

    // Wait for the GPIO directory to be created
    snprintf(buffer, sizeof(buffer), "/sys/class/gpio/gpio%d", pin);
    for (int i = 0; i < 10; ++i) {
        if (access(buffer, F_OK) == 0) {
            break;
        }
        usleep(10000); // Wait 10ms
    }

    return 0;
}

