    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO direction file");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) < 0) {
        perror("Failed to write to GPIO direction file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to write to GPIO pin
int gpio_write(int pin, int value) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO value file");
        return -1;
    }

    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d.  Must be 0 or 1.\n", value);
        close(fd);
        return -1;
    }

    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);

    if (write(fd, val_str, 1) < 0) {
        perror("Failed to write to GPIO value file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read ADC value
int read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01;                  // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buf[2] = 0x00;                  // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to log data to file
void log_data(uint64_t timestamp_ns, int raw_adc_value) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file not opened.\n");
        return;
    }

    fprintf(log_file, "%llu|%d\n", timestamp_ns, raw_adc_value);
    fflush(log_file);
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received: %d.  Terminating...\n", sig);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");

    // Release GPIO
    if (gpio_fd != -1) {
        close(gpio_fd);
        gpio_fd = -1;
    }

    // Close SPI
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    // Unmap GPIO memory
    unmap_gpio_memory();

    fprintf(stderr, "Cleanup complete.\n");
}

int main() {
    struct timespec sleep_time, remaining_time;
    uint64_t timestamp_ns;
    int adc_value;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    // Initialize GPIO
