        cleanup();
        return 1;
    }

    // Set GPIO direction to output
    if (gpio_set_direction(GPIO_PIN, "out") != 0) {
        fprintf(stderr, "Failed to set GPIO direction.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Map GPIO memory
    gpio_map = map_gpio_memory();
    if (gpio_map == MAP_FAILED) {
        fprintf(stderr, "Failed to map GPIO memory.\n");
        cleanup();
        return 1;
    }

    // Main loop
