    sleep_time.tv_nsec = SAMPLE_PERIOD_NS;

    while (!terminate) {
        // Toggle GPIO pin
        gpio_write(GPIO_PIN, 1);
        nanosleep(&sleep_time, &remaining_time);
        gpio_write(GPIO_PIN, 0);
        nanosleep(&sleep_time, &remaining_time);

        // Read ADC value
        adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value.\n");
