#define VOLTAGE_REF 3.3
#define LOG_FILE "gas_log.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_ppm(float voltage);
