void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Retry loop
    int retries = 3;
    while (retries > 0) {
        int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
        if (result == 3) {
            // Extract ADC value
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed, retrying... (%d retries left)\n", retries - 1);
            gpioDelay(100); // 100ms delay
            retries--;
        }
    }

    fprintf(stderr, "SPI transfer failed after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to convert ADC value to voltage
