#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SPI_CE 8
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define ADXL335 sensitivity (3.3V range)
#define ADXL335_SENSITIVITY 0.3 // 300mV/g

// Define Kalman filter parameters
#define PROCESS_NOISE 0.01
#define MEASUREMENT_NOISE 0.1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman filter state
float x_state = 0.0;
float x_error_covariance = 1.0;
float x_process_noise_covariance = PROCESS_NOISE;
float x_measurement_noise_covariance = MEASUREMENT_NOISE;

float y_state = 0.0;
float y_error_covariance = 1.0;
float y_process_noise_covariance = PROCESS_NOISE;
float y_measurement_noise_covariance = MEASUREMENT_NOISE;

float z_state = 0.0;
float z_error_covariance = 1.0;
float z_process_noise_covariance = PROCESS_NOISE;
float z_measurement_noise_covariance = MEASUREMENT_NOISE;

// Function prototypes
int initialize_spi();
int read_mcp3008_channel(int channel);
float convert_to_g(int adc_value);
void kalman_filter(float measurement, float *state, float *error_covariance, float process_noise_covariance, float measurement_noise_covariance);
void print_acceleration(float x_g, float y_g, float z_g);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read MCP3008 channel
int read_mcp3008_channel(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to g
float convert_to_g(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * 3.3; // 10-bit ADC, 3.3V reference
    float acceleration = voltage / ADXL335_SENSITIVITY;
    return acceleration;
}

// Kalman filter
void kalman_filter(float measurement, float *state, float *error_covariance, float process_noise_covariance, float measurement_noise_covariance) {
    // Prediction step
    float prediction = *state;
    float prediction_error_covariance = *error_covariance + process_noise_covariance;

    // Update step
    float kalman_gain = prediction_error_covariance / (prediction_error_covariance + measurement_noise_covariance);
    *state = prediction + kalman_gain * (measurement - prediction);
    *error_covariance = (1 - kalman_gain) * prediction_error_covariance;
}

// Print acceleration values
void print_acceleration(float x_g, float y_g, float z_g) {
    printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", x_g, y_g, z_g);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("ADXL335 Accelerometer Interface\n");

    // Main loop
    while (!terminate) {
        // Read ADC values
        int x_adc = read_mcp3008_channel(0);
        int y_adc = read_mcp3008_channel(1);
        int z_adc = read_mcp3008_channel(2);

        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "Error reading ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert to g
        float x_g = convert_to_g(x_adc);
        float y_g = convert_to_g(y_adc);
        float z_g = convert_to_g(z_adc);

        // Apply Kalman filter
        kalman_filter(x_g, &x_state, &x_error_covariance, x_process_noise_covariance, x_measurement_noise_covariance);
        kalman_filter(y_g, &y_state, &y_error_covariance, y_process_noise_covariance, y_measurement_noise_covariance);
        kalman_filter(z_g, &z_state, &z_error_covariance, z_process_noise_covariance, z_measurement_noise_covariance);

        // Print acceleration values
        print_acceleration(x_state, y_state, z_state);

        // Delay for 10 Hz
        gpioDelay(100000); // 100 ms
    }

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated\n");
    return 0;
}

