#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

// Define magnetic field strength conversion constants
#define VOLTAGE_HIGH 3.3f
#define VOLTAGE_LOW 0.0f
#define MT_PER_VOLT 0.1f

// Define the magnetic field strength range
#define MIN_MILLITESLA -100.0f
#define MAX_MILLITESLA 100.0f

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

// Function to read the sensor value from a GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to convert the sensor value to a magnetic field strength value
float convert_to_mT(int sensor_value) {
    float voltage = (sensor_value == 1) ? VOLTAGE_HIGH : VOLTAGE_LOW;
    float mT = voltage * MT_PER_VOLT;
    return mT;
}

// Function to log the magnetic field strengths to a file
int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen("magnetic_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening magnetic_log.txt for writing\n");
        return -1; // Indicate an error
    }

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    fflush(fp); // Flush the buffer to ensure data is written to the file
    fclose(fp);
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read the sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);
        int sensor3_value = read_sensor(SENSOR3_PIN);

        // Check for errors during sensor reading
        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
            fprintf(stderr, "Error reading sensor values, skipping iteration\n");
            gpioDelay(100); // Wait 100ms before the next iteration
            continue;
        }

        // Convert the sensor values to magnetic field strengths
        float sensor1_mT = convert_to_mT(sensor1_value);
        float sensor2_mT = convert_to_mT(sensor2_value);
        float sensor3_mT = convert_to_mT(sensor3_value);

        // Check if the magnetic field strengths are within the specified range
        if (sensor1_mT < MIN_MILLITESLA || sensor1_mT > MAX_MILLITESLA ||
            sensor2_mT < MIN_MILLITESLA || sensor2_mT > MAX_MILLITESLA ||
            sensor3_mT < MIN_MILLITESLA || sensor3_mT > MAX_MILLITESLA) {
            fprintf(stderr, "Warning: Magnetic field strength out of range\n");
        } else {
            // Log the data to the file
            if (log_data(sensor1_mT, sensor2_mT, sensor3_mT) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

