#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// SPI device and settings
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// MCP3008 channel numbers
#define CHANNEL_0 0
#define CHANNEL_1 1
#define CHANNEL_2 2

// Global variables
int spi_fd = -1;
FILE *fp = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
int log_data(int channel0_value, int channel1_value, int channel2_value);
void signal_handler(int signal);

// Structure to hold SPI configuration
struct spi_config {
    uint8_t mode;
    uint8_t bits_per_word;
    uint32_t speed;
};

// Function to initialize SPI
int spi_init(void) {
    int ret = 0;
    struct spi_config config;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    config.mode = SPI_MODE;
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &config.mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    config.bits_per_word = SPI_BITS_PER_WORD;
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &config.bits_per_word);
    if (ret == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    config.speed = SPI_SPEED;
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &config.speed);
    if (ret == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];
    int ret;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer);
    if (ret < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to log data to CSV file
int log_data(int channel0_value, int channel1_value, int channel2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, channel0_value, channel1_value, channel2_value);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(void) {
    int channel0_value, channel1_value, channel2_value;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open CSV file for writing
    fp = fopen("sensor_data.csv", "w");
    if (fp == NULL) {
        perror("Error opening sensor_data.csv");
        close(spi_fd);
        return 1;
    }

    // Write CSV header
    fprintf(fp, "Timestamp,Channel0,Channel1,Channel2\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        channel0_value = read_mcp3008(CHANNEL_0);
        channel1_value = read_mcp3008(CHANNEL_1);
        channel2_value = read_mcp3008(CHANNEL_2);

        if (channel0_value == -1 || channel1_value == -1 || channel2_value == -1) {
            fprintf(stderr, "Error reading sensor values. Retrying.\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Log data
        if (log_data(channel0_value, channel1_value, channel2_value) < 0) {
            fprintf(stderr, "Error logging data. \n");
        }

        sleep(1); // Read and log data every 1 second
    }

    // Close file and SPI device
    fclose(fp);
    close(spi_fd);

    return 0;
}

