#include <signal.h>
#include <unistd.h>
#include <mosquitto.h>
#include <jansson.h>
#include <pigpio.h>

#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define LED_GPIO 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;
static int reconnect_delay = 1; // Initial reconnection delay in seconds

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] %s\n", timestamp, message);
}

// Callback function for when the MQTT client connects to the broker
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        log_message("MQTT connected successfully");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "MQTT connection error: %s", mosquitto_connack_string(result));
        log_message(error_message);
    }
}

// Callback function for when the MQTT client disconnects from the broker
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "MQTT disconnected unexpectedly with code %d", rc);
        log_message(error_message);
    }
}

// Callback function for when the MQTT client receives a message
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen && message->payload) {
        json_error_t error;
        json_t *root = json_loads(message->payload, 0, &error);

        if (!root) {
            char error_message[200];
            snprintf(error_message, sizeof(error_message), "JSON parse error: %s at line %d, column %d", error.text, error.line, error.column);
            log_message(error_message);
            return;
        }

        json_t *led_state = json_object_get(root, "led_state");
        if (!led_state) {
            log_message("JSON parse error: 'led_state' key not found");
            json_decref(root);
            return;
        }

        if (!json_is_boolean(led_state)) {
            log_message("JSON parse error: 'led_state' is not a boolean");
            json_decref(root);
            return;
        }

        bool state = json_boolean_value(led_state);
        gpioWrite(LED_GPIO, state ? 1 : 0);
        char message_str[50];
        snprintf(message_str, sizeof(message_str), "LED set to %s", state ? "ON" : "OFF");
        log_message(message_str);

        json_decref(root);
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_message("Received signal, disconnecting and exiting...");
        running = 0;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Turn off LED at startup

    // Initialize libmosquitto
    mosquitto_lib_init();

    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message("Failed to create mosquitto instance");
        gpioTerminate();
        return 1;
    }

    // Set callback functions
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    // Connect to MQTT broker with exponential backoff
    while (running) {
        int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
        if (rc == MOSQ_ERR_SUCCESS) {
            mosquitto_loop_start(mosq);
            break; // Connection successful, exit the loop
        } else {
            char error_message[100];
            snprintf(error_message, sizeof(error_message), "MQTT connection failed: %s", mosquitto_strerror(rc));
            log_message(error_message);
            sleep(reconnect_delay);
            reconnect_delay = (reconnect_delay < 60) ? (reconnect_delay * 2) : 60; // Exponential backoff with max delay
        }
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        sleep(1);
    }

    // Clean up
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(LED_GPIO, 0); // Turn off LED before exiting
    gpioTerminate();

    log_message("Exiting cleanly");
    return 0;
}

