#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    int sound_level;
    int init_result;

    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Initialize the pigpio library
    init_result = gpioInitialise();
    if (init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", init_result);
        return 1;
    }

    // Set GPIO17 as an input
    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as an output
    if (gpioSetMode(ALARM_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALARM_LED_PIN);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read the sound sensor level
        sound_level = gpioRead(SOUND_SENSOR_PIN);

        // Print the sound level
        printf("Sound Level: %d\n", sound_level);

        // Check for sound event and trigger alarm
        if (sound_level == 0) {
            printf("Sound event detected! Activating alarm.\n");
            gpioWrite(ALARM_LED_PIN, 1); // Turn on the alarm LED
            gpioDelay(1000);             // Wait for 1 second
            gpioWrite(ALARM_LED_PIN, 0); // Turn off the alarm LED
        }

        // Delay for 100 milliseconds
        gpioDelay(100);
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

