#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <errno.h>

#define GPIO_CHIP 0
#define GPIO_LINE 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int gpio_fd, log_fd;
    struct gpio_event_request event_req;
    struct gpio_event_data event_data;
    struct timespec ts;
    char timestamp[30];
    char log_message[100];
    struct gpiochip_info chip_info;
    struct gpioline_info line_info;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    char gpio_path[50];
    snprintf(gpio_path, sizeof(gpio_path), "/dev/gpiochip%d", GPIO_CHIP);
    gpio_fd = open(gpio_path, O_RDWR);
    if (gpio_fd < 0) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO chip info
    if (ioctl(gpio_fd, GPIO_GET_CHIPINFO_IOCTL, &chip_info) < 0) {
        perror("Error getting GPIO chip info");
        close(gpio_fd);
        return 1;
    }

    // Get GPIO line info
    snprintf(gpio_path, sizeof(gpio_path), "/dev/gpiochip%d/gpio%d", GPIO_CHIP, GPIO_LINE);
    int line_fd = open(gpio_path, O_RDWR);
    if (line_fd < 0) {
        perror("Error opening GPIO line");
        close(gpio_fd);
        return 1;
    }

    if (ioctl(line_fd, GPIO_GET_LINEINFO_IOCTL, &line_info) < 0) {
        perror("Error getting GPIO line info");
        close(gpio_fd);
        close(line_fd);
        return 1;
    }

    // Request event
    event_req.line_offset = GPIO_LINE;
    event_req.handle = 0; // Let the kernel allocate a handle
    event_req.flags = 0; // Flags (not used in this example)
    event_req.event_type = GPIOEVENT_TYPE_RISING_EDGE | GPIOEVENT_TYPE_FALLING_EDGE;
    event_req.chip = GPIO_CHIP;

    if (ioctl(gpio_fd, GPIO_GETEVENTS_IOCTL, &event_req) < 0) {
        perror("Error requesting GPIO event");
        close(gpio_fd);
        close(line_fd);
        return 1;
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("Error opening log file");
        close(gpio_fd);
        close(line_fd);
        return 1;
    }

    // Main loop
    printf("Monitoring vibration on GPIO%d... Press Ctrl+C to exit.\n", GPIO_LINE);
    while (program_running) {
        ssize_t bytes_read = read(gpio_fd, &event_data, sizeof(event_data));
        if (bytes_read > 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
                snprintf(log_message, sizeof(log_message), "%s.%09ld: Vibration detected on GPIO%d\n", timestamp, ts.tv_nsec, GPIO_LINE);

                // Write to log file
                if (write(log_fd, log_message, strlen(log_message)) < 0) {
                    perror("Error writing to log file");
                }

                // Write to stdout
                printf("%s", log_message);

                // Shutdown
                system("sudo shutdown -h now");
            } else {
                perror("Error getting timestamp");
            }
        } else if (bytes_read < 0) {
            perror("Error reading GPIO event");
            break;
        }
    }

    // Cleanup
    close(gpio_fd);
    close(log_fd);
    close(line_fd);

    printf("Exiting.\n");
    return 0;
}

