#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define MCP3008_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LOG_FILE "environmental_log.txt"

// Global variables
int i2c_handle = -1;
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750();
int read_mcp3008(int channel);
void log_data(int light, int sound);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read light from BH1750 sensor
int read_bh1750() {
    int lux = -1; // Default to error value
    if (i2c_handle >= 0) {
        // Send start measurement command (High Resolution Mode)
        if (i2cWriteByteData(i2c_handle, 0x00, 0x10) != 0) {
            fprintf(stderr, "Error: Failed to write to BH1750\n");
            return -1;
        }
        gpioDelay(200); // Wait for measurement (at least 180ms)

        // Read two bytes of data
        char buf[2];
        if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) == 2) {
            lux = (buf[0] << 8) | buf[1];
        } else {
            fprintf(stderr, "Error: Failed to read from BH1750\n");
            return -1;
        }
    } else {
        fprintf(stderr, "Error: BH1750 I2C not initialized\n");
        return -1;
    }
    return lux;
}

// Function to read sound from MCP3008 ADC
int read_mcp3008(int channel) {
    if (spi_handle >= 0) {
        // Construct SPI message (MCP3008 datasheet)
        unsigned char tx_buf[3];
        unsigned char rx_buf[3];

        tx_buf[0] = 0x01; // Start bit
        tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
        tx_buf[2] = 0x00;

        if (spiXfer(spi_handle, tx_buf, rx_buf, 3) == 3) {
            // Extract ADC value (10 bits)
            int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "Error: SPI transfer failed\n");
            return -1;
        }
    } else {
        fprintf(stderr, "Error: SPI not initialized\n");
        return -1;
    }
}

// Function to log data to file
void log_data(int light, int sound) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Light: %d, Sound: %d\n", timestamp, light, sound);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file not opened\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        i2c_handle = -1; // Mark as invalid
    }

    // Open SPI connection
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI device: %d\n", spi_handle);
        spi_handle = -1; // Mark as invalid
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int light = read_bh1750();
        int sound = read_mcp3008(MCP3008_CHANNEL);

        if (light != -1 && sound != -1) {
            log_data(light, sound);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        sleep(1); // Sample every 1 second
    }

    // Cleanup
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

