static volatile int keepRunning = 1;

void intHandler(int dummy) {
    keepRunning = 0;
}

int main() {
    FILE *fp;
    int pinValue;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Register signal handlers for graceful shutdown
    signal(SIGINT, intHandler);
    signal(SIGTERM, intHandler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_DOWN);

    // Open log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (keepRunning) {
        // Read digital value from GPIO pin
        pinValue = gpioRead(FLAME_SENSOR_PIN);

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log data to CSV file
        fprintf(fp, "%s,%d,%d\n", timestamp, FLAME_SENSOR_PIN, pinValue);
        fflush(fp); // Ensure data is written to file immediately

        // Check for flame detection (active HIGH)
        if (pinValue == 1) {
            printf("ALARM: Flame detected!\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Close log file
    fclose(fp);

    // Terminate pigpio library
    gpioTerminate();

    printf("Flame sensor monitoring stopped.\n");

    return 0;
}

