#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500kHz
#define I2C_ADDRESS 0x60
#define DAC_VREF 3.3
#define TMP36_VREF 3.3
#define TMP36_OFFSET 0.5
#define TMP36_SCALE 0.01
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 500

// Global variables
static int spi_fd = -1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init();
int i2c_init();
int read_adc(int channel);
float convert_to_celsius(int adc_value);
int write_dac(float voltage);
int log_data(int adc_value, float temperature, float voltage);
void signal_handler(int signal);
void cleanup();

// SPI Initialization
int spi_init() {
    spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "Error initializing SPI: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C Initialization
int i2c_init() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

// Read ADC Value
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char buffer[3];
    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    buffer[2] = 0x00;

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    int adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Convert ADC Value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (float)adc_value * TMP36_VREF / 1024.0;
    float temperature = (voltage - TMP36_OFFSET) / TMP36_SCALE;
    return temperature;
}

// Write DAC Value
int write_dac(float voltage) {
    if (voltage < 0.0 || voltage > DAC_VREF) {
        fprintf(stderr, "Invalid DAC voltage: %.2f\n", voltage);
        return -1;
    }

    unsigned char data[3];
    data[0] = 0x40; // Write DAC register
    data[1] = (unsigned char)(voltage * 4095.0 / DAC_VREF);
    data[2] = (unsigned char)((voltage * 4095.0 / DAC_VREF) >> 8);

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (write(i2c_fd, data, 3) == 3) {
            return 0;
        } else {
            fprintf(stderr, "I2C write error: %s. Retrying (%d/%d)\n", strerror(errno), retries + 1, MAX_RETRIES);
            usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
            retries++;
        }
    }
    fprintf(stderr, "I2C write failed after %d retries.\n", MAX_RETRIES);
    return -1;
}

// Log Data to File
int log_data(int adc_value, float temperature, float voltage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, ADC: %d, Temperature: %.2f C, Voltage: %.2f V\n", timestamp, adc_value, temperature, voltage);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal Handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup Function
void cleanup() {
    if (spi_fd != -1) {
        // No specific SPI de-initialization function in wiringPi, but we can reset the SPI channel.
        // wiringPiSPIClose(SPI_CHANNEL); // This is not a valid function in wiringPi
        spi_fd = -1;
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing WiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (i2c_init() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    fprintf(stdout, "Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value.\n");
            continue; // Skip to the next iteration
        }

        // Convert to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Write to DAC
        if (write_dac(temperature) != 0) {
            fprintf(stderr, "Error writing to DAC.\n");
        }

        // Log data
        if (log_data(adc_value, temperature, temperature) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Echo to stdout
        printf("ADC: %d, Temperature: %.2f C, Voltage: %.2f V\n", adc_value, temperature, temperature);

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup and exit
    cleanup();
    fprintf(stdout, "Temperature monitoring stopped.\n");
    return 0;
}

