#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define relay GPIO pins (BCM numbering)
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Function prototypes
int initialize_gpio();
void activate_relay(int pin);
void deactivate_relay(int pin);
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
        program_running = 0; // Signal the main loop to exit
        cleanup_gpio();       // Deactivate all relays and release GPIO lines
        exit(0);              // Exit the program
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY2_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY3_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY3_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY4_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY4_PIN);
        gpioTerminate();
        return 1;
    }

    // Initially deactivate all relays (set pins LOW)
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    return 0; // Indicate success
}

// Function to activate a relay
void activate_relay(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Failed to activate relay on GPIO %d\n", pin);
    }
}

// Function to deactivate a relay
void deactivate_relay(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Failed to deactivate relay on GPIO %d\n", pin);
    }
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    // Deactivate all relays
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    // Terminate the pigpio library
    gpioTerminate();
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed, exiting\n");
        return 1;
    }

    printf("Light sequencer started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Activate relays sequentially
        activate_relay(RELAY1_PIN);
        sleep(1);
        deactivate_relay(RELAY1_PIN);

        activate_relay(RELAY2_PIN);
        sleep(1);
        deactivate_relay(RELAY2_PIN);

        activate_relay(RELAY3_PIN);
        sleep(1);
        deactivate_relay(RELAY3_PIN);

        activate_relay(RELAY4_PIN);
        sleep(1);
        deactivate_relay(RELAY4_PIN);
    }

    return 0;
}

