#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Define GPIO pins
#define MOTOR_IN1 17  // BCM GPIO 17
#define MOTOR_IN2 18  // BCM GPIO 18
#define MOTOR_ENA 27  // BCM GPIO 27

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define rain threshold
#define RAIN_THRESHOLD 5

// Define motor speed (PWM duty cycle)
#define MOTOR_FORWARD_SPEED 150
#define MOTOR_REVERSE_SPEED 150

// Define motor run time
#define MOTOR_RUN_TIME 3 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int read_mcp3008(int channel);
int log_rain_data(int rain_level);
void control_motor(int direction);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to log rain data to file
int log_rain_data(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Flush the buffer to ensure data is written to disk
    return 0;
}

// Function to control the DC motor
void control_motor(int direction) {
    if (direction == 1) { // Forward
        digitalWrite(MOTOR_IN1, HIGH);
        digitalWrite(MOTOR_IN2, LOW);
        pwmWrite(MOTOR_ENA, MOTOR_FORWARD_SPEED);
