        // Read ADC value
        int adc_value = read_adc();

        // Detect clap
        if (detect_clap(adc_value)) {
            // Debounce clap detection
            if (gpioTick() - last_clap_time > DEBOUNCE_TIME_MS * 1000) {
                // Log clap event
                log_clap();

                // Turn on LED
                control_led(1);
                state.led_state = 1;

                // Wait for LED to turn off
                gpioDelay(LED_ON_TIME_MS * 1000); // Convert ms to us

                // Turn off LED
                control_led(0);
                state.led_state = 0;

                // Update last clap time
                last_clap_time = gpioTick();
            }
        }

        // Small delay to avoid busy-waiting
        gpioDelay(1000); // 1ms delay
    }

    // Clean up and exit
    printf("Exiting gracefully...\n");
    gpioTerminate();
    return 0;
}

