#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30.0
#define ADC_MAX 1023.0
#define ADC_MIN 0.0
#define MOISTURE_MAX 100.0
#define MOISTURE_MIN 0.0
#define SAMPLE_INTERVAL 60 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_adc(int channel);
float convert_to_percentage(int adc_value);
void control_pump(float moisture_percentage);
void log_data(float moisture_percentage, int pump_status);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int pump_gpio;
    float moisture_threshold;
    int sample_interval;
} Config;

Config config = {SPI_CHANNEL, PUMP_GPIO, MOISTURE_THRESHOLD, SAMPLE_INTERVAL};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d seconds.\n", config.sample_interval);
            gpioDelay(config.sample_interval * 1000000); // Delay in microseconds
            continue;
        }

        float moisture_percentage = convert_to_percentage(adc_value);
        control_pump(moisture_percentage);
        log_data(moisture_percentage, gpioRead(config.pump_gpio));

        gpioDelay(config.sample_interval * 1000000); // Delay in microseconds
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(config.pump_gpio, PI_OUTPUT);
    gpioWrite(config.pump_gpio, 0); // Ensure pump is off initially

    // Open log file
    log_file = fopen("soil_moisture.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

