#define VREF 3.3 // Reference voltage (VDD = VREF)
#define SENSITIVITY 0.002 // Sensitivity (V/mt) - Example value, check datasheet
#define ZERO_FIELD_VOLTAGE 1.65 // Zero field voltage (V) - Example value, check datasheet

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold SPI configuration
typedef struct {
    int ce_pin;
    int mosi_pin;
    int miso_pin;
    int clk_pin;
    int channel;
    int speed;
    int mode;
} spi_config_t;

