    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting data acquisition...\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert to magnetic field strength
        float magnetic_field = convert_to_magnetic_field(adc_value);

        // Log data
        if (log_data(magnetic_field) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        // Print magnetic field strength
        printf("Magnetic Field: %.2f mt\n", magnetic_field);

        // Wait for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

