            fprintf(stderr, "Failed to read ADC value. Continuing.\n");
            sleep(1);
            continue;
        }

        // Convert ADC value to current
        float current = adc_to_current(adc_value);

        // Log data
        if (log_data(current) != 0) {
            fprintf(stderr, "Failed to log data. Continuing.\n");
        }

        // Disable sensor power
        if (gpio_set_value(GPIO_PIN, 0) != 0) {
            fprintf(stderr, "Failed to disable sensor power. Continuing.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_fd != -1) {
        close(gpio_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpio_unexport(GPIO_PIN);

    printf("Exiting.\n");
    return 0;
}

