#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define VREF 5.0        // Reference voltage (V)
#define MAX_VOLTAGE 5.0  // Maximum voltage to consider (V)
#define MIN_VOLTAGE 0.0  // Minimum voltage to consider (V)
#define LOG_FILE "current_log.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int spi_channel;
    int spi_speed;
    int adc_channel;
    double vref;
    double max_voltage;
    double min_voltage;
    char *log_file;
} Config;

// Function prototypes
int read_mcp3008(int channel);
double adc_to_voltage(int adc_value, double vref);
double voltage_to_current(double voltage);
int log_current(double current);
void signal_handler(int signal);
int initialize_spi(Config config);
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;           // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value from response
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to voltage
double adc_to_voltage(int adc_value, double vref) {
    return ((double)adc_value / 1023.0) * vref;
}

// Function to convert voltage to current (example linear relationship)
double voltage_to_current(double voltage) {
    // Assuming a linear relationship between voltage and current
    // You'll need to calibrate this based on your MLX91211 sensor
    // and the voltage characteristics of your load.
    // Example: 0V = 0A, 5V = 10A (10A = 5V)
    // Current = (Voltage - 0V) * (10A / 5V) = Voltage * (10A / 5V)
    return voltage * (10.0 / 5.0); // Example linear relationship
}

// Function to log current to file
int log_current(double current) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s %.2f A\n", timestamp, current);
    fflush(fp); // Ensure data is written to disk immediately
    fclose(fp);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to initialize SPI
int initialize_spi(Config config) {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI channel %d: %d\n", config.spi_channel, spi_handle);
        return -1;
    }
    return 0;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    // Configuration
    Config config = {
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED,
        .adc_channel = ADC_CHANNEL,
        .vref = VREF,
        .max_voltage = MAX_VOLTAGE,
        .min_voltage = MIN_VOLTAGE,
        .log_file = LOG_FILE
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi(config) != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Current sensor logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        double voltage = adc_to_voltage(adc_value, config.vref);

        // Check voltage range
        if (voltage < config.min_voltage || voltage > config.max_voltage) {
            fprintf(stderr, "Warning: Voltage out of range: %.2f V\n", voltage);
            continue; // Skip to the next iteration
        }

        // Convert voltage to current
        double current = voltage_to_current(voltage);

        // Log current
        if (log_current(current) != 0) {
            fprintf(stderr, "Error: Failed to log current\n");
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

