#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17

// Debounce count
#define DEBOUNCE_COUNT 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to read a sensor value with debouncing
int read_sensor(int gpio_pin) {
    int high_count = 0;
    for (int i = 0; i < DEBOUNCE_COUNT; i++) {
        if (gpioRead(gpio_pin) == 0) { // Active low
            high_count++;
        }
        gpioDelay(2); // 2ms delay
    }
    return (high_count >= (DEBOUNCE_COUNT / 2)) ? 0 : 1; // Return 0 if majority is low, 1 otherwise
}

// Function to log the sensor states
void log_sensor_states(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1_state, sensor2_state);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Monitoring sensors... Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        // Log sensor states
        log_sensor_states(sensor1_state, sensor2_state);

        // Check if both sensors detect an object
        if (sensor1_state == 0 && sensor2_state == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

