#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define POLL_INTERVAL_MS 50
#define CAPTURE_DIR "/home/pi/security_cam/"
#define LOG_FILE "/var/log/security_monitor.log"

static volatile int running = 1;
static int gpio_initialized = 0;

// Function to log messages to syslog
void log_message(int priority, const char *message) {
  syslog(priority, "%s", message);
}

// Function to initialize the pigpio library and configure the GPIO pin
int initialize_gpio() {
  if (gpioInitialise() < 0) {
    log_message(LOG_ERR, "pigpio initialisation failed");
    return -1;
  }
  gpio_initialized = 1;
  gpioSetMode(GPIO_PIN, PI_INPUT);
  gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
  log_message(LOG_INFO, "GPIO initialized successfully");
  return 0;
}

// Function to generate a timestamp in ISO 8601 format
int generate_timestamp(char *timestamp) {
  time_t rawtime;
  struct tm *timeinfo;

  time(&rawtime);
  timeinfo = gmtime(&rawtime);

  if (strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
    log_message(LOG_ERR, "Failed to format timestamp");
    return -1;
  }
  return 0;
}

// Function to construct the filename for the captured image
int construct_filename(char *filename) {
  char timestamp[21];
  if (generate_timestamp(timestamp) != 0) {
    return -1;
  }
  snprintf(filename, 256, "%s%s.jpg", CAPTURE_DIR, timestamp);
  return 0;
}

// Function to capture an image using libcamera-still
int capture_image(const char *filename) {
  char command[512];
  snprintf(command, sizeof(command), "libcamera-still -o %s", filename);

  pid_t pid = fork();
  if (pid == 0) {
    // Child process
    execl("/usr/bin/libcamera-still", "libcamera-still", "-o", filename, (char *)NULL);
    perror("execl failed"); // This will only be printed if execl fails
    exit(EXIT_FAILURE);
  } else if (pid < 0) {
    log_message(LOG_ERR, "Fork failed");
    return -1;
  } else {
    // Parent process
    int status;
    if (waitpid(pid, &status, 0) == -1) {
      log_message(LOG_ERR, "Waitpid failed");
      return -1;
    }

    if (WIFEXITED(status)) {
      int exit_status = WEXITSTATUS(status);
      if (exit_status == 0) {
        char log_message_buffer[256];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "Image captured successfully: %s", filename);
        log_message(LOG_INFO, log_message_buffer);
        return 0;
      } else {
        char log_message_buffer[256];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "libcamera-still exited with status %d", exit_status);
        log_message(LOG_ERR, log_message_buffer);
        return -1;
      }
    } else {
      log_message(LOG_ERR, "libcamera-still terminated abnormally");
      return -1;
    }
  }
}

// Function to handle the SIGINT and SIGTERM signals
void signal_handler(int signal) {
  log_message(LOG_INFO, "Signal received, shutting down...");
  running = 0;
}

// Function to create the capture directory if it doesn't exist
int create_capture_directory() {
  struct stat st = {0};

  if (stat(CAPTURE_DIR, &st) == -1) {
    if (mkdir(CAPTURE_DIR, 0777) == -1) {
      log_message(LOG_ERR, "Failed to create capture directory");
      return -1;
    }
    log_message(LOG_INFO, "Capture directory created");
  }
  return 0;
}

int main() {
  openlog("security_monitor", LOG_PID | LOG_CONS, LOG_USER);
  log_message(LOG_INFO, "Starting security monitor...");

  // Register signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Initialize GPIO
  if (initialize_gpio() != 0) {
    closelog();
    return 1;
  }

  // Create capture directory
  if (create_capture_directory() != 0) {
    gpioTerminate();
    closelog();
    return 1;
  }

  int last_state = 0; // Assume initial state is LOW
  int motion_detected = 0;
  int debounce_timer = 0;

  while (running) {
    int current_state = gpioRead(GPIO_PIN);

    if (current_state != last_state) {
      if (debounce_timer == 0) {
        motion_detected = 1;
        debounce_timer = DEBOUNCE_DELAY_MS;
      }
    }

    if (debounce_timer > 0) {
      debounce_timer -= POLL_INTERVAL_MS;
    }

    if (motion_detected && debounce_timer <= 0) {
      char filename[256];
      if (construct_filename(filename) == 0) {
        if (capture_image(filename) == 0) {
          motion_detected = 0; // Reset motion detection after successful capture
        } else {
          log_message(LOG_ERR, "Image capture failed");
        }
      } else {
        log_message(LOG_ERR, "Filename construction failed");
      }
    }

    last_state = current_state;
    gpioDelay(POLL_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
  }

  // Cleanup
  log_message(LOG_INFO, "Cleaning up...");
  if (gpio_initialized) {
    gpioTerminate();
    log_message(LOG_INFO, "GPIO terminated");
  }
  closelog();
  return 0;
}

