        }
    }

    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting capture");
        return -1;
    }

    return 0;
}

// Function to close memory mapping
void close_mmap(void) {
    unsigned int i;

    for (i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("Error unmapping buffer");
        }
    }
}

int main(void) {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open the video device
    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    // Initialize the device
    if (init_device(fd) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Initialize memory mapping
    if (init_mmap(fd) == -1) {
