    stop_capturing(fd);

    // Close memory mapping
    close_mmap();

    // Uninitialize the device
    uninit_device(fd);

    // Close the device
    close_device(fd);

    // Close the log file
    fclose(log_file);

    fprintf(stderr, "Capturing stopped.\n");

    return EXIT_SUCCESS;
}

