#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <unistd.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_FILE "image.jpg"
#define WIDTH 192
#define HEIGHT 108
#define NUM_BUFFERS 4

// Structure to hold buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer;

// Global variables
static int                  fd = -1;
static buffer               *buffers = NULL;
static unsigned int          n_buffers = 0;
static volatile int         keep_running = 1;

// Signal handler for graceful shutdown
static void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
    keep_running = 0;
}

// Function to open the video device
int open_device(const char *device_name)
{
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Function to query device capabilities
int query_capabilities(int fd)
{
    struct v4l2_capability cap;

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    return 0;
}

// Function to set the pixel format
int set_pixel_format(int fd, unsigned int width, unsigned int height)
{
    struct v4l2_format fmt;

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting pixel format");
        return -1;
    }

    return 0;
}

// Function to request buffers
int request_buffers(int fd, unsigned int num_buffers)
{
    struct v4l2_requestbuffers req;

    memset(&req, 0, sizeof(req));
    req.count = num_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }

    if (req.count < num_buffers) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    return 0;
}

// Function to map buffers
int map_buffers(int fd, unsigned int num_buffers, buffer *buffers)
{
    struct v4l2_buffer buf;

    for (unsigned int i = 0; i < num_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
    }

    return 0;
}

// Function to enqueue buffers
int enqueue_buffers(int fd, unsigned int num_buffers)
{
    struct v4l2_buffer buf;

    for (unsigned int i = 0; i < num_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("Error enqueueing buffer");
            return -1;
        }
    }

    return 0;
}

// Function to start streaming
int start_streaming(int fd)
{
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting streaming");
        return -1;
    }

    return 0;
}

// Function to dequeue a single frame
int dequeue_frame(int fd, buffer *buffers, unsigned int num_buffers)
{
    struct v4l2_buffer buf;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Error dequeuing buffer");
        return -1;
    }

    if (buf.bytesused > 0) {
        // Write the MJPEG data to a file
        FILE *fp = fopen(IMAGE_FILE, "wb");
        if (fp == NULL) {
            perror("Error opening image file");
            return -1;
        }
        fwrite(buffers[buf.index].start, 1, buf.bytesused, fp);
        fclose(fp);
        printf("Wrote %d bytes to %s\n", buf.bytesused, IMAGE_FILE);
    } else {
        fprintf(stderr, "No data received from camera\n");
        return -1;
    }

    return 0;
}

// Function to stop streaming
int stop_streaming(int fd)
{
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping streaming");
        return -1;
    }

    return 0;
}

// Function to unmap buffers
int unmap_buffers(int fd, unsigned int num_buffers, buffer *buffers)
{
    for (unsigned int i = 0; i < num_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("Error unmapping buffer");
            return -1;
        }
    }

    return 0;
}

// Function to free buffer array
void free_buffer_array(buffer *buffers)
{
    free(buffers);
}

// Function to close the device
int close_device(int fd)
{
    if (close(fd) == -1) {
        perror("Error closing device");
        return -1;
    }
    return 0;
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    // Query capabilities
    if (query_capabilities(fd) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Set pixel format
    if (set_pixel_format(fd, WIDTH, HEIGHT) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    buffers = (buffer *)calloc(NUM_BUFFERS, sizeof(buffer));
    if (!buffers) {
        perror("Out of memory");
        close_device(fd);
        return EXIT_FAILURE;
    }

    if (request_buffers(fd, NUM_BUFFERS) == -1) {
        free_buffer_array(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Map buffers
    if (map_buffers(fd, NUM_BUFFERS, buffers) == -1) {
        free_buffer_array(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Enqueue buffers
    if (enqueue_buffers(fd, NUM_BUFFERS) == -1) {
        unmap_buffers(fd, NUM_BUFFERS, buffers);
        free_buffer_array(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(fd) == -1) {
        unmap_buffers(fd, NUM_BUFFERS, buffers);
        free_buffer_array(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Dequeue a single frame
    if (dequeue_frame(fd, buffers, NUM_BUFFERS) == -1) {
        stop_streaming(fd);
        unmap_buffers(fd, NUM_BUFFERS, buffers);
        free_buffer_array(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Stop streaming
    if (stop_streaming(fd) == -1) {
        unmap_buffers(fd, NUM_BUFFERS, buffers);
        free_buffer_array(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Unmap buffers
    if (unmap_buffers(fd, NUM_BUFFERS, buffers) == -1) {
        free_buffer_array(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Free buffer array
    free_buffer_array(buffers);

    // Close the device
    if (close_device(fd) == -1) {
        return EXIT_FAILURE;
    }

    printf("Program finished successfully.\n");
    return EXIT_SUCCESS;
}

