#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_BUTTON_PIN 6
#define TILT_DOWN_BUTTON_PIN 7
#define PAN_LEFT_BUTTON_PIN 8
#define PAN_RIGHT_BUTTON_PIN 9

// Define PWM frequency and range
#define PWM_FREQUENCY 50
#define PWM_RANGE 1000

// Define servo limits
#define SERVO_MIN 25
#define SERVO_MAX 125

// Define button press duration
#define BUTTON_PRESS_DURATION_MS 200

// Global variables
volatile sig_atomic_t program_running = 1;
int pan_position = 75;
int tilt_position = 75;

// Function prototypes
int initialize_gpio();
void set_servo_position(int pin, int position);
int get_button_state(int pin);
void handle_button_press(int button_pin, int *position);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
        cleanup_gpio();
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(TILT_DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(PAN_LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(PAN_RIGHT_BUTTON_PIN, PI_INPUT);

    // Set pull-up resistors
    gpioSetPullUpDown(TILT_UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency and range
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE);

    // Set initial servo positions
    set_servo_position(PAN_SERVO_PIN, pan_position);
    set_servo_position(TILT_SERVO_PIN, tilt_position);

    return 0;
}

// Set servo position
void set_servo_position(int pin, int position) {
    if (position < SERVO_MIN) {
        position = SERVO_MIN;
    } else if (position > SERVO_MAX) {
        position = SERVO_MAX;
    }

    int pulse_width = (int)(((float)position / 100.0) * PWM_RANGE);
    gpioPWM(pin, pulse_width);
}

// Get button state
int get_button_state(int pin) {
    return gpioRead(pin);
}

// Handle button press
void handle_button_press(int button_pin, int *position) {
    int current_position = *position;
    int increment = 5;

    if (button_pin == TILT_UP_BUTTON_PIN) {
        current_position += increment;
    } else if (button_pin == TILT_DOWN_BUTTON_PIN) {
        current_position -= increment;
    } else if (button_pin == PAN_LEFT_BUTTON_PIN) {
        current_position -= increment;
    } else if (button_pin == PAN_RIGHT_BUTTON_PIN) {
        current_position += increment;
    }

    // Clamp position to limits
    if (current_position < SERVO_MIN) {
        current_position = SERVO_MIN;
    } else if (current_position > SERVO_MAX) {
        current_position = SERVO_MAX;
    }

    *position = current_position;
    set_servo_position((button_pin == TILT_UP_BUTTON_PIN || button_pin == TILT_DOWN_BUTTON_PIN) ? TILT_SERVO_PIN : PAN_SERVO_PIN, current_position);
}

// Cleanup GPIO pins
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Pan-Tilt control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check button states
        if (get_button_state(TILT_UP_BUTTON_PIN) == 0) {
            handle_button_press(TILT_UP_BUTTON_PIN, &tilt_position);
            gpioDelay(BUTTON_PRESS_DURATION_MS * 1000); // Debounce
        }
        if (get_button_state(TILT_DOWN_BUTTON_PIN) == 0) {
            handle_button_press(TILT_DOWN_BUTTON_PIN, &tilt_position);
            gpioDelay(BUTTON_PRESS_DURATION_MS * 1000); // Debounce
        }
        if (get_button_state(PAN_LEFT_BUTTON_PIN) == 0) {
            handle_button_press(PAN_LEFT_BUTTON_PIN, &pan_position);
            gpioDelay(BUTTON_PRESS_DURATION_MS * 1000); // Debounce
        }
        if (get_button_state(PAN_RIGHT_BUTTON_PIN) == 0) {
            handle_button_press(PAN_RIGHT_BUTTON_PIN, &pan_position);
            gpioDelay(BUTTON_PRESS_DURATION_MS * 1000); // Debounce
        }

        gpioDelay(50 * 1000); // Poll every 50ms
    }

    return 0;
}

