            unsigned char y1 = yuyv[i * width * 2 + j * 2];
            unsigned char u = yuyv[i * width * 2 + j * 2 + 1];
            unsigned char y2 = yuyv[i * width * 2 + j * 2 + 2];
            unsigned char v = yuyv[i * width * 2 + j * 2 + 3];

            int r1 = y1 + 1.13983 * (v - 128);
            int g1 = y1 - 0.39465 * (u - 128) - 0.58060 * (v - 128);
            int b1 = y1 + 2.03211 * (u - 128);

