    if (blurred == NULL) {
        perror("Error allocating memory for blurred image");
        return;
    }

    // Copy original image to blurred image
    memcpy(blurred, rgb, width * height * 3 * sizeof(unsigned char));

    // Apply blur filter (simple averaging)
    for (i = 1; i < height - 1; i++) {
        for (j = 1; j < width - 1; j++) {
            int r = 0, g = 0, b = 0;
            for (k = -1; k <= 1; k++) {
                for (l = -1; l <= 1; l++) {
                    r += blurred[(i + k) * width * 3 + (j + l) * 3 + 0];
                    g += blurred[(i + k) * width * 3 + (j + l) * 3 + 1];
