#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_fmtdesc fmtdesc;
    struct v4l2_frmsizeenum frmsizeenum;
    struct v4l2_frmivalenum frmivalenum;
    struct v4l2_queryctrl queryctrl;

    // Check if the device node exists
    if (access(VIDEO_DEVICE, F_OK) == -1) {
        fprintf(stderr, "Error: Device node %s does not exist.\n", VIDEO_DEVICE);
        return 1;
    }

    // Open the device node
    fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Error opening device node");
        return 1;
    }

    // Query device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        close(fd);
        return 1;
    }

    printf("Driver: %s\n", cap.driver);
    printf("Card: %s\n", cap.card);
    printf("Bus info: %s\n", cap.bus_info);
    printf("Version: %d\n", cap.version);
    printf("Capabilities: 0x%08x\n", cap.capabilities);

    // Enumerate supported formats
    fmtdesc.index = 0;
    fmtdesc.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    printf("\nSupported Formats:\n");
    while (ioctl(fd, VIDIOC_ENUM_FMT, &fmtdesc) != -1) {
        printf("  %s (FourCC: %c%c%c%c)\n", fmtdesc.description,
               fmtdesc.pixelformat & 0xFF, (fmtdesc.pixelformat >> 8) & 0xFF,
               (fmtdesc.pixelformat >> 16) & 0xFF, (fmtdesc.pixelformat >> 24) & 0xFF);

        // Enumerate frame sizes for the current format
        frmsizeenum.index = 0;
        frmsizeenum.pixel_format = fmtdesc.pixelformat;
        printf("    Supported Frame Sizes:\n");
        while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsizeenum) != -1) {
            printf("      %dx%d\n", frmsizeenum.discrete.width, frmsizeenum.discrete.height);

