#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN  4  // GPIO4 (BCM)
#define TILT_SERVO_PIN 5  // GPIO5 (BCM)
#define UP_BUTTON_PIN   6 // GPIO6 (BCM)
#define DOWN_BUTTON_PIN 7 // GPIO7 (BCM)
#define LEFT_BUTTON_PIN 8 // GPIO8 (BCM)
#define RIGHT_BUTTON_PIN 9 // GPIO9 (BCM)

// Define pulse width limits
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000
#define CENTER_PULSE_WIDTH 1500

// Global variables
volatile sig_atomic_t program_running = 1;
int pan_pulse_width = CENTER_PULSE_WIDTH;
int tilt_pulse_width = CENTER_PULSE_WIDTH;

// Signal handler function
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    program_running = 0;
    gpioPWM(PAN_SERVO_PIN, 0); // Stop PWM on pan servo
    gpioPWM(TILT_SERVO_PIN, 0); // Stop PWM on tilt servo
    gpioTerminate();            // Terminate pigpio
    exit(0);
}

// Function to set servo pulse width
void set_servo_pulse_width(int pin, int pulse_width)
{
    if (pulse_width < MIN_PULSE_WIDTH) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (pulse_width > MAX_PULSE_WIDTH) {
        pulse_width = MAX_PULSE_WIDTH;
    }
    gpioPWM(pin, pulse_width); // Set PWM duty cycle
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors on buttons
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency to 50Hz
    gpioSetPWMfrequency(PAN_SERVO_PIN, 50);
    gpioSetPWMfrequency(TILT_SERVO_PIN, 50);

    // Set PWM range (optional, but recommended)
    gpioSetPWMrange(PAN_SERVO_PIN, 20000); // 20ms period
    gpioSetPWMrange(TILT_SERVO_PIN, 20000);

    // Set initial servo positions
    set_servo_pulse_width(PAN_SERVO_PIN, CENTER_PULSE_WIDTH);
    set_servo_pulse_width(TILT_SERVO_PIN, CENTER_PULSE_WIDTH);

    // Print startup message
    printf("Pan-Tilt Control Program\n");
    printf("Pan servo: GPIO%d (BCM)\n", PAN_SERVO_PIN);
    printf("Tilt servo: GPIO%d (BCM)\n", TILT_SERVO_PIN);
    printf("Up button: GPIO%d (BCM)\n", UP_BUTTON_PIN);
    printf("Down button: GPIO%d (BCM)\n", DOWN_BUTTON_PIN);
    printf("Left button: GPIO%d (BCM)\n", LEFT_BUTTON_PIN);
    printf("Right button: GPIO%d (BCM)\n", RIGHT_BUTTON_PIN);
    printf("Center position: 1500 us\n");

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Check button states
        if (gpioRead(UP_BUTTON_PIN) == 0) {
            pan_pulse_width += 10;
            set_servo_pulse_width(PAN_SERVO_PIN, pan_pulse_width);
            gpioDelay(50000); // Debounce delay
        }
        if (gpioRead(DOWN_BUTTON_PIN) == 0) {
            pan_pulse_width -= 10;
            set_servo_pulse_width(PAN_SERVO_PIN, pan_pulse_width);
            gpioDelay(50000); // Debounce delay
        }
        if (gpioRead(LEFT_BUTTON_PIN) == 0) {
            tilt_pulse_width -= 10;
            set_servo_pulse_width(TILT_SERVO_PIN, tilt_pulse_width);
            gpioDelay(50000); // Debounce delay
        }
        if (gpioRead(RIGHT_BUTTON_PIN) == 0) {
            tilt_pulse_width += 10;
            set_servo_pulse_width(TILT_SERVO_PIN, tilt_pulse_width);
            gpioDelay(50000); // Debounce delay
        }

        gpioDelay(50000); // Delay for 50ms
    }

    // Cleanup (should not reach here if signal handler works)
    gpioPWM(PAN_SERVO_PIN, 0);
    gpioPWM(TILT_SERVO_PIN, 0);
    gpioTerminate();

    return 0;
}

