#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <curl/curl.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 2 // seconds
#define POLL_INTERVAL 0.1 // seconds
#define IMAGE_QUALITY 85
#define MOTION_DETECTED 1
#define MOTION_NOT_DETECTED 0

// Global variables
static volatile int running = 1;
static char *http_endpoint = NULL;
static char *image_directory = NULL;
static int debounce_start_time = 0;

// Structure to hold the image data
typedef struct {
  char *data;
  size_t size;
} ImageData;

// Function prototypes
int initialize_gpio();
int initialize_http_library();
void cleanup_gpio();
void cleanup_http_library();
void signal_handler(int signal);
int capture_image(char *filename, ImageData *image_data);
int post_data(const char *filename, const char *timestamp, int motion_status, const char *image_data, size_t image_size);
void motion_detected_callback(int gpio, int level, uint32_t tick);
int create_directory(const char *directory);

// Callback function to handle the image data
size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
  size_t realsize = size * nmemb;
  ImageData *image_data = (ImageData *)userp;

  char *ptr = realloc(image_data->data, image_data->size + realsize + 1);
  if (ptr == NULL) {
    fprintf(stderr, "Error: Failed to allocate memory in write_callback\n");
    return 0;
  }

  image_data->data = ptr;
  memcpy(&(image_data->data[image_data->size]), contents, realsize);
  image_data->size += realsize;
  image_data->data[image_data->size] = 0;

  return realsize;
}

int main(int argc, char *argv[]) {
  if (argc != 3) {
    fprintf(stderr, "Usage: %s <http_endpoint> <image_directory>\n", argv[0]);
    return 1;
  }

  http_endpoint = argv[1];
  image_directory = argv[2];

  // Initialize signal handling
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Initialize pigpio
  if (initialize_gpio() != 0) {
    fprintf(stderr, "Error: Failed to initialize pigpio\n");
    return 1;
  }

  // Initialize libcurl
  if (initialize_http_library() != 0) {
    fprintf(stderr, "Error: Failed to initialize libcurl\n");
    cleanup_gpio();
    return 1;
  }

  // Create the image directory if it doesn't exist
  if (create_directory(image_directory) != 0) {
    fprintf(stderr, "Error: Failed to create image directory\n");
    cleanup_gpio();
    cleanup_http_library();
    return 1;
  }

  // Set GPIO17 as input with pull-down resistor
  gpioSetMode(GPIO_PIN, PI_INPUT);
  gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

  // Set callback function for motion detection
  gpioSetAlertFuncEx(GPIO_PIN, motion_detected_callback, NULL);

  printf("Motion detection started. Press Ctrl+C to exit.\n");

  // Main loop
  while (running) {
    sleep(1); // Sleep for 1 second
  }

  // Cleanup
  cleanup_gpio();
  cleanup_http_library();

  printf("Motion detection stopped.\n");

  return 0;
}

int initialize_gpio() {
  if (gpioInitialise() < 0) {
    fprintf(stderr, "Error: pigpio initialisation failed\n");
    return 1;
  }
  return 0;
}

int initialize_http_library() {
  curl_global_init(CURL_GLOBAL_DEFAULT);
  return 0;
}

void cleanup_gpio() {
  gpioTerminate();
}

void cleanup_http_library() {
  curl_global_cleanup();
}

void signal_handler(int signal) {
  printf("Signal received (%d). Exiting...\n", signal);
  running = 0;
}

int capture_image(char *filename, ImageData *image_data) {
  char command[256];
  snprintf(command, sizeof(command), "raspistill -o %s/%s -q %d", image_directory, filename, IMAGE_QUALITY);

  FILE *fp = popen(command, "r");
  if (fp == NULL) {
    fprintf(stderr, "Error: Failed to execute raspistill command\n");
    return 1;
  }

  // Read the output of the command (which should be the image data)
  // We don't actually use this output, but it's important to read it to avoid blocking
  char buffer[1024];
  while (fgets(buffer, sizeof(buffer), fp) != NULL) {
    // Do nothing, just read the output
  }

  int status = pclose(fp);
  if (status != 0) {
    fprintf(stderr, "Error: raspistill command failed with status %d\n", status);
    return 1;
  }

  // Read the image data from the file
  FILE *image_fp = fopen(filename, "rb");
  if (image_fp == NULL) {
    fprintf(stderr, "Error: Failed to open image file for reading\n");
    return 1;
  }

  fseek(image_fp, 0, SEEK_END);
  image_data->size = ftell(image_fp);
  fseek(image_fp, 0, SEEK_SET);

  image_data->data = (char *)malloc(image_data->size + 1);
  if (image_data->data == NULL) {
    fprintf(stderr, "Error: Failed to allocate memory for image data\n");
    fclose(image_fp);
    return 1;
  }

  fread(image_data->data, 1, image_data->size, image_fp);
  image_data->data[image_data->size] = '\0';

  fclose(image_fp);

  return 0;
}

int post_data(const char *filename, const char *timestamp, int motion_status, const char *image_data, size_t image_size) {
  CURL *curl;
  CURLcode res;
  char json_payload[2048]; // Adjust size as needed

  // Construct JSON payload
  snprintf(json_payload, sizeof(json_payload), 
           "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion_status\": %d, \"image_data\": \"%s\"}",
           filename, timestamp, motion_status, image_data);

  curl = curl_easy_init();
  if (curl) {
    curl_easy_setopt(curl, CURLOPT_URL, http_endpoint);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_payload));

    // Set the Content-Type header to application/json
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    // Set the write callback to handle the response (optional)
    ImageData image_data_local = {NULL, 0};
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &image_data_local);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
      fprintf(stderr, "Error: curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    } else {
      long response_code;
      curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
      printf("HTTP response code: %ld\n", response_code);
    }

    // Clean up
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    if(image_data_local.data) free(image_data_local.data);
  } else {
    fprintf(stderr, "Error: Failed to initialize curl\n");
    return 1;
  }

  return 0;
}

void motion_detected_callback(int gpio, int level, uint32_t tick) {
  if (level == 1) { // Rising edge detected
    printf("Motion detected!\n");

    // Debouncing
    if (debounce_start_time == 0) {
      debounce_start_time = time(NULL);
    } else {
      time_t current_time = time(NULL);
      if (difftime(current_time, debounce_start_time) >= DEBOUNCE_TIME) {
        printf("Motion confirmed after debounce.\n");

        // Capture image
        time_t rawtime;
        struct tm *timeinfo;
        char filename[80];
        char timestamp[30];
        struct timespec ts;

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        clock_gettime(CLOCK_REALTIME, &ts);

        strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S", timeinfo);
        snprintf(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%03ldZ", timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday, timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec, ts.tv_nsec / 1000000);

        ImageData image_data = {NULL, 0};
        if (capture_image(filename, &image_data) == 0) {
          printf("Image captured: %s\n", filename);

          // Post data
          if (post_data(filename, timestamp, MOTION_DETECTED, image_data.data, image_data.size) == 0) {
            printf("Data posted successfully.\n");
          } else {
            fprintf(stderr, "Error: Failed to post data\n");
          }

          free(image_data.data);
        } else {
          fprintf(stderr, "Error: Failed to capture image\n");
        }

        debounce_start_time = 0; // Reset debounce timer
      } else {
        printf("Motion detected, but still in debounce period.\n");
      }
    }
  }
}

int create_directory(const char *directory) {
  struct stat st = {0};

  if (stat(directory, &st) == -1) {
    if (mkdir(directory, 0777) == 0) {
      printf("Directory created: %s\n", directory);
      return 0;
    } else {
      fprintf(stderr, "Error: Failed to create directory %s\n", directory);
      return 1;
    }
  } else {
    printf("Directory already exists: %s\n", directory);
    return 0;
  }
}

