#include <errno.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 50
#define CAPTURE_TIMEOUT_MS 2000
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"

static volatile int keep_running = 1;
static int gpio_fd = -1;
static FILE *log_fp = NULL;

void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, exiting gracefully.\n", sig);
        keep_running = 0;
    }
}

int gpio_export(int pin) {
    struct gpio_request req;
    memset(&req, 0, sizeof(req));
    req.request_type = GPIO_REQUEST_DIRECTION_OUTPUT; // Request direction
    req.gpio = pin;
    if (ioctl(gpio_fd, GPIO_GET_LINE, &req) < 0) {
        perror("GPIO_GET_LINE failed");
        return -1;
    }
    return 0;
}

int gpio_direction(int pin, const char *direction) {
    struct gpio_request req;
    memset(&req, 0, sizeof(req));
    req.request_type = GPIO_REQUEST_DIRECTION_INPUT; // Request direction
    req.gpio = pin;
    if (ioctl(gpio_fd, GPIO_GET_LINE, &req) < 0) {
        perror("GPIO_GET_LINE failed");
        return -1;
    }
    return 0;
}

int gpio_read(int pin) {
    struct gpio_request req;
    memset(&req, 0, sizeof(req));
    req.request_type = GPIO_REQUEST_DIRECTION_INPUT; // Request direction
    req.gpio = pin;
    if (ioctl(gpio_fd, GPIO_GET_LINE, &req) < 0) {
        perror("GPIO_GET_LINE failed");
        return -1;
    }
    return 0;
}

int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s/%s -w 640 -h 480 -q 85 --timeout %d --nopreview", IMAGE_DIR, filename, CAPTURE_TIMEOUT_MS);
    int status = system(command);
    return status;
}

int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", t);
    int milliseconds = (int)((now - (time_t)t->tm_sec) * 1000);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), "_%03d", milliseconds);

    fprintf(log_fp, "%s: %s\n", timestamp, message);
    fflush(log_fp);
    return 0;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("Failed to open log file");
        return 1;
    }

    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        log_event("Failed to open GPIO chip");
        fclose(log_fp);
        return 1;
    }

    if (gpio_export(GPIO_PIN) < 0) {
        log_event("Failed to export GPIO pin");
        close(gpio_fd);
        fclose(log_fp);
        return 1;
    }

    if (gpio_direction(GPIO_PIN, "in") < 0) {
        log_event("Failed to set GPIO direction to input");
        close(gpio_fd);
        fclose(log_fp);
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");
    log_event("Motion detection started");

    while (keep_running) {
        int value = gpio_read(GPIO_PIN);
        if (value < 0) {
            log_event("Failed to read GPIO value");
            sleep(1); // Avoid spamming the log
            continue;
        }

        if (value == 0) { // Assuming 0 means motion detected
            log_event("Motion detected");

            // Debounce
            usleep(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
            if (gpio_read(GPIO_PIN) == 0) { // Re-read after debounce
                // Capture image
                time_t now = time(NULL);
                struct tm *t = localtime(&now);
                char filename[64];
                strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S", t);
                int milliseconds = (int)((now - (time_t)t->tm_sec) * 1000);
                snprintf(filename + strlen(filename), sizeof(filename) - strlen(filename), "_%03d.jpg", milliseconds);

                int status = capture_image(filename);
                if (status == 0) {
                    char message[128];
                    snprintf(message, sizeof(message), "Image captured: %s", filename);
                    log_event(message);
                } else {
                    char message[128];
                    snprintf(message, sizeof(message), "Image capture failed with status %d", status);
                    log_event(message);
                }
            } else {
                log_event("Motion detected, but debounce failed");
            }
        }
        usleep(10000); // Check every 10ms
    }

    // Cleanup
    close(gpio_fd);
    fclose(log_fp);
    printf("Exiting.\n");
    return 0;
}

