#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <errno.h>
#include <signal.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define CROPPED_WIDTH 200
#define CROPPED_HEIGHT 150
#define CROPPED_SIZE (CROPPED_WIDTH * CROPPED_HEIGHT * 2)

static int fd = -1;
static void *buffer = NULL;
static size_t buffer_size = 0;
static FILE *output_file = NULL;

static void signal_handler(int sig) {
    fprintf(stderr, "Caught signal %d, cleaning up...\n", sig);
    if (fd != -1) {
        if (buffer != NULL) {
            if (munmap(buffer, buffer_size) == -1) {
                perror("munmap");
            }
        }
        if (close(fd) == -1) {
            perror("close");
        }
    }
    if (output_file != NULL) {
        if (fclose(output_file) == EOF) {
            perror("fclose");
        }
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    // Query capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        goto cleanup;
    }

    // Set format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640; // Example width
    fmt.fmt.pix.height = 480; // Example height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    // Map buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        goto cleanup;
    }

    buffer_size = buf.length;
    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        goto cleanup;
    }

    // Queue buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        goto cleanup;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    // Main loop
    while (1) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2; // Timeout of 2 seconds
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (r == -1) {
            if (errno == EINTR) {
                fprintf(stderr, "select interrupted by signal\n");
                continue; // Retry select
            }
            perror("select");
            goto cleanup;
        } else if (r == 0) {
            fprintf(stderr, "select timeout\n");
            goto cleanup;
        } else {
            // Dequeue buffer
            if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
                perror("VIDIOC_DQBUF");
                goto cleanup;
            }

            // Check format
            if (fmt.fmt.pix.width != 640 || fmt.fmt.pix.height != 480 || fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
                fprintf(stderr, "Format mismatch: width=%d, height=%d, pixelformat=0x%x\n", fmt.fmt.pix.width, fmt.fmt.pix.height, fmt.fmt.pix.pixelformat);
                goto cleanup;
            }

            // Crop and write to file
            output_file = fopen("cropped.yuv", "wb");
            if (output_file == NULL) {
                perror("fopen");
                goto cleanup;
            }

            size_t bytes_written = fwrite(buffer, 1, CROPPED_SIZE, output_file);
            if (bytes_written != CROPPED_SIZE) {
                fprintf(stderr, "Error writing to file: wrote %zu bytes, expected %zu\n", bytes_written, CROPPED_SIZE);
                goto cleanup;
            }

            if (fclose(output_file) == EOF) {
                perror("fclose");
                goto cleanup;
            }
            output_file = NULL;

            // Requeue buffer
            if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
