#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define neutral position (90 degrees)
#define NEUTRAL_PAN 90
#define NEUTRAL_TILT 90

// Define angle limits
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define delay between commands (100ms)
#define DELAY_MS 100

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to set servo angle
int set_servo_angle(int gpio, int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (0-%d)\n", MAX_ANGLE);
        return -1;
    }

    // Calculate PWM duty cycle (0-1000000)
    int duty_cycle = (int)(((float)angle / 180.0) * 1000000.0);

    // Set PWM duty cycle
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle for GPIO %d\n", gpio);
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for servos
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);

    // Set neutral position
    if (set_servo_angle(PAN_GPIO, NEUTRAL_PAN) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_servo_angle(TILT_GPIO, NEUTRAL_TILT) != 0) {
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Servo control program. Press arrow keys (up, down, left, right) or 'q' to exit.\n");

    // Main loop
    while (!terminate) {
        int c = getchar();

        switch (c) {
            case 'q':
                printf("Exiting...\n");
                terminate = 1;
                break;
            case 27: // Escape key
                // Read the next two characters to determine the arrow key
                c = getchar();
                if (c == '[') {
                    c = getchar();
                    switch (c) {
                        case 'A': // Up arrow
                            printf("Moving pan servo up\n");
                            if (set_servo_angle(PAN_GPIO, NEUTRAL_PAN + 5) != 0) {
                                fprintf(stderr, "Error: Failed to move pan servo up\n");
                            }
                            break;
                        case 'B': // Down arrow
                            printf("Moving pan servo down\n");
                            if (set_servo_angle(PAN_GPIO, NEUTRAL_PAN - 5) != 0) {
                                fprintf(stderr, "Error: Failed to move pan servo down\n");
                            }
                            break;
                        case 'C': // Right arrow
                            printf("Moving tilt servo right\n");
                            if (set_servo_angle(TILT_GPIO, NEUTRAL_TILT + 5) != 0) {
                                fprintf(stderr, "Error: Failed to move tilt servo right\n");
                            }
                            break;
                        case 'D': // Left arrow
                            printf("Moving tilt servo left\n");
                            if (set_servo_angle(TILT_GPIO, NEUTRAL_TILT - 5) != 0) {
                                fprintf(stderr, "Error: Failed to move tilt servo left\n");
                            }
                            break;
                        default:
                            printf("Unknown arrow key\n");
                            break;
                    }
                }
                break;
            default:
                // Ignore other characters
                break;
        }

        gpioDelay(DELAY_MS * 1000); // Delay in microseconds
    }

    // Set neutral position before exiting
    set_servo_angle(PAN_GPIO, NEUTRAL_PAN);
    set_servo_angle(TILT_GPIO, NEUTRAL_TILT);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

