// OLED Set Pixel
int oled_set_pixel(int x, int y, int color) {
    if (x < 0 || x >= OLED_WIDTH || y < 0 || y >= OLED_HEIGHT) return -1;

    int page = y / 8;
    int bit = y % 8;

    unsigned char data = 0x00;
    if (color == 1) {
        data = 1 << bit;
    }

    if (oled_write_command(0xB0 + page) < 0) return -1; // Set page address
    if (oled_write_command(0x00 + (x & 0x0F)) < 0) return -1; // Set lower column address
    if (oled_write_command(0x10 + ((x >> 4) & 0x0F)) < 0) return -1; // Set higher column address

