// Read CPU Temperature
int read_cpu_temp(char *temp_str, size_t size) {
    FILE *fp;
    char line[256];
    float temp = -1.0f;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file!\n");
        return -1;
    }

    if (fgets(line, sizeof(line), fp) != NULL) {
        temp = (float)atoi(line) / 1000.0f;
        snprintf(temp_str, size, "%.1f°C", temp);
    } else {
        fprintf(stderr, "Error reading temperature file!\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Read CPU Usage
int read_cpu_usage(char *usage_str, size_t size) {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    unsigned long long total, prev_total;
    float usage = -1.0f;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CPU stats file!\n");
        return -1;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error reading CPU stats file!\n");
        fclose(fp);
        return -1;
    }

    prev_user = user;
    prev_nice = nice;
    prev_system = system;
    prev_idle = idle;
    prev_iowait = iowait;
    prev_irq = irq;
    prev_softirq = softirq;
    prev_steal = steal;
    prev_guest = guest;
    prev_guest_nice = guest_nice;

    sleep(1);

    rewind(fp);

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error reading CPU stats file!\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    prev_total = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal + prev_guest + prev_guest_nice;

    unsigned long long idle_time = idle + iowait;
    unsigned long long prev_idle_time = prev_idle + prev_iowait;

    unsigned long long total_time = total;
    unsigned long long prev_total_time = prev_total;

    unsigned long long idle_diff = idle_time - prev_idle_time;
    unsigned long long total_diff = total_time - prev_total_time;

    usage = 100.0f * (1.0f - ((float)idle_diff / (float)total_diff));

    snprintf(usage_str, size, "%.1f%%", usage);
    return 0;
}

// OLED Write String
int oled_write_string(int x, int y, const char *str) {
    if (x < 0 || x >= OLED_WIDTH || y < 0 || y >= OLED_HEIGHT) return -1;

    int current_x = x;
    int current_y = y;

    for (int i = 0; str[i] != '\0'; i++) {
        char c = str[i];
        if (c >= ' ' && c <= '~') {
            int char_index = c - ' ';

            for (int j = 0; j < 5; j++) {
                unsigned char pixel_data = font[char_index][j];

                for (int k = 0; k < 8; k++) {
                    if ((pixel_data >> k) & 0x01) {
                        if (oled_set_pixel(current_x + j, current_y + k, 1) < 0) return -1;
                    } else {
                        if (oled_set_pixel(current_x + j, current_y + k, 0) < 0) return -1;
                    }
                }
            }
            current_x += 6; // Character width + 1 pixel spacing
        } else {
            // Handle unknown characters (e.g., space)
            current_x += 6;
        }

        if (current_x > OLED_WIDTH) {
            current_x = x; // Wrap to the next line
            current_y += 8; // Move to the next line
            if (current_y > OLED_HEIGHT) return -1; // Prevent overflow
        }
    }
    return 0;
}

// Signal Handler
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, OLED_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize OLED display
    if (oled_init() < 0) {
        fprintf(stderr, "OLED initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Clear the display
    if (oled_clear() < 0) {
        fprintf(stderr, "OLED clear failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    char temp_str[10];
    char usage_str[10];

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        if (read_cpu_temp(temp_str, sizeof(temp_str)) < 0) {
            snprintf(temp_str, sizeof(temp_str), "Error");
        }

        // Read CPU usage
        if (read_cpu_usage(usage_str, sizeof(usage_str)) < 0) {
            snprintf(usage_str, sizeof(usage_str), "Error");
        }

        // Clear the display
        if (oled_clear() < 0) {
            fprintf(stderr, "OLED clear failed\n");
            break;
        }

        // Write temperature to the display
        if (oled_write_string(0, 0, temp_str) < 0) {
            fprintf(stderr, "OLED write string failed\n");
            break;
        }

        // Write CPU usage to the display
        if (oled_write_string(0, 16, usage_str) < 0) {
            fprintf(stderr, "OLED write string failed\n");
            break;
        }

        // Display the content
        if (oled_display() < 0) {
            fprintf(stderr, "OLED display failed\n");
            break;
        }

        sleep(1);
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

