// Constants
#define GPIO_PIN 17
#define PULSES_PER_LITER 450.0
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define I2C_BUS 1

// Global variables
volatile int pulse_count = 0;
double total_volume = 0.0;
int i2c_handle;
int running = 1;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate();
void update_total_volume(double flow_rate);
void display_on_lcd(double flow_rate, double total_volume);
void signal_handler(int signal);
int lcd_init();
void lcd_clear();
void lcd_print(const char *text);

// Pulse callback function
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Calculate flow rate in liters per minute
double calculate_flow_rate() {
    double flow_rate = (double)pulse_count / PULSES_PER_LITER * 60.0;
    pulse_count = 0; // Reset pulse count
    return flow_rate;
}

// Update total volume
void update_total_volume(double flow_rate) {
    total_volume += flow_rate / 60.0; // Accumulate volume over one second
}

// Initialize LCD
int lcd_init() {
    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Initialize LCD (4-bit mode)
    gpioDelay(50000); // Wait 50ms
    i2cWriteByteData(i2c_handle, 0x00, 0x33); // Initialize
    gpioDelay(5000);  // Wait 5ms
    i2cWriteByteData(i2c_handle, 0x00, 0x32); // Initialize
    gpioDelay(5000);  // Wait 5ms
    i2cWriteByteData(i2c_handle, 0x00, 0x28); // 4-bit mode, 2 lines, 5x8 font
    i2cWriteByteData(i2c_handle, 0x00, 0x0C); // Display on, cursor off, blink off
    i2cWriteByteData(i2c_handle, 0x00, 0x06); // Increment cursor, no shift
    i2cWriteByteData(i2c_handle, 0x00, 0x01); // Clear display
    gpioDelay(2000);  // Wait 2ms

    return 0;
}

// Clear LCD display
void lcd_clear() {
    i2cWriteByteData(i2c_handle, 0x00, 0x01); // Clear display
    gpioDelay(2000); // Wait 2ms
}

// Print text to LCD
void lcd_print(const char *text) {
    int len = strlen(text);
    for (int i = 0; i < len; i++) {
        i2cWriteByteData(i2c_handle, 0x40, text[i]);
    }
}

// Display data on LCD
void display_on_lcd(double flow_rate, double total_volume) {
    char buffer[32];
    snprintf(buffer, sizeof(buffer), "Flow: %.2f LPM", flow_rate);
    lcd_clear();
    lcd_print(buffer);

    snprintf(buffer, sizeof(buffer), "Total: %.2f L", total_volume);
    lcd_print(buffer);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    gpioTerminate();
    i2cClose(i2c_handle);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set up interrupt on rising edge
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    if (lcd_init() != 0) {
        fprintf(stderr, "LCD initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Calculate flow rate
        double flow_rate = calculate_flow_rate();

        // Update total volume
        update_total_volume(flow_rate);

        // Display on LCD
        display_on_lcd(flow_rate, total_volume);

        // Wait for one second
        sleep(1);
    }

    // Cleanup (should not reach here if signal handler works)
    gpioTerminate();
    i2cClose(i2c_handle);
    return 0;
}

