#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <wiringPiSPI.h>

// Configuration
#define ANEMOMETER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define I2C_ADDRESS 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define SAMPLE_WINDOW_MS 500
#define PULSES_PER_REV 1.0 // Adjust based on anemometer
#define WIND_VANE_CHANNEL 0
#define ADC_STUCK_THRESHOLD 10
#define ADC_ERROR_THRESHOLD 5
#define I2C_ERROR_THRESHOLD 5
#define SPI_ERROR_THRESHOLD 5

// Global variables
volatile int pulse_count = 0;
int lcd_handle;
int spi_fd;
int i2c_fd;
int error_count = 0;
int anemometer_active = 1;

// Function prototypes
void anemometer_interrupt();
float calculate_wind_speed(int pulse_count, int sample_window_ms);
int read_wind_direction();
void lcd_init();
void lcd_clear();
void lcd_set_cursor(int row, int col);
void lcd_print(const char *str);
void lcd_print_float(float num, int precision);
void handle_error(const char *message);
void signal_handler(int signal);

// Anemometer interrupt handler
void anemometer_interrupt() {
    if (anemometer_active) {
        pulse_count++;
    }
}

// Calculate wind speed
float calculate_wind_speed(int pulse_count, int sample_window_ms) {
    float revolutions_per_second = (float)pulse_count / (sample_window_ms / 1000.0);
    float wind_speed = revolutions_per_second * PULSES_PER_REV * 2.0; // m/s
    return wind_speed;
}

// Read wind direction from MCP3008 ADC
int read_wind_direction() {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | WIND_VANE_CHANNEL) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00;

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        handle_error("SPI transaction failed");
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// LCD initialization
void lcd_init() {
    // Initialization sequence (adjust based on your LCD module)
    lcd_write_command(0x33); // Initialize
    lcd_write_command(0x32); // Initialize
    lcd_write_command(0x28); // 4-bit mode, 2 lines, 5x8 font
    lcd_write_command(0x0C); // Display on, cursor off, blink off
    lcd_write_command(0x06); // Increment cursor, no shift
    lcd_write_command(0x01); // Clear display
    delay(2); // Delay for initialization
}

// LCD clear display
void lcd_clear() {
    lcd_write_command(0x01); // Clear display
    delay(2); // Delay for clear
}

// LCD set cursor position
void lcd_set_cursor(int row, int col) {
    int addr;
    if (row == 0) {
        addr = 0x00 + col;
    } else {
        addr = 0x40 + col;
    }
    lcd_write_command(0x80 + addr);
}

// LCD write command
void lcd_write_command(unsigned char cmd) {
    unsigned char data_u, data_l;
	unsigned char data_t[4];
	data_u = (cmd&0xF0);
	data_l = ((cmd<<4)&0xF0);
	data_t[0] = data_u|0x0C;  //en=1, rs=0
	data_t[1] = data_u|0x08;  //en=0, rs=0
	data_t[2] = data_l|0x0C;  //en=1, rs=0
	data_t[3] = data_l|0x08;  //en=0, rs=0
    write(i2c_fd, data_t, 4);
}

// LCD write data
void lcd_write_data(unsigned char data) {
    unsigned char data_u, data_l;
	unsigned char data_t[4];
	data_u = (data&0xF0);
	data_l = ((data<<4)&0xF0);
	data_t[0] = data_u|0x0D;  //en=1, rs=1
	data_t[1] = data_u|0x09;  //en=0, rs=1
	data_t[2] = data_l|0x0D;  //en=1, rs=1
	data_t[3] = data_l|0x09;  //en=0, rs=1
    write(i2c_fd, data_t, 4);
}

// LCD print string
void lcd_print(const char *str) {
    int i = 0;
    while (str[i] != 0) {
        lcd_write_data(str[i]);
        i++;
    }
}

// LCD print float
void lcd_print_float(float num, int precision) {
    char buf[20];
    sprintf(buf, "%.*f", precision, num);
    lcd_print(buf);
}

// Handle errors
void handle_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    error_count++;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    anemometer_active = 0; // Stop the anemometer interrupt
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_print("Shutting down...");
    close(spi_fd);
    close(i2c_fd);
    exit(0);
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd == -1) {
        fprintf(stderr, "SPI initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(I2C_ADDRESS);
    if (i2c_fd == -1) {
        fprintf(stderr, "I2C initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize LCD
    lcd_init();

    // Set up interrupt for anemometer
    if (wiringPiISR(ANEMOMETER_GPIO, INT_EDGE_RISING, &anemometer_interrupt) < 0) {
        fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int adc_value;
    int adc_stuck_count = 0;
    int i2c_error_count = 0;
    int spi_error_count = 0;

    while (1) {
        // Sample anemometer data
        pulse_count = 0;
        anemometer_active = 1; // Re-enable the interrupt
        delay(SAMPLE_WINDOW_MS);
        anemometer_active = 0; // Disable the interrupt after the sample window

        float wind_speed = calculate_wind_speed(pulse_count, SAMPLE_WINDOW_MS);

        // Read wind direction
        adc_value = read_wind_direction();
        if (adc_value == -1) {
            handle_error("Failed to read wind direction");
            spi_error_count++;
            if (spi_error_count > SPI_ERROR_THRESHOLD) {
                handle_error("Too many SPI errors, exiting");
                break;
            }
        } else {
            spi_error_count = 0; // Reset error count
        }

        // Check for sensor stuck conditions
        if (adc_value == 0) {
            adc_stuck_count++;
            if (adc_stuck_count > ADC_STUCK_THRESHOLD) {
                handle_error("ADC stuck at 0");
                break;
            }
        } else if (adc_value == 1023) {
            adc_stuck_count++;
            if (adc_stuck_count > ADC_STUCK_THRESHOLD) {
                handle_error("ADC stuck at 1023");
                break;
            }
        } else {
            adc_stuck_count = 0; // Reset stuck count
        }

        // Display data on LCD
        lcd_clear();
        lcd_set_cursor(0, 0);
        lcd_print("Speed: ");
        lcd_print_float(wind_speed, 2);
        lcd_print(" m/s");

        lcd_set_cursor(1, 0);
        lcd_print("Dir: ");
        lcd_print_float((float)adc_value, 0);
        lcd_print(" ");

        delay(500); // Update every 500ms

        // Check for I2C errors
        if (i2c_error_count > I2C_ERROR_THRESHOLD) {
            handle_error("Too many I2C errors, exiting");
            break;
        }
    }

    // Cleanup
    lcd_clear();
    close(spi_fd);
    close(i2c_fd);

    return 0;
}

