#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_PIN 17
#define LCD_I2C_ADDR 0x27 // I2C address of the LCD1602

// Define LCD dimensions
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

// Global variables
static volatile int pulse_count = 0;
static volatile int running = 1;
static int i2c_handle;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data);
float calculate_flow_rate(int pulse_count);
void display_flow_rate(float flow_rate);
void signal_handler(int signal);
int lcd_init();
void lcd_clear();
void lcd_set_cursor(int row, int col);
void lcd_print(const char *str);

// Pulse callback function
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Calculate flow rate in liters per minute
float calculate_flow_rate(int pulse_count) {
    return (float)pulse_count / 7.5; // 7.5 pulses per liter
}

// Display flow rate on LCD
void display_flow_rate(float flow_rate) {
    char buffer[20];
    snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f L/min", flow_rate);
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_print(buffer);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialize LCD
int lcd_init() {
    // Initialize I2C
    i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0); // Bus 1, address 0x27, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Initialize LCD (4-bit mode)
    gpioDelay(50000); // Wait 50ms
    i2cWriteByteData(i2c_handle, 0x00, 0x33); // Initialize
    gpioDelay(5000);  // Wait 5ms
    i2cWriteByteData(i2c_handle, 0x00, 0x32); // Initialize
    gpioDelay(5000);  // Wait 5ms
    i2cWriteByteData(i2c_handle, 0x00, 0x28); // 4-bit mode, 2 lines, 5x8 font
    i2cWriteByteData(i2c_handle, 0x00, 0x0C); // Display on, cursor off, blink off
    i2cWriteByteData(i2c_handle, 0x00, 0x06); // Increment cursor, no shift
    i2cWriteByteData(i2c_handle, 0x00, 0x01); // Clear display
    gpioDelay(2000);  // Wait 2ms

    return 0;
}

// Clear LCD display
void lcd_clear() {
    i2cWriteByteData(i2c_handle, 0x00, 0x01); // Clear display
    gpioDelay(2000); // Wait 2ms
}

// Set cursor position on LCD
void lcd_set_cursor(int row, int col) {
    int addr;
    if (row == 0) {
        addr = 0x80 + col;
    } else {
        addr = 0xC0 + col;
    }
    i2cWriteByteData(i2c_handle, 0x00, addr);
}

// Print string to LCD
void lcd_print(const char *str) {
    int len = strlen(str);
    for (int i = 0; i < len; i++) {
        i2cWriteByteData(i2c_handle, 0x40, str[i]);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for sensor pin
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Set up interrupt on rising edge
    if (gpioSetAlertFuncEx(SENSOR_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up alert function\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    if (lcd_init() != 0) {
        fprintf(stderr, "LCD initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t start_time, current_time;
    time(&start_time);

    // Main loop
    while (running) {
        pulse_count = 0; // Reset pulse count
        time(&start_time);
        sleep(1); // Wait for 1 second

        time(&current_time);
        double elapsed_time = difftime(current_time, start_time);

        if (elapsed_time != 1.0) {
            fprintf(stderr, "Error: Elapsed time is not 1 second.  Expected: 1.0, Got: %f\n", elapsed_time);
            continue; // Skip to the next iteration
        }

        float flow_rate = calculate_flow_rate(pulse_count);
        display_flow_rate(flow_rate);

        if (pulse_count == 0) {
            lcd_clear();
            lcd_set_cursor(0, 0);
            lcd_print("No Water Flow");
            gpioDelay(1000000); // Wait 1 second
            lcd_clear();
        }
    }

    // Clean up
    lcd_clear();
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

