#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for rows and columns
const int ROW_PINS[] = {17, 18, 27, 22, 23, 24, 25, 4};
const int COL_PINS[] = {5, 6, 12, 13, 19, 16, 26, 20};
const int NUM_ROWS = sizeof(ROW_PINS) / sizeof(ROW_PINS[0]);
const int NUM_COLS = sizeof(COL_PINS) / sizeof(COL_PINS[0]);

// Define delay in microseconds
const int DELAY_US = 800;

// Global variable to track program state for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set row pins as outputs and initialize to HIGH (common anode)
    for (int i = 0; i < NUM_ROWS; i++) {
        gpioSetMode(ROW_PINS[i], PI_OUTPUT);
        gpioWrite(ROW_PINS[i], 1); // Common anode, so initially off
    }

    // Set column pins as outputs and initialize to HIGH (cathode)
    for (int i = 0; i < NUM_COLS; i++) {
        gpioSetMode(COL_PINS[i], PI_OUTPUT);
        gpioWrite(COL_PINS[i], 1); // Initially off
    }

    return 0;
}

// Function to display a frame on the LED matrix
void display_frame(const int frame[NUM_ROWS][NUM_COLS]) {
    for (int row = 0; row < NUM_ROWS; row++) {
        gpioWrite(ROW_PINS[row], 0); // Turn on the row

        for (int col = 0; col < NUM_COLS; col++) {
            gpioWrite(COL_PINS[col], frame[row][col]); // Set the column
        }

        gpioDelay(DELAY_US); // Delay for scanning
        gpioWrite(ROW_PINS[row], 1); // Turn off the row
    }
}

// Function to create a wave-like animation (left-to-right)
void create_wave_left(int frame[NUM_ROWS][NUM_COLS]) {
    for (int col = 0; col < NUM_COLS; col++) {
        for (int row = 0; row < NUM_ROWS; row++) {
            frame[row][col] = (row + col) % 2; // Wave pattern
        }
    }
}

// Function to create a wave-like animation (right-to-left)
void create_wave_right(int frame[NUM_ROWS][NUM_COLS]) {
    for (int col = 0; col < NUM_COLS; col++) {
        for (int row = 0; row < NUM_ROWS; row++) {
            frame[row][col] = (row + (NUM_COLS - 1 - col)) % 2; // Wave pattern
        }
    }
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    // Turn off all LEDs
    for (int i = 0; i < NUM_ROWS; i++) {
        gpioWrite(ROW_PINS[i], 1);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        gpioWrite(COL_PINS[i], 1);
    }

    // Release GPIO pins
    gpioTerminate();
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    int frame[NUM_ROWS][NUM_COLS];

    // Main loop
    while (program_running) {
        // Create and display left-to-right wave
        create_wave_left(frame);
        display_frame(frame);
        gpioDelay(DELAY_US * 2); // Short pause between frames

        // Create and display right-to-left wave
        create_wave_right(frame);
        display_frame(frame);
        gpioDelay(DELAY_US * 2); // Short pause between frames
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

