// Function to initialize the Si1145 sensor
int initialize_sensor() {
    // Reset the sensor (example initialization sequence)
    if (i2cWriteByteData(i2c_handle, 0x17, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor.\n");
        return -1;
    }
    gpioDelay(10); // Small delay after reset

