    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Starting data logging... Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&proximity, &ambient_light) == 0) {
            // Get timestamp
            timestamp = get_iso8601_timestamp();

            // Log the data
            if (log_data(timestamp, proximity, ambient_light) != 0) {
                fprintf(stderr, "Error: Failed to log data.\n");
            }

            free(timestamp); // Free the allocated memory
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Wait for the next sample
    }

    // Clean up
    printf("Closing I2C connection...\n");
    i2cClose(i2c_handle);
    printf("Closing log file...\n");
    fclose(log_file);
    printf("Terminating pigpio...\n");
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

