#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_PIN 4
#define LED_PIN 17

static volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    FILE *log_file;
    int sensor_value;
    time_t rawtime;
    struct tm *info;
    char timestamp[30];
    int led_state = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Main loop
    while (running) {
        sensor_value = gpioRead(SENSOR_PIN);

        if (sensor_value == 0) { // Falling edge detected
            // Get current time
            time(&rawtime);
            info = gmtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", info);

            // Open log file in append mode
            log_file = fopen("proximity.log", "a");
            if (log_file == NULL) {
                fprintf(stderr, "Error opening log file!\n");
            } else {
                // Write timestamp to log file
                fprintf(log_file, "%s Object detected\n", timestamp);
                fclose(log_file);
            }

            // Blink LED
            gpioWrite(LED_PIN, 1); // Turn LED on
            gpioDelay(100);        // Wait 100ms
            gpioWrite(LED_PIN, 0); // Turn LED off

            // Debounce: Wait for a short period to avoid multiple triggers
            gpioDelay(200); // Wait 200ms
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();

    return 0;
}

