#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PART_ID_REG 0x00
#define ALS_VIS_DATA0 0x22
#define PS1_DATA0 0x24
#define RESET_CMD 0x07
#define HW_KEY 0x17

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1145_init();
int read_sensor_data(int *proximity, int *ambient_light);
int log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Si1145 initialization function
int si1145_init() {
    int status;

    // Reset the device
    status = i2cWriteByteData(i2c_handle, RESET_CMD, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error resetting Si1145: %d\n", status);
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Check PART_ID
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

