#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define TIMEOUT_US 30000        // 30ms timeout in microseconds
#define LOG_INTERVAL_SEC 60    // 60 seconds

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void triggerSensor();
long pulseIn(int pin, int level, int timeout);
float calculateDistance(long pulse_duration);
void logDistance(float distance);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse duration on the echo pin
long pulseIn(int pin, int level, int timeout) {
    long width = 0;
    long start = gpioTick();

    // Wait for the pulse to start
    while (gpioRead(pin) != level) {
        if (gpioTick() - start > timeout) {
            return 0; // Timeout
        }
    }

    long pulse_start = gpioTick();

    // Measure the pulse width
    while (gpioRead(pin) == level) {
        if (gpioTick() - pulse_start > timeout) {
            return 0; // Timeout
        }
        width++;
    }

    return width;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_duration) {
    return (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s, then divide by 2 for one-way distance
}

// Function to log the distance to a file
void logDistance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    struct timespec ts;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    clock_gettime(CLOCK_REALTIME, &ts);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), 5, ".%03ldZ", ts.tv_nsec / 1000000);

    if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
        fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file);
        if (distance < 15.0) {
            fprintf(log_file, "%s Time to water the plant!\n", timestamp);
            fflush(log_file);
        }
    } else {
        fprintf(log_file, "%s Error: Distance out of range (%.2f cm)\n", timestamp, distance);
        fflush(log_file);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        triggerSensor();
        long pulse_duration = pulseIn(ECHO_PIN, 1, TIMEOUT_US);

        if (pulse_duration > 0) {
            float distance = calculateDistance(pulse_duration);
            logDistance(distance);
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[30];
            struct timespec ts;

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            clock_gettime(CLOCK_REALTIME, &ts);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
            snprintf(timestamp + strlen(timestamp), 5, ".%03ldZ", ts.tv_nsec / 1000000);

            fprintf(log_file, "%s Error: Timeout or sensor absent\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(LOG_INTERVAL_SEC * 1000); // Wait for the next log interval
    }

    // Close log file and terminate pigpio
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

