    return (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s, then divide by 2 for one-way distance
}

// Function to log the distance to a file
void logDistance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    struct timespec ts;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    clock_gettime(CLOCK_REALTIME, &ts);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), 5, ".%03ldZ", ts.tv_nsec / 1000000);

    if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
        fprintf(log_file, "%s Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file);
        if (distance < 15.0) {
            fprintf(log_file, "%s Time to water the plant!\n", timestamp);
            fflush(log_file);
        }
    } else {
        fprintf(log_file, "%s Error: Distance out of range (%.2f cm)\n", timestamp, distance);
        fflush(log_file);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        triggerSensor();
        long pulse_duration = pulseIn(ECHO_PIN, 1, TIMEOUT_US);

        if (pulse_duration > 0) {
            float distance = calculateDistance(pulse_duration);
            logDistance(distance);
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[30];
            struct timespec ts;

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            clock_gettime(CLOCK_REALTIME, &ts);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
            snprintf(timestamp + strlen(timestamp), 5, ".%03ldZ", ts.tv_nsec / 1000000);

            fprintf(log_file, "%s Error: Timeout or sensor absent\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(LOG_INTERVAL_SEC * 1000); // Wait for the next log interval
    }

    // Close log file and terminate pigpio
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

