#include <unistd.h>

// Constants
#define I2C_ADDR 0x39
#define I2C_BUS 1
#define PROX_DATA_REG 0x08
#define BPM_DATA_REG 0x0A
#define SAMPLE_INTERVAL_MS 100
#define CSV_FILENAME "heartrate.csv"

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t running = 1;

// Structure for sensor data
typedef struct {
    int proximity;
    int bpm;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
int read_sensor_data(sensor_data_t *data);
float calculate_bpm(int proximity);
int write_data_to_csv(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the sensor
int initialize_sensor() {
    // Example initialization sequence (replace with actual Si1182 initialization)
    if (i2cWriteByteData(i2c_handle, 0x17, 0x01) < 0) { // Example register write
        fprintf(stderr, "Error writing to sensor during initialization.\n");
        return -1;
    }
    gpioDelay(1000); // Delay for 1ms
    if (i2cWriteByteData(i2c_handle, 0x18, 0x02) < 0) { // Example register write
        fprintf(stderr, "Error writing to sensor during initialization.\n");
        return -1;
    }
    gpioDelay(1000); // Delay for 1ms
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    int proximity, bpm;

    proximity = i2cReadWordData(i2c_handle, PROX_DATA_REG);
    if (proximity < 0) {
        fprintf(stderr, "Error reading proximity data: %d\n", proximity);
        return -1;
    }

    bpm = i2cReadWordData(i2c_handle, BPM_DATA_REG);
    if (bpm < 0) {
        fprintf(stderr, "Error reading BPM data: %d\n", bpm);
        return -1;
    }

    data->proximity = proximity;
    data->bpm = bpm;

    return 0;
}

// Function to calculate BPM (example formula, adjust as needed)
float calculate_bpm(int proximity) {
    // This is a placeholder.  A real implementation would use a more sophisticated
    // algorithm based on the proximity data.
    // For example, you might use a lookup table or a more complex formula.
    // This example just returns a value based on the proximity.
    return (float)proximity * 0.1; // Example scaling
}

// Function to write data to CSV file
int write_data_to_csv(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(csv_file, "%s,%d\n", timestamp, data.bpm);
    fflush(csv_file);

    return 0;
}

