    sensor_data_t sensor_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for writing
    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,bpm\n");
    }
    rewind(csv_file);

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        if (read_sensor_data(&sensor_data) == 0) {
            sensor_data.bpm = (int)calculate_bpm(sensor_data.proximity);
            write_data_to_csv(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Skipping sample.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for sample interval
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(csv_file);
    gpioTerminate();

    return 0;
}

