#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define GPIO_PIN 17
#define RESULT_INTERRUPT_STATUS 0x0014
#define DISTANCE_MM 0x001E
#define TIMEOUT_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int check_sensor_presence(int i2c_handle);
int configure_interrupt(int gpio_pin);
int read_distance(int i2c_handle);
void log_distance(FILE *log_file, int distance_mm);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to check sensor presence
int check_sensor_presence(int i2c_handle) {
    char data[2];
    int result;

    // Read two bytes from the sensor's default address (0x00)
    result = i2cReadI2CBlockData(i2c_handle, 0x00, data, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return 0; // Sensor not present
    }

    // Check if the first byte is 0xEE (VL53L0X signature)
    if (data[0] != 0xEE) {
        fprintf(stderr, "Incorrect sensor signature: 0x%02X\n", data[0]);
        return 0; // Sensor not present
    }

    printf("Sensor found!\n");
    return 1; // Sensor present
}

// Function to configure interrupt
int configure_interrupt(int gpio_pin) {
    gpioSetMode(gpio_pin, PI_INPUT);
    gpioSetPullUpDown(gpio_pin, PI_PUD_UP);
    gpioSetAlertFunc(gpio_pin, NULL); // Disable interrupts initially
    return 0;
}

// Function to read distance
int read_distance(int i2c_handle) {
    char data[2];
    int result;
    uint16_t distance;

    // Write 0x00 to RESULT_INTERRUPT_STATUS to clear any pending interrupts
    result = i2cWriteByteData(i2c_handle, RESULT_INTERRUPT_STATUS, 0x00);
    if (result != 0) {
        fprintf(stderr, "Error clearing interrupt status: %d\n", result);
        return -1;
    }

    // Start a single measurement
    result = i2cWriteByteData(i2c_handle, 0x0000, 0x01); // Start measurement
    if (result != 0) {
        fprintf(stderr, "Error starting measurement: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete with timeout
    int timeout_count = 0;
    while (1) {
        result = i2cReadByteData(i2c_handle, RESULT_INTERRUPT_STATUS);
        if (result < 0) {
            fprintf(stderr, "Error reading interrupt status: %d\n", result);
            return -1;
        }

        if (result & 0x04) { // Check bit 2 for data ready
            break;
        }

        gpioDelay(1); // Small delay
        timeout_count++;
        if (timeout_count > TIMEOUT_MS) {
            fprintf(stderr, "Timeout waiting for measurement\n");
            return -1;
        }
    }

    // Read the distance
    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_MM, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    distance = (data[0] << 8) | data[1];

    return distance;
}

// Function to log distance
void log_distance(FILE *log_file, int distance_mm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, distance_mm);
    fflush(log_file); // Ensure data is written to file immediately
    printf("%s, %d mm\n", timestamp, distance_mm);
}

int main() {
    int distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check sensor presence
    if (!check_sensor_presence(i2c_handle)) {
        fprintf(stderr, "Sensor not found, exiting\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure interrupt
    if (configure_interrupt(GPIO_PIN) != 0) {
        fprintf(stderr, "Error configuring interrupt\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Enable interrupt on falling edge
        gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Re-enable interrupt

        // Wait for interrupt (or timeout)
        gpioDelay(1000); // Wait 1 second

        // Disable interrupt
        gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable interrupt

        // Read distance
        distance = read_distance(i2c_handle);
        if (distance >= 0) {
            // Log distance
            log_distance(log_file, distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

