FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t proximity;
    uint16_t ambient_light;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retry mechanism
int read_sensor_data(sensor_data_t *data) {
    int result;
    uint8_t buffer[4];

    // Read proximity data
    result = i2cReadI2CBlockData(i2c_handle, PROX_DATA_REG, (char *)buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading proximity data: %d\n", result);
        return -1;
    }
    data->proximity = (buffer[1] << 8) | buffer[0];

    // Read ambient light data
    result = i2cReadI2CBlockData(i2c_handle, ALS_DATA_REG, (char *)buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ambient light data: %d\n", result);
        return -1;
    }
    data->ambient_light = (buffer[1] << 8) | buffer[0];

    return 0;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Proximity: %u, Ambient Light: %u\n", timestamp, data.proximity, data.ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

