    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    exit(0);
}

// Initializes the ICU-20201 sensor
int initialize_sensor() {
    int who_am_i;

    // Verify sensor presence by reading WHO_AM_I register
    who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }

    if (who_am_i != 0x47) { // Expected value for ICU-20201
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x47, got 0x%02X\n", who_am_i);
        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

