#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define INTRUSION_THRESHOLD 1000 // mm
#define SAMPLE_DELAY 100 // ms
#define MEASUREMENT_DELAY 10 // ms
#define RESPONSE_LENGTH 15

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    uint8_t header;
    uint8_t reserved1;
    uint8_t reserved2;
    uint8_t reserved3;
    uint8_t reserved4;
    uint8_t reserved5;
    uint8_t reserved6;
    uint8_t reserved7;
    uint8_t reserved8;
    uint8_t reserved9;
    uint8_t reserved10;
    uint8_t reserved11;
    uint8_t reserved12;
    uint8_t reserved13;
    uint8_t reserved14;
    uint8_t reserved15;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_measurement_command();
int read_sensor_data(sensor_data_t *data);
uint16_t extract_distance(const sensor_data_t *data);
float calculate_average_distance(uint16_t distances[], int num_samples);
int log_intrusion(float average_distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send measurement command
int send_measurement_command() {
    char command[4] = {0x00, 0x00, 0x00, 0x00};
    int result = i2cWriteDevice(i2c_handle, command, 4);
    if (result != 4) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY * 1000); // Delay in microseconds
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[RESPONSE_LENGTH];
    int result = i2cReadDevice(i2c_handle, buffer, RESPONSE_LENGTH);
    if (result != RESPONSE_LENGTH) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    data->header = buffer[0];
    data->reserved1 = buffer[1];
    data->reserved2 = buffer[2];
    data->reserved3 = buffer[3];
    data->reserved4 = buffer[4];
    data->reserved5 = buffer[5];
    data->reserved6 = buffer[6];
    data->reserved7 = buffer[7];
    data->reserved8 = buffer[8];
    data->reserved9 = buffer[9];
    data->reserved10 = buffer[10];
    data->reserved11 = buffer[11];
    data->reserved12 = buffer[12];
    data->reserved13 = buffer[13];
    data->reserved14 = buffer[14];
    data->reserved15 = buffer[15];

    return 0;
}

// Extract distance from sensor data
uint16_t extract_distance(const sensor_data_t *data) {
    return (uint16_t)((data->reserved11 << 8) | data->reserved12);
}

// Calculate average distance
float calculate_average_distance(uint16_t distances[], int num_samples) {
    double sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += distances[i];
    }
    return (float)(sum / num_samples);
}

// Log intrusion event
int log_intrusion(float average_distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("intrusion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "%s, Average Distance: %.2f mm\n", timestamp, average_distance);
    fclose(log_file);

    return 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t distances[10];
        sensor_data_t sensor_data;

        // Take 10 measurements
        for (int i = 0; i < 10; i++) {
            if (send_measurement_command() != 0) {
                fprintf(stderr, "Error sending measurement command, exiting.\n");
                cleanup();
                return 1;
            }

            if (read_sensor_data(&sensor_data) != 0) {
                fprintf(stderr, "Error reading sensor data, exiting.\n");
                cleanup();
                return 1;
            }

            distances[i] = extract_distance(&sensor_data);
            gpioDelay(SAMPLE_DELAY * 1000); // Delay in microseconds
        }

        // Calculate average distance
        float average_distance = calculate_average_distance(distances, 10);

        // Check for intrusion
        if (average_distance < INTRUSION_THRESHOLD) {
            if (log_intrusion(average_distance) != 0) {
                fprintf(stderr, "Error logging intrusion, exiting.\n");
                cleanup();
                return 1;
            }
            printf("Intrusion detected! Average distance: %.2f mm\n", average_distance);
        }

        gpioDelay(100 * 1000); // Delay between cycles
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

