int init_vl53l0x() {
    int model_id, revision_id;

    // Read model ID
    model_id = i2cReadByteData(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }

    // Read revision ID
    revision_id = i2cReadByteData(i2c_handle, VL53L0X_REG_IDENTIFICATION_REVISION_ID);
    if (revision_id < 0) {
        fprintf(stderr, "Error reading revision ID: %s\n", strerror(errno));
        return -1;
    }

    // Verify model ID
    if (model_id != VL53L0X_EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: Incorrect model ID (0x%02X, expected 0x%02X)\n", model_id, VL53L0X_EXPECTED_MODEL_ID);
        return -1;
    }

    printf("VL53L0X sensor initialized successfully. Model ID: 0x%02X, Revision ID: 0x%02X\n", model_id, revision_id);
    return 0;
}

// Read distance from VL53L0X sensor
int read_distance(int *distance) {
    int status, distance_raw;

    // Check for interrupt
    status = i2cReadByteData(i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error reading interrupt status: %s\n", strerror(errno));
        return -1;
    }

    if (status & 0x07) { // Check bit 0-2 for new measurement
        // Read distance
        distance_raw = i2cReadWordData(i2c_handle, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
        if (distance_raw < 0) {
            fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
            return -1;
        }

        *distance = distance_raw;
        return 0;
    } else {
        return -1; // No new measurement
    }
}

// Print distance to stdout
void print_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s Distance: %d mm\n", timestamp, distance);
}

int main() {
    int distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L0X sensor
    if (init_vl53l0x() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        if (read_distance(&distance) == 0) {
            print_distance(distance);
        } else {
            //fprintf(stderr, "No new measurement available\n");
        }

        gpioDelay(500); // 500ms delay
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

