int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the proximity data from the sensor
        int data = i2cReadWordData(i2c_handle, PROX_DATA_REG);
        if (data < 0) {
            fprintf(stderr, "Failed to read proximity data: %d\n", data);
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C device: %d\n", i2c_handle);
                gpioTerminate();
                return 1;
            }
            gpioDelay(100); // Small delay before retrying
            continue;       // Skip to the next iteration
        }

        // Print the proximity data to the console
        printf("Proximity: %d\n", data);

        // Delay for 500ms
        gpioDelay(500);
    }

    // The program should never reach here due to the infinite loop
    return 0;
}

