#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4A
#define DISTANCE_REG 0x00
#define DISTANCE_REG_LEN 2

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;

void sigint_handler(int sig) {
    keep_running = 0;
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500000000; // 500ms

    // Register signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Verify sensor presence by reading distance register
    unsigned char buffer[DISTANCE_REG_LEN];
    if (read(i2c_fd, buffer, DISTANCE_REG_LEN) != DISTANCE_REG_LEN) {
        fprintf(stderr, "Error reading distance register: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Read distance data
    if (read(i2c_fd, buffer, DISTANCE_REG_LEN) != DISTANCE_REG_LEN) {
        fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
    } else {
        int distance = (buffer[0] << 8) | buffer[1];
        printf("Distance: %d mm\n", distance);
    }

    // Main loop
    while (keep_running) {
        if (read(i2c_fd, buffer, DISTANCE_REG_LEN) != DISTANCE_REG_LEN) {
            fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
        } else {
            int distance = (buffer[0] << 8) | buffer[1];
            printf("Distance: %d mm\n", distance);
        }
        nanosleep(&sleep_time, NULL);
    }

    // Close I2C bus
    close(i2c_fd);
    return 0;
}

