#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 200000      // 200ms timeout in microseconds
#define MIN_PULSE_DURATION 0.0  // Minimum pulse duration in seconds
#define MAX_PULSE_DURATION 0.038 // Maximum pulse duration in seconds (38ms)

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration
long measurePulseDuration() {
    long start_tick, end_tick, pulse_duration;

    // Wait for echo pin to go high (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every microsecond
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse start timeout\n");
        return -1; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for echo pin to go low (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every microsecond
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse end timeout\n");
        return -1; // Timeout error
    }

    end_tick = gpioTick();

    pulse_duration = end_tick - start_tick;

    if (pulse_duration < 0) {
        // Handle tick counter wrapping
        pulse_duration += 0xFFFFFFFF; // Add the maximum tick value
    }

    return pulse_duration;
}

// Function to calculate distance in centimeters
double calculateDistance(long pulse_duration) {
    return (double)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the pulse duration
        long pulse_duration = measurePulseDuration();

        // Check for errors during pulse measurement
        if (pulse_duration < 0) {
            fprintf(stderr, "Error: Pulse measurement failed\n");
            gpioDelay(1000); // Wait 1 second before next attempt
            continue;
        }

        // Validate pulse duration
        if (pulse_duration <= 0 || (double)pulse_duration / 1000000.0 > MAX_PULSE_DURATION) {
            fprintf(stderr, "Error: Invalid pulse duration: %ld us\n", pulse_duration);
            gpioDelay(1000); // Wait 1 second before next attempt
            continue;
        }

        // Calculate the distance
        double distance = calculateDistance(pulse_duration);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log the distance with timestamp
        printf("%s Distance: %.2f cm\n", timestamp, distance);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

