// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 1.0 // meters
#define ALERT_DURATION 2 // seconds
#define LOG_FILE "intrusion_log.csv"

// Global variables
int uart_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for UART configuration
typedef struct {
    int baud_rate;
    char *device;
} uart_config_t;

// Function prototypes
int uart_init(const uart_config_t *config);
int uart_read_frame(int fd, unsigned char *frame, size_t frame_size);
int decode_range_profile(const unsigned char *frame, float *range_profile);
int check_distance_threshold(const float *range_profile, int num_bins, float threshold);
int log_intrusion(float distance);
int activate_alert(int gpio_pin, int duration_seconds);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// UART initialization function
int uart_init(const uart_config_t *config) {
    uart_fd = open(config->device, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(uart_fd);
        return -1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN]  = 0;            // read doesn't block
    tty.c_cc[VTIME] = 5;            // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);// ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD);      // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (cfsetospeed(&tty, config->baud_rate) != 0 || cfsetispeed(&tty, config->baud_rate) != 0) {
        perror("Error setting baud rate");
        close(uart_fd);
        return -1;
    }

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(uart_fd);
        return -1;
    }

    return 0;
}

// UART read frame function
int uart_read_frame(int fd, unsigned char *frame, size_t frame_size) {
    ssize_t bytes_read = read(fd, frame, frame_size);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read != frame_size) {
        fprintf(stderr, "Warning: Read %zd bytes, expected %zu\n", bytes_read, frame_size);
        return -1; // Indicate incomplete read
    }
    return 0;
}

// Range profile decoding function
int decode_range_profile(const unsigned char *frame, float *range_profile) {
    // Magic word check (assuming little-endian)
    if (frame[0] != 0x02 || frame[1] != 0x01 || frame[2] != 0x04 || frame[3] != 0x03 ||
        frame[4] != 0x06 || frame[5] != 0x05 || frame[6] != 0x08 || frame[7] != 0x07) {
        fprintf(stderr, "Error: Invalid magic word\n");
        return -1;
    }

    // Extract distance bins (assuming little-endian)
    for (int i = 0; i < 64; i++) {
        unsigned short distance = (frame[8 + 2 * i] << 8) | frame[9 + 2 * i];
        range_profile[i] = (float)distance / 100.0; // Convert to meters (example scaling)
    }
    return 0;
}

// Distance threshold check function
int check_distance_threshold(const float *range_profile, int num_bins, float threshold) {
    for (int i = 0; i < num_bins; i++) {
        if (range_profile[i] <= threshold) {
            return 1; // Target detected
        }
    }
    return 0; // No target detected
}

// Intrusion logging function
int log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fclose(log_file);
    return 0;
}

// Alert activation function
int activate_alert(int gpio_pin, int duration_seconds) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(duration_seconds * 1000000); // Delay for specified seconds
    gpioWrite(gpio_pin, 0); // Turn LED off
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_PIN, 0); // Ensure LED is off
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT); // Set GPIO pin as output

    // Configure UART
    uart_config_t uart_config = {
        .baud_rate = BAUD_RATE,
        .device = UART_DEVICE
    };

    if (uart_init(&uart_config) != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char frame[128];
    float range_profile[64];

    printf("Starting intrusion detection...\n");

    while (!terminate) {
        // Read frame from UART
        if (uart_read_frame(uart_fd, frame, sizeof(frame)) == 0) {
            // Decode range profile
            if (decode_range_profile(frame, range_profile) == 0) {
                // Check distance threshold
                if (check_distance_threshold(range_profile, 64, DISTANCE_THRESHOLD)) {
                    printf("Target detected within %.2f meters!\n", DISTANCE_THRESHOLD);

                    // Log intrusion
                    if (log_intrusion(DISTANCE_THRESHOLD) != 0) {
                        fprintf(stderr, "Error logging intrusion\n");
                    }

                    // Activate alert
                    if (activate_alert(GPIO_PIN, ALERT_DURATION) != 0) {
                        fprintf(stderr, "Error activating alert\n");
                    }
                }
            }
        } else {
            fprintf(stderr, "Error reading frame, retrying...\n");
        }

        gpioDelay(10000); // Delay 10ms to avoid busy-waiting
    }

    cleanup();
    return 0;
}

