#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define CH201_ADDR 0x70
#define LED_GPIO 18
#define DISTANCE_REG 0x00 // Example register, adjust as needed
#define BLINK_FREQ_REG 0x01 // Example register, adjust as needed
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000 // 10ms

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(uint16_t *distance);
int set_blink_frequency(uint8_t frequency);
void blink_led(int frequency);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from sensor
int read_distance(uint16_t *distance) {
    char buf[2];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
        if (result == 2) {
            *distance = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_US);
            retries++;
        }
    }
    fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Set blink frequency
int set_blink_frequency(uint8_t frequency) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(i2c_handle, BLINK_FREQ_REG, frequency);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_US);
            retries++;
        }
    }
    fprintf(stderr, "Failed to set blink frequency after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Blink LED
void blink_led(int frequency) {
    if (frequency > 0) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
        gpioDelay(500000 / frequency); // Half cycle
        gpioWrite(LED_GPIO, 0); // Turn LED off
        gpioDelay(500000 / frequency); // Half cycle
    } else {
        gpioWrite(LED_GPIO, 0); // Ensure LED is off if frequency is 0
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        uint16_t distance;
        if (read_distance(&distance) == 0) {
            // Calculate blink frequency (example mapping)
            int frequency = 1000; // Default frequency
            if (distance > 0 && distance <= 200) {
                frequency = 1000 - (int)((float)distance / 200.0 * 900.0); // Inverse relationship
                if (frequency < 100) frequency = 100; // Clamp minimum frequency
            }

            // Set blink frequency
            if (set_blink_frequency((uint8_t)frequency) != 0) {
                fprintf(stderr, "Failed to set blink frequency.\n");
            }

            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log data
            printf("%s, Distance: %d mm, Frequency: %d Hz\n", timestamp, distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

