                        fprintf(stderr, "Error logging data, retrying...\n");
                    }
                } else {
                    fprintf(stderr, "Error reading distance, retrying...\n");
                }
            } else {
                fprintf(stderr, "Error triggering measurement, retrying...\n");
            }

            retry++;
            gpioDelay(RETRY_DELAY_MS); // Exponential backoff
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Max retries reached, skipping this sample.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Sample interval
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

