#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 27

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Log file name
#define LOG_FILE "proximity_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
void log_event(int sensor_id, const char *event_type);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log the event to the file
void log_event(int sensor_id, const char *event_type) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d, %s\n", buf, sensor_id, event_type);
        fflush(log_file); // Ensure data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int sensor1_state = 0;
    int sensor2_state = 0;
    int sensor1_last_state = 0;
    int sensor2_last_state = 0;

    // Main loop
    while (program_running) {
        // Read sensor 1
        int sensor1_new_state = read_sensor(SENSOR_1_PIN);

        if (sensor1_new_state != sensor1_last_state) {
            if (sensor1_new_state == 0) { // Obstacle detected (LOW to LOW)
                log_event(1, "DETECTED");
            } else { // Obstacle cleared (HIGH to HIGH)
                log_event(1, "CLEARED");
            }
            sensor1_last_state = sensor1_new_state;
        }

        // Read sensor 2
        int sensor2_new_state = read_sensor(SENSOR_2_PIN);

        if (sensor2_new_state != sensor2_last_state) {
            if (sensor2_new_state == 0) { // Obstacle detected (LOW to LOW)
                log_event(2, "DETECTED");
            } else { // Obstacle cleared (HIGH to HIGH)
                log_event(2, "CLEARED");
            }
            sensor2_last_state = sensor2_new_state;
        }

        gpioDelay(10); // Poll every 10ms
    }

    // Clean up resources before exiting
    fclose(log_file);
    gpioTerminate();

    return 0;
}

