#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define CH101_ADDR 0x70
#define MEAS_STATUS_REG 0x00
#define DISTANCE_REG 0x01
#define CSV_FILE "distance_log.csv"
#define SAMPLE_INTERVAL_MS 500

volatile sig_atomic_t keep_running = 1;
int i2c_fd = -1;
FILE *csv_file = NULL;

void signal_handler(int sig) {
    keep_running = 0;
    fprintf(stderr, "Signal received, exiting...\n");
}

int i2c_write(int fd, unsigned char reg, unsigned char value) {
    unsigned char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read(int fd, unsigned char reg, unsigned char *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (address) failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main() {
    struct timespec ts;
    char timestamp[30];
    unsigned char status, distance_msb, distance_lsb;
    int distance_mm;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Poll MEAS_STATUS register
        if (i2c_read(i2c_fd, MEAS_STATUS_REG, &status) == 0) {
            if ((status & 0x01) == 0) { // Check if measurement is ready
                // Read distance data
                if (i2c_read(i2c_fd, DISTANCE_REG, &distance_msb) == 0) {
                    if (i2c_read(i2c_fd, DISTANCE_REG + 1, &distance_lsb) == 0) {
                        distance_mm = (distance_msb << 8) | distance_lsb;

                        // Get timestamp
                        if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%03ldZ", localtime(&ts.tv_sec));
                            fprintf(csv_file, "%s,%d\n", timestamp, distance_mm);
                            fflush(csv_file);
                        } else {
                            fprintf(stderr, "Failed to get timestamp: %s\n", strerror(errno));
                        }
                    } else {
                        fprintf(stderr, "Failed to read distance LSB\n");
                    }
                } else {
                    fprintf(stderr, "Failed to read distance MSB\n");
                }
            } else {
                //fprintf(stderr, "Measurement not ready\n");
            }
        } else {
            fprintf(stderr, "Failed to read MEAS_STATUS register\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Wait before next sample
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fflush(csv_file);
        fclose(csv_file);
    }

    return 0;
}

