// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100 // mm
#define BUZZER_DURATION 200    // ms

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void control_buzzer(int distance);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_MODE 0x0011
#define VL53L1X_REG_START_STOP 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to write a byte to a VL53L1X register
int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02x\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02x\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%02x\n", reg);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure buzzer GPIO
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    int distance;
    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            control_buzzer(distance);
        } else {
            fprintf(stderr, "Failed to read distance. Skipping iteration.\n");
        }
        gpioDelay(500000); // 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    uint8_t model_id;

    // Check sensor ID (example)
    if (read_register(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }
    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02x\n", model_id);
        return -1;
    }

    // Set continuous ranging mode
    if (write_register(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x02) != 0) {
        fprintf(stderr, "Error setting ranging mode\n");
        return -1;
    }

    // Start continuous ranging
    if (write_register(i2c_handle, VL53L1X_REG_START_STOP, 0x04) != 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    uint8_t range_status;
    uint8_t buffer[2];

    // Read range status
    if (read_register(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Read distance (2 bytes)
    if (read_register(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &buffer[0]) != 0) {
        fprintf(stderr, "Error reading distance MSB\n");
        return -1;
    }
    if (read_register(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, &buffer[1]) != 0) {
        fprintf(stderr, "Error reading distance LSB\n");
        return -1;
    }

    *distance = (buffer[0] << 8) | buffer[1];

    return 0;
}

// Control buzzer based on distance
void control_buzzer(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_GPIO, 1); // Turn on buzzer
        gpioDelay(BUZZER_DURATION * 1000); // Delay for buzzer duration
        gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

