#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_MS 50
#define MIN_DISTANCE 2.0      // Minimum measurable distance (cm)
#define MAX_DISTANCE 400.0    // Maximum measurable distance (cm)
#define MIN_ANGLE -90.0       // Minimum servo angle (degrees)
#define MAX_ANGLE 90.0        // Maximum servo angle (degrees)

// Global variables
FILE *log_file;
int running = 1;

// Function prototypes
void triggerSensor();
long pulseIn(int pin, int level, int timeout);
float calculateDistance(long pulse_duration);
int mapDistanceToAngle(float distance);
void setServoAngle(int angle);
void logData(float distance);
void signalHandler(int signal);

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse duration on the echo pin
long pulseIn(int pin, int level, int timeout) {
    long start = gpioTick();
    long end = start;
    long diff;

    // Wait for the pulse to start
    while (gpioRead(pin) != level) {
        end = gpioTick();
        diff = end - start;
        if (diff > timeout) {
            return -1; // Timeout
        }
    }

    start = gpioTick();

    // Wait for the pulse to end
    while (gpioRead(pin) == level) {
        end = gpioTick();
        diff = end - start;
        if (diff > timeout) {
            return -1; // Timeout
        }
    }

    end = gpioTick();
    diff = end - start;
    return diff;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_duration) {
    if (pulse_duration < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to map the distance to a servo angle
int mapDistanceToAngle(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return (int)(((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * (MAX_ANGLE - MIN_ANGLE) - MAX_ANGLE);
    }
}

// Function to set the servo angle
void setServoAngle(int angle) {
    gpioServo(SERVO_PIN, angle * 1000 / 180 + 500); // Convert angle to pulse width (500-2500)
}

// Function to log the distance data to a file
void logData(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler function
void signalHandler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Initialize log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (running) {
        triggerSensor();
        long pulse_duration = pulseIn(ECHO_PIN, 1, TIMEOUT_MS * 1000); // Timeout in microseconds

        if (pulse_duration > 0) {
            float distance = calculateDistance(pulse_duration);
            if (distance > 0) {
                int angle = mapDistanceToAngle(distance);
                setServoAngle(angle);
                logData(distance);
                printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
            } else {
                fprintf(stderr, "Error: Invalid distance reading\n");
            }
        } else {
            fprintf(stderr, "Error: Sensor timeout\n");
        }

        gpioDelay(200); // Wait 200 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

