#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 50000      // 50ms timeout
#define MIN_DISTANCE 2       // cm
#define MAX_DISTANCE 400     // cm
#define BUZZER_THRESHOLD 30   // cm

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t start, uint32_t end);
void activate_buzzer();
void deactivate_buzzer();
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
  gpioWrite(TRIGGER_PIN, 1);
  gpioDelay(10);
  gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, uint32_t tick) {
  if (level == 1) {
    start_tick = tick;
    echo_received = 1;
  } else if (level == 0) {
    end_tick = tick;
    echo_received = 2;
  }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t start, uint32_t end) {
  uint32_t diff = end - start;
  if (diff > 0x7FFFFFFF) {
    diff -= 0xFFFFFFFF + 1; // Handle tick wraparound
  }
  double time_taken = (double)diff / 1000000.0; // in seconds
  double distance = (time_taken * SPEED_OF_SOUND) / 2.0;
  return distance;
}

// Function to activate the buzzer
void activate_buzzer() {
  gpioWrite(BUZZER_PIN, 1);
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
  gpioWrite(BUZZER_PIN, 0);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
  printf("\nCaught signal %d, cleaning up...\n", signal);
  running = 0;
  deactivate_buzzer();
  gpioTerminate();
  exit(0);
}

int main() {
  // Initialize pigpio library
  if (gpioInitialise() < 0) {
    fprintf(stderr, "pigpio initialisation failed\n");
    return 1;
  }

  // Set GPIO modes
  gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
  gpioSetMode(ECHO_PIN, PI_INPUT);
  gpioSetMode(BUZZER_PIN, PI_OUTPUT);

  // Register signal handler for Ctrl+C
  signal(SIGINT, signal_handler);

  // Register interrupt handler for echo pin
  if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
    fprintf(stderr, "Failed to set alert function\n");
    gpioTerminate();
    return 1;
  }

  printf("Parking sensor started. Press Ctrl+C to exit.\n");

  while (running) {
    // Trigger the sensor
    trigger_pulse();

    // Wait for echo or timeout
    echo_received = 0;
    uint32_t start = gpioTick();
    while (echo_received < 2 && (gpioTick() - start) < TIMEOUT_US) {
      gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (echo_received == 2) {
      // Calculate distance
      double distance = calculate_distance(start_tick, end_tick);

      // Validate distance
      if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
        printf("Distance: %.2f cm\n", distance);

        // Activate buzzer if distance is less than threshold
        if (distance < BUZZER_THRESHOLD) {
          activate_buzzer();
        } else {
          deactivate_buzzer();
        }
      } else {
        fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
      }
    } else {
      fprintf(stderr, "Timeout or no echo received\n");
    }

    gpioDelay(100); // Delay 100ms
  }

  // Cleanup (should not reach here if signal handler works)
  deactivate_buzzer();
  gpioTerminate();

  return 0;
}

