// Function to log events with timestamps
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_event("Signal received, shutting down...");
    terminate = 1;
}

// Callback function to force the gate open
void force_open_callback() {
    log_event("Remote command: Force open");
    servo_open();
}

// Callback function to force the gate close
void force_close_callback() {
    log_event("Remote command: Force close");
    servo_close();
}

