// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define MOTOR_FORWARD 17
#define MOTOR_BACKWARD 18
#define DISTANCE_THRESHOLD_LOW 100
#define DISTANCE_THRESHOLD_HIGH 300
#define GPIO_INTERRUPT 24
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile int running = 1;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void motor_forward();
void motor_backward();
void motor_stop();
void distance_isr(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x00
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x1E

// Function to initialize the VL53L1X sensor
int vl53l1x_init() {
    int retries = 0;
    int status;

    // Soft reset
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, 0x00, 0x00); // Soft reset command
        if (status >= 0) break;
        fprintf(stderr, "Error resetting VL53L1X (attempt %d): %d\n", retries + 1, status);
        gpioDelay(1000); // 1ms delay
        retries++;
    }
    if (retries == MAX_RETRIES) return -1;

    gpioDelay(1000); // Wait for reset to complete

    // Start continuous ranging
    retries = 0;
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01); // Start continuous ranging
        if (status >= 0) break;
        fprintf(stderr, "Error starting ranging (attempt %d): %d\n", retries + 1, status);
        gpioDelay(1000); // 1ms delay
        retries++;
    }
    if (retries == MAX_RETRIES) return -1;

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int vl53l1x_read_distance() {
    int retries = 0;
    int status;
    unsigned char data[2];

    while (retries < MAX_RETRIES) {
        status = i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, (char *)data, 2);
        if (status >= 0) break;
        fprintf(stderr, "Error reading distance (attempt %d): %d\n", retries + 1, status);
        gpioDelay(1000); // 1ms delay
        retries++;
    }
    if (retries == MAX_RETRIES) return -1;

    return (data[0] << 8) | data[1];
}

// Function to control the motor forward
void motor_forward() {
    gpioWrite(MOTOR_FORWARD, 1);
    gpioWrite(MOTOR_BACKWARD, 0);
    printf("Motor: Forward\n");
}

// Function to control the motor backward
void motor_backward() {
    gpioWrite(MOTOR_FORWARD, 0);
    gpioWrite(MOTOR_BACKWARD, 1);
    printf("Motor: Backward\n");
}

// Function to stop the motor
void motor_stop() {
    gpioWrite(MOTOR_FORWARD, 0);
    gpioWrite(MOTOR_BACKWARD, 0);
    printf("Motor: Stop\n");
}

// Interrupt service routine for distance measurement
void distance_isr(int gpio, int level, uint32_t tick, void *user) {
    if (level == 1) { // Rising edge
        int distance = vl53l1x_read_distance();
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
            if (distance < DISTANCE_THRESHOLD_LOW) {
                motor_forward();
            } else if (distance > DISTANCE_THRESHOLD_HIGH) {
                motor_backward();
            } else {
                motor_stop();
            }
        } else {
            fprintf(stderr, "Error reading distance in ISR\n");
            motor_stop();
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD, PI_OUTPUT);
    gpioSetMode(GPIO_INTERRUPT, PI_INPUT);
    gpioSetPullUpDown(GPIO_INTERRUPT, PI_PUD_DOWN); // Optional: Pull-down resistor

    // Set up interrupt service routine
    if (gpioSetISRFuncEx(GPIO_INTERRUPT, RISING_EDGE, 0, distance_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Program running. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep for 100ms
    }

    // Cleanup
    motor_stop();
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

