    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Set Electrode Configuration
        fprintf(stderr, "Error: Failed to write to MPR121 register 0x5E\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5F, 0x01) < 0) { // Set Electrode Configuration
        fprintf(stderr, "Error: Failed to write to MPR121 register 0x5F\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x05) < 0) { // Set Touch Threshold
        fprintf(stderr, "Error: Failed to write to MPR121 register 0x2B\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x05) < 0) { // Set Release Threshold
        fprintf(stderr, "Error: Failed to write to MPR121 register 0x2C\n");
        return -1;
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) { // Enable Electrode 0
        fprintf(stderr, "Error: Failed to write to MPR121 register 0x5B\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x01) < 0) { // Enable Electrode 1
        fprintf(stderr, "Error: Failed to write to MPR121 register 0x5C\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) { // Enable Electrode 2
        fprintf(stderr, "Error: Failed to write to MPR121 register 0x5D\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x01) < 0) { // Enable Electrode 3
