    int result = wiringPiI2CWriteReg8(fd, reg, value);
    if (result == -1) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to configure the MPR121
int mpr121_configure(int fd) {
    // Reset the MPR121
    if (mpr121_write_register(fd, 0x80, 0x63) == -1) return -1;
    delay(100); // Wait for reset to complete

    // Configure Electrode Filtering
    if (mpr121_write_register(fd, 0x2B, 0x01) == -1) return -1; // FFI
    if (mpr121_write_register(fd, 0x2C, 0x01) == -1) return -1; // SFI
    if (mpr121_write_register(fd, 0x2D, 0x01) == -1) return -1; // ESI

    // Configure Debounce
    if (mpr121_write_register(fd, 0x5B, 0x10) == -1) return -1; // Touch debounce
    if (mpr121_write_register(fd, 0x5C, 0x10) == -1) return -1; // Release debounce

    // Configure AFE
    if (mpr121_write_register(fd, 0x5E, 0x0C) == -1) return -1; // Set Electrode sensitivity

    // Configure Baseline Filtering
    if (mpr121_write_register(fd, 0x2E, 0x01) == -1) return -1; // Enable baseline filtering
    if (mpr121_write_register(fd, 0x2F, 0x01) == -1) return -1; // Set baseline filter period

    // Enable all electrodes
    if (mpr121_write_register(fd, 0x5D, 0x24) == -1) return -1; // Enable electrode 0, 1, 2, 3

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status(int fd) {
    int touch_status = mpr121_read_register(fd, 0x00);
    if (touch_status == -1) return -1;
    return touch_status;
}

// Function to handle a proximity event
void proximity_event_handler(int touch_status) {
    if (touch_status > PROXIMITY_THRESHOLD) {
        led_on(LED_PIN);
        delay(PROXIMITY_DURATION_MS);
        led_off(LED_PIN);
        log_proximity_event(touch_status);
    }
}

// Function to turn the LED on
void led_on(int pin) {
    digitalWrite(pin, HIGH);
}

// Function to turn the LED off
void led_off(int pin) {
    digitalWrite(pin, LOW);
}

// Function to log a proximity event
void log_proximity_event(int touch_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Proximity event detected: Touch status = 0x%02X\n", timestamp, touch_status);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = false;
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_I2C_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "I2C initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Verify MPR121 device ID
    int device_id = mpr121_read_register(i2c_fd, 0x5E);
    if (device_id != 0x5A) {
        fprintf(stderr, "Error: Invalid device ID 0x%02X. Expected 0x5A.\n", device_id);
        return 1;
    }
    printf("MPR121 device ID: 0x%02X\n", device_id);

    // Configure MPR121
    if (mpr121_configure(i2c_fd) == -1) {
        fprintf(stderr, "MPR121 configuration failed.\n");
        return 1;
    }

    // Set LED pin as output
    pinMode(LED_PIN, OUTPUT);
    led_off(LED_PIN); // Ensure LED is off initially

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int touch_status = mpr121_read_touch_status(i2c_fd);
        if (touch_status != -1) {
            proximity_event_handler(touch_status);
        } else {
            fprintf(stderr, "Error reading touch status.\n");
        }
        delay(DEBOUNCE_DELAY_MS);
    }

    // Cleanup
    led_off(LED_PIN);
    fclose(log_file);

    return 0;
}

