#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define TIMEOUT_US 30000       // 30ms timeout in microseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int trigger_sensor();
long measure_pulse_width();
double calculate_distance(long pulse_width);
void log_distance(double distance);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        running = 0;
    }
}

// Function to trigger the ultrasonic sensor
int trigger_sensor() {
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to set trigger pin low.\n");
        return -1;
    }
    gpioDelay(5); // 5us delay
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: Failed to set trigger pin high.\n");
        return -1;
    }
    gpioDelay(10); // 10us delay
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to set trigger pin low.\n");
        return -1;
    }
    return 0;
}

// Function to measure the pulse width of the echo signal
long measure_pulse_width() {
    long start_tick, end_tick, pulse_width;

    // Wait for echo pin to go high (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal timeout (rising edge).\n");
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for echo pin to go low (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal timeout (falling edge).\n");
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF; // Handle tick rollover
    }

    return pulse_width;
}

// Function to calculate the distance in centimeters
double calculate_distance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log the distance to a file
void log_distance(double distance) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file); // Flush the buffer to ensure data is written
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set trigger pin as output.\n");
        cleanup();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set echo pin as input.\n");
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        cleanup();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (trigger_sensor() == 0) {
            long pulse_width = measure_pulse_width();
            if (pulse_width > 0) {
                double distance = calculate_distance(pulse_width);

                if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                    log_distance(distance);
                } else {
                    fprintf(stderr, "Error: Distance out of range: %.2f cm\n", distance);
                    time_t now = time(NULL);
                    struct tm *t = gmtime(&now);
                    char timestamp[32];
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
                    fprintf(log_file, "%s, ERROR: Distance out of range: %.2f cm\n", timestamp, distance);
                    fflush(log_file);
                }
            } else {
                fprintf(stderr, "Error: Pulse width measurement failed.\n");
                time_t now = time(NULL);
                struct tm *t = gmtime(&now);
                char timestamp[32];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
                fprintf(log_file, "%s, ERROR: Pulse width measurement failed.\n", timestamp);
                fflush(log_file);
            }
        } else {
            fprintf(stderr, "Error: Trigger sensor failed.\n");
            time_t now = time(NULL);
            struct tm *t = gmtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
            fprintf(log_file, "%s, ERROR: Trigger sensor failed.\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

