#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 1.0       // Minimum measurable distance in cm
#define MAX_DISTANCE 400.0     // Maximum measurable distance in cm
#define MIN_PULSE_WIDTH 58.0    // Minimum pulse width in us (1cm)
#define MAX_PULSE_WIDTH 25000.0 // Maximum pulse width in us (4m)
#define TRIGGER_PULSE_WIDTH 10  // Trigger pulse width in us

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_valid = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width);
void log_data(double distance);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
  gpioWrite(TRIG_PIN, 1);
  gpioDelay(TRIGGER_PULSE_WIDTH);
  gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
  if (level == 1) {
    echo_start_tick = tick;
    echo_valid = 0; // Reset valid flag on rising edge
  } else if (level == 0) {
    echo_end_tick = tick;

    // Calculate pulse width
    int pulse_width = echo_end_tick - echo_start_tick;
    if (pulse_width < 0) {
      pulse_width += 0xFFFFFFFF; // Handle tick wrap-around
    }

    // Validate pulse width
    if (pulse_width > 0 && pulse_width >= MIN_PULSE_WIDTH && pulse_width <= MAX_PULSE_WIDTH) {
      echo_valid = 1; // Set valid flag if pulse width is valid
    } else {
      echo_valid = 0; // Reset valid flag if pulse width is invalid
    }
  }
}

// Function to calculate distance in meters
double calculate_distance(int pulse_width) {
  return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Function to log data to file
void log_data(double distance) {
  time_t rawtime;
  struct tm *timeinfo;
  char timestamp[80];

  time(&rawtime);
  timeinfo = localtime(&rawtime);

  strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

  fprintf(log_file, "%s,%.2f\n", timestamp, distance);
  fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
  printf("Caught signal %d, exiting gracefully...\n", signal);
  running = 0;
}

int main() {
  // Initialize pigpio library
  if (gpioInitialise() < 0) {
    fprintf(stderr, "pigpio initialisation failed\n");
    return 1;
  }

  // Set GPIO modes
  gpioSetMode(TRIG_PIN, PI_OUTPUT);
  gpioSetMode(ECHO_PIN, PI_INPUT);

  // Set pull-down resistor on ECHO pin
  gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

  // Open log file
  log_file = fopen("distance_log.txt", "a");
  if (log_file == NULL) {
    fprintf(stderr, "Error opening log file!\n");
    gpioTerminate();
    return 1;
  }

  // Register signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Set ISR callback function
  gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL);

  printf("Distance measurement started. Press Ctrl+C to exit.\n");

  // Main loop
  while (running) {
    trigger_pulse();
    gpioDelay(1000000); // Wait 1 second

    if (echo_valid) {
      int pulse_width = echo_end_tick - echo_start_tick;
      if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF; // Handle tick wrap-around
      }

      double distance = calculate_distance(pulse_width);
      log_data(distance);
      printf("Distance: %.2f m\n", distance);
    } else {
      printf("Invalid pulse width!\n");
    }
  }

  // Disable ISR
  gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);

  // Close log file
  fclose(log_file);

  // Terminate pigpio library
  gpioTerminate();

  printf("Program terminated.\n");
  return 0;
}

