// Function to write a byte to a VL53L1X register
int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        return -1; // Error
    }
    return 0; // Success
}

// Function to read a byte from a VL53L1X register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cWriteDevice(handle, &reg, 1);
    if (result != 0) {
        return -1; // Error writing register address
    }
    result = i2cReadDevice(handle, value, 1);
    if (result != 0) {
        return -1; // Error reading register value
    }
    return 0; // Success
}

