#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define DISTANCE_MIN 2.0
#define DISTANCE_MAX 400.0
#define MOVING_AVG_SIZE 5
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_CENTER_ANGLE 90.0
#define SERVO_RANGE 180.0
#define SERVO_MIN_ANGLE 0.0
#define SERVO_MAX_ANGLE 180.0
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000         // 30ms timeout

// Global variables
volatile sig_atomic_t terminate = 0;
volatile int new_pulse = 0;
volatile unsigned int pulse_width = 0;
double distance_history[MOVING_AVG_SIZE];
int history_index = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_distance(unsigned int pulse_width);
double moving_average(double new_value);
double map_distance_to_angle(double distance);
int set_servo_angle(double angle);
int log_data(double distance, double angle);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
  gpioWrite(TRIGGER_PIN, 1);
  gpioDelay(10);
  gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
  static uint32_t start_tick = 0;
  if (level == 1) {
    start_tick = tick;
  } else if (level == 0) {
    uint32_t end_tick = tick;
    uint32_t diff = end_tick - start_tick;

    // Handle tick counter wrap-around
    if (end_tick < start_tick) {
      diff = (0xFFFFFFFF - start_tick) + end_tick + 1;
    }

    if (diff > TIMEOUT_US) {
      pulse_width = 0; // Indicate timeout
    } else {
      pulse_width = diff;
    }
    new_pulse = 1; // Set the flag
  }
}

// Function to calculate distance from pulse width
double calculate_distance(unsigned int pulse_width) {
  if (pulse_width == 0) return -1.0; // Indicate timeout
  return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // in cm
}

// Function to calculate moving average
double moving_average(double new_value) {
  distance_history[history_index] = new_value;
  history_index = (history_index + 1) % MOVING_AVG_SIZE;

  double sum = 0.0;
  for (int i = 0; i < MOVING_AVG_SIZE; i++) {
    sum += distance_history[i];
  }
  return sum / MOVING_AVG_SIZE;
}

// Function to map distance to servo angle
double map_distance_to_angle(double distance) {
  if (distance < DISTANCE_MIN) {
    return SERVO_MIN_ANGLE;
  } else if (distance > DISTANCE_MAX) {
    return SERVO_MAX_ANGLE;
  } else {
    return (distance - DISTANCE_MIN) / (DISTANCE_MAX - DISTANCE_MIN) * SERVO_RANGE + SERVO_MIN_ANGLE;
  }
}

// Function to set servo angle
int set_servo_angle(double angle) {
  if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
    fprintf(stderr, "Error: Angle out of range (%f)\n", angle);
    return -1;
  }

  int pulse_width = (int)((angle / SERVO_RANGE) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH);
  gpioServo(SERVO_PIN, pulse_width);
  return 0;
}

// Function to log data to file
int log_data(double distance, double angle) {
  FILE *fp = fopen("distance_log.csv", "a");
  if (fp == NULL) {
    perror("Error opening file");
    return -1;
  }

  time_t t = time(NULL);
  struct tm tm = *localtime(&t);
  fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, distance, angle);

  fflush(fp);
  fclose(fp);
  return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
  terminate = 1;
  printf("Caught signal %d, terminating...\n", signal);
}

int main() {
  // Initialize pigpio
  if (gpioInitialise() < 0) {
    fprintf(stderr, "pigpio initialisation failed\n");
    return 1;
  }

  // Set GPIO modes
  gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
  gpioSetMode(ECHO_PIN, PI_INPUT);
  gpioSetMode(SERVO_PIN, PI_OUTPUT);

  // Initialize distance history
  for (int i = 0; i < MOVING_AVG_SIZE; i++) {
    distance_history[i] = DISTANCE_MAX; // Initialize with max distance
  }

  // Set up signal handler
  signal(SIGINT, signal_handler);

  // Set up alert function for echo pin
  if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
    fprintf(stderr, "Error setting alert function\n");
    gpioTerminate();
    return 1;
  }

  // Main loop
  while (!terminate) {
    // Trigger the sensor
    trigger_pulse();

    // Wait for a short period
    gpioDelay(100); // 100ms

    // Check for new pulse
    if (new_pulse) {
      // Read pulse width
      unsigned int current_pulse_width = pulse_width;
      pulse_width = 0; // Clear for next pulse
      new_pulse = 0;   // Clear the flag

      // Calculate distance
      double distance = calculate_distance(current_pulse_width);

      // Validate distance
      if (distance < DISTANCE_MIN || distance > DISTANCE_MAX) {
        distance = -1.0; // Indicate invalid reading
      }

      // Calculate moving average
      double filtered_distance = moving_average(distance);

      // Map distance to angle
      double angle = map_distance_to_angle(filtered_distance);

      // Set servo angle
      if (set_servo_angle(angle) != 0) {
        fprintf(stderr, "Error setting servo angle\n");
      }

      // Log data
      if (log_data(filtered_distance, angle) != 0) {
        fprintf(stderr, "Error logging data\n");
      }
    }

    // Small delay to avoid busy-waiting
    gpioDelay(10);
  }

  // Stop servo
  gpioServo(SERVO_PIN, 0);

  // Close CSV file (handled by log_data, but good practice to include)
  FILE *fp = fopen("distance_log.csv", "a");
  if (fp != NULL) {
    fclose(fp);
  }

  // Terminate pigpio
  gpioTerminate();

  return 0;
}

