#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define GPIO_PIN 27
#define PROXIMITY_REG 0x08
#define INTERRUPT_ENABLE_REG 0x03
#define INTERRUPT_STATUS_REG 0x04
#define LOG_FILE "proximity.log"

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
int threshold = DEFAULT_THRESHOLD;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int address);
int configure_sensor(int handle, int threshold);
int read_proximity(int handle);
int check_threshold(int proximity, int threshold);
void log_data(int proximity, const char *status);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the sensor
int configure_sensor(int handle, int threshold) {
    // Enable interrupt on rising edge
    if (i2cWriteByteData(handle, INTERRUPT_ENABLE_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing to interrupt enable register\n");
        return -1;
    }

    // Set threshold (example, adjust as needed)
    if (i2cWriteByteData(handle, 0x0A, threshold & 0xFF) < 0) { //LSB
        fprintf(stderr, "Error writing to threshold LSB register\n");
        return -1;
    }
    if (i2cWriteByteData(handle, 0x0B, (threshold >> 8) & 0xFF) < 0) { //MSB
        fprintf(stderr, "Error writing to threshold MSB register\n");
        return -1;
    }

    return 0;
}

// Function to read proximity value
int read_proximity(int handle) {
    int proximity = i2cReadWordData(handle, PROXIMITY_REG);
    if (proximity < 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }
    return proximity;
}

// Function to check threshold
int check_threshold(int proximity, int threshold) {
    return (proximity <= threshold) ? 1 : 0;
}

// Function to log data
void log_data(int proximity, const char *status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Proximity: %d, Status: %s\n", timestamp, proximity, status);
    fflush(log_file); // Ensure data is written to file immediately
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    // This function is called when the interrupt occurs.
    // It reads the proximity value and checks the threshold.
    // The actual logging is deferred until the main thread processes the data.
    int proximity = read_proximity(i2c_handle);
    if (proximity >= 0) {
        const char *status = check_threshold(proximity, threshold) ? "SAFE" : "ALERT";
        // Data will be logged in the main thread.
    } else {
        fprintf(stderr, "Error in interrupt handler: Could not read proximity.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0); // Allow hex or decimal
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(i2c_address) != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_handle, threshold) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        cleanup();
        return 1;
    }

    fprintf(stderr, "Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Process any deferred data (if any)
        // In this simple example, we don't have any deferred data.
        // In a real application, this would be where you process the data
        // and log it to the file.

        gpioDelay(100); // Check every 100ms
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Proximity sensor monitoring stopped.\n");
    return 0;
}

