#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24

// Define PWM pin
#define PWM_PIN 18

// Define distance range and frequency range
#define MIN_DISTANCE 2.0  // cm
#define MAX_DISTANCE 200.0 // cm
#define MIN_FREQUENCY 200.0 // Hz
#define MAX_FREQUENCY 2000.0 // Hz

// Define timeout duration
#define TIMEOUT_US 200000 // 200ms

// Global variables
static volatile int running = 1;
static volatile int last_valid_frequency = 0; // Store the last valid frequency

// Function prototypes
void signal_handler(int signal);
double measure_distance();
double map_distance_to_frequency(double distance);
void set_pwm_frequency(int frequency);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup();
    exit(0);
}

// Function to measure distance using HC-SR04
double measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1us
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    double pulse_duration = (double)(end_tick - start_tick);
    double distance = pulse_duration / 58.0; // Speed of sound correction

    return distance;
}

// Function to map distance to frequency using logarithmic scale
double map_distance_to_frequency(double distance) {
    // Clamp distance to the defined range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Map distance to frequency using logarithmic scale
    double frequency = MIN_FREQUENCY * pow(MAX_FREQUENCY / MIN_FREQUENCY, (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE));
    return frequency;
}

// Function to set PWM frequency
void set_pwm_frequency(int frequency) {
    if (frequency <= 0) {
        fprintf(stderr, "Invalid frequency: %d\n", frequency);
        return;
    }

    gpioSetPWMfrequency(PWM_PIN, frequency);
    gpioPWM(PWM_PIN, 128); // 50% duty cycle
}

// Function to clean up resources
void cleanup() {
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();      // Terminate pigpio
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(PWM_PIN, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();

        if (distance > 0) {
            double frequency = map_distance_to_frequency(distance);
            set_pwm_frequency((int)frequency);
            last_valid_frequency = (int)frequency; // Update last valid frequency
        } else {
            // If distance measurement failed, use the last valid frequency
            set_pwm_frequency(last_valid_frequency);
        }

        gpioDelay(50); // Delay between measurements
    }

    return 0;
}

