#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioWrite(TRIGGER_PIN, 0);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);

        uint32_t start_tick = gpioTick();
        uint32_t end_tick = start_tick;

        while (gpioRead(ECHO_PIN) == 0 && (end_tick - start_tick) < 50000) {
            end_tick = gpioTick();
        }

        if ((end_tick - start_tick) >= 50000) {
            printf("Timeout\n");
            continue;
        }

        uint32_t echo_start = end_tick;
        end_tick = echo_start;

        while (gpioRead(ECHO_PIN) == 1 && (end_tick - echo_start) < 50000) {
            end_tick = gpioTick();
        }

        if ((end_tick - echo_start) >= 50000) {
            printf("Timeout\n");
            continue;
