#include <pigpio.h>

// Constants
#define I2C_ADDR 0x60
#define ALS_VIS_REG 0x20
#define LOG_FILE "proximity_log.csv"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_als_visible(uint16_t *als_visible);
int log_data(const char *timestamp, uint16_t als_visible);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x60, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ALS Visible data
int read_als_visible(uint16_t *als_visible) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, ALS_VIS_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ALS Visible data: %d\n", result);
        return -1;
    }
    *als_visible = (buf[1] << 8) | buf[0]; // Combine bytes
    return 0;
}

// Log data to file
int log_data(const char *timestamp, uint16_t als_visible) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
        // Write header if the file is newly created
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "timestamp,als_visible\n");
        }
    }

    fprintf(log_file, "%s,%u\n", timestamp, als_visible);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tstruct);

        uint16_t als_visible;
        if (read_als_visible(&als_visible) == 0) {
            if (log_data(timestamp, als_visible) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

