#define SI1120_ALS_VIS_DATA0 0x22
#define SI1120_PS1_DATA0 0x24
#define SI1120_PART_ID 0x00
#define SI1120_PART_ID_VALUE 0x60

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(unsigned short *als, unsigned short *proximity);
int log_data(unsigned short als, unsigned short proximity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initializes the Si1120 sensor
int initialize_sensor() {
    int retries = 3;
    int status;

    // Reset the sensor
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, SI1120_RESET, 0x00);
        if (status >= 0) break; // Success
        fprintf(stderr, "Error resetting sensor, retrying... (%d retries left)\n", retries - 1);
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to reset sensor after multiple retries.\n");
        return -1;
    }

    // Verify part ID
    retries = 3;
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, SI1120_PART_ID);
        if (status >= 0) {
            if (status == SI1120_PART_ID_VALUE) break; // Success
            fprintf(stderr, "Incorrect part ID: 0x%02X (expected 0x%02X), retrying... (%d retries left)\n", status, SI1120_PART_ID_VALUE, retries - 1);
        } else {
            fprintf(stderr, "Error reading part ID, retrying... (%d retries left)\n", retries - 1);
        }
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to verify part ID after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Reads ALS and proximity data from the sensor
int read_sensor_data(unsigned short *als, unsigned short *proximity) {
    int retries = 3;
    int status;

    // Read ALS data
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, SI1120_ALS_VIS_DATA0);
        if (status >= 0) {
            *als = status;
            break; // Success
        } else {
            fprintf(stderr, "Error reading ALS data, retrying... (%d retries left)\n", retries - 1);
        }
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read ALS data after multiple retries.\n");
        return -1;
    }

    retries = 3;
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, SI1120_ALS_VIS_DATA0 + 1);
        if (status >= 0) {
            *als |= (status << 8);
            break; // Success
        } else {
            fprintf(stderr, "Error reading ALS data (MSB), retrying... (%d retries left)\n", retries - 1);
        }
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read ALS data (MSB) after multiple retries.\n");
        return -1;
    }

    // Read proximity data
    retries = 3;
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, SI1120_PS1_DATA0);
        if (status >= 0) {
            *proximity = status;
            break; // Success
        } else {
            fprintf(stderr, "Error reading proximity data, retrying... (%d retries left)\n", retries - 1);
        }
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read proximity data after multiple retries.\n");
        return -1;
    }

    retries = 3;
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, SI1120_PS1_DATA0 + 1);
        if (status >= 0) {
            *proximity |= (status << 8);
            break; // Success
        } else {
            fprintf(stderr, "Error reading proximity data (MSB), retrying... (%d retries left)\n", retries - 1);
        }
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read proximity data (MSB) after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Logs the data to a file
int log_data(unsigned short als, unsigned short proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %u, Proximity: %u\n", timestamp, als, proximity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    unsigned short als, proximity;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&als, &proximity) == 0) {
            log_data(als, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(500000); // 500ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

