#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_ADDR 0x60
#define PS1_DATA0_REG 0x24
#define PS1_DATA1_REG 0x25
#define LOG_FILE "proximity_log.txt"
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_proximity_data(uint16_t *proximity);
int log_data(uint16_t proximity);
void signal_handler(int signal);

// Function to initialize the Si1145 sensor
int initialize_sensor() {
    int status;
    int retries = RETRY_COUNT;

    // Reset the sensor (example initialization sequence)
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, 0x17, 0x00); // Reset command
        if (status >= 0) break; // Success
        fprintf(stderr, "Error resetting sensor: %d\n", status);
        gpioDelay(1000); // Wait 1ms
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to reset sensor after multiple retries.\n");
        return -1;
    }

    retries = RETRY_COUNT;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, 0x18, 0x7B); // PS1_ADCMUX
        if (status >= 0) break; // Success
        fprintf(stderr, "Error writing PS1_ADCMUX: %d\n", status);
        gpioDelay(1000); // Wait 1ms
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write PS1_ADCMUX after multiple retries.\n");
        return -1;
    }

    retries = RETRY_COUNT;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, 0x19, 0x01); // PS1_ADC_GAIN
        if (status >= 0) break; // Success
        fprintf(stderr, "Error writing PS1_ADC_GAIN: %d\n", status);
        gpioDelay(1000); // Wait 1ms
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write PS1_ADC_GAIN after multiple retries.\n");
        return -1;
    }

    retries = RETRY_COUNT;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, 0x1A, 0x00); // PS1_LED_DUTY
        if (status >= 0) break; // Success
        fprintf(stderr, "Error writing PS1_LED_DUTY: %d\n", status);
        gpioDelay(1000); // Wait 1ms
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write PS1_LED_DUTY after multiple retries.\n");
        return -1;
    }

    retries = RETRY_COUNT;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, 0x1B, 0x01); // PS1_MEAS_RATE
        if (status >= 0) break; // Success
        fprintf(stderr, "Error writing PS1_MEAS_RATE: %d\n", status);
        gpioDelay(1000); // Wait 1ms
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write PS1_MEAS_RATE after multiple retries.\n");
        return -1;
    }

    retries = RETRY_COUNT;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, 0x1C, 0x01); // PS1_ALS_RATE
        if (status >= 0) break; // Success
        fprintf(stderr, "Error writing PS1_ALS_RATE: %d\n", status);
        gpioDelay(1000); // Wait 1ms
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write PS1_ALS_RATE after multiple retries.\n");
        return -1;
    }

    retries = RETRY_COUNT;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, 0x1D, 0x01); // PS1_IOCFG
        if (status >= 0) break; // Success
        fprintf(stderr, "Error writing PS1_IOCFG: %d\n", status);
        gpioDelay(1000); // Wait 1ms
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write PS1_IOCFG after multiple retries.\n");
        return -1;
    }

    retries = RETRY_COUNT;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, 0x1E, 0x01); // PS1_HW_KEY
        if (status >= 0) break; // Success
        fprintf(stderr, "Error writing PS1_HW_KEY: %d\n", status);
        gpioDelay(1000); // Wait 1ms
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write PS1_HW_KEY after multiple retries.\n");
        return -1;
    }

    retries = RETRY_COUNT;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, 0x07, 0x01); // Enable PS1
        if (status >= 0) break; // Success
        fprintf(stderr, "Error enabling PS1: %d\n", status);
        gpioDelay(1000); // Wait 1ms
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to enable PS1 after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Function to read proximity data from the Si1145 sensor
int read_proximity_data(uint16_t *proximity) {
    int status;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        status = i2cReadWordData(i2c_handle, PS1_DATA0_REG);
        if (status >= 0) {
            *proximity = (uint16_t)status;
            return 0; // Success
        }
        fprintf(stderr, "Error reading proximity data: %d\n", status);
        gpioDelay(1000); // Wait 1ms
        retries--;
    }

    fprintf(stderr, "Failed to read proximity data after multiple retries.\n");
    return -1; // Failure
}

// Function to log the proximity data to a file
int log_data(uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %u\n", timestamp, proximity);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
