#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define DISTANCE_THRESHOLD 20.0 // Distance threshold in cm
#define BUZZER_DURATION 500     // Buzzer duration in ms

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_valid = 0; // Flag to indicate valid echo

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(int start_tick, int end_tick);
void control_buzzer(double distance);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us delay
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            // Rising edge
            echo_start_tick = tick;
            echo_valid = 1; // Reset the valid flag on rising edge
        } else if (level == 0 && echo_valid) {
            // Falling edge
            echo_end_tick = tick;
            echo_valid = 0; // Disable further updates until next rising edge
        }
    }
}

// Function to calculate distance in centimeters
double calculate_distance(int start_tick, int end_tick) {
    if (start_tick == 0 || end_tick == 0) return -1.0; // Indicate invalid reading
    double diff = (double)(end_tick - start_tick);
    return (diff * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance, convert us to s
}

// Function to control the buzzer based on distance
void control_buzzer(double distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
        gpioDelay(BUZZER_DURATION); // Keep buzzer on for specified duration
        gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
    } else {
        gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off if distance is above threshold
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate(); // Terminate pigpio
    exit(0);          // Exit the program
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        trigger_pulse(); // Send trigger pulse

        gpioDelay(1000); // Wait for 1 second

        // Calculate distance
        double distance = calculate_distance(echo_start_tick, echo_end_tick);

        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
            control_buzzer(distance);
        } else {
            printf("Invalid reading\n");
        }
    }

    return 0; // This line will never be reached due to the infinite loop
}

