#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 50000      // 50ms timeout

// Global variables
volatile int running = 1;
int servo_angle = 0;

// Function prototypes
float measure_distance();
void set_servo_angle(int angle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

// Function to measure distance using HC-SR04
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0;
    }
    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0;
    }
    end_tick = gpioTick();

    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff_tick * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to set servo angle
void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    // Map angle (0-180) to pulse width (500-2500)
    int pulse_width = (int)(500 + (float)angle * (2500.0 - 500.0) / 180.0);
    gpioServo(SERVO_PIN, pulse_width);
    servo_angle = angle;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Install signal handler
    signal(SIGINT, signal_handler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();

        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);

            // Map distance to servo angle (example mapping)
            int angle;
            if (distance > 20.0) {
                angle = 180;
            } else if (distance > 110.0) {
                angle = 90;
            } else {
                angle = 0;
            }

            set_servo_angle(angle);
        } else {
            fprintf(stderr, "Error measuring distance\n");
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup (should not reach here if signal handler works)
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();

    return 0;
}

