#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define MIN_ANGLE 0.0         // degrees
#define MAX_ANGLE 180.0       // degrees
#define TIMEOUT_US 50000       // 50ms timeout
#define SERVO_MIN_PULSEWIDTH 500
#define SERVO_MAX_PULSEWIDTH 2500
#define SERVO_CENTER_PULSEWIDTH 1500
#define TRIGGER_PULSEWIDTH 10 // 10us trigger pulse

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCtrl+C pressed. Stopping servo and exiting.\n");
}

// Function to trigger the ultrasonic sensor
int triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSEWIDTH);
    gpioWrite(TRIGGER_PIN, 0);
    return 0;
}

// Function to measure the echo pulse width
long measurePulseWidth() {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every microsecond
    }
    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }
    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }
    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }
    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF; // Handle tick rollover
    }
    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate timeout error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to map the distance to a servo angle
float mapDistanceToAngle(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return MIN_ANGLE + (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set the servo angle
int setServoAngle(float angle) {
    int pulsewidth = SERVO_MIN_PULSEWIDTH + (int)((angle / 180.0) * (SERVO_MAX_PULSEWIDTH - SERVO_MIN_PULSEWIDTH));
    gpioServo(SERVO_PIN, pulsewidth);
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic distance measurement and servo control started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Trigger the sensor
        if (triggerSensor() != 0) {
            fprintf(stderr, "Error triggering sensor\n");
            continue;
        }

        // Measure the pulse width
        long pulse_width = measurePulseWidth();

        // Calculate the distance
        float distance = calculateDistance(pulse_width);

        // Map the distance to a servo angle
        float angle = mapDistanceToAngle(distance);

        // Set the servo angle
        if (setServoAngle(angle) != 0) {
            fprintf(stderr, "Error setting servo angle\n");
        }

        // Print the distance and angle
        printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);

        // Pause for 100ms
        gpioDelay(100000);
    }

    // Stop the servo
    gpioServo(SERVO_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

