#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// Measurement command (High Repeatability)
#define MEASURE_CMD 0xFD

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor(sensor_data_t *data);
void process_data(uint8_t *raw_data, sensor_data_t *data);
int validate_checksum(uint8_t data[], int len);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// CRC-8 calculation (as per SHT40 datasheet)
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor(sensor_data_t *data) {
    uint8_t raw_data[6];
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 10ms)
    gpioDelay(10000); // 10ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)raw_data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Process the data
    process_data(raw_data, data);

    return 0;
}

// Process raw data and convert to temperature and humidity
void process_data(uint8_t *raw_data, sensor_data_t *data) {
    // Extract temperature data
    uint16_t temperature_raw = (raw_data[0] << 8) | raw_data[1];
    uint8_t temperature_crc = raw_data[2];

    // Extract humidity data
    uint16_t humidity_raw = (raw_data[3] << 8) | raw_data[4];
    uint8_t humidity_crc = raw_data[5];

    // Validate temperature checksum
    if (!validate_checksum(raw_data, 2)) {
        fprintf(stderr, "Temperature checksum failure\n");
        data->temperature = -999.0; // Indicate error
    } else {
        // Convert temperature to Celsius (datasheet formula)
        data->temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
    }

    // Validate humidity checksum
    if (!validate_checksum(raw_data + 3, 2)) {
        fprintf(stderr, "Humidity checksum failure\n");
        data->humidity = -999.0; // Indicate error
    } else {
        // Convert humidity to percentage (datasheet formula)
        data->humidity = 100.0 * (float)humidity_raw / 65535.0;
    }
}

// Validate checksum
int validate_checksum(uint8_t data[], int len) {
    uint8_t calculated_crc = crc8(data, len - 1);
    return (calculated_crc == data[len - 1]);
}

// Log data to console
void log_data(sensor_data_t data) {
    printf("Temperature: %.2f °C, Humidity: %.2f %%\n", data.temperature, data.humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor(&sensor_data) == 0) {
            // Log data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

