        // Convert temperature to Celsius (datasheet formula)
        data->temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
    }

    // Validate humidity checksum
    if (!validate_checksum(raw_data + 3, 2)) {
        fprintf(stderr, "Humidity checksum failure\n");
        data->humidity = -999.0; // Indicate error
    } else {
        // Convert humidity to percentage (datasheet formula)
        data->humidity = 100.0 * (float)humidity_raw / 65535.0;
    }
}

// Validate checksum
int validate_checksum(uint8_t data[], int len) {
    uint8_t calculated_crc = crc8(data, len - 1);
    return (calculated_crc == data[len - 1]);
}

// Log data to console
void log_data(sensor_data_t data) {
    printf("Temperature: %.2f °C, Humidity: %.2f %%\n", data.temperature, data.humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor(&sensor_data) == 0) {
            // Log data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

