#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD_1 0x36
#define MEASURE_CMD_2 0x2F
#define LOG_FILE "pressure_log.csv"
#define SCALE_FACTOR_PRESSURE 60.0  // Pa
#define SCALE_FACTOR_TEMPERATURE 200.0 // °C

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_measurement_command();
int read_sensor_data(uint8_t *data);
int validate_crc8(const uint8_t *data, int len);
int convert_data(const uint8_t *data, sensor_data_t *sensor_data);
int log_data(const sensor_data_t *sensor_data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF; // Initialization value
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31; // Polynomial
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        sensor_data_t sensor_data;

        // Send measurement command
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            continue; // Retry
        }

        // Wait for measurement to complete (at least 1ms)
        gpioDelay(1000); // 1 ms

        // Read sensor data
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue; // Retry
        }

        // Validate CRC-8 checksums
        if (validate_crc8(data, 2) != 0 || validate_crc8(data + 3, 2) != 0 || validate_crc8(data + 6, 2) != 0) {
            fprintf(stderr, "CRC-8 validation failed\n");
            continue; // Retry
        }

        // Convert raw data to pressure and temperature
        if (convert_data(data, &sensor_data) != 0) {
            fprintf(stderr, "Failed to convert data\n");
            continue; // Retry
        }

        // Log data to file
        if (log_data(&sensor_data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }
    return 0;
}

// Send measurement command
int send_measurement_command() {
    char cmd[2] = {MEASURE_CMD_1, MEASURE_CMD_2};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return 1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc8(const uint8_t *data, int len) {
    uint8_t crc = crc8(data, len - 1);
    if (crc != data[len - 1]) {
        fprintf(stderr, "CRC-8 mismatch: expected 0x%02X, got 0x%02X\n", data[len - 1], crc);
        return 1;
    }
    return 0;
}

// Convert raw data to pressure and temperature
int convert_data(const uint8_t *data, sensor_data_t *sensor_data) {
    // Extract raw values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t raw_scale_factor_pressure = (data[6] << 8) | data[7];
    int16_t raw_scale_factor_temperature = (data[6] << 8) | data[8];

    // Convert to physical units
    sensor_data->pressure = (float)raw_pressure / raw_scale_factor_pressure * SCALE_FACTOR_PRESSURE;
    sensor_data->temperature = (float)raw_temperature / raw_scale_factor_temperature * SCALE_FACTOR_TEMPERATURE;

    return 0;
}

// Log data to file
int log_data(const sensor_data_t *sensor_data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Check if the file is empty, if so, write the header
