        return 1;
    }
    return 0;
}

// Validate CRC-8 checksum
int validate_crc8(const uint8_t *data, int len) {
    uint8_t crc = crc8(data, len - 1);
    if (crc != data[len - 1]) {
        fprintf(stderr, "CRC-8 mismatch: expected 0x%02X, got 0x%02X\n", data[len - 1], crc);
        return 1;
    }
    return 0;
}

