#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP31_ADDR 0x21
#define MEASURE_CMD 0x362F
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "airflow.log"
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
sensor_data_t convert_data(const uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger continuous measurement
int trigger_measurement() {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, cmd, 2);
        if (result == 0) {
            gpioDelay(1); // Wait 1ms
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (trigger): %d, retry %d\n", result, retries + 1);
            retries++;
            gpioDelay((1 << retries) * 10); // Exponential backoff
        }
    }
    fprintf(stderr, "Failed to trigger measurement after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Read sensor data
int read_sensor_data(uint8_t *data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result == 6) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %d, retry %d\n", result, retries + 1);
            retries++;
            gpioDelay((1 << retries) * 10); // Exponential backoff
        }
    }
    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Conversion formulas from SDP31 datasheet
    sensor_data.pressure_pa = (float)raw_pressure / 60.0; // Scale factor for SDP31
    sensor_data.temperature_c = (float)raw_temperature / 200.0; // Scale factor for SDP31

    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.pressure_pa, data.temperature_c);
    fflush(fp); // Flush the buffer to ensure data is written
    fclose(fp);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t sensor_data[6];
    sensor_data_t converted_data;

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement.\n");
            continue; // Skip to the next iteration
        }

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Failed to read sensor data.\n");
            continue; // Skip to the next iteration
        }

        // Convert data
        converted_data = convert_data(sensor_data);

        // Log data
        if (log_data(converted_data) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

