#include <unistd.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define TRIGGER_CMD_1 0x36
#define TRIGGER_CMD_2 0x2F
#define DATA_LENGTH 9
#define SLEEP_MS 100
#define SLEEP_TRIGGER_MS 45
#define SLEEP_ERROR_MS 1000
#define SLEEP_BUS_ERROR_MS 5000
#define SLEEP_SENSOR_ERROR_MS 5000
#define SLEEP_INIT_ERROR_MS 5000
#define SLEEP_CRC_ERROR_MS 1000
#define SLEEP_I2C_ERROR_MS 1000
#define SLEEP_I2C_BUSY_MS 1000
#define SLEEP_I2C_RETRY_MS 10
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    int16_t scale_factor;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
int validate_crc(const uint8_t *data, int len);
int convert_data(const uint8_t *data, sensor_data_t *sensor_data);
int log_data(const sensor_data_t *sensor_data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation (SDP800-500Pa datasheet)
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("airflow_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    // Main loop
    while (!terminate) {
        uint8_t raw_data[DATA_LENGTH];
        sensor_data_t sensor_data;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Trigger measurement failed\n");
            sleep(SLEEP_ERROR_MS);
            continue;
        }

        // Read sensor data
        if (read_sensor_data(raw_data) != 0) {
            fprintf(stderr, "Read sensor data failed\n");
            sleep(SLEEP_ERROR_MS);
            continue;
        }

        // Validate CRC
        if (validate_crc(raw_data, DATA_LENGTH) != 0) {
            fprintf(stderr, "CRC validation failed\n");
            sleep(SLEEP_CRC_ERROR_MS);
            continue;
        }

        // Convert data
        if (convert_data(raw_data, &sensor_data) != 0) {
            fprintf(stderr, "Data conversion failed\n");
            sleep(SLEEP_ERROR_MS);
            continue;
        }

        // Log data
        if (log_data(&sensor_data) != 0) {
            fprintf(stderr, "Logging data failed\n");
            sleep(SLEEP_ERROR_MS);
            continue;
        }

        // Sleep
        usleep(SLEEP_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup
    cleanup();

    return 0;
}

int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int trigger_measurement() {
    char cmd[2] = {TRIGGER_CMD_1, TRIGGER_CMD_2};
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, cmd, 2);
        if (result == 0) {
            usleep(SLEEP_TRIGGER_MS * 1000); // Wait for trigger to complete
            return 0;
        } else {
            fprintf(stderr, "I2C write failed (trigger): %s\n", strerror(errno));
            retries++;
            usleep(SLEEP_I2C_ERROR_MS * 1000);
        }
    }
    return -1;
}

int read_sensor_data(uint8_t *data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, (char *)data, DATA_LENGTH);
        if (result == DATA_LENGTH) {
            return 0;
        } else {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            retries++;
            usleep(SLEEP_I2C_ERROR_MS * 1000);
        }
    }
    return -1;
}

int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = crc8(data, len - 1);
    if (crc != data[len - 1]) {
        fprintf(stderr, "CRC mismatch: calculated 0x%02X, received 0x%02X\n", crc, data[len - 1]);
        return -1;
    }
    return 0;
}

int convert_data(const uint8_t *data, sensor_data_t *sensor_data) {
    sensor_data->pressure = (int16_t)((data[0] << 8) | data[1]);
    sensor_data->temperature = (int16_t)((data[3] << 8) | data[4]);
    sensor_data->scale_factor = (int16_t)((data[6] << 8) | data[7]);
    return 0;
}

int log_data(const sensor_data_t *sensor_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, (float)sensor_data->pressure / 10.0, (float)sensor_data->temperature / 200.0);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

