    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Send a command to the sensor
int send_command(int handle, unsigned short command) {
    unsigned char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, (char *)buf, 2);
    if (result != 2) {
        log_error("Failed to send command");
        return -1;
    }
    return 0;
}

