// SHT40 I2C address
#define SHT40_ADDR 0x44

// Measurement command (High Repeatability)
#define MEASURE_CMD 0xFD

// File to log data to
#define LOG_FILE "sht40_log.txt"

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SHT40 sensor
int read_sht40(sensor_data_t *data) {
    uint8_t write_data[1] = {MEASURE_CMD};
    uint8_t read_data[6];

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, write_data, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for measurement to complete (at least 8.5ms)
    gpioDelay(8500); // 8500 microseconds = 8.5 milliseconds

    // Read 6 bytes of data
    if (i2cReadDevice(i2c_handle, read_data, 6) != 0) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // CRC validation
    if (crc8(read_data, 2) != read_data[2]) {
        fprintf(stderr, "Temperature CRC failure\n");
        return -1;
    }
    if (crc8(read_data + 3, 2) != read_data[5]) {
        fprintf(stderr, "Humidity CRC failure\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t temperature_raw = (read_data[0] << 8) | read_data[1];
    uint16_t humidity_raw = (read_data[3] << 8) | read_data[4];

    data->temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
    data->humidity = 100.0 * (float)humidity_raw / 65535.0;

    return 0;
}

// Function to log data to a file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

