    if (result != count) {
        log_error("Failed to read data");
        return -1;
    }
    return 0;
}

// Process raw data
sensor_data_t process_data(const uint8_t *raw_data) {
    sensor_data_t data;
    data.pressure = (int16_t)((raw_data[0] << 8) | raw_data[1]);
    data.temperature = (int16_t)((raw_data[3] << 8) | raw_data[4]);
