    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(data_file, "%s,%.2f,%.2f\n", timestamp, (float)data.pressure / 10.0, (float)data.temperature / 200.0);
