#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_CMD 0xE3
#define FAN_GPIO 18
#define TEMP_THRESHOLD_ON 28.0
#define TEMP_THRESHOLD_OFF 27.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define FAN_ON_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer entry
typedef struct {
    time_t timestamp;
    float temperature;
} buffer_entry_t;

// Circular buffer
buffer_entry_t buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;

// Function prototypes
int read_temperature(float *temperature);
void control_fan(float temperature);
void add_to_buffer(float temperature);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature from Si7021
int read_temperature(float *temperature) {
    int result;
    uint8_t buf[2];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        result = i2cWriteByte(i2c_handle, TEMP_CMD);
        if (result == 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error writing temperature command: %d. Retries remaining: %d\n", result, retries);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to write temperature command after multiple retries.\n");
        return -1; // Indicate failure
    }

    gpioDelay(10000); // Wait 10ms

    retries = RETRY_COUNT;
    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result == 2) {
            break; // Success
        } else {
            fprintf(stderr, "Error reading temperature data: %d. Retries remaining: %d\n", result, retries);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read temperature data after multiple retries.\n");
        return -1; // Indicate failure
    }

    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    *temperature = (175.72 * raw_temp / 65536.0) - 46.85;

    return 0; // Indicate success
}

// Function to control the cooling fan
void control_fan(float temperature) {
    static int fan_on = 0; // Hysteresis state

    if (temperature > TEMP_THRESHOLD_ON && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON\n");
    } else if (temperature < TEMP_THRESHOLD_OFF && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF\n");
    }
}

// Function to add temperature reading to the circular buffer
void add_to_buffer(float temperature) {
    time(&buffer[buffer_index].timestamp);
    buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Temperature Log ---\n");
    for (int i = 0; i < buffer_count; i++) {
        struct tm *timeinfo = localtime(&buffer[i].timestamp);
        char timestamp_str[64];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Temperature: %.2f °C\n", timestamp_str, buffer[i].temperature);
    }
    printf("--- End of Log ---\n\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature;

    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
            add_to_buffer(temperature);
            control_fan(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Cleanup (should not reach here if signal handler works)
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

