#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xE4B8
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
int start_periodic_measurement();
int read_measurement(sensor_data_t *data);
int stop_periodic_measurement();
uint8_t crc8(const uint8_t *data, int len);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// CRC-8 calculation (as per SCD40 datasheet)
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize the sensor
int initialize_sensor() {
    int retries = 3;
    while (retries > 0) {
        i2c_handle = i2cOpen(1, SCD40_ADDR, 0);
        if (i2c_handle >= 0) {
            printf("Sensor initialized successfully.\n");
            return 0; // Success
        } else {
            fprintf(stderr, "Error opening I2C device: %d. Retrying...\n", i2c_handle);
            retries--;
            gpioDelay(100); // Wait 100ms before retrying
        }
    }
    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Start periodic measurement
int start_periodic_measurement() {
    char buf[2];
    buf[0] = (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_START_PERIODIC_MEASUREMENT & 0xFF;

    int retries = 3;
    while (retries > 0) {
        int result = i2cWriteDevice(i2c_handle, buf, 2);
        if (result == 0) {
            printf("Periodic measurement started.\n");
            return 0; // Success
        } else {
            fprintf(stderr, "Error starting periodic measurement: %d. Retrying...\n", result);
            retries--;
            gpioDelay(100); // Wait 100ms before retrying
        }
    }
    fprintf(stderr, "Failed to start periodic measurement after multiple retries.\n");
    return -1; // Failure
}

// Read measurement data
int read_measurement(sensor_data_t *data) {
    char buf[2];
    buf[0] = (CMD_READ_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_READ_MEASUREMENT & 0xFF;

