#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define GPIO_LED 17
#define CO2_THRESHOLD 1000
#define BUFFER_SIZE 20

// SCD40 Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xE4B8
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// Structure for sensor data
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_scd40();
int read_scd40(sensor_data_t *data);
int validate_checksum(uint16_t data, uint8_t checksum);
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
int get_from_buffer(circular_buffer_t *buffer, int index, sensor_data_t *data);
void control_led(int co2);
void signal_handler(int signal);
void cleanup();

// CRC-8-Maxim Algorithm (from SCD40 datasheet)
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize SCD40 sensor
int init_scd40() {
    char buf[2];
    buf[0] = (CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_START_PERIODIC_MEASUREMENT & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to start periodic measurement: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for sensor to start

    return 0;
}

// Read data from SCD40
int read_scd40(sensor_data_t *data) {
    char cmd[2] = {(CMD_READ_MEASUREMENT >> 8) & 0xFF, CMD_READ_MEASUREMENT & 0xFF};
    char buf[9];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write read measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Small delay after write

    result = i2cReadDevice(i2c_handle, buf, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // Extract data
    uint16_t co2 = (buf[0] << 8) | buf[1];
    uint16_t temp_raw = (buf[3] << 8) | buf[4];
    uint16_t humidity_raw = (buf[6] << 8) | buf[7];

    // Validate checksums
    if (!validate_checksum(co2, buf[2]) || !validate_checksum(temp_raw, buf[5]) || !validate_checksum(humidity_raw, buf[8])) {
        fprintf(stderr, "Checksum validation failed\n");
        return -1;
    }

    // Convert data
    data->co2 = co2;
    data->temperature = -45 + 175 * (float)temp_raw / 65535.0;
    data->humidity = 100 * (float)humidity_raw / 65535.0;

    return 0;
}

// Validate checksum
int validate_checksum(uint16_t data, uint8_t checksum) {
    uint8_t calculated_checksum = crc8((uint8_t *)&data, 2);
    return (calculated_checksum == checksum);
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get data from circular buffer
int get_from_buffer(circular_buffer_t *buffer, int index, sensor_data_t *data) {
    if (index < 0 || index >= buffer->count) {
        return -1; // Invalid index
    }
    int actual_index = (buffer->head - buffer->count + index + BUFFER_SIZE) % BUFFER_SIZE;
    *data = buffer->data[actual_index];
    return 0;
}

// Control LED based on CO2 level
void control_led(int co2) {
    if (co2 > CO2_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    char buf[2];
    buf[0] = (CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    buf[1] = CMD_STOP_PERIODIC_MEASUREMENT & 0xFF;

    i2cWriteDevice(i2c_handle, buf, 2);
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize SCD40
    if (init_scd40() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        cleanup();
        return 1;
    }

    // Main loop
    sensor_data_t data;
    while (!terminate) {
        if (read_scd40(&data) == 0) {
            add_to_buffer(&buffer, data);
            printf("CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%\n", data.co2, data.temperature, data.humidity);
            control_led(data.co2);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        gpioDelay(5000); // 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

