    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        cleanup();
        return 1;
    }

    // Main loop
    sensor_data_t data;
    while (!terminate) {
        if (read_scd40(&data) == 0) {
