#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 5 // seconds
#define TIMEOUT_US 50000   // 50ms
#define MAX_TEMP 150.0
#define MIN_TEMP -40.0

volatile sig_atomic_t terminate = 0;
int log_fd = -1;
int sensor_failures = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    return 0;
}

int open_log_file() {
    log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd == -1) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

void close_log_file() {
    if (log_fd != -1) {
        close(log_fd);
        log_fd = -1;
    }
}

void log_message(const char *message) {
    if (log_fd == -1) return;

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%s %s\n", timestamp, message);

    if (write(log_fd, log_entry, strlen(log_entry)) == -1) {
        perror("Error writing to log file");
    }
}

void cleanup() {
    close_log_file();
    gpioTerminate();
    fprintf(stderr, "Cleanup complete.\n");
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        return 1;
    }

    if (open_log_file() != 0) {
        cleanup();
        return 1;
    }

    struct timespec start, end;
    long long high_time, total_time;
    double temperature;

    while (!terminate) {
        // Wait for rising edge
        int start_sec, start_nsec;
        int end_sec, end_nsec;
        int timeout_sec = TIMEOUT_US / 1000000;
        int timeout_nsec = (TIMEOUT_US % 1000000) * 1000;

        clock_gettime(CLOCK_MONOTONIC, &start);
        start_sec = start.tv_sec;
        start_nsec = start.tv_nsec;

        int level = gpioRead(GPIO_PIN);
        while (level == 0 && !terminate) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            end_sec = end.tv_sec;
            end_nsec = end.tv_nsec;

            if ((end_sec - start_sec) * 1000000000LL + (end_nsec - start_nsec) > TIMEOUT_US * 1000) {
                log_message("Timeout waiting for rising edge");
                break;
            }
            level = gpioRead(GPIO_PIN);
        }

        if (terminate) break;

        clock_gettime(CLOCK_MONOTONIC, &start);
        start_sec = start.tv_sec;
        start_nsec = start.tv_nsec;

        // Wait for falling edge
        level = gpioRead(GPIO_PIN);
        while (level == 1 && !terminate) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            end_sec = end.tv_sec;
            end_nsec = end.tv_nsec;

            if ((end_sec - start_sec) * 1000000000LL + (end_nsec - start_nsec) > TIMEOUT_US * 1000) {
                log_message("Timeout waiting for falling edge");
                break;
            }
            level = gpioRead(GPIO_PIN);
        }

        if (terminate) break;

        clock_gettime(CLOCK_MONOTONIC, &end);
        end_sec = end.tv_sec;
        end_nsec = end.tv_nsec;

        high_time = (end_sec - start_sec) * 1000000000LL + (end_nsec - start_nsec);
        total_time = (end_sec - start_sec) * 1000000000LL + (end_nsec - start_nsec);

        // Calculate temperature (example formula, adjust as needed)
        if (high_time == 0) {
            log_message("Error: High time is zero");
            sensor_failures++;
            if (sensor_failures >= 3) {
                log_message("SENSOR MALFUNCTION");
                sensor_failures = 0; // Reset after logging
            }
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        temperature = (double)high_time / total_time * 100.0; // Example conversion

        if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
            char error_message[128];
            snprintf(error_message, sizeof(error_message), "Temperature out of range: %.2f", temperature);
            log_message(error_message);
            sensor_failures++;
            if (sensor_failures >= 3) {
                log_message("SENSOR MALFUNCTION");
                sensor_failures = 0; // Reset after logging
            }
        } else {
            char log_entry[128];
            snprintf(log_entry, sizeof(log_entry), "Temperature: %.2f C", temperature);
            log_message(log_entry);
            sensor_failures = 0; // Reset failure count on successful reading
        }

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}

