#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2400
#define CRC_POLYNOMIAL 0x31
#define DATA_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *data_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes);
SensorData process_sensor_data(uint8_t *raw_data);
float apply_offset(float value, float base_value, float amplitude, float frequency);
void log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from the SHT35 sensor
int read_sensor_data(uint8_t *data) {
    char cmd[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int retries = 3;
    int delay_ms = 1000; // Initial delay in milliseconds

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, cmd, 2) == 2) {
            gpioDelay(15); // Wait for measurement (at least 15ms)
            if (i2cReadDevice(i2c_handle, (char *)data, 6) == 6) {
                return 0; // Success
            } else {
                fprintf(stderr, "I2C read failed, retrying...\n");
            }
        } else {
            fprintf(stderr, "I2C write failed, retrying...\n");
        }

        retries--;
        gpioDelay(delay_ms);
        delay_ms *= 2; // Exponential backoff
    }

    fprintf(stderr, "I2C read failed after multiple retries\n");
    return -1; // Failure after retries
}

// Function to calculate the CRC checksum
uint8_t calculate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = 0xFF;
    uint8_t bit;

    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= (data[i]);
        for (bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

// Function to process raw sensor data
SensorData process_sensor_data(uint8_t *raw_data) {
    SensorData data;
    uint16_t temperature_raw, humidity_raw;

    // CRC validation
    if (calculate_crc(raw_data, 2) != raw_data[2]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        data.temperature = NAN;
    } else {
        temperature_raw = (raw_data[0] << 8) | raw_data[1];
        data.temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
    }

    if (calculate_crc(raw_data + 3, 2) != raw_data[5]) {
        fprintf(stderr, "Humidity CRC check failed\n");
        data.humidity = NAN;
    } else {
        humidity_raw = (raw_data[3] << 8) | raw_data[4];
        data.humidity = 100.0 * (float)humidity_raw / 65535.0;
    }

    return data;
}

// Function to apply a sinusoidal offset
float apply_offset(float value, float base_value, float amplitude, float frequency) {
    float offset = amplitude * sin(2 * M_PI * frequency * time(NULL));
    return base_value + offset;
}

// Function to log data to a file
void log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (data_file != NULL) {
        fprintf(data_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
        fflush(data_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Data file is not open\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    if (data_file != NULL) {
        fclose(data_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open data file
    data_file = fopen(DATA_FILE, "a");
    if (data_file == NULL) {
        fprintf(stderr, "Failed to open data file\n");
        cleanup();
        return 1;
    }

    uint8_t raw_data[6];
    SensorData sensor_data;
    float temperature_offset = 0.0;
    float humidity_offset = 0.0;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(raw_data) == 0) {
            // Process sensor data
            sensor_data = process_sensor_data(raw_data);

            // Apply offsets
            sensor_data.temperature = apply_offset(sensor_data.temperature, temperature_offset, 2.0, 0.041666666666666664); // 1/24 hours
            sensor_data.humidity = apply_offset(sensor_data.humidity, humidity_offset, 5.0, 0.041666666666666664); // 1/24 hours

            // Log data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
            fprintf(data_file, "NaN,NaN\n");
            fflush(data_file);
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

