// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len, uint8_t crc) {
    const uint8_t POLYNOMIAL = 0x31;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, sensor_data_t *data) {
    uint8_t buffer[9];
    int result;

    // Send continuous measurement command
    uint8_t cmd[2] = {(CONT_MEAS_CMD >> 8) & 0xFF, CONT_MEAS_CMD & 0xFF};
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
