    uint8_t crc_pressure = crc8(buffer, 2, 0xFF);
    uint8_t crc_temperature = crc8(buffer + 3, 2, 0xFF);
    uint8_t crc_scale_factor = crc8(buffer + 6, 1, 0xFF);

