#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2400
#define CSV_FILE "environment.csv"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(unsigned char *data);
int validate_checksum(unsigned char *data);
sensor_data_t convert_data(unsigned char *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void shutdown();

// CRC-8 calculation (Sensirion SHT35)
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(unsigned char *data) {
    unsigned char command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    if (i2cWriteDevice(i2c_handle, command, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }
    gpioDelay(15); // Wait 15ms
    if (i2cReadDevice(i2c_handle, data, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }
    return 0;
}

// Validate checksum
int validate_checksum(unsigned char *data) {
    unsigned char temp_data[2] = {data[0], data[1]};
    unsigned char hum_data[2] = {data[3], data[4]};

    if (crc8(temp_data, 2) != data[2]) {
        fprintf(stderr, "Temperature checksum error\n");
        return -1;
    }
    if (crc8(hum_data, 2) != data[5]) {
        fprintf(stderr, "Humidity checksum error\n");
        return -1;
    }
    return 0;
}

// Convert data to temperature and humidity
sensor_data_t convert_data(unsigned char *data) {
    sensor_data_t result;
    // Convert temperature
    int temp_raw = (data[0] << 8) | data[1];
    result.temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);

    // Convert humidity
    int hum_raw = (data[3] << 8) | data[4];
    result.humidity = 100.0 * (float)hum_raw / 65535.0;
    return result;
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    FILE *fp = fopen(CSV_FILE, "a+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        return -1;
    }

    // Check if the file is empty, if so, add the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,temperature_C,humidity_percent\n");
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    // Write data to file
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Shutdown function
void shutdown() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char data[6];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Validate checksum
            if (validate_checksum(data) == 0) {
                // Convert data
                sensor_data = convert_data(data);

                // Log data
                if (log_data(sensor_data) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                fprintf(stderr, "Checksum validation failed\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Shutdown
    shutdown();

    return 0;
}

