    int result, i;
    unsigned char buffer[3];

    result = i2cWriteByte(handle, command);
    if (result != 0) {
        fprintf(stderr, "Error writing command to sensor: %d\n", result);
        return -1;
    }

    gpioDelay(50); // Wait for measurement (datasheet specifies typical 11ms)

    for (i = 0; i < 3; i++) {
        result = i2cReadByte(handle);
        if (result < 0) {
            fprintf(stderr, "Error reading byte %d from sensor: %d\n", i, result);
            return -1;
        }
        buffer[i] = (unsigned char)result;
    }

    *data = (buffer[0] << 8) | buffer[1];

