    unsigned char data_crc = buffer[2];
    unsigned char data_msb = buffer[0];
    unsigned char data_lsb = buffer[1];

    crc ^= data_msb;
    for (i = 0; i < 8; i++) {
        if (crc & 0x80) {
            crc = (crc << 1) ^ 0x131; // Polynomial X^8 + X^5 + X^4 + 1
        } else {
            crc <<= 1;
        }
    }

    crc ^= data_lsb;
    for (i = 0; i < 8; i++) {
        if (crc & 0x80) {
            crc = (crc << 1) ^ 0x131; // Polynomial X^8 + X^5 + X^4 + 1
        } else {
            crc <<= 1;
        }
    }

    if (crc != data_crc) {
        fprintf(stderr, "CRC check failed!\n");
        return -1;
    }

    return 0;
}

