#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x362F
#define SAMPLE_INTERVAL_SEC 1
#define FILENAME "airflow.dat"

// Global variables
int i2c_handle = -1;
FILE *fp = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// CRC-8 calculation (as per SDP810 datasheet)
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send the measurement command
int send_command() {
    char cmd[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to validate the CRC checksums
int validate_checksum(uint8_t *data) {
    uint8_t pressure_data[2] = {data[0], data[1]};
    uint8_t temperature_data[2] = {data[3], data[4]};

    if (crc8(pressure_data, 2) != data[2]) {
        fprintf(stderr, "Pressure CRC check failed\n");
        return -1;
    }

    if (crc8(temperature_data, 2) != data[5]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    return 0;
}

// Function to convert raw data to pressure and temperature
sensor_data_t convert_data(uint8_t *data) {
    sensor_data_t sensor_data;
    // Scale factors (example values, adjust based on datasheet)
    float pressure_scale_factor = 0.1; // Pa
    float temperature_scale_factor = 0.01; // °C

    // Combine MSB and LSB for pressure and temperature
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // Convert to floating-point values
    sensor_data.pressure = (float)raw_pressure * pressure_scale_factor;
    sensor_data.temperature = (float)raw_temperature * temperature_scale_factor;

    return sensor_data;
}

// Function to log the data to a file
int log_data(float pressure, float temperature) {
    if (fp == NULL) {
        fp = fopen(FILENAME, "wb");
        if (fp == NULL) {
            fprintf(stderr, "Failed to open file for writing\n");
            return -1;
        }
    }

    fwrite(&pressure, sizeof(float), 1, fp);
    fwrite(&temperature, sizeof(float), 1, fp);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Send measurement command
    if (send_command() != 0) {
        gpioTerminate();
        i2cClose(i2c_handle);
        return 1;
    }

    uint8_t data[9];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Validate checksum
            if (validate_checksum(data) == 0) {
                // Convert data
                sensor_data = convert_data(data);

                // Log data
                if (log_data(sensor_data.pressure, sensor_data.temperature) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "Checksum validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();

    return 0;
}

