#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define CONT_MEAS_CMD 0x362F
#define CRC_POLYNOMIAL 0x31
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint16_t status;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
int read_sensor_data(int handle, sensor_data_t *data);
double convert_pressure(int16_t raw_pressure);
void log_data(double pressure);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = crc8(data, len - 1);
    return (crc == data[len - 1]);
}

// I2C initialization function
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// I2C write function
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }
    return 0;
}

// I2C read function
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Data conversion function
double convert_pressure(int16_t raw_pressure) {
    return (double)raw_pressure / 30.0; // Sensitivity of SDP800-500Pa
}

// Data logging function
void log_data(double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f Pa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Sensor data reading function
int read_sensor_data(int handle, sensor_data_t *data) {
    uint8_t raw_data[9];
    int16_t raw_pressure;
    int16_t raw_temperature;

    if (send_command(handle, CONT_MEAS_CMD) != 0) {
        fprintf(stderr, "Failed to send continuous measurement command\n");
        return -1;
    }

    gpioDelay(45); // Wait for conversion time

    if (read_data(handle, raw_data, 9) != 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    // CRC validation
    if (!validate_crc(raw_data, 3) || !validate_crc(raw_data + 3, 3) || !validate_crc(raw_data + 6, 3)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Extract data
    raw_pressure = (int16_t)((raw_data[0] << 8) | raw_data[1]);
    raw_temperature = (int16_t)((raw_data[3] << 8) | raw_data[4]);
    data->status = (uint16_t)((raw_data[6] << 8) | raw_data[7]);

    // Convert pressure
    data->pressure = raw_pressure;
    data->temperature = raw_temperature;

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

