// Constants
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int i2c_handle, int *raw_pressure);
float convert_to_pressure(int raw_pressure);
float calculate_flow_rate(float pressure);
void set_fan_speed(int gpio, float flow_rate);
void log_data(FILE *log_file, float pressure, float flow_rate);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, shutting down...\n", signal);
}

// Function to read the sensor data
int read_sensor(int i2c_handle, int *raw_pressure) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1; // Indicate failure
    }

    *raw_pressure = (buf[0] << 8) | buf[1];
    return 0; // Indicate success
}

// Function to convert raw data to pressure (Pa)
float convert_to_pressure(int raw_pressure) {
    // HAFBLF0100A2AX5: 0.1 Pa/LSB
    return (float)raw_pressure * 0.1;
}

// Function to calculate flow rate (mL/min) from pressure (Pa)
float calculate_flow_rate(float pressure) {
    // Approximate linear relationship: flow_rate = pressure * 0.1
    return pressure * 0.1;
}

// Function to set the fan speed using PWM
void set_fan_speed(int gpio, float flow_rate) {
    // Map flow rate to PWM duty cycle (0-1000)
    int duty_cycle = (int)(flow_rate * 10); // Scale flow rate to 0-100
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 1000) duty_cycle = 1000;

    gpioPWM(gpio, duty_cycle);
}

// Function to log data to a file
void log_data(FILE *log_file, float pressure, float flow_rate) {
    time_t now = time(NULL);
    fprintf(log_file, "%ld,%.2f,%.2f\n", now, pressure, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x28, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int raw_pressure;
    float pressure, flow_rate;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor(i2c_handle, &raw_pressure) == 0) {
            // Convert to pressure
            pressure = convert_to_pressure(raw_pressure);

            // Calculate flow rate
            flow_rate = calculate_flow_rate(pressure);

            // Set fan speed
            set_fan_speed(FAN_GPIO, flow_rate);

            // Log data
            log_data(log_file, pressure, flow_rate);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    gpioPWM(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

