#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// LPS33HW I2C address (default)
#define LPS33HW_ADDR 0x5C

// LPS33HW register addresses
#define CTRL_REG1 0x20
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful termination
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0); // Bus 1, address 0x5C, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize the LPS33HW sensor
int init_sensor() {
    // Enable continuous data acquisition (ODR = 100 Hz)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x44) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    return 0;
}

// Read pressure and temperature data from the sensor
int read_sensor_data(sensor_data_t *data) {
    unsigned char buffer[5];
    int result;

    // Read pressure data (3 bytes)
    result = i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, (char *)buffer, 3);
    if (result < 0) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1;
    }

    // Read temperature data (2 bytes)
    result = i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, (char *)buffer + 3, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }

    // Combine pressure data
    int32_t pressure_raw = (int32_t)buffer[0] | ((int32_t)buffer[1] << 8) | ((int32_t)buffer[2] << 16);

    // Combine temperature data
    int16_t temperature_raw = (int16_t)buffer[3] | ((int16_t)buffer[4] << 8);

    // Convert raw data to hPa and Celsius (refer to LPS33HW datasheet)
    data->pressure = (float)pressure_raw / 4096.0; // hPa
    data->temperature = (float)temperature_raw / 100.0; // °C

    return 0;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t now;
    struct tm timeinfo;
    char timestamp[20];

    time(&now);
    localtime_r(&now, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, data.pressure, data.temperature);
    fflush(log_file);

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data. Continuing...\n");
        }
        time_sleep(1.0);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

