#define TEMP_THRESHOLD 28.0f

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_i2c();
float read_temperature();
void update_circular_buffer(float temperature);
float calculate_average();
void control_led(float average_temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read temperature from STLM75 sensor
float read_temperature() {
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -100.0f; // Indicate error with a very low temperature
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits
    float temperature = raw_temp * 0.125f;

    return temperature;
}

// Update circular buffer with new temperature reading
void update_circular_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate running average of temperature readings
float calculate_average() {
    float sum = 0.0f;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Control LED based on average temperature
void control_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C communication
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer with 0.0
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temperature_buffer[i] = 0.0f;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -99.0f) { // Check for valid temperature reading
            update_circular_buffer(temperature);
            float average_temperature = calculate_average();
            control_led(average_temperature);
            printf("Temperature: %.2f°C, Average: %.2f°C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping iteration.\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup before exiting
    gpioWrite(LED_GPIO, 0); // Turn LED off
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");
    return 0;
}

