#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdbool.h>

// SCD30 I2C address
#define SCD30_I2C_ADDR 0x61

// SCD30 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x0010
#define CMD_READ_MEASUREMENT 0x0300
#define CMD_STOP_PERIODIC_MEASUREMENT 0x0104
#define CMD_SELF_TEST 0x3646
#define CMD_GET_DATA_READY 0x0202
#define CMD_SET_MEASUREMENT_INTERVAL 0x4600

// Global variables
int i2c_handle;
FILE *log_file;
bool running = true;

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_scd30();
int read_scd30_data(sensor_data_t *data);
int write_scd30_command(unsigned short command);
int stop_periodic_measurement();
int start_periodic_measurement();
int set_measurement_interval(unsigned short interval);
int get_data_ready();
void ventilation_control(float co2);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the SCD30 sensor
int init_scd30() {
    // Start periodic measurement
    if (write_scd30_command(CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement.\n");
        return -1;
    }

    // Set measurement interval to 5 seconds
    if (set_measurement_interval(5) != 0) {
        fprintf(stderr, "Error: Failed to set measurement interval.\n");
        return -1;
    }

    return 0;
}

// Function to read data from the SCD30 sensor
int read_scd30_data(sensor_data_t *data) {
    unsigned char buffer[18];
    int result;

    // Check if data is ready
    if (get_data_ready() != 0) {
        fprintf(stderr, "Error: Data not ready.\n");
        return -1;
    }

    // Read measurement data
    result = i2cReadI2CBlockData(i2c_handle, CMD_READ_MEASUREMENT, (char *)buffer, 18);
    if (result != 18) {
        fprintf(stderr, "Error: Failed to read measurement data. Returned %d\n", result);
        return -1;
    }

    // CRC check
    unsigned char crc = 0xFF;
    for (int i = 0; i < 16; i++) {
        crc ^= buffer[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x131; // Polynomial X^8 + X^5 + X^4 + 1
            } else {
                crc = (crc << 1);
            }
        }
    }

    if (crc != buffer[16]) {
        fprintf(stderr, "Error: CRC mismatch.\n");
        return -1;
    }

    // Parse data
    data->co2 = (float)((unsigned int)buffer[0] << 8 | (unsigned int)buffer[1]);
    data->temperature = (float)((unsigned int)buffer[6] << 8 | (unsigned int)buffer[7]) / 100.0;
    data->humidity = (float)((unsigned int)buffer[12] << 8 | (unsigned int)buffer[13]) / 100.0;

    return 0;
}

// Function to write a command to the SCD30 sensor
int write_scd30_command(unsigned short command) {
    unsigned char buffer[2];
    buffer[0] = command >> 8;
    buffer[1] = command & 0xFF;

    int result = i2cWriteI2CBlockData(i2c_handle, buffer[0], (char *)buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error: Failed to write command 0x%04X. Returned %d\n", command, result);
        return -1;
    }

    return 0;
}

// Function to stop periodic measurement
int stop_periodic_measurement() {
    return write_scd30_command(CMD_STOP_PERIODIC_MEASUREMENT);
}

// Function to start periodic measurement
int start_periodic_measurement() {
    return write_scd30_command(CMD_START_PERIODIC_MEASUREMENT);
}

// Function to set measurement interval
int set_measurement_interval(unsigned short interval) {
    unsigned char buffer[2];
    buffer[0] = interval >> 8;
    buffer[1] = interval & 0xFF;

    int result = i2cWriteI2CBlockData(i2c_handle, CMD_SET_MEASUREMENT_INTERVAL, (char *)buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error: Failed to set measurement interval. Returned %d\n", result);
        return -1;
    }

    return 0;
}

// Function to check if data is ready
int get_data_ready() {
    unsigned char buffer[3];
    int result = i2cReadI2CBlockData(i2c_handle, CMD_GET_DATA_READY, (char *)buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: Failed to get data ready status. Returned %d\n", result);
        return -1;
    }

    if (buffer[0] != 0x00 || buffer[1] != 0x00 || buffer[2] != 0x00) {
        return 0; // Data not ready
    }

    return 1; // Data ready
}

// Function to control ventilation based on CO2 level
void ventilation_control(float co2) {
    if (co2 < 800) {
        printf("VENT OFF\n");
    } else if (co2 >= 800 && co2 < 1200) {
        printf("VENT LOW\n");
    } else {
        printf("VENT HIGH\n");
    }
}

// Function to log data to a file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, stopping...\n", signal);
    running = false;
}

// Cleanup function to close I2C and log file
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. Error code: %d\n", i2c_handle);
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        cleanup();
        return 1;
    }

    // Initialize SCD30 sensor
    if (init_scd30() != 0) {
        fprintf(stderr, "Error: SCD30 initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (running) {
        // Read sensor data
        if (read_scd30_data(&sensor_data) == 0) {
            // Log data
            log_data(sensor_data);

            // Control ventilation
            ventilation_control(sensor_data.co2);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Stop periodic measurement
    stop_periodic_measurement();

    // Cleanup and exit
    cleanup();
    return 0;
}

