#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define HDC1000_ADDR 0x40
#define TEMP_REG 0x00
#define HUMID_REG 0x01
#define CONFIG_REG 0x02

int i2c_fd = -1;

void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    int temp_raw, humid_raw;
    float temperature, humidity;
    unsigned char buf[4];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Configure HDC1000 for 14-bit temperature and humidity measurement
    buf[0] = CONFIG_REG;
    buf[1] = 0x00; // Configure register value
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    while (1) {
        // Trigger temperature and humidity measurement
        buf[0] = TEMP_REG;
        if (write(i2c_fd, buf, 1) != 1) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            continue; // Continue to the next iteration
        }

        // Wait for conversion to complete (at least 20ms)
        usleep(20000); // 20ms

        // Read temperature data
        buf[0] = TEMP_REG;
        if (write(i2c_fd, buf, 1) != 1) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            continue; // Continue to the next iteration
        }

        if (read(i2c_fd, buf, 2) != 2) {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            continue; // Continue to the next iteration
        }
        temp_raw = (buf[0] << 8) | buf[1];
        temperature = ((float)temp_raw / 65536.0) * 165.0 - 40.0;

        // Read humidity data
        buf[0] = HUMID_REG;
        if (write(i2c_fd, buf, 1) != 1) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            continue; // Continue to the next iteration
        }

        if (read(i2c_fd, buf, 2) != 2) {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            continue; // Continue to the next iteration
        }
        humid_raw = (buf[0] << 8) | buf[1];
        humidity = ((float)humid_raw / 65536.0) * 100.0;

        // Print temperature and humidity
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

