#define SLEEP_DURATION 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read temperature from Si7051
float read_temperature() {
    char buf[2];
    int result;

    // Send temperature measurement command
    result = i2cWriteByteData(i2c_handle, TEMP_MEASURE_CMD, 0);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1000.0; // Indicate error
