// Constants
#define I2C_BUS 1
#define ICP10101_ADDR 0x69
#define TEMP_REG 0x00
#define PRESS_REG 0x03
#define DEFAULT_TEMP 25.0
#define DEFAULT_PRESS 101325.0
#define SLEEP_DURATION 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float pressure;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
void print_sensor_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICP10101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and pressure data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[6];
    int result;

    // Trigger measurement (no-op command)
    result = i2cWriteByteData(i2c_handle, 0x7E, 0x00); // Example command, check datasheet
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(7); // Wait 7ms

    // Read temperature and pressure data
    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature and pressure (example conversion, adjust as needed)
    int raw_temp = (buf[0] << 8) | buf[1];
    int raw_press = (buf[3] << 8) | buf[4];

    data->temperature = (float)raw_temp / 100.0; // Example conversion
    data->pressure = (float)raw_press * 10.0;    // Example conversion

    return 0;
}

// Print sensor data with ISO 8601 timestamp
void print_sensor_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, data.temperature, data.pressure);
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            print_sensor_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Using default values.\n");
            sensor_data.temperature = DEFAULT_TEMP;
            sensor_data.pressure = DEFAULT_PRESS;
            print_sensor_data(sensor_data);
        }
        gpioSleep(PI_TIME_RELATIVE, SLEEP_DURATION, 0); // Sleep for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

