            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // CRC validation
        uint8_t crc_data[2] = {(sensor_data.pressure >> 8) & 0xFF, sensor_data.pressure & 0xFF};
        uint8_t calculated_crc = calculate_crc(crc_data, 2);

        if (calculated_crc != sensor_data.crc) {
            fprintf(stderr, "CRC validation failed! Calculated: 0x%02X, Received: 0x%02X\n", calculated_crc, sensor_data.crc);
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Log data
        if (log_data(sensor_data.pressure) != 0) {
            fprintf(stderr, "Error logging data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        gpioDelay(SLEEP_MS); // Sleep for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

