#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MLX90821_ADDR 0x60
#define PRESSURE_REG 0x00
#define PRESSURE_SCALE_FACTOR 0.1 // kPa per raw unit
#define PRESSURE_MIN 200.0
#define PRESSURE_MAX 250.0
#define RETRY_COUNT 2
#define RETRY_DELAY_MS 10
#define LOG_FILE "pressure_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_i2c();
int read_pressure(float *pressure);
int log_data(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int mlx90821_address;
    float pressure_scale;
    float pressure_min;
    float pressure_max;
    int retry_count;
    int retry_delay_ms;
    char *log_file_name;
} config_t;

config_t config = {
    I2C_BUS,
    MLX90821_ADDR,
    PRESSURE_SCALE_FACTOR,
    PRESSURE_MIN,
    PRESSURE_MAX,
    RETRY_COUNT,
    RETRY_DELAY_MS,
    LOG_FILE
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float pressure;
    while (1) {
        if (read_pressure(&pressure) == 0) {
            log_data(pressure);

            // Check pressure range
            if (pressure < config.pressure_min || pressure > config.pressure_max) {
                fprintf(stderr, "Warning: Pressure out of range: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Failed to read pressure\n");
        }

        sleep(1);
    }

    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.mlx90821_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read pressure from sensor
int read_pressure(float *pressure) {
    char buffer[2];
    int raw_pressure;
    int result;

    // Read pressure register
    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        // Retry once
        gpioDelay(RETRY_DELAY_MS * 1000); //pigpio delay in microseconds
        result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buffer, 2);
        if (result != 2) {
            fprintf(stderr, "I2C read failed after retry: %d\n", result);
            return -1;
        }
    }

    // Combine bytes to form raw pressure value
    raw_pressure = (buffer[0] << 8) | buffer[1];

    // Convert to kPa
    *pressure = raw_pressure * config.pressure_scale;

    return 0;
}

// Log data to file
int log_data(float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Write to log file
    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

