#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_MAX_SIZE 1048576 // 1MB
#define MEASUREMENT_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *humidity, uint16_t *temperature);
SensorData process_sensor_data(uint16_t raw_humidity, uint16_t raw_temperature);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw sensor data
int read_sensor_data(uint16_t *humidity, uint16_t *temperature) {
    char buf[4];
    int result;

    // Trigger measurement
    result = i2cWriteByte(i2c_handle, 0x00);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(40); // Wait 40ms

    // Read 4 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Check status bits
    uint16_t status = ((uint16_t)buf[0] << 8) | (uint16_t)buf[1];
    if (status & 0x0002) {
        fprintf(stderr, "Sensor busy\n");
        return -1;
    }
    if (status & 0x0001) {
        fprintf(stderr, "Sensor error\n");
        return -1;
    }

    // Extract humidity and temperature
    *humidity = ((uint16_t)buf[0] << 8) | (uint16_t)buf[1];
    *temperature = ((uint16_t)buf[2] << 6) | ((uint16_t)buf[3] >> 2);

    return 0;
}

// Process raw sensor data
SensorData process_sensor_data(uint16_t raw_humidity, uint16_t raw_temperature) {
    SensorData data;
    data.humidity = (float)raw_humidity / 16383 * 100;
    data.temperature = (float)raw_temperature / 16383 * 165 - 40;
    return data;
}

// Log data to file
int log_data(SensorData data) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    // Write data to file
    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);

    fclose(fp);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t raw_humidity, raw_temperature;
        SensorData data;

        // Read sensor data
        if (read_sensor_data(&raw_humidity, &raw_temperature) == 0) {
            // Process sensor data
            data = process_sensor_data(raw_humidity, raw_temperature);

            // Log data
            if (log_data(data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Check log file size and truncate if necessary
        struct stat st;
        if (stat(LOG_FILE, &st) == 0) {
            if (st.st_size > LOG_FILE_MAX_SIZE) {
                FILE *fp = fopen(LOG_FILE, "w");
                if (fp != NULL) {
                    fclose(fp);
                    printf("Log file truncated\n");
                } else {
                    fprintf(stderr, "Error truncating log file\n");
                }
            }
        } else {
            fprintf(stderr, "Error getting log file size\n");
        }

        // Wait for the next measurement interval
        sleep(MEASUREMENT_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

