        return 1;
    }

    // Set GPIO4 as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s.\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting pressure monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        // Read SENT data
        if (read_sent_data(GPIO_PIN, &status, &data1, &data2, &data3, &checksum) == 0) {
            // Validate data
            if (validate_data(status, data1, data2, data3, checksum) == 0) {
                // Convert to pressure
                pressure = convert_to_pressure(data1, data2, data3);

                // Log pressure
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Error: Failed to log pressure.\n");
                }
            } else {
                fprintf(stderr, "Error: Data validation failed.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read SENT data.\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

