#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define CRC8_POLYNOMIAL 0x31
#define DATA_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle = -1;
FILE *data_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
int read_sht40(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
SensorData convert_data(const uint8_t *data);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from the SHT40 sensor
int read_sht40(uint8_t *data) {
    if (i2cWriteByte(i2c_handle, MEASURE_HIGH_PRECISION) != 0) {
        fprintf(stderr, "Failed to write measurement command\n");
        return -1;
    }
    gpioDelay(10); // Wait for conversion (datasheet specifies 8.5ms for high precision)

    if (i2cReadDevice(i2c_handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Failed to read data from sensor\n");
        return -1;
    }

    return 0;
}

// Function to calculate the CRC8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate the CRC8 checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = calculate_crc(data, len - 1);
    return (crc == data[len - 1]);
}

// Function to convert raw data to temperature and humidity
SensorData convert_data(const uint8_t *data) {
    SensorData sensor_data;
    // Temperature
    uint16_t temperature_raw = (data[0] << 8) | data[1];
    sensor_data.temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;

    // Humidity
    uint16_t humidity_raw = (data[3] << 8) | data[4];
    sensor_data.humidity = -6.0 + 125.0 * (float)humidity_raw / 65535.0;

    return sensor_data;
}

// Function to log data to a file
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (data_file == NULL) {
        data_file = fopen(DATA_FILE, "a");
        if (data_file == NULL) {
            fprintf(stderr, "Failed to open data file for appending\n");
            return -1;
        }
    }

    fprintf(data_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    fflush(data_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    if (data_file != NULL) {
        fclose(data_file);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    uint8_t data[6];
    SensorData sensor_data;

    while (!terminate) {
        // Read sensor data
        if (read_sht40(data) == 0) {
            // Validate CRC
            if (validate_crc(data, 2) && validate_crc(data + 3, 2)) {
                // Convert data
                sensor_data = convert_data(data);

                // Log data
                if (log_data(sensor_data) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

