} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int bytes_read;

    // Read rotation speed
    bytes_read = i2cReadI2CBlockData(i2c_handle, ROTATION_SPEED_REG, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading rotation speed: %d\n", bytes_read);
        data->speed = NAN;
    } else {
        int16_t raw_speed = (buf[0] << 8) | buf[1];
        data->speed = (float)raw_speed * SPEED_SCALE_FACTOR;
    }

    // Read temperature
    bytes_read = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", bytes_read);
        data->temperature = NAN;
    } else {
        int16_t raw_temp = (buf[0] << 8) | buf[1];
        data->temperature = (float)raw_temp * TEMP_SCALE_FACTOR;
    }

    return 0;
}

// Function to log data to a file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
        fprintf(log_file, "Timestamp,Speed (RPM),Temperature (C)\n"); // Header
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.speed, data.temperature);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Function to clean up resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log data
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, logging NaN values\n");
            sensor_data.speed = NAN;
            sensor_data.temperature = NAN;
            log_data(sensor_data);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // microseconds
    }

    // Clean up and exit
    cleanup();
    return 0;
}

