            }

            return temperature;
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(100); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_RETRIES);
    return -999.0; // Indicate error
}

