    while (!terminate) {
        float temperature = read_temperature();

        if (temperature != -999.0) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping logging.\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

