#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_PIN 4
#define SAMPLE_INTERVAL 2 // seconds
#define MAX_RETRIES 3

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int read_dht11_data(int pin, float *humidity, float *temperature) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int byte_index = 0;
    int i, j;
    unsigned int start_time, end_time, pulse_length;

    // Send start signal
    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 0);
    gpioDelay(18000); // 18ms
    gpioWrite(pin, 1);
    gpioDelay(20); // 20us

    gpioSetMode(pin, PI_INPUT);

    // Read data
    start_time = gpioTick();
    while (bit_count < 40) {
        // Wait for low pulse
        while (gpioRead(pin) == 1) {
            end_time = gpioTick();
            if (end_time - start_time > 200) {
                fprintf(stderr, "Timeout waiting for low pulse\n");
                return -1; // Timeout
            }
        }
        start_time = gpioTick();

        // Measure high pulse length
        while (gpioRead(pin) == 0) {
            end_time = gpioTick();
            if (end_time - start_time > 200) {
                fprintf(stderr, "Timeout waiting for high pulse\n");
                return -1; // Timeout
            }
        }
        end_time = gpioTick();

        pulse_length = end_time - start_time;

        // Determine bit value
        if (pulse_length > 40) {
            data[byte_index] |= (1 << (7 - bit_count % 8));
        }

        bit_count++;
        byte_index += bit_count / 8;
        bit_count %= 8;
    }

    // Verify checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "Checksum failure\n");
        return -2; // Checksum failure
    }

    // Convert data to temperature and humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0; // Success
}

int log_data(float humidity, float temperature) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("dht11_readings.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing\n");
        return -1;
    }

    fprintf(fp, "%s,%.1f,%.1f\n", timestamp, humidity, temperature);
    fclose(fp);

    return 0;
}

int main() {
    float humidity, temperature;
    int result, retries;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        retries = 0;
        do {
            result = read_dht11_data(DHT11_PIN, &humidity, &temperature);
            if (result == 0) {
                if (log_data(humidity, temperature) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "DHT11 read failed, retry %d\n", retries + 1);
                retries++;
                gpioDelay(1000000); // Wait 1 second before retrying
            }
        } while (retries < MAX_RETRIES);

        if (result != 0) {
            fprintf(stderr, "DHT11 read failed after %d retries\n", MAX_RETRIES);
        }

        sleep(SAMPLE_INTERVAL);
    }

    gpioTerminate();
    printf("Program terminated gracefully\n");
    return 0;
}

