    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("dht11_readings.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing\n");
        return -1;
    }

    fprintf(fp, "%s,%.1f,%.1f\n", timestamp, humidity, temperature);
    fclose(fp);

    return 0;
}

