// Constants
#define I2C_BUS 1
#define SHT31_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2C06
#define DATA_LENGTH 6
#define LOG_FILE "sht31d_data.log"
#define RETRY_COUNT 3
#define SLEEP_DURATION 5 // seconds

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc8(const uint8_t *data, int len);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation (as per SHT31-D datasheet)
uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retries
int read_sensor_data(uint8_t *data) {
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = i2cWriteWordData(i2c_handle, 0, MEASUREMENT_COMMAND);
        if (result < 0) {
            fprintf(stderr, "Error writing to I2C: %d, retries left: %d\n", result, retries);
            gpioDelay(10); // Small delay before retry
            retries--;
            continue;
        }

        gpioDelay(15); // Wait for measurement (at least 15ms)

        result = i2cReadI2CBlockData(i2c_handle, 0, (char *)data, DATA_LENGTH);
        if (result == DATA_LENGTH) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C: %d, retries left: %d\n", result, retries);
            retries--;
            gpioDelay(10); // Small delay before retry
        }
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure after retries
}

// Log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    uint8_t raw_data[DATA_LENGTH];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(raw_data) == 0) {
            // CRC validation
            if (calculate_crc8(raw_data, 2) != raw_data[2]) {
                fprintf(stderr, "Temperature CRC check failed!\n");
                log_data(-999.0, -999.0); // Log error values
            } else if (calculate_crc8(raw_data + 3, 2) != raw_data[5]) {
                fprintf(stderr, "Humidity CRC check failed!\n");
                log_data(-999.0, -999.0); // Log error values
            } else {
                // Convert raw data to temperature and humidity
                int16_t temperature_raw = (raw_data[0] << 8) | raw_data[1];
                int16_t humidity_raw = (raw_data[3] << 8) | raw_data[4];

                sensor_data.temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
                sensor_data.humidity = 100.0 * (float)humidity_raw / 65535.0;

                // Log the data
                if (log_data(sensor_data.temperature, sensor_data.humidity) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
            log_data(-999.0, -999.0); // Log error values
        }

        sleep(SLEEP_DURATION);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

