        cleanup();
        return 1;
    }
    if (initialize_sensor(i2c_handle_2, SENSOR_ID_2) < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("cct_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        cleanup();
        return 1;
    }

    // Check if the file is empty and write the header if needed
