    if (result < 0) {
        fprintf(stderr, "Error: Failed to read sensor data\n");
        return -1;
    }

    // Assuming data is in the order Red, Green, Blue (adjust as needed)
    *red = (buffer[1] << 8) | buffer[0];
    *green = (buffer[3] << 8) | buffer[2];
    *blue = (buffer[5] << 8) | buffer[4];

    return 0;
}

