    // Convert raw data to pressure and temperature (example conversion, adjust as needed)
    int raw_pressure = (buf[0] << 8) | buf[1];
    int raw_temperature = (buf[2] << 8) | buf[3];

    data->pressure = (float)raw_pressure * 0.1; // Example conversion
    data->temperature = (float)raw_temperature * 0.01 - 40.0; // Example conversion

    return 0;
}

// Logs the pressure and temperature data to a file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return -1;
        }
