    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Cleans up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed, exiting\n");
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioSleep(PI_TIME_RELATIVE, SLEEP_DURATION, 0); // Sleep for 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

