#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_ADDR 0x48
#define FAN_GPIO 18
#define TEMP_THRESHOLD_ON 28.0f
#define TEMP_THRESHOLD_OFF 26.0f
#define SAMPLE_SIZE 60
#define SAMPLE_PERIOD_SEC 1

// Global variables
int i2c_handle;
float temperature_buffer[SAMPLE_SIZE];
int buffer_index = 0;
bool fan_on = false;

// Function prototypes
float read_temperature();
float calculate_average();
void control_fan(float average_temperature);
void log_error(const char *message);
void signal_handler(int signal);

// Function to read temperature from LM75B sensor
float read_temperature() {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        log_error("Failed to read temperature from I2C device.");
        return -100.0f; // Indicate error
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits
    float temperature = raw_temp * 0.125f;

    return temperature;
}

// Function to calculate the running average of the temperature buffer
float calculate_average() {
    float sum = 0.0f;
    for (int i = 0; i < SAMPLE_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    return sum / SAMPLE_SIZE;
}

// Function to control the cooling fan with hysteresis
void control_fan(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD_ON && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = true;
        printf("Fan turned ON (Avg Temp: %.2f°C)\n", average_temperature);
    } else if (average_temperature < TEMP_THRESHOLD_OFF && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = false;
        printf("Fan turned OFF (Avg Temp: %.2f°C)\n", average_temperature);
    }
}

// Function to log errors to stderr
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device.");
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize temperature buffer with 0.0
    for (int i = 0; i < SAMPLE_SIZE; i++) {
        temperature_buffer[i] = 0.0f;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read temperature
        float temperature = read_temperature();
        if (temperature > -99.0f) { // Check for valid temperature reading
            // Store temperature in circular buffer
            temperature_buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % SAMPLE_SIZE;

            // Calculate running average
            float average_temperature = calculate_average();

            // Control fan
            control_fan(average_temperature);

            printf("Temperature: %.2f°C, Average: %.2f°C\n", temperature, average_temperature);
        } else {
            log_error("Invalid temperature reading, skipping this cycle.");
        }

        // Wait for 1 second
        time_sleep(SAMPLE_PERIOD_SEC);
    }

    return 0;
}

