#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_ADDR 0x25
#define I2C_BUS 1
#define MEASURE_CMD 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define LOG_FILE "airflow.log"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
sensor_data_t process_sensor_data(const uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    gpioDelay(45000); // 45ms delay
    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC-8
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = calculate_crc(data, len - 1);
    return (crc == data[2]);
}

// Function to process sensor data
sensor_data_t process_sensor_data(const uint8_t *data) {
    sensor_data_t result;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    result.pressure = (float)raw_pressure / 240.0; // Scale factor from datasheet
    result.temperature = (float)raw_temperature / 200.0; // Scale factor from datasheet

    return result;
}

// Function to log data to file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
