#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_ADDR 0x4A
#define TEMP_REG 0x00
#define LED_GPIO 17
#define TEMP_HIGH 28.0
#define TEMP_LOW 27.0
#define I2C_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_temperature(float *temperature);
void control_led(float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read temperature from STTS2004 sensor
int read_temperature(float *temperature) {
    int retries = I2C_RETRIES;
    int result;
    unsigned char data[2];

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, (char *)data, 2);
        if (result == 2) {
            // Convert raw data to temperature (refer to STTS2004 datasheet)
            int raw_temp = (data[0] << 8) | data[1];
            *temperature = (float)raw_temp / 256.0; // Example conversion, adjust as needed
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (errno: %d), retries remaining: %d\n", errno, retries);
            retries--;
            usleep(100000); // Wait 100ms before retrying
        }
    }

    fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    return -1; // Failure
}

// Function to control the LED with hysteresis
void control_led(float temperature) {
    static int led_state = 0; // 0 = off, 1 = on

    if (temperature > TEMP_HIGH && led_state == 0) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
        led_state = 1;
        printf("Temperature: %.2f°C, LED ON\n", temperature);
    } else if (temperature < TEMP_LOW && led_state == 1) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
        led_state = 0;
        printf("Temperature: %.2f°C, LED OFF\n", temperature);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x4A, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus (errno: %d)\n", errno);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature;

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            control_led(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

