#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// HDC1080 I2C address
#define HDC1080_ADDR 0x40

// HDC1080 register addresses
#define HDC1080_TEMP_REG 0x00
#define HDC1080_HUMID_REG 0x01
#define HDC1080_CONFIG_REG 0x02

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the HDC1080 sensor
int hdc1080_init(int i2c_handle) {
    // Configure the sensor for temperature and humidity measurement (14-bit resolution, 14-bit temperature, 14-bit humidity)
    // 0x00 = 14-bit resolution, 0x00 = 14-bit temperature, 0x00 = 14-bit humidity
    if (i2cWriteByteData(i2c_handle, HDC1080_CONFIG_REG, 0x00) != 0) {
        fprintf(stderr, "Error writing to configuration register\n");
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the HDC1080 sensor
int hdc1080_read(int i2c_handle, float *temperature, float *humidity) {
    // Trigger temperature and humidity measurement
    if (i2cWriteByte(i2c_handle, HDC1080_TEMP_REG) != 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    // Wait for at least 20ms for conversion
    gpioDelay(20000); // 20ms

    // Read temperature data
    uint16_t raw_temp;
    if (i2cReadWordData(i2c_handle, HDC1080_TEMP_REG) != 0) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }
    raw_temp = i2cReadWordData(i2c_handle, HDC1080_TEMP_REG);
    if (raw_temp == PI_BAD_I2C_ADDR) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    // Read humidity data
    uint16_t raw_humidity;
    if (i2cReadWordData(i2c_handle, HDC1080_HUMID_REG) != 0) {
        fprintf(stderr, "Error reading humidity data\n");
        return -1;
    }
    raw_humidity = i2cReadWordData(i2c_handle, HDC1080_HUMID_REG);
    if (raw_humidity == PI_BAD_I2C_ADDR) {
        fprintf(stderr, "Error reading humidity data\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    *temperature = ((float)raw_temp / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

// Function to log data to a file
int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HDC1080 sensor
    if (hdc1080_init(i2c_handle) != 0) {
        fprintf(stderr, "HDC1080 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Read temperature and humidity
        if (hdc1080_read(i2c_handle, &temperature, &humidity) == 0) {
            // Log data to file
            if (log_data("enviro_log.txt", temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

