#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// STS40 I2C address
#define STS40_ADDR 0x44

// Measurement command (High Precision)
#define MEASURE_CMD 0xFD

// File to log temperature data
#define LOG_FILE "temperature_log.txt"

// Global variables for signal handling
static volatile int running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    uint16_t temperature;
    uint16_t humidity;
} sensor_data_t;

// CRC8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from STS40
int read_sts40(int i2c_fd, float *temperature) {
    uint8_t cmd = MEASURE_CMD;
    uint8_t data[6];
    int result;

    // Send measurement command
    result = i2cWriteDevice(i2c_fd, &cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 10ms)
    gpioDelay(10000); // 10ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_fd, data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // CRC8 validation
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC8 mismatch for temperature data\n");
        return -1;
    }

    // Convert raw temperature to Celsius
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    *temperature = -45.0 + (175.0 * raw_temperature / 65535.0);

    return 0;
}

// Function to log temperature data to file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    float temperature;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(1, STS40_ADDR, 0); // Bus 1, address 0x44, no flags
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read temperature
        if (read_sts40(i2c_fd, &temperature) == 0) {
            // Log temperature
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

