        log_error("Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    char buf[2];
    buf[0] = (START_MEASUREMENT_CMD >> 8) & 0xFF;
    buf[1] = START_MEASUREMENT_CMD & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to start periodic measurement");
        return -1;
    }
    return 0;
}

// Stop periodic measurement
int stop_periodic_measurement() {
    char buf[2];
    buf[0] = (STOP_MEASUREMENT_CMD >> 8) & 0xFF;
    buf[1] = STOP_MEASUREMENT_CMD & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to stop periodic measurement");
        return -1;
    }
    return 0;
}

// Read data from SCD40
int read_scd40_data(uint16_t *co2, float *temperature, float *humidity) {
    char buf[2];
    char read_buf[9];
    uint16_t raw_co2, raw_temperature, raw_humidity;

    // Read CO2
    buf[0] = 0xE4B8 >> 8;
    buf[1] = 0xE4B8 & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        log_error("Failed to write CO2 read command");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, read_buf, 3) != 3) {
        log_error("Failed to read CO2 data");
        return -1;
    }
    raw_co2 = (read_buf[0] << 8) | read_buf[1];
    if (!validate_crc(raw_co2, read_buf[2])) {
        log_error("CO2 CRC validation failed");
        return -1;
    }

    // Read Temperature
    buf[0] = 0xEC05 >> 8;
    buf[1] = 0xEC05 & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        log_error("Failed to write temperature read command");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, read_buf, 3) != 3) {
        log_error("Failed to read temperature data");
        return -1;
    }
    raw_temperature = (read_buf[0] << 8) | read_buf[1];
    if (!validate_crc(raw_temperature, read_buf[2])) {
        log_error("Temperature CRC validation failed");
        return -1;
    }

    // Read Humidity
    buf[0] = 0xE000 >> 8;
    buf[1] = 0xE000 & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        log_error("Failed to write humidity read command");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, read_buf, 3) != 3) {
        log_error("Failed to read humidity data");
        return -1;
    }
    raw_humidity = (read_buf[0] << 8) | read_buf[1];
    if (!validate_crc(raw_humidity, read_buf[2])) {
        log_error("Humidity CRC validation failed");
        return -1;
    }

    *co2 = raw_co2;
    *temperature = -45 + 175 * (raw_temperature / 65535.0);
    *humidity = 100 * (raw_humidity / 65535.0);

    return 0;
}

// Validate CRC
int validate_crc(uint16_t data, uint8_t crc) {
    uint8_t data_bytes[2];
    data_bytes[0] = (data >> 8) & 0xFF;
    data_bytes[1] = data & 0xFF;
    uint8_t calculated_crc = crc8(data_bytes, 2);
    return (calculated_crc == crc);
}

// Add data to circular buffer
int add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->buffer[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Get data from circular buffer
int get_from_buffer(circular_buffer_t *buffer, sensor_data_t *data) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->count == 0) {
        pthread_mutex_unlock(&buffer->mutex);
        return -1; // Buffer is empty
    }
    *data = buffer->buffer[buffer->tail];
    buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    buffer->count--;
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Logging thread function
void *logging_thread_func(void *arg) {
    (void)arg; // Suppress unused parameter warning
    while (running) {
        sleep(LOGGING_INTERVAL);
        if (!running) break;

        FILE *fp = fopen(DATA_FILE_PATH, "a");
        if (fp == NULL) {
            log_error("Failed to open data file for writing");
            continue;
        }

        // Write header if the file is newly created
        fseek(fp, 0, SEEK_END);
        long fsize = ftell(fp);
        if (fsize == 0) {
            fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%)\n");
        }

        circular_buffer_t local_buffer;
        pthread_mutex_lock(&data_buffer.mutex);
        memcpy(&local_buffer, &data_buffer, sizeof(circular_buffer_t));
        pthread_mutex_unlock(&data_buffer.mutex);

        for (int i = 0; i < local_buffer.count; i++) {
            int index = (local_buffer.tail + i) % BUFFER_SIZE;
            fprintf(fp, "%ld,%u,%.2f,%.2f\n", local_buffer.buffer[index].timestamp,
                    local_buffer.buffer[index].co2, local_buffer.buffer[index].temperature,
                    local_buffer.buffer[index].humidity);
        }

        fclose(fp);
    }
    pthread_exit(NULL);
}

// Signal handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT. Shutting down...\n");
        running = 0;
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");

    // Stop periodic measurement
    stop_periodic_measurement();

    // Wait for logging thread to finish
    pthread_join(logging_thread, NULL);

    // Close I2C connection
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close error log file
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }

    // Destroy mutex
    pthread_mutex_destroy(&data_buffer.mutex);

    printf("Cleanup complete. Exiting.\n");
}

// Log error to file
void log_error(const char *message) {
    if (error_log_file == NULL) {
        error_log_file = fopen(ERROR_LOG_PATH, "a");
        if (error_log_file == NULL) {
            perror("Failed to open error log file");
            return;
        }
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(error_log_file, "%d-%02d-%02d %02d:%02d:%02d: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(error_log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    data_buffer.head = 0;
    data_buffer.tail = 0;
    data_buffer.count = 0;
    pthread_mutex_init(&data_buffer.mutex, NULL);

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Create logging thread
    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        log_error("Failed to create logging thread");
        cleanup();
        return 1;
    }

    // Main loop
    uint16_t co2;
    float temperature, humidity;
    sensor_data_t data;
    time_t last_read_time = time(NULL);

    while (running) {
        time_t current_time = time(NULL);
        if (difftime(current_time, last_read_time) >= READ_INTERVAL) {
            if (read_scd40_data(&co2, &temperature, &humidity) == 0) {
                data.timestamp = time(NULL);
                data.co2 = co2;
                data.temperature = temperature;
                data.humidity = humidity;
                add_to_buffer(&data_buffer, data);
            }
            last_read_time = current_time;
        }
        sleep(1); // Check every second
    }

    // Cleanup and exit
    cleanup();
    gpioTerminate();
    return 0;
}

