// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len, uint8_t crc) {
    const uint8_t POLYNOMIAL = 0x31; // CRC-8-ATM
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, sensor_data_t *data) {
