    if (pressure < PRESSURE_THRESHOLD) {
        // Switch to alert blink rate
        if (current_time - last_toggle_time >= (1000 / ALERT_BLINK_RATE) / 2) {
            led_state = !led_state;
            gpioWrite(gpio_pin, led_state);
            last_toggle_time = current_time;
        }
    } else {
