        // Read sensor data with retries
        int read_result = -1;
        for (int i = 0; i < retries; i++) {
            if (read_sensor_data(i2c_handle, sensor_data) == 0) {
                read_result = 0;
                break;
            } else {
                fprintf(stderr, "Retrying I2C read (%d/%d)...\n", i + 1, retries);
