            }
        }

        if (read_result != 0) {
            fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
            continue; // Skip to the next iteration
        }

        // Verify CRC checksum
        if (!verify_crc(sensor_data, 6)) {
            fprintf(stderr, "CRC checksum verification failed!\n");
            continue; // Skip to the next iteration
        }

        // Extract raw data
        raw_pressure = (sensor_data[0] << 8) | sensor_data[1];
        raw_temperature = (sensor_data[2] << 8) | sensor_data[3];

        // Convert data
        pressure = convert_pressure(raw_pressure);
        temperature = convert_temperature(raw_temperature);

        // Control LED
        control_led(GPIO_LED, pressure);

        // Print data (optional)
        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        // Delay
        gpioDelay(20); // 20ms delay

        // Poll every second
        gpioDelay((1000 - POLL_INTERVAL) * 1000); // Delay for remaining time
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

