#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define HYSTERESIS_ON_TEMP 30.0
#define HYSTERESIS_OFF_TEMP 28.0
#define LOG_FILE "temperature_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_temperature(int reg, float *temp);
void control_fan(float object_temp);
void log_temperature(float ambient_temp, float object_temp);
void signal_handler(int signal);

// Structure for grouping sensor data
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from the sensor
int read_temperature(int reg, float *temp) {
    int retries = 3;
    int result;
    uint16_t raw_temp;

    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, reg);
        if (result >= 0) {
            raw_temp = (uint16_t)result;
            *temp = (float)raw_temp * 0.02 - 273.15; // Convert to Celsius
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (reg 0x%02X), retrying...\n", reg);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X)\n", reg);
    return -1; // Failure
}

// Function to control the cooling fan
void control_fan(float object_temp) {
    static int fan_on = 0; // Hysteresis state

    if (object_temp > HYSTERESIS_ON_TEMP && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON\n");
    } else if (object_temp < HYSTERESIS_OFF_TEMP && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF\n");
    }
}

// Function to log temperature data to a file
void log_temperature(float ambient_temp, float object_temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    FILE *fp;

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    fprintf(fp, "%s, Ambient: %.2f C, Object: %.2f C\n", timestamp, ambient_temp, object_temp);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    sensor_data_t sensor_data;

    while (!terminate) {
        // Read temperatures
        if (read_temperature(AMBIENT_TEMP_REG, &sensor_data.ambient_temp) != 0) {
            fprintf(stderr, "Failed to read ambient temperature\n");
        }
        if (read_temperature(OBJECT_TEMP_REG, &sensor_data.object_temp) != 0) {
            fprintf(stderr, "Failed to read object temperature\n");
        }

        // Log temperatures
        log_temperature(sensor_data.ambient_temp, sensor_data.object_temp);

        // Control fan
        control_fan(sensor_data.object_temp);

        sleep(2);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");
    return 0;
}

