// Constants
#define I2C_BUS 1
#define TMP102_ADDR 0x48
#define CSV_FILE "temperature_log.csv"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle = -1; // Initialize to -1 to indicate not opened
volatile sig_atomic_t terminate = 0; // Flag for graceful shutdown

// Function prototypes
int init_i2c();
float read_temperature();
int log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional, but good practice)
typedef struct {
    int i2c_bus;
    int tmp102_address;
    const char* csv_filename;
    int sample_interval;
} config_t;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read temperature from TMP102
float read_temperature() {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 4) | (buf[1] >> 4);
    if (raw_temp & 0x800) {
        raw_temp |= 0xF000; // Sign extend if negative
    }
    float temperature = raw_temp * 0.0625;

    return temperature;
}

// Log temperature to CSV file
int log_temperature(float temperature) {
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature, skipping log.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

