#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define TEMP_MSB_REG 0x00
#define TEMP_LSB_REG 0x01
#define HUMID_MSB_REG 0x02
#define HUMID_LSB_REG 0x03
#define MEASUREMENT_CONFIG_REG 0x0F

// I2C bus
#define I2C_BUS 1

// Timeout in milliseconds
#define TIMEOUT_MS 500

// Maximum retry count
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to read a register from the HDC2010
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading register 0x%02X: %d. Retry %d/%d\n", reg, result, retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
    }

    fprintf(stderr, "Failed to read register 0x%02X after %d retries.\n", reg, MAX_RETRIES);
    return -1; // Failure
}

// Function to write a register to the HDC2010
int write_register(int handle, uint8_t reg, uint8_t value) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing register 0x%02X: %d. Retry %d/%d\n", reg, result, retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10); // Small delay before retrying
        }
    }

    fprintf(stderr, "Failed to write register 0x%02X after %d retries.\n", reg, MAX_RETRIES);
    return -1; // Failure
}

// Function to read temperature and humidity from the HDC2010
int read_temperature_humidity(int handle, float *temperature, float *humidity) {
    uint8_t temp_msb, temp_lsb, humid_msb, humid_lsb;
    int retries = 0;
    int result;

    // Trigger measurement
    if (write_register(handle, MEASUREMENT_CONFIG_REG, 0x01) != 0) {
        fprintf(stderr, "Failed to trigger measurement.\n");
        return -1;
    }

    // Wait for measurement to complete with timeout
    uint32_t start_time = gpioTick();
    while (1) {
        if (read_register(handle, MEASUREMENT_CONFIG_REG, &result) != 0) {
            fprintf(stderr, "Failed to read measurement status.\n");
            return -1;
        }

        if ((result & 0x01) == 0) {
            break; // Measurement complete
        }

        if (gpioTick() - start_time > TIMEOUT_MS * 1000) {
            fprintf(stderr, "Timeout waiting for measurement to complete.\n");
            return -1;
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    // Read temperature data
    if (read_register(handle, TEMP_MSB_REG, &temp_msb) != 0) {
        fprintf(stderr, "Failed to read temperature MSB.\n");
        return -1;
    }
    if (read_register(handle, TEMP_LSB_REG, &temp_lsb) != 0) {
        fprintf(stderr, "Failed to read temperature LSB.\n");
        return -1;
    }

    // Read humidity data
    if (read_register(handle, HUMID_MSB_REG, &humid_msb) != 0) {
        fprintf(stderr, "Failed to read humidity MSB.\n");
        return -1;
    }
    if (read_register(handle, HUMID_LSB_REG, &humid_lsb) != 0) {
        fprintf(stderr, "Failed to read humidity LSB.\n");
        return -1;
    }

