#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F // Continuous measurement without averaging
#define PRESSURE_SCALE 60.0f
#define TEMPERATURE_SCALE 200.0f
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[6];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, MEASURE_CMD >> 8, MEASURE_CMD & 0xFF);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (45ms)
    gpioDelay(45000); // microseconds

    // Read 6 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0, (char *)buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // CRC validation
    if (calculate_crc(buffer, 2) != buffer[2] || calculate_crc(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert data
    data->pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->temperature = (int16_t)((buffer[3] << 8) | buffer[4]);

    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    printf("SDP800-500Pa sensor reader started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            // Log data
            printf("Pressure: %d Pa, Temperature: %d °C\n", sensor_data.pressure, sensor_data.temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(500000); // 500ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

