#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SSR_GPIO 17
#define TARGET_PROFILE "profile.txt"
#define LOG_FILE "reflow_log.csv"
#define MAX_RETRIES 3

// PID Gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for PID controller state
typedef struct {
    double integral;
    double previous_error;
} PIDState;

PIDState pid_state = {0.0, 0.0};

// Function prototypes
double read_thermocouple();
double calculate_pid(double setpoint, double actual_temperature);
void set_ssr_duty_cycle(double duty_cycle);
void log_temperature(double temperature);
void load_target_profile(double *profile, int *profile_size);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to initialize the system
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SSR_GPIO, PI_OUTPUT);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature\n");
    }
    rewind(log_file);

    return 0;
}

// Function to read temperature from MAX6675
double read_thermocouple() {
    unsigned char data[2];
    int i;
    double temperature = -1000.0; // Initialize with an invalid value

    for (i = 0; i < MAX_RETRIES; ++i) {
        if (spiRead(spi_handle, data, 2) == 2) {
            // Check for fault bit (bit 2 of byte 0)
            if (data[0] & 0x04) {
                fprintf(stderr, "Thermocouple fault detected!\n");
                log_temperature(-999.0); // Log fault
                gpioDelay(100); // Small delay before retry
                continue; // Retry
            }

            // Extract temperature data (bits 3-14 of byte 0 and byte 1)
            int raw_temp = ((data[0] << 8) | data[1]) >> 3;
            temperature = raw_temp * 0.25;
            return temperature;
        } else {
            fprintf(stderr, "SPI read failed, retrying...\n");
            gpioDelay(100); // Small delay before retry
        }
    }

    fprintf(stderr, "Failed to read temperature after multiple retries\n");
    log_temperature(-998.0); // Log error
    return -1000.0; // Return invalid value
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    pid_state.integral += error;
    double derivative = error - pid_state.previous_error;
    double output = KP * error + KI * pid_state.integral + KD * derivative;
    pid_state.previous_error = error;

    // Clamp the output to the range 0.0 - 1.0
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;

    return output;
}

// Function to set SSR duty cycle
void set_ssr_duty_cycle(double duty_cycle) {
    int pulse_width = (int)(duty_cycle * 1000000); // Convert duty cycle to pulse width (microseconds)
    gpioPWM(SSR_GPIO, pulse_width);
}

// Function to log temperature to file
void log_temperature(double temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to load target profile from file
void load_target_profile(double *profile, int *profile_size) {
    FILE *fp = fopen(TARGET_PROFILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open target profile file\n");
        *profile_size = 0; // Indicate failure
        return;
    }

    char line[256];
    int count = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (count >= 100) { // Limit the number of entries to prevent buffer overflow
            fprintf(stderr, "Target profile too long, max 100 entries\n");
            break;
        }
        if (sscanf(line, "%lf,%lf", &profile[count].time, &profile[count].temperature) == 2) {
            count++;
        } else {
            fprintf(stderr, "Invalid line in target profile: %s", line);
        }
    }

    fclose(fp);
    *profile_size = count;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to clean up resources
void cleanup() {
    printf("Cleaning up...\n");
    set_ssr_duty_cycle(0.0); // Turn off SSR
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    double target_profile[100]; // Assuming max 100 points in profile
    int profile_size = 0;
    load_target_profile(target_profile, &profile_size);

    if (profile_size == 0) {
        fprintf(stderr, "Failed to load target profile, exiting\n");
        cleanup();
        return 1;
    }

    double current_temperature;
    double setpoint;
    double pid_output;
    time_t current_time;
    struct tm *timeinfo;
    char timestamp[20];
    int profile_index = 0;

    while (!terminate) {
        current_temperature = read_thermocouple();

        if (current_temperature > -999.0) { // Check for valid temperature reading
            time(&current_time);
            timeinfo = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            if (profile_index < profile_size) {
                setpoint = target_profile[profile_index].temperature;
            } else {
                setpoint = 0.0; // Default to 0°C after profile is exhausted
            }

            pid_output = calculate_pid(setpoint, current_temperature);
            set_ssr_duty_cycle(pid_output);
            log_temperature(current_temperature);

            printf("%s - Temperature: %.2f°C, Setpoint: %.2f°C, PID Output: %.2f, Duty Cycle: %.2f\n",
                   timestamp, current_temperature, setpoint, pid_output, pid_output);

            if (profile_index < profile_size && current_time >= target_profile[profile_index].time) {
                profile_index++;
            }
        } else {
            fprintf(stderr, "Invalid temperature reading, skipping PID calculation\n");
        }

        gpioDelay(100); // 10 Hz (100 ms delay)
    }

    cleanup();
    return 0;
}

