#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HTU21D_ADDR 0x40
#define MEASURE_HUMIDITY_HOLD 0xE5
#define API_ENDPOINT "http://api.example.com/humidity"
#define POLL_INTERVAL 60 // seconds

int i2c_handle;
volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to read humidity from HTU21D sensor
float read_humidity() {
    char buf[3];
    int result;

    result = i2cWriteByteData(i2c_handle, MEASURE_HUMIDITY_HOLD, 0);
    if (result != 0) {
        syslog(LOG_ERR, "Failed to trigger humidity measurement: %d", result);
        return -1.0;
    }

    gpioDelay(50); // Wait for measurement (datasheet specifies 50ms)

    result = i2cReadI2CBlockData(i2c_handle, 0, buf, 3);
    if (result != 3) {
        syslog(LOG_ERR, "Failed to read humidity data: %d", result);
        return -1.0;
    }

    unsigned int raw_humidity = (buf[0] << 8) | buf[1];
    unsigned char crc = buf[2];

    // CRC check (example, adjust as needed based on datasheet)
    if (crc != 0) { // Placeholder CRC check, replace with actual CRC calculation
        syslog(LOG_ERR, "CRC mismatch: %d", crc);
        return -1.0;
    }

    // Convert raw data to humidity (example, adjust as needed based on datasheet)
    float humidity = (float)raw_humidity * 125.0 / 65536.0 - 6.0;
    if (humidity < 0.0 || humidity > 100.0) {
        syslog(LOG_ERR, "Humidity out of range: %.2f", humidity);
        return -1.0;
    }

    return humidity;
}

// Function to format humidity data as JSON
char* format_json(float humidity) {
    char *json_string = malloc(50 * sizeof(char)); // Allocate memory for the JSON string
    if (json_string == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for JSON string");
        return NULL;
    }
    snprintf(json_string, 50, "{\"humidity\": %.2f}", humidity);
    return json_string;
}

// Function to send HTTP POST request
int send_http_post(const char *json_data) {
    int sockfd;
    struct sockaddr_in serv_addr;
    char buffer[1024] = {0};
    ssize_t bytes_sent, bytes_received;
    char response[256] = {0};

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Failed to create socket");
        return -1;
    }

    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80); // Default HTTP port

    if (inet_pton(AF_INET, "api.example.com", &serv_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        syslog(LOG_ERR, "Failed to connect to server");
        close(sockfd);
        return -1;
    }

    // Construct HTTP POST request
    snprintf(buffer, sizeof(buffer), "POST %s HTTP/1.1\r\nHost: api.example.com\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s", API_ENDPOINT, strlen(json_data), json_data);

    bytes_sent = send(sockfd, buffer, strlen(buffer), 0);
    if (bytes_sent < 0) {
        syslog(LOG_ERR, "Failed to send data: %zd", bytes_sent);
        close(sockfd);
        return -1;
    }

    // Receive server response
    bytes_received = recv(sockfd, response, sizeof(response) - 1, 0);
    if (bytes_received < 0) {
        syslog(LOG_ERR, "Failed to receive data: %zd", bytes_received);
        close(sockfd);
        return -1;
    }
    response[bytes_received] = '\0';

    syslog(LOG_INFO, "Received server response: %s", response);

    close(sockfd);
    return 0;
}

int main() {
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting humidity monitor...");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HTU21D_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %d", i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    while (!terminate) {
        float humidity = read_humidity();
        if (humidity >= 0.0) {
            char *json_data = format_json(humidity);
            if (json_data != NULL) {
                if (send_http_post(json_data) == 0) {
                    syslog(LOG_INFO, "Humidity: %.2f%%, JSON: %s", humidity, json_data);
                } else {
                    syslog(LOG_ERR, "Failed to send HTTP POST request");
                }
                free(json_data);
            } else {
                syslog(LOG_ERR, "Failed to format JSON");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }

        sleep(POLL_INTERVAL);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    return 0;
}

