#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_CHIPID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESSURE_MSB 0xF7
#define BMP280_REG_PRESSURE_LSB 0xF8
#define BMP280_REG_PRESSURE_XLSB 0xF9
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC

// Expected chip ID
#define BMP280_CHIP_ID 0x58

// Oversampling settings
#define BMP280_OVERSAMPLING_TEMP 2 // x2
#define BMP280_OVERSAMPLING_PRESS 5 // x16
#define BMP280_MODE_NORMAL 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration data
int32_t t_fine;
uint16_t dig_T1;
int16_t dig_T2;
int16_t dig_T3;
uint16_t dig_P1;
int16_t dig_P2;
int16_t dig_P3;
int16_t dig_P4;
int16_t dig_P5;
int16_t dig_P6;
int16_t dig_P7;
int16_t dig_P8;
int16_t dig_P9;

// Function prototypes
int init_bmp280();
int read_calibration_data();
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure);
void log_pressure(double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize BMP280 sensor
int init_bmp280() {
    int retries = 3;
    while (retries > 0) {
        // Verify chip ID
        char chip_id;
        if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CHIPID, &chip_id, 1) != 1) {
            fprintf(stderr, "Error reading chip ID\n");
            retries--;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (chip_id != BMP280_CHIP_ID) {
            fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
            retries--;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Set oversampling and mode
        char ctrl_meas = (BMP280_OVERSAMPLING_TEMP << 5) | (BMP280_OVERSAMPLING_PRESS << 2) | BMP280_MODE_NORMAL;
        if (i2cWriteI2CBlockData(i2c_handle, BMP280_REG_CTRL_MEAS, &ctrl_meas, 1) != 1) {
            fprintf(stderr, "Error writing control register\n");
            retries--;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Set filter and standby time (optional)
        char config = (0x02 << 5) | (0x04 << 2); // Filter = 4, Standby = 1000ms
        if (i2cWriteI2CBlockData(i2c_handle, BMP280_REG_CONFIG, &config, 1) != 1) {
            fprintf(stderr, "Error writing config register\n");
            retries--;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        printf("BMP280 initialized successfully\n");
        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize BMP280 after multiple retries\n");
    return -1; // Failure
}

// Read calibration data from BMP280
int read_calibration_data() {
    uint8_t data[26];
    if (i2cReadI2CBlockData(i2c_handle, 0x88, (char *)data, 26) != 26) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    dig_T1 = (data[1] << 8) | data[0];
    dig_T2 = (data[3] << 8) | data[2];
    dig_T3 = (data[5] << 8) | data[4];
    dig_P1 = (data[7] << 8) | data[6];
    dig_P2 = (data[9] << 8) | data[8];
    dig_P3 = (data[11] << 8) | data[10];
    dig_P4 = (data[13] << 8) | data[12];
    dig_P5 = (data[15] << 8) | data[14];
    dig_P6 = (data[17] << 8) | data[16];
    dig_P7 = (data[19] << 8) | data[18];
    dig_P8 = (data[21] << 8) | data[20];
    dig_P9 = (data[23] << 8) | data[22];

    return 0;
}

// Read raw temperature and pressure data
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESSURE_MSB, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    *temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    return 0;
}

// Temperature compensation
double compensate_temperature(int32_t raw_temperature) {
