#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3
#define BACKOFF_MS 10

// Global variables
static volatile int running = 1;
static int i2c_handle_tmp117 = -1;
static int i2c_handle_aht20 = -1;
static FILE *log_file = NULL;

// Function prototypes
int read_tmp117(float *temperature);
int read_aht20(float *humidity);
int read_pir(int *motion);
int log_data(float temperature, float humidity, int motion);
void signal_handler(int signal);
int setup();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Setup function to initialize pigpio and I2C
int setup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle_tmp117 = i2cOpen(1, TMP117_ADDR, 0);
    if (i2c_handle_tmp117 < 0) {
        fprintf(stderr, "Failed to open I2C device for TMP117: %d\n", i2c_handle_tmp117);
        // Continue even if TMP117 is not present
    }

    i2c_handle_aht20 = i2cOpen(1, AHT20_ADDR, 0);
    if (i2c_handle_aht20 < 0) {
        fprintf(stderr, "Failed to open I2C device for AHT20: %d\n", i2c_handle_aht20);
        // Continue even if AHT20 is not present
    }

    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle_tmp117 >= 0) {
        i2cClose(i2c_handle_tmp117);
    }
    if (i2c_handle_aht20 >= 0) {
        i2cClose(i2c_handle_aht20);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to read temperature from TMP117
int read_tmp117(float *temperature) {
    unsigned char buf[2];
    int retries = MAX_RETRIES;
    int result;

    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle_tmp117, 0x00, (char *)buf, 2);
        if (result == 2) {
            // Convert raw data to temperature (Celsius)
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            *temperature = raw_temp * 0.0078125;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (TMP117): %d, retries left: %d\n", result, retries);
            gpioDelay(BACKOFF_MS * 1000); // Backoff
            retries--;
        }
    }
    fprintf(stderr, "Failed to read TMP117 after multiple retries\n");
    return 1; // Failure
}

// Function to read humidity from AHT20
int read_aht20(float *humidity) {
    unsigned char buf[6];
    int retries = MAX_RETRIES;
    int result;

    // Trigger measurement
    buf[0] = 0xAC;
    buf[1] = 0x33;
    buf[2] = 0x00;
    if (i2cWriteDevice(i2c_handle_aht20, (char *)buf, 3) != 0) {
        fprintf(stderr, "Failed to trigger AHT20 measurement\n");
        return 1;
    }
    gpioDelay(80); // Wait for measurement (datasheet specifies 75ms)

    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle_aht20, 0x00, (char *)buf, 6);
        if (result == 6) {
            // Check status bit (bit 7 of byte 0)
            if (buf[0] & 0x80) {
                fprintf(stderr, "AHT20 busy\n");
                gpioDelay(BACKOFF_MS * 1000);
                retries--;
                continue;
            }

            // Convert raw data to humidity
            uint32_t raw_humidity = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | (buf[3] >> 4);
            *humidity = ((float)raw_humidity / 0x100000) * 100;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (AHT20): %d, retries left: %d\n", result, retries);
            gpioDelay(BACKOFF_MS * 1000); // Backoff
            retries--;
        }
    }
    fprintf(stderr, "Failed to read AHT20 after multiple retries\n");
    return 1; // Failure
}

// Function to read motion from PIR sensor
int read_pir(int *motion) {
    *motion = gpioRead(PIR_GPIO);
    return 0;
}

// Function to log data to CSV file
int log_data(float temperature, float humidity, int motion) {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[50];
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Create filename based on current date
    strftime(filename, sizeof(filename), "sensor_log_%Y-%m-%d.csv", timeinfo);

    // Create or open the log file
    if (log_file == NULL) {
        log_file = fopen(filename, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", filename);
            return 1;
        }

        // Write header if the file is newly created
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
        }
    }

    // Write data to the log file
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

int main() {
    float temperature, humidity;
    int motion;

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and I2C
    if (setup() != 0) {
        return 1;
    }

    printf("Sensor logger started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sensor data
        if (read_tmp117(&temperature) != 0) {
            temperature = -999.0; // Indicate error
        }
        if (read_aht20(&humidity) != 0) {
            humidity = -999.0; // Indicate error
        }
        if (read_pir(&motion) != 0) {
            motion = -1; // Indicate error
        }

        // Log the data
        if (log_data(temperature, humidity, motion) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Clean up resources before exiting
    cleanup();

    printf("Sensor logger stopped.\n");
    return 0;
}

