}

// Function to read motion from PIR sensor
int read_pir(int *motion) {
    *motion = gpioRead(PIR_GPIO);
    return 0;
}

// Function to log data to CSV file
int log_data(float temperature, float humidity, int motion) {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[50];
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Create filename based on current date
    strftime(filename, sizeof(filename), "sensor_log_%Y-%m-%d.csv", timeinfo);

    // Create or open the log file
    if (log_file == NULL) {
        log_file = fopen(filename, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", filename);
            return 1;
        }

        // Write header if the file is newly created
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
        }
    }

    // Write data to the log file
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

int main() {
    float temperature, humidity;
    int motion;

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and I2C
    if (setup() != 0) {
        return 1;
    }

    printf("Sensor logger started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sensor data
        if (read_tmp117(&temperature) != 0) {
            temperature = -999.0; // Indicate error
        }
        if (read_aht20(&humidity) != 0) {
            humidity = -999.0; // Indicate error
        }
        if (read_pir(&motion) != 0) {
            motion = -1; // Indicate error
        }

        // Log the data
        if (log_data(temperature, humidity, motion) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Clean up resources before exiting
    cleanup();

    printf("Sensor logger stopped.\n");
    return 0;
}

