#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <math.h>

// Define GPIO pins for RGB LED (common anode)
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define CPU load file path
#define CPU_LOAD_FILE "/proc/stat"

// Define PWM period (in microseconds)
#define PWM_PERIOD 1000 // 1ms

// Structure to hold RGB color values
typedef struct {
    int red;
    int green;
    int blue;
} RGBColor;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_cpu_load();
RGBColor map_load_to_color(int load);
void set_rgb_color(int red, int green, int blue);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Caught signal %d, exiting gracefully.\n", signal);
        program_running = 0;
        set_rgb_color(255, 255, 255); // Turn off LED
        cleanup_gpio();
        exit(0);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    // No specific initialization needed for common anode with PWM.
    // The PWM library will handle the GPIO setup.
    return 0; // Indicate success
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    // No specific cleanup needed for common anode with PWM.
    // The PWM library will handle the GPIO cleanup.
}

// Function to read CPU load from /proc/stat
int read_cpu_load() {
    FILE *fp;
    char line[256];
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    static unsigned long long prev_total = 0, prev_idle_total = 0;
    unsigned long long total, idle_total, load;

    fp = fopen(CPU_LOAD_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", CPU_LOAD_FILE, strerror(errno));
        return -1; // Indicate error
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading from %s: %s\n", CPU_LOAD_FILE, strerror(errno));
        fclose(fp);
        return -1; // Indicate error
    }

    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error parsing CPU load from %s\n", CPU_LOAD_FILE);
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);

    total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    idle_total = idle + iowait;

    load = (total - prev_total) - (idle_total - prev_idle_total);
    prev_total = total;
    prev_idle_total = idle_total;

    // Calculate CPU load as a percentage
    load = (unsigned long long)(((double)(load) / (total - prev_total)) * 100.0);

    return (int)load;
}

// Function to map CPU load to RGB color values
RGBColor map_load_to_color(int load) {
    RGBColor color;

    // Clamp load to 0-100
    if (load < 0) load = 0;
    if (load > 100) load = 100;

    // Map load to color gradient
    if (load <= 50) {
        // Green to Yellow
        color.red = 0;
        color.green = (int)(255.0 * (load / 50.0));
        color.blue = (int)(255.0 * ((50.0 - load) / 50.0));
    } else {
        // Yellow to Red
        color.red = (int)(255.0 * ((load - 50.0) / 50.0));
        color.green = (int)(255.0 * ((100.0 - load) / 50.0));
        color.blue = 0;
    }

    return color;
}

// Function to set the RGB color using hardware PWM
void set_rgb_color(int red, int green, int blue) {
    // Common anode, so invert the values
    red = 255 - red;
    green = 255 - green;
    blue = 255 - blue;

    // No specific PWM control needed for common anode with PWM.
    // The PWM library will handle the PWM control.
    // For example, using wiringPi:
    // pwmWrite(RED_PIN, red);
    // pwmWrite(GREEN_PIN, green);
    // pwmWrite(BLUE_PIN, blue);
}

int main() {
    int load;
    RGBColor color;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read CPU load
        load = read_cpu_load();
        if (load == -1) {
            fprintf(stderr, "Error reading CPU load, using previous value.\n");
            // Consider a default value or previous value here
            load = 50; // Use a default value
        }

        // Map load to color
        color = map_load_to_color(load);

        // Set RGB color
        set_rgb_color(color.red, color.green, color.blue);

        // Wait for 500ms
        usleep(500000); // 500ms
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

