#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_ID 0xD0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variables
int i2c_handle;
int udp_socket;
struct sockaddr_in server_addr;
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t dig_T1, dig_T2, dig_T3;
int16_t dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;

// Function prototypes
int init_bmp280();
int read_calibration_data();
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, double t_fine);
char* format_json(double temperature, double pressure);
int send_udp_packet(const char *json_string);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize BMP280 sensor
int init_bmp280() {
    // Check sensor ID
    int id = i2cReadByteData(i2c_handle, BMP280_REG_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", id);
        return -1;
    }
    if (id != 0x58) {
        fprintf(stderr, "Incorrect sensor ID: 0x%X\n", id);
        return -1;
    }

    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure sensor (oversampling, mode)
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CONFIG, 0x04 | (0x02 << 3)) < 0) { // t_sb = 0.5ms, filter = x4
        fprintf(stderr, "Error configuring sensor\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) { // osrs_t = x1, osrs_p = x1, normal mode
        fprintf(stderr, "Error configuring sensor\n");
        return -1;
    }

    return 0;
}

// Read calibration data from BMP280
int read_calibration_data() {
    uint8_t data[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, (char *)data, 26) < 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    dig_T1 = (data[1] << 8) | data[0];
    dig_T2 = (data[3] << 8) | (int8_t)data[2];
    dig_T3 = (data[5] << 8) | (int8_t)data[4];
    dig_P1 = (data[7] << 8) | data[6];
    dig_P2 = (data[9] << 8) | (int8_t)data[8];
    dig_P3 = (data[11] << 8) | (int8_t)data[10];
    dig_P4 = (data[13] << 8) | (int8_t)data[12];
    dig_P5 = (data[15] << 8) | (int8_t)data[14];
    dig_P6 = (data[17] << 8) | (int8_t)data[16];
    dig_P7 = (data[19] << 8) | (int8_t)data[18];
    dig_P8 = (data[21] << 8) | (int8_t)data[20];
    dig_P9 = (data[23] << 8) | (int8_t)data[22];

    return 0;
}

// Read raw temperature and pressure data from BMP280
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, (char *)data, 6) < 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

