#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define FAN_GPIO 18       // BCM GPIO 18
#define FAN_PWM_RANGE 255
#define FAN_PWM_CLOCK 192  // 19.2 MHz / 192 = 100 kHz
#define TEMP_READ_INTERVAL 1 // seconds

// Temperature thresholds for fan control
#define TEMP_LOW 25.0
#define TEMP_MED_LOW 40.0
#define TEMP_MED_HIGH 60.0
#define TEMP_HIGH 60.0

// Circular buffer size
#define BUFFER_SIZE 20

// Data structure for the circular buffer
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} buffer_entry_t;

// Circular buffer
buffer_entry_t buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0; // Number of elements currently in the buffer

// Function prototypes
int read_max31855(int channel, float *temperature);
int calculate_duty_cycle(float temperature);
void update_fan(int duty_cycle);
void add_to_buffer(time_t timestamp, float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Global variable for SPI file descriptor
int spi_fd = -1;

// Function to read temperature from MAX31855
int read_max31855(int channel, float *temperature) {
    unsigned char data[4];
    int result;

    // Read 4 bytes from the SPI channel
    result = wiringPiSPIDataRW(channel, data, 4);
    if (result == -1) {
        fprintf(stderr, "Error reading SPI data: %s\n", strerror(errno));
        return -1;
    }

    // Check for fault conditions
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        return -1;
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -1;
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1;
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    *temperature = raw_temp * 0.25;

    return 0;
}

// Function to calculate duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle = 0;

    if (temperature < TEMP_LOW) {
        duty_cycle = 0;
    } else if (temperature < TEMP_MED_LOW) {
        duty_cycle = (int)((temperature - TEMP_LOW) / (TEMP_MED_LOW - TEMP_LOW) * 50.0);
    } else if (temperature < TEMP_MED_HIGH) {
        duty_cycle = (int)(50.0 + (temperature - TEMP_MED_LOW) / (TEMP_MED_HIGH - TEMP_MED_LOW) * 50.0);
    } else if (temperature > TEMP_HIGH) {
        duty_cycle = 255;
    } else {
        duty_cycle = 100;
    }

    return duty_cycle;
}

// Function to update the fan speed using hardware PWM
void update_fan(int duty_cycle) {
    pwmWrite(FAN_GPIO, duty_cycle);
}

// Function to add data to the circular buffer
void add_to_buffer(time_t timestamp, float temperature, int duty_cycle) {
    buffer[buffer_index].timestamp = timestamp;
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].duty_cycle = duty_cycle;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Circular Buffer Contents ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE; // Calculate correct index
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&buffer[index].timestamp));
        printf("[%s] Temperature: %.2f°C, Duty Cycle: %d\n", timestamp_str, buffer[index].temperature, buffer[index].duty_cycle);
    }
    printf("--- End of Buffer ---\n\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Stop the fan
    update_fan(0);

    // Close SPI interface
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Print the buffer
    print_buffer();

    // Terminate the wiringPi library
    wiringPiSetup(); // Reinitialize to allow cleanup
    wiringPiSPIClose(SPI_CHANNEL);

    exit(0);
}

int main() {
    float temperature;
    int duty_cycle;

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd == -1) {
        fprintf(stderr, "Error initializing SPI: %s\n", strerror(errno));
        return 1;
    }

    // Configure PWM on GPIO18
    pinMode(FAN_GPIO, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetClock(FAN_PWM_CLOCK);
    pwmSetRange(FAN_PWM_RANGE);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Temperature-controlled fan control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read temperature from MAX31855
        if (read_max31855(SPI_CHANNEL, &temperature) == 0) {
            // Calculate duty cycle
            duty_cycle = calculate_duty_cycle(temperature);

            // Update fan speed
            update_fan(duty_cycle);

            // Add data to the circular buffer
            time_t now = time(NULL);
            add_to_buffer(now, temperature, duty_cycle);

            printf("Temperature: %.2f°C, Duty Cycle: %d\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "Error reading temperature, skipping fan update.\n");
        }

        // Wait for 1 second
        delay(TEMP_READ_INTERVAL * 1000);
    }

    return 0;
}

