  if (read_uword(i2c_handle, BMP180_REG_CAL_AC6, &ac6) != 0) return -1;
  if (read_word(i2c_handle, BMP180_REG_CAL_B1, &b1) != 0) return -1;
  if (read_word(i2c_handle, BMP180_REG_CAL_B2, &b2) != 0) return -1;
  if (read_word(i2c_handle, BMP180_REG_CAL_MB, &mb) != 0) return -1;
  if (read_word(i2c_handle, BMP180_REG_CAL_MC, &mc) != 0) return -1;
  if (read_word(i2c_handle, BMP180_REG_CAL_MD, &md) != 0) return -1;

  return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int32_t *raw_temp) {
  if (write_register(i2c_handle, BMP180_REG_CONTROL, 0x2E) != 0) return -1;
  gpioDelay(5000); // Wait 4.5ms
  if (read_word(i2c_handle, BMP180_REG_MSB, (int16_t *)raw_temp) != 0) return -1;
