  log_file = fopen("altitude_log.txt", "a");
  if (log_file == NULL) {
    fprintf(stderr, "Error opening log file\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    return 1;
  }

  // Register signal handler
  signal(SIGINT, signal_handler);

  // Main loop
  while (1) {
    if (logging_active) {
      int32_t raw_temp, raw_pressure;
      double temperature, pressure, altitude;
      time_t rawtime;
      struct tm *timeinfo;
      char timestamp[80];

      // Read raw temperature and pressure
      if (read_raw_temperature(&raw_temp) != 0) {
        fprintf(stderr, "Error reading raw temperature\n");
        continue;
      }
      if (read_raw_pressure(&raw_pressure) != 0) {
        fprintf(stderr, "Error reading raw pressure\n");
        continue;
      }

      // Calculate temperature and pressure
      temperature = calculate_temperature(raw_temp);
      pressure = calculate_pressure(raw_pressure, raw_temp);

      // Calculate altitude
      altitude = calculate_altitude(pressure);

      // Get current timestamp
      time(&rawtime);
      timeinfo = localtime(&rawtime);
      strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

      // Write data to log file
      fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
      fflush(log_file); // Ensure data is written to disk

      printf("%s,%.2f,%.2f,%.2f\n", timestamp, temperature, pressure, altitude);
    }

    gpioDelay(1000000); // Wait 1 second
  }

  return 0;
}

