#define CE_GPIO 8
#define RTD_NOMINAL 100.0
#define A 3.9083e-3
#define B -5.775e-7
#define C -4.183e-12
#define D 0.0
#define FAULT_TEMP_MIN -50.0
#define FAULT_TEMP_MAX 125.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_register(int handle, uint8_t reg);
int spi_write_register(int handle, uint8_t reg, uint8_t value);
float read_rtd_temperature(int handle);
void log_data(FILE *fp, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// SPI read register function
int spi_read_register(int handle, uint8_t reg) {
    char tx[2], rx[2];
    tx[0] = reg | 0x80; // Set MSB for read operation
    tx[1] = 0x00;       // Dummy byte for reading

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI read error: %d\n", spiXfer(handle, tx, rx, 2));
        return -1;
    }

    return rx[1];
}

// SPI write register function
int spi_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx[2];
    tx[0] = reg & 0x7F; // Clear MSB for write operation
    tx[1] = value;

    if (spiXfer(handle, tx, NULL, 2) != 0) {
        fprintf(stderr, "SPI write error: %d\n", spiXfer(handle, tx, NULL, 2));
        return -1;
    }

    return 0;
}

// Read RTD temperature function
float read_rtd_temperature(int handle) {
    int rtd_value;
    float rtd_resistance, temperature;

    rtd_value = spi_read_register(handle, 0x01); // Read RTD MSB
    if (rtd_value < 0) return -273.15; // Indicate error

    rtd_value = (rtd_value << 8) | spi_read_register(handle, 0x02); // Read RTD LSB
    if (rtd_value < 0) return -273.15; // Indicate error

    // Check for fault conditions
    int fault_status = spi_read_register(handle, 0x07);
    if (fault_status < 0) return -273.15; // Indicate error

    if (fault_status & 0x07) {
