        if (fault_status & 0x02) fprintf(stderr, "  RTD Low Threshold\n");
        if (fault_status & 0x04) fprintf(stderr, "  RTD Fault\n");
        return -273.15; // Indicate error
    }

    // Extract RTD resistance (see MAX31865 datasheet)
    rtd_resistance = (float)rtd_value * 400.0 / 32768.0; // Assuming 400 Ohm reference resistor

    // Callendar-Van Dusen equation
    temperature = (rtd_resistance / RTD_NOMINAL);
    temperature = A + B * temperature + C * temperature * temperature + D * temperature * temperature * temperature;
    temperature = temperature - 273.15; // Convert to Celsius

