        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C)\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_rtd_temperature(spi_handle);

        if (temperature > FAULT_TEMP_MIN && temperature < FAULT_TEMP_MAX) {
            log_data(log_file, temperature);
        } else {
            fprintf(stderr, "Invalid temperature reading: %.2f\n", temperature);
        }

        sleep(5);
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

