// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize BME280 sensor
int init_bme280() {
    int chip_id;

    // Check if the BME280 is present
    chip_id = i2cReadByteData(i2c_handle, BME280_REG_CHIPID);
    if (chip_id < 0) {
        fprintf(stderr, "Error reading chip ID: %d\n", chip_id);
        return -1;
    }

    if (chip_id != 0x60) {
        fprintf(stderr, "Incorrect chip ID: 0x%X\n", chip_id);
        return -1;
    }

    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, BME280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(10); // Wait for the reset to complete

    // Set humidity control register
    if (i2cWriteByteData(i2c_handle, BME280_REG_CTRL_HUM, 0x01) < 0) {
        fprintf(stderr, "Error writing to humidity control register\n");
        return -1;
    }

    // Set control measurement register
    if (i2cWriteByteData(i2c_handle, BME280_REG_CTRL_MEAS, 0x27) < 0) { // Oversampling x1, Normal mode
        fprintf(stderr, "Error writing to control measurement register\n");
        return -1;
    }

    // Set config register
    if (i2cWriteByteData(i2c_handle, BME280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to config register\n");
        return -1;
    }

    return 0;
}

// Read calibration data from the sensor
int read_calibration_data() {
    uint8_t buffer[26];
    uint8_t buffer_h[7];

    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_CALIB_00, (char *)buffer, 26) < 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_CALIB_26, (char *)buffer_h, 7) < 0) {
        fprintf(stderr, "Error reading humidity calibration data\n");
        return -1;
    }

    calib.dig_T1 = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    calib.dig_T2 = (int16_t)buffer[2] | ((int16_t)buffer[3] << 8);
    calib.dig_T3 = (int16_t)buffer[4] | ((int16_t)buffer[5] << 8);
    calib.dig_P1 = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);
    calib.dig_P2 = (int16_t)buffer[8] | ((int16_t)buffer[9] << 8);
    calib.dig_P3 = (int16_t)buffer[10] | ((int16_t)buffer[11] << 8);
    calib.dig_P4 = (int16_t)buffer[12] | ((int16_t)buffer[13] << 8);
    calib.dig_P5 = (int16_t)buffer[14] | ((int16_t)buffer[15] << 8);
    calib.dig_P6 = (int16_t)buffer[16] | ((int16_t)buffer[17] << 8);
    calib.dig_P7 = (int16_t)buffer[18] | ((int16_t)buffer[19] << 8);
    calib.dig_P8 = (int16_t)buffer[20] | ((int16_t)buffer[21] << 8);
    calib.dig_P9 = (int16_t)buffer[22] | ((int16_t)buffer[23] << 8);
    calib.dig_H1 = buffer[25];
    calib.dig_H2 = (int16_t)buffer_h[0] | ((int16_t)buffer_h[1] << 8);
    calib.dig_H3 = buffer_h[2];
    calib.dig_H4 = (int16_t)((buffer_h[3] << 4) | (buffer_h[4] & 0x0F));
    calib.dig_H5 = (int16_t)((buffer_h[5] << 4) | (buffer_h[4] >> 4));
    calib.dig_H6 = (int8_t)buffer_h[6];

    return 0;
}

// Read raw temperature, pressure and humidity data from the sensor
int read_raw_data(int32_t *temperature, int32_t *pressure, int32_t *humidity) {
    uint8_t buffer[8];

    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_DATA_PRESS_MSB, (char *)buffer, 8) < 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = (int32_t)((((uint32_t)buffer[0]) << 12) | (((uint32_t)buffer[1]) << 4) | ((uint32_t)buffer[2] >> 4));
    *temperature = (int32_t)((((uint32_t)buffer[3]) << 12) | (((uint32_t)buffer[4]) << 4) | ((uint32_t)buffer[5] >> 4));
    *humidity = (int32_t)(((uint32_t)buffer[6] << 8) | ((uint32_t)buffer[7]));

