#define BMP180_ADDR 0x77
#define GPIO_ALERT 24
#define SAMPLE_INTERVAL_MS 50
#define BUFFER_SIZE 60
#define ALERT_THRESHOLD 5.0f

// BMP180 Registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 Commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 // Oss = 0
#define BMP180_CMD_PRESSURE1 0x74 // Oss = 1
#define BMP180_CMD_PRESSURE2 0xB4 // Oss = 2
#define BMP180_CMD_PRESSURE3 0xF4 // Oss = 3

// Calibration Data Structure
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

// Circular Buffer Structure
typedef struct {
    time_t timestamp[BUFFER_SIZE];
    float pressure[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global Variables
int i2c_handle;
bmp180_calibration_data_t calibration_data;
circular_buffer_t pressure_buffer;
bool running = true;

// Function Prototypes
int read_calibration_data(int i2c_handle, bmp180_calibration_data_t *calibration_data);
int read_raw_temperature(int i2c_handle);
int read_raw_pressure(int i2c_handle, uint8_t oss);
float calculate_true_temperature(int32_t ut, bmp180_calibration_data_t calibration_data);
float calculate_true_pressure(int32_t up, int32_t ut, bmp180_calibration_data_t calibration_data, uint8_t oss);
void add_to_buffer(circular_buffer_t *buffer, time_t timestamp, float pressure);
float calculate_rolling_average(circular_buffer_t *buffer);
void trigger_alert(int gpio_pin);
void log_error(const char *message);
void signal_handler(int signal);
void timer_callback();

// Function Implementations

// Function to read calibration data from the BMP180
int read_calibration_data(int i2c_handle, bmp180_calibration_data_t *calibration_data) {
    char data[22];
    if (i2cReadI2CBlockData(i2c_handle, 0xAA, data, 22) != 22) {
        log_error("Failed to read calibration data");
        return -1;
    }

    calibration_data->ac1 = (data[0] << 8) | data[1];
    calibration_data->ac2 = (data[2] << 8) | data[3];
    calibration_data->ac3 = (data[4] << 8) | data[5];
    calibration_data->ac4 = (data[6] << 8) | data[7];
    calibration_data->ac5 = (data[8] << 8) | data[9];
    calibration_data->ac6 = (data[10] << 8) | data[11];
    calibration_data->b1 = (data[12] << 8) | data[13];
    calibration_data->b2 = (data[14] << 8) | data[15];
    calibration_data->mb = (data[16] << 8) | data[17];
    calibration_data->mc = (data[18] << 8) | data[19];
    calibration_data->md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int i2c_handle) {
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = BMP180_CMD_TEMP;

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf+1, 1) != 1) {
        log_error("Failed to write temperature command");
        return -1;
    }

    gpioDelay(5000); // Wait 5ms

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        log_error("Failed to write read temperature command");
        return -1;
    }

    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 2) != 2) {
        log_error("Failed to read raw temperature data");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int i2c_handle, uint8_t oss) {
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    switch (oss) {
        case 0: buf[1] = BMP180_CMD_PRESSURE0; break;
        case 1: buf[1] = BMP180_CMD_PRESSURE1; break;
        case 2: buf[1] = BMP180_CMD_PRESSURE2; break;
        case 3: buf[1] = BMP180_CMD_PRESSURE3; break;
        default: buf[1] = BMP180_CMD_PRESSURE0; break;
    }

    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf+1, 1) != 1) {
        log_error("Failed to write pressure command");
        return -1;
    }

    gpioDelay(2 + (3 << oss)); // Wait for conversion

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        log_error("Failed to write read pressure command");
        return -1;
    }

    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3) != 3) {
        log_error("Failed to read raw pressure data");
        return -1;
    }

    return ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - oss);
}

// Function to calculate true temperature in degrees Celsius
float calculate_true_temperature(int32_t ut, bmp180_calibration_data_t calibration_data) {
    int32_t x1 = (((int32_t)ut - (int32_t)calibration_data.ac6) * (int32_t)calibration_data.ac5) >> 15;
    int32_t x2 = ((int32_t)calibration_data.mc << 11) / (x1 + calibration_data.md);
    int32_t b5 = x1 + x2;
    float temperature = ((b5 + 8) >> 4) / 10.0f;
    return temperature;
}

// Function to calculate true pressure in Pascals
float calculate_true_pressure(int32_t up, int32_t ut, bmp180_calibration_data_t calibration_data, uint8_t oss) {
    int32_t x1 = (((int32_t)ut - (int32_t)calibration_data.ac6) * (int32_t)calibration_data.ac5) >> 15;
    int32_t x2 = ((int32_t)calibration_data.mc << 11) / (x1 + calibration_data.md);
    int32_t b5 = x1 + x2;

    int32_t b6 = b5 - 4000;
    x1 = (calibration_data.b2 * (b6 * b6) >> 12) >> 11;
    x2 = (calibration_data.ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)calibration_data.ac1) * 4 + x3) << oss) + 2) >> 2;

    x1 = (calibration_data.ac3 * b6) >> 13;
    x2 = (calibration_data.b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = (calibration_data.ac4 * (uint32_t)(x3 + 32768)) >> 15;

    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> oss);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    float pressure = p + ((x1 + x2 + 3791) >> 4);

    return pressure;
}

// Function to add a new reading to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, time_t timestamp, float pressure) {
    buffer->timestamp[buffer->head] = timestamp;
    buffer->pressure[buffer->head] = pressure;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to calculate the rolling average of the pressure readings
float calculate_rolling_average(circular_buffer_t *buffer) {
    if (buffer->count == 0) {
        return 0.0f;
    }

    float sum = 0.0f;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->pressure[i];
    }
    return sum / buffer->count;
}

// Function to trigger the alert by setting GPIO24 HIGH
void trigger_alert(int gpio_pin) {
    gpioWrite(gpio_pin, 1);
    gpioDelay(1000); // 1 second
    gpioWrite(gpio_pin, 0);
}

// Function to log errors to stderr
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "%d-%02d-%02d %02d:%02d:%02d: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = false;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Timer callback function
void timer_callback() {
    // Read raw temperature and pressure
    int32_t ut = read_raw_temperature(i2c_handle);
    int32_t up = read_raw_pressure(i2c_handle, 3); // Oss = 3

    if (ut == -1 || up == -1) {
        log_error("Failed to read sensor data");
        return;
    }

    // Calculate true temperature and pressure
    float temperature = calculate_true_temperature(ut, calibration_data);
    float pressure = calculate_true_pressure(up, ut, calibration_data, 3);

    // Get current timestamp
    time_t now = time(NULL);

    // Add reading to circular buffer
    add_to_buffer(&pressure_buffer, now, pressure);

    // Calculate rolling average
    float rolling_average = calculate_rolling_average(&pressure_buffer);

    // Check for alert condition
    if (fabs(pressure - rolling_average) > ALERT_THRESHOLD) {
        printf("Alert: Pressure deviation detected! Current: %.2f hPa, Average: %.2f hPa\n", pressure, rolling_average);
        trigger_alert(GPIO_ALERT);
    }

    printf("Pressure: %.2f hPa, Rolling Average: %.2f hPa\n", pressure, rolling_average);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle, &calibration_data) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    pressure_buffer.head = 0;
    pressure_buffer.count = 0;

    // Set GPIO24 as output
    gpioSetMode(GPIO_ALERT, PI_OUTPUT);
    gpioWrite(GPIO_ALERT, 0); // Ensure it starts LOW

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up timer callback function
    gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, timer_callback, NULL);

    // Main loop
    while (running) {
        sleep(1); // Sleep for 1 second
    }

    // Clean up resources
    gpioSetTimerFuncEx(0, 0, NULL, NULL); // Disable timer
    i2cClose(i2c_handle);
    gpioWrite(GPIO_ALERT, 0); // Reset GPIO
    gpioTerminate();

    return 0;
}

