    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("bmp180_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up hardware timer interrupt (every 500ms)
    gpioSetTimerFuncEx(0, 500, timer_interrupt_handler, NULL);

    // Main loop
    while (!terminate) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // Clean up resources
    gpioSetTimerFuncEx(0, 500, NULL, NULL); // Disable timer
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

