// Function to read a 16-bit value from the I2C bus
int read_i2c_word(int handle, uint8_t reg, int16_t *value) {
    char buf[2];
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read a 16-bit value from the I2C bus
int read_i2c_uword(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data() {
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC1, &calibration_data.ac1) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC2, &calibration_data.ac2) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_AC3, &calibration_data.ac3) != 0) return -1;
    if (read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC4, &calibration_data.ac4) != 0) return -1;
    if (read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC5, &calibration_data.ac5) != 0) return -1;
    if (read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC6, &calibration_data.ac6) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_B1, &calibration_data.b1) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_B2, &calibration_data.b2) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MB, &calibration_data.mb) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MC, &calibration_data.mc) != 0) return -1;
    if (read_i2c_word(i2c_handle, BMP180_REG_CAL_MD, &calibration_data.md) != 0) return -1;

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int32_t *raw_temp) {
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing temperature command to I2C device.\n");
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms (minimum)

    char data[2];
    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device for temperature read.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading temperature data from I2C device.\n");
        return -1;
    }

    *raw_temp = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int32_t *raw_pressure) {
    char buf[1];
    buf[0] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing pressure command to I2C device.\n");
        return -1;
    }
    gpioDelay(2 + (3 << BMP180_OSS)); // Wait for conversion

    char data[3];
    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device for pressure read.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 3) != 3) {
        fprintf(stderr, "Error reading pressure data from I2C device.\n");
        return -1;
    }

    *raw_pressure = ((int32_t)data[0] << 16 | (int32_t)data[1] << 8 | (int32_t)data[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int32_t raw_temp) {
    int32_t X1 = (((int32_t)raw_temp - (int32_t)calibration_data.ac6) * (int32_t)calibration_data.ac5) >> 15;
    int32_t X2 = ((int32_t)calibration_data.mc << 11) / (X1 + calibration_data.md);
    int32_t B5 = X1 + X2;
    double temperature = ((B5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in pascals
double calculate_pressure(int32_t raw_pressure, double temperature) {
    int32_t B6 = (int32_t)temperature * 10 - 400;
    int32_t X1 = ((int32_t)calibration_data.b2 * (B6 * B6) >> 12) >> 11;
    int32_t X2 = ((int32_t)calibration_data.ac2 * B6) >> 11;
    int32_t X3 = X1 + X2;
    int32_t B3 = (((((int32_t)calibration_data.ac1) * 4 + X3) << BMP180_OSS) + 2) >> 2;
    uint32_t X1_u = ((uint32_t)calibration_data.ac3 * B6) >> 13;
    uint32_t X2_u = ((uint32_t)calibration_data.b1 * ((B6 * B6) >> 12)) >> 16;
    uint32_t X3_u = ((X1_u + X2_u) + 2) >> 2;
    uint32_t B4 = ((uint32_t)calibration_data.ac4 * (X3_u + 32768)) >> 15;
    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (B7 < 0x80000000) {
        p = (B7 * 2) / B4;
    } else {
        p = (B7 / B4) * 2;
    }
    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    double pressure = p + ((X1 + X2 + 3791) >> 4);
    return pressure;
}

// Function to log data to a file
void log_data(double temperature, double pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Pressure: %.2f Pa\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, pressure);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Timer interrupt handler
void timer_interrupt_handler() {
    int32_t raw_temp, raw_pressure;
    double temperature, pressure;

    if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
        temperature = calculate_temperature(raw_temp);
        pressure = calculate_pressure(raw_pressure, temperature);
        log_data(temperature, pressure);
    } else {
        fprintf(stderr, "Error reading sensor data.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("bmp180_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up hardware timer interrupt (every 500ms)
    gpioSetTimerFuncEx(0, 500, timer_interrupt_handler, NULL);

    // Main loop
    while (!terminate) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // Clean up resources
    gpioSetTimerFuncEx(0, 500, NULL, NULL); // Disable timer
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

