        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        temp = read_cpu_temp();
        if (temp == -1) {
            fprintf(stderr, "Failed to read CPU temperature, using previous value or 40°C\n");
            // Handle error, maybe use a default value or previous value
            temp = 40; // Or some other appropriate default
        }

        duty_cycle = map_temp_to_duty(temp);
        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Failed to set fan speed\n");
        }

        if (log_data(temp, duty_cycle) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        sleep(5);
    }

    set_fan_speed(0); // Stop the fan

    if (log_fp != NULL) {
        fclose(log_fp);
    }

    gpioTerminate();
    return 0;
}

