#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define ALERT_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0f
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
float running_average = 0.0f;
pthread_mutex_t buffer_mutex;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
float read_temperature();
void update_buffer(float temperature);
float calculate_running_average();
void control_alert_led(float average_temperature);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read temperature from LM75
float read_temperature() {
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -100.0f; // Indicate error
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits
    float temperature = raw_temp * 0.125f;

    return temperature;
}

// Function to update the circular buffer
void update_buffer(float temperature) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

// Function to calculate the running average
float calculate_running_average() {
    pthread_mutex_lock(&buffer_mutex);
    float sum = 0.0f;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    pthread_mutex_unlock(&buffer_mutex);
    return sum / BUFFER_SIZE;
}

// Function to control the alert LED
void control_alert_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(ALERT_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(ALERT_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    i2cClose(i2c_handle);
    gpioWrite(ALERT_GPIO, 0); // Ensure LED is off
    gpioSetMode(ALERT_GPIO, PI_INPUT); // Release GPIO
    pthread_mutex_destroy(&buffer_mutex);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO for alert LED
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);

    // Initialize mutex
    if (pthread_mutex_init(&buffer_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -99.0f) { // Check for valid temperature reading
            update_buffer(temperature);
            running_average = calculate_running_average();
            control_alert_led(running_average);
            printf("Temperature: %.2f C, Running Average: %.2f C\n", temperature, running_average);
        } else {
            fprintf(stderr, "Failed to read temperature, attempting re-initialization...\n");
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting...\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

