#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <jansson.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 500000  // 500 kHz
#define HEATER_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000
#define MAX_TEMP 80.0
#define MAX_RTD 100.0
#define MAX_RESISTANCE 430.0
#define PID_SAMPLE_INTERVAL 100 // ms

// PID Gains
double Kp = 1.0;
double Ki = 0.1;
double Kd = 0.01;

// Target Temperature
double target_temperature = 25.0;

// SPI Handle
int spi_handle;

// File Descriptors for Logging
FILE *error_log_file = NULL;
FILE *data_log_file = NULL;

// Function Prototypes
int read_config(const char *filename);
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature);
void set_heater_pwm(int duty_cycle);
void signal_handler(int signal);
void log_error(const char *message);
void log_data(double temperature, double setpoint, double pid_output);

// PID Variables
double integral = 0.0;
double previous_error = 0.0;

// Function to read configuration from JSON file
int read_config(const char *filename) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        return -1;
    }

    json_t *target_temp_json = json_object_get(root, "target_temperature");
    if (target_temp_json) {
        target_temperature = json_real_value(target_temp_json);
    } else {
        fprintf(stderr, "Warning: target_temperature not found in config file, using default: %.2f\n", target_temperature);
    }

    json_t *kp_json = json_object_get(root, "Kp");
    if (kp_json) {
        Kp = json_real_value(kp_json);
    } else {
        fprintf(stderr, "Warning: Kp not found in config file, using default: %.2f\n", Kp);
    }

    json_t *ki_json = json_object_get(root, "Ki");
    if (ki_json) {
        Ki = json_real_value(ki_json);
    } else {
        fprintf(stderr, "Warning: Ki not found in config file, using default: %.2f\n", Ki);
    }

    json_t *kd_json = json_object_get(root, "Kd");
    if (kd_json) {
        Kd = json_real_value(kd_json);
    } else {
        fprintf(stderr, "Warning: Kd not found in config file, using default: %.2f\n", Kd);
    }

    json_decref(root);
    return 0;
}

// Function to read temperature from MAX31865 via SPI
double read_temperature() {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];
    int rtd_raw;
    double resistance, temperature;

    // Read RTD MSB and LSB registers (0x01 and 0x02)
    tx_buffer[0] = 0x01 | 0x80; // Read command for register 0x01
    tx_buffer[1] = 0x00; // Dummy byte
    tx_buffer[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        log_error("SPI read failed");
        return -1000.0; // Indicate error
    }

    rtd_raw = ((rx_buffer[1] << 8) | rx_buffer[2]) >> 1; // Combine MSB and LSB, remove fault bit

    // Check for fault
    if (rx_buffer[1] & 0x04) {
        log_error("MAX31865 Fault detected");
        return -1000.0; // Indicate error
    }

    // Convert RTD value to resistance (PT100)
    resistance = ((double)rtd_raw / 32768.0) * MAX_RESISTANCE;

    // Convert resistance to temperature (PT100 approximation)
    temperature = (resistance - 100.0) / 0.385; // Linear approximation

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    integral += error * Ki;
    double derivative = (error - previous_error) * Kd;
    double output = Kp * error + integral + derivative;
    previous_error = error;

    // Clamp output to PWM range
    if (output < 0) output = 0;
    if (output > PWM_RANGE) output = PWM_RANGE;

    return output;
}

// Function to set heater PWM duty cycle
void set_heater_pwm(int duty_cycle) {
    gpioPWM(HEATER_GPIO, duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    set_heater_pwm(0); // Turn off heater
    spiClose(spi_handle); // Close SPI
    gpioTerminate(); // Terminate pigpio
    if (error_log_file) fclose(error_log_file);
    if (data_log_file) fclose(data_log_file);
    exit(0);
}

// Function to log errors to file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(error_log_file, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(error_log_file);
    fprintf(stderr, "ERROR: %s\n", message);
}

// Function to log data to file
void log_data(double temperature, double setpoint, double pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(data_log_file, "[%d-%02d-%02d %02d:%02d:%02d] Temperature: %.2f, Setpoint: %.2f, PID Output: %.2f\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, temperature, setpoint, pid_output);
    fflush(data_log_file);
}

int main() {
    double temperature, pid_output;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_log_file = fopen("error.log", "a");
    if (!error_log_file) {
        fprintf(stderr, "Error opening error log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open data log file
    data_log_file = fopen("data.log", "a");
    if (!data_log_file) {
        fprintf(stderr, "Error opening data log file\n");
        fclose(error_log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Read configuration from file
    if (read_config("config.json") != 0) {
        log_error("Failed to read config.json, using default values");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read temperature
        temperature = read_temperature();
        if (temperature < -999.0) {
            log_error("Failed to read temperature, exiting");
            break;
        }

        // Check for temperature limit
        if (temperature > MAX_TEMP) {
            log_error("Temperature exceeded limit, shutting down");
            set_heater_pwm(0);
            break;
        }

        // Calculate PID output
        pid_output = calculate_pid(target_temperature, temperature);

        // Set heater PWM
        duty_cycle = (int)pid_output;
        set_heater_pwm(duty_cycle);

        // Log data
        log_data(temperature, target_temperature, pid_output);

        // Wait for next sample
        gpioDelay(PID_SAMPLE_INTERVAL * 1000); // Convert ms to us
    }

    // Cleanup
    set_heater_pwm(0);
    spiClose(spi_handle);
    gpioTerminate();
    fclose(error_log_file);
    fclose(data_log_file);

    return 0;
}

