// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration data
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int bmp180_read_raw_temperature(int fd, int32_t *raw_temp);
int bmp180_read_raw_pressure(int fd, int32_t *raw_pressure);
int bmp180_calculate_temperature(int32_t raw_temp, int32_t *calculated_temp);
int bmp180_calculate_pressure(int32_t raw_pressure, int32_t raw_temp, int32_t *calculated_pressure);
void log_breach(const char *message);
void signal_handler(int sig);
int bmp180_init(int fd);

// I2C read function with retry and error handling
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 3;
    int result;
    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("Failed to write register address");
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }

        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            perror("Failed to read data");
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    return -1; // Failure after retries
}

// I2C write function with retry and error handling
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    int retries = 3;
    int result;
    while (retries > 0) {
        uint8_t buf[2] = {reg, value};
        result = write(fd, buf, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            perror("Failed to write data");
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    return -1; // Failure after retries
}

// BMP180 read raw temperature function
int bmp180_read_raw_temperature(int fd, int32_t *raw_temp) {
    uint8_t data[2];
    if (i2c_write_byte(fd, BMP180_REG_CONTROL, 0x2E) != 0) {
        perror("Failed to write temperature read command");
        return -1;
    }
    usleep(5000); // Wait 4.5ms
    if (i2c_read_bytes(fd, BMP180_REG_MSB, data, 2) != 0) {
        perror("Failed to read raw temperature data");
        return -1;
    }
    *raw_temp = (data[0] << 8) | data[1];
    return 0;
}

// BMP180 read raw pressure function
int bmp180_read_raw_pressure(int fd, int32_t *raw_pressure) {
    uint8_t data[3];
    if (i2c_write_byte(fd, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) {
        perror("Failed to write pressure read command");
        return -1;
    }
    usleep(26000); // Wait 25.5ms for OSS = 3
    if (i2c_read_bytes(fd, BMP180_REG_MSB, data, 3) != 0) {
        perror("Failed to read raw pressure data");
        return -1;
    }
    *raw_pressure = ((int32_t)data[0] << 16 | (int32_t)data[1] << 8 | (int32_t)data[2]) >> (8 - BMP180_OSS);
    return 0;
}

// BMP180 calculate temperature function
int bmp180_calculate_temperature(int32_t raw_temp, int32_t *calculated_temp) {
    int32_t x1 = (((int32_t)raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    *calculated_temp = (b5 + 8) >> 4;
    return 0;
}

// BMP180 calculate pressure function
int bmp180_calculate_pressure(int32_t raw_pressure, int32_t raw_temp, int32_t *calculated_pressure) {
    int32_t b6 = raw_temp - ((int32_t)ac6);
    int32_t x1 = ((int32_t)b2 * (b6 * b6 >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)raw_pressure - b3) * (uint32_t)(50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    *calculated_pressure = p + ((x1 + x2 + 3791) >> 4);
    return 0;
}

// Log breach function
void log_breach(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

// BMP180 initialization function
int bmp180_init(int fd) {
    uint8_t data[2];

    // Read calibration data
    if (i2c_read_bytes(fd, BMP180_REG_CAL_AC1, (uint8_t *)&ac1, 2) != 0) return -1;
    if (i2c_read_bytes(fd, BMP180_REG_CAL_AC2, (uint8_t *)&ac2, 2) != 0) return -1;
    if (i2c_read_bytes(fd, BMP180_REG_CAL_AC3, (uint8_t *)&ac3, 2) != 0) return -1;
    if (i2c_read_bytes(fd, BMP180_REG_CAL_AC4, (uint8_t *)&ac4, 2) != 0) return -1;
    if (i2c_read_bytes(fd, BMP180_REG_CAL_AC5, (uint8_t *)&ac5, 2) != 0) return -1;
    if (i2c_read_bytes(fd, BMP180_REG_CAL_AC6, (uint8_t *)&ac6, 2) != 0) return -1;
    if (i2c_read_bytes(fd, BMP180_REG_CAL_B1, (uint8_t *)&b1, 2) != 0) return -1;
    if (i2c_read_bytes(fd, BMP180_REG_CAL_B2, (uint8_t *)&b2, 2) != 0) return -1;
    if (i2c_read_bytes(fd, BMP180_REG_CAL_MB, (uint8_t *)&mb, 2) != 0) return -1;
    if (i2c_read_bytes(fd, BMP180_REG_CAL_MC, (uint8_t *)&mc, 2) != 0) return -1;
    if (i2c_read_bytes(fd, BMP180_REG_CAL_MD, (uint8_t *)&md, 2) != 0) return -1;

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize BMP180 sensor
    if (bmp180_init(i2c_fd) != 0) {
        fprintf(stderr, "BMP180 initialization failed. Check I2C connection.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("breach_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    printf("Monitoring BMP180 sensor... Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int32_t raw_temp, raw_pressure;
        int32_t calculated_temp, calculated_pressure;

        // Read raw temperature and pressure
        if (bmp180_read_raw_temperature(i2c_fd, &raw_temp) != 0) {
            fprintf(stderr, "Failed to read raw temperature. Retrying...\n");
            continue;
        }
        if (bmp180_read_raw_pressure(i2c_fd, &raw_pressure) != 0) {
            fprintf(stderr, "Failed to read raw pressure. Retrying...\n");
            continue;
        }

        // Calculate temperature and pressure
        if (bmp180_calculate_temperature(raw_temp, &calculated_temp) != 0) {
            fprintf(stderr, "Failed to calculate temperature. Retrying...\n");
            continue;
        }
        if (bmp180_calculate_pressure(raw_pressure, raw_temp, &calculated_pressure) != 0) {
            fprintf(stderr, "Failed to calculate pressure. Retrying...\n");
            continue;
        }

        // Convert temperature to Celsius
        float temperature = (float)calculated_temp / 10.0;

        // Convert pressure to hPa
        float pressure = (float)calculated_pressure / 100.0;

        // Check for breaches
        if (temperature > 30.0) {
            char message[128];
            snprintf(message, sizeof(message), "Temperature breach: %.2f °C", temperature);
            log_breach(message);
        }
        if (pressure < 950.0) {
            char message[128];
            snprintf(message, sizeof(message), "Pressure breach: %.2f hPa", pressure);
            log_breach(message);
        }

        sleep(1); // Wait 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

