#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling Setting (OSS)
#define OSS 0

// GPIO pin for fan control
#define FAN_PIN 18

// Circular buffer size
#define BUFFER_SIZE 60

// Structure to hold calibration data
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

// Structure to hold sensor data
typedef struct {
    time_t timestamp;
    float temperature;
    float pressure;
} sensor_data_t;

// Circular buffer
sensor_data_t data_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C file descriptor
int i2c_fd;

// Calibration data
bmp180_calibration_data_t calibration_data;

// Function prototypes
int read_calibration_data(int fd, bmp180_calibration_data_t *cal);
int read_raw_temperature(int fd);
int read_raw_pressure(int fd);
float calculate_temperature(int raw_temperature, bmp180_calibration_data_t cal);
float calculate_pressure(int raw_pressure, int raw_temperature, bmp180_calibration_data_t cal);
void add_to_buffer(sensor_data_t data);
void print_buffer();
void control_fan(float temperature);
void timer_callback();
void signal_handler(int signal);

// Function to read a 16-bit value from the I2C bus
int read_i2c_word(int fd, int reg)
{
    int msb = wiringPiI2CReadReg8(fd, reg);
    int lsb = wiringPiI2CReadReg8(fd, reg + 1);

    if (msb == -1 || lsb == -1) {
        fprintf(stderr, "Error reading I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    return (msb << 8) | lsb;
}

// Function to read calibration data from the BMP180
int read_calibration_data(int fd, bmp180_calibration_data_t *cal) {
    cal->ac1 = read_i2c_word(fd, BMP180_REG_CAL_AC1);
    cal->ac2 = read_i2c_word(fd, BMP180_REG_CAL_AC2);
    cal->ac3 = read_i2c_word(fd, BMP180_REG_CAL_AC3);
    cal->ac4 = read_i2c_word(fd, BMP180_REG_CAL_AC4);
    cal->ac5 = read_i2c_word(fd, BMP180_REG_CAL_AC5);
    cal->ac6 = read_i2c_word(fd, BMP180_REG_CAL_AC6);
    cal->b1 = read_i2c_word(fd, BMP180_REG_CAL_B1);
    cal->b2 = read_i2c_word(fd, BMP180_REG_CAL_B2);
    cal->mb = read_i2c_word(fd, BMP180_REG_CAL_MB);
    cal->mc = read_i2c_word(fd, BMP180_REG_CAL_MC);
    cal->md = read_i2c_word(fd, BMP180_REG_CAL_MD);

    if (cal->ac1 == -1 || cal->ac2 == -1 || cal->ac3 == -1 || cal->ac4 == -1 ||
        cal->ac5 == -1 || cal->ac6 == -1 || cal->b1 == -1 || cal->b2 == -1 ||
        cal->mb == -1 || cal->mc == -1 || cal->md == -1) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    return 0;
}

// Function to read the raw temperature value from the BMP180
int read_raw_temperature(int fd) {
    wiringPiI2CWriteReg8(fd, BMP180_REG_CONTROL, 0x2E);
    delay(5); // Wait 4.5ms
    return read_i2c_word(fd, BMP180_REG_MSB);
}

// Function to read the raw pressure value from the BMP180
int read_raw_pressure(int fd) {
    wiringPiI2CWriteReg8(fd, BMP180_REG_CONTROL, 0x34 + (OSS << 6));
    delay(2 + (3 << OSS)); // Wait for conversion
    int msb = wiringPiI2CReadReg8(fd, BMP180_REG_MSB);
    int lsb = wiringPiI2CReadReg8(fd, BMP180_REG_LSB);
    int xlsb = wiringPiI2CReadReg8(fd, BMP180_REG_XLSB);

    if (msb == -1 || lsb == -1 || xlsb == -1) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    return ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
}

// Function to calculate the compensated temperature
float calculate_temperature(int raw_temperature, bmp180_calibration_data_t cal) {
    long X1 = ((long)raw_temperature - (long)cal.ac6) * ((long)cal.ac5) / pow(2, 15);
    long X2 = ((long)cal.mc * pow(2, 11)) / (X1 + cal.md);
    long B5 = X1 + X2;
    float temperature = (B5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate the compensated pressure
float calculate_pressure(int raw_pressure, int raw_temperature, bmp180_calibration_data_t cal) {
    long X1 = ((long)raw_temperature - (long)cal.ac6) * ((long)cal.ac5) / pow(2, 15);
    long X2 = ((long)cal.mc * pow(2, 11)) / (X1 + cal.md);
    long B5 = X1 + X2;

    long B6 = B5 - 4000;
    long X3 = ((long)cal.b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    long X4 = ((long)cal.ac2 * B6) / pow(2, 11);
    long B3 = (((long)cal.ac1 * 4 + X3 + X4) + 2) / 4;

    unsigned long X1_pressure = ((unsigned long)cal.ac3 * B6) / pow(2, 13);
    unsigned long X2_pressure = ((unsigned long)cal.b1 * (B6 * B6) / pow(2, 12)) / pow(2, 16);
    unsigned long B4 = ((unsigned long)cal.ac4 * (X1_pressure + X2_pressure + 32768)) / pow(2, 15);
    unsigned long B7 = ((unsigned long)raw_pressure - B3) * (50000 >> OSS);

    long pressure;
    if (B7 < 0x80000000) {
        pressure = (B7 * 2) / B4;
    } else {
        pressure = (B7 / B4) * 2;
    }

    X1 = (pressure / pow(2, 8)) * (pressure / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * pressure) / pow(2, 16);
    pressure = pressure + (X1 + X2 + 3791) / pow(2, 4);

    return pressure;
}

// Function to add data to the circular buffer
void add_to_buffer(sensor_data_t data) {
    data_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Data Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&data_buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp_str, data_buffer[index].temperature, data_buffer[index].pressure);
    }
    printf("--- End of Buffer ---\n\n");
}

// Function to control the cooling fan
void control_fan(float temperature) {
    if (temperature > 30.0) {
        digitalWrite(FAN_PIN, HIGH); // Turn fan on
        printf("Fan ON (Temperature: %.2f C)\n", temperature);
    } else {
        digitalWrite(FAN_PIN, LOW);  // Turn fan off
        printf("Fan OFF (Temperature: %.2f C)\n", temperature);
    }
}

// Timer callback function
void timer_callback() {
    int raw_temperature = read_raw_temperature(i2c_fd);
    int raw_pressure = read_raw_pressure(i2c_fd);

    if (raw_temperature == -1 || raw_pressure == -1) {
        fprintf(stderr, "Error reading sensor data. Skipping.\n");
        return;
    }

    float temperature = calculate_temperature(raw_temperature, calibration_data);
    float pressure = calculate_pressure(raw_pressure, raw_temperature, calibration_data);

    time_t now = time(NULL);
    sensor_data_t data = {now, temperature, pressure};

    add_to_buffer(data);
    print_buffer();
    control_fan(temperature);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d. Turning fan off and exiting.\n", signal);
    digitalWrite(FAN_PIN, LOW); // Turn fan off
    close(i2c_fd);
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPiSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(BMP180_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd, &calibration_data) == -1) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Set up GPIO pin for fan control
    pinMode(FAN_PIN, OUTPUT);
    digitalWrite(FAN_PIN, LOW); // Ensure fan is off initially

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback (every 500ms)
    if (wiringPiISR(0, INT_EDGE_RISING, timer_callback) < 0) {
        fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
        return 1;
    }

    printf("BMP180 sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop (keep the program running until a signal is received)
    while (1) {
        delay(1000); // Sleep for 1 second
    }

    return 0;
}

