// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Temperature thresholds (millidegrees Celsius)
#define TEMP_LOW   40000
#define TEMP_MED   60000
#define TEMP_HIGH  70000

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read CPU temperature from file
int read_cpu_temp(int *temp)
{
    FILE *fp;
    char buffer[10];

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        if (ferror(fp)) {
            perror("Error reading temperature file");
            fclose(fp);
            return -1;
        } else {
            fprintf(stderr, "Temperature file is empty or not readable\n");
            fclose(fp);
            return -1;
        }
    }

    fclose(fp);

    // Convert temperature from millidegrees Celsius to integer
    *temp = atoi(buffer);

    return 0;
}

// Function to set RGB LED color using pigpio
int set_led_color(int red, int green, int blue)
{
    // pigpio uses 0-255 range for PWM, so we need to scale our values
    int red_pwm   = 255 - red;   // Invert for common anode
    int green_pwm = 255 - green; // Invert for common anode
    int blue_pwm  = 255 - blue;  // Invert for common anode

    // Set PWM values for each color channel
    if (gpioPWM(RED_PIN, red_pwm) != 0) {
        fprintf(stderr, "Error setting Red PWM value\n");
        return -1;
    }
    if (gpioPWM(GREEN_PIN, green_pwm) != 0) {
        fprintf(stderr, "Error setting Green PWM value\n");
        return -1;
    }
    if (gpioPWM(BLUE_PIN, blue_pwm) != 0) {
        fprintf(stderr, "Error setting Blue PWM value\n");
        return -1;
    }

    return 0;
}

int main()
{
    int temperature;

    // Register signal handlers for graceful shutdown
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        if (read_cpu_temp(&temperature) == 0) {
            printf("Temperature: %d m°C\n", temperature);

            // Determine LED color based on temperature
            if (temperature < TEMP_LOW) {
                // Solid Blue
                if (set_led_color(0, 0, 255) != 0) {
                    fprintf(stderr, "Error setting Blue color\n");
                }
            } else if (temperature < TEMP_MED) {
                // Solid Green
                if (set_led_color(0, 255, 0) != 0) {
                    fprintf(stderr, "Error setting Green color\n");
                }
            } else {
                // Solid Red
                if (set_led_color(255, 0, 0) != 0) {
                    fprintf(stderr, "Error setting Red color\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading temperature, skipping LED update\n");
        }

        // Wait for 0.5 seconds
        gpioDelay(500000); // 500000 microseconds = 0.5 seconds
    }

    // Turn off all LEDs before exiting
    set_led_color(255, 255, 255); // Set all channels to max (off)

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated gracefully.\n");

    return 0;
}

