#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define SERVER_URL "http://yourserver.com/api/humidity"

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int error;
} DHT22Data;

// Function to read DHT22 data
DHT22Data read_dht22() {
    DHT22Data data = {0.0, 0.0, -1}; // Initialize with error
    int i, j;
    int bit_count = 0;
    int data_buffer[40] = {0};
    unsigned int pulse_lengths[80] = {0};
    unsigned int start_time, end_time, current_time;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // 1ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 30us

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Read pulse lengths
    for (i = 0; i < 80; i++) {
        start_time = gpioTick();
        while (gpioRead(DHT22_GPIO) == (i % 2 == 0 ? 0 : 1)) {
            current_time = gpioTick();
            if (current_time - start_time > 200) { // Timeout
                fprintf(stderr, "DHT22: Timeout waiting for change\n");
                return data; // Return with error
            }
        }
        end_time = gpioTick();
        pulse_lengths[i] = end_time - start_time;
    }

    // Decode data
    for (i = 0; i < 40; i++) {
        unsigned int sum = 0;
        for (j = 0; j < 10; j++) {
            sum += pulse_lengths[(2 * i) + j];
        }
        data_buffer[i] = (sum > 40) ? 1 : 0; // Threshold
    }

    // Validate checksum
    int checksum = 0;
    for (i = 0; i < 32; i++) {
        checksum += (data_buffer[i] << (31 - i));
    }
    int received_checksum = 0;
    for (i = 0; i < 8; i++) {
        received_checksum += (data_buffer[32 + i] << (7 - i));
    }

    if ((checksum & 0xFF) != received_checksum) {
        fprintf(stderr, "DHT22: Checksum mismatch: calculated %d, received %d\n", checksum & 0xFF, received_checksum);
        return data; // Return with error
    }

    // Extract data
    int humidity_int = 0;
    int temperature_int = 0;
    for (i = 0; i < 16; i++) {
        humidity_int += (data_buffer[i] << (15 - i));
    }
    for (i = 16; i < 32; i++) {
        temperature_int += (data_buffer[i] << (31 - i));
    }

    data.humidity = (float)humidity_int / 10.0;
    data.temperature = (float)temperature_int / 10.0;
    data.error = 0; // Success

    return data;
}

// Function to format data as JSON
char* format_json(float temperature, float humidity) {
    char *json_string = malloc(100); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Failed to allocate memory for JSON string\n");
        return NULL;
    }
    snprintf(json_string, 100, "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);
    return json_string;
}

// Function to send HTTP POST request
int send_http_post(const char *json_data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);

        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (response_code >= 400) {
                fprintf(stderr, "HTTP POST failed with status code: %ld\n", response_code);
            }
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    } else {
        fprintf(stderr, "Failed to initialize libcurl\n");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int retry_count;
    DHT22Data dht22_data;
    char *json_data;

    while (!terminate) {
        retry_count = 0;
        do {
            dht22_data = read_dht22();
            if (dht22_data.error == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "DHT22 read failed, retrying (%d/%d)...\n", retry_count + 1, MAX_RETRIES);
                gpioDelay(1000); // Wait 1 second before retrying
                retry_count++;
            }
        } while (retry_count < MAX_RETRIES && !terminate);

        if (dht22_data.error == 0) {
            json_data = format_json(dht22_data.temperature, dht22_data.humidity);
            if (json_data != NULL) {
                retry_count = 0;
                do {
                    if (send_http_post(json_data) == 0) {
                        break; // Success, exit retry loop
                    } else {
                        fprintf(stderr, "HTTP POST failed, retrying (%d/%d)...\n", retry_count + 1, MAX_RETRIES);
                        gpioDelay(1000); // Wait 1 second before retrying
                        retry_count++;
                    }
                } while (retry_count < MAX_RETRIES && !terminate);

                free(json_data);
            } else {
                fprintf(stderr, "Failed to format JSON data\n");
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 data after multiple retries\n");
        }

        gpioDelay(5000); // Wait 5 seconds before next reading
    }

    gpioTerminate();
    return 0;
}

