                gpioDelay(1000); // Wait 1 second before retrying
                retry_count++;
            }
        } while (retry_count < MAX_RETRIES && !terminate);

        if (dht22_data.error == 0) {
            json_data = format_json(dht22_data.temperature, dht22_data.humidity);
            if (json_data != NULL) {
