// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 // OSS = 0
#define BMP180_CMD_PRESSURE1 0x74 // OSS = 1
#define BMP180_CMD_PRESSURE2 0xB4 // OSS = 2
#define BMP180_CMD_PRESSURE3 0xF4 // OSS = 3

// GPIO pin for push-button interrupt
#define BUTTON_GPIO 4

// Debounce time in microseconds
#define DEBOUNCE_TIME 200000

// Conversion delay in milliseconds
#define CONVERSION_DELAY 26

// Global variables
static int i2c_handle;
static volatile bool logging_enabled = false;
static volatile uint32_t last_interrupt_time = 0;
static int oss = 3; // Oversampling setting

// Calibration data
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
