// Function to read a 16-bit value from the I2C bus
int16_t read_i2c_word(int reg)
{
    char buf[2];
    if (i2cWriteByte(i2c_handle, reg) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read a 16-bit value from the I2C bus
uint16_t read_i2c_uword(int reg)
{
    char buf[2];
    if (i2cWriteByte(i2c_handle, reg) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    return (uint16_t)((buf[0] << 8) | buf[1]);
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    ac1 = read_i2c_word(0xAA);
    ac2 = read_i2c_word(0xAC);
    ac3 = read_i2c_word(0xAE);
    ac4 = read_i2c_uword(0xB0);
    ac5 = read_i2c_uword(0xB2);
    ac6 = read_i2c_uword(0xB4);
