    b2 = read_i2c_word(0xB8);
    mb = read_i2c_word(0xBA);
    mc = read_i2c_word(0xBC);
    md = read_i2c_word(0xBE);

    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        fprintf(stderr, "Error reading calibration data.\n");
        return -1;
    }

    return 0;
}

// Function to read the raw temperature value from the BMP180
int read_raw_temperature()
{
    char buf[1];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0) {
        fprintf(stderr, "Error writing temperature command to I2C device.\n");
        return -1;
    }
    gpioDelay(5000); // Wait 5ms
    if (i2cWriteByte(i2c_handle, BMP180_REG_MSB) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    return buf[0];
}

// Function to read the raw pressure value from the BMP180
int read_raw_pressure()
{
    char buf[2];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE3) != 0) {
        fprintf(stderr, "Error writing pressure command to I2C device.\n");
        return -1;
    }
    gpioDelay(26000); // Wait 26ms
    if (i2cWriteByte(i2c_handle, BMP180_REG_MSB) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// Function to calculate the true temperature in degrees Celsius
long calculate_true_temperature(int32_t ut)
{
    int32_t x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    long temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate the true pressure in hPa
long calculate_true_pressure(int32_t up, int32_t ut)
{
    int32_t x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;

    int32_t b6 = b5 - 4000;
    x1 = (b2 * (b6 * b6) >> 12) >> 11;
    x2 = (ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << oss) + 2) >> 2;

    x1 = (ac3 * b6) >> 13;
    x2 = (b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = (ac4 * (uint32_t)(x3 + 32768)) >> 15;

    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> oss);
    int32_t p;
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    return p / 100.0; // Convert to hPa
}

// Function to log the pressure to a file
void log_pressure(long pressure)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening pressure_log.txt for writing.\n");
        return;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, pressure);
    fclose(fp);
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user)
{
    uint32_t current_time = gpioTick();
    if (current_time - last_interrupt_time > DEBOUNCE_TIME) {
        logging_enabled = !logging_enabled;
        last_interrupt_time = current_time;

        if (logging_enabled) {
            printf("Logging started.\n");
        } else {
            printf("Logging stopped.\n");
        }
    }
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pin for push-button interrupt
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);
    gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 200000, interrupt_handler, NULL); // Debounce time 200ms

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("BMP180 data logger started. Press the button to toggle logging.\n");

    while (1) {
        if (logging_enabled) {
            int32_t ut = read_raw_temperature();
            int32_t up = read_raw_pressure();

            if (ut != -1 && up != -1) {
                long temperature = calculate_true_temperature(ut);
                long pressure = calculate_true_pressure(up, ut);

                log_pressure(pressure);
                printf("Pressure: %.2f hPa\n", pressure);
            } else {
                fprintf(stderr, "Error reading sensor data.\n");
            }

            gpioDelay(2000000); // Wait 2 seconds
        } else {
            gpioDelay(100000); // Wait 0.1 seconds
        }
    }

    return 0;
}

