    return 0;
}

// Function to send data to the specified URL using libcurl
int send_data(const char *url, const char *json_data) {
    CURL *curl;
    CURLcode res;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        curl = curl_easy_init();
        if (curl) {
            curl_easy_setopt(curl, CURLOPT_URL, url);
            curl_easy_setopt(curl, CURLOPT_POST, 1L);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_data));
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
            curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L); // Set timeout to 10 seconds

            struct curl_slist *headers = NULL;
            headers = curl_slist_append(headers, "Content-Type: application/json");
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

            res = curl_easy_perform(curl);

            if (res == CURLE_OK) {
                long response_code;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
                if (response_code >= 200 && response_code < 300) {
                    syslog(LOG_INFO, "Data sent successfully, HTTP status code: %ld", response_code);
                    curl_slist_free_all(headers);
                    curl_easy_cleanup(curl);
                    return 0; // Success
                } else {
                    syslog(LOG_ERR, "HTTP request failed, status code: %ld", response_code);
                }
            } else {
                syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
            }

            curl_slist_free_all(headers);
            curl_easy_cleanup(curl);
        } else {
            syslog(LOG_ERR, "curl_easy_init() failed");
        }

        retries++;
        if (retries < MAX_RETRIES) {
            int backoff = BACKOFF_BASE * (1 << (retries - 1));
            if (backoff > MAX_BACKOFF) {
                backoff = MAX_BACKOFF;
            }
            syslog(LOG_INFO, "Retrying in %d seconds...", backoff);
            sleep(backoff);
        }
    }

    syslog(LOG_ERR, "Failed to send data after %d retries", MAX_RETRIES);
    return -1; // Failure
}

// Function to read data from the DHT22 sensor
DHT22Data read_dht22() {
    DHT22Data data = {0.0, 0.0, 0};
    int data_bits[40] = {0};
    int i, j;
    unsigned int pulse_lengths[80] = {0};
    unsigned int last_tick = 0;
    unsigned int current_tick;
    int bit_index = 0;
    int data_index = 0;
    int checksum = 0;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        // Send start signal
        gpioSetMode(DHT22_GPIO, PI_OUTPUT);
        gpioWrite(DHT22_GPIO, 0);
        gpioDelay(1); // 1ms
        gpioWrite(DHT22_GPIO, 1);
        gpioDelay(20); // 20us

        // Switch to input mode
        gpioSetMode(DHT22_GPIO, PI_INPUT);

        // Read pulse lengths
        for (i = 0; i < 80; i++) {
            current_tick = gpioTick();
            while (gpioRead(DHT22_GPIO) == (i % 2 == 0 ? 0 : 1)) {
                if (gpioTick() - current_tick > 200) { // Timeout
                    syslog(LOG_ERR, "DHT22 timeout during read");
                    goto retry;
                }
            }
            pulse_lengths[i] = gpioTick() - current_tick;
        }

        // Decode data bits
        for (i = 3; i < 43; i++) {
            if (pulse_lengths[2 * i + 1] > 40) {
                data_bits[i - 3] = 1;
            } else {
                data_bits[i - 3] = 0;
            }
        }

        // Validate checksum
        for (i = 0; i < 32; i++) {
            if (data_bits[i]) {
                checksum += (1 << (31 - i));
            }
        }

        int received_checksum = 0;
        for (i = 0; i < 8; i++) {
            if (data_bits[32 + i]) {
                received_checksum += (1 << (7 - i));
            }
        }

        if (checksum == received_checksum) {
            // Extract data
            int humidity = 0;
            for (i = 0; i < 16; i++) {
                if (data_bits[i]) {
                    humidity += (1 << (15 - i));
                }
            }
            data.humidity = (float)humidity / 10.0;

            int temperature = 0;
            for (i = 16; i < 32; i++) {
                if (data_bits[i]) {
                    temperature += (1 << (31 - i));
                }
            }
            data.temperature = (float)temperature / 10.0;
            if (temperature & 0x8000) {
                data.temperature *= -1;
            }

            data.valid = 1;
            syslog(LOG_INFO, "DHT22 data: Temperature = %.1f°C, Humidity = %.1f%%", data.temperature, data.humidity);
            return data;
        } else {
            syslog(LOG_ERR, "DHT22 checksum mismatch: calculated = %d, received = %d", checksum, received_checksum);
            goto retry;
        }

        retry:
        retries++;
        if (retries < MAX_RETRIES) {
            int backoff = BACKOFF_BASE * (1 << (retries - 1));
            if (backoff > MAX_BACKOFF) {
                backoff = MAX_BACKOFF;
            }
            syslog(LOG_INFO, "Retrying DHT22 read in %d seconds...", backoff);
            sleep(backoff);
        }
    }

    syslog(LOG_ERR, "Failed to read DHT22 data after %d retries", MAX_RETRIES);
    return data; // Return invalid data
}

// Function to format data as JSON
char *format_json(float temperature, float humidity) {
    static char json_string[MAX_JSON_SIZE];
    snprintf(json_string, MAX_JSON_SIZE, "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);
    return json_string;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    if (url != DEFAULT_URL) {
        free(url);
    }
    curl_global_cleanup();
    gpioTerminate();
    closelog();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                url = strdup(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <url>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (init_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize libcurl
    curl_global_init(CURL_GLOBAL_DEFAULT);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        DHT22Data dht22_data = read_dht22();

        if (dht22_data.valid) {
            char *json_data = format_json(dht22_data.temperature, dht22_data.humidity);
            if (send_data(url, json_data) != 0) {
                syslog(LOG_ERR, "Failed to send data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read DHT22 data");
        }

        sleep(10);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

