#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define MAX_FAN_STATE_FILE "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5

volatile sig_atomic_t program_running = 1;

void signal_handler(int signum) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signum);
}

int read_cpu_temp() {
    FILE *fp;
    int temp = -1;
    int retry_count = 0;
    const int max_retries = 3;

    while (retry_count < max_retries) {
        fp = fopen(TEMP_FILE, "r");
        if (fp == NULL) {
            perror("Failed to open temperature file");
            retry_count++;
            sleep(1); // Wait before retrying
            continue;
        }

        if (fscanf(fp, "%d", &temp) != 1) {
            fprintf(stderr, "Failed to read temperature from file\n");
            fclose(fp);
            retry_count++;
            sleep(1);
            continue;
        }

        fclose(fp);
        return temp;
    }

    fprintf(stderr, "Failed to read temperature after multiple retries\n");
    return -1; // Indicate failure
}

int read_fan_state() {
    FILE *fp;
    int state = -1;
    int retry_count = 0;
    const int max_retries = 3;

    while (retry_count < max_retries) {
        fp = fopen(FAN_STATE_FILE, "r");
        if (fp == NULL) {
            perror("Failed to open fan state file");
            retry_count++;
            sleep(1);
            continue;
        }

        if (fscanf(fp, "%d", &state) != 1) {
            fprintf(stderr, "Failed to read fan state from file\n");
            fclose(fp);
            retry_count++;
            sleep(1);
            continue;
        }

        fclose(fp);
        return state;
    }

    fprintf(stderr, "Failed to read fan state after multiple retries\n");
    return -1; // Indicate failure
}

int read_max_fan_state() {
    FILE *fp;
    int max_state = -1;
    int retry_count = 0;
    const int max_retries = 3;

    while (retry_count < max_retries) {
        fp = fopen(MAX_FAN_STATE_FILE, "r");
        if (fp == NULL) {
            perror("Failed to open max fan state file");
            retry_count++;
            sleep(1);
            continue;
        }

        if (fscanf(fp, "%d", &max_state) != 1) {
            fprintf(stderr, "Failed to read max fan state from file\n");
            fclose(fp);
            retry_count++;
            sleep(1);
            continue;
        }

        fclose(fp);
        return max_state;
    }

    fprintf(stderr, "Failed to read max fan state after multiple retries\n");
    return -1; // Indicate failure
}

int set_fan_state(int state) {
    FILE *fp;
    int retry_count = 0;
    const int max_retries = 3;

    while (retry_count < max_retries) {
        fp = fopen(FAN_STATE_FILE, "w");
        if (fp == NULL) {
            perror("Failed to open fan state file for writing");
            retry_count++;
            sleep(1);
            continue;
        }

        if (fprintf(fp, "%d", state) < 0) {
            fprintf(stderr, "Failed to write fan state to file\n");
            fclose(fp);
            retry_count++;
            sleep(1);
            continue;
        }

        fclose(fp);
        return 0; // Success
    }

    fprintf(stderr, "Failed to set fan state after multiple retries\n");
    return -1; // Indicate failure
}

int map_temperature_to_fan_speed(int temperature) {
    if (temperature < 45000) {
        return 0;
    } else if (temperature < 55000) {
        return 1;
    } else if (temperature < 65000) {
        return 2;
    } else {
        return 3;
    }
}

int log_event(const char *message) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

int main() {
    int current_temperature, current_fan_state, max_fan_state, desired_fan_speed;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started");

    while (program_running) {
        current_temperature = read_cpu_temp();
        if (current_temperature == -1) {
            fprintf(stderr, "Failed to read CPU temperature, using previous value\n");
        } else {
            printf("CPU Temperature: %d m°C\n", current_temperature);
        }

        current_fan_state = read_fan_state();
        if (current_fan_state == -1) {
            fprintf(stderr, "Failed to read fan state, using previous value\n");
        } else {
            printf("Current Fan State: %d\n", current_fan_state);
        }

        max_fan_state = read_max_fan_state();
        if (max_fan_state == -1) {
            fprintf(stderr, "Failed to read max fan state, using previous value\n");
        } else {
            printf("Max Fan State: %d\n", max_fan_state);
        }

        if (current_temperature != -1) {
            desired_fan_speed = map_temperature_to_fan_speed(current_temperature);
            printf("Desired Fan Speed: %d\n", desired_fan_speed);

            if (desired_fan_speed > max_fan_state) {
                fprintf(stderr, "Desired fan speed exceeds maximum allowed speed. Setting to max.\n");
                desired_fan_speed = max_fan_state;
            }

