#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define HEATER_GPIO 18
#define SPI_CLK 11
#define SPI_CS 8
#define SPI_DO 9

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 500000 // 500kHz

// Define PWM parameters
#define PWM_FREQUENCY 1000 // 1kHz
#define PWM_RANGE 100

// Define temperature limits
#define MIN_TEMP 0.0
#define MAX_TEMP 100.0

// Define PID parameters
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Define PID limits
#define MIN_DUTY 0
#define MAX_DUTY 100

// Define failsafe temperature
#define FAILSAFE_TEMP 50.0

// Global variables
int spi_handle;
double integral = 0.0;
double previous_error = 0.0;
FILE *log_file;

// Function prototypes
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature);
void set_heater_pwm(int duty_cycle);
void log_data(double temperature, int duty_cycle, double pid_output);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO18 as output for PWM
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heater_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char data[4];
    int result = spiRead(spi_handle, data, 4);

    if (result != 4) {
        fprintf(stderr, "SPI read failed\n");
        return -1000.0; // Indicate error
    }

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(log_file, "MAX31855 Fault: Open Circuit\n");
        fflush(log_file);
        return -1000.0;
    }
    if (data[3] & 0x02) {
        fprintf(log_file, "MAX31855 Fault: Short to GND\n");
        fflush(log_file);
        return -1000.0;
    }
    if (data[3] & 0x04) {
        fprintf(log_file, "MAX31855 Fault: Short to VCC\n");
        fflush(log_file);
        return -1000.0;
    }

    // Extract temperature data (ignoring fault bits)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    double temperature = (double)raw_temp * 0.25;

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;

    integral += error;
    if (integral > MAX_DUTY) integral = MAX_DUTY;
    if (integral < MIN_DUTY) integral = MIN_DUTY;

    double derivative = error - previous_error;

    double output = (Kp * error) + (Ki * integral) + (Kd * derivative);

    previous_error = error;

    return output;
}

// Function to set heater PWM duty cycle
void set_heater_pwm(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    gpioPWM(HEATER_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(double temperature, int duty_cycle, double pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f, Duty Cycle: %d, PID Output: %.2f\n", timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    set_heater_pwm(0); // Turn off heater
    spiClose(spi_handle); // Close SPI
    fclose(log_file); // Close log file
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to clean up resources before exiting
void cleanup() {
    set_heater_pwm(0); // Turn off heater
    spiClose(spi_handle); // Close SPI
    fclose(log_file); // Close log file
    gpioTerminate(); // Terminate pigpio
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize system
    if (initialize()) {
        return 1;
    }

    double target_temperature = 50.0;
    double actual_temperature;
    double pid_output;
    int duty_cycle;

    while (1) {
        // Read temperature
        actual_temperature = read_temperature();

        if (actual_temperature < MIN_TEMP || actual_temperature > MAX_TEMP) {
            fprintf(log_file, "Temperature out of range: %.2f\n", actual_temperature);
            fflush(log_file);
            set_heater_pwm(0);
            integral = 0.0;
            previous_error = 0.0;
            gpioDelay(1000); // Wait 1 second
            continue;
        }

        // Calculate PID output
        pid_output = calculate_pid(target_temperature, actual_temperature);

        // Limit PID output to 0-100
        if (pid_output < MIN_DUTY) pid_output = MIN_DUTY;
        if (pid_output > MAX_DUTY) pid_output = MAX_DUTY;

        // Set heater PWM duty cycle
        duty_cycle = (int)pid_output;
        set_heater_pwm(duty_cycle);

        // Log data
        log_data(actual_temperature, duty_cycle, pid_output);

        // Failsafe
        if (actual_temperature > FAILSAFE_TEMP) {
            fprintf(log_file, "Failsafe triggered: Temperature exceeded %.2f\n", FAILSAFE_TEMP);
            fflush(log_file);
            set_heater_pwm(0);
            integral = 0.0;
            previous_error = 0.0;
        }

        // Wait 1 second
        gpioDelay(1000);
    }

    return 0;
}

