#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"

static volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

float read_cpu_temp() {
    FILE *fp;
    int temp_raw;
    float temp_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0;
    }

    if (fscanf(fp, "%d", &temp_raw) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1.0;
    }

    fclose(fp);
    temp_celsius = (float)temp_raw / 1000.0;
    return temp_celsius;
}

int set_pwm_duty_cycle(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle\n");
        return -1;
    }
    return 0;
}

int log_data(float temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fclose(fp);
    return 0;
}

int main() {
    float temperature;
    int duty_cycle;
    int pigpio_init_result;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error setting PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value or exiting\n");
            // Consider exiting if temperature reading consistently fails
            // For now, just continue with previous duty cycle
            continue;
        }

        // Map temperature to duty cycle (0-100%)
        if (temperature <= 40.0) {
            duty_cycle = 0;
        } else if (temperature >= 70.0) {
            duty_cycle = 100;
        } else {
            duty_cycle = (int)((temperature - 40.0) / (70.0 - 40.0) * 100.0);
        }

        if (set_pwm_duty_cycle(duty_cycle) != 0) {
            fprintf(stderr, "Error setting duty cycle, exiting\n");
            break;
        }

        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data, continuing\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Turn off the fan before exiting
    set_pwm_duty_cycle(0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

