int read_sensor(int i2c_handle, float *flow_rate) {
    unsigned char buffer[3];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, buffer, 3);
        if (result == 3) {
            // Checksum validation
            if (validate_checksum(buffer, 3)) {
                // Convert raw data to flow rate (example conversion, adjust as needed)
                int raw_flow = (buffer[0] << 8) | buffer[1];
                *flow_rate = (float)raw_flow / 100.0; // Example scaling
                return 0; // Success
            } else {
                fprintf(stderr, "Checksum failed, retrying...\n");
            }
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
        }
        retries++;
        gpioDelay(10); // Small delay before retrying
    }

    fprintf(stderr, "Failed to read sensor after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to validate the checksum
int validate_checksum(unsigned char data[], int len) {
    unsigned char crc = 0xFF;
    unsigned char polynomial = 0x31;

    for (int i = 0; i < len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }

    return (crc == data[len - 1]);
}

