        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow1, flow2;

    // Main loop
    while (!terminate) {
        // Read sensor 1
        if (read_sensor(i2c_handle1, &flow1) != 0) {
            flow1 = -1.0; // Indicate error
        }

        // Read sensor 2
        if (read_sensor(i2c_handle2, &flow2) != 0) {
            flow2 = -1.0; // Indicate error
        }

        // Log the data
        if (log_data(flow1, flow2) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Close I2C handles
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

