#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for Channel A and Channel B
#define CHANNEL_A_PIN 17
#define CHANNEL_B_PIN 18

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 360

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Global variables
static volatile int running = 1;
static volatile int current_state = 0; // Initial state
static volatile int pulse_count = 0;
static volatile double angular_position = 0.0;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_encoder();
double calculate_angular_position(int pulse_count);
int log_position(double angular_position);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int a_pin;
    int b_pin;
} EncoderConfig;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(CHANNEL_A_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_A_PIN, PI_PUD_UP);
    gpioSetMode(CHANNEL_B_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_B_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the encoder state
int read_encoder() {
    int a_value = gpioRead(CHANNEL_A_PIN);
    int b_value = gpioRead(CHANNEL_B_PIN);

    // Implement quadrature decoding
    if (a_value == b_value) {
        return 0; // No change
    } else if (a_value > b_value) {
        return 1; // Clockwise
    } else {
        return -1; // Counter-clockwise
    }
}

// Function to calculate the angular position
double calculate_angular_position(int pulse_count) {
    return (double)pulse_count * (360.0 / PULSES_PER_REVOLUTION);
}

// Function to log the angular position to a file
int log_position(double angular_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, angular_position);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int delta = read_encoder();

        if (delta != 0) {
            pulse_count += delta;
            angular_position = calculate_angular_position(pulse_count);

            if (log_position(angular_position) != 0) {
                fprintf(stderr, "Error logging position.\n");
            }
        }

        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

