#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define PULSES_PER_REVOLUTION 1.0
#define DEBOUNCE_DELAY_US 500

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile int running = 1;

// Structure to pass data to the ISR
typedef struct {
    int gpio;
    int level;
    uint32_t tick;
} isr_data_t;

// Function prototypes
void *rpm_calculator_thread(void *arg);
void isr_callback(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);
int initialize();
void cleanup();

// ISR callback function
void isr_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) {
        // Debounce
        gpioDelay(DEBOUNCE_DELAY_US);

        if (gpioRead(gpio) == PI_HIGH) {
            pthread_mutex_lock(&pulse_mutex);
            pulse_count++;
            pthread_mutex_unlock(&pulse_mutex);
        }
    }
}

// RPM calculator thread function
void *rpm_calculator_thread(void *arg) {
    while (running) {
        sleep(1);

        int local_pulse_count;
        pthread_mutex_lock(&pulse_mutex);
        local_pulse_count = pulse_count;
        pulse_count = 0; // Reset the counter
        pthread_mutex_unlock(&pulse_mutex);

        double rpm = (local_pulse_count / PULSES_PER_REVOLUTION) * 60.0;

        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        if (log_file != NULL) {
            fprintf(log_file, "%s, %.2f\n", buf, rpm);
            fflush(log_file);
        } else {
            fprintf(stderr, "Error: Log file is not open.\n");
        }

        if (local_pulse_count == 0) {
            if (log_file != NULL) {
                fprintf(log_file, "%s, 0.00\n", buf);
                fflush(log_file);
            } else {
                fprintf(stderr, "Error: Log file is not open.\n");
            }
        }
    }
    return NULL;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Register ISR
    isr_data_t isr_data;
    isr_data.gpio = GPIO_PIN;
    isr_data.level = PI_INPUT;
    isr_data.tick = 0;

    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, isr_callback, &isr_data) != 0) {
        fprintf(stderr, "Failed to register ISR\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    pthread_t rpm_thread;
    if (pthread_create(&rpm_thread, NULL, rpm_calculator_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create RPM calculator thread\n");
        cleanup();
        return 1;
    }

    pthread_join(rpm_thread, NULL);

    cleanup();
    return 0;
}

