#include <string.h>

#define AUDIO_PIN 17
#define GAIN_PIN 18
#define LOG_FILE "audio_log.txt"
#define SAMPLE_INTERVAL_MS 10

static volatile int running = 1;
static FILE *log_file = NULL;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(AUDIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", AUDIO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(GAIN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GAIN_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(GAIN_PIN, 0) != 0) { // Set GAIN_PIN LOW for 60dB gain
        fprintf(stderr, "Failed to set GPIO%d LOW\n", GAIN_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to log audio event to file
int log_audio_event(int level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s %d\n", timestamp, level);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main() {
    int last_state = 0;
    int current_state;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Audio event logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        current_state = gpioRead(AUDIO_PIN);

        if (current_state == 1 && last_state == 0) {
            // Rising edge detected
            if (log_audio_event(1) != 0) {
                fprintf(stderr, "Error logging audio event.\n");
            }
        }

        last_state = current_state;
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

