#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x36
#define FLOW_LOG_FILE "flow_log.csv"
#define SAMPLE_INTERVAL_MS 1000
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_flow_rate(int *raw_flow_rate);
uint8_t calculate_crc(const uint8_t *data, int len);
int log_flow_rate(int flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional, but good practice)
typedef struct {
    int raw_flow_rate;
    uint8_t crc;
} sensor_data_t;

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    int raw_flow_rate;
    while (!terminate) {
        if (read_flow_rate(&raw_flow_rate) == 0) {
            log_flow_rate(raw_flow_rate);
        } else {
            fprintf(stderr, "Failed to read flow rate\n");
        }
        gpioDelay(SAMPLE_INTERVAL_MS); // Delay for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read flow rate from the sensor
int read_flow_rate(int *raw_flow_rate) {
    char buffer[3];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 3);

    if (bytes_read != 3) {
        fprintf(stderr, "I2C read failed: %d\n", bytes_read);
        return 1;
    }

    // Extract raw flow rate (MSB first)
    *raw_flow_rate = (buffer[0] << 8) | buffer[1];

    // CRC validation
    uint8_t calculated_crc = calculate_crc((uint8_t *)buffer, 2);
    if (calculated_crc != buffer[2]) {
        fprintf(stderr, "CRC validation failed: calculated=0x%02X, received=0x%02X\n", calculated_crc, buffer[2]);
        return 1; // Skip this reading
    }

    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Log flow rate to CSV file
int log_flow_rate(int flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, flow_rate);
    fflush(log_file); // Flush the buffer to ensure data is written to the file

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

