    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            int iaq = calculate_iaq(sensor_data.tvoc, sensor_data.eco2);
            log_data(iaq, sensor_data.tvoc, sensor_data.eco2);

            if (iaq > IAQ_THRESHOLD) {
                printf("High IAQ detected! IAQ: %d, TVOC: %u, eCO2: %u\n", iaq, sensor_data.tvoc, sensor_data.eco2);
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

