#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 50
#define INTRUSION_DURATION_S 5

static volatile int running = 1;
static volatile int intrusion_detected = 0;

void cleanup(int signum) {
    printf("\nCaught signal %d, cleaning up...\n", signum);
    gpioWrite(GPIO_PIN, 0); // Set GPIO to LOW
    gpioSetMode(GPIO_PIN, PI_INPUT); // Set GPIO to input
    gpioTerminate(); // Terminate pigpio
    running = 0;
    exit(0);
}

int main() {
    int rc;
    struct timespec ts_start, ts_end;
    double elapsed_time;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    printf("Tamper detection started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read GPIO pin value
        int gpio_value = gpioRead(GPIO_PIN);

        if (gpio_value < 0) {
            fprintf(stderr, "Error reading GPIO pin: %s\n", strerror(errno));
            cleanup(0);
            return EXIT_FAILURE;
        }

        // Check for touch event (HIGH signal)
        if (gpio_value == 1 && !intrusion_detected) {
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds

            // Re-read GPIO pin value after debounce delay
            gpio_value = gpioRead(GPIO_PIN);
            if (gpio_value < 0) {
                fprintf(stderr, "Error reading GPIO pin after debounce: %s\n", strerror(errno));
                cleanup(0);
                return EXIT_FAILURE;
            }

            if (gpio_value == 1) {
                // Touch event detected
                intrusion_detected = 1;
                clock_gettime(CLOCK_MONOTONIC, &ts_start);

                printf("Intrusion detected!\n");
            }
        } else if (gpio_value == 0 && intrusion_detected) {
            // Reset intrusion detection when touch is released
            intrusion_detected = 0;
        }

        // Check for intrusion duration
        if (intrusion_detected) {
            clock_gettime(CLOCK_MONOTONIC, &ts_end);
            elapsed_time = (ts_end.tv_sec - ts_start.tv_sec) + (ts_end.tv_nsec - ts_start.tv_nsec) / 1000000000.0;

            if (elapsed_time >= INTRUSION_DURATION_S) {
                // Intrusion duration exceeded
                intrusion_detected = 0; // Reset intrusion detection
                printf("Intrusion confirmed!\n");
            }
        }

        gpioDelay(100 * 1000); // Check every 100ms
    }

    return 0;
}

