            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds

            // Re-read GPIO pin value after debounce delay
            gpio_value = gpioRead(GPIO_PIN);
            if (gpio_value < 0) {
                fprintf(stderr, "Error reading GPIO pin after debounce: %s\n", strerror(errno));
                cleanup(0);
                return EXIT_FAILURE;
            }

            if (gpio_value == 1) {
                // Touch event detected
                intrusion_detected = 1;
                clock_gettime(CLOCK_MONOTONIC, &ts_start);

                printf("Intrusion detected!\n");
            }
        } else if (gpio_value == 0 && intrusion_detected) {
            // Reset intrusion detection when touch is released
            intrusion_detected = 0;
        }

        // Check for intrusion duration
        if (intrusion_detected) {
            clock_gettime(CLOCK_MONOTONIC, &ts_end);
            elapsed_time = (ts_end.tv_sec - ts_start.tv_sec) + (ts_end.tv_nsec - ts_start.tv_nsec) / 1000000000.0;

            if (elapsed_time >= INTRUSION_DURATION_S) {
                // Intrusion duration exceeded
                intrusion_detected = 0; // Reset intrusion detection
                printf("Intrusion confirmed!\n");
            }
        }

        gpioDelay(100 * 1000); // Check every 100ms
    }

    return 0;
}

