#include <pigpio.h>

#define SAMPLE_RATE 44100
#define NUM_CHANNELS 2
#define SAMPLE_SIZE 2 // 16-bit PCM
#define GPIO_PIN 17
#define GPIO_MODE PI_OUTPUT
#define FILENAME "audio_capture.pcm"

static volatile int keep_running = 1;
static snd_pcm_t *pcm_handle = NULL;
static FILE *output_file = NULL;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        keep_running = 0;
    }
}

int initialize_i2s() {
    int err;
    snd_pcm_hw_params_t *hw_params;

    if ((err = snd_pcm_open(&pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    if ((err = snd_pcm_hw_params_malloc(&hw_params)) < 0) {
        fprintf(stderr, "Error allocating hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error initializing hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw_params);
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw_params);
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting sample format: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw_params);
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channel count: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw_params);
        snd_pcm_close(pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw_params);
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(hw_params);
        snd_pcm_close(pcm_handle);
        return -1;
    }

    snd_pcm_hw_params_free(hw_params);

    return 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, GPIO_MODE);
    return 0;
}

int main() {
    int err;
    int i;
    short *buffer;
    int buffer_size = SAMPLE_RATE * NUM_CHANNELS * SAMPLE_SIZE / 10; // 10ms buffer

    signal(SIGINT, signal_handler);

    if (initialize_i2s() != 0) {
        fprintf(stderr, "I2S initialization failed\n");
        return 1;
    }

    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        snd_pcm_close(pcm_handle);
        return 1;
    }

    buffer = (short *)malloc(buffer_size);
    if (!buffer) {
        fprintf(stderr, "Failed to allocate buffer\n");
        gpioTerminate();
        snd_pcm_close(pcm_handle);
        return 1;
    }

    output_file = fopen(FILENAME, "wb");
    if (!output_file) {
        fprintf(stderr, "Failed to open output file\n");
        free(buffer);
        gpioTerminate();
        snd_pcm_close(pcm_handle);
        return 1;
    }

    printf("Starting audio capture...\n");

    while (keep_running) {
        // Set GPIO to select left channel
        gpioWrite(GPIO_PIN, 0);

        if ((err = snd_pcm_readi(pcm_handle, buffer, buffer_size / (NUM_CHANNELS * SAMPLE_SIZE))) != buffer_size / (NUM_CHANNELS * SAMPLE_SIZE)) {
            fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(err));
            break;
        }

        // Write left channel data to file
        fwrite(buffer, SAMPLE_SIZE, buffer_size / (NUM_CHANNELS * SAMPLE_SIZE), output_file);

        // Set GPIO to select right channel
        gpioWrite(GPIO_PIN, 1);

        if ((err = snd_pcm_readi(pcm_handle, buffer, buffer_size / (NUM_CHANNELS * SAMPLE_SIZE))) != buffer_size / (NUM_CHANNELS * SAMPLE_SIZE)) {
            fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(err));
            break;
        }

        // Write right channel data to file
        fwrite(buffer, SAMPLE_SIZE, buffer_size / (NUM_CHANNELS * SAMPLE_SIZE), output_file);
    }

    printf("Stopping audio capture...\n");

    free(buffer);
    fclose(output_file);
    gpioTerminate();
    snd_pcm_close(pcm_handle);

    printf("Audio capture complete. File saved as %s\n", FILENAME);

    return 0;
}

