#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define FAN_PWM_GPIO 18
#define PWM_FREQUENCY 100
#define DEBOUNCE_DELAY_MS 50
#define TIMEOUT_MS 1000
#define LOG_FILE "flame_log.txt"

static FILE *log_file = NULL;
static volatile int running = 1;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *info;
    char *buffer = malloc(sizeof(char) * 30);
    if (buffer == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    info = gmtime(&rawtime);

    strftime(buffer, 30, "%Y-%m-%dT%H:%M:%SZ", info);
    return buffer;
}

// Function to log events to the log file
void log_event(const char *event) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write to file
        free(timestamp);
    } else {
        fprintf(stderr, "Error: Could not get timestamp for event: %s\n", event);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pins
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(FAN_PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency (optional, but recommended for stability)
    gpioSetPWMfrequency(FAN_PWM_GPIO, PWM_FREQUENCY);

    return 0;
}

// Function to read the flame sensor with debouncing
int read_flame_sensor() {
    int reading = gpioRead(FLAME_SENSOR_GPIO);
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
    return reading;
}

// Function to control the fan using PWM
void control_fan(int state) {
    gpioPWM(FAN_PWM_GPIO, state ? 255 : 0); // 255 for full speed, 0 for off
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Initialize pigpio and GPIO pins
    if (initialize()) {
        fclose(log_file);
        return 1;
    }

    log_event("System started");

    int flame_detected = 0;
    time_t last_reading_time = time(NULL);

    while (running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0) { // Flame detected (LOW signal)
            if (!flame_detected) {
                flame_detected = 1;
                control_fan(1); // Turn on the fan
                log_event("Flame detected");
            }
            last_reading_time = time(NULL);
        } else {
            // Check for timeout
            if (flame_detected && (time(NULL) - last_reading_time) * 1000 >= TIMEOUT_MS) {
                flame_detected = 0;
                control_fan(0); // Turn off the fan
                log_event("Flame ended (timeout)");
            }
        }

        gpioDelay(10000); // Check every 10ms
    }

    // Cleanup before exiting
    control_fan(0); // Ensure fan is off
    gpioTerminate(); // Terminate pigpio
    fclose(log_file); // Close the log file

    log_event("System shutdown");

    return 0;
}

