#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define FRAME_TRIGGER_PIN 23 // BCM GPIO 23
#define DATA_READY_PIN 24    // BCM GPIO 24
#define FRAME_PERIOD_MS 100
#define FRAME_SIZE_BYTES 32768
#define LOG_FILE_NAME "radar_data.bin"
#define MAGIC_NUMBER 4144

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold radar configuration
typedef struct {
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint16_t num_chirps;
    uint16_t num_samples;
} radar_config_t;

// Function prototypes
int initialize();
int configure_sensor(radar_config_t config);
int capture_frame(uint8_t *frame_data);
int log_frame(uint8_t *frame_data, uint64_t timestamp, uint32_t frame_number);
void signal_handler(int signal);
void frame_trigger_callback(int gpio, int level, uint32_t tick, void *user);
void data_ready_callback(int gpio, int level, uint32_t tick, void *user);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Frame trigger callback function
void frame_trigger_callback(int gpio, int level, uint32_t tick, void *user) {
    // This function is called when the frame trigger pin goes high.
    // It triggers the data ready interrupt.
    gpioSetISRFuncEx(DATA_READY_PIN, RISING_EDGE, 0, data_ready_callback, NULL);
}

// Data ready callback function
void data_ready_callback(int gpio, int level, uint32_t tick, void *user) {
    // This function is called when the data ready pin goes high.
    // It captures the frame data and logs it.
    uint8_t frame_data[FRAME_SIZE_BYTES];
    uint64_t timestamp;
    uint32_t frame_number;

    // Get current timestamp
    timestamp = gpioTick();

    // Get frame number (increment a global counter)
    static uint32_t frame_counter = 0;
    frame_number = frame_counter++;
    printf("Frame number: %u\n", frame_number);

    // Capture the frame data
    if (capture_frame(frame_data) != 0) {
        fprintf(stderr, "Error capturing frame data\n");
        return;
    }

    // Log the frame data
    if (log_frame(frame_data, timestamp, frame_number) != 0) {
        fprintf(stderr, "Error logging frame data\n");
    }

    // Disable the data ready interrupt
    gpioSetISRFuncEx(DATA_READY_PIN, RISING_EDGE, 0, NULL, NULL);
}

// Initialize function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Configure SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Configure GPIO pins
    gpioSetMode(FRAME_TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(DATA_READY_PIN, PI_INPUT);
    gpioSetPullUpDown(DATA_READY_PIN, PI_PUD_DOWN); // Pull-down resistor

    // Set up interrupt handlers
    gpioSetISRFuncEx(FRAME_TRIGGER_PIN, RISING_EDGE, 0, frame_trigger_callback, NULL);

    return 0;
}

// Configure sensor function
int configure_sensor(radar_config_t config) {
    // Placeholder for sensor configuration
    // In a real application, this would involve sending SPI commands to the AWR1642
    // to set the desired configuration parameters.
    printf("Sensor configuration: start_frequency=%u, end_frequency=%u, num_chirps=%u, num_samples=%u\n",
           config.start_frequency, config.end_frequency, config.num_chirps, config.num_samples);

    // For demonstration purposes, we'll just return success.
    return 0;
}

// Capture frame function
int capture_frame(uint8_t *frame_data) {
    // Placeholder for frame capture
    // In a real application, this would involve reading data from the SPI interface
    // to capture the range-Doppler heatmap data.
    // For now, we'll just fill the buffer with some dummy data.
    for (int i = 0; i < FRAME_SIZE_BYTES; i++) {
        frame_data[i] = i % 256; // Fill with some pattern
    }

    return 0;
}

// Log frame function
int log_frame(uint8_t *frame_data, uint64_t timestamp, uint32_t frame_number) {
    // Open the log file in append mode
    log_file = fopen(LOG_FILE_NAME, "ab");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

