#define GPIO_PIN 20
#define LOG_FILE "flame_log.txt"

static volatile int keepRunning = 1;
static FILE *logFile = NULL;

void signalHandler(int signal) {
    keepRunning = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int currentValue, previousValue;
    time_t rawtime;
    struct tm *info;
    char timestamp[30];
    int result;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open log file
    logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    previousValue = gpioRead(GPIO_PIN);

    printf("Monitoring flame sensor on GPIO %d...\n", GPIO_PIN);

    while (keepRunning) {
        currentValue = gpioRead(GPIO_PIN);

        if (currentValue != previousValue) {
            // Get current timestamp
            time(&rawtime);
            info = gmtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", info);

            // Log the event
            result = fprintf(logFile, "%s,%s\n", timestamp, currentValue == 0 ? "flame_detected" : "flame_cleared");
            if (result < 0) {
                fprintf(stderr, "Error writing to log file\n");
            } else {
                fflush(logFile); // Ensure data is written to disk
            }

            previousValue = currentValue;
        }

        gpioDelay(100); // Wait 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (logFile != NULL) {
        fclose(logFile);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

