#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SLEEP_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_lux(float *lux);
int write_data_to_file(float lux);
void signal_handler(int signal);
void cleanup();

// Structure for grouping sensor data
typedef struct {
    float lux;
    char timestamp[32];
} sensor_data_t;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the OPT3001 sensor
int configure_sensor() {
    unsigned char config_value[2];
    config_value[0] = CONFIG_REG;
    config_value[1] = 0xCB; // Continuous mode, auto full-scale range

    int result = i2cWriteDevice(i2c_handle, (char *)config_value, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read lux value from the sensor
int read_lux(float *lux) {
    unsigned char data[2];
    int result;

    // Read result register
    result = i2cReadDevice(i2c_handle, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from result register: %d\n", result);
        return -1;
    }

    // Parse lux value
    int exponent = (data[0] >> 2) & 0x1F;
    int mantissa = (data[1] >> 6) & 0x3F;
    *lux = 0.01 * (1 << exponent) * mantissa;

    return 0;
}

// Write data to file
int write_data_to_file(float lux) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);

    fp = fopen("light_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file!\n");
        return -1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, lux);
    fclose(fp);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    float lux;
    int retry;

    // Main loop
    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_lux(&lux) == 0) {
                if (write_data_to_file(lux) != 0) {
                    fprintf(stderr, "Error writing data to file, retrying...\n");
                }
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Error reading lux value, retrying (%d/%d)...\n", retry + 1, RETRY_COUNT);
                retry++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read lux value after %d retries. Continuing...\n", RETRY_COUNT);
        }

        gpioDelay(SLEEP_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

