#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LEFT_PIN 17
#define CENTER_PIN 18
#define RIGHT_PIN 27

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Could not register signal handler.\n");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pins as inputs
    if (gpioSetMode(LEFT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", LEFT_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(CENTER_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", CENTER_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RIGHT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", RIGHT_PIN);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read the state of each GPIO pin
        int left_state = gpioRead(LEFT_PIN);
        int center_state = gpioRead(CENTER_PIN);
        int right_state = gpioRead(RIGHT_PIN);

        // Print the states to the console
        printf("Left: %d, Center: %d, Right: %d\n", left_state, center_state, right_state);

        // Wait for 50 milliseconds
        usleep(50000);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

