        return -1;
    }
    channel_states[4] = result;

    result = gpioRead(pins.gpio7);
    if (result < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", pins.gpio7, result);
        return -1;
    }
    channel_states[5] = result;

    result = gpioRead(pins.gpio8);
    if (result < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", pins.gpio8, result);
        return -1;
    }
    channel_states[6] = result;

    result = gpioRead(pins.gpio9);
    if (result < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", pins.gpio9, result);
        return -1;
    }
    channel_states[7] = result;

    return 0;
}

int main() {
    gpio_pins_t pins = {GPIO_2, GPIO_3, GPIO_4, GPIO_5, GPIO_6, GPIO_7, GPIO_8, GPIO_9};
