    struct tm *time_info;
    char timestamp[20];
    int i;

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(pins.gpio2, PI_INPUT);
    gpioSetMode(pins.gpio3, PI_INPUT);
    gpioSetMode(pins.gpio4, PI_INPUT);
    gpioSetMode(pins.gpio5, PI_INPUT);
    gpioSetMode(pins.gpio6, PI_INPUT);
    gpioSetMode(pins.gpio7, PI_INPUT);
    gpioSetMode(pins.gpio8, PI_INPUT);
    gpioSetMode(pins.gpio9, PI_INPUT);

    // Main loop
    while (program_running) {
        // Read the touch sensor channels
        if (read_touch_sensor(pins, channel_states) == 0) {
            // Get the current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

