            fprintf(stderr, "Error reading touch sensor data\n");
        }

        // Wait for 100 milliseconds
        usleep(100000); // 100ms = 100000 microseconds
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

