#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the GPIO pins connected to the TTP226 sensor outputs
const int sensor_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = 8;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main()
{
    int i, result;

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure the sensor pins as inputs with pull-down resistors
    for (i = 0; i < num_channels; i++)
    {
        gpioSetMode(sensor_pins[i], PI_INPUT);
        gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN);
    }

    // Main loop
    while (!terminate)
    {
        // Read the sensor values
        for (i = 0; i < num_channels; i++)
        {
            int value = gpioRead(sensor_pins[i]);
            if (value < 0)
            {
                fprintf(stderr, "Error reading sensor %d\n", i + 1);
                terminate = 1; // Exit loop on error
                break;
            }
            printf("CH%d=%d ", i + 1, value);
        }
        printf("\n");

        // Delay for 100ms
        usleep(100000); // 100ms = 100000 microseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();
    fprintf(stderr, "pigpio terminated\n");

    return 0;
}

