    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP);

    // Set up signal handling for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop to read sensor states and log them
    while (!terminate)
    {
        // Read sensor 1 state
