#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TILT_PIN 7 // BCM GPIO 7

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int tilt_state = -1; // Initialize to an invalid state
    int current_tilt_state;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pin as input with pull-up resistor
    gpioSetMode(TILT_PIN, PI_INPUT);
    gpioSetPullUpDown(TILT_PIN, PI_PUD_UP);

    // Print startup banner
    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read the tilt sensor state
        current_tilt_state = gpioRead(TILT_PIN);

        // Validate the sensor reading
        if (current_tilt_state != 0 && current_tilt_state != 1) {
            fprintf(stderr, "Error: Invalid sensor reading: %d\n", current_tilt_state);
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Check for tilt state changes
        if (current_tilt_state != tilt_state) {
            // Flush stdout to ensure immediate output
            fflush(stdout);

            // Log the tilt state to the console
            if (current_tilt_state == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }

            // Update the tilt state
            tilt_state = current_tilt_state;
        }

        // Wait for 100ms
        gpioDelay(100);
    }

    // Clean up and exit
    printf("\nExiting cleanly.\n");
    gpioTerminate();
    return 0;
}

