#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define ALARM_GPIO 17
#define FLOW_RATE_THRESHOLD 0.5 // ml/min
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flow_rate(int i2c_handle);
float calculate_average_flow(float flow1, float flow2);
void log_data(float average_flow);
void alarm_control(float average_flow);
void signal_handler(int signal);
int crc8(const uint8_t *data, int len);

// CRC-8 calculation (Sensirion polynomial)
int crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read flow rate from a sensor
int read_flow_rate(int i2c_handle) {
    uint8_t buffer[3];
    int flow_rate = -1; // Initialize to an invalid value

    // Send start command (0x00)
    if (i2cWriteByte(i2c_handle, 0x00) != 0) {
        fprintf(stderr, "Error writing start command to I2C device.\n");
        return -1;
    }

    // Wait 100 ms
    gpioDelay(100000); // 100 ms

    // Read 3 bytes from the sensor
    if (i2cReadDevice(i2c_handle, buffer, 3) != 3) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    // CRC validation
    uint8_t crc_data[2] = {buffer[0], buffer[1]};
    uint8_t crc = crc8(crc_data, 2);
    if (crc != buffer[2]) {
        fprintf(stderr, "CRC validation failed.\n");
        return -1;
    }

    // Convert the data to a signed 16-bit integer
    int16_t raw_flow = (buffer[0] << 8) | buffer[1];
    flow_rate = (int)raw_flow / 120.0; // Convert to ml/min (example scaling)

    return flow_rate;
}

// Function to calculate the average flow rate
float calculate_average_flow(float flow1, float flow2) {
    if (flow1 < 0 && flow2 < 0) {
        return -1.0; // Indicate an error
    } else if (flow1 < 0) {
        return flow2;
    } else if (flow2 < 0) {
        return flow1;
    } else {
        return (flow1 + flow2) / 2.0;
    }
}

// Function to log the data to a file
void log_data(float average_flow) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Average Flow: %.2f ml/min\n", timestamp, average_flow);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to control the alarm based on the average flow rate
void alarm_control(float average_flow) {
    if (average_flow < FLOW_RATE_THRESHOLD) {
        gpioWrite(ALARM_GPIO, 1); // Set GPIO high (alarm on)
    } else {
        gpioWrite(ALARM_GPIO, 0); // Set GPIO low (alarm off)
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C devices
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float flow1 = read_flow_rate(i2c_handle1);
        float flow2 = read_flow_rate(i2c_handle2);
        float average_flow = calculate_average_flow(flow1, flow2);

        if (average_flow >= 0) {
            log_data(average_flow);
            alarm_control(average_flow);
        } else {
            fprintf(stderr, "Error: Could not read flow rate from one or more sensors.\n");
        }

        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioWrite(ALARM_GPIO, 0); // Turn off alarm
    gpioTerminate();

    return 0;
}

