#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100

// Structure to hold timestamp and obstacle detection status
typedef struct {
    time_t timestamp;
    int obstacle_detected;
} DetectionEvent;

// Circular buffer
DetectionEvent detection_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_buffer(time_t timestamp, int obstacle_detected);
void dump_buffer();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing pigpio library.\n");
        return 1;
    }

    printf("Obstacle detection program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor value
        int sensor_value = read_sensor();

        // Get current timestamp
        time_t current_time = time(NULL);

        // Add event to buffer
        add_to_buffer(current_time, sensor_value);

        // Check for obstacle detection (LOW signal)
        if (sensor_value == 0) {
            printf("Obstacle detected!\n");
        }

        // Wait for 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    // Dump the buffer before exiting
    dump_buffer();

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

// Function to initialize the pigpio library and configure GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to add an event to the circular buffer
void add_to_buffer(time_t timestamp, int obstacle_detected) {
    detection_buffer[buffer_index].timestamp = timestamp;
    detection_buffer[buffer_index].obstacle_detected = obstacle_detected;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to dump the contents of the circular buffer to stdout
void dump_buffer() {
    printf("\n--- Detection Log ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE; // Corrected index calculation
        struct tm *timeinfo = localtime(&detection_buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("[%s] Obstacle Detected: %s\n", timestamp_str, detection_buffer[index].obstacle_detected ? "Yes" : "No");
    }
    printf("--- End of Log ---\n");
}

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT. Exiting...\n");
        program_running = 0;
    }
}

