#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_ADDR 0x4C
#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define ACTIVE_TIMEOUT_MS 1000
#define SAMPLE_INTERVAL_MS 500
#define CSV_FILE "fan_health.csv"

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int set_sensor_mode();
int wait_for_active();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
int write_data_to_csv(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Sensor mode setting function
int set_sensor_mode() {
    // Example: Set to continuous measurement mode (adjust as needed)
    char buf[2];
    buf[0] = 0x20; // Register address for mode setting
    buf[1] = 0x03; // Mode value (continuous measurement)

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Active status waiting function
int wait_for_active() {
    int timeout = 0;
    while (timeout < ACTIVE_TIMEOUT_MS) {
        char buf[1];
        buf[0] = 0x02; // Register address for active status
        int result = i2cWriteDevice(i2c_handle, buf, 1);
        if (result < 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", result);
            gpioDelay(100); // Small delay before retry
            timeout += 100;
            continue;
        }

        char status[1];
        result = i2cReadDevice(i2c_handle, status, 1);
        if (result < 0) {
            fprintf(stderr, "Error reading from I2C device: %d\n", result);
            gpioDelay(100); // Small delay before retry
            timeout += 100;
            continue;
        }

        if (status[0] & 0x01) { // Check if active bit is set
            return 0; // Sensor is active
        }

        gpioDelay(100); // Small delay
        timeout += 100;
    }

    fprintf(stderr, "Sensor did not become active within timeout period.\n");
    return -1;
}

// Sensor data reading function
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[1];
    buf[0] = 0x08; // Register address for X acceleration
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    char data[6];
    result = i2cReadDevice(i2c_handle, data, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Data writing to CSV function
int write_data_to_csv(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (csv_file == NULL) {
        csv_file = fopen(CSV_FILE, "a");
        if (csv_file == NULL) {
            fprintf(stderr, "Error opening CSV file for writing.\n");
            return -1;
        }
        fprintf(csv_file, "Timestamp,X,Y,Z\n"); // Write header if file is new
    }

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(csv_file); // Ensure data is written immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set sensor mode
    if (set_sensor_mode() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait for sensor to become active
    if (wait_for_active() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int16_t x, y, z;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&x, &y, &z) == 0) {
            // Write data to CSV file
            if (write_data_to_csv(x, y, z) != 0) {
                fprintf(stderr, "Error writing data to CSV file.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Delay for 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();

    return 0;
}

