#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define LED_PIN 25

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    int init_result;

    // Initialize pigpio library
    init_result = gpioInitialise();
    if (init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", init_result);
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR1_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR2_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
