#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define STALL_DURATION 2 // seconds
#define DEBOUNCE_DELAY 100 // milliseconds

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pins
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to read the sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to check for a stall condition
int is_stalled(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0);
}

// Function to log a stall event to a file
int log_stall_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: Stall detected\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0; // Indicate success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1; // Indicate failure
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the log file
    log_file = fopen("stall_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate(); // Clean up pigpio
        return 1; // Exit if file opening fails
    }

    int stall_count = 0;
    int sensor1_value, sensor2_value;

    printf("Monitoring conveyor belt... Press Ctrl+C to exit.\n");

    while (running) {
        sensor1_value = read_sensor(SENSOR1_PIN);
        sensor2_value = read_sensor(SENSOR2_PIN);

        if (sensor1_value == PI_BAD_GPIO || sensor2_value == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading sensor value. Retrying...\n");
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        if (is_stalled(sensor1_value, sensor2_value)) {
            stall_count++;
            if (stall_count >= (STALL_DURATION * 10)) { // Check every 100ms, so 2 seconds is 20 checks
                if (log_stall_event() == 0) {
                    printf("Stall event logged.\n");
                } else {
                    fprintf(stderr, "Error logging stall event.\n");
                }
                stall_count = 0; // Reset stall count after logging
            }
        } else {
            stall_count = 0; // Reset stall count if not stalled
        }

        gpioDelay(DEBOUNCE_DELAY); // Debounce delay
    }

    // Clean up resources before exiting
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio

    printf("Exiting.\n");
    return 0;
}

