#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// TMAG5170 I2C address
#define TMAG5170_ADDR 0x0E

// TMAG5170 register addresses
#define REG_X_AXIS 0x00
#define REG_Y_AXIS 0x02
#define REG_Z_AXIS 0x04
#define REG_CONFIG 0x06

// Configuration values
#define CONFIG_CONTINUOUS_MODE 0x80
#define CONFIG_RANGE_50mT 0x00

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(sensor_data_t *data);
char* get_iso8601_timestamp();
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the sensor
int configure_sensor() {
    char config_data[2];
    config_data[0] = REG_CONFIG;
    config_data[1] = CONFIG_CONTINUOUS_MODE | CONFIG_RANGE_50mT;

    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write configuration: %d\n", result);
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char reg_data[1];
    char read_data[6];

    // Read X axis
    reg_data[0] = REG_X_AXIS;
    if (i2cWriteDevice(i2c_handle, reg_data, 1) != 0) {
        fprintf(stderr, "Failed to write X axis register address\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, read_data, 2) != 2) {
        fprintf(stderr, "Failed to read X axis data\n");
        return -1;
    }
    data->x = (int16_t)((read_data[0] << 8) | read_data[1]);

    // Read Y axis
    reg_data[0] = REG_Y_AXIS;
    if (i2cWriteDevice(i2c_handle, reg_data, 1) != 0) {
        fprintf(stderr, "Failed to write Y axis register address\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, read_data, 2) != 2) {
        fprintf(stderr, "Failed to read Y axis data\n");
        return -1;
    }
    data->y = (int16_t)((read_data[0] << 8) | read_data[1]);

    // Read Z axis
    reg_data[0] = REG_Z_AXIS;
    if (i2cWriteDevice(i2c_handle, reg_data, 1) != 0) {
        fprintf(stderr, "Failed to write Z axis register address\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, read_data, 2) != 2) {
        fprintf(stderr, "Failed to read Z axis data\n");
        return -1;
    }
    data->z = (int16_t)((read_data[0] << 8) | read_data[1]);

    return 0;
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char buffer[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    char *timestamp = get_iso8601_timestamp();

    if (log_file == NULL) {
        log_file = fopen("magnetic_log.csv", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return -1;
        }
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log data
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

