#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"
#define RETRY_DELAY 60 // seconds

static volatile int running = 1;
static FILE *log_file = NULL;

void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    return 0;
}

void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s %s\n", timestamp, message);
    fflush(log_file);
    printf("%s %s\n", timestamp, message);
}

void cleanup() {
    printf("Cleaning up resources.\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    log_message("Daemon started.");

    while (running) {
        int level = gpioRead(GPIO_PIN);
        if (level == PI_HIGH) {
            log_message("ALERT: Water detected");
        } else if (level < 0) {
            log_message("ERROR: GPIO read failed. Retrying in 60 seconds.");
            sleep(RETRY_DELAY);
            if (initialize_gpio() != 0) {
                log_message("ERROR: GPIO re-initialization failed.");
            }
        }
        sleep(2);
    }

    log_message("Daemon stopped.");
    cleanup();
    return 0;
}

