    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    log_message("Daemon started.");

    while (running) {
        int level = gpioRead(GPIO_PIN);
        if (level == PI_HIGH) {
            log_message("ALERT: Water detected");
        } else if (level < 0) {
            log_message("ERROR: GPIO read failed. Retrying in 60 seconds.");
            sleep(RETRY_DELAY);
            if (initialize_gpio() != 0) {
                log_message("ERROR: GPIO re-initialization failed.");
            }
        }
        sleep(2);
    }

    log_message("Daemon stopped.");
    cleanup();
    return 0;
}

