#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins for sensors A and B
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the mutex and condition variable
pthread_mutex_t mutex;
pthread_cond_t condition;

// Global variables for sensor states
volatile int sensor_a_state = 0;
volatile int sensor_b_state = 0;

// Global variable for the log file pointer
FILE *log_file = NULL;

// Function prototypes
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user);
void log_rotation(const char *direction);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold sensor states
typedef struct {
    int a;
    int b;
} sensor_states_t;

// Function to get current timestamp in millisecond precision
void get_timestamp(char *timestamp)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, 26, "%Y-%m-%d %H:%M:%S", &tm_info);
    sprintf(timestamp + 19, ".%03ld", ts.tv_nsec / 1000000);
}

// Interrupt service routine for sensor A
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio; // unused
    (void)tick; // unused
    (void)user; // unused

    if (level == PI_HIGH) {
        sensor_a_state = 1;
    } else {
        sensor_a_state = 0;
    }
}

// Interrupt service routine for sensor B
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio; // unused
    (void)tick; // unused
    (void)user; // unused

    if (level == PI_HIGH) {
        sensor_b_state = 1;
    } else {
        sensor_b_state = 0;
    }
}

// Function to log rotation events
void log_rotation(const char *direction)
{
    char timestamp[26];
    get_timestamp(timestamp);

    pthread_mutex_lock(&mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%s %s\n", timestamp, direction);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    pthread_mutex_unlock(&mutex);
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Initialization function
int initialize()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for sensors A and B
    gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_B_GPIO, PI_INPUT);

    // Set pull-up resistors
    gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);

    // Initialize mutex and condition variable
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }
    if (pthread_cond_init(&condition, NULL) != 0) {
        fprintf(stderr, "Condition variable initialization failed\n");
        pthread_mutex_destroy(&mutex);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    pthread_mutex_lock(&mutex);
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        pthread_mutex_unlock(&mutex);
        pthread_mutex_destroy(&mutex);
        pthread_cond_destroy(&condition);
        gpioTerminate();
        return 1;
    }
    pthread_mutex_unlock(&mutex);

    // Set up interrupt handlers for sensors A and B
    if (gpioSetISRFuncEx(SENSOR_A_GPIO, RISING_EDGE, 0, sensor_a_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR for sensor A\n");
        cleanup();
        return 1;
    }
    if (gpioSetISRFuncEx(SENSOR_B_GPIO, RISING_EDGE, 0, sensor_b_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR for sensor B\n");
        cleanup();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup()
{
    // Disable interrupts
    gpioSetISRFuncEx(SENSOR_A_GPIO, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(SENSOR_B_GPIO, RISING_EDGE, 0, NULL, NULL);

    // Close the log file
    pthread_mutex_lock(&mutex);
    if (log_file != NULL) {
        fclose(log_file);
    }
    pthread_mutex_unlock(&mutex);

    // Destroy mutex and condition variable
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&condition);

    // Terminate pigpio library
    gpioTerminate();
}

int main()
{
    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the system
    if (initialize() != 0) {
        return 1;
    }

    printf("Quadrature encoder logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Wait for a short period
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 10000000; // 10 milliseconds
        nanosleep(&sleep_time, NULL);

        // Check for rotation events
        int a_state = sensor_a_state;
        int b_state = sensor_b_state;

        // Reset sensor states
        sensor_a_state = 0;
        sensor_b_state = 0;

        // Determine the direction of rotation
        if (a_state == 1 && b_state == 0) {
            log_rotation("CW");
        } else if (a_state == 0 && b_state == 1) {
            log_rotation("CCW");
        }
    }

    return 0;
}

