#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <syslog.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>
#include <poll.h>
#include <bcm2835.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN RPI_GPIO_P1_16 // GPIO23 (BCM 23)
#define LED_PIN RPI_GPIO_P1_12         // GPIO18 (BCM 18)

// Define debounce delay in milliseconds
#define DEBOUNCE_DELAY_MS 50

// Global variables
volatile sig_atomic_t program_running = 1;
int led_state = 0; // 0: off, 1: on

// Function prototypes
int gpio_init(void);
int gpio_read(int pin);
int gpio_write(int pin, int value);
void led_on(void);
void led_off(void);
void signal_handler(int signal);
void log_event(const char *message);

// Signal handler function
void signal_handler(int signal) {
  syslog(LOG_INFO, "Signal received, shutting down...");
  program_running = 0;
  led_off(); // Turn off the LED
  bcm2835_close(); // Close the bcm2835 library
  closelog(); // Close syslog
  exit(0);
}

// Initialize GPIO using bcm2835 library
int gpio_init(void) {
  if (!bcm2835_init()) {
    syslog(LOG_ERR, "bcm2835_init failed. Are you running as root?");
    return 1;
  }

  // Set GPIO23 as input
  bcm2835_gpio_fsel(TOUCH_SENSOR_PIN, BCM2835_GPIO_FSEL_INPT);
  bcm2835_gpio_set_pud(TOUCH_SENSOR_PIN, BCM2835_GPIO_PUD_DOWN); // Optional: Pull-down resistor

  // Set GPIO18 as output
  bcm2835_gpio_fsel(LED_PIN, BCM2835_GPIO_FSEL_OUTP);

  return 0;
}

// Read the value of a GPIO pin
int gpio_read(int pin) {
  return bcm2835_gpio_lev(pin);
}

// Write a value to a GPIO pin
int gpio_write(int pin, int value) {
  bcm2835_gpio_write(pin, value);
  return 0;
}

// Turn the LED on
void led_on(void) {
  if (led_state == 0) {
    gpio_write(LED_PIN, HIGH);
    led_state = 1;
    syslog(LOG_INFO, "LED turned ON");
  }
}

// Turn the LED off
void led_off(void) {
  if (led_state == 1) {
    gpio_write(LED_PIN, LOW);
    led_state = 0;
    syslog(LOG_INFO, "LED turned OFF");
  }
}

// Log an event to syslog
void log_event(const char *message) {
  struct timeval tv;
  gettimeofday(&tv, NULL);
  struct tm *tm = localtime(&tv.tv_sec);
  char timestamp[30];
  strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
  char log_message[200];
  snprintf(log_message, sizeof(log_message), "%s.%06ld: %s", timestamp, tv.tv_usec, message);
  syslog(LOG_INFO, "%s", log_message);
}

int main(void) {
  // Open syslog
  openlog("touch_sensor", LOG_PID | LOG_CONS, LOG_USER);

  // Register signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Initialize GPIO
  if (gpio_init() != 0) {
    syslog(LOG_ERR, "GPIO initialization failed");
    closelog();
    return 1;
  }

  log_event("Program started");

  // Main loop
  while (program_running) {
    // Read the touch sensor value
    int touch_value = gpio_read(TOUCH_SENSOR_PIN);

    // Debounce and control the LED
    if (touch_value == HIGH) {
      led_on();
      bcm2835_delay(DEBOUNCE_DELAY_MS); // Debounce delay
      while (gpio_read(TOUCH_SENSOR_PIN) == HIGH && program_running) {
        bcm2835_delay(DEBOUNCE_DELAY_MS);
      }
      led_off();
    } else {
      led_off();
    }

    bcm2835_delay(1); // Small delay to prevent busy-waiting
  }

  // Cleanup (should not reach here if signal handler works correctly)
  led_off();
  bcm2835_close();
  closelog();

  return 0;
}

