        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        return 1;
    }
    return 0;
}

// Function to setup the interrupt on the touch sensor pin
int setup_interrupt() {
    if (gpioSetAlertFunc(TOUCH_SENSOR_PIN, debounce) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO%d\n", TOUCH_SENSOR_PIN);
        return 1;
    }
    return 0;
}

