#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>

// Define GPIO pins (BCM numbering)
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define LED1_PIN 27
#define LED2_PIN 22

// Define log buffer size
#define LOG_BUFFER_SIZE 100

// Define debounce delay (milliseconds)
#define DEBOUNCE_DELAY 50

// Define log entry structure
typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} log_entry_t;

// Define circular buffer structure
typedef struct {
    log_entry_t entries[LOG_BUFFER_SIZE];
    int head;
    int count;
    int overflow_count;
} circular_buffer_t;

// Global variables
circular_buffer_t log_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int pin);
void control_led(int pin, int state);
void log_event(int sensor_pin, int state);
void print_log_buffer();
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int pin) {
    int value = digitalRead(pin);
    if (value == -1) {
        fprintf(stderr, "Error reading sensor %d: %s\n", pin, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to control LED state
void control_led(int pin, int state) {
    if (digitalWrite(pin, state) == -1) {
        fprintf(stderr, "Error writing to LED %d: %s\n", pin, strerror(errno));
    }
}

// Function to log event to circular buffer
void log_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    if (now == -1) {
        fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
        return;
    }

    log_buffer.entries[log_buffer.head].sensor_pin = sensor_pin;
    log_buffer.entries[log_buffer.head].timestamp = now;
    log_buffer.entries[log_buffer.head].state = state;

    log_buffer.head = (log_buffer.head + 1) % LOG_BUFFER_SIZE;
    if (log_buffer.count < LOG_BUFFER_SIZE) {
        log_buffer.count++;
    } else {
        log_buffer.overflow_count++;
    }
}

// Function to print log buffer to stdout
void print_log_buffer() {
    printf("--- Log Buffer ---\n");
    for (int i = 0; i < log_buffer.count; i++) {
        int index = (log_buffer.head - log_buffer.count + i + LOG_BUFFER_SIZE) % LOG_BUFFER_SIZE;
        struct tm *timeinfo = localtime(&log_buffer.entries[index].timestamp);
        char timestamp_str[64];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("Sensor: %d, Timestamp: %s, State: %d\n", log_buffer.entries[index].sensor_pin, timestamp_str, log_buffer.entries[index].state);
    }
    printf("Overflow Count: %d\n", log_buffer.overflow_count);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, shutting down...\n", signal);
    control_led(LED1_PIN, LOW);
    control_led(LED2_PIN, LOW);
    print_log_buffer();
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set pin modes
    pinMode(SENSOR1_PIN, INPUT);
    pinMode(SENSOR2_PIN, INPUT);
    pinMode(LED1_PIN, OUTPUT);
    pinMode(LED2_PIN, OUTPUT);

    // Initialize circular buffer
    log_buffer.head = 0;
    log_buffer.count = 0;
    log_buffer.overflow_count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int sensor1_state = LOW;
    int sensor2_state = LOW;

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int new_sensor1_state = read_sensor(SENSOR1_PIN);
        int new_sensor2_state = read_sensor(SENSOR2_PIN);

        if (new_sensor1_state != -1 && new_sensor1_state != sensor1_state) {
            sensor1_state = new_sensor1_state;
            control_led(LED1_PIN, sensor1_state);
            log_event(SENSOR1_PIN, sensor1_state);
            delay(DEBOUNCE_DELAY);
        }

        if (new_sensor2_state != -1 && new_sensor2_state != sensor2_state) {
            sensor2_state = new_sensor2_state;
            control_led(LED2_PIN, sensor2_state);
            log_event(SENSOR2_PIN, sensor2_state);
            delay(DEBOUNCE_DELAY);
        }

        delay(1); // Small delay to reduce CPU usage
    }

    return 0;
}

