        if (log_file == NULL) {
            perror("Error opening log file");
            return -1; // Indicate error
        }
    }

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to disk

    return 0;
}

int main() {
    int current_state, previous_state = -1; // Initialize to an invalid state
    int gpio_value;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    FILE *export_fp = fopen("/sys/class/gpio/export", "w");
    if (export_fp == NULL) {
        perror("Error opening GPIO export file");
        return 1;
    }
    fprintf(export_fp, "%d", GPIO_PIN);
    fclose(export_fp);

    // Set GPIO direction to input
    FILE *direction_fp = fopen("/sys/class/gpio/gpio17/direction", "w");
    if (direction_fp == NULL) {
        perror("Error opening GPIO direction file");
        return 1;
    }
    fprintf(direction_fp, "in");
    fclose(direction_fp);

    // Enable pull-up resistor
    FILE *pull_fp = fopen("/sys/class/gpio/gpio17/pull", "w");
    if (pull_fp == NULL) {
        perror("Error opening GPIO pull file");
        return 1;
    }
    fprintf(pull_fp, "up");
    fclose(pull_fp);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        gpio_value = read_gpio(GPIO_PIN);
        if (gpio_value == -1) {
            fprintf(stderr, "Error reading GPIO, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        current_state = (gpio_value == 0) ? 1 : 0; // Active low

        if (current_state != previous_state) {
            if (current_state == 1) {
                if (log_event("Rain Detected") != 0) {
                    fprintf(stderr, "Error logging rain event.\n");
                }
            } else {
                if (log_event("No Rain") != 0) {
                    fprintf(stderr, "Error logging no rain event.\n");
                }
            }
            previous_state = current_state;
        }

        usleep(500000); // 500ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Unexport GPIO pin
    FILE *unexport_fp = fopen("/sys/class/gpio/unexport", "w");
    if (unexport_fp != NULL) {
        fprintf(unexport_fp, "%d", GPIO_PIN);
        fclose(unexport_fp);
    }

    printf("Exiting.\n");
    return 0;
}

