#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor states and timestamps
typedef struct {
    int sensor1_state;
    int sensor2_state;
    long long timestamp;
} SensorData;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void log_data(SensorData data);
void calculate_rpm(SensorData data);
void signal_handler(int signal);
void sensor1_callback(int gpio, int level, uint32_t tick);
void sensor2_callback(int gpio, int level, uint32_t tick);

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = tick;

    if (current_tick - last_tick > DEBOUNCE_TIME * 1000) { // Debounce
        SensorData data;
        data.sensor1_state = level;
        data.sensor2_state = gpioRead(SENSOR2_GPIO);
        data.timestamp = time(NULL);
        log_data(data);
        calculate_rpm(data);
        last_tick = current_tick;
    }
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = tick;

    if (current_tick - last_tick > DEBOUNCE_TIME * 1000) { // Debounce
        SensorData data;
        data.sensor1_state = gpioRead(SENSOR1_GPIO);
        data.sensor2_state = level;
        data.timestamp = time(NULL);
        log_data(data);
        calculate_rpm(data);
        last_tick = current_tick;
    }
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Set up interrupts for both sensors
    gpioSetAlertFuncEx(SENSOR1_GPIO, sensor1_callback, NULL);
    gpioSetAlertFuncEx(SENSOR2_GPIO, sensor2_callback, NULL);

    return 0;
}

// Function to cleanup the pigpio library and close the log file
void cleanup_gpio() {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Function to log data to the CSV file
void log_data(SensorData data) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&data.timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp_str, data.sensor1_state, data.sensor2_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to calculate and print the RPM
void calculate_rpm(SensorData data) {
    // This is a simplified example.  A real implementation would
    // need to track the time between transitions for each sensor.
    // This example assumes a single transition per revolution.
    static long long last_timestamp1 = 0;
    static long long last_timestamp2 = 0;
    long long time_diff1 = 0, time_diff2 = 0;
    double rpm1 = 0.0, rpm2 = 0.0;

    if (data.sensor1_state == 1) {
        if (last_timestamp1 != 0) {
            time_diff1 = data.timestamp - last_timestamp1;
            rpm1 = 60000.0 / (double)time_diff1; // Convert seconds to milliseconds
        }
        last_timestamp1 = data.timestamp;
    }

    if (data.sensor2_state == 1) {
        if (last_timestamp2 != 0) {
            time_diff2 = data.timestamp - last_timestamp2;
            rpm2 = 60000.0 / (double)time_diff2; // Convert seconds to milliseconds
        }
        last_timestamp2 = data.timestamp;
    }

    printf("RPM Sensor 1: %.2f, Sensor 2: %.2f\n", rpm1, rpm2);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    printf("Monitoring RPM... Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1); // Sleep for 1 second
    }

    // Cleanup and exit
    cleanup_gpio();
    printf("Exiting.\n");
    return 0;
}

