#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SENSOR_ADDR 0x1D
#define CTRL1_REG 0x20
#define DATA_REG 0x28
#define LED_GPIO 17
#define VIBRATION_THRESHOLD 500
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
int log_event(double magnitude);
int control_led(int on);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the sensor
int init_sensor() {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        // Clear power-down bit
        if (i2cWriteByteData(i2c_handle, CTRL1_REG, 0x00) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: Failed to clear power-down bit. Retries remaining: %d\n", retries);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }
    fprintf(stderr, "Error: Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Read sensor data with retries
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int retries = RETRY_COUNT;
    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, DATA_REG, buffer, 6) == 6) {
            *x = (int16_t)((buffer[1] << 8) | buffer[0]);
            *y = (int16_t)((buffer[3] << 8) | buffer[2]);
            *z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0; // Success
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Retries remaining: %d\n", retries);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }
    fprintf(stderr, "Error: Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Calculate Euclidean magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Log event to file
int log_event(double magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Peak Vibration: %.2f\n", timestamp, magnitude);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Control LED
int control_led(int on) {
    gpioWrite(LED_GPIO, on);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    double magnitude;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > VIBRATION_THRESHOLD) {
                printf("Threshold exceeded! Magnitude: %.2f\n", magnitude);
                log_event(magnitude);
                control_led(1); // Turn LED on
                gpioDelay(1000);  // Wait for 1 second
                control_led(0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data in main loop.\n");
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

