#include <unistd.h>

// Define GPIO pins
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LED_PIN 18

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read sensor data
int read_sensor(int gpio_pin) {
    return (gpioRead(gpio_pin) == 0) ? 1 : 0; // Active low
}

// Function to control the LED
void control_led(int led_pin, int state) {
    gpioWrite(led_pin, state);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as input or output
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(SENSOR3_PIN, PI_INPUT);
    gpioSetMode(SENSOR4_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Read sensor data
        int sensor1 = read_sensor(SENSOR1_PIN);
        int sensor2 = read_sensor(SENSOR2_PIN);
        int sensor3 = read_sensor(SENSOR3_PIN);
        int sensor4 = read_sensor(SENSOR4_PIN);

        // Check if any sensor detects an obstacle
        int obstacle_detected = (sensor1 || sensor2 || sensor3 || sensor4);

        // Control the LED
        control_led(LED_PIN, obstacle_detected);

        // Wait 50 milliseconds
        usleep(50000); // 50ms
    }

    // Clean up GPIO resources
    gpioTerminate();

    return 0;
}

