#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the GPIO pins connected to the TTP226 sensor outputs
const int sensor_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_sensors = 8;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
    printf("\nCaught SIGINT, exiting gracefully...\n");
}

// Function to get the current timestamp in ISO 8601 format
char *get_iso8601_timestamp()
{
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char *)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL)
    {
        perror("Failed to allocate memory for timestamp");
        return NULL; // Return NULL to indicate failure
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return timestamp;
}

// Function to log the sensor state change to the console
void log_sensor_state(int sensor_index, int pin, int state)
{
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp, skipping log.\n");
        return;
    }

    printf("%s Sensor %d (BCM %d): %s\n", timestamp, sensor_index, pin, state ? "Touched" : "Released");
    free(timestamp); // Free the allocated memory
}

int main()
{
    // Register the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed: %d\n", gpioInitialise());
        return 1; // Exit with an error code
    }

    // Set the GPIO pins as inputs
    for (int i = 0; i < num_sensors; i++)
    {
        gpioSetMode(sensor_pins[i], PI_INPUT);
    }

    // Main loop to continuously monitor the sensor states
    while (!terminate)
    {
        for (int i = 0; i < num_sensors; i++)
        {
            int current_state = gpioRead(sensor_pins[i]);
            log_sensor_state(i, sensor_pins[i], current_state);
        }

        gpioDelay(50000); // Delay for 50 milliseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0; // Exit successfully
}

