#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Constants
#define VEML7700_ADDR 0x48
#define VEML7700_ALS_CONF 0x00
#define VEML7700_ALS_DATA 0x04
#define GPIO_PIN 18
#define PWM_FREQUENCY 1000
#define LOG_FILE "grow_log.txt"

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_pwm();
int init_log();
int read_lux();
int map_lux_to_brightness(int lux);
int set_pwm_duty_cycle(int duty_cycle);
int log_data(int lux, int brightness, int error_code);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_fd = wiringPiI2CSetupInterface("/dev/i2c-1", VEML7700_ADDR);
    if (i2c_fd == -1) {
        perror("Failed to initialize I2C");
        return -1;
    }
    printf("I2C initialized successfully.\n");
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (wiringPiSetupGpio() == -1) {
        perror("Failed to initialize wiringPi");
        return -1;
    }
    pinMode(GPIO_PIN, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetRange(100);
    pwmSetClock(192); // Adjust clock for 1kHz frequency
    printf("GPIO initialized successfully.\n");
    return 0;
}

// Initialize PWM
int init_pwm() {
    pwmWrite(GPIO_PIN, 0); // Initially turn off the LED
    printf("PWM initialized successfully.\n");
    return 0;
}

// Initialize log file
int init_log() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }
    printf("Log file initialized successfully.\n");
    return 0;
}

// Read lux value from VEML7700
int read_lux() {
    int lux = -1;
    int retry_count = 0;
    const int max_retries = 3;

    while (retry_count < max_retries) {
        lux = wiringPiI2CReadReg16(i2c_fd, VEML7700_ALS_DATA);
        if (lux >= 0) {
            // VEML7700 returns data in little-endian format, so swap bytes
            lux = (lux >> 8) | (lux << 8);
            return lux;
        } else {
            perror("Failed to read lux value");
            retry_count++;
            delay(100); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read lux value after %d retries.\n", max_retries);
    return -1; // Indicate failure
}

// Map lux value to brightness level
int map_lux_to_brightness(int lux) {
    if (lux < 100) {
        return 100;
    } else if (lux < 500) {
        return 75;
    } else if (lux < 1000) {
        return 50;
    } else {
        return 25;
    }
}

// Set PWM duty cycle
int set_pwm_duty_cycle(int duty_cycle) {
    pwmWrite(GPIO_PIN, duty_cycle);
    return 0;
}

// Log data to file
int log_data(int lux, int brightness, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, Lux: %d, Brightness: %d, Error: %d\n", timestamp, lux, brightness, error_code);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_fd != -1) {
        // No specific I2C cleanup function in wiringPi, but we can reset the bus
        // wiringPiI2CWrite(i2c_fd, 0); // Example: Reset the sensor (if applicable)
        close(i2c_fd);
        printf("I2C bus closed.\n");
    }
    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }
    pwmWrite(GPIO_PIN, 0); // Turn off LED
    printf("Grow light turned off.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (init_i2c() != 0) return 1;
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }
    if (init_pwm() != 0) {
        cleanup();
        return 1;
    }
    if (init_log() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int lux = read_lux();
        int brightness = 0;
        int error_code = 0;

        if (lux == -1) {
            error_code = 1; // Sensor read error
        } else {
            brightness = map_lux_to_brightness(lux);
            set_pwm_duty_cycle(brightness);
        }

        log_data(lux, brightness, error_code);
        delay(1000); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

