    pwmWrite(GPIO_PIN, duty_cycle);
    return 0;
}

// Log data to file
int log_data(int lux, int brightness, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, Lux: %d, Brightness: %d, Error: %d\n", timestamp, lux, brightness, error_code);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_fd != -1) {
        // No specific I2C cleanup function in wiringPi, but we can reset the bus
        // wiringPiI2CWrite(i2c_fd, 0); // Example: Reset the sensor (if applicable)
        close(i2c_fd);
        printf("I2C bus closed.\n");
    }
    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }
    pwmWrite(GPIO_PIN, 0); // Turn off LED
    printf("Grow light turned off.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (init_i2c() != 0) return 1;
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }
    if (init_pwm() != 0) {
        cleanup();
        return 1;
    }
    if (init_log() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int lux = read_lux();
        int brightness = 0;
        int error_code = 0;

        if (lux == -1) {
            error_code = 1; // Sensor read error
        } else {
            brightness = map_lux_to_brightness(lux);
            set_pwm_duty_cycle(brightness);
        }

        log_data(lux, brightness, error_code);
        delay(1000); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

