    gpioSetMode(CHANNEL_2_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_2_PIN, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_3_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_3_PIN, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_4_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_4_PIN, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_5_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_5_PIN, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_6_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_6_PIN, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_7_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_7_PIN, PI_PUD_DOWN);
    gpioSetMode(CHANNEL_8_PIN, PI_INPUT);
    gpioSetPullUpDown(CHANNEL_8_PIN, PI_PUD_DOWN);

    // Set GPIO pin for LED as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

