int debounce_channel(int pin) {
    int current_state = gpioRead(pin);
    int last_state = current_state;
    int stable_count = 0;

    // Wait for DEBOUNCE_TIME milliseconds
    for (int i = 0; i < DEBOUNCE_TIME; i++) {
        gpioDelay(1000); // 1ms delay
        current_state = gpioRead(pin);
        if (current_state == last_state) {
            stable_count++;
        } else {
            stable_count = 0; // Reset if state changes
        }
        last_state = current_state;
    }

    // Return 1 if the state is stable, 0 otherwise
    return (stable_count == DEBOUNCE_TIME);
}

