#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_DEFAULT 0xC810 // Continuous mode, 100ms conversion time
#define LUX_CALIBRATION 0.01 // Example calibration factor (adjust as needed)

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_write_word_data(int fd, uint8_t reg, uint16_t data);
int i2c_read_word_data(int fd, uint8_t reg);
float calculate_lux(uint16_t raw_result);
int log_data(const char *timestamp, float lux_value);
void signal_handler(int signal);

// I2C write function with error handling
int i2c_write_word_data(int fd, uint8_t reg, uint16_t data) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = data & 0xFF;       // LSB
    buf[2] = (data >> 8) & 0xFF; // MSB

    if (write(fd, buf, 3) != 3) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function with error handling
int i2c_read_word_data(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }

    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }

    return (buf[1] << 8) | buf[0]; // Byte swap for big-endian
}

// Calculate lux value from raw result
float calculate_lux(uint16_t raw_result) {
    uint16_t exponent = (raw_result >> 12) & 0x0F;
    uint16_t result = raw_result & 0x0FFF;
    return result * (0.01 * (1 << exponent));
}

// Log data to file and stdout
int log_data(const char *timestamp, float lux_value) {
    FILE *fp = fopen("light_data.txt", "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, lux_value);
    if (ferror(fp)) {
        perror("Failed to write to log file");
        fclose(fp);
        return -1;
    }

    fprintf(stdout, "%s, %.2f\n", timestamp, lux_value);
    if (ferror(stdout)) {
        perror("Failed to write to stdout");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Failed to close log file");
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Configure OPT3001
    if (i2c_write_word_data(i2c_fd, CONFIG_REG, CONFIG_DEFAULT) < 0) {
        close(i2c_fd);
        return 1;
    }
    usleep(100000); // Wait 100ms

    // Main loop
    while (program_running) {
        // Read result from OPT3001
        int raw_result = i2c_read_word_data(i2c_fd, RESULT_REG);
        if (raw_result < 0) {
            fprintf(stderr, "Failed to read result, retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Calculate lux value
        float lux_value = calculate_lux((uint16_t)raw_result);

        // Get current timestamp
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

        // Log data
        if (log_data(timestamp, lux_value) < 0) {
            fprintf(stderr, "Failed to log data, skipping iteration.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    close(i2c_fd);

    return 0;
}

