#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define DEBOUNCE_MS 50
#define LOG_FILE "touch_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "Caught signal %d, exiting...\n", signal);
}

int main() {
    int rc;
    int last_state = 0;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char log_message[100];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Touch sensor monitoring started on GPIO %d\n", GPIO_PIN);

    while (running) {
        int current_state = gpioRead(GPIO_PIN);

        if (current_state != last_state) {
            // Debounce
            gpioDelay(DEBOUNCE_MS * 1000); // Convert ms to microseconds
            current_state = gpioRead(GPIO_PIN); // Re-read after debounce

            if (current_state != last_state) {
                // State changed after debounce
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                if (current_state == 1) {
                    // Touch detected
                    snprintf(log_message, sizeof(log_message), "%s: Touch Detected", timestamp);
                    fprintf(log_file, "%s\n", log_message);
                    fflush(log_file);
                    fprintf(stderr, "%s\n", log_message);
                } else {
                    // Touch released
                    snprintf(log_message, sizeof(log_message), "%s: Touch Released", timestamp);
                    fprintf(log_file, "%s\n", log_message);
                    fflush(log_file);
                    fprintf(stderr, "%s\n", log_message);
                }

                last_state = current_state;
            }
        }

        gpioDelay(1000); // Check every 1ms
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    fprintf(stderr, "Exiting cleanly.\n");
    return 0;
}

