#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x36
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 100.0
#define LOG_FILE "cooling_log.csv"
#define ERROR_STATUS "ERROR"
#define INVALID_STATUS "INVALID"
#define HEADER "Timestamp,Flow Rate (ml/min),Status"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int16_t *flow_rate, uint8_t *crc);
uint8_t calculate_crc(const uint8_t *data, size_t len);
const char *validate_flow_rate(int16_t flow_rate);
void log_data(const char *timestamp, float flow_rate, const char *status, uint8_t raw_flags);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional, but good practice)
typedef struct {
    int16_t flow_rate;
    uint8_t crc;
} sensor_data_t;

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "%s\n", HEADER);
    }

    // Main loop
    while (!terminate) {
        int16_t flow_rate;
        uint8_t crc;
        uint8_t raw_flags;
        const char *status;
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        // Read sensor data
        if (read_sensor_data(&flow_rate, &crc) == 0) {
            // Validate flow rate
            status = validate_flow_rate(flow_rate);
            raw_flags = 0; // No flags in this example, but could be read from sensor

            // Log data
            log_data(timestamp, (float)flow_rate, status, raw_flags);
        } else {
            // Log error
            log_data(timestamp, 0.0, ERROR_STATUS, 0); // Log error with 0 flow rate
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int16_t *flow_rate, uint8_t *crc) {
    char buf[3];
    int result;

    // Send command (0x00 0x00) to trigger a measurement
    result = i2cWriteByteData(i2c_handle, 0x00, 0x00);
    if (result < 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return -1;
    }

    // Wait at least 2ms
    gpioDelay(2000); // 2000 microseconds = 2 milliseconds

    // Read 3 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1;
    }

    // Extract flow rate and CRC
    *flow_rate = (int16_t)((buf[0] << 8) | buf[1]);
    *crc = buf[2];

    return 0;
}

// Calculate CRC-8
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF; // Initial value
    size_t i, j;

    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ 0x31; // Polynomial: 0x31
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate flow rate
const char *validate_flow_rate(int16_t flow_rate) {
    if (flow_rate < FLOW_RATE_MIN || flow_rate > FLOW_RATE_MAX) {
        return INVALID_STATUS;
    } else {
        return "VALID";
    }
}

// Log data to file
void log_data(const char *timestamp, float flow_rate, const char *status, uint8_t raw_flags) {
    fprintf(log_file, "%s,%.2f,%s\n", timestamp, flow_rate, status);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

