#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Global variables for signal handling
static volatile int running = 1;
static int log_file_fd = -1;

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp(char* timestamp_buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm* timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp_buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp_buffer;
}

// Function to write data to CSV file
int write_to_csv(const char* timestamp, int left, int middle, int right) {
    char csv_line[256];
    int bytes_written;

    snprintf(csv_line, sizeof(csv_line), "%s,%d,%d,%d\n", timestamp, left, middle, right);

    if (log_file_fd == -1) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    bytes_written = write(log_file_fd, csv_line, strlen(csv_line));
    if (bytes_written == -1) {
        perror("Error writing to log file");
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);

    // Open log file in append mode
    log_file_fd = open("path_log.csv", O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
    if (log_file_fd == -1) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Main loop
    char timestamp[32];
    while (running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int middle_value = read_sensor(MIDDLE_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        // Get timestamp
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        // Write data to CSV file
        if (write_to_csv(timestamp, left_value, middle_value, right_value) != 0) {
            fprintf(stderr, "Error writing to CSV file.\n");
        }

        // Delay for 50ms
        usleep(50000); // 50ms
    }

    // Clean up and exit
    close(log_file_fd);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

