#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_CHIP 4
#define GPIO_TOUCH 23
#define GPIO_LED 24
#define LOG_FILE "touch_log.txt"

static volatile int keep_running = 1;
static int log_fd = -1;

void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        keep_running = 0;
        fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
    }
}

int gpio_export(int gpio) {
    int fd;
    struct gpio_request req;

    fd = open("/dev/gpiochip" GPIO_CHIP, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    req.gpio = gpio;
    if (ioctl(fd, GPIO_GET_LINE, &req) < 0) {
        if (errno == ENOENT) {
            req.flags = 0;
            if (ioctl(fd, GPIO_REQUEST, &req) < 0) {
                fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
                close(fd);
                return -1;
            }
        } else {
            fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
            close(fd);
            return -1;
        }
    }

    close(fd);
    return 0;
}

int gpio_unexport(int gpio) {
    int fd;
    struct gpio_request req;

    fd = open("/dev/gpiochip" GPIO_CHIP, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    req.gpio = gpio;
    if (ioctl(fd, GPIO_GET_LINE, &req) < 0) {
        if (errno == ENOENT) {
            close(fd);
            return 0; // Already unexported
        } else {
            fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
            close(fd);
            return -1;
        }
    }

    req.flags = 0; // Unexport
    if (ioctl(fd, GPIO_REQUEST, &req) < 0) {
        fprintf(stderr, "Error unexporting GPIO line: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int gpio_set_direction(int gpio, const char *direction) {
    int fd;
    struct gpio_line_request req;

    fd = open("/dev/gpiochip" GPIO_CHIP, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    req.line_offset = gpio;
    req.consumer = direction;
    if (ioctl(fd, GPIO_GET_LINE, &req) < 0) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (ioctl(fd, GPIO_SET_DIRECTION, &req) < 0) {
        fprintf(stderr, "Error setting GPIO direction: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int gpio_read(int gpio) {
    int fd;
    struct gpio_line_request req;
    struct gpio_line_values vals;

    fd = open("/dev/gpiochip" GPIO_CHIP, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    req.line_offset = gpio;
    req.consumer = "touch_read";
    if (ioctl(fd, GPIO_GET_LINE, &req) < 0) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    vals.mask = 1 << gpio;
    if (ioctl(fd, GPIO_GET_VALUES, &vals) < 0) {
        fprintf(stderr, "Error getting GPIO values: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return (vals.values[0] >> gpio) & 1;
}

int gpio_write(int gpio, int value) {
    int fd;
    struct gpio_line_request req;
    struct gpio_line_values vals;

    fd = open("/dev/gpiochip" GPIO_CHIP, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    req.line_offset = gpio;
    req.consumer = "touch_write";
    if (ioctl(fd, GPIO_GET_LINE, &req) < 0) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    vals.mask = 1 << gpio;
    vals.values[0] = (value ? 1 : 0) << gpio;
    if (ioctl(fd, GPIO_SET_VALUES, &vals) < 0) {
        fprintf(stderr, "Error setting GPIO values: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int log_event(int touch_state, int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    char log_entry[100];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    snprintf(log_entry, sizeof(log_entry), "%s - Touch: %d, LED: %d\n", timestamp, touch_state, led_state);

    if (write(log_fd, log_entry, strlen(log_entry)) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    int touch_state = 0;
    int led_state = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpio_export(GPIO_TOUCH) < 0 || gpio_export(GPIO_LED) < 0) {
        fprintf(stderr, "Failed to export GPIO pins. Exiting.\n");
        return 1;
    }

    if (gpio_set_direction(GPIO_TOUCH, "in") < 0 || gpio_set_direction(GPIO_LED, "out") < 0) {
        fprintf(stderr, "Failed to set GPIO direction. Exiting.\n");
        gpio_unexport(GPIO_TOUCH);
        gpio_unexport(GPIO_LED);
        return 1;
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpio_unexport(GPIO_TOUCH);
        gpio_unexport(GPIO_LED);
        return 1;
    }

    printf("Touch-activated lamp simulation started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int new_touch_state = gpio_read(GPIO_TOUCH);
        if (new_touch_state < 0) {
            fprintf(stderr, "Error reading touch sensor. Exiting.\n");
            break;
        }

        if (new_touch_state != touch_state) {
            touch_state = new_touch_state;
            led_state = !led_state; // Toggle LED state
            if (gpio_write(GPIO_LED, led_state) < 0) {
                fprintf(stderr, "Error writing to LED. Exiting.\n");
                break;
            }

            if (log_event(touch_state, led_state) < 0) {
                fprintf(stderr, "Error logging event. Exiting.\n");
                break;
            }
        }

        sleep(1); // Check every second
    }

    printf("Cleaning up...\n");

    close(log_fd);
    gpio_unexport(GPIO_TOUCH);
    gpio_unexport(GPIO_LED);

    printf("Exiting.\n");
    return 0;
}

