#include <gpiod.h>

#define GPIOCHIP "gpiochip0"
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18

static struct gpiod_chip *chip;
static struct gpiod_line *flame_line;
static struct gpiod_line *buzzer_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    terminate = 1;
}

static int setup_gpio(void)
{
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        fprintf(stderr, "Error getting flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "Error requesting flame sensor line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static int setup_logging(void)
{
    log_file = fopen("alert_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

static int log_event(const char *message)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (t == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d: %s\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                t->tm_hour, t->tm_min, t->tm_sec, message) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void)
{
    struct timespec sleep_time = {0, 100000000}; // 100ms
    struct timespec buzzer_duration = {2, 0}; // 2 seconds
    int flame_detected = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_gpio() < 0) {
        return 1;
    }

    if (setup_logging() < 0) {
        cleanup();
        return 1;
    }

    if (log_event("System started") < 0) {
        cleanup();
        return 1;
    }

    while (!terminate) {
        int value = gpiod_line_get_value(flame_line);
        if (value < 0) {
            fprintf(stderr, "Error reading flame sensor value: %s\n", strerror(errno));
            break;
        }

        if (value == 0 && !flame_detected) {
            flame_detected = 1;
            if (log_event("FLAME DETECTED") < 0) {
                break;
            }
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                fprintf(stderr, "Error setting buzzer line value: %s\n", strerror(errno));
                break;
            }
            nanosleep(&buzzer_duration, NULL);
            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                fprintf(stderr, "Error setting buzzer line value: %s\n", strerror(errno));
                break;
            }
        } else if (value == 1) {
            flame_detected = 0;
        }

        nanosleep(&sleep_time, NULL);
    }

    if (log_event("System stopped") < 0) {
        // Don't exit if logging fails, but indicate the error
        fprintf(stderr, "Error logging system stop event.\n");
    }

    cleanup();
    return 0;
}

