#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define LED_PIN 17
#define DEBOUNCE_TIME 200 // milliseconds
#define LOG_FILE "touch_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *info;
    char *buffer = malloc(sizeof(char) * 30);
    if (buffer == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for timestamp.\n");
        return NULL;
    }

    time(&rawtime);
    info = gmtime(&rawtime);

    strftime(buffer, 30, "%Y-%m-%dT%H:%M:%SZ", info);
    return buffer;
}

// Function to log a timestamp to the file
int log_timestamp(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s\n", timestamp);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    int touch_state = 1; // Initialize to HIGH (not touched)
    int last_touch_state = 1;
    unsigned int last_touch_time = 0;
    char *timestamp = NULL;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        touch_state = gpioRead(TOUCH_PIN);

        if (touch_state == 0 && last_touch_state == 1) {
            // Rising edge detected
            unsigned int current_time = gpioTick();
            if (current_time - last_touch_time > DEBOUNCE_TIME * 1000) { // Debounce
                timestamp = get_iso8601_timestamp();
                if (timestamp != NULL) {
                    if (log_timestamp(timestamp) != 0) {
                        fprintf(stderr, "Warning: Failed to log timestamp.\n");
                    }
                    free(timestamp);
                }
                last_touch_time = current_time;
            }
        }

        last_touch_state = touch_state;
        gpioDelay(10); // Poll every 10ms
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Touch sensor logging stopped.\n");
    return 0;
}

