#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    int sensor3_state;
} SensorStates;

SensorStates sensor_states = {0, 0, 0};

// Function prototypes
int read_sensor(int gpio_pin);
void log_event(int sensor_id, int state);
void signal_handler(int signal);
int initialize_gpio();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int state = gpioRead(gpio_pin);
    if (state < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, state);
        return -1; // Indicate an error
    }
    return state;
}

// Function to log an event to the log file
void log_event(int sensor_id, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s Sensor %d: %s\n", timestamp, sensor_id, state ? "magnet removed" : "magnet present");
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP);
    if (gpioGetMode(SENSOR1_PIN) != PI_INPUT || gpioGetPullUpDown(SENSOR1_PIN) != PI_PUD_UP) {
        fprintf(stderr, "Failed to set mode or pull-up for SENSOR1_PIN\n");
        gpioTerminate();
        return -1;
    }

    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP);
    if (gpioGetMode(SENSOR2_PIN) != PI_INPUT || gpioGetPullUpDown(SENSOR2_PIN) != PI_PUD_UP) {
        fprintf(stderr, "Failed to set mode or pull-up for SENSOR2_PIN\n");
        gpioTerminate();
        return -1;
    }

    gpioSetMode(SENSOR3_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR3_PIN, PI_PUD_UP);
    if (gpioGetMode(SENSOR3_PIN) != PI_INPUT || gpioGetPullUpDown(SENSOR3_PIN) != PI_PUD_UP) {
        fprintf(stderr, "Failed to set mode or pull-up for SENSOR3_PIN\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

int main() {
    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("magnet_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Read initial states
    sensor_states.sensor1_state = read_sensor(SENSOR1_PIN);
    sensor_states.sensor2_state = read_sensor(SENSOR2_PIN);
    sensor_states.sensor3_state = read_sensor(SENSOR3_PIN);

    if (sensor_states.sensor1_state == -1 || sensor_states.sensor2_state == -1 || sensor_states.sensor3_state == -1) {
        fprintf(stderr, "Error reading initial sensor states. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        int current_sensor1_state = read_sensor(SENSOR1_PIN);
        int current_sensor2_state = read_sensor(SENSOR2_PIN);
        int current_sensor3_state = read_sensor(SENSOR3_PIN);

        if (current_sensor1_state == -1 || current_sensor2_state == -1 || current_sensor3_state == -1) {
            fprintf(stderr, "Error reading sensor states. Continuing.\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (current_sensor1_state != sensor_states.sensor1_state) {
            log_event(1, current_sensor1_state);
            sensor_states.sensor1_state = current_sensor1_state;
        }

        if (current_sensor2_state != sensor_states.sensor2_state) {
            log_event(2, current_sensor2_state);
            sensor_states.sensor2_state = current_sensor2_state;
        }

        if (current_sensor3_state != sensor_states.sensor3_state) {
            log_event(3, current_sensor3_state);
            sensor_states.sensor3_state = current_sensor3_state;
        }

        gpioDelay(100); // Wait 100ms
    }

    // Clean up and exit
    fclose(log_file);
    gpioTerminate();
    return 0;
}

