#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define HR_REG 0x24
#define NUM_SAMPLES 5
#define BPM_MIN 30
#define BPM_MAX 220

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int *raw_data);
float moving_average_filter(int *data, int size);
int validate_bpm(float bpm);
int log_data(float bpm);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the sensor
int initialize_sensor() {
    int part_id, hw_rev;

    // Read PART_ID register
    part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X (expected 0x82)\n", part_id);
        return -1;
    }

    // Read HW_REV register
    hw_rev = i2cReadByteData(i2c_handle, HW_REV_REG);
    if (hw_rev < 0) {
        fprintf(stderr, "Error reading HW_REV register: %d\n", hw_rev);
        return -1;
    }
    if (hw_rev != 0x01) {
        fprintf(stderr, "Incorrect HW_REV: 0x%02X (expected 0x01)\n", hw_rev);
        return -1;
    }

    // Configure the sensor (example configuration - adjust as needed)
    int status = i2cWriteByteData(i2c_handle, 0x07, 0x03); // Example register and value
    if (status < 0) {
        fprintf(stderr, "Error writing to sensor: %d\n", status);
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(int *raw_data) {
    int retries = 3;
    int status;

    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, HR_REG);
        if (status >= 0) {
            *raw_data = status;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error: %d, retries remaining: %d\n", status, retries);
            gpioDelay(10); // Wait before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Moving average filter
float moving_average_filter(int *data, int size) {
    float sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += data[i];
    }
    return sum / size;
}

// Validate BPM value
int validate_bpm(float bpm) {
    return (bpm >= BPM_MIN && bpm <= BPM_MAX) ? 0 : -1;
}

// Log data to file
int log_data(float bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
        fflush(log_file); // Ensure data is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main() {
    int raw_data[NUM_SAMPLES];
    float bpm;
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        for (i = 0; i < NUM_SAMPLES; i++) {
            if (read_sensor_data(&raw_data[i]) != 0) {
                fprintf(stderr, "Error reading sensor data.\n");
                break; // Exit loop if read fails
            }
            gpioDelay(10); // Small delay between reads
        }

        // Apply moving average filter
        if (i == NUM_SAMPLES) {
            bpm = moving_average_filter(raw_data, NUM_SAMPLES);

            // Validate BPM value
            if (validate_bpm(bpm) == 0) {
                // Log data
                if (log_data(bpm) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            } else {
                fprintf(stderr, "Invalid BPM value: %.2f\n", bpm);
            }
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

