#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_log.txt"

static volatile int terminate = 0;
static FILE *log_file = NULL;

void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int last_state = 1; // Assume initially no flame
    time_t last_alert_time = 0;
    struct timespec sleep_time = {0, 100000000}; // 100ms

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int current_state = gpioRead(GPIO_PIN);

        if (current_state == 0 && last_state == 1) { // Falling edge detected
            time_t now = time(NULL);
            if (difftime(now, last_alert_time) >= 1.0) { // Debounce: 1 second
                printf("FLAME DETECTED\n");
                fprintf(log_file, "FLAME DETECTED\n");
                fflush(log_file);
                last_alert_time = now;
            }
        }

        last_state = current_state;
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

