#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO chip and line numbers
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE_1 5
#define GPIO_LINE_2 6
#define GPIO_LINE_3 7
#define GPIO_LINE_4 8
#define GPIO_LINE_5 9
#define GPIO_LINE_6 10
#define GPIO_LINE_7 11
#define GPIO_LINE_8 12

// Define counter GPIO lines
#define COUNTER_GPIO_0 17
#define COUNTER_GPIO_7 24

// Define debounce delay in milliseconds
#define DEBOUNCE_DELAY_MS 10

// Define stabilization delay in milliseconds
#define STABILIZATION_DELAY_MS 200

// Define counter reset value
#define COUNTER_RESET_VALUE 0

// Define counter wrap value
#define COUNTER_WRAP_VALUE 255

// Define log file name
#define LOG_FILE "touch_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[8] = {NULL}; // Array to hold line pointers
static int counter_value = COUNTER_RESET_VALUE;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_channel(int channel);
void update_counter(int channel);
void update_gpio_output(int counter_value);
void log_event(int channel, int counter_value);
void signal_handler(int sig);
int setup_gpio();
void cleanup_gpio();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Function to read sensor channel
int read_sensor_channel(int channel) {
    int value;
    int ret;

    ret = gpiod_line_get_value(lines[channel - 1]);
    if (ret < 0) {
        fprintf(stderr, "Error reading line %d: %s\n", channel, strerror(errno));
        return -1; // Indicate error
    }
    value = ret;

    return value;
}

// Function to update the counter
void update_counter(int channel) {
    counter_value++;
    if (counter_value > COUNTER_WRAP_VALUE) {
        counter_value = COUNTER_RESET_VALUE;
    }
}

// Function to update GPIO output
void update_gpio_output(int counter_value) {
    int i;
    int ret;

    for (i = 0; i < 8; i++) {
        ret = gpiod_line_set_value(lines[i], (counter_value >> i) & 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting line %d: %s\n", i + 1, strerror(errno));
        }
    }
}

// Function to log event
void log_event(int channel, int counter_value) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter_value);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Log file not opened. Event: %s, Channel: %d, Counter: %d\n", timestamp, channel, counter_value);
    }
}

// Function to setup GPIO
int setup_gpio() {
    int i;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get lines
    for (i = 0; i < 8; i++) {
        lines[i] = gpiod_chip_get_line(chip, i + 1);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", i + 1, strerror(errno));
            cleanup_gpio();
            return -1;
        }
    }

    // Request lines for input
    for (i = 0; i < 8; i++) {
        ret = gpiod_line_request_input(lines[i], "touch_counter");
        if (ret < 0) {
            fprintf(stderr, "Error requesting line %d for input: %s\n", i + 1, strerror(errno));
            cleanup_gpio();
            return -1;
        }
    }

    // Request counter GPIO lines for output
    for (i = 0; i < 8; i++) {
        ret = gpiod_chip_get_line(chip, COUNTER_GPIO_0 + i);
        if (!ret) {
