#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define DEBOUNCE_TIME_MS 50
#define POLLING_INTERVAL_MS 100

// Global variables for signal handling
static volatile int running = 1;
static int chip_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int debounce(int gpio, int sensor_number);
void log_event(int sensor_number);
void signal_handler(int signal);

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO lines
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensor 1
        if (debounce(SENSOR_1_GPIO, 1) == 0) {
            log_event(1);
        }

        // Read sensor 2
        if (debounce(SENSOR_2_GPIO, 2) == 0) {
            log_event(2);
        }

        // Wait for the next polling interval
        gpioDelay(POLLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initializes the pigpio library and configures the GPIO lines.
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the GPIO chip
    chip_fd = gpioOpen(1, 0, 0); // Chip 1, no flags, no mode
    if (chip_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %d\n", chip_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes and pull-up resistors
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Reads the state of a sensor.
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO %d: %d\n", gpio, value);
        return -1; // Indicate an error
    }
    return value;
}

// Implements a debounce filter.
int debounce(int gpio, int sensor_number) {
    int value = read_sensor(gpio);
    if (value < 0) return -1; // Propagate error

    gpioDelay(DEBOUNCE_TIME_MS * 1000); // Wait for debounce time
    int debounced_value = read_sensor(gpio);
    if (debounced_value < 0) return -1; // Propagate error

    if (value == 1 && debounced_value == 0) {
        return 0; // Tilt detected
    } else {
        return 1; // No tilt
    }
}

// Logs a tilt event to the log file.
void log_event(int sensor_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("/var/log/tilt_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number);
    fclose(log_file);
}

// Signal handler for graceful shutdown.
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    running = 0;
}

