    log_file = fopen("obstacle_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        int led_state = (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;
        control_led(led_state);

        log_data(log_file, sensor1_value, sensor2_value, led_state);

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_led(0);
    fclose(log_file);
    gpioTerminate();

