#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define MICROPHONE_PIN 4
#define LED_PIN 17

// Define sampling rate (8 kHz)
#define SAMPLING_RATE 8000
#define SAMPLE_PERIOD_US (1000000 / SAMPLING_RATE)

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

int main() {
    int rc;
    struct timespec ts;
    int led_state = 0; // 0: off, 1: on

    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input
    gpioSetMode(MICROPHONE_PIN, PI_INPUT);

    // Set GPIO17 as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    printf("Microphone sampling started. Press Ctrl+C to stop.\n");

    // Main sampling loop
    while (!terminate) {
        // Read microphone pin
        int mic_value = gpioRead(MICROPHONE_PIN);

        // Check for errors during gpioRead
        if (mic_value < 0) {
            fprintf(stderr, "Error reading microphone pin: %d\n", mic_value);
            break; // Exit loop on error
        }

        // Check for peak (HIGH reading)
        if (mic_value == 1) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
                perror("clock_gettime");
                break; // Exit loop on error
            }

            // Print timestamp to stdout
            printf("%ld.%09ld\n", ts.tv_sec, ts.tv_nsec);

            // Turn on LED for 100ms
            gpioWrite(LED_PIN, 1);
            led_state = 1;
            gpioDelay(100); // 100ms
            gpioWrite(LED_PIN, 0);
            led_state = 0;
        }

        // Delay to achieve 8kHz sampling rate
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Clean up and exit
    printf("Cleaning up and exiting...\n");

    // Turn off LED
    gpioWrite(LED_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Microphone sampling stopped.\n");

    return 0;
}

