#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Could not register signal handler.\n");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Configure the GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);

    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP);

    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input.\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Main loop to read and log sensor data
    while (program_running) {
        // Read the sensor states
        int left_state = gpioRead(LEFT_SENSOR_PIN);
        int center_state = gpioRead(CENTER_SENSOR_PIN);
        int right_state = gpioRead(RIGHT_SENSOR_PIN);

        // Log the sensor states to the console
        printf("Left: %d, Center: %d, Right: %d\n", left_state, center_state, right_state);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");

    return 0;
}

