#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1175 I2C address
#define SI1175_ADDR 0x60

// Si1175 register addresses
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23

// I2C bus
#define I2C_BUS 1

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read ALS data
        int als_data0 = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0);
        int als_data1 = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA1);

        if (als_data0 < 0 || als_data1 < 0) {
            fprintf(stderr, "Failed to read ALS data: %d %d\n", als_data0, als_data1);
            // Attempt to recover by re-initializing I2C
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C device: %d\n", i2c_handle);
                gpioTerminate();
                return 1;
            }
            gpioDelay(100); // Wait before retrying
            continue;       // Skip to the next iteration
        }

        // Combine LSB and MSB
        int als_value = (als_data1 << 8) | als_data0;

        // Log the raw sensor reading
        printf("ALS Value: %d\n", als_value);

        // Wait for 100ms
        gpioDelay(100);
    }

    // Cleanup (this part will not be reached in the infinite loop)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

