        printf("L:%d M:%d R:%d\n", left_value, middle_value, right_value);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

