#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x48 // Assuming the TTP226 is connected to this address

// Define the GPIO pins connected to the TTP226 outputs
const int gpio_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_channels = 8;

// Global variables for cleanup
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold the state of the program
typedef struct {
    int i2c_fd;
} ProgramState;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read the state of the TTP226 sensor
int read_ttp226(int i2c_fd) {
    uint8_t buffer[1];
    int result;

    // Read a single byte from the I2C device
    result = read(i2c_fd, buffer, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1; // Indicate an error
    }

    return buffer[0];
}

// Function to parse the sensor data and format the output string
void format_output(int data, char *output_string) {
    for (int i = 0; i < num_channels; i++) {
        int bit = (data >> i) & 1;
        sprintf(output_string + strlen(output_string), "CH%d=%d ", i + 1, bit);
    }
}

int main() {
    struct timespec ts;
    char output_string[256];
    int sensor_data;
    ProgramState state;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }
    state.i2c_fd = i2c_fd;

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read the sensor data
        sensor_data = read_ttp226(i2c_fd);
        if (sensor_data < 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Get the current timestamp
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
            fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
            continue;
        }

        // Format the output string
        sprintf(output_string, "[%.3f] ", (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0);
        format_output(sensor_data, output_string);

        // Print the output string
        printf("%s\n", output_string);

        // Wait for 200ms
        usleep(200000);
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

