#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM frequency (1000 Hz)
#define PWM_FREQUENCY 1000

// Define number of steps for interpolation
#define NUM_STEPS 50

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to generate a random hue value
int generate_hue()
{
    return rand() % 360;
}

// Function to convert hue (0-360) to RGB (0-255,0-255,0-255)
void hue_to_rgb(int hue, int *r, int *g, int *b)
{
    float h = (float)hue / 360.0f;
    float s = 1.0f;
    float v = 1.0f;

    float i = floor(h * 6);
    float f = h * 6 - i;
    float p = v * (1 - s);
    float q = v * (1 - f * s);
    float t = v * (1 - (1 - f) * s);

    if (i == 0) {
        *r = v; *g = t; *b = p;
    } else if (i == 1) {
        *r = q; *g = v; *b = p;
    } else if (i == 2) {
        *r = p; *g = v; *b = t;
    } else if (i == 3) {
        *r = p; *g = q; *b = v;
    } else if (i == 4) {
        *r = t; *g = p; *b = v;
    } else {
        *r = v; *g = p; *b = q;
    }
}

// Function to interpolate between two RGB values
void interpolate_rgb(int r1, int g1, int b1, int r2, int g2, int b2, int step, int total_steps, int *r, int *g, int *b)
{
    *r = r1 + (r2 - r1) * step / total_steps;
    *g = g1 + (g2 - g1) * step / total_steps;
    *b = b1 + (b2 - b1) * step / total_steps;
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue)
{
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

int main()
{
    // Initialize syslog
    openlog("rgb_led_fader", LOG_PID | LOG_CONS, LOG_USER);

    // Seed the random number generator with /dev/urandom
    FILE *urandom = fopen("/dev/urandom", "r");
    if (urandom == NULL) {
        syslog(LOG_ERR, "Failed to open /dev/urandom");
        perror("fopen");
        return 1;
    }
    unsigned int seed;
    if (fread(&seed, sizeof(seed), 1, urandom) != 1) {
        syslog(LOG_ERR, "Failed to read from /dev/urandom");
        fclose(urandom);
        return 1;
    }
    fclose(urandom);
    srand(seed);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range to 255
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "RGB LED fader started");

    // Main loop
    while (!terminate) {
        // Generate two random hues
        int hue1 = generate_hue();
        int hue2 = generate_hue();

        // Convert hues to RGB values
        int r1, g1, b1, r2, g2, b2;
        hue_to_rgb(hue1, &r1, &g1, &b1);
        hue_to_rgb(hue2, &r2, &g2, &b2);

        // Perform linear interpolation
        for (int step = 0; step <= NUM_STEPS; ++step) {
            int r, g, b;
            interpolate_rgb(r1, g1, b1, r2, g2, b2, step, NUM_STEPS, &r, &g, &b);

            // Set the LED color
            set_led_color(r, g, b);

            // Wait for a short duration
            gpioDelay(5000000 / NUM_STEPS); // 5 seconds
        }

        // Wait for a short duration before the next transition
        gpioDelay(5000000); // 5 seconds
    }

    // Turn off the LED
    set_led_color(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    syslog(LOG_INFO, "RGB LED fader terminated");

    // Close syslog
    closelog();

    return 0;
}

