#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ATIME           (0x01)
#define TCS34725_CONTROL         (0x0F)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)

// Integration Time
#define TCS34725_INTEGRATION_TIME_154MS (0xEB) // 154ms

// GPIO Pin for LED
#define LED_GPIO 17

// Red Value Threshold
#define RED_THRESHOLD 200

// I2C Bus
#define I2C_BUS "/dev/i2c-1"

// Global Variables
static int i2c_fd = -1;
static volatile int running = 1;

// Function Prototypes
int tcs34725_init();
int tcs34725_read_raw(uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c);
void tcs34725_power_down();
void tcs34725_power_on();
void tcs34725_enable_rgbc();
void tcs34725_disable_rgbc();
void tcs34725_set_integration_time(uint8_t it);
void tcs34725_calibrate(uint16_t raw_r, uint16_t raw_g, uint16_t raw_b, uint16_t raw_c, float *r, float *g, float *b, float *c);
void gpio_set_led(int state);
void signal_handler(int signal);

// Signal Handler
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// TCS34725 Initialization
int tcs34725_init() {
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: I2C device not opened.\n");
        return -1;
    }

    // Power Down
    if (tcs34725_power_down() < 0) return -1;

    // Set Integration Time
    if (tcs34725_set_integration_time(TCS34725_INTEGRATION_TIME_154MS) < 0) return -1;

    // Enable RGBC
    if (tcs34725_enable_rgbc() < 0) return -1;

    return 0;
}

// TCS34725 Power Down
void tcs34725_power_down() {
    uint8_t buf[2];
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_ENABLE;
    buf[1] = 0x00; // PON = 0, AEN = 0

    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to I2C device (Power Down)");
    }
}

// TCS34725 Power On
void tcs34725_power_on() {
    uint8_t buf[2];
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_ENABLE;
    buf[1] = 0x03; // PON = 1, AEN = 0

    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to I2C device (Power On)");
    }
}

// TCS34725 Enable RGBC
void tcs34725_enable_rgbc() {
    uint8_t buf[2];
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_ENABLE;
    buf[1] = 0x03; // PON = 1, AEN = 1

    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to I2C device (Enable RGBC)");
    }
}

// TCS34725 Disable RGBC
void tcs34725_disable_rgbc() {
    uint8_t buf[2];
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_ENABLE;
    buf[1] = 0x00; // PON = 0, AEN = 0

    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to I2C device (Disable RGBC)");
    }
}

// TCS34725 Set Integration Time
void tcs34725_set_integration_time(uint8_t it) {
    uint8_t buf[2];
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_ATIME;
    buf[1] = it;

    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to I2C device (Set Integration Time)");
    }
}

// TCS34725 Read Raw Data
int tcs34725_read_raw(uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    uint8_t buf[1];
    uint8_t data[8];

    // Read Clear Data
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_CDATA;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Error writing to I2C device (Read Clear Data)");
        return -1;
    }
    if (read(i2c_fd, data, 2) != 2) {
        perror("Error reading from I2C device (Read Clear Data)");
        return -1;
    }
    *c = (data[1] << 8) | data[0];

    // Read Red Data
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_RDATA;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Error writing to I2C device (Read Red Data)");
        return -1;
    }
    if (read(i2c_fd, data, 2) != 2) {
        perror("Error reading from I2C device (Read Red Data)");
        return -1;
    }
    *r = (data[1] << 8) | data[0];

    // Read Green Data
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_GDATA;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Error writing to I2C device (Read Green Data)");
        return -1;
    }
    if (read(i2c_fd, data, 2) != 2) {
        perror("Error reading from I2C device (Read Green Data)");
        return -1;
    }
    *g = (data[1] << 8) | data[0];

    // Read Blue Data
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_BDATA;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Error writing to I2C device (Read Blue Data)");
        return -1;
    }
    if (read(i2c_fd, data, 2) != 2) {
        perror("Error reading from I2C device (Read Blue Data)");
        return -1;
    }
    *b = (data[1] << 8) | data[0];

    return 0;
}

// TCS34725 Calibrate Data
void tcs34725_calibrate(uint16_t raw_r, uint16_t raw_g, uint16_t raw_b, uint16_t raw_c, float *r, float *g, float *b, float *c) {
    // Simple calibration (adjust as needed)
    *r = (float)raw_r;
    *g = (float)raw_g;
    *b = (float)raw_b;
    *c = (float)raw_c;
}

// GPIO Set LED
void gpio_set_led(int state) {
    gpioWrite(LED_GPIO, state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
