        if (tcs34725_read_raw(&raw_r, &raw_g, &raw_b, &raw_c) == 0) {
            // Calibrate data
            tcs34725_calibrate(raw_r, raw_g, raw_b, raw_c, &r, &g, &b, &c);

            // Print calibrated values
            printf("R: %.2f, G: %.2f, B: %.2f, C: %.2f\n", r, g, b, c);

            // Control LED based on red value
            if (r > RED_THRESHOLD) {
                gpio_set_led(1); // Turn LED on
            } else {
                gpio_set_led(0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading sensor data, re-initializing...\n");
            tcs34725_power_down();
            tcs34725_power_on();
            tcs34725_enable_rgbc();
            tcs34725_set_integration_time(TCS34725_INTEGRATION_TIME_154MS);
            sleep(1); // Wait before retrying
        }

        // Wait 200ms
        usleep(200000);
    }

