#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_ADDR 0x23
#define I2C_BUS 1
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_PIN 18
#define NUM_LEDS 10
#define PWM_FREQUENCY 800000 // 800 kHz

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750();
float map_lux_to_brightness(float lux);
void set_led_brightness(int brightness);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read lux value from BH1750 sensor
int read_bh1750() {
    int lux = -1;
    int retries = 3;

    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE) != 0) {
            fprintf(stderr, "Error writing to I2C device.\n");
            retries--;
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        gpioDelay(180); // Wait for measurement (at least 180ms)

        int raw_value = i2cReadWordData(i2c_handle, 0x00);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading from I2C device.\n");
            retries--;
            gpioDelay(1000); // Wait 1ms before retrying
            continue;
        }

        lux = (raw_value >> 8) | (raw_value << 8); // Byte swap
        lux = lux / 1.2; // Apply conversion factor
        break; // Exit retry loop on success
    }

    if (lux == -1) {
        fprintf(stderr, "Failed to read lux value after multiple retries.\n");
    }

    return lux;
}

// Function to map lux value to brightness level (0-255)
float map_lux_to_brightness(float lux) {
    // Define lux ranges and corresponding brightness levels
    float lux_ranges[][2] = {{0, 50}, {50, 100}, {100, 200}, {200, 500}, {500, 1000}, {1000, 2000}, {2000, 5000}, {5000, 10000}, {10000, 20000}, {20000, 100000}};
    float brightness_levels[] = {0, 10, 20, 30, 40, 50, 60, 70, 80, 255};

    // Clamp lux value to the defined range
    if (lux < 0) lux = 0;
    if (lux > 100000) lux = 100000;

    // Find the appropriate lux range
    for (int i = 0; i < sizeof(lux_ranges) / sizeof(lux_ranges[0]); i++) {
        if (lux >= lux_ranges[i][0] && lux <= lux_ranges[i][1]) {
            // Linear interpolation
            float range_diff = lux_ranges[i][1] - lux_ranges[i][0];
            float brightness_diff = brightness_levels[i+1] - brightness_levels[i];
            float brightness = brightness_levels[i] + (lux - lux_ranges[i][0]) * brightness_diff / range_diff;
            return brightness;
        }
    }

    // Default brightness if no range is found
    return 0;
}

// Function to set the brightness of the WS2812B LED strip
void set_led_brightness(int brightness) {
    // Calculate the number of high and low pulses needed for each bit
    int num_pulses = NUM_LEDS * 24; // Each LED has 24 bits (8 bits per color)
    int high_pulses = 0;
    int low_pulses = 0;

    for (int i = 0; i < num_pulses; i++) {
        // Determine if the bit is a 0 or 1 based on the brightness
        int bit_value = (brightness > (i * 255 / num_pulses)) ? 1 : 0;

        // Determine the pulse width based on the bit value
        int pulse_width = (bit_value == 1) ? 0.4 : 0.85; // Empirical values

        // Calculate the pulse duration in microseconds
        int pulse_duration = (int)(pulse_width * 1000); // Convert ms to us

        // Set the GPIO pin high or low for the calculated duration
        gpioWrite(GPIO_PIN, bit_value);
        gpioDelay(pulse_duration);

        if (bit_value == 1) {
            high_pulses++;
        } else {
            low_pulses++;
        }
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency (optional, but recommended for WS2812B)
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Set up signal handlers for graceful termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Illumination control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read lux value from BH1750 sensor
        int lux = read_bh1750();

        if (lux != -1) {
            // Map lux value to brightness level
            float brightness = map_lux_to_brightness((float)lux);

            // Set the brightness of the WS2812B LED strip
            set_led_brightness((int)brightness);

            printf("Lux: %d, Brightness: %d\n", lux, (int)brightness);
        } else {
            fprintf(stderr, "Failed to read lux value. Setting brightness to 0.\n");
            set_led_brightness(0);
        }

        // Delay for 100ms
        gpioDelay(100);
    }

    // Clean up and exit
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

