#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

// Define constants
#define BH1750_ADDR1 0x23
#define BH1750_ADDR2 0x5C
#define BH1750_ADDR3 0x46
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define APA102_GPIO 10
#define APA102_SPI_CHANNEL 0
#define APA102_NUM_LEDS 30
#define FADE_DURATION_MS 500
#define READ_DELAY_MS 100

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
int i2c_handle3 = -1;
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold RGB color data
typedef struct {
    uint8_t r;
    uint8_t g;
    uint8_t b;
} RGB;

// Function prototypes
int init_i2c();
int init_spi();
int read_bh1750(int handle);
float average_lux(float lux1, float lux2, float lux3);
RGB calculate_brightness(float avg_lux);
void set_apa102_brightness(RGB color);
void fade_brightness(RGB start_color, RGB end_color, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle1 = i2cOpen(1, BH1750_ADDR1, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle1);
        i2c_handle1 = -1; // Mark as invalid
    }

    i2c_handle2 = i2cOpen(1, BH1750_ADDR2, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        i2c_handle2 = -1; // Mark as invalid
    }

    i2c_handle3 = i2cOpen(1, BH1750_ADDR3, 0);
    if (i2c_handle3 < 0) {
        fprintf(stderr, "Error opening I2C device 3: %d\n", i2c_handle3);
        i2c_handle3 = -1; // Mark as invalid
    }

    return 0;
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(APA102_SPI_CHANNEL, 32000000, 0); // 32MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read light level from BH1750 sensor
int read_bh1750(int handle) {
    if (handle < 0) return -1; // Invalid handle

    if (i2cWriteByteData(handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", handle);
        return -1;
    }
    gpioDelay(180); // Wait for conversion

    int raw_value = i2cReadWordData(handle, 0x00);
    if (raw_value < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", handle);
        return -1;
    }

    return raw_value;
}

// Calculate average lux value
float average_lux(float lux1, float lux2, float lux3) {
    float sum = 0;
    int count = 0;

    if (lux1 >= 0) {
        sum += lux1;
        count++;
    }
    if (lux2 >= 0) {
        sum += lux2;
        count++;
    }
    if (lux3 >= 0) {
        sum += lux3;
        count++;
    }

    if (count == 0) return -1; // No valid readings

    return sum / count;
}

// Calculate RGB color based on average lux value
RGB calculate_brightness(float avg_lux) {
    RGB color;

    if (avg_lux < 0) {
        color.r = 0;
        color.g = 0;
        color.b = 0;
        return color;
    }

    // Non-linear mapping (logarithmic)
    float brightness = log10(avg_lux + 1) / log10(1000); // Normalize to 0-1 range (0-1000 lux)
    if (brightness > 1) brightness = 1; // Clamp to max brightness
    if (brightness < 0) brightness = 0; // Clamp to min brightness

    // Map brightness to RGB values (example: blue -> green -> red)
    color.r = (uint8_t)(255 * (1 - brightness));
    color.g = (uint8_t)(255 * brightness);
    color.b = (uint8_t)(255 * (1 - brightness));

    return color;
}

// Set APA102 LED strip brightness using hardware SPI
void set_apa102_brightness(RGB color) {
    // Start frame (4 bytes of 0x00)
    char start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    spiWrite(spi_handle, start_frame, 4);

    // LED data (4 bytes per LED: 0xE0 | brightness, green, red, blue)
    char led_data[4] = {0xE0 | 31, color.b, color.g, color.r}; // White color
    for (int i = 0; i < APA102_NUM_LEDS; i++) {
        spiWrite(spi_handle, led_data, 4);
    }

    // End frame (4 bytes of 0xFF)
    char end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    spiWrite(spi_handle, end_frame, 4);
}

// Fade brightness over a given duration
void fade_brightness(RGB start_color, RGB end_color, int duration_ms) {
    int num_steps = duration_ms / 10; // 10ms per step
    float r_diff = (float)(end_color.r - start_color.r) / num_steps;
    float g_diff = (float)(end_color.g - start_color.g) / num_steps;
    float b_diff = (float)(end_color.b - start_color.b) / num_steps;

    RGB current_color = start_color;

    for (int i = 0; i < num_steps; i++) {
        current_color.r += r_diff;
        current_color.g += g_diff;
        current_color.b += b_diff;
        set_apa102_brightness(current_color);
        gpioDelay(10); // 10ms delay
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C and SPI
    if (init_i2c() != 0 || init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    RGB current_color = {0, 0, 0};
    RGB target_color;

    while (!terminate) {
        // Read light levels from sensors
        float lux1 = -1, lux2 = -1, lux3 = -1;
        if (i2c_handle1 >= 0) lux1 = read_bh1750(i2c_handle1);
        if (i2c_handle2 >= 0) lux2 = read_bh1750(i2c_handle2);
        if (i2c_handle3 >= 0) lux3 = read_bh1750(i2c_handle3);

        // Calculate average lux value
        float avg_lux = average_lux(lux1, lux2, lux3);

        // Calculate target RGB color
        target_color = calculate_brightness(avg_lux);

        // Fade to target color
        fade_brightness(current_color, target_color, FADE_DURATION_MS);

        // Update current color
        current_color = target_color;

        // Delay before next reading
        gpioDelay(READ_DELAY_MS);
    }

    // Turn off LED strip
    set_apa102_brightness((RGB){0, 0, 0});

    // Close I2C and SPI handles
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    if (i2c_handle3 >= 0) i2cClose(i2c_handle3);
    if (spi_handle >= 0) spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

