#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_ADDR 0x48
#define ALS_DATA_REG 0x04
#define GPIO_PIN 18
#define PWM_FREQUENCY 800000 // 800 kHz
#define PWM_RANGE 1000
#define THRESHOLD 100
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_veml7700(int i2c_handle, uint16_t *als_data);
float calculate_lux(uint16_t als_data);
int gamma_correct(float lux);
void set_led_brightness(int brightness);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to read ALS data from VEML7700
int read_veml7700(int i2c_handle, uint16_t *als_data) {
    int result, retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadWordData(i2c_handle, ALS_DATA_REG);
        if (result >= 0) {
            *als_data = (uint16_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "Failed to read ALS data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to calculate lux value
float calculate_lux(uint16_t als_data) {
    // Conversion formula from VEML7700 datasheet
    // Adjust gain and integration time as needed
    float lux = (float)als_data * 0.0576; // Example conversion, adjust based on gain and integration time
    return lux;
}

// Function to apply gamma correction
int gamma_correct(float lux) {
    // Gamma correction (2.2 is a common value)
    float gamma_corrected = powf(lux / 1000.0, 2.2) * 1000.0; // Scale to 0-1000
    return (int)gamma_corrected;
}

// Function to set LED brightness using bit-banging
void set_led_brightness(int brightness) {
    int i;
    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Reset the data line
    gpioWrite(GPIO_PIN, 0);
    gpioDelay(50); // Reset pulse

    // Start frame (0b11100000)
    for (i = 0; i < 8; i++) {
        gpioWrite(GPIO_PIN, 0);
        gpioDelay(35); // T0H
        gpioWrite(GPIO_PIN, 1);
        gpioDelay(35); // T0L
    }

    // Data bits (green, blue, red)
    for (i = 0; i < 24; i++) {
        if (brightness & (1 << i)) {
            gpioWrite(GPIO_PIN, 1);
            gpioDelay(35); // T1H
            gpioWrite(GPIO_PIN, 0);
            gpioDelay(35); // T1L
        } else {
            gpioWrite(GPIO_PIN, 0);
            gpioDelay(35); // T0H
            gpioWrite(GPIO_PIN, 0);
            gpioDelay(35); // T0L
        }
    }

    // End frame (0b00011111)
    for (i = 0; i < 8; i++) {
        gpioWrite(GPIO_PIN, 0);
        gpioDelay(35); // T0H
        gpioWrite(GPIO_PIN, 1);
        gpioDelay(35); // T0L
    }

    // Set GPIO pin back to input mode
    gpioSetMode(GPIO_PIN, PI_INPUT);
}

int main() {
    uint16_t als_data;
    float lux;
    int brightness;
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ALS data
        result = read_veml7700(i2c_handle, &als_data);
        if (result != 0) {
            fprintf(stderr, "Failed to read ALS data. Using threshold-based approach.\n");
            // Use threshold-based approach if I2C fails
            if (als_data > THRESHOLD) {
                brightness = 1000;
            } else {
                brightness = 0;
            }
        } else {
            // Calculate lux value
            lux = calculate_lux(als_data);

            // Apply gamma correction
            brightness = gamma_correct(lux);
        }

        // Set LED brightness
        set_led_brightness(brightness);

        // Print lux and brightness values
        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        // Delay
        gpioDelay(200 * 1000); // 200 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

