#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Define error codes
#define NO_ERROR 0
#define FLAME_DETECTED 1
#define FLAME_CLEARED 2
#define ERROR_CODE 3

// Global variables
FILE *log_file;
int running = 1;

// Function prototypes
int read_flame_sensor();
void control_buzzer(int state);
void control_led(int state);
void log_event(int event_type);
void blink_led(int duration_ms);
void blink_buzzer(int duration_ms);
void self_test();
void signal_handler(int signal);

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor: %d\n", value);
        return -1; // Indicate error
    }
    return (value == 0) ? 1 : 0; // Return 1 if flame detected (LOW), 0 otherwise
}

// Function to control the buzzer
void control_buzzer(int state) {
    gpioWrite(BUZZER_PIN, state);
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to log events to a file
void log_event(int event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    switch (event_type) {
        case FLAME_DETECTED:
            fprintf(log_file, "%s - Flame detected\n", timestamp);
            break;
        case FLAME_CLEARED:
            fprintf(log_file, "%s - Flame cleared\n", timestamp);
            break;
        case ERROR_CODE:
            fprintf(log_file, "%s - Error occurred\n", timestamp);
            break;
        default:
            fprintf(log_file, "%s - Unknown event\n", timestamp);
            break;
    }
    fflush(log_file); // Ensure the log is written immediately
}

// Function to blink the LED
void blink_led(int duration_ms) {
    control_led(1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    control_led(0); // Turn LED off
    gpioDelay(duration_ms * 1000); // Delay for specified duration
}

// Function to blink the buzzer
void blink_buzzer(int duration_ms) {
    control_buzzer(1); // Turn buzzer on
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    control_buzzer(0); // Turn buzzer off
    gpioDelay(duration_ms * 1000); // Delay for specified duration
}

// Function to perform the self-test
void self_test() {
    printf("Starting self-test...\n");
    log_file = fopen("flame_sensor.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        exit(1);
    }

    // Blink LED twice
    for (int i = 0; i < 2; i++) {
        blink_led(500);
    }

    // Read flame sensor five times
    int flame_detected_count = 0;
    for (int i = 0; i < 5; i++) {
        int sensor_value = read_flame_sensor();
        if (sensor_value == 1) {
            flame_detected_count++;
        } else if (sensor_value == -1) {
            log_event(ERROR_CODE);
            fprintf(stderr, "Error during self-test, exiting.\n");
            fclose(log_file);
            exit(1);
        }
        gpioDelay(100 * 1000); // Delay 100ms
    }

    // Check if flame is consistently detected
    if (flame_detected_count == 5) {
        printf("Self-test failed: Flame detected on all samples.\n");
        log_event(ERROR_CODE);

        // Blink LED rapidly
        for (int i = 0; i < 5; i++) {
            blink_led(100);
        }

        // Buzzer pattern
        for (int i = 0; i < 3; i++) {
            blink_buzzer(200);
            gpioDelay(200 * 1000);
            blink_buzzer(600);
            gpioDelay(200 * 1000);
        }

        fclose(log_file);
        exit(1);
    } else {
        printf("Self-test passed.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    control_buzzer(0);
    control_led(0);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set pull-up/down resistor for flame sensor (optional, depends on sensor)
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Perform self-test
    self_test();

    printf("Starting main loop...\n");

    // Main loop
    while (running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value == 1) {
            log_event(FLAME_DETECTED);
            control_buzzer(1);
            control_led(1);
        } else if (sensor_value == 0) {
            log_event(FLAME_CLEARED);
            control_buzzer(0);
            control_led(0);
        } else if (sensor_value == -1) {
            log_event(ERROR_CODE);
            fprintf(stderr, "Error reading sensor, exiting.\n");
            running = 0; // Exit loop on error
        }

        gpioDelay(50 * 1000); // Delay 50ms
    }

    // Cleanup (should not reach here if signal handler works)
    control_buzzer(0);
    control_led(0);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

