#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define LED_GPIO 17
#define NUM_READINGS 60
#define MIN_FREQUENCY 0.5
#define MAX_FREQUENCY 5.0
#define MIN_LUX 0.0
#define MAX_LUX 1000.0

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t running = 1;

// Circular buffer
float lux_buffer[NUM_READINGS];
int buffer_index = 0;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_bh1750(int fd);
float calculate_average_lux(const float *buffer, int size);
void set_led_frequency(float frequency);
void cleanup_gpio(int gpio);
void signal_handler(int sig);

// I2C initialization function
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// BH1750 read function
int read_bh1750(int fd) {
    uint8_t buf[2];
    int retries = 3;

    while (retries > 0) {
        // Send measurement command
        if (write(fd, &CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
            perror("Error writing to I2C device");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        usleep(200000); // Wait for measurement (at least 180ms)

        // Read 2 bytes of data
        if (read(fd, buf, 2) != 2) {
            perror("Error reading from I2C device");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        // Combine bytes to form lux value
        uint16_t raw_value = (buf[0] << 8) | buf[1];
        return raw_value;
    }

    fprintf(stderr, "Failed to read BH1750 after multiple retries.\n");
    return -1; // Indicate failure
}

// Calculate average lux function
float calculate_average_lux(const float *buffer, int size) {
    float sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += buffer[i];
    }
    return sum / size;
}

// Set LED frequency function
void set_led_frequency(float frequency) {
    // Calculate period in microseconds
    float period_us = 1000000.0 / frequency;

    // Calculate on-time in microseconds (50% duty cycle)
    float on_time_us = period_us / 2.0;

    // Calculate the number of microseconds to sleep for the rest of the period
    float off_time_us = period_us - on_time_us;

    // Sleep for the on-time
    struct timespec on_spec = {0, (long)(on_time_us * 1000)}; // Convert microseconds to nanoseconds
    nanosleep(&on_spec, NULL);

    // Sleep for the off-time
    struct timespec off_spec = {0, (long)(off_time_us * 1000)}; // Convert microseconds to nanoseconds
    nanosleep(&off_spec, NULL);
}

// Cleanup GPIO function
void cleanup_gpio(int gpio) {
    int unexport_fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (unexport_fd < 0) {
        perror("Error opening /sys/class/gpio/unexport");
        return;
    }

    char gpio_str[3];
    snprintf(gpio_str, sizeof(gpio_str), "%d", gpio);
    if (write(unexport_fd, gpio_str, strlen(gpio_str)) < 0) {
        perror("Error writing to /sys/class/gpio/unexport");
    }

    close(unexport_fd);
}

// Signal handler function
void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize GPIO for LED
    int gpio_fd = open("/sys/class/gpio/export", O_WRONLY);
    if (gpio_fd < 0) {
        perror("Error opening /sys/class/gpio/export");
        close(i2c_fd);
        return 1;
    }

    char gpio_str[3];
    snprintf(gpio_str, sizeof(gpio_str), "%d", LED_GPIO);
    if (write(gpio_fd, gpio_str, strlen(gpio_str)) < 0) {
        perror("Error writing to /sys/class/gpio/export");
        close(i2c_fd);
        close(gpio_fd);
        return 1;
    }
    close(gpio_fd);

    // Set GPIO direction to output
    char direction_path[50];
    snprintf(direction_path, sizeof(direction_path), "/sys/class/gpio/gpio%d/direction", LED_GPIO);
    int direction_fd = open(direction_path, O_WRONLY);
    if (direction_fd < 0) {
        perror("Error opening GPIO direction file");
        cleanup_gpio(LED_GPIO);
        close(i2c_fd);
        return 1;
    }
    if (write(direction_fd, "out", 3) < 0) {
        perror("Error writing to GPIO direction file");
        close(direction_fd);
        cleanup_gpio(LED_GPIO);
        close(i2c_fd);
        return 1;
    }
    close(direction_fd);

    // Main loop
    while (running) {
        // Read lux value
        int lux_raw = read_bh1750(i2c_fd);
        if (lux_raw < 0) {
            fprintf(stderr, "Failed to read lux value. Skipping.\n");
            sleep(1);
            continue;
        }

        // Convert raw value to lux
        float lux = (float)lux_raw / 1.2; // Empirical conversion factor

        // Store in circular buffer
        lux_buffer[buffer_index] = lux;
        buffer_index = (buffer_index + 1) % NUM_READINGS;

        // Calculate average lux
        float avg_lux = calculate_average_lux(lux_buffer, NUM_READINGS);

        // Calculate LED frequency
        float frequency = MIN_FREQUENCY + (avg_lux / MAX_LUX) * (MAX_FREQUENCY - MIN_FREQUENCY);

        // Set LED frequency
        set_led_frequency(frequency);

        // Print lux value
        printf("Lux: %.2f, Average Lux: %.2f, Frequency: %.2f Hz\n", lux, avg_lux, frequency);

        sleep(1);
    }

    // Cleanup
    close(i2c_fd);
    cleanup_gpio(LED_GPIO);

    return 0;
}

