#include <stdio.h>
#include <stdlib.h>
#include <wiringPi.h>
#include <errno.h>

// Define GPIO pins (BCM numbering)
#define DATA_PIN   17
#define CLOCK_PIN  18
#define LATCH_PIN  27

// Define segment patterns for digits (a, b, c, d, e, f, g, dp)
const unsigned char digit_patterns[] = {
    0b00111111, // 0
    0b00000110, // 1
    0b01011011, // 2
    0b01001111, // 3
    0b01100110, // 4
    0b01101101, // 5
    0b01111101, // 6
    0b00000111, // 7
    0b01111111, // 8
    0b01101111  // 9
};

// Function to shift out data to the 74HC595
void shiftOut(unsigned char data) {
    for (int i = 0; i < 8; i++) {
        // Set data pin based on the bit
        digitalWrite(DATA_PIN, (data >> (7 - i)) & 0x01);

        // Clock the data in
        digitalWrite(CLOCK_PIN, HIGH);
        delayMicroseconds(1); // Small delay for clock stability
        digitalWrite(CLOCK_PIN, LOW);
        delayMicroseconds(1); // Small delay for clock stability
    }
}

// Function to latch the data to the output
void latchData() {
    digitalWrite(LATCH_PIN, HIGH);
    delayMicroseconds(1); // Small delay for latch stability
    digitalWrite(LATCH_PIN, LOW);
    delayMicroseconds(1); // Small delay for latch stability
}

int main() {
    // Initialize wiringPi using BCM GPIO numbering
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1; // Exit with an error code
    }

    // Set GPIO pins as output
    pinMode(DATA_PIN, OUTPUT);
    pinMode(CLOCK_PIN, OUTPUT);
    pinMode(LATCH_PIN, OUTPUT);

    // Main loop to display the digit '5' repeatedly
    while (1) {
        // Shift out the digit '5' pattern
        shiftOut(digit_patterns[5]);

        // Latch the data to the output
        latchData();

        // Blink the display for 500ms on, 500ms off
        delay(500);
        digitalWrite(LATCH_PIN, LOW); // Ensure latch is low before next cycle
        delay(500);
    }

    return 0; // Exit successfully
}

