#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_LED 17
#define GPIO_BUTTON 18
#define GPIOCHIP 0

static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct gpiod_line *button_line;
static int running = 1;

void cleanup(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);
    running = 0;
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main()
{
    struct gpiod_line_event event;
    int ret;

    signal(SIGINT, cleanup);

    chip = gpiod_chip_open_by_number(GPIOCHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        gpiod_chip_close(chip);
        return 1;
    }

    button_line = gpiod_chip_get_line(chip, GPIO_BUTTON);
    if (!button_line) {
        perror("gpiod_chip_get_line (BUTTON)");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (LED)");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_falling_edge_events(button_line, "blink_button");
    if (ret < 0) {
        perror("gpiod_line_request_falling_edge_events (BUTTON)");
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Waiting for falling edge on GPIO%d...\n", GPIO_BUTTON);

    while (running) {
        ret = gpiod_line_event_wait(button_line, NULL, 1); // Timeout of 1 second
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            break;
        } else if (ret == 0) {
            printf("Timeout waiting for event.\n");
            break;
        }

        ret = gpiod_line_event_read(button_line, &event);
        if (ret < 0) {
            perror("gpiod_line_event_read");
            break;
        }

        printf("Button pressed!\n");
        running = 0; // Stop the blinking loop
        break;
    }

    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return 0;
}

