#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 24
#define BUTTON_PIN 22

// Define blinking parameters
#define BLINK_ON_TIME 500  // milliseconds
#define BLINK_OFF_TIME 500 // milliseconds

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    int led_handle, button_handle;
    int led_level = 0; // 0 for off, 1 for on
    int button_state = 0; // 0 for not pressed, 1 for pressed
    int last_button_state = 0;

    // Register signal handlers for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO chip
    led_handle = gpioOpen(LED_PIN, PI_OUTPUT, 0);
    if (led_handle < 0) {
        fprintf(stderr, "Failed to open LED GPIO: %d\n", led_handle);
        gpioTerminate();
        return 1;
    }

    button_handle = gpioOpen(BUTTON_PIN, PI_INPUT, 0);
    if (button_handle < 0) {
        fprintf(stderr, "Failed to open button GPIO: %d\n", button_handle);
        gpioTerminate();
        return 1;
    }

    // Set initial LED state to off
    gpioWrite(led_handle, 0);

    // Main loop
    while (program_running) {
        // Read button state
        button_state = gpioRead(button_handle);

        // Check if button is pressed (rising edge)
        if (button_state == 1 && last_button_state == 0) {
            // Toggle LED state
            led_level = !led_level;
            gpioWrite(led_handle, led_level);

            // Blink LED if button is held down
            if (led_level == 1) {
                while (button_state == 1 && program_running) {
                    gpioWrite(led_handle, 1);
                    gpioDelay(BLINK_ON_TIME * 1000); // Convert ms to microseconds
                    gpioWrite(led_handle, 0);
                    gpioDelay(BLINK_OFF_TIME * 1000); // Convert ms to microseconds
                    button_state = gpioRead(button_handle); // Re-read button state
                }
                gpioWrite(led_handle, 0); // Turn off LED if button is released
            }
        }

        last_button_state = button_state;
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    // Close GPIO lines
    gpioClose(led_handle);
    gpioClose(button_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

