#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <bcm2835.h>

// Define GPIO pins for RGB LED
#define RED_PIN   RPI_GPIO_P1_18 // GPIO24
#define GREEN_PIN RPI_GPIO_P1_16 // GPIO23
#define BLUE_PIN  RPI_GPIO_P1_12 // GPIO18

// PWM frequency (Hz)
#define PWM_FREQUENCY 100

// PWM period (nanoseconds)
#define PWM_PERIOD (1000000000 / PWM_FREQUENCY)

// Function prototypes
void set_rgb(int red, int green, int blue);
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting gracefully.\n");
        terminate = 1;
    }
}

// Function to set the RGB LED color using software PWM
void set_rgb(int red, int green, int blue) {
    // Calculate on-time for each color based on intensity
    long red_on_time   = (red   * PWM_PERIOD) / 100;
    long green_on_time = (green * PWM_PERIOD) / 100;
    long blue_on_time  = (blue  * PWM_PERIOD) / 100;

    // Calculate off-time for each color
    long red_off_time   = PWM_PERIOD - red_on_time;
    long green_off_time = PWM_PERIOD - green_on_time;
    long blue_off_time  = PWM_PERIOD - blue_on_time;

    // Set GPIO pins HIGH or LOW for the calculated on-time and off-time
    bcm2835_gpio_write(RED_PIN,   HIGH);
    bcm2835_gpio_write(GREEN_PIN, HIGH);
    bcm2835_gpio_write(BLUE_PIN,  HIGH);

    bcm2835_delayMicroseconds(red_on_time);
    bcm2835_gpio_write(RED_PIN,   LOW);
    bcm2835_delayMicroseconds(red_off_time);

    bcm2835_delayMicroseconds(green_on_time);
    bcm2835_gpio_write(GREEN_PIN, LOW);
    bcm2835_delayMicroseconds(green_off_time);

    bcm2835_delayMicroseconds(blue_on_time);
    bcm2835_gpio_write(BLUE_PIN,  LOW);
    bcm2835_delayMicroseconds(blue_off_time);
}

int main(int argc, char **argv) {
    // Seed the random number generator
    srand(time(NULL));

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the BCM2835 library
    if (!bcm2835_init()) {
        fprintf(stderr, "bcm2835_init failed. Are you running as root?\n");
        return 1;
    }

    // Configure the GPIO pins as output
    bcm2835_gpio_fsel(RED_PIN,   OUTPUT);
    bcm2835_gpio_fsel(GREEN_PIN, OUTPUT);
    bcm2835_gpio_fsel(BLUE_PIN,  OUTPUT);

    // Main loop
    while (!terminate) {
        // Generate random intensity values for red, green, and blue
        int red   = rand() % 101;
        int green = rand() % 101;
        int blue  = rand() % 101;

        // Set the RGB LED color
        set_rgb(red, green, blue);

        // Wait for 100 milliseconds
        bcm2835_delay(100);
    }

    // Clean up and exit
    bcm2835_close();
    return 0;
}

