#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LSM303_ACCEL_ADDR 0x19
#define CTRL_REG1_A 0x20
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D
#define GPIO_PIN 17
#define DEFAULT_THRESHOLD 2.0f
#define SAMPLE_RATE 10 // Hz
#define SAMPLE_PERIOD (1000000 / SAMPLE_RATE) // microseconds

// Global variables
int i2c_handle;
float threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int read_accel_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void trigger_interrupt();
void log_data(int16_t x, int16_t y, int16_t z, float magnitude);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Configure accelerometer: 10 Hz, normal mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accel_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate magnitude
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 16384.0f; // Assuming +/- 2G sensitivity
    float y_g = (float)y / 16384.0f;
    float z_g = (float)z / 16384.0f;
    return sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Trigger interrupt
void trigger_interrupt() {
    gpioWrite(GPIO_PIN, 1);
    gpioDelay(50); // 50ms
    gpioWrite(GPIO_PIN, 0);
}

// Log data to file
void log_data(int16_t x, int16_t y, int16_t z, float magnitude) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %d, %d, %d, %.4f\n", s, x, y, z, magnitude);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float magnitude;

    printf("Monitoring accelerometer... (Threshold: %.2f G)\n", threshold);

    while (!terminate) {
        if (read_accel_data(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > threshold) {
                printf("Impact detected! Magnitude: %.4f G\n", magnitude);
                trigger_interrupt();
                log_data(x, y, z, magnitude);
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

