        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float magnitude;

    printf("Monitoring accelerometer... (Threshold: %.2f G)\n", threshold);

    while (!terminate) {
        if (read_accel_data(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > threshold) {
                printf("Impact detected! Magnitude: %.4f G\n", magnitude);
                trigger_interrupt();
                log_data(x, y, z, magnitude);
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

