#define ALS_MSB_REG 0x01
#define RED_LSB_REG 0x02
#define RED_MSB_REG 0x03
#define GREEN_LSB_REG 0x04
#define GREEN_MSB_REG 0x05
#define BLUE_LSB_REG 0x06
#define BLUE_MSB_REG 0x07
#define LED_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000      // Range for PWM duty cycle (0-1000)
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
void process_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t *data);
void control_led(uint16_t als_value);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[8];
    int result;

    // Read ALS data
    result = i2cReadI2CBlockData(i2c_handle, ALS_LSB_REG, buf, 8);
    if (result != 8) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    data->als = (uint16_t)buf[1] << 8 | (uint16_t)buf[0];
    data->red = (uint16_t)buf[3] << 8 | (uint16_t)buf[2];
    data->green = (uint16_t)buf[5] << 8 | (uint16_t)buf[4];
    data->blue = (uint16_t)buf[7] << 8 | (uint16_t)buf[6];

    return 0;
}

// Function to process sensor data (currently does nothing)
void process_sensor_data(sensor_data_t *data) {
    // Add any data processing logic here
}

// Function to log data to CSV file
