#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define FXOS8700CQ_ADDR 0x1F
#define FXOS8700CQ_WHO_AM_I 0x0D
#define FXOS8700CQ_CTRL_REG1 0x2A
#define FXOS8700CQ_XYZ_DATA_CFG 0x0E
#define FXOS8700CQ_STATUS 0x00
#define FXOS8700CQ_OUT_X_MSB 0x01
#define FXOS8700CQ_OUT_Y_MSB 0x03
#define FXOS8700CQ_OUT_Z_MSB 0x05
#define FXOS8700CQ_M_OUT_X_MSB 0x33
#define FXOS8700CQ_M_OUT_Y_MSB 0x35
#define FXOS8700CQ_M_OUT_Z_MSB 0x37
#define IMPACT_THRESHOLD 1.5 // g
#define DATA_RATE 200 // Hz
#define SAMPLE_INTERVAL (1000000 / DATA_RATE) // microseconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_fxos8700cq();
int read_sensor_data(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
int log_impact(float x, float y, float z, float magnitude);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
}

// Initialize the FXOS8700CQ sensor
int init_fxos8700cq() {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, FXOS8700CQ_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xC7) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    // Put the sensor in standby mode
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set the accelerometer range to ±2g
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG\n");
        return -1;
    }

    // Set the data rate to 200 Hz and activate the sensor
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x15) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data from the sensor
int read_sensor_data(float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    // Read the X, Y, and Z axis data
    if (i2cReadI2CBlockData(i2c_handle, FXOS8700CQ_OUT_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    // Combine MSB and LSB, and convert to g
    raw_x = (int16_t)((buffer[0] << 8) | buffer[1]) >> 2;
    raw_y = (int16_t)((buffer[2] << 8) | buffer[3]) >> 2;
    raw_z = (int16_t)((buffer[4] << 8) | buffer[5]) >> 2;

    *x = (float)raw_x / 4096.0f; // 2^12 = 4096
    *y = (float)raw_y / 4096.0f;
    *z = (float)raw_z / 4096.0f;

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Log impact data to a file
int log_impact(float x, float y, float z, float magnitude) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open the log file in append mode
    fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt\n");
        return -1;
    }

    // Write the data to the log file
    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);

    // Close the log file
    fclose(fp);

    return 0;
}

int main() {
    float x, y, z, magnitude;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_fxos8700cq() < 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(x, y, z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                // Log the impact data
                if (log_impact(x, y, z, magnitude) != 0) {
                    fprintf(stderr, "Error logging impact data\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Delay for the specified interval
        gpioDelay(SAMPLE_INTERVAL);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

