#define WHO_AM_I_VALUE 0xD3
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define SAMPLE_RATE 20 // Hz
#define SAMPLE_PERIOD 50 // ms
#define ALERT_THRESHOLD 50.0 // dps
#define NUM_CALIBRATION_SAMPLES 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration offsets
float x_offset = 0.0;
float y_offset = 0.0;
float z_offset = 0.0;

// Function prototypes
int init_gyro();
int calibrate_gyro();
int read_gyro_data(float *x, float *y, float *z);
void log_data(float x, float y, float z);
void check_alert(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    // Verify sensor presence
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%X (expected 0x%X)\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, 100Hz data rate)
    int status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F); // 0x0F = 0b00001111
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", status);
        return -1;
    }

    // Configure CTRL_REG4 (Full scale +/- 250 dps)
    status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00); // 0x00 = 0b00000000
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4: %d\n", status);
        return -1;
    }

    return 0;
}

// Calibrate the gyroscope
int calibrate_gyro() {
    float x, y, z;
    float x_sum = 0.0, y_sum = 0.0, z_sum = 0.0;

    printf("Calibrating gyroscope...\n");
    for (int i = 0; i < NUM_CALIBRATION_SAMPLES; i++) {
        if (read_gyro_data(&x, &y, &z) < 0) {
            fprintf(stderr, "Error reading gyro data during calibration\n");
            return -1;
        }
        x_sum += x;
        y_sum += y;
        z_sum += z;
        gpioDelay(5000); // 5ms delay
    }

    x_offset = x_sum / NUM_CALIBRATION_SAMPLES;
    y_offset = y_sum / NUM_CALIBRATION_SAMPLES;
    z_offset = z_sum / NUM_CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", x_offset, y_offset, z_offset);
    return 0;
}

// Read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading gyro data: %d\n", status);
        return -1;
    }

    // Combine high and low bytes, and convert to signed 16-bit integer
    short x_raw = (short)((buffer[1] << 8) | buffer[0]);
    short y_raw = (short)((buffer[3] << 8) | buffer[2]);
    short z_raw = (short)((buffer[5] << 8) | buffer[4]);

    // Convert to degrees per second (dps)
    *x = (float)x_raw / 14.375; // Sensitivity at +/- 250 dps is 14.375 LSB/dps
    *y = (float)y_raw / 14.375;
    *z = (float)z_raw / 14.375;

    return 0;
}

