        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to verify the device ID
int adxl345_verify_device_id(int handle) {
    int device_id = adxl345_read_register(handle, ADXL345_REG_DEVID);
    if (device_id < 0) {
        return -1;
    }
    if (device_id != 0xE5) {
        fprintf(stderr, "Error: Incorrect device ID: 0x%02X\n", device_id);
        return -1;
    }
    printf("ADXL345 device ID verified successfully.\n");
    return 0;
}

// Function to configure the ADXL345
int adxl345_configure(int handle) {
    // Set data format register to full resolution, ±2g range
    if (adxl345_write_register(handle, 0x31, 0x08) < 0) {
        return -1;
    }

    // Set power control register to measure mode
    if (adxl345_write_register(handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        return -1;
    }

    printf("ADXL345 configured successfully.\n");
    return 0;
}

// Function to read acceleration data
int adxl345_read_acceleration(int handle, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;

    // Read raw acceleration data
    int x0 = adxl345_read_register(handle, ADXL345_REG_DATAX0);
    int x1 = adxl345_read_register(handle, ADXL345_REG_DATAX1);
    int y0 = adxl345_read_register(handle, ADXL345_REG_DATAY0);
    int y1 = adxl345_read_register(handle, ADXL345_REG_DATAY1);
    int z0 = adxl345_read_register(handle, ADXL345_REG_DATAZ0);
    int z1 = adxl345_read_register(handle, ADXL345_REG_DATAZ1);

    if (x0 < 0 || x1 < 0 || y0 < 0 || y1 < 0 || z0 < 0 || z1 < 0) {
        return -1;
    }

    // Combine high and low bytes
    raw_x = (int16_t)((x1 << 8) | x0);
    raw_y = (int16_t)((y1 << 8) | y0);
    raw_z = (int16_t)((z1 << 8) | z0);

    // Convert to g units
    *x = (float)raw_x * FULL_RESOLUTION_SENSITIVITY;
    *y = (float)raw_y * FULL_RESOLUTION_SENSITIVITY;
    *z = (float)raw_z * FULL_RESOLUTION_SENSITIVITY;

    return 0;
}

// Function to log data to a file
void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Function to control the LED based on acceleration
void control_led(int pin, float x, float y, float z) {
    if (fabs(x) > 2.0 || fabs(y) > 2.0 || fabs(z) > 2.0) {
        gpioWrite(pin, 1); // Turn LED on
    } else {
        gpioWrite(pin, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    if (adxl345_verify_device_id(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADXL345
    if (adxl345_configure(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;
    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (adxl345_read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            // Log data
            log_data(log_file, x, y, z);

            // Control LED
            control_led(LED_PIN, x, y, z);
        } else {
            fprintf(stderr, "Error reading acceleration data.\n");
        }

        // Delay for 100ms (10Hz sampling rate)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    fclose(log_file);

    return 0;
}

