#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>

// LSM303DLHC I2C addresses
#define ACCEL_ADDR 0x19
#define MAG_ADDR 0x1E

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x20
#define CRA_REG_M 0x00
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Sensitivity values (adjust based on your sensor's configuration)
#define ACCEL_SENSITIVITY 0.001 // g/LSB
#define MAG_SENSITIVITY 0.08  // Gauss/LSB

// Global variables
int i2c_handle_accel, i2c_handle_mag;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float x, y, z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_sensors();
sensor_data_t read_accelerometer();
sensor_data_t read_magnetometer();
float calculate_heading(sensor_data_t accel, sensor_data_t mag);
int log_data(float heading, sensor_data_t accel, sensor_data_t mag);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle_accel >= 0) i2cClose(i2c_handle_accel);
    if (i2c_handle_mag >= 0) i2cClose(i2c_handle_mag);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle_accel = i2cOpen(1, ACCEL_ADDR, 0);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Failed to open I2C device for accelerometer: %d\n", i2c_handle_accel);
        return -1;
    }

    i2c_handle_mag = i2cOpen(1, MAG_ADDR, 0);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Failed to open I2C device for magnetometer: %d\n", i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        return -1;
    }

    return 0;
}

// Initialize sensors
int init_sensors() {
    // Accelerometer: Enable all axes, 50Hz data rate
    if (i2cWriteByteData(i2c_handle_accel, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Failed to write to accelerometer CTRL_REG1_A\n");
        return -1;
    }

    // Magnetometer: Enable continuous conversion mode, 15 Hz data rate
    if (i2cWriteByteData(i2c_handle_mag, CRA_REG_M, 0x18) < 0) {
        fprintf(stderr, "Failed to write to magnetometer CRA_REG_M\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data
sensor_data_t read_accelerometer() {
    sensor_data_t data;
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle_accel, OUT_X_L_A | 0x80, buf, 6) < 0) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        data.x = data.y = data.z = 0.0; // Return zeroed data on error
        return data;
    }

    int16_t x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t z = (int16_t)((buf[5] << 8) | buf[4]);

    data.x = (float)x * ACCEL_SENSITIVITY;
    data.y = (float)y * ACCEL_SENSITIVITY;
    data.z = (float)z * ACCEL_SENSITIVITY;

    return data;
}

// Read magnetometer data
sensor_data_t read_magnetometer() {
    sensor_data_t data;
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle_mag, OUT_X_H_M, buf, 6) < 0) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        data.x = data.y = data.z = 0.0; // Return zeroed data on error
        return data;
    }

    int16_t x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t z = (int16_t)((buf[4] << 8) | buf[5]);

    data.x = (float)x * MAG_SENSITIVITY;
    data.y = (float)y * MAG_SENSITIVITY;
    data.z = (float)z * MAG_SENSITIVITY;

    return data;
}

// Calculate heading
float calculate_heading(sensor_data_t accel, sensor_data_t mag) {
    float roll = atan2(accel.y, accel.z);
    float pitch = atan2(-accel.x, sqrt(accel.y * accel.y + accel.z * accel.z));

    float mag_x = mag.x * cos(pitch) + mag.z * sin(pitch);
    float mag_y = mag.x * sin(roll) * sin(pitch) + mag.y * cos(roll) - mag.z * sin(roll) * cos(pitch);

    float heading = atan2(mag_y, mag_x);

    if (heading < 0) {
        heading += 2 * M_PI;
    }

    if (heading > 2 * M_PI) {
        heading -= 2 * M_PI;
    }

    return heading * 180 / M_PI;
}

// Log data to file
int log_data(float heading, sensor_data_t accel, sensor_data_t mag) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, heading, accel.x, accel.y, accel.z, mag.x, mag.y, mag.z);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Initialize sensors
    if (init_sensors() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading,Accel_X,Accel_Y,Accel_Z,Mag_X,Mag_Y,Mag_Z\n");
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t accel_data = read_accelerometer();
        sensor_data_t mag_data = read_magnetometer();

        // Calculate heading
        float heading = calculate_heading(accel_data, mag_data);

        // Log data
        log_data(heading, accel_data, mag_data);

        // Delay
        gpioDelay(100); // 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

