#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// VL6180X I2C address
#define VL6180X_ADDR 0x29

// VL6180X register addresses
#define VL6180X_REG_IDENTIFICATION_MODEL_ID 0x000
#define VL6180X_REG_SYSTEM_FRESH_OUT_OF_RESET 0x016
#define VL6180X_REG_SYSRANGE_START 0x018
#define VL6180X_REG_RESULT_RANGE_VAL 0x062

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl6180x_init();
int read_distance();
void log_data(int distance, const char *status);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// VL6180X initialization function
int vl6180x_init() {
    int status;

    // Check sensor ID
    status = i2cReadByteData(i2c_handle, VL6180X_REG_IDENTIFICATION_MODEL_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", status);
        return -1;
    }
    if (status != 0xB4) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", status);
        return -1;
    }

    // Recommended init sequence from datasheet
    status = i2cWriteByteData(i2c_handle, 0x020, 0x01); // set bit 0
    if (status < 0) return -1;
    status = i2cWriteByteData(i2c_handle, 0x021, 0x02); // set bit 1
    if (status < 0) return -1;
    status = i2cWriteByteData(i2c_handle, 0x022, 0x04); // set bit 2
    if (status < 0) return -1;
    status = i2cWriteByteData(i2c_handle, 0x023, 0x08); // set bit 3
    if (status < 0) return -1;
    status = i2cWriteByteData(i2c_handle, 0x024, 0x10); // set bit 4
    if (status < 0) return -1;
    status = i2cWriteByteData(i2c_handle, 0x025, 0x20); // set bit 5
    if (status < 0) return -1;
    status = i2cWriteByteData(i2c_handle, 0x026, 0x40); // set bit 6
    if (status < 0) return -1;
    status = i2cWriteByteData(i2c_handle, 0x027, 0x80); // set bit 7
    if (status < 0) return -1;

    status = i2cWriteByteData(i2c_handle, 0x010, 0x00); // clear bit 0
    if (status < 0) return -1;
    status = i2cWriteByteData(i2c_handle, 0x011, 0x00); // clear bit 1
    if (status < 0) return -1;
    status = i2cWriteByteData(i2c_handle, 0x012, 0x00); // clear bit 2
    if (status < 0) return -1;
    status = i2cWriteByteData(i2c_handle, 0x013, 0x00); // clear bit 3
    if (status < 0) return -1;
    status = i2cWriteByteData(i2c_handle, 0x014, 0x00); // clear bit 4
