#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Sensor I2C addresses
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69

// I2C bus
#define I2C_BUS 1

// Sampling interval (in microseconds)
#define SAMPLING_INTERVAL 10000

// File to log data
#define LOG_FILE "audio_log.dat"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t sensor1;
    int16_t sensor2;
    long tdoa;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the pigpio library and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return -1;
    }

    return 0;
}

