#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0       // Mode 0 (CPOL=0, CPHA=0)
#define GYRO_SENSITIVITY 0.005 // deg/sec/LSB
#define ACCEL_SENSITIVITY 0.00025 // g/LSB
#define SAMPLE_INTERVAL_MS 100
#define STALL_TIME_US 40
#define DATA_FILE "imu_data.csv"
#define HEADER_FILE "imu_header.csv"

// Global variables
int spi_handle = -1;
FILE *data_file = NULL;
volatile sig_atomic_t running = 1;

// Function prototypes
int spi_read_register(int handle, uint8_t reg);
int spi_write_register(int handle, uint8_t reg, uint16_t data);
int read_imu_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z);
int write_data_to_file(FILE *file, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z);
void cleanup();
void signal_handler(int signal);

// Function to read a register via SPI
int spi_read_register(int handle, uint8_t reg) {
    char tx[2], rx[2];
    tx[0] = 0x00; // Command word: Read
    tx[1] = reg;  // Register address

    if (spiXfer(handle, tx, rx, 2) != 2) {
        fprintf(stderr, "Error: SPI read failed for register 0x%02X\n", reg);
        return -1;
    }

    return (rx[1] << 8) | rx[0]; // Combine the two bytes into a 16-bit value
}

// Function to write a register via SPI
int spi_write_register(int handle, uint8_t reg, uint16_t data) {
    char tx[3], rx[3];
    tx[0] = 0x80; // Command word: Write
    tx[1] = reg;  // Register address
    tx[2] = data & 0xFF; // Lower byte of data

    if (spiXfer(handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI write failed for register 0x%02X\n", reg);
        return -1;
    }

    tx[0] = 0x00; // Command word: Read
    tx[1] = reg;  // Register address
    tx[2] = (data >> 8) & 0xFF; // Upper byte of data

    if (spiXfer(handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI write failed for register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

// Function to read IMU data
int read_imu_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z) {
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;

    // Read raw gyroscope data
    raw_gyro_x = spi_read_register(handle, 0x04); // GYRO_XOUT
    raw_gyro_y = spi_read_register(handle, 0x06); // GYRO_YOUT
    raw_gyro_z = spi_read_register(handle, 0x08); // GYRO_ZOUT

    // Read raw accelerometer data
    raw_accel_x = spi_read_register(handle, 0x0A); // ACCEL_XOUT
    raw_accel_y = spi_read_register(handle, 0x0C); // ACCEL_YOUT
    raw_accel_z = spi_read_register(handle, 0x0E); // ACCEL_ZOUT

    if (raw_gyro_x < 0 || raw_gyro_y < 0 || raw_gyro_z < 0 || raw_accel_x < 0 || raw_accel_y < 0 || raw_accel_z < 0) {
        fprintf(stderr, "Error: Invalid raw data read\n");
        return -1;
    }

    // Convert raw data to physical units
    *gyro_x = (float)raw_gyro_x * GYRO_SENSITIVITY;
    *gyro_y = (float)raw_gyro_y * GYRO_SENSITIVITY;
    *gyro_z = (float)raw_gyro_z * GYRO_SENSITIVITY;
    *accel_x = (float)raw_accel_x * ACCEL_SENSITIVITY;
    *accel_y = (float)raw_accel_y * ACCEL_SENSITIVITY;
    *accel_z = (float)raw_accel_z * ACCEL_SENSITIVITY;

    return 0;
}

// Function to write data to file
int write_data_to_file(FILE *file, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z) {
    time_t timestamp = time(NULL);
    if (fprintf(file, "%ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n", timestamp, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z) < 0) {
        fprintf(stderr, "Error: Failed to write data to file\n");
        return -1;
    }
    return 0;
}

// Cleanup function to be called on exit
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d).  Shutting down...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        cleanup();
        return 1;
    }

    // Open data file
    data_file = fopen(DATA_FILE, "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error: Failed to open data file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(data_file, 0, SEEK_END);
    long file_size = ftell(data_file);
    if (file_size == 0) {
        FILE *header_file = fopen(HEADER_FILE, "r");
        if (header_file != NULL) {
            char header[256];
            if (fgets(header, sizeof(header), header_file) != NULL) {
                fprintf(data_file, "%s", header);
            }
            fclose(header_file);
        }
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register cleanup function
    atexit(cleanup);

    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    int delay_count = 0;

    // Main loop
    while (running) {
        // Read IMU data
        if (read_imu_data(spi_handle, &gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z) == 0) {
            // Write data to file
            if (write_data_to_file(data_file, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z) != 0) {
                running = 0; // Stop if file write fails
            }
        } else {
            running = 0; // Stop if IMU read fails
        }

        // Delay to achieve 100ms sampling rate
        delay_count++;
        if (delay_count >= (SAMPLE_INTERVAL_MS / STALL_TIME_US)) {
            gpioDelay(STALL_TIME_US); // Delay in microseconds
            delay_count = 0;
        }
    }

    // Cleanup will be called on exit
    return 0;
}

