    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read Register Function
int read_register(uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Set MSB of register address to 1 for read operation
    tx_buf[0] = (reg_addr << 1) | 0x80;
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
