#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to read a 16-bit value from the IMU
int16_t read_imu_value(int i2c_handle, uint8_t high_reg, uint8_t low_reg)
{
    int retries = 3;
    int16_t value = 0;
    char buf[2];

    while (retries > 0) {
        // Read high byte
        if (i2cReadI2CBlockData(i2c_handle, high_reg, buf, 2) == 2) {
            value = (int16_t)((buf[0] << 8) | buf[1]);
            return value;
        } else {
            fprintf(stderr, "Error reading IMU value, retrying...\n");
            gpioDelay(10); // Small delay before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read IMU value after multiple retries.\n");
    return 0; // Return 0 on failure
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPU6886_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wake up the MPU-6886 (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to wake up MPU-6886\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        // Read accelerometer values
        int16_t accel_x = read_imu_value(i2c_handle, ACCEL_XOUT_H, ACCEL_XOUT_H + 1);
        int16_t accel_y = read_imu_value(i2c_handle, ACCEL_XOUT_H + 2, ACCEL_XOUT_H + 3);
        int16_t accel_z = read_imu_value(i2c_handle, ACCEL_XOUT_H + 4, ACCEL_XOUT_H + 5);

        // Read gyroscope values
        int16_t gyro_x = read_imu_value(i2c_handle, GYRO_XOUT_H, GYRO_XOUT_H + 1);
        int16_t gyro_y = read_imu_value(i2c_handle, GYRO_XOUT_H + 2, GYRO_XOUT_H + 3);
        int16_t gyro_z = read_imu_value(i2c_handle, GYRO_XOUT_H + 4, GYRO_XOUT_H + 5);

        // Print the values
        printf("Accel: %6d %6d %6d | Gyro: %6d %6d %6d\n", accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        // Delay for 50ms
        gpioDelay(50);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

