#define ADXL345_DATAX0 0x32
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAZ0 0x36
#define ADXL345_RANGE 2.0f // ±2g
#define LED_GPIO 17
#define IMPACT_THRESHOLD 2.5f
#define SAMPLE_INTERVAL_MS 10
#define SAMPLE_INTERVAL_US (SAMPLE_INTERVAL_MS * 1000)

// Global variables
int i2c_handle;
FILE *log_file;
bool running = true;

// Function prototypes
int init_i2c();
int verify_device_id();
int configure_adxl345();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void control_led(int on);
void log_impact(int16_t x, int16_t y, int16_t z, float magnitude);
void signal_handler(int signal);

// Structure for grouping sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        fprintf(stderr, "Device ID verification failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADXL345
    if (configure_adxl345() != 0) {
        fprintf(stderr, "ADXL345 configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    float magnitude;
    while (running) {
        // Read acceleration data
        if (read_acceleration(&sensor_data.x, &sensor_data.y, &sensor_data.z) != 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            break; // Exit loop on error
        }

        // Calculate magnitude
        magnitude = calculate_magnitude(sensor_data.x, sensor_data.y, sensor_data.z);

        // Check for impact
        if (magnitude > IMPACT_THRESHOLD) {
            control_led(1); // Turn on LED
            log_impact(sensor_data.x, sensor_data.y, sensor_data.z, magnitude);
            gpioDelay(500); // Wait 500ms
            control_led(0); // Turn off LED
        }

        gpioDelay(SAMPLE_INTERVAL_US); // Delay for 10ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify device ID
int verify_device_id() {
    int device_id = i2cReadByteData(i2c_handle, 0x00);
    if (device_id < 0) {
        fprintf(stderr, "Failed to read device ID: %d\n", device_id);
        return -1;
    }
    if (device_id != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%X\n", device_id);
        return -1;
    }
    return 0;
}

// Configure ADXL345
int configure_adxl345() {
    // Set data format register to full resolution and ±2g range
    int status = i2cWriteByteData(i2c_handle, 0x31, 0x08); // Full resolution, ±2g
    if (status < 0) {
        fprintf(stderr, "Failed to write data format register: %d\n", status);
        return -1;
    }

    // Set power control register to measure mode
    status = i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08); // Measurement mode
    if (status < 0) {
        fprintf(stderr, "Failed to write power control register: %d\n", status);
        return -1;
    }
    return 0;
}

// Read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, buffer, 6);
    if (status < 0) {
        fprintf(stderr, "Failed to read acceleration data: %d\n", status);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate magnitude
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 256.0f;
    float y_g = (float)y / 256.0f;
    float z_g = (float)z / 256.0f;
    return sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Log impact
void log_impact(int16_t x, int16_t y, int16_t z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    running = false;
}

