#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define ADXL345_DEVID 0x00
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_INT_ENABLE 0x2E
#define ADXL345_INT_SOURCE 0x30
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAZ0 0x36
#define ADXL345_INT1_PIN 17
#define FREEFALL_THRESHOLD 0.3f // g
#define FREEFALL_TIME 0.1f      // seconds
#define SAMPLE_RATE 100         // Hz
#define SAMPLE_PERIOD (1000000 / SAMPLE_RATE) // microseconds

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int adxl345_init();
int adxl345_read_register(uint8_t reg, uint8_t *value);
int adxl345_write_register(uint8_t reg, uint8_t value);
int adxl345_read_acceleration(float *x, float *y, float *z);
void freefall_interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);
int setup_gpio_interrupt();
int cleanup_gpio_interrupt();
int open_log_file();
int close_log_file();
int write_log_entry(float x, float y, float z);

// Function to read a single byte from an ADXL345 register
int adxl345_read_register(uint8_t reg, uint8_t *value) {
  if (i2c_fd < 0) return -1; // I2C not initialized
  if (value == NULL) return -1; // Invalid argument

  if (write(i2c_fd, &reg, 1) != 1) {
    perror("Failed to write register address");
    return -1;
  }

  if (read(i2c_fd, value, 1) != 1) {
    perror("Failed to read register value");
    return -1;
  }

  return 0;
}

// Function to write a single byte to an ADXL345 register
int adxl345_write_register(uint8_t reg, uint8_t value) {
  uint8_t buf[2];
  buf[0] = reg;
  buf[1] = value;

  if (i2c_fd < 0) return -1; // I2C not initialized

  if (write(i2c_fd, buf, 2) != 2) {
    perror("Failed to write to register");
    return -1;
  }

  return 0;
}

// Function to initialize the ADXL345
int adxl345_init() {
  uint8_t devid;

  // Verify device ID
  if (adxl345_read_register(ADXL345_DEVID, &devid) != 0) {
    fprintf(stderr, "Error reading device ID\n");
    return -1;
  }

  if (devid != 0xE5) {
    fprintf(stderr, "Incorrect device ID: 0x%02X\n", devid);
    return -1;
  }

  // Set data format: +/- 2g range, full resolution
  if (adxl345_write_register(ADXL345_DATA_FORMAT, 0x0B) != 0) {
    fprintf(stderr, "Error setting data format\n");
    return -1;
  }

  // Put the ADXL345 into standby mode
  if (adxl345_write_register(ADXL345_POWER_CTL, 0x00) != 0) {
    fprintf(stderr, "Error putting ADXL345 into standby mode\n");
    return -1;
  }

  // Enable free-fall interrupt
  if (adxl345_write_register(ADXL345_INT_ENABLE, 0x10) != 0) {
    fprintf(stderr, "Error enabling free-fall interrupt\n");
    return -1;
  }

  return 0;
}

// Function to read acceleration data from the ADXL345
int adxl345_read_acceleration(float *x, float *y, float *z) {
  uint8_t raw_data[6];
  int16_t x_raw, y_raw, z_raw;

  // Read all six acceleration registers in one go
  if (adxl345_read_register(ADXL345_DATAX0, &raw_data[0]) != 0 ||
      adxl345_read_register(ADXL345_DATAX0 + 1, &raw_data[1]) != 0 ||
      adxl345_read_register(ADXL345_DATAY0, &raw_data[2]) != 0 ||
      adxl345_read_register(ADXL345_DATAY0 + 1, &raw_data[3]) != 0 ||
      adxl345_read_register(ADXL345_DATAZ0, &raw_data[4]) != 0 ||
      adxl345_read_register(ADXL345_DATAZ0 + 1, &raw_data[5]) != 0) {
    fprintf(stderr, "Error reading acceleration data\n");
    return -1;
  }

  // Combine high and low bytes, and convert to g units
  x_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);
  y_raw = (int16_t)((raw_data[3] << 8) | raw_data[2]);
  z_raw = (int16_t)((raw_data[5] << 8) | raw_data[4]);

  *x = (float)x_raw / 256.0f; // Assuming +/- 2g range, 10 bits resolution
  *y = (float)y_raw / 256.0f;
  *z = (float)z_raw / 256.0f;

  return 0;
}

// Function to handle free-fall interrupt
void freefall_interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
  static uint32_t start_time = 0;
  static int freefall_active = 0;
  float x, y, z;
  struct timespec ts;
  char timestamp[30];

  if (level == 1) { // Rising edge (free-fall detected)
    clock_gettime(CLOCK_REALTIME, &ts);
    start_time = ts.tv_sec * 1000000 + ts.tv_nsec / 1000; // microseconds
    freefall_active = 1;
  } else if (level == 0) { // Falling edge (free-fall ended)
    freefall_active = 0;
  }

  if (freefall_active) {
    clock_gettime(CLOCK_REALTIME, &ts);
    uint32_t current_time = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

    if (current_time - start_time >= (uint32_t)(FREEFALL_TIME * 1000000)) {
      if (adxl345_read_acceleration(&x, &y, &z) == 0) {
        if (write_log_entry(x, y, z) != 0) {
          fprintf(stderr, "Error writing log entry\n");
        }
      } else {
        fprintf(stderr, "Error reading acceleration data in interrupt handler\n");
      }
      start_time = 0; // Reset start time after logging
    }
  }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
  fprintf(stderr, "Received signal %d, terminating...\n", signal);
  terminate = 1;
}

// Function to setup GPIO interrupt
int setup_gpio_interrupt() {
  if (gpioSetMode(ADXL345_INT1_PIN, PI_INPUT) != 0) {
    fprintf(stderr, "Error setting GPIO mode\n");
    return -1;
  }

  if (gpioSetISRFuncEx(ADXL345_INT1_PIN, EITHER_EDGE, 0, freefall_interrupt_handler, NULL) != 0) {
    fprintf(stderr, "Error setting ISR function\n");
    return -1;
  }

  return 0;
}

// Function to cleanup GPIO interrupt
int cleanup_gpio_interrupt() {
  gpioSetISRFuncEx(ADXL345_INT1_PIN, EITHER_EDGE, 0, NULL, NULL); // Disable interrupt
  gpioSetMode(ADXL345_INT1_PIN, PI_INPUT); // Set back to input
  return 0;
}

// Function to open the log file
int open_log_file() {
  log_file = fopen("freefall_log.csv", "a");
  if (log_file == NULL) {
    perror("Failed to open log file");
    return -1;
  }

  // Write header if the file is newly created
  fseek(log_file, 0, SEEK_END);
  long file_size = ftell(log_file);
  if (file_size == 0) {
    fprintf(log_file, "Timestamp,X,Y,Z\n");
  }

  return 0;
}

// Function to close the log file
int close_log_file() {
  if (log_file != NULL) {
    fflush(log_file);
    fclose(log_file);
    log_file = NULL;
  }
  return 0;
}

// Function to write a log entry
int write_log_entry(float x, float y, float z) {
  struct timespec ts;
  char timestamp[30];

  clock_gettime(CLOCK_REALTIME, &ts);
  snprintf(timestamp, sizeof(timestamp), "%ld.%03ld", ts.tv_sec, ts.tv_nsec / 1000000);

  fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
  fflush(log_file); // Flush to ensure data is written immediately

  return 0;
}

int main() {
  // Initialize pigpio
  if (gpioInitialise() < 0) {
    fprintf(stderr, "pigpio initialisation failed\n");
    return 1;
  }

  // Open I2C bus
  i2c_fd = open(I2C_BUS, O_RDWR);
  if (i2c_fd < 0) {
    perror("Failed to open I2C bus");
    gpioTerminate();
    return 1;
  }

  // Set I2C slave address
  if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
    perror("Failed to set I2C slave address");
    close(i2c_fd);
