  if (setup_gpio_interrupt() != 0) {
    fprintf(stderr, "GPIO interrupt setup failed\n");
    close(i2c_fd);
    gpioTerminate();
    return 1;
  }

  // Open log file
  if (open_log_file() != 0) {
    fprintf(stderr, "Failed to open log file\n");
    cleanup_gpio_interrupt();
    close(i2c_fd);
    gpioTerminate();
    return 1;
  }

  // Set up signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Main loop
  while (!terminate) {
    // Do other tasks here if needed
    usleep(SAMPLE_PERIOD); // Sleep for the sample period
  }

  // Cleanup
  fprintf(stderr, "Cleaning up...\n");
  cleanup_gpio_interrupt();
  close_log_file();
  close(i2c_fd);
  gpioTerminate();

  return 0;
}

