#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <unistd.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28
#define WHO_AM_I 0x0F

// Configuration values
#define ACCEL_ODR_104HZ 0x60 // 104 Hz output data rate
#define ACCEL_FS_2G 0x00      // ±2g full-scale
#define GYRO_FS_250DPS 0x00   // ±250 dps full-scale

// Fall detection thresholds
#define FALL_THRESHOLD 0.2  // g
#define IMPACT_THRESHOLD 2.5 // g
#define IMPACT_WINDOW 1.0   // s

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x;
    float accel_y;
    float accel_z;
    float gyro_x;
    float gyro_y;
    float gyro_z;
} sensor_data_t;

// Function prototypes
int init_imu();
int read_imu_data(sensor_data_t *data);
float calculate_acceleration_magnitude(sensor_data_t data);
void log_data(sensor_data_t data);
void fall_detection(sensor_data_t data);
void signal_handler(int signal);

// Function to initialize the IMU
int init_imu() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x69, got 0x%x\n", who_am_i);
        return -1;
    }

    // Configure accelerometer
    int config_accel = i2cWriteByteData(i2c_handle, CTRL1_XL, ACCEL_ODR_104HZ | ACCEL_FS_2G);
    if (config_accel < 0) {
        fprintf(stderr, "Error configuring accelerometer: %d\n", config_accel);
        return -1;
    }

    // Configure gyroscope
    int config_gyro = i2cWriteByteData(i2c_handle, CTRL2_G, GYRO_FS_250DPS);
    if (config_gyro < 0) {
        fprintf(stderr, "Error configuring gyroscope: %d\n", config_gyro);
        return -1;
    }

    return 0;
}

// Function to read IMU data
int read_imu_data(sensor_data_t *data) {
    char buffer[12];
    int read_result = i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buffer, 12);
    if (read_result < 0) {
        fprintf(stderr, "Error reading IMU data: %d\n", read_result);
        return -1;
    }

    // Convert raw data to g and dps
    int16_t raw_accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    int16_t raw_gyro_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t raw_gyro_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t raw_gyro_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    data->accel_x = (float)raw_accel_x / 16384.0f; // 2g range
    data->accel_y = (float)raw_accel_y / 16384.0f;
    data->accel_z = (float)raw_accel_z / 16384.0f;
    data->gyro_x = (float)raw_gyro_x / 131.0f; // 250 dps range
    data->gyro_y = (float)raw_gyro_y / 131.0f;
    data->gyro_z = (float)raw_gyro_z / 131.0f;

    return 0;
}

// Function to calculate acceleration magnitude
float calculate_acceleration_magnitude(sensor_data_t data) {
    return sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);
}

// Function to log data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z, data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to implement fall detection state machine
void fall_detection(sensor_data_t data) {
    static float acceleration_magnitude = 0.0;
    static time_t impact_start_time = 0;
    static int state = 0; // 0: IDLE, 1: FREEFALL, 2: IMPACT

    acceleration_magnitude = calculate_acceleration_magnitude(data);

    switch (state) {
        case 0: // IDLE
            if (acceleration_magnitude < FALL_THRESHOLD) {
                state = 1;
                printf("Transition to FREEFALL\n");
            }
            break;
        case 1: // FREEFALL
            if (acceleration_magnitude > IMPACT_THRESHOLD) {
                state = 2;
                impact_start_time = time(NULL);
                printf("Transition to IMPACT\n");
            }
            break;
        case 2: // IMPACT
            if (time(NULL) - impact_start_time >= IMPACT_WINDOW) {
                state = 0;
                printf("Transition back to IDLE\n");
            }
            break;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize IMU
    if (init_imu() < 0) {
        fprintf(stderr, "IMU initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read IMU data
        if (read_imu_data(&sensor_data) == 0) {
            // Log data
            log_data(sensor_data);

            // Perform fall detection
            fall_detection(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (init_imu() < 0) {
                    fprintf(stderr, "IMU re-initialisation failed\n");
                    terminate = 1;
                }
            }
        }

        // Delay for approximately 10ms (100Hz sampling rate)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

