#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define ADIS16266_WHO_AM_I 0x02
#define ADIS16266_GYRO_OUT 0x04

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0 // Mode 0 (CPOL=0, CPHA=0)

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data);
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data);
int verify_who_am_i(int handle);
float read_gyro_rate(int handle);
void log_data(float rate);
void signal_handler(int signal);

// SPI Read Register Function
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr | 0x80; // Set MSB for read
    tx_buf[1] = 0x00; // Dummy byte

    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI Read Error: %d\n", result);
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// SPI Write Register Function
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write
    tx_buf[1] = data & 0xFF; //LSB

    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI Write Error: %d\n", result);
        return -1;
    }

    tx_buf[0] = (data >> 8) & 0xFF; //MSB
    tx_buf[1] = 0x00; //Dummy byte

    result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI Write Error: %d\n", result);
        return -1;
    }

    return 0;
}

// Verify WHO_AM_I Register Function
int verify_who_am_i(int handle) {
    uint16_t who_am_i;
    if (spi_read_register(handle, ADIS16266_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register.\n");
        return -1;
    }

    if (who_am_i != 0x3D) {
        fprintf(stderr, "WHO_AM_I mismatch: Expected 0x3D, got 0x%02X\n", who_am_i);
        return -1;
    }

    printf("WHO_AM_I verification successful.\n");
    return 0;
}

// Read Gyroscope Rate Function
float read_gyro_rate(int handle) {
    uint16_t raw_data;
    if (spi_read_register(handle, ADIS16266_GYRO_OUT, &raw_data) != 0) {
        fprintf(stderr, "Failed to read gyro rate.\n");
        return 0.0;
    }

    // Scale factor: 0.0305 deg/sec/LSB
    return (float)((int16_t)raw_data) * 0.0305;
}

// Log Data Function
void log_data(float rate) {
    time_t now = time(NULL);
    fprintf(log_file, "%ld,%.4f\n", now, rate);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal Handler Function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I register
    if (verify_who_am_i(spi_handle) != 0) {
        fprintf(stderr, "WHO_AM_I verification failed.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Rate\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float rate = read_gyro_rate(spi_handle);
        log_data(rate);
        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

