#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0xD3
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define SENSITIVITY 8.75f // mdps/LSB
#define SAMPLE_INTERVAL_NS 10000000 // 10ms in nanoseconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_gyro();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful termination
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the gyroscope
int init_gyro() {
    int retries = 3;
    int status;

    // Check WHO_AM_I register
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, WHO_AM_I_REG, 0x00); // Dummy write to trigger read
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to WHO_AM_I register: %s\n", strerror(errno));
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register after multiple retries.\n");
        return -1;
    }

    char who_am_i;
    retries = 3;
    while (retries > 0) {
        who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
        if (who_am_i >= 0) {
            break;
        } else {
            fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register after multiple retries.\n");
        return -1;
    }

    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, 100Hz)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F); // Normal mode, 100Hz
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1 after multiple retries.\n");
        return -1;
    }

    // Configure CTRL_REG4 (8.75 mdps/LSB)
    retries = 3;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00); // 8.75 mdps/LSB
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "Error writing to CTRL_REG4: %s\n", strerror(errno));
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4 after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    int16_t raw_x, raw_y, raw_z;
    int retries = 3;
    int status;

    // Read X axis
    while (retries > 0) {
        raw_x = i2cReadWordData(i2c_handle, OUT_X_L);
        if (raw_x >= 0) {
            break;
        } else {
            fprintf(stderr, "Error reading X axis data: %s\n", strerror(errno));
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read X axis data after multiple retries.\n");
        data.x = 0.0f; // Return 0 in case of error
    } else {
        data.x = (float)raw_x / SENSITIVITY;
    }

    // Read Y axis
    retries = 3;
    while (retries > 0) {
        raw_y = i2cReadWordData(i2c_handle, OUT_Y_L);
        if (raw_y >= 0) {
            break;
        } else {
            fprintf(stderr, "Error reading Y axis data: %s\n", strerror(errno));
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read Y axis data after multiple retries.\n");
        data.y = 0.0f; // Return 0 in case of error
    } else {
        data.y = (float)raw_y / SENSITIVITY;
    }

    // Read Z axis
    retries = 3;
    while (retries > 0) {
        raw_z = i2cReadWordData(i2c_handle, OUT_Z_L);
        if (raw_z >= 0) {
            break;
        } else {
            fprintf(stderr, "Error reading Z axis data: %s\n", strerror(errno));
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read Z axis data after multiple retries.\n");
        data.z = 0.0f; // Return 0 in case of error
