#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_events.log"

volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int sensor_value;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];
    char log_message[100];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input with pull-up resistor
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);

    // Open log file in append mode
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor value
        sensor_value = gpioRead(FLAME_SENSOR_GPIO);

        // Get current timestamp
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Format log message
        if (sensor_value == 0) {
            snprintf(log_message, sizeof(log_message), "%s - Flame detected: YES\n", timestamp);
            printf("FLAME DETECTED!\n");
        } else {
            snprintf(log_message, sizeof(log_message), "%s - Flame detected: NO\n", timestamp);
        }

        // Write to log file
        if (fputs(log_message, log_file) == EOF) {
            fprintf(stderr, "Error writing to log file!\n");
        }
        fflush(log_file); // Flush the buffer to ensure immediate write

        // Wait 500ms
        gpioDelay(500000); // pigpio uses microseconds
    }

    // Clean up and exit
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

