#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VAL 0x1A
#define CTRL_REG1 0x2A
#define CTRL_REG1_STANDBY 0x00
#define CTRL_REG1_100HZ 0x01
#define CTRL_REG1_ACTIVE 0x02
#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define TILT_THRESHOLD 45.0f
#define LOG_FILE "fall_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int verify_who_am_i(int fd);
int initialize_accelerometer(int fd);
accelerometer_data_t read_accelerometer_data(int fd);
float calculate_tilt(accelerometer_data_t data);
void log_fall_event(accelerometer_data_t data);
void signal_handler(int signal);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return buf[0];
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Verify WHO_AM_I register
int verify_who_am_i(int fd) {
    int who_am_i = i2c_read_reg(fd, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I value mismatch: expected 0x%02X, got 0x%02X\n", WHO_AM_I_VAL, who_am_i);
        return -1;
    }
    printf("WHO_AM_I value verified: 0x%02X\n", who_am_i);
    return 0;
}

// Initialize accelerometer
int initialize_accelerometer(int fd) {
    // Put in standby mode
    if (i2c_write_reg(fd, CTRL_REG1, CTRL_REG1_STANDBY) < 0) {
        fprintf(stderr, "Error setting standby mode.\n");
        return -1;
    }
    // Set data rate to 100 Hz
    if (i2c_write_reg(fd, CTRL_REG1, CTRL_REG1_100HZ) < 0) {
        fprintf(stderr, "Error setting data rate to 100 Hz.\n");
        return -1;
    }
    // Enable active mode
    if (i2c_write_reg(fd, CTRL_REG1, CTRL_REG1_ACTIVE) < 0) {
        fprintf(stderr, "Error setting active mode.\n");
        return -1;
    }
    printf("Accelerometer initialized.\n");
    return 0;
}

// Read accelerometer data
accelerometer_data_t read_accelerometer_data(int fd) {
    accelerometer_data_t data;
    uint8_t buf[6];

    // Read all six data registers in one go
    uint8_t reg = OUT_X_MSB;
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device for multi-read: %s\n", strerror(errno));
        data.x = 0; data.y = 0; data.z = 0; // Return default values
        return data;
    }
    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device for multi-read: %s\n", strerror(errno));
        data.x = 0; data.y = 0; data.z = 0; // Return default values
        return data;
    }

    // Combine MSB and LSB, right-shift by 4
    data.x = ((int16_t)(buf[0] << 8 | buf[1])) >> 4;
    data.y = ((int16_t)(buf[2] << 8 | buf[3])) >> 4;
    data.z = ((int16_t)(buf[4] << 8 | buf[5])) >> 4;

    return data;
}

// Calculate tilt angle
float calculate_tilt(accelerometer_data_t data) {
    float x = (float)data.x;
    float y = (float)data.y;
    float z = (float)data.z;
    float tilt = (180.0f / M_PI) * atan2(y, sqrt(x * x + z * z));
    return tilt;
}

// Log fall event
void log_fall_event(accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to file immediately
    printf("Fall event logged: %s, X: %d, Y: %d, Z: %d\n", timestamp, data.x, data.y, data.z);
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Verify WHO_AM_I register
    if (verify_who_am_i(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Initialize accelerometer
    if (initialize_accelerometer(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 10 ms

    while (!terminate) {
        // Read accelerometer data
        accelerometer_data_t data = read_accelerometer_data(i2c_fd);

        // Calculate tilt angle
        float tilt = calculate_tilt(data);

        // Check for fall event
        if (fabs(tilt) > TILT_THRESHOLD) {
            log_fall_event(data);
        }

        // Sleep for 10 ms
        nanosleep(&sleep_time, NULL);
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    printf("Program terminated.\n");
    return 0;
}

