#include <time.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_OUT_X_L 0x28
#define LIS3MDL_OUT_X_H 0x29
#define LIS3MDL_OUT_Y_L 0x2A
#define LIS3MDL_OUT_Y_H 0x2B
#define LIS3MDL_OUT_Z_L 0x2C
#define LIS3MDL_OUT_Z_H 0x2D

// Calibration constants (replace with your actual values)
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define SCALE_FACTOR 0.146

// Metal detector threshold
#define METAL_THRESHOLD 800.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

// Function to initialize the LIS3MDL sensor
int init_lis3mdl() {
    int retries = 3;
    int status;

    while (retries > 0) {
        // Set CTRL_REG1 to enable continuous mode and 10 Hz data rate
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG1, 0x70); //0x70
        if (status < 0) {
            fprintf(stderr, "Error writing to CTRL_REG1: %d\n", status);
            retries--;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Set CTRL_REG3 to enable continuous conversion mode
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG3, 0x00);
        if (status < 0) {
            fprintf(stderr, "Error writing to CTRL_REG3: %d\n", status);
            retries--;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        return 0; // Initialization successful
    }

    fprintf(stderr, "LIS3MDL initialization failed after multiple retries.\n");
    return -1; // Initialization failed
}

// Function to read raw magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle, LIS3MDL_OUT_X_L, buffer, 6);

    if (status < 0) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", status);
