#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL354B Register Addresses
#define ADXL354B_RESET_REG   0x1F
#define ADXL354B_POWER_CTL   0x2D
#define ADXL354B_STATUS      0x2E
#define ADXL354B_XDATA_L     0x0E
#define ADXL354B_XDATA_H     0x0F
#define ADXL354B_YDATA_L     0x10
#define ADXL354B_YDATA_H     0x11
#define ADXL354B_ZDATA_L     0x12
#define ADXL354B_ZDATA_H     0x13
#define ADXL354B_PARTID      0x2C

// ADXL354B Reset Value
#define ADXL354B_RESET_VALUE 0x52

// ADXL354B Part ID
#define ADXL354B_PARTID_VALUE 0xAD

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg, uint8_t *data, int len);
int spi_write_register(int handle, uint8_t reg, uint8_t data);
int adxl354b_reset(int handle);
int adxl354b_power_control(int handle, uint8_t power_state);
int adxl354b_wait_for_stable(int handle);
int adxl354b_read_acceleration(int handle, int32_t *x, int32_t *y, int32_t *z);
int adxl354b_verify_partid(int handle);
void log_data(FILE *fp, int32_t x, int32_t y, int32_t z);
void signal_handler(int signal);

// SPI Read Register Function
int spi_read_register(int handle, uint8_t reg, uint8_t *data, int len) {
    char tx[len + 1];
    char rx[len + 1];
    tx[0] = reg | 0x80; // Set MSB for read operation
    memset(tx + 1, 0x00, len); // Fill with dummy data for reading

    int result = spiXfer(handle, tx, rx, len + 1);
    if (result != len + 1) {
        fprintf(stderr, "SPI Read Error: %d\n", result);
        return -1;
    }

    memcpy(data, rx + 1, len);
    return 0;
}

// SPI Write Register Function
int spi_write_register(int handle, uint8_t reg, uint8_t data) {
    char tx[2];
    char rx[2];
    tx[0] = reg & 0x7F; // Clear MSB for write operation
    tx[1] = data;

    int result = spiXfer(handle, tx, rx, 2);
    if (result != 2) {
        fprintf(stderr, "SPI Write Error: %d\n", result);
        return -1;
    }

    return 0;
}

// ADXL354B Reset Function
int adxl354b_reset(int handle) {
    return spi_write_register(handle, ADXL354B_RESET_REG, ADXL354B_RESET_VALUE);
}

// ADXL354B Power Control Function
int adxl354b_power_control(int handle, uint8_t power_state) {
    return spi_write_register(handle, ADXL354B_POWER_CTL, power_state);
}

// ADXL354B Wait for Stable Function
int adxl354b_wait_for_stable(int handle) {
    uint8_t status;
    int retries = 0;
    while (retries < 100) {
        if (spi_read_register(handle, ADXL354B_STATUS, &status, 1) == 0) {
            if (status & 0x08) { // Check STABLE bit
                return 0;
            }
        }
        gpioDelay(1000); // Wait 1ms
        retries++;
    }
    fprintf(stderr, "Timeout waiting for STABLE bit\n");
    return -1;
}

// ADXL354B Read Acceleration Function
int adxl354b_read_acceleration(int handle, int32_t *x, int32_t *y, int32_t *z) {
    uint8_t x_l, x_h, y_l, y_h, z_l, z_h;
    int retries = 0;

    while (retries < 3) {
        if (spi_read_register(handle, ADXL354B_XDATA_L, &x_l, 1) == 0 &&
            spi_read_register(handle, ADXL354B_XDATA_H, &x_h, 1) == 0 &&
            spi_read_register(handle, ADXL354B_YDATA_L, &y_l, 1) == 0 &&
            spi_read_register(handle, ADXL354B_YDATA_H, &y_h, 1) == 0 &&
            spi_read_register(handle, ADXL354B_ZDATA_L, &z_l, 1) == 0 &&
            spi_read_register(handle, ADXL354B_ZDATA_H, &z_h, 1) == 0) {

            *x = ((int32_t)x_h << 8) | x_l;
            *y = ((int32_t)y_h << 8) | y_l;
            *z = ((int32_t)z_h << 8) | z_l;

            // Sign extend 20-bit values
            if (*x & 0x8000) *x |= 0xFFF00000;
            if (*y & 0x8000) *y |= 0xFFF00000;
            if (*z & 0x8000) *z |= 0xFFF00000;

            return 0;
        } else {
            fprintf(stderr, "Acceleration read retry %d\n", retries + 1);
            retries++;
            gpioDelay(1000); // Wait 1ms before retry
        }
    }

    fprintf(stderr, "Failed to read acceleration data after multiple retries\n");
    return -1;
}

// ADXL354B Verify Part ID Function
int adxl354b_verify_partid(int handle) {
    uint8_t partid;
    if (spi_read_register(handle, ADXL354B_PARTID, &partid, 1) == 0) {
        if (partid == ADXL354B_PARTID_VALUE) {
            return 0;
        } else {
            fprintf(stderr, "Incorrect PARTID: 0x%02X\n", partid);
            return -1;
        }
    } else {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }
}

// Log Data Function
void log_data(FILE *fp, int32_t x, int32_t y, int32_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal Handler Function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // ADXL354B Reset and Power Control
    if (adxl354b_reset(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B reset failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000); // Wait 1ms

    if (adxl354b_power_control(spi_handle, 0x00) != 0) { // Disable measurement
        fprintf(stderr, "ADXL354B power control failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000); // Wait 1ms

    if (adxl354b_wait_for_stable(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B wait for stable failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (adxl354b_power_control(spi_handle, 0x02) != 0) { // Enable measurement
        fprintf(stderr, "ADXL354B power control failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000); // Wait 1ms

    if (adxl354b_verify_partid(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B verify part ID failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int32_t x, y, z;
    while (!terminate) {
        if (adxl354b_read_acceleration(spi_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

