    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // ADXL354B Reset and Power Control
    if (adxl354b_reset(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B reset failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000); // Wait 1ms

    if (adxl354b_power_control(spi_handle, 0x00) != 0) { // Disable measurement
        fprintf(stderr, "ADXL354B power control failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000); // Wait 1ms

    if (adxl354b_wait_for_stable(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B wait for stable failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (adxl354b_power_control(spi_handle, 0x02) != 0) { // Enable measurement
        fprintf(stderr, "ADXL354B power control failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000); // Wait 1ms

    if (adxl354b_verify_partid(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B verify part ID failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int32_t x, y, z;
    while (!terminate) {
        if (adxl354b_read_acceleration(spi_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

