#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16362 Register Addresses
#define ADIS16362_REG_GYRO_XOUT 0x04
#define ADIS16362_REG_GYRO_YOUT 0x06
#define ADIS16362_REG_GYRO_ZOUT 0x08
#define ADIS16362_REG_ACCEL_XOUT 0x0A
#define ADIS16362_REG_ACCEL_YOUT 0x0C
#define ADIS16362_REG_ACCEL_ZOUT 0x0E
#define ADIS16362_REG_SMPL_PRD 0x36
#define ADIS16362_REG_GLOB_CMD 0x68

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Scaling Factors
#define GYRO_SCALE 0.05 // deg/sec/LSB
#define ACCEL_SCALE 0.0025 // g/LSB

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    double timestamp;
    float gyro_x, gyro_y, gyro_z;
    float accel_x, accel_y, accel_z;
} imu_data_t;

// Function Prototypes
int initialize_spi();
int initialize_imu();
int read_imu_data(imu_data_t *data);
void log_data(imu_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to initialize the IMU
int initialize_imu() {
    // Reset the device
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = ADIS16362_REG_GLOB_CMD | 0x80; // Write command
    tx_buf[1] = 0x04; // Reset command

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error resetting IMU\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Set sample period (adjust as needed)
    tx_buf[0] = ADIS16362_REG_SMPL_PRD | 0x80; // Write command
    tx_buf[1] = 0x01; // Sample period = 1 (adjust as needed)

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error setting sample period\n");
        return -1;
    }

    return 0;
}

// Function to read IMU data
int read_imu_data(imu_data_t *data) {
    char tx_buf[2];
    char rx_buf[4];
    int16_t raw_data[6];

    // Read Gyro X
    tx_buf[0] = ADIS16362_REG_GYRO_XOUT | 0x80; // Read command
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 4) != 0) {
        fprintf(stderr, "Error reading Gyro X\n");
        return -1;
    }
    raw_data[0] = (rx_buf[0] << 8) | rx_buf[1];

    // Read Gyro Y
    tx_buf[0] = ADIS16362_REG_GYRO_YOUT | 0x80; // Read command
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 4) != 0) {
        fprintf(stderr, "Error reading Gyro Y\n");
        return -1;
    }
    raw_data[1] = (rx_buf[0] << 8) | rx_buf[1];

    // Read Gyro Z
    tx_buf[0] = ADIS16362_REG_GYRO_ZOUT | 0x80; // Read command
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 4) != 0) {
        fprintf(stderr, "Error reading Gyro Z\n");
        return -1;
    }
    raw_data[2] = (rx_buf[0] << 8) | rx_buf[1];

    // Read Accel X
    tx_buf[0] = ADIS16362_REG_ACCEL_XOUT | 0x80; // Read command
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 4) != 0) {
        fprintf(stderr, "Error reading Accel X\n");
        return -1;
    }
    raw_data[3] = (rx_buf[0] << 8) | rx_buf[1];

    // Read Accel Y
    tx_buf[0] = ADIS16362_REG_ACCEL_YOUT | 0x80; // Read command
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 4) != 0) {
        fprintf(stderr, "Error reading Accel Y\n");
        return -1;
    }
    raw_data[4] = (rx_buf[0] << 8) | rx_buf[1];

    // Read Accel Z
    tx_buf[0] = ADIS16362_REG_ACCEL_ZOUT | 0x80; // Read command
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 4) != 0) {
        fprintf(stderr, "Error reading Accel Z\n");
        return -1;
    }
    raw_data[5] = (rx_buf[0] << 8) | rx_buf[1];

    // Convert to physical units
    data->gyro_x = (float)raw_data[0] * GYRO_SCALE;
    data->gyro_y = (float)raw_data[1] * GYRO_SCALE;
    data->gyro_z = (float)raw_data[2] * GYRO_SCALE;
    data->accel_x = (float)raw_data[3] * ACCEL_SCALE;
    data->accel_y = (float)raw_data[4] * ACCEL_SCALE;
    data->accel_z = (float)raw_data[5] * ACCEL_SCALE;

    return 0;
}

// Function to log data to CSV file
void log_data(imu_data_t data) {
    fprintf(log_file, "%.9f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            data.timestamp, data.gyro_x, data.gyro_y, data.gyro_z,
            data.accel_x, data.accel_y, data.accel_z);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Initialize IMU
    if (initialize_imu() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    // Main loop
    imu_data_t imu_data;
    struct timespec ts;

    while (!terminate) {
        // Read IMU data
        if (read_imu_data(&imu_data) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                imu_data.timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

                // Log data
                log_data(imu_data);
            } else {
                fprintf(stderr, "Error getting timestamp\n");
            }
        } else {
            fprintf(stderr, "Error reading IMU data, retrying...\n");
        }

        // Delay
        gpioDelay(10); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

