#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_PIN 17
#define GPIO_CHIP 4

static volatile int keepRunning = 1;

void intHandler(int dummy) {
    keepRunning = 0;
}

int main() {
    int handle;
    int value;
    time_t rawtime;
    struct tm * timeinfo;
    char timestamp[80];

    // Register signal handler for Ctrl+C
    signal(SIGINT, intHandler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO chip
    handle = gpioOpen(GPIO_CHIP, 0, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %d\n", handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as input
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    printf("Self-parking sequence started\n");

    // Main loop
    while (keepRunning) {
        // Read GPIO value
        value = gpioRead(handle);

        if (value == 0) {
            // Get current time
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            // Format timestamp
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log message
            printf("%s - Obstacle detected! Self-parking sequence completed\n", timestamp);
            break; // Exit loop after first detection
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close GPIO chip
    gpioClose(handle);

    // Terminate pigpio library
    gpioTerminate();

    printf("Self-parking sequence completed\n");

    return 0;
}

