#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int handle;
    int sensor1_value, sensor2_value;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Main loop
    while (!terminate) {
        // Read sensor values
        sensor1_value = gpioRead(SENSOR1_GPIO);
        sensor2_value = gpioRead(SENSOR2_GPIO);

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log sensor status
        printf("%s - Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1_value, sensor2_value);

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

