#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM6DSR I2C address (SA0 low)
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to write a byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value)
{
    int result = i2cWriteByteData(handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int read_register(int handle, uint8_t reg, uint8_t *value)
{
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to initialize the LSM6DSR
int init_lsm6dsr(int handle)
{
    // Check WHO_AM_I register
    uint8_t who_am_i;
    if (read_register(handle, 0x0F, &who_am_i) != 0) {
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: ±2g, 104 Hz
    if (write_register(handle, CTRL1_XL, 0x60) != 0) {
        return -1;
    }

    // Configure gyroscope: ±250 dps, 104 Hz
    if (write_register(handle, CTRL2_G, 0x60) != 0) {
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_data(int handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z)
{
    uint8_t buffer[12];

    // Read accelerometer and gyroscope data in one burst
    if (i2cReadI2CBlockData(handle, OUTX_L_XL, (char *)buffer, 12) != 12) {
        fprintf(stderr, "Error reading data block\n");
        return -1;
    }

    // Combine low and high bytes for accelerometer
    *accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Combine low and high bytes for gyroscope
    *gyro_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    *gyro_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    *gyro_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr(i2c_handle) != 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    while (!terminate) {
        // Read data
        if (read_data(i2c_handle, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Print data
            printf("%d,%d,%d,%d,%d,%d\n", accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Error reading data, exiting\n");
            break;
        }

        // Sleep for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

