// FXOS8700 I2C address
#define FXOS8700_ADDR 0x1F

// FXOS8700 register addresses
#define FXOS8700_REG_STATUS 0x00
#define FXOS8700_REG_OUT_X_MSB 0x01
#define FXOS8700_REG_OUT_X_LSB 0x02
#define FXOS8700_REG_OUT_Y_MSB 0x03
#define FXOS8700_REG_OUT_Y_LSB 0x04
#define FXOS8700_REG_OUT_Z_MSB 0x05
#define FXOS8700_REG_OUT_Z_LSB 0x06
#define FXOS8700_REG_M_OUT_X_MSB 0x33
#define FXOS8700_REG_M_OUT_X_LSB 0x34
#define FXOS8700_REG_M_OUT_Y_MSB 0x35
#define FXOS8700_REG_M_OUT_Y_LSB 0x36
#define FXOS8700_REG_M_OUT_Z_MSB 0x37
#define FXOS8700_REG_M_OUT_Z_LSB 0x38
#define FXOS8700_REG_WHO_AM_I 0x0D
#define FXOS8700_REG_CTRL_REG1 0x2A

// Expected WHO_AM_I value
#define FXOS8700_WHO_AM_I_VALUE 0xC7

// Global I2C handle
int i2c_handle;

// Signal handler function
void signal_handler(int signal)
{
    printf("Received signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a register with retry
int read_register(int handle, int reg, char *buf, int count)
{
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cReadI2CBlockData(handle, reg, buf, count);
        if (result == count) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X, count %d): %d\n", reg, count, result);
            gpioDelay(10); // Wait before retrying
            retries--;
        }
    }
    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to write a register with retry
int write_register(int handle, int reg, char *buf, int count)
{
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cWriteI2CBlockData(handle, reg, buf, count);
        if (result == count) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, count %d): %d\n", reg, count, result);
            gpioDelay(10); // Wait before retrying
            retries--;
        }
    }
    fprintf(stderr, "Failed to write register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    char who_am_i;
    if (read_register(i2c_handle, FXOS8700_REG_WHO_AM_I, &who_am_i, 1) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (who_am_i != FXOS8700_WHO_AM_I_VALUE) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X (expected 0x%02X)\n", who_am_i, FXOS8700_WHO_AM_I_VALUE);
        i2cClose(i2c_handle);
