#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5000 // 5 seconds * 1000 ms/second
#define SAMPLE_INTERVAL 1 // milliseconds

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    int threshold;
    if (sscanf(argv[1], "%d", &threshold) != 1 || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value. Must be a positive integer.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int high_count;
    int window_count = 0;
    int current_state;
    int previous_state = gpioRead(GPIO_PIN);
    time_t start_time, current_time;
    struct tm *timeinfo;
    char timestamp[20];

    while (program_running) {
        high_count = 0;
        start_time = time(NULL);
        window_count++;

        while (time(NULL) - start_time < 5 && program_running) {
            current_state = gpioRead(GPIO_PIN);
            if (current_state == PI_HIGH) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL * 1000); // Convert ms to microseconds
        }

        time(&current_time);
        timeinfo = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (high_count > threshold) {
            printf("%s ALERT: High readings = %d\n", timestamp, high_count);
        } else {
            printf("%s Status: High readings = %d\n", timestamp, high_count);
        }

        gpioDelay(1000); // Pause for 1 second
    }

    gpioTerminate();
    return 0;
}

