#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define DOOR_A_PIN 17
#define DOOR_B_PIN 27

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define lock duration (seconds)
#define LOCK_DURATION 5

// Define security code range
#define MIN_CODE 100000
#define MAX_CODE 999999

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *door_a_line = NULL;
static struct gpiod_line *door_b_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio(void);
int generate_security_code(void);
int unlock_door(int door);
int lock_door(int door);
int log_access(int code);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up...\n");

    // Lock both doors
    lock_door(0); // Door A
    lock_door(1); // Door B

    // Release GPIO resources
    if (door_a_line) {
        gpiod_line_release(door_a_line);
    }
    if (door_b_line) {
        gpiod_line_release(door_b_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete.\n");
}

// Initialize GPIO pins
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    // Get GPIO lines
    door_a_line = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!door_a_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup_chip;
    }

    door_b_line = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!door_b_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup_line_a;
    }

    // Request GPIO lines as outputs
    ret = gpiod_line_request_output(door_a_line, "door_access", 0); // Initial state: LOW
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup_line_b;
    }

