#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MAX_LUX 65535.0
#define LOG_FILE "light_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_lux(float *lux);
int log_data(float lux);
void cleanup();
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int bh1750_address;
    int measurement_mode;
} config_t;

config_t config = {I2C_BUS, BH1750_ADDR, CONTINUOUS_HIGH_RES_MODE};

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    float lux;
    while (!terminate) {
        if (read_lux(&lux) == 0) {
            if (log_data(lux) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        gpioSleep(PI_TIME_RELATIVE, 5, 0); // Sleep for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.bh1750_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return 1;
    }

    // Set continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, config.measurement_mode) < 0) {
        fprintf(stderr, "Failed to set measurement mode\n");
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read lux value from sensor
int read_lux(float *lux) {
    int raw_value;

    // Read two bytes from the sensor
    raw_value = i2cReadWordData(i2c_handle, 0x00);
    if (raw_value < 0) {
        fprintf(stderr, "Failed to read data from sensor\n");
        return 1;
    }

    // Convert to lux
    *lux = (float)raw_value / MAX_LUX;

    return 0;
}

// Log data to file
int log_data(float lux) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open file in append mode
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Write data to file
    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);

    // Close file
    fclose(fp);

    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");
    terminate = 1;
}

