#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define GPIO_PIN 18
#define PWM_FREQUENCY 440
#define PWM_DUTYCYCLE 128
#define PORT 12345
#define SAMPLE_INTERVAL_MS 20
#define PLAYBACK_DURATION_S 5
#define MOTION_DETECTED_COMMAND "MOTION_DETECTED:MySecretKey"
#define MOTION_DETECTED_COMMAND_LENGTH 28
#define LOG_FILE "frequency_log.txt"

// Global variables
int i2c_handle;
int socket_fd;
FILE *log_file;

// Function prototypes
int initialize_mpr121();
int read_touch_data(int *touch_data);
int calculate_frequency(int touch_data);
int play_tone(int frequency);
int log_frequency(int frequency);
int handle_tcp_connection(int client_socket);
void signal_handler(int signal);

// MPR121 Register Addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

// Function to initialize the MPR121
int initialize_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x00) < 0) {
        perror("Error: Failed to reset MPR121");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Configure electrode sensitivity and release thresholds
    // Example configuration (adjust as needed)
    if (i2cWriteByteData(i2c_handle, 0x41, 0x30) < 0) { // Touch threshold
        perror("Error: Failed to set touch threshold");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x42, 0x10) < 0) { // Release threshold
        perror("Error: Failed to set release threshold");
        return -1;
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x8F) < 0) { // Enable all electrodes
        perror("Error: Failed to enable electrodes");
        return -1;
    }

    return 0;
}

// Function to read touch data from the MPR121
int read_touch_data(int *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        perror("Error: Failed to read touch data");
        return -1;
    }

    *touch_data = ((int)buf[1] << 8) | (int)buf[0];
    return 0;
}

// Function to calculate the frequency based on touch data
int calculate_frequency(int touch_data) {
    // Simple mapping: touch_data -> frequency
    // Adjust the mapping as needed for your specific application
    int frequency = 440 + (touch_data % 100) * 10; // Example mapping
    return frequency;
}

// Function to play a tone using PWM
int play_tone(int frequency) {
    gpioSetPWMfrequency(GPIO_PIN, frequency);
    gpioPWM(GPIO_PIN, PWM_DUTYCYCLE);
    return 0;
}

// Function to log the played frequency to a file
int log_frequency(int frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: Frequency = %d Hz\n", timestamp, frequency);
    fflush(log_file); // Ensure data is written to the file immediately
    return 0;
}

// Function to handle a TCP connection
int handle_tcp_connection(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received;

    bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("Error: Failed to receive data");
        close(client_socket);
        return -1;
    }
    buffer[bytes_received] = '\0';

    printf("Received: %s\n", buffer);

    if (strncmp(buffer, MOTION_DETECTED_COMMAND, MOTION_DETECTED_COMMAND_LENGTH) == 0) {
        printf("Motion detected! Playing tone...\n");

        // Play the tone
        for (int i = 0; i < PLAYBACK_DURATION_S * 1000 / SAMPLE_INTERVAL_MS; ++i) {
            int touch_data;
            if (read_touch_data(&touch_data) == 0) {
                int frequency = calculate_frequency(touch_data);
                play_tone(frequency);
                log_frequency(frequency);
            } else {
                fprintf(stderr, "Error reading touch data during playback.\n");
                break; // Exit loop on error
            }
