    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, MAG_DATA_REG, buffer, 6);
    if (result != 6) {
        log_error("Failed to read magnetometer data");
        return -1;
    }

    // Combine MSB and LSB, convert to signed 16-bit integers
    int16_t x_raw = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t y_raw = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t z_raw = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to microteslas (µT) - adjust scale factor as needed
    *x = (float)x_raw * 0.001; // Example scale factor
    *y = (float)y_raw * 0.001;
    *z = (float)z_raw * 0.001;

    return 0;
}

// Set LED brightness using PWM
void set_led_brightness(float z_magnitude) {
    // Normalize Z magnitude to a range of 0-255
    int brightness = (int)((fabs(z_magnitude) / 1000.0) * 255.0); // Assuming max Z magnitude is 1000 uT
    if (brightness > 255) brightness = 255;
    if (brightness < 0) brightness = 0;

    gpioPWM(LED_GPIO, brightness);
}

