#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// I2C bus
#define I2C_BUS 1

// Number of samples for offset calculation
#define NUM_SAMPLES 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Structure to hold magnetometer offsets
typedef struct {
    float x_offset;
    float y_offset;
    float z_offset;
} magnetometer_offsets_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the HMC5883L
int init_hmc5883l() {
    // Configure register A: 8-average, 15 Hz, normal measurement
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Configure register B: Gain = 1.3 Ga
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0xA0) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Set continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Function to read raw magnetometer data
int read_magnetometer_data(magnetometer_data_t *data) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to calculate hard-iron offsets
void calculate_offsets(magnetometer_data_t *samples, int num_samples, magnetometer_offsets_t *offsets) {
    float x_sum = 0, y_sum = 0, z_sum = 0;

    for (int i = 0; i < num_samples; i++) {
        x_sum += samples[i].x;
        y_sum += samples[i].y;
        z_sum += samples[i].z;
    }

    offsets->x_offset = x_sum / num_samples;
    offsets->y_offset = y_sum / num_samples;
    offsets->z_offset = z_sum / num_samples;
}

// Function to apply hard-iron offsets
void apply_offsets(magnetometer_data_t raw_data, magnetometer_offsets_t offsets, magnetometer_data_t *corrected_data) {
    corrected_data->x = raw_data.x - offsets.x_offset;
    corrected_data->y = raw_data.y - offsets.y_offset;
    corrected_data->z = raw_data.z - offsets.z_offset;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
