#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define LSM303D_CTRL_REG1_A 0x20
#define LSM303D_CTRL_REG4_A 0x23
#define LSM303D_OUT_X_L_A 0x28
#define LSM303D_OUT_X_H_A 0x29
#define LSM303D_OUT_Y_L_A 0x2A
#define LSM303D_OUT_Y_H_A 0x2B
#define LSM303D_OUT_Z_L_A 0x2C
#define LSM303D_OUT_Z_H_A 0x2D
#define LSM303D_INT1_CFG 0x30
#define LSM303D_INT1_THS 0x32
#define LSM303D_INT1_DURATION 0x33

// GPIO pin for interrupt
#define GPIO_PIN 23

// Circular buffer size
#define BUFFER_SIZE 64

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Global variables
static int i2c_fd = -1;
static struct gpiod_line *gpio_line = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static accelerometer_data_t buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int read_accelerometer_data(int fd, accelerometer_data_t *data);
void dump_buffer(void);
void signal_handler(int sig);
int setup_gpio(void);
void cleanup_gpio(void);

// I2C read function with error handling and retry
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }

    return 0;
}

// I2C write function with error handling and retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int fd, accelerometer_data_t *data) {
    uint8_t x_l, x_h, y_l, y_h, z_l, z_h;

    if (i2c_read_reg(fd, LSM303D_OUT_X_L_A, &x_l) != 0) return -1;
    if (i2c_read_reg(fd, LSM303D_OUT_X_H_A, &x_h) != 0) return -1;
    if (i2c_read_reg(fd, LSM303D_OUT_Y_L_A, &y_l) != 0) return -1;
    if (i2c_read_reg(fd, LSM303D_OUT_Y_H_A, &y_h) != 0) return -1;
    if (i2c_read_reg(fd, LSM303D_OUT_Z_L_A, &z_l) != 0) return -1;
    if (i2c_read_reg(fd, LSM303D_OUT_Z_H_A, &z_h) != 0) return -1;

    data->x = (int16_t)((x_h << 8) | x_l);
    data->y = (int16_t)((y_h << 8) | y_l);
    data->z = (int16_t)((z_h << 8) | z_l);

    return 0;
}

// Function to dump the circular buffer
void dump_buffer(void) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s: ", timestamp);
    for (int i = 0; i < 10; i++) {
        int index = (buffer_index - 10 + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("X: %6d, Y: %6d, Z: %6d  ", buffer[index].x, buffer[index].y, buffer[index].z);
    }
    printf("\n");
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("Caught signal %d, exiting...\n", sig);
}

// Setup GPIO for interrupt
int setup_gpio(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("gpiod_chip_open_by_name failed");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("gpiod_chip_get_line failed");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request(gpio_line, "lsm303d_mon", GPIOD_LINE_REQUEST_DIRECTION_FALLING_EDGE) < 0) {
        perror("gpiod_line_request failed");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO
void cleanup_gpio(void) {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify device identity
    uint8_t device_id;
    if (i2c_read_reg(i2c_fd, 0x0F, &device_id) != 0) {
        fprintf(stderr, "Failed to read device ID\n");
        close(i2c_fd);
        return 1;
    }

    if (device_id != 0x49) {
        fprintf(stderr, "Incorrect device ID: 0x%02x\n", device_id);
        close(i2c_fd);
        return 1;
    }

    // Initialize accelerometer
    if (i2c_write_reg(i2c_fd, LSM303D_CTRL_REG1_A, 0x27) != 0) { // Enable all axes, 50Hz
        fprintf(stderr, "Failed to write to CTRL_REG1_A\n");
        close(i2c_fd);
        return 1;
    }

    if (i2c_write_reg(i2c_fd, LSM303D_CTRL_REG4_A, 0x00) != 0) { // +/- 2g range
        fprintf(stderr, "Failed to write to CTRL_REG4_A\n");
        close(i2c_fd);
        return 1;
    }

    // Configure interrupt
    if (i2c_write_reg(i2c_fd, LSM303D_INT1_CFG, 0x24) != 0) { // Enable interrupt on INT1 pin
        fprintf(stderr, "Failed to write to INT1_CFG\n");
        close(i2c_fd);
        return 1;
    }

    if (i2c_write_reg(i2c_fd, LSM303D_INT1_THS, 0x7D) != 0) { // Threshold of 2000 mg
        fprintf(stderr, "Failed to write to INT1_THS\n");
        close(i2c_fd);
        return 1;
    }

    if (i2c_write_reg(i2c_fd, LSM303D_INT1_DURATION, 0x00) != 0) { // Duration of 0 ms
        fprintf(stderr, "Failed to write to INT1_DURATION\n");
        close(i2c_fd);
        return 1;
    }

    // Setup GPIO for interrupt
    if (setup_gpio() != 0) {
        fprintf(stderr, "Failed to setup GPIO\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        accelerometer_data_t data;

        if (read_accelerometer_data(i2c_fd, &data) == 0) {
            buffer[buffer_index] = data;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            struct gpiod_line_event event;
            int ret = gpiod_line_event_wait(gpio_line, NULL);
            if (ret > 0) {
                if (gpiod_line_event_read(gpio_line, &event) == 0) {
                    dump_buffer();
                }
            } else if (ret < 0) {
                perror("gpiod_line_event_wait failed");
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data, skipping sample\n");
        }

        usleep(10000); // 10 ms
    }

    // Disable accelerometer
    i2c_write_reg(i2c_fd, LSM303D_CTRL_REG1_A, 0x00);

    // Cleanup
    close(i2c_fd);
    cleanup_gpio();

    return 0;
}

