#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define UART0 "/dev/serial0"
#define UART1 "/dev/serial1"
#define RELAY1_GPIO 17
#define RELAY2_GPIO 27
#define EXPECTED_CODE "123456"
#define LOCK_DURATION_MS 2000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "Signal received, terminating...\n");
}

int initialize_uart(const char *device, int baud_rate, int *fd) {
    *fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (*fd == -1) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(*fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes for %s: %s\n", device, strerror(errno));
        close(*fd);
        return -1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN]  = 0;            // read doesn't block
    tty.c_cc[VTIME] = 5;            // 0.5 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (cfsetospeed(&tty, baud_rate) != 0 || cfsetispeed(&tty, baud_rate) != 0) {
        fprintf(stderr, "Error setting baud rate for %s: %s\n", device, strerror(errno));
        close(*fd);
        return -1;
    }

    if (tcsetattr(*fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes for %s: %s\n", device, strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

int read_code(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0; // Timeout or no data
        } else {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        }
    } else if (bytes_read > 0) {
        buffer[bytes_read] = '\0';
        // Validate input (digits only)
        for (size_t i = 0; i < bytes_read; ++i) {
            if (!isdigit(buffer[i])) {
                buffer[0] = '\0'; // Clear buffer on invalid input
                return 0; // Reset buffer
            }
        }
        return bytes_read;
    } else {
        return 0; // Timeout or no data
    }
}

int compare_codes(const char *code1, const char *code2) {
    if (strlen(code1) != 6 || strlen(code2) != 6) {
        return 0; // Codes must be 6 digits
    }

    for (size_t i = 0; i < 6; ++i) {
        if (code1[i] != code2[i]) {
            return 0; // Codes do not match
        }
    }

    return 1; // Codes match
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int uart0_fd, uart1_fd;
    if (initialize_uart(UART0, 9600, &uart0_fd) != 0) {
        gpioTerminate();
        return 1;
    }
    if (initialize_uart(UART1, 9600, &uart1_fd) != 0) {
        close(uart0_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioWrite(RELAY1_GPIO, 0); // Initialize LOW
    gpioWrite(RELAY2_GPIO, 0); // Initialize LOW

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char code0_buffer[7] = {0}; // 6 digits + null terminator
    char code1_buffer[7] = {0};

    while (!terminate) {
        int code0_len = read_code(uart0_fd, code0_buffer, sizeof(code0_buffer));
        int code1_len = read_code(uart1_fd, code1_buffer, sizeof(code1_buffer));

        if (code0_len > 0) {
            printf("UART0: %s\n", code0_buffer);
        }
        if (code1_len > 0) {
            printf("UART1: %s\n", code1_buffer);
        }

        if (code0_len > 0 && code1_len > 0) {
            if (compare_codes(code0_buffer, code1_buffer) && compare_codes(code0_buffer, EXPECTED_CODE)) {
                printf("Codes match, unlocking door!\n");
                gpioWrite(RELAY1_GPIO, 1);
                gpioWrite(RELAY2_GPIO, 1);
                gpioDelay(LOCK_DURATION_MS);
                gpioWrite(RELAY1_GPIO, 0);
                gpioWrite(RELAY2_GPIO, 0);
                // Reset buffers after successful unlock
                code0_buffer[0] = '\0';
                code1_buffer[0] = '\0';
            } else {
                fprintf(stderr, "Codes do not match or are incorrect.\n");
            }
        }

        gpioDelay(100); // Small delay to prevent busy-waiting
    }

    // Cleanup
    close(uart0_fd);
    close(uart1_fd);
    gpioWrite(RELAY1_GPIO, 0);
    gpioWrite(RELAY2_GPIO, 0);
    gpioTerminate();

    return 0;
}

