#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ON_TIME 1 // seconds
#define PIR_TIMEOUT 10 // seconds

// Global variables
static volatile int running = 1;
static volatile int pir_timeout_count = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void control_relay(int on);
void log_event(int level, const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    log_event(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        log_event(LOG_ERR, "Failed to set PIR pin as input");
        cleanup();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        log_event(LOG_ERR, "Failed to set relay pin as output");
        cleanup();
        return 1;
    }

    gpioWrite(RELAY_PIN, 0); // Ensure relay is off initially

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Control relay (on/off)
void control_relay(int on) {
    gpioWrite(RELAY_PIN, on);
    char message[50];
    snprintf(message, sizeof(message), "Relay %s", on ? "ON" : "OFF");
    log_event(LOG_INFO, message);
}

// Log event to syslog
void log_event(int level, const char *message) {
    syslog(level, message);
}

// Cleanup function
void cleanup() {
    log_event(LOG_INFO, "Cleaning up...");
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioSetMode(PIR_PIN, PI_INPUT); // Set PIR pin to input
    gpioSetMode(RELAY_PIN, PI_INPUT); // Set relay pin to input
    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    // Open syslog
    openlog("pir_relay", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    log_event(LOG_INFO, "PIR sensor relay control started");

    // Main loop
    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            log_event(LOG_INFO, "Motion detected!");
            control_relay(1); // Activate relay
            sleep(RELAY_ON_TIME);
            control_relay(0); // Deactivate relay
            pir_timeout_count = 0; // Reset timeout counter
        } else {
            pir_timeout_count++;
            if (pir_timeout_count > PIR_TIMEOUT) {
                log_event(LOG_WARNING, "PIR signal timeout, triggering failsafe!");
                control_relay(0); // Deactivate relay
                log_event(LOG_WARNING, "System shutdown initiated.");
                system("sudo shutdown -h now");
                running = 0; // Exit the loop
            }
        }

        gpioDelay(50000); // 50ms delay
    }

    cleanup();

    return 0;
}

