#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/time.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_PWR_MGMT_1 0x6B

// Circular buffer size
#define BUFFER_SIZE 100

// Data structure for accelerometer readings
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} AccelData;

// Global variables
int i2c_fd = -1;
AccelData buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;
int running = 1;

// Function prototypes
int init_i2c();
int read_accel_data(AccelData *data);
void store_data(AccelData data);
int read_latest_data(AccelData *data);
void signal_handler(int sig);
void cleanup();

// Initialize I2C
int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Wake up the MPU6050
    uint8_t wake_up_data[2] = {MPU6050_PWR_MGMT_1, 0x00};
    if (write(i2c_fd, wake_up_data, 2) != 2) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accel_data(AccelData *data) {
    uint8_t reg = MPU6050_ACCEL_XOUT_H;
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    uint8_t buffer[6];
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading from I2C device");
        return -1;
    }

    data->x = (buffer[0] << 8) | buffer[1];
    data->y = (buffer[2] << 8) | buffer[3];
    data->z = (buffer[4] << 8) | buffer[5];

    return 0;
}

// Store data in circular buffer
void store_data(AccelData data) {
    buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Read latest data from circular buffer
int read_latest_data(AccelData *data) {
    if (buffer_count == 0) {
        return -1; // Buffer is empty
    }

    int index = (buffer_index - 1 + BUFFER_SIZE) % BUFFER_SIZE;
    *data = buffer[index];
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("Received signal %d, shutting down...\n", sig);
}

// Cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    printf("Cleanup complete.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Create /sys/kernel/mpu6050_accel/latest file
    int fd = open("/sys/kernel/mpu6050_accel/latest", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("Error creating /sys/kernel/mpu6050_accel/latest");
        cleanup();
        return 1;
    }
    close(fd);

    // Configure POSIX timer
    struct sigevent sev;
    struct itimerspec its;

    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGALRM;
    sev.sigev_value.sival_ptr = &timer_id;

    if (timer_create(CLOCK_REALTIME, &sev, &timer_id) == -1) {
        perror("timer_create");
        cleanup();
        return 1;
    }

    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 10000000; // 10 ms
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 10000000; // 10 ms

    if (timer_settime(timer_id, 0, &its, NULL) == -1) {
        perror("timer_settime");
        cleanup();
        return 1;
    }

    printf("MPU6050 data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        pause(); // Wait for signal

        if (!running) break;

        AccelData data;
        if (read_accel_data(&data) == 0) {
            store_data(data);

            // Write data to /sys/kernel/mpu6050_accel/latest
            char buffer[50];
            snprintf(buffer, sizeof(buffer), "%d,%d,%d\n", data.x, data.y, data.z);
            fd = open("/sys/kernel/mpu6050_accel/latest", O_WRONLY | O_CREAT | O_TRUNC, 0644);
            if (fd >= 0) {
                write(fd, buffer, strlen(buffer));
                close(fd);
            } else {
                perror("Error writing to /sys/kernel/mpu6050_accel/latest");
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data.\n");
        }
    }

    // Cleanup and exit
    timer_delete(timer_id);
    cleanup();
    return 0;
}

