#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for relays
#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define prime numbers for intervals
#define PRIME1 2
#define PRIME2 3
#define PRIME3 5
#define PRIME4 7

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a relay
int set_relay_state(int pin, int state) {
    int result = gpioWrite(pin, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", pin, result);
        return -1;
    }
    return 0;
}

// Function to toggle a relay state
int toggle_relay(int pin) {
    int current_state = gpioRead(pin);
    int new_state = !current_state;
    return set_relay_state(pin, new_state);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set initial relay states to OFF
    set_relay_state(RELAY1_PIN, 0);
    set_relay_state(RELAY2_PIN, 0);
    set_relay_state(RELAY3_PIN, 0);
    set_relay_state(RELAY4_PIN, 0);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Toggle relays with prime-numbered intervals
        if (toggle_relay(RELAY1_PIN) != 0) terminate = 1;
        if (toggle_relay(RELAY2_PIN) != 0) terminate = 1;
        if (toggle_relay(RELAY3_PIN) != 0) terminate = 1;
        if (toggle_relay(RELAY4_PIN) != 0) terminate = 1;

        // Wait for the specified interval
        struct timespec req, rem;
        req.tv_sec = 0;
        req.tv_nsec = PRIME1 * 1000000000L; // Convert seconds to nanoseconds
        nanosleep(&req, &rem);

        req.tv_sec = 0;
        req.tv_nsec = PRIME2 * 1000000000L; // Convert seconds to nanoseconds
        nanosleep(&req, &rem);

        req.tv_sec = 0;
        req.tv_nsec = PRIME3 * 1000000000L; // Convert seconds to nanoseconds
        nanosleep(&req, &rem);

        req.tv_sec = 0;
        req.tv_nsec = PRIME4 * 1000000000L; // Convert seconds to nanoseconds
        nanosleep(&req, &rem);
    }

    // Turn off all relays before exiting
    set_relay_state(RELAY1_PIN, 0);
    set_relay_state(RELAY2_PIN, 0);
    set_relay_state(RELAY3_PIN, 0);
    set_relay_state(RELAY4_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

