    int current_state = gpioRead(pin);
    int new_state = !current_state;
    return set_relay_state(pin, new_state);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set initial relay states to OFF
    set_relay_state(RELAY1_PIN, 0);
    set_relay_state(RELAY2_PIN, 0);
    set_relay_state(RELAY3_PIN, 0);
    set_relay_state(RELAY4_PIN, 0);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Toggle relays with prime-numbered intervals
        if (toggle_relay(RELAY1_PIN) != 0) terminate = 1;
        if (toggle_relay(RELAY2_PIN) != 0) terminate = 1;
        if (toggle_relay(RELAY3_PIN) != 0) terminate = 1;
        if (toggle_relay(RELAY4_PIN) != 0) terminate = 1;

        // Wait for the specified interval
        struct timespec req, rem;
        req.tv_sec = 0;
        req.tv_nsec = PRIME1 * 1000000000L; // Convert seconds to nanoseconds
        nanosleep(&req, &rem);

        req.tv_sec = 0;
        req.tv_nsec = PRIME2 * 1000000000L; // Convert seconds to nanoseconds
        nanosleep(&req, &rem);

        req.tv_sec = 0;
        req.tv_nsec = PRIME3 * 1000000000L; // Convert seconds to nanoseconds
        nanosleep(&req, &rem);

        req.tv_sec = 0;
        req.tv_nsec = PRIME4 * 1000000000L; // Convert seconds to nanoseconds
        nanosleep(&req, &rem);
    }

    // Turn off all relays before exiting
    set_relay_state(RELAY1_PIN, 0);
    set_relay_state(RELAY2_PIN, 0);
    set_relay_state(RELAY3_PIN, 0);
    set_relay_state(RELAY4_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

