            // Debounce mechanism
            if (current_time - last_trigger_time > DEBOUNCE_TIME * 1000) {
                printf("Sound detected!\n");
                if (activate_relay() == 0) {
                    if (log_event() == 0) {
                        printf("Relay activated and event logged.\n");
                    } else {
                        fprintf(stderr, "Error logging event!\n");
                    }
                } else {
                    fprintf(stderr, "Error activating relay!\n");
                }
                last_trigger_time = current_time;
            }
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(RELAY_PIN, 0); // Turn off relay
    gpioTerminate(); // Terminate pigpio

    return 0;
}

