#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Sensitivity scale factor (LSB/degree/sec)
#define GYRO_SCALE 131.0

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C handle
int i2c_handle;

// Function prototypes
int init_mpu6050();
gyro_data_t read_gyro_data();
float calculate_magnitude(gyro_data_t data);
void handle_threshold_exceeded(float magnitude);
void signal_handler(int signal);

// Callback function pointer type
typedef void (*callback_t)(float);

// Global callback function pointer
callback_t callback = NULL;

// Function to initialize the MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (set sleep bit to 0)
    char data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00;

    if (i2cWriteDevice(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050. %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read gyroscope data from the MPU-6050
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buffer[6];

    // Read all six gyroscope registers in one go
    if (i2cReadDevice(i2c_handle, buffer, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data. %s\n", strerror(errno));
        data.x = 0.0; // Set to 0 to avoid using uninitialized values
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes, convert to signed 16-bit integers
    int16_t gyro_x = (buffer[0] << 8) | buffer[1];
    int16_t gyro_y = (buffer[2] << 8) | buffer[3];
    int16_t gyro_z = (buffer[4] << 8) | buffer[5];

    // Convert to degrees per second
    data.x = (float)gyro_x / GYRO_SCALE;
    data.y = (float)gyro_y / GYRO_SCALE;
    data.z = (float)gyro_z / GYRO_SCALE;

    return data;
}

// Function to calculate the magnitude of the angular velocity vector
float calculate_magnitude(gyro_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Function to handle threshold exceeded
void handle_threshold_exceeded(float magnitude) {
    if (callback != NULL) {
        callback(magnitude);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Register callback function
    callback = handle_threshold_exceeded;

    printf("MPU-6050 data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read gyroscope data
        gyro_data_t gyro_data = read_gyro_data();

        // Store data in circular buffer
        gyro_buffer[buffer_index] = gyro_data;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Calculate magnitude
        float magnitude = calculate_magnitude(gyro_data);

        // Check if threshold exceeded
        if (magnitude > 50.0) {
            handle_threshold_exceeded(magnitude);
        }

        // Delay for a short period
        gpioDelay(10); // 10 ms delay
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

