#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <sys/select.h>
#include <sys/time.h>

// Define UART device and baud rate
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B9600

// Define log file names
#define CO2_LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"

// Define command and response lengths
#define COMMAND_LENGTH 9
#define RESPONSE_LENGTH 9

// Define retry parameters
#define MAX_RETRIES 5
#define RETRY_DELAY_MS 10

// Define timeout parameters
#define MAX_TIMEOUT_MS 1000

// Define sampling interval
#define SAMPLE_INTERVAL_S 5

// Define CO2 ppm range
#define MIN_CO2_PPM 0
#define MAX_CO2_PPM 5000

// Define error codes
#define ERROR_NONE 0
#define ERROR_CHECKSUM 1
#define ERROR_TIMEOUT 2
#define ERROR_UART 3

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *co2_log_fp = NULL;
FILE *error_log_fp = NULL;

// Structure to hold sensor data
typedef struct {
    long tv_sec;
    long tv_nsec;
    int ppm;
    int error;
} sensor_data_t;

// Function prototypes
int init_uart(const char *device, speed_t baud_rate);
int send_command(int fd, const unsigned char *command, int command_length);
int receive_response(int fd, unsigned char *response, int response_length, int timeout_ms);
int calculate_checksum(const unsigned char *data, int length);
int validate_checksum(const unsigned char *response);
int parse_co2_ppm(const unsigned char *response, int *ppm);
int log_data(FILE *fp, const sensor_data_t *data);
int log_error(FILE *fp, int error_code, const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Initialize UART
int init_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                                // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read at least 0 characters
    tty.c_cc[VTIME] = 5;                             // Wait for 0.5 seconds (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Send command to sensor
int send_command(int fd, const unsigned char *command, int command_length) {
    ssize_t bytes_written = write(fd, command, command_length);
    if (bytes_written != command_length) {
        perror("Error writing to UART");
        return -1;
    }
    return 0;
}

// Receive response from sensor with timeout
int receive_response(int fd, unsigned char *response, int response_length, int timeout_ms) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = timeout_ms / 1000;
    timeout.tv_usec = (timeout_ms % 1000) * 1000;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("Error in select()");
        return -1;
    } else if (retval == 0) {
        fprintf(stderr, "Timeout waiting for response\n");
        return -1;
    } else {
        ssize_t bytes_read = read(fd, response, response_length);
        if (bytes_read != response_length) {
            fprintf(stderr, "Error reading from UART, read %zd bytes, expected %d\n", bytes_read, response_length);
            return -1;
        }
        return 0;
    }
}

// Calculate checksum
int calculate_checksum(const unsigned char *data, int length) {
    int checksum = 0;
    for (int i = 0; i < length; i++) {
        checksum += data[i];
    }
    return checksum;
}

// Validate checksum
int validate_checksum(const unsigned char *response) {
    int checksum = calculate_checksum(response, RESPONSE_LENGTH - 1);
    int received_checksum = (response[RESPONSE_LENGTH - 1] << 8) | response[RESPONSE_LENGTH - 2];
    if (checksum != received_checksum) {
        fprintf(stderr, "Checksum mismatch: calculated 0x%04X, received 0x%04X\n", checksum, received_checksum);
        return 0; // Checksum mismatch
    }
    return 1; // Checksum valid
}

// Parse CO2 ppm value
int parse_co2_ppm(const unsigned char *response, int *ppm) {
    *ppm = (response[0] << 8) | response[1];
    return 0;
}

// Log data to file
int log_data(FILE *fp, const sensor_data_t *data) {
    if (fp == NULL) {
        fprintf(stderr, "Error: Log file not opened\n");
        return -1;
    }

    fprintf(fp, "{\"timestamp\":%ld.%09ld, \"ppm\":%d, \"error\":%d}\n",
            data->tv_sec, data->tv_nsec, data->ppm, data->error);
    fflush(fp);
    return 0;
}

// Log error to file
int log_error(FILE *fp, int error_code, const char *message) {
    if (fp == NULL) {
        fprintf(stderr, "Error: Error log file not opened\n");
        return -1;
    }

    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

