#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// GPIO pin for output
#define GPIO_PIN 17

// Target heading
#define TARGET_HEADING 90.0

// Heading deviation threshold
#define HEADING_THRESHOLD 10.0

// Circular buffer size
#define BUFFER_SIZE 100

// I2C handle
int i2c_handle;

// Circular buffer
float heading_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_hmc5883l();
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t x, int16_t y);
float apply_hard_iron_compensation(float heading, int16_t x_offset, int16_t y_offset);
void update_circular_buffer(float heading);
float calculate_average_heading();
void set_gpio_output(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Initialize HMC5883L
int init_hmc5883l() {
    // Configure register A: 8-average, 15 Hz, normal measurement
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Configure register B: Gain = 1.3 Ga
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0xA0) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Set continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, data, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *z = (int16_t)((data[2] << 8) | data[3]);
    *y = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Calculate heading from magnetometer data
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2(y, x) * 180 / M_PI;

    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Apply hard iron compensation
float apply_hard_iron_compensation(float heading, int16_t x_offset, int16_t y_offset) {
    float compensated_heading = heading - (float)x_offset / 100.0; // Assuming 100 counts per degree
    return compensated_heading;
}

// Update circular buffer
void update_circular_buffer(float heading) {
    heading_buffer[buffer_index] = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate average heading from circular buffer
float calculate_average_heading() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += heading_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Set GPIO output
void set_gpio_output(int state) {
    gpioWrite(GPIO_PIN, state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float heading, compensated_heading, average_heading;

    // Main loop
    while (1) {
        // Read magnetometer data
        if (read_magnetometer(&x, &y, &z) == 0) {
            // Calculate heading
            heading = calculate_heading(x, y);

            // Apply hard iron compensation
            compensated_heading = apply_hard_iron_compensation(heading, 100, -50);

            // Update circular buffer
            update_circular_buffer(compensated_heading);

            // Calculate average heading
            average_heading = calculate_average_heading();

            // Check for deviation
            if (fabs(average_heading - TARGET_HEADING) > HEADING_THRESHOLD) {
                set_gpio_output(1);
            } else {
                set_gpio_output(0);
            }

            printf("Heading: %.2f, Average Heading: %.2f, GPIO: %d\n", compensated_heading, average_heading, gpioRead(GPIO_PIN));
        } else {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
        }

        // Delay
        gpioDelay(100000); // 100ms
    }

    // Cleanup (should not reach here in normal operation due to signal handler)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

