#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor A pins
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B pins
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// Proportional gain
#define PROPORTIONAL_GAIN 2.0

// Distance thresholds (cm)
#define FORWARD_THRESHOLD 50.0
#define BACKWARD_THRESHOLD 100.0

// Global flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set motor control pins as outputs
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency for IN2 and IN4
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    return 0;
}

// Function to set motor speed
void set_motor_speed(int motor, int speed) {
    if (motor == 0) { // Motor A
        if (speed > 0) {
            gpioWrite(MOTOR_A_IN1, 1);
            gpioWrite(MOTOR_A_IN2, 0);
            gpioPWM(MOTOR_A_IN2, speed);
        } else {
            gpioWrite(MOTOR_A_IN1, 0);
            gpioWrite(MOTOR_A_IN2, 0);
        }
    } else { // Motor B
        if (speed > 0) {
            gpioWrite(MOTOR_B_IN3, 1);
            gpioWrite(MOTOR_B_IN4, 0);
            gpioPWM(MOTOR_B_IN4, speed);
        } else {
            gpioWrite(MOTOR_B_IN3, 0);
            gpioWrite(MOTOR_B_IN4, 0);
        }
    }
}

// Function to stop the motor
void stop_motor(int motor) {
    if (motor == 0) { // Motor A
        gpioWrite(MOTOR_A_IN1, 0);
        gpioWrite(MOTOR_A_IN2, 0);
        gpioPWM(MOTOR_A_IN2, 0);
    } else { // Motor B
        gpioWrite(MOTOR_B_IN3, 0);
        gpioWrite(MOTOR_B_IN4, 0);
        gpioPWM(MOTOR_B_IN4, 0);
    }
}

// Function to calculate PWM duty cycle based on distance
int calculate_pwm(int distance) {
    if (distance < FORWARD_THRESHOLD) {
        return (int)((FORWARD_THRESHOLD - distance) * PROPORTIONAL_GAIN);
    } else if (distance > BACKWARD_THRESHOLD) {
        return 0;
    } else {
        return 0;
    }
}

int main(int argc, char *argv[]) {
    // Check for correct number of arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_a> <distance_b>\n", argv[0]);
        return 1;
    }

    // Parse distance arguments
    float distance_a = atof(argv[1]);
    float distance_b = atof(argv[2]);

    // Validate distance arguments
    if (distance_a < 10.0 || distance_a > 100.0 || distance_b < 10.0 || distance_b > 100.0) {
        fprintf(stderr, "Error: Distance values must be between 10 and 100 cm\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (!terminate) {
        // Calculate PWM duty cycles
        int pwm_a = calculate_pwm((int)distance_a);
        int pwm_b = calculate_pwm((int)distance_b);

        // Set motor speeds
        set_motor_speed(0, pwm_a);
        set_motor_speed(1, pwm_b);

        // Print motor speeds (for debugging)
        printf("Motor A: %d, Motor B: %d\n", pwm_a, pwm_b);

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Stop motors and cleanup
    stop_motor(0);
    stop_motor(1);
    gpioTerminate();

    return 0;
}

