    gpioWrite(IN1, steps[step_number][0]);
    gpioWrite(IN2, steps[step_number][1]);
    gpioWrite(IN3, steps[step_number][2]);
    gpioWrite(IN4, steps[step_number][3]);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(IN1, PI_OUTPUT);
    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(IN3, PI_OUTPUT);
    gpioSetMode(IN4, PI_OUTPUT);

    // Set button pins as inputs with pull-up resistors
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    printf("Door lock/unlock system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Check for lock button press
        if (gpioRead(LOCK_BUTTON) == 0 && !lock_pressed) {
            lock_pressed = 1;
            unlock_pressed = 0; // Prevent re-triggering on hold
            lock_door();
        } else if (gpioRead(LOCK_BUTTON) == 1) {
            lock_pressed = 0;
        }

        // Check for unlock button press
        if (gpioRead(UNLOCK_BUTTON) == 0 && !unlock_pressed) {
            unlock_pressed = 1;
            lock_pressed = 0; // Prevent re-triggering on hold
            unlock_door();
        } else if (gpioRead(UNLOCK_BUTTON) == 1) {
            unlock_pressed = 0;
        }

        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    return 0;
}

