#include <linux/i2c-dev.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43
#define SERVO_PIN 18
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define PWM_PERIOD 20000000 // 20ms
#define LOG_FILE "solar_tracker.log"

// Global variables
int i2c_fd = -1;
FILE *log_fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int init_mpu6050(int fd);
int read_mpu6050_data(int fd, float *pitch, float *roll);
int set_servo_angle(int angle);
int log_data(float pitch, float roll, int angle);
void signal_handler(int sig);

// I2C read function with retry and exponential backoff
int i2c_read_reg(int fd, uint8_t reg) {
    int retries = 3;
    int delay_ms = 10;
    int result;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            perror("Failed to acquire bus access and/or talk to slave");
            return -1;
        }

        if (write(fd, &reg, 1) != 1) {
            perror("Failed to write to I2C device");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            continue;
        }

        result = read(fd, &reg, 1);
        if (result == 1) {
            return reg;
        } else {
            perror("Failed to read from I2C device");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }
    return -1; // Indicate failure after retries
}

// I2C write function with retry and exponential backoff
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int retries = 3;
    int delay_ms = 10;
    uint8_t buf[2];

    buf[0] = reg;
    buf[1] = value;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
            perror("Failed to acquire bus access and/or talk to slave");
            return -1;
        }

        if (write(fd, buf, 2) == 2) {
            return 0; // Success
        } else {
            perror("Failed to write to I2C device");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
        }
    }
    return -1; // Indicate failure after retries
}

// MPU6050 initialization function
int init_mpu6050(int fd) {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2c_write_reg(fd, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error waking up MPU6050\n");
        return -1;
    }
    return 0;
}

// MPU6050 data reading function
int read_mpu6050_data(int fd, float *pitch, float *roll) {
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float accel_x_f, accel_y_f, accel_z_f, gyro_x_f, gyro_y_f, gyro_z_f;

    // Read accelerometer data
    accel_x = (i2c_read_reg(fd, ACCEL_XOUT_H) << 8) | i2c_read_reg(fd, ACCEL_XOUT_H + 1);
    accel_y = (i2c_read_reg(fd, ACCEL_XOUT_H + 2) << 8) | i2c_read_reg(fd, ACCEL_XOUT_H + 3);
    accel_z = (i2c_read_reg(fd, ACCEL_XOUT_H + 4) << 8) | i2c_read_reg(fd, ACCEL_XOUT_H + 5);

    // Read gyroscope data
    gyro_x = (i2c_read_reg(fd, GYRO_XOUT_H) << 8) | i2c_read_reg(fd, GYRO_XOUT_H + 1);
    gyro_y = (i2c_read_reg(fd, GYRO_XOUT_H + 2) << 8) | i2c_read_reg(fd, GYRO_XOUT_H + 3);
    gyro_z = (i2c_read_reg(fd, GYRO_XOUT_H + 4) << 8) | i2c_read_reg(fd, GYRO_XOUT_H + 5);

    // Convert to float values (adjust scaling as needed)
    accel_x_f = (float)accel_x / 16384.0f; // Assuming +/- 2g sensitivity
    accel_y_f = (float)accel_y / 16384.0f;
    accel_z_f = (float)accel_z / 16384.0f;
    gyro_x_f = (float)gyro_x / 131.0f;     // Assuming +/- 250 deg/s sensitivity
    gyro_y_f = (float)gyro_y / 131.0f;
    gyro_z_f = (float)gyro_z / 131.0f;

    // Calculate pitch and roll
    *pitch = atan2(accel_x_f, sqrt(accel_y_f * accel_y_f + accel_z_f * accel_z_f)) * 180 / M_PI;
    *roll = atan2(accel_y_f, sqrt(accel_x_f * accel_x_f + accel_z_f * accel_z_f)) * 180 / M_PI;

    return 0;
}

// Servo motor control function
int set_servo_angle(int angle) {
    char path[64];
    int fd;
    char buf[64];

    // Export PWM channel
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/export", PWM_CHIP, PWM_CHANNEL);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
