    // Set PWM period
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM period file");
        return -1;
    }
    snprintf(buf, sizeof(buf), "%d", PWM_PERIOD);
    if (write(fd, buf, strlen(buf)) < 0) {
        perror("Failed to write to PWM period file");
        close(fd);
        return -1;
    }
    close(fd);

    // Set PWM duty cycle (adjust for angle)
    int duty_cycle = (int)((angle / 180.0) * PWM_PERIOD);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM duty_cycle file");
        return -1;
    }
    snprintf(buf, sizeof(buf), "%d", duty_cycle);
    if (write(fd, buf, strlen(buf)) < 0) {
        perror("Failed to write to PWM duty_cycle file");
        close(fd);
        return -1;
    }
    close(fd);

    // Enable PWM
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open PWM enable file");
        return -1;
    }
    if (write(fd, "1", 1) < 0) {
        perror("Failed to write to PWM enable file");
        close(fd);
        return -1;
    }
    close(fd);

    return 0;
}

// Data logging function
int log_data(float pitch, float roll, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_fp, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, angle);
    fflush(log_fp); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    float pitch, roll;
    int angle;

    // Register signal handlers
    signal(SIGINT, signal_handler);
