    if (log_fp == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_mpu6050_data(i2c_fd, &pitch, &roll) == 0) {
            // Calculate servo angle (example: map pitch to angle)
            angle = (int)((pitch + 90) / 180.0 * 180); // Map pitch to 0-180
            if (angle < 0) angle = 0;
            if (angle > 180) angle = 180;

            // Set servo angle
