        }

        usleep(100000); // 100ms delay
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_fp);

    // Disable PWM
    char path[64];
    int fd;
    char buf[64];

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    fd = open(path, O_WRONLY);
    if (fd >= 0) {
        write(fd, "0", 1);
        close(fd);
    }

    return 0;
}

