#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_FREQUENCY 200.0    // Minimum buzzer frequency in Hz
#define MAX_FREQUENCY 2000.0   // Maximum buzzer frequency in Hz
#define MIN_DISTANCE 2.0       // Minimum distance in cm
#define MAX_DISTANCE 20.0      // Maximum distance in cm
#define TIMEOUT_US 50000        // Timeout in microseconds (50ms)
#define MIN_GAP_MS 60          // Minimum gap between measurements in milliseconds

// Global variables
static volatile int running = 1;
static volatile unsigned int last_echo_time = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_sensor();
long measure_pulse_width();
double calculate_distance(long pulse_width);
int map_distance_to_frequency(double distance);
void set_buzzer_frequency(int frequency);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low initially
    gpioPWM(BUZZER_PIN, 0);    // Ensure buzzer is off initially

    return 0;
}

// Trigger the HC-SR04 sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the pulse width of the echo signal
long measure_pulse_width() {
    unsigned int start_tick, end_tick, current_tick;

    // Wait for echo to go high, with timeout
    current_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - current_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo high\n");
            return -1; // Timeout
        }
    }
    start_tick = gpioTick();

    // Wait for echo to go low, with timeout
    current_tick = start_tick;
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - current_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo low\n");
            return -1; // Timeout
        }
    }
    end_tick = gpioTick();

    return end_tick - start_tick;
}

// Calculate the distance in centimeters
double calculate_distance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Map the distance to a frequency
int map_distance_to_frequency(double distance) {
    if (distance < MIN_DISTANCE) {
        return (int)MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return (int)MAX_FREQUENCY;
    } else {
        // Linear mapping
        return (int)(MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE));
    }
}

// Set the buzzer frequency
void set_buzzer_frequency(int frequency) {
    gpioSetPWMfrequency(BUZZER_PIN, frequency);
    gpioPWM(BUZZER_PIN, 128); // 50% duty cycle
}

// Cleanup function
void cleanup() {
    gpioPWM(BUZZER_PIN, 0); // Silence the buzzer
    gpioTerminate();         // Terminate pigpio
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio()) {
        return 1;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    struct timespec last_measurement, current_time;
    clock_gettime(CLOCK_MONOTONIC, &last_measurement);

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        double time_diff_ms = (current_time.tv_sec - last_measurement.tv_sec) * 1000.0 + (current_time.tv_nsec - last_measurement.tv_nsec) / 1000000.0;

        if (time_diff_ms >= MIN_GAP_MS) {
            trigger_sensor();
            long pulse_width = measure_pulse_width();

            if (pulse_width > 0) {
                double distance = calculate_distance(pulse_width);
                if (distance > 0) {
                    int frequency = map_distance_to_frequency(distance);
                    set_buzzer_frequency(frequency);
                    printf("Distance: %.2f cm, Frequency: %d Hz\n", distance, frequency);
                } else {
                    fprintf(stderr, "Error: Invalid distance measurement\n");
                }
            } else {
                fprintf(stderr, "Error: Invalid pulse width\n");
            }

            clock_gettime(CLOCK_MONOTONIC, &last_measurement);
        }

        gpioDelay(1000); // Check every 1ms
    }

    cleanup();
    return 0;
}

