#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set the color of the RGB LED
void set_led_color(float red, float green, float blue) {
    // Common anode, so invert the PWM duty cycle
    int red_pwm   = 255 - (int)(red   * 255.0);
    int green_pwm = 255 - (int)(green * 255.0);
    int blue_pwm  = 255 - (int)(blue  * 255.0);

    // Set PWM duty cycle for each color
    gpioPWM(RED_PIN,   red_pwm);
    gpioPWM(GREEN_PIN, green_pwm);
    gpioPWM(BLUE_PIN,  blue_pwm);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN,   PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN,   255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN,  255);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Calculate time
        double time = time_time();

        // Calculate sine wave values for red, green, and blue
        float red   = sin(time);
        float green = sin(time + M_PI / 2.0);
        float blue  = sin(time + M_PI);

        // Set LED color
        set_led_color(red, green, blue);

        // Delay for a short period
        gpioDelay(10000); // 10ms
    }

    // Turn off the LED
    set_led_color(0.0, 0.0, 0.0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

