#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Sensitivity scale factor (LSB/deg/s)
#define GYRO_SENSITIVITY 131.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050();
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void convert_gyro_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps);
int log_data(float gyro_x_dps, float gyro_y_dps, float gyro_z_dps);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize MPU6050
int init_mpu6050() {
    // Wake up the MPU6050 (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU6050: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read gyroscope data
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyro data: %s\n", strerror(errno));
        return -1;
    }

    *gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    *gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    *gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Convert gyroscope data to degrees per second
void convert_gyro_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps) {
    *gyro_x_dps = (float)gyro_x / GYRO_SENSITIVITY;
    *gyro_y_dps = (float)gyro_y / GYRO_SENSITIVITY;
    *gyro_z_dps = (float)gyro_z / GYRO_SENSITIVITY;
}

// Log data to file
int log_data(float gyro_x_dps, float gyro_y_dps, float gyro_z_dps) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, gyro_x_dps, gyro_y_dps, gyro_z_dps) < 0) {
        fprintf(stderr, "Error: Could not write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    int16_t gyro_x, gyro_y, gyro_z;
    float gyro_x_dps, gyro_y_dps, gyro_z_dps;
    int init_attempts = 0;
    const int max_init_attempts = 3;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050
    while (init_mpu6050() != 0 && init_attempts < max_init_attempts) {
        fprintf(stderr, "Attempting to re-initialize MPU6050... (%d/%d)\n", init_attempts + 1, max_init_attempts);
        gpioDelay(1000); // Wait 1 second before retrying
        init_attempts++;
    }

    if (init_attempts == max_init_attempts) {
        fprintf(stderr, "Error: Failed to initialize MPU6050 after %d attempts\n", max_init_attempts);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) == 0) {
            // Convert gyroscope data
            convert_gyro_data(gyro_x, gyro_y, gyro_z, &gyro_x_dps, &gyro_y_dps, &gyro_z_dps);

            // Log data
            if (log_data(gyro_x_dps, gyro_y_dps, gyro_z_dps) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read gyro data\n");
        }

        gpioDelay(100); // Sample every 100ms
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

