#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody notes (frequency, duration in ms)
const int melody[][2] = {
    {262, 200},   // C4
    {294, 200},   // D4
    {330, 200},   // E4
    {349, 200},   // F4
    {392, 200},   // G4
    {440, 200},   // A4
    {494, 200},   // B4
    {523, 200}    // C5
};

const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Global variables
volatile int melody_playing = 0;
volatile int button_pressed = 0;

// Function prototypes
void button_callback(int gpio, int level, uint32_t tick);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Button interrupt callback function
void button_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Button pressed (active low)
        button_pressed = 1;
    }
}

// Play melody function
void play_melody() {
    int i;
    for (i = 0; i < melody_length; i++) {
        int frequency = melody[i][0];
        int duration = melody[i][1];

        gpioPWM(BUZZER_PIN, 128); // 50% duty cycle
        gpioSetPWMfrequency(BUZZER_PIN, frequency);
        gpioDelay(duration * 1000); // Convert ms to us

        if (!melody_playing) {
            break; // Stop if melody stopped
        }
    }
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
}

// Stop melody function
void stop_melody() {
    melody_playing = 0;
    gpioPWM(BUZZER_PIN, 0); // Stop PWM
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_melody();
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Enable pull-up resistor on the button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set PWM range (adjust as needed)
    gpioSetPWMrange(BUZZER_PIN, 255);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(BUZZER_PIN, 440); // Initial frequency

    // Set interrupt callback for button press
    gpioSetAlertFunc(BUTTON_PIN, button_callback);

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Doorbell program started. Press Ctrl+C to exit.\n");

    int last_button_state = 1; // Assume button is released initially
    int melody_start_time = 0;

    while (1) {
        if (button_pressed) {
            int current_button_state = gpioRead(BUTTON_PIN);

            if (current_button_state == 0) { // Button still pressed
                if (!melody_playing) {
                    melody_playing = 1;
                    play_melody();
                } else {
                    stop_melody();
                }
                button_pressed = 0; // Reset flag
                last_button_state = 0; // Update last state
            } else {
                last_button_state = 1; // Button released
            }
        }

        gpioDelay(1000); // Check every 1ms
    }

    return 0;
}

