#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5
#define DEFAULT_TIMEOUT_MS 1000

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int main(int argc, char *argv[]) {
    int timeout_ms = DEFAULT_TIMEOUT_MS;
    int window[WINDOW_SIZE] = {0};
    int window_index = 0;
    int earthquake_count = 0;
    int edge_count = 0;
    int log_fd = -1;
    struct timespec ts;
    char timestamp[30];
    char log_message[100];
    int i;

    // Parse command-line arguments
    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default: %d ms\n", DEFAULT_TIMEOUT_MS);
            timeout_ms = DEFAULT_TIMEOUT_MS;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_fd = open("vibration_events.log", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read GPIO pin value
        int value = gpioRead(GPIO_PIN);

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Failed to get timestamp: %s\n", strerror(errno));
            continue; // Continue to the next iteration
        }

        // Format timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&ts.tv_sec));
        snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ldZ", ts.tv_nsec);

        // Log event
        snprintf(log_message, sizeof(log_message), "%s %d\n", timestamp, value);
        if (write(log_fd, log_message, strlen(log_message)) == -1) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        }
        fsync(log_fd);

        // Update sliding window
        window[window_index] = value;
        window_index = (window_index + 1) % WINDOW_SIZE;

        // Check for earthquake
        earthquake_count = 0;
        for (i = 0; i < WINDOW_SIZE; i++) {
            if (window[i] == 1) {
                earthquake_count++;
            }
        }

        if (earthquake_count >= 3) {
            printf("EARTHQUAKE ALERT: %s\n", timestamp);
        }

        edge_count++;

        // Sleep for timeout
        gpioDelay(timeout_ms * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    close(log_fd);
    gpioTerminate();

    return 0;
}

