#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define CRA_REG_M 0x00
#define CRB_REG_M 0x01
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function prototypes
int init_i2c();
magnetometer_data_t read_magnetometer();
magnetometer_data_t calibrate_magnetometer(magnetometer_data_t raw_data);
float calculate_heading(magnetometer_data_t calibrated_data);
const char* determine_direction(float heading);
void log_data(magnetometer_data_t calibrated_data, float heading);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Configure magnetometer (example configuration)
    if (i2cWriteByteData(i2c_handle, CRA_REG_M, 0x14) < 0) { // 75 Hz, 15 uT
        fprintf(stderr, "Error writing to CRA_REG_M\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CRB_REG_M, 0x20) < 0) { // Gain = 1
        fprintf(stderr, "Error writing to CRB_REG_M\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MR_REG_M, 0x00) < 0) { // Continuous conversion mode
        fprintf(stderr, "Error writing to MR_REG_M\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
magnetometer_data_t read_magnetometer() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data
        return data;
    }

    data.x = (int16_t)(buffer[0] << 8 | buffer[1]);
    data.z = (int16_t)(buffer[2] << 8 | buffer[3]);
    data.y = (int16_t)(buffer[4] << 8 | buffer[5]);

    return data;
}

// Calibrate magnetometer data
magnetometer_data_t calibrate_magnetometer(magnetometer_data_t raw_data) {
    magnetometer_data_t calibrated_data;
    calibrated_data.x = raw_data.x - X_OFFSET;
    calibrated_data.y = raw_data.y - Y_OFFSET;
    calibrated_data.z = raw_data.z - Z_OFFSET;
    return calibrated_data;
}

// Calculate heading in degrees
float calculate_heading(magnetometer_data_t calibrated_data) {
    float heading = atan2(calibrated_data.y, calibrated_data.x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Determine compass direction
const char* determine_direction(float heading) {
    if (heading >= 337.5 || heading < 22.5) {
        return "N";
    } else if (heading >= 22.5 && heading < 67.5) {
        return "NE";
    } else if (heading >= 67.5 && heading < 112.5) {
        return "E";
    } else if (heading >= 112.5 && heading < 157.5) {
        return "SE";
    } else if (heading >= 157.5 && heading < 202.5) {
        return "S";
    } else if (heading >= 202.5 && heading < 247.5) {
        return "SW";
    } else if (heading >= 247.5 && heading < 292.5) {
        return "W";
    } else {
        return "NW";
    }
}

// Log data to file
void log_data(magnetometer_data_t calibrated_data, float heading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d, %.2f\n", timestamp, calibrated_data.x, calibrated_data.y, calibrated_data.z, heading);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        magnetometer_data_t raw_data = read_magnetometer();
        magnetometer_data_t calibrated_data = calibrate_magnetometer(raw_data);
        float heading = calculate_heading(calibrated_data);
        const char* direction = determine_direction(heading);

        printf("Heading: %.2f degrees, Direction: %s\n", heading, direction);

        log_data(calibrated_data, heading);

        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

