#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 200

static volatile int running = 1;
static volatile unsigned long last_touch_time = 0;

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *info;
    char *buffer = malloc(sizeof(char) * 30);
    if (buffer == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    info = gmtime(&rawtime);

    strftime(buffer, 30, "%Y-%m-%dT%H:%M:%SZ", info);
    return buffer;
}

// Function to log relay state to JSON file
int log_relay_state(const char *timestamp, const char *state) {
    FILE *fp = fopen("relay_log.json", "a");
    if (fp == NULL) {
        perror("Failed to open relay_log.json");
        return -1;
    }

    fprintf(fp, "{\"timestamp\": \"%s\", \"relay_state\": \"%s\"}\n", timestamp, state);
    fclose(fp);
    return 0;
}

// Function to toggle relay state
void toggle_relay() {
    int current_state = gpioRead(RELAY_PIN);
    int new_state = !current_state;
    gpioWrite(RELAY_PIN, new_state);

    char *timestamp = get_iso8601_timestamp();
    if (timestamp != NULL) {
        if (new_state == 1) {
            if (log_relay_state(timestamp, "ON") != 0) {
                fprintf(stderr, "Failed to log relay state ON\n");
            }
        } else {
            if (log_relay_state(timestamp, "OFF") != 0) {
                fprintf(stderr, "Failed to log relay state OFF\n");
            }
        }
        free(timestamp);
    } else {
        fprintf(stderr, "Failed to get timestamp for relay state change\n");
    }
}

// Interrupt handler function
void touch_interrupt_handler(int gpio, int level, unsigned int tick, void *user) {
    unsigned long current_time = gpioTick();
    if (current_time - last_touch_time > DEBOUNCE_DELAY_MS * 1000) { // Convert ms to us
        toggle_relay();
        last_touch_time = current_time;
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioWrite(RELAY_PIN, 0); // Turn off relay
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-down resistor on touch pin
    gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN);

    // Set initial relay state to OFF
    gpioWrite(RELAY_PIN, 0);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set interrupt handler for touch pin
    if (gpioSetISRFuncEx(TOUCH_PIN, RISING_EDGE, 0, touch_interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set interrupt handler\n");
        gpioTerminate();
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep for 100ms
    }

    return 0;
}

