#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define VALVE_GPIO 17
#define NOZZLE_GPIO 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    gpioServo(VALVE_GPIO, 0);
    gpioServo(NOZZLE_GPIO, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int moisture_levels[] = {20, 40, 60, 80, 100};
    int moisture_index = 0;
    int moisture;
    int nozzle_angle;
    int i, j;

    while (!terminate) {
        moisture = moisture_levels[moisture_index];
        moisture_index = (moisture_index + 1) % 5;

        printf("Moisture level: %d\n", moisture);

        if (moisture < 50) {
            printf("Moisture below threshold. Watering cycle started.\n");

            // Open valve
            for (i = 0; i < 3; ++i) {
                int result = gpioServo(VALVE_GPIO, 1500);
                if (result == 0) break;
                fprintf(stderr, "Valve open failed (attempt %d): %d\n", i + 1, result);
                gpioDelay(100000); // 100ms
            }
            if (i == 3) {
                fprintf(stderr, "Valve open failed after multiple retries. Skipping watering cycle.\n");
                gpioServo(VALVE_GPIO, 0);
                gpioDelay(5000000); // 5s
                continue;
            }

            // Spray nozzle
            for (nozzle_angle = 0; nozzle_angle <= 180; nozzle_angle += 45) {
                for (j = 0; j < 3; ++j) {
                    int pulse_width = 500 + (nozzle_angle * 50); // 500-2500
                    int result = gpioServo(NOZZLE_GPIO, pulse_width);
                    if (result == 0) break;
                    fprintf(stderr, "Nozzle position %d failed (attempt %d): %d\n", nozzle_angle, j + 1, result);
                    gpioDelay(100000); // 100ms
                }
                if (j == 3) {
                    fprintf(stderr, "Nozzle position %d failed after multiple retries. Continuing to next position.\n", nozzle_angle);
                    continue;
                }
                gpioDelay(2000000); // 2s
            }

            // Close valve
            for (i = 0; i < 3; ++i) {
                int result = gpioServo(VALVE_GPIO, 500);
                if (result == 0) break;
                fprintf(stderr, "Valve close failed (attempt %d): %d\n", i + 1, result);
                gpioDelay(100000); // 100ms
            }
            if (i == 3) {
                fprintf(stderr, "Valve close failed after multiple retries. Continuing to next cycle.\n");
            }

            gpioDelay(5000000); // 5s
        } else {
            printf("Moisture above threshold. Skipping watering cycle.\n");
            gpioDelay(5000000); // 5s
        }
    }

    gpioServo(VALVE_GPIO, 0);
    gpioServo(NOZZLE_GPIO, 0);
    gpioTerminate();

    return 0;
}

