    *gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Log data to file
int log_data(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, gyro_x, gyro_y, gyro_z);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    int result;
    int16_t gyro_x, gyro_y, gyro_z;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "MPU6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_x, &gyro_y, &gyro_z) == 0) {
            // Log data
            if (log_data(gyro_x, gyro_y, gyro_z) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }

        // Delay for 100ms (10Hz sampling rate)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

