#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_RELAY 18
#define DISTANCE_THRESHOLD 50 // cm
#define POLL_INTERVAL_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void set_relay_state(int state);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // No specific initialization needed for VL53L1X with pigpio, but good practice to check I2C connection
    // In a real application, you might need to write specific registers to configure the sensor.
    // For example, setting timing budget, ranging mode, etc.

    // Check if the sensor is present by reading a register (e.g., model ID)
    // This is a placeholder, replace with actual register read
    char buf[1];
    if (i2cReadDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error: VL53L1X not found or I2C error during initialization.\n");
        return -1;
    }

    return 0; // Success
}

// Read distance from VL53L1X sensor
int read_distance(int *distance) {
    // VL53L1X register addresses (example, adjust based on datasheet)
    const int VL53L1X_REG_START_STOP_CONTROL = 0x41;
    const int VL53L1X_REG_RESULT_RANGE_STATUS = 0x14;
    const int VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 = 0x1E;

    // Start a single measurement
    char start_buf[2] = {VL53L1X_REG_START_STOP_CONTROL, 0x01}; // Example value, check datasheet
    if (i2cWriteDevice(i2c_handle, start_buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to start measurement.\n");
        return -1;
    }

    // Wait for measurement to complete (adjust timeout as needed)
    gpioDelay(10000); // 10ms

    // Read the range status
    char range_status_buf[1] = {VL53L1X_REG_RESULT_RANGE_STATUS};
    if (i2cWriteDevice(i2c_handle, range_status_buf, 1) != 1) {
        fprintf(stderr, "Error: Failed to write range status register address.\n");
        return -1;
    }

    char range_status[1];
    if (i2cReadDevice(i2c_handle, range_status, 1) != 1) {
        fprintf(stderr, "Error: Failed to read range status.\n");
        return -1;
    }

    // Read the distance
    char distance_buf[1] = {VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0};
    if (i2cWriteDevice(i2c_handle, distance_buf, 1) != 1) {
        fprintf(stderr, "Error: Failed to write distance register address.\n");
        return -1;
    }

    char distance_data[2];
    if (i2cReadDevice(i2c_handle, distance_data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read distance data.\n");
        return -1;
    }

    *distance = (distance_data[0] << 8) | distance_data[1]; // Combine bytes

    return 0; // Success
}

// Set relay state
void set_relay_state(int state) {
    gpioWrite(GPIO_RELAY, state);
}

