#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Global variable for I2C handle
int i2c_handle;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a single byte from an I2C register
int read_register(int handle, int reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050 (wake up the sensor)
    if (write_register(i2c_handle, PWR_MGMT_1, 0) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read gyroscope data
        int gyro_x_h = read_register(i2c_handle, GYRO_XOUT_H);
        int gyro_x_l = read_register(i2c_handle, GYRO_XOUT_L);
        int gyro_y_h = read_register(i2c_handle, GYRO_YOUT_H);
        int gyro_y_l = read_register(i2c_handle, GYRO_YOUT_L);
        int gyro_z_h = read_register(i2c_handle, GYRO_ZOUT_H);
        int gyro_z_l = read_register(i2c_handle, GYRO_ZOUT_L);

        if (gyro_x_h < 0 || gyro_x_l < 0 || gyro_y_h < 0 || gyro_y_l < 0 || gyro_z_h < 0 || gyro_z_l < 0) {
            fprintf(stderr, "Error reading gyroscope data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Combine high and low bytes to form 16-bit values
        short gyro_x = (gyro_x_h << 8) | gyro_x_l;
        short gyro_y = (gyro_y_h << 8) | gyro_y_l;
        short gyro_z = (gyro_z_h << 8) | gyro_z_l;

        // Print the angular velocities
        printf("X: %6d, Y: %6d, Z: %6d\n", gyro_x, gyro_y, gyro_z);

        // Delay for 100ms
        gpioDelay(100);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

