#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO17 17
#define GPIO18 18
#define GPIO27 27
#define GPIO22 22

// Define watering duration (seconds)
#define WATERING_DURATION 5

// Define cycle duration (seconds)
#define CYCLE_DURATION 86400 // 24 hours

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *line17, *line18, *line27, *line22;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
void cleanup_gpio(void);
int activate_relay(int gpio_pin);
int deactivate_relay(int gpio_pin);
int log_watering_event(int gpio_pin);
void signal_handler(int sig);
char* get_current_timestamp(void);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to get current timestamp
char* get_current_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    static char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    return buffer;
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO lines
    line17 = gpiod_chip_get_line(chip, GPIO17);
    line18 = gpiod_chip_get_line(chip, GPIO18);
    line27 = gpiod_chip_get_line(chip, GPIO27);
    line22 = gpiod_chip_get_line(chip, GPIO22);

    if (!line17 || !line18 || !line27 || !line22) {
        perror("Error getting GPIO line");
        cleanup_gpio();
        return -1;
    }

    // Request GPIO lines as outputs
    ret = gpiod_line_request_output(line17, "watering", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        cleanup_gpio();
        return -1;
    }
    ret = gpiod_line_request_output(line18, "watering", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        cleanup_gpio();
        return -1;
    }
    ret = gpiod_line_request_output(line27, "watering", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        cleanup_gpio();
        return -1;
    }
    ret = gpiod_line_request_output(line22, "watering", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Function to activate a relay
int activate_relay(int gpio_pin) {
    int ret;
    struct gpiod_line *line = NULL;

    switch (gpio_pin) {
        case GPIO17:
            line = line17;
            break;
        case GPIO18:
            line = line18;
            break;
        case GPIO27:
            line = line27;
            break;
        case GPIO22:
            line = line22;
            break;
        default:
            fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
            return -1;
    }

    if (!line) {
        fprintf(stderr, "GPIO line not found for pin: %d\n", gpio_pin);
        return -1;
    }

    ret = gpiod_line_set_value(line, 0); // Active low
    if (ret < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }

    return 0;
}

// Function to deactivate a relay
int deactivate_relay(int gpio_pin) {
    int ret;
    struct gpiod_line *line = NULL;

    switch (gpio_pin) {
        case GPIO17:
            line = line17;
            break;
        case GPIO18:
            line = line18;
            break;
        case GPIO27:
            line = line27;
            break;
        case GPIO22:
            line = line22;
            break;
        default:
            fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
            return -1;
    }

    if (!line) {
        fprintf(stderr, "GPIO line not found for pin: %d\n", gpio_pin);
        return -1;
    }

    ret = gpiod_line_set_value(line, 1); // Active low
    if (ret < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }

    return 0;
}

// Function to log watering event
int log_watering_event(int gpio_pin) {
    char *timestamp = get_current_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return -1;
    }

    fprintf(log_file, "%s - Watering GPIO %d\n", timestamp, gpio_pin);
    fflush(log_file); // Ensure immediate write to file

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (line27) {
        gpiod_line_release(line27);
    }
    if (line22) {
        gpiod_line_release(line22);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int i;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("watering_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (!terminate) {
        for (i = 0; i < 4; i++) {
            int gpio_pin;
            switch (i) {
                case 0:
                    gpio_pin = GPIO17;
                    break;
                case 1:
                    gpio_pin = GPIO18;
                    break;
                case 2:
                    gpio_pin = GPIO27;
                    break;
                case 3:
                    gpio_pin = GPIO22;
                    break;
                default:
                    gpio_pin = -1; // Should not happen
                    break;
            }

            if (gpio_pin != -1) {
                printf("Watering GPIO %d\n", gpio_pin);
                if (log_watering_event(gpio_pin) < 0) {
                    fprintf(stderr, "Error logging watering event\n");
                }
                if (activate_relay(gpio_pin) < 0) {
                    fprintf(stderr, "Error activating relay\n");
                }
                sleep(WATERING_DURATION);
                if (deactivate_relay(gpio_pin) < 0) {
                    fprintf(stderr, "Error deactivating relay\n");
                }
            }
        }
        sleep(CYCLE_DURATION);
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

