        default:
            fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
            return -1;
    }

    if (!line) {
        fprintf(stderr, "GPIO line not found for pin: %d\n", gpio_pin);
        return -1;
    }

    ret = gpiod_line_set_value(line, 1); // Active low
    if (ret < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }

    return 0;
}

// Function to log watering event
int log_watering_event(int gpio_pin) {
    char *timestamp = get_current_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return -1;
    }

    fprintf(log_file, "%s - Watering GPIO %d\n", timestamp, gpio_pin);
    fflush(log_file); // Ensure immediate write to file

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (line27) {
        gpiod_line_release(line27);
    }
    if (line22) {
        gpiod_line_release(line22);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int i;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("watering_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (!terminate) {
        for (i = 0; i < 4; i++) {
            int gpio_pin;
            switch (i) {
                case 0:
                    gpio_pin = GPIO17;
                    break;
                case 1:
                    gpio_pin = GPIO18;
                    break;
                case 2:
                    gpio_pin = GPIO27;
                    break;
                case 3:
                    gpio_pin = GPIO22;
                    break;
                default:
                    gpio_pin = -1; // Should not happen
                    break;
            }

            if (gpio_pin != -1) {
                printf("Watering GPIO %d\n", gpio_pin);
                if (log_watering_event(gpio_pin) < 0) {
                    fprintf(stderr, "Error logging watering event\n");
                }
                if (activate_relay(gpio_pin) < 0) {
                    fprintf(stderr, "Error activating relay\n");
                }
                sleep(WATERING_DURATION);
                if (deactivate_relay(gpio_pin) < 0) {
                    fprintf(stderr, "Error deactivating relay\n");
                }
            }
        }
        sleep(CYCLE_DURATION);
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

