#define LOG_FILE "smart_lighting.log"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_relay_intensity(int gpio, int intensity);
int log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        log_event("Received signal, shutting down...");
    }
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RELAY1_GPIO, PI_OUTPUT) != 0) {
        log_event("Failed to set GPIO17 as output");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY2_GPIO, PI_OUTPUT) != 0) {
        log_event("Failed to set GPIO18 as output");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY3_GPIO, PI_OUTPUT) != 0) {
        log_event("Failed to set GPIO27 as output");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY4_GPIO, PI_OUTPUT) != 0) {
        log_event("Failed to set GPIO22 as output");
        gpioTerminate();
        return 1;
    }

    log_event("GPIO initialisation successful");
    return 0; // Indicate success
}

// Function to set the intensity of a relay (GPIO pin)
int set_relay_intensity(int gpio, int intensity) {
    if (intensity < 0 || intensity > 255) {
        char message[100];
        snprintf(message, sizeof(message), "Invalid intensity value: %d", intensity);
        log_event(message);
        return 1; // Indicate failure
    }

    gpioPWM(gpio, intensity); // Set PWM duty cycle
    char message[100];
    snprintf(message, sizeof(message), "Set GPIO%d intensity to %d", gpio, intensity);
    log_event(message);
    return 0; // Indicate success
}

// Function to log events to a file with timestamps
int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return 1; // Indicate failure
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0; // Indicate success
}

