    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting");
        return 1;
    }

    // Main loop for sunrise effect
    for (int intensity = 0; intensity <= 255 && program_running; intensity++) {
        if (!program_running) break;

        // Set intensity for each relay
        if (set_relay_intensity(RELAY1_GPIO, intensity) != 0) {
            log_event("Failed to set intensity for GPIO17");
        }
        if (set_relay_intensity(RELAY2_GPIO, intensity) != 0) {
            log_event("Failed to set intensity for GPIO18");
        }
        if (set_relay_intensity(RELAY3_GPIO, intensity) != 0) {
            log_event("Failed to set intensity for GPIO27");
        }
        if (set_relay_intensity(RELAY4_GPIO, intensity) != 0) {
            log_event("Failed to set intensity for GPIO22");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Ensure all relays are turned off before exiting
    set_relay_intensity(RELAY1_GPIO, 0);
    set_relay_intensity(RELAY2_GPIO, 0);
    set_relay_intensity(RELAY3_GPIO, 0);
    set_relay_intensity(RELAY4_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();
    log_event("Program terminated");

    return 0;
}

