#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define LED_GPIO 17
#define SAMPLE_RATE_HZ 20
#define SAMPLE_PERIOD_MS (1000 / SAMPLE_RATE_HZ)
#define BUFFER_SIZE 100
#define GYRO_SENSITIVITY 131.0 // LSB/deg/s for +/- 250 deg/s range

// Data structure for gyroscope readings
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_gyro();
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(float x, float y, float z);
void check_thresholds(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the MPU6050 gyroscope
int configure_gyro() {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1\n");
        return -1;
    }

    // Set gyroscope full-scale range to +/- 250 deg/s
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0) < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG\n");
        return -1;
    }
    return 0;
}

// Read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    // Combine high and low bytes, convert to signed 16-bit integer
    int16_t raw_x = (buf[0] << 8) | buf[1];
    int16_t raw_y = (buf[2] << 8) | buf[3];
    int16_t raw_z = (buf[4] << 8) | buf[5];

    // Convert to degrees per second
    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(float x, float y, float z) {
    clock_gettime(CLOCK_REALTIME, &gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Check if any axis exceeds the threshold
void check_thresholds(float x, float y, float z) {
    if (fabs(x) > 250.0 || fabs(y) > 250.0 || fabs(z) > 250.0) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C with retry mechanism
    int init_attempts = 0;
    while (init_i2c() < 0 && init_attempts < 3) {
        fprintf(stderr, "I2C initialization failed, retrying...\n");
        init_attempts++;
        sleep(1); // Wait before retrying
    }
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed after multiple attempts, exiting\n");
        gpioTerminate();
        return 1;
    }

    // Configure gyroscope
    if (configure_gyro() < 0) {
        fprintf(stderr, "Gyroscope configuration failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially turn LED off

    float x, y, z;
    // Main loop
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);
            check_thresholds(x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyro data, attempting re-initialization...\n");
            i2cClose(i2c_handle);
            init_attempts = 0;
            while (init_i2c() < 0 && init_attempts < 3) {
                fprintf(stderr, "I2C re-initialization failed, retrying...\n");
                init_attempts++;
                sleep(1);
            }
            if (init_i2c() < 0) {
                fprintf(stderr, "I2C re-initialization failed after multiple attempts, exiting\n");
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                configure_gyro(); // Re-configure gyro after successful re-initialization
            }
        }
        gpioDelay(SAMPLE_PERIOD_MS * 1000); // Delay for the sample period
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

