#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 3900000 // Approximately 3.9 MHz
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define LED_GPIO 17
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define BUFFER_SIZE 64
#define THRESHOLD 200.0f // degrees/second

// Data structure for gyroscope data
typedef struct {
    long timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// SPI handle
int spi_handle;

// Function prototypes
int init_spi();
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(float x, float y, float z);
void blink_led();
void signal_handler(int signal);
void shutdown();
void print_buffer();

// Function to initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char tx[6] = {GYRO_XOUT_H | 0x80, 0x00, 0x00, GYRO_YOUT_H | 0x80, 0x00, 0x00};
    char rx[6] = {0};

    if (spiXfer(spi_handle, tx, rx, 6) != 0) {
        fprintf(stderr, "Error reading SPI data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t raw_x = (rx[1] << 8) | rx[2];
    int16_t raw_y = (rx[4] << 8) | rx[5];

    // Convert to degrees/second (assuming sensitivity of 131 LSB/deg/s)
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)((rx[3] << 8) | rx[4]) / 131.0f;

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(float x, float y, float z) {
    gyro_buffer[buffer_index].timestamp = time(NULL);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to blink the LED
void blink_led() {
    gpioWrite(LED_GPIO, 1); // Turn LED on
    gpioDelay(500);         // Wait 500ms
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioDelay(500);         // Wait 500ms
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    shutdown();
    exit(0);
}

// Function to shut down the program
void shutdown() {
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

// Function to print the buffer to a CSV file
void print_buffer() {
    FILE *fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing\n");
        return;
    }

    fprintf(fp, "Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        fprintf(fp, "%ld,%.2f,%.2f,%.2f\n", gyro_buffer[i].timestamp, gyro_buffer[i].x, gyro_buffer[i].y, gyro_buffer[i].z);
    }

    fclose(fp);
    printf("Data saved to gyro_data.csv\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z;
    int blink_flag = 0;

    printf("Gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    while (1) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);

            // Check for threshold violation
            if (fabs(x) > THRESHOLD || fabs(y) > THRESHOLD || fabs(z) > THRESHOLD) {
                if (!blink_flag) {
                    blink_led();
                    blink_flag = 1;
                }
            } else {
                blink_flag = 0;
            }
        } else {
            fprintf(stderr, "Failed to read gyro data. Retrying...\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    return 0;
}

