int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buffer[14];

    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buffer, 14) != 14) {
        fprintf(stderr, "Error: Could not read raw data from MPU6050\n");
        return -1;
    }

    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    *gyro_x = (int16_t)((buffer[8] << 8) | buffer[9]);
    *gyro_y = (int16_t)((buffer[10] << 8) | buffer[11]);
    *gyro_z = (int16_t)((buffer[12] << 8) | buffer[13]);

    return 0;
}

// Calculates roll and pitch from accelerometer data
void calculate_roll_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *roll, float *pitch) {
    float accel_x_g = (float)accel_x / 16384.0; // Assuming sensitivity of +/- 2g
    float accel_y_g = (float)accel_y / 16384.0;
    float accel_z_g = (float)accel_z / 16384.0;

    *roll = atan2(accel_y_g, accel_z_g) * 180 / M_PI;
    *pitch = atan2(-accel_x_g, sqrt(accel_y_g * accel_y_g + accel_z_g * accel_z_g)) * 180 / M_PI;
