#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x60
#define LED_GPIO 17
#define PROXIMITY_THRESHOLD 100
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int si1145_read_register(int fd, uint8_t reg);
int si1145_write_register(int fd, uint8_t reg, uint8_t value);
int si1145_read_ambient_light(int fd);
int si1145_read_proximity(int fd);
void log_data(FILE *fp, int ambient_light, int proximity);
void signal_handler(int signal);

// Function to read a single byte from a Si1145 register
int si1145_read_register(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return buf[0];
}

// Function to write a single byte to a Si1145 register
int si1145_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register value");
        return -1;
    }
    return 0;
}

// Function to read the ambient light value from the Si1145
int si1145_read_ambient_light(int fd) {
    int retries = 3;
    while (retries > 0) {
        int als_vis_low = si1145_read_register(fd, 0x22);
        int als_vis_high = si1145_read_register(fd, 0x23);

        if (als_vis_low >= 0 && als_vis_high >= 0) {
            return (als_vis_high << 8) | als_vis_low;
        } else {
            fprintf(stderr, "Error reading ambient light, retrying...\n");
            usleep(10000); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read ambient light after multiple retries.\n");
    return -1;
}

// Function to read the proximity value from the Si1145
int si1145_read_proximity(int fd) {
    int retries = 3;
    while (retries > 0) {
        int ps1_low = si1145_read_register(fd, 0x24);
        int ps1_high = si1145_read_register(fd, 0x25);

        if (ps1_low >= 0 && ps1_high >= 0) {
            return (ps1_high << 8) | ps1_low;
        } else {
            fprintf(stderr, "Error reading proximity, retrying...\n");
            usleep(10000); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read proximity after multiple retries.\n");
    return -1;
}

// Function to log the ambient light and proximity values to a file
void log_data(FILE *fp, int ambient_light, int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,AmbientLight:%d,Proximity:%d\n", timestamp, ambient_light, proximity);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int ambient_light = si1145_read_ambient_light(i2c_fd);
        int proximity = si1145_read_proximity(i2c_fd);

        if (ambient_light >= 0 && proximity >= 0) {
            log_data(log_file, ambient_light, proximity);

            if (proximity > PROXIMITY_THRESHOLD) {
                gpioWrite(LED_GPIO, 1); // Turn on LED
            } else {
                gpioWrite(LED_GPIO, 0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        usleep(100000); // 100ms delay
    }

    return 0;
}

