#define ALERT_PIN 17

// Define seismic event duration
#define SEISMIC_DURATION 500 // milliseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int open_log_file();
void close_log_file();
void seismic_event_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);
void log_seismic_event();

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    uint32_t start_time;
} SensorData;

SensorData sensor_data = {0, 0, 0};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    if (open_log_file() != 0) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Set alert pin as output
    gpioSetMode(ALERT_PIN, PI_OUTPUT);
    gpioWrite(ALERT_PIN, 0); // Ensure it starts LOW

    // Register callback functions for both sensors
    if (gpioSetAlertFuncEx(SENSOR1_PIN, seismic_event_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register callback for sensor 1. Exiting.\n");
        close_log_file();
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFuncEx(SENSOR2_PIN, seismic_event_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register callback for sensor 2. Exiting.\n");
        close_log_file();
        gpioTerminate();
        return 1;
    }

    printf("Seismic monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Do other tasks here if needed
        gpioDelay(100); // Check every 100ms
    }

    // Cleanup
    close_log_file();
    gpioWrite(ALERT_PIN, 0); // Ensure alert pin is LOW
    gpioTerminate();

    printf("Seismic monitor stopped.\n");
    return 0;
}

