void seismic_event_callback(int gpio, int level, uint32_t tick) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (gpio == SENSOR1_PIN) {
        sensor_data.sensor1_state = level;
    } else if (gpio == SENSOR2_PIN) {
        sensor_data.sensor2_state = level;
    }

    if (sensor_data.sensor1_state == 1 && sensor_data.sensor2_state == 1) {
        if (sensor_data.start_time == 0) {
            sensor_data.start_time = tick;
        } else {
            if (tick - sensor_data.start_time >= SEISMIC_DURATION * 1000) { // Convert ms to us
                log_seismic_event();
                sensor_data.start_time = 0; // Reset start time after logging
            }
        }
    } else {
        sensor_data.start_time = 0; // Reset start time if either sensor is LOW
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    running = 0;
}

// Log seismic event to file
void log_seismic_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
    fflush(log_file); // Ensure data is written to file immediately

    // Trigger alert
    gpioWrite(ALERT_PIN, 1);
    gpioDelay(2000); // 2 seconds
    gpioWrite(ALERT_PIN, 0);
}

