#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define CE0_PIN 8
#define SCLK_PIN 11
#define MOSI_PIN 10
#define MISO_PIN 9
#define LED_PIN 17

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define circular buffer size
#define BUFFER_SIZE 100

// Define gyroscope sensitivity (degrees per second per LSB)
#define GYRO_SENSITIVITY 0.03125

// Define threshold for angular rate (degrees per second)
#define THRESHOLD 20.0

// Structure to store gyroscope data
typedef struct {
    struct timespec timestamp;
    float angular_rate_x;
} gyro_data_t;

// Circular buffer
gyro_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// SPI handle
int spi_handle;

// Function prototypes
int spi_read_register(int handle, uint8_t address);
int spi_write_register(int handle, uint8_t address, uint8_t data);
void add_to_buffer(gyro_data_t data);
gyro_data_t get_from_buffer(int index);
void signal_handler(int signal);
void control_led(int state);

// Function to read a register via SPI
int spi_read_register(int handle, uint8_t address) {
    char tx_buf[2];
    char rx_buf[2];

    // Set MSB of address to 1 for read
    tx_buf[0] = address | 0x80; // Set MSB to 1 for read
    tx_buf[1] = 0x00; // Dummy byte for reading

    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 0) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1; // Indicate error
    }

    return rx_buf[1];
}

// Function to write a register via SPI
int spi_write_register(int handle, uint8_t address, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = address & 0x7F; // Set MSB to 0 for write
    tx_buf[1] = data;

    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 0) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1; // Indicate error
    }

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(gyro_data_t data) {
    circular_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to get data from the circular buffer
gyro_data_t get_from_buffer(int index) {
    return circular_buffer[index];
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    spiClose(spi_handle);
    control_led(0); // Turn off LED
    gpioTerminate();
    exit(0);
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(CE0_PIN, PI_OUTPUT);
    gpioSetMode(SCLK_PIN, PI_OUTPUT);
    gpioSetMode(MOSI_PIN, PI_OUTPUT);
    gpioSetMode(MISO_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ADXRS290 (example: set to continuous measurement mode)
    if (spi_write_register(spi_handle, 0x02, 0x00) < 0) { // Example register and value
        fprintf(stderr, "ADXRS290 configuration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Gyroscope monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read angular rate X from the gyroscope
        int16_t raw_data = spi_read_register(spi_handle, 0x04); // Example register
        if (raw_data < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            continue; // Skip to the next iteration
        }

        // Convert raw data to degrees per second
        float angular_rate_x = (float)raw_data * GYRO_SENSITIVITY;

        // Get timestamp
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);

        // Create gyroscope data struct
        gyro_data_t gyro_data;
        gyro_data.timestamp = ts;
        gyro_data.angular_rate_x = angular_rate_x;

        // Add data to the circular buffer
        add_to_buffer(gyro_data);

        // Check if angular rate exceeds threshold
        if (fabs(angular_rate_x) > THRESHOLD) {
            control_led(1); // Turn on LED
        } else {
            control_led(0); // Turn off LED
        }

        // Print angular rate and timestamp
        printf("Timestamp: %ld.%09ld, Angular Rate X: %.2f deg/s\n", ts.tv_sec, ts.tv_nsec, angular_rate_x);

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

