#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM frequency (100 Hz)
#define PWM_FREQUENCY 100

// Define PWM range (0-255)
#define PWM_RANGE 255

// Global variable to store the total duration in seconds
int total_duration = 0;

// Function prototypes
int initialize_gpio();
void set_lamp_brightness(int gpio, int brightness);
void fade_lamp(int gpio, int duration);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO pins and PWM
int initialize_gpio() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM frequency and range for each lamp
    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE);

    return 0; // Indicate success
}

// Function to set the brightness of a lamp
void set_lamp_brightness(int gpio, int brightness) {
    gpioPWM(gpio, brightness);
}

// Function to fade a lamp over a given duration
void fade_lamp(int gpio, int duration) {
    int steps = duration * PWM_FREQUENCY; // Calculate number of steps
    float increment = (float)PWM_RANGE / steps; // Calculate increment per step

    // Fade in
    for (int i = 0; i <= steps; i++) {
        set_lamp_brightness(gpio, (int)(increment * i));
        gpioDelay(1000000 / PWM_FREQUENCY); // Delay for PWM period
    }

    // Fade out
    for (int i = steps; i >= 0; i--) {
        set_lamp_brightness(gpio, (int)(increment * i));
        gpioDelay(1000000 / PWM_FREQUENCY); // Delay for PWM period
    }

    set_lamp_brightness(gpio, 0); // Ensure lamp is off after fade
}

// Function to cleanup GPIO pins and terminate pigpio
void cleanup_gpio() {
    // Turn off all lamps
    set_lamp_brightness(LAMP1_GPIO, 0);
    set_lamp_brightness(LAMP2_GPIO, 0);
    set_lamp_brightness(LAMP3_GPIO, 0);

    // Terminate pigpio library
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Check for command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_duration_in_seconds>\n", argv[0]);
        return 1;
    }

    // Parse command-line argument
    total_duration = atoi(argv[1]);

    // Validate command-line argument
    if (total_duration < 1 || total_duration > 3600) {
        fprintf(stderr, "Error: Total duration must be between 1 and 3600 seconds\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sunset simulator started. Total duration: %d seconds\n", total_duration);

    // Fade lamps sequentially
    fade_lamp(LAMP1_GPIO, total_duration / 3);
    fade_lamp(LAMP2_GPIO, total_duration / 3);
    fade_lamp(LAMP3_GPIO, total_duration / 3);

    printf("Sunset simulator completed.\n");

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

