#include <pigpio.h>

// Define GPIO pins for relays
#define RED_RELAY 17
#define YELLOW_RELAY 22
#define GREEN_RELAY 23
#define YELLOW2_RELAY 24

// Traffic light sequence
const int sequence[] = {RED_RELAY, YELLOW_RELAY, GREEN_RELAY, YELLOW2_RELAY};
const int durations[] = {10, 2, 10, 3};
const int sequence_length = sizeof(sequence) / sizeof(sequence[0]);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Deactivate all relays
    gpioWrite(RED_RELAY, 1);
    gpioWrite(YELLOW_RELAY, 1);
    gpioWrite(GREEN_RELAY, 1);
    gpioWrite(YELLOW2_RELAY, 1);

    // Terminate pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    int i, j;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_RELAY, PI_OUTPUT);
    gpioSetMode(YELLOW_RELAY, PI_OUTPUT);
    gpioSetMode(GREEN_RELAY, PI_OUTPUT);
    gpioSetMode(YELLOW2_RELAY, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        for (i = 0; i < sequence_length; i++) {
            // Activate relay
            gpioWrite(sequence[i], 0);
            printf("Activating relay on GPIO %d\n", sequence[i]);

            // Wait for duration
            sleep(durations[i]);

            // Deactivate relay
            gpioWrite(sequence[i], 1);
            printf("Deactivating relay on GPIO %d\n", sequence[i]);
        }
    }

    return 0;
}

