#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23

// Define constants
#define FLAME_DETECTED_LOG_FILE "flame_log.txt"
#define FLAME_DETECTED_LOG_MESSAGE "Flame Detected"
#define FLAME_CLEAR_LOG_MESSAGE "Flame Cleared"
#define FLAME_DETECTED_DURATION_MS 2000
#define FLAME_READ_INTERVAL_MS 50
#define FLAME_READ_COUNT 3

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_flame_sensor();
void log_event(const char *message);
void activate_buzzer_led();
void deactivate_buzzer_led();
void signal_handler(int signal);

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to log an event to the log file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to activate the buzzer and LED
void activate_buzzer_led() {
    gpioWrite(BUZZER_PIN, 1);
    gpioWrite(LED_PIN, 1);
}

// Function to deactivate the buzzer and LED
void deactivate_buzzer_led() {
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    deactivate_buzzer_led(); // Ensure buzzer and LED are off
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open the log file
    log_file = fopen(FLAME_DETECTED_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int flame_detected_count = 0;
    int last_flame_state = 1; // Assume no flame initially (active low)

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_flame_state = read_flame_sensor();

        if (current_flame_state == 0 && last_flame_state == 1) {
            // Flame detected
            flame_detected_count++;
            if (flame_detected_count == FLAME_READ_COUNT) {
                log_event(FLAME_DETECTED_LOG_MESSAGE);
                activate_buzzer_led();
                gpioDelay(FLAME_DETECTED_DURATION_MS * 1000); // Delay in microseconds
                deactivate_buzzer_led();
                flame_detected_count = 0; // Reset counter
            }
        } else if (current_flame_state == 1 && last_flame_state == 0) {
            // Flame cleared
            flame_detected_count = 0; // Reset counter
            log_event(FLAME_CLEAR_LOG_MESSAGE);
        }

        last_flame_state = current_flame_state;
        gpioDelay(FLAME_READ_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_buzzer_led();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

