volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void activate_solenoid(int pin, int duration_ms);
void deactivate_solenoid(int pin);
void log_dispense_event(int solenoid1_pin, int solenoid2_pin, int duration_ms);
