    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Activate solenoid 1
