#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Motor GPIO pins
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENA 24
#define ENB 25

// PID parameters
#define KP 0.5
#define KI 0.1
#define KD 0.2

// Obstacle avoidance distance threshold
#define OBSTACLE_DISTANCE 20.0

// Socket parameters
#define PORT 12345
#define IP_ADDRESS "127.0.0.1" // Loopback for testing

// Global variables
static volatile int running = 1;
static int socket_desc;
static FILE *log_file;

// Function prototypes
float simulate_tilt_error();
float simulate_distance();
void set_motor_speed(int motor, int speed);
void stop_motors();
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void obstacle_avoidance();
void signal_handler(int signal);
int setup_socket();

// PID variables
float integral = 0.0;
float previous_error = 0.0;

// Function to simulate tilt error
float simulate_tilt_error() {
    return ((float)rand() / RAND_MAX) * 20.0 - 10.0;
}

// Function to simulate distance sensor reading
float simulate_distance() {
    return ((float)rand() / RAND_MAX) * 400.0 + 2.0;
}

// Function to set motor speed using pigpio
void set_motor_speed(int motor, int speed) {
    if (speed > 255) speed = 255;
    if (speed < -255) speed = -255;

    if (motor == 1) { // Motor A
        if (speed > 0) {
            gpioWrite(MOTOR_A_FORWARD, 1);
            gpioWrite(MOTOR_A_BACKWARD, 0);
            gpioPWM(ENA, speed);
        } else if (speed < 0) {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 1);
            gpioPWM(ENA, -speed);
        } else {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 0);
            gpioPWM(ENA, 0);
        }
    } else if (motor == 2) { // Motor B
        if (speed > 0) {
            gpioWrite(MOTOR_B_FORWARD, 1);
            gpioWrite(MOTOR_B_BACKWARD, 0);
            gpioPWM(ENB, speed);
        } else if (speed < 0) {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 1);
            gpioPWM(ENB, -speed);
        } else {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 0);
            gpioPWM(ENB, 0);
        }
    }
}

// Function to stop both motors
void stop_motors() {
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
}

// Function to log data to file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to handle obstacle avoidance
void obstacle_avoidance() {
    set_motor_speed(1, -128); // Reverse Motor A
    set_motor_speed(2, -128); // Reverse Motor B
    gpioDelay(500);           // Reverse for 500ms
    stop_motors();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    running = 0;
    stop_motors();
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to set up the socket
int setup_socket() {
    struct sockaddr_in server;

    // Create socket
    socket_desc = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_desc == -1) {
        perror("Could not create socket");
        return 1;
    }

    server.sin_addr.s_addr = inet_addr(IP_ADDRESS);
    server.sin_family = AF_INET;
    server.sin_port = htons(PORT);

    // Connect to remote server
    if (connect(socket_desc, (struct sockaddr *)&server, sizeof(server)) < 0) {
        perror("Connect failed. Error");
        return 1;
    }

    puts("Connected\n");
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(ENA, 255);
    gpioSetPWMrange(ENB, 255);

    // Open log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Set up socket
    if (setup_socket() != 0) {
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    srand(time(NULL)); // Seed random number generator

    while (running) {
        // Simulate tilt error and distance
        float tilt_error = simulate_tilt_error();
        float distance = simulate_distance();

        // PID control
        float error = tilt_error;
        integral += error;
        float derivative = error - previous_error;
        float output = KP * error + KI * integral + KD * derivative;

        // Motor speeds (example: adjust based on PID output)
        int motor_a_speed = (int)output;
        int motor_b_speed = (int)output;

        // Obstacle avoidance
        if (distance < OBSTACLE_DISTANCE) {
            obstacle_avoidance();
            motor_a_speed = 0; // Stop motors after obstacle avoidance
            motor_b_speed = 0;
        }

        // Set motor speeds
        set_motor_speed(1, motor_a_speed);
        set_motor_speed(2, motor_b_speed);

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Receive data from socket
        char buffer[256];
        ssize_t bytes_received = recv(socket_desc, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            printf("Received: %s\n", buffer);
        } else if (bytes_received == 0) {
            printf("Server disconnected\n");
            running = 0;
        } else {
            perror("recv failed");
        }

        gpioDelay(50); // Control loop frequency
        previous_error = error;
    }

    // Clean up
    stop_motors();
    gpioTerminate();
    fclose(log_file);
    close(socket_desc);

    return 0;
}

