#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY_MS 50

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set touch sensor pin as input with pull-down resistor
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO%d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    // Set relay pin as output
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay state
void toggle_relay() {
    int current_state = gpioRead(RELAY_PIN);
    gpioWrite(RELAY_PIN, !current_state);
}

// Function to implement debounce delay
void debounce_delay() {
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert milliseconds to microseconds
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (read_touch_sensor() == 1) {
            toggle_relay();
            debounce_delay();
        }
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    // Cleanup and exit
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off before exiting
    gpioTerminate();
    fprintf(stderr, "Program terminated.\n");
    return 0;
}

