    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay state
void toggle_relay() {
    int current_state = gpioRead(RELAY_PIN);
    gpioWrite(RELAY_PIN, !current_state);
}

// Function to implement debounce delay
void debounce_delay() {
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert milliseconds to microseconds
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (read_touch_sensor() == 1) {
            toggle_relay();
            debounce_delay();
        }
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    // Cleanup and exit
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off before exiting
    gpioTerminate();
    fprintf(stderr, "Program terminated.\n");
    return 0;
}

