#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define ALSA parameters
#define SAMPLE_RATE 8000
#define FORMAT      SND_PCM_FORMAT_S16_LE
#define CHANNELS    1
#define PERIOD_SIZE 1024

// Define PWM frequency (adjust as needed)
#define PWM_FREQUENCY 1000

// Define PWM range (adjust as needed)
#define PWM_RANGE 1000

// Define RMS window size (in frames)
#define RMS_WINDOW_SIZE 10

// Define scaling factor for RMS amplitude
#define RMS_SCALE 1.0

// Define a structure to hold RGB color values
typedef struct {
    int red;
    int green;
    int blue;
} rgb_color_t;

// Global variables
snd_pcm_t *pcm_handle = NULL;
double rms_history[RMS_WINDOW_SIZE];
int rms_index = 0;
double rms_sum = 0.0;
double rms_average = 0.0;
double sensitivity = 1.0;
int running = 1;

// Function prototypes
int init_alsa(snd_pcm_t **pcm_handle);
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int buffer_size);
double calculate_rms(short *buffer, int buffer_size);
rgb_color_t map_rms_to_color(double rms_amplitude);
void set_rgb_color(int red, int green, int blue);
void cleanup();
void signal_handler(int signum);

// Function to initialize ALSA
int init_alsa(snd_pcm_t **pcm_handle) {
    snd_pcm_hw_params_t *hw_params;
    int err;

    if ((err = snd_pcm_open(pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening ALSA device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, FORMAT)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_period_size(*pcm_handle, hw_params, PERIOD_SIZE, 0)) < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Function to capture audio data
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int buffer_size) {
    int err;
    int frames = buffer_size / CHANNELS;

    while (frames > 0) {
        int result = snd_pcm_readi(pcm_handle, buffer, frames);
        if (result == -EPIPE) {
            fprintf(stderr, "Overrun occurred\n");
            snd_pcm_prepare(pcm_handle);
        } else if (result < 0) {
            fprintf(stderr, "Error reading audio: %s\n", snd_strerror(result));
            return -1;
        } else if (result != frames) {
            fprintf(stderr, "Short read, read %d frames\n", result);
        }
        frames -= result;
    }
    return 0;
}

// Function to calculate RMS amplitude
double calculate_rms(short *buffer, int buffer_size) {
    double sum_sq = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum_sq += (double)buffer[i] * buffer[i];
    }
    double mean_sq = sum_sq / buffer_size;
    return sqrt(mean_sq) * RMS_SCALE;
}

// Function to map RMS amplitude to RGB color
rgb_color_t map_rms_to_color(double rms_amplitude) {
    rgb_color_t color;

    // Normalize RMS amplitude to the range [0, 1]
    double normalized_amplitude = rms_amplitude / 1000.0; // Assuming max RMS amplitude is 1000
    if (normalized_amplitude > 1.0) normalized_amplitude = 1.0;
    if (normalized_amplitude < 0.0) normalized_amplitude = 0.0;

    // Map RMS amplitude to RGB values using a non-linear function
    // Example: Use a logarithmic mapping
    double red_value = 255.0 * pow(normalized_amplitude, 0.5); // Adjust exponent for desired mapping
    double green_value = 255.0 * pow(normalized_amplitude, 0.5);
    double blue_value = 255.0 * pow(normalized_amplitude, 0.5);

    // Clamp RGB values to the range [0, 255]
    if (red_value > 255.0) red_value = 255.0;
    if (green_value > 255.0) green_value = 255.0;
    if (blue_value > 255.0) blue_value = 255.0;

    if (red_value < 0.0) red_value = 0.0;
    if (green_value < 0.0) green_value = 0.0;
    if (blue_value < 0.0) blue_value = 0.0;

    color.red = (int)red_value;
    color.green = (int)green_value;
    color.blue = (int)blue_value;

    return color;
}

// Function to set RGB color using software PWM
void set_rgb_color(int red, int green, int blue) {
    // Calculate PWM duty cycles for each color component
    int red_duty_cycle = (int)(((double)red / 255.0) * PWM_RANGE);
    int green_duty_cycle = (int)(((double)green / 255.0) * PWM_RANGE);
    int blue_duty_cycle = (int)(((double)blue / 255.0) * PWM_RANGE);

    // Set PWM duty cycles for each color channel
    gpioPWM(RED_PIN, red_duty_cycle);
    gpioPWM(GREEN_PIN, green_duty_cycle);
    gpioPWM(BLUE_PIN, blue_duty_cycle);
}

// Function to clean up resources
void cleanup() {
    printf("Cleaning up...\n");

    // Stop PWM
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);

    // Close ALSA device
    if (pcm_handle != NULL) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    printf("Signal received (%d).  Shutting down...\n", signum);
    running = 0;
    cleanup();
    exit(0);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        sensitivity = atof(argv[1]);
        printf("Using sensitivity factor: %f\n", sensitivity);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    // Initialize ALSA
    if (init_alsa(&pcm_handle) < 0) {
        fprintf(stderr, "ALSA initialisation failed\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Allocate memory for audio buffer
    short *audio_buffer = (short *)malloc(PERIOD_SIZE * sizeof(short));
    if (audio_buffer == NULL) {
        fprintf(stderr, "Failed to allocate memory for audio buffer\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Capture audio
        if (capture_audio(pcm_handle, audio_buffer, PERIOD_SIZE) < 0) {
            fprintf(stderr, "Audio capture failed\n");
            break;
        }

        // Calculate RMS amplitude
        double rms_amplitude = calculate_rms(audio_buffer, PERIOD_SIZE);

        // Update RMS history
        rms_sum -= rms_history[rms_index];
        rms_sum += rms_amplitude;
        rms_history[rms_index] = rms_amplitude;
        rms_index = (rms_index + 1) % RMS_WINDOW_SIZE;
        rms_average = rms_sum / RMS_WINDOW_SIZE;

        // Map RMS amplitude to RGB color
        rgb_color_t color = map_rms_to_color(rms_average);

        // Set RGB color
        set_rgb_color(color.red, color.green, color.blue);

        // Print status message
        printf("RMS Amplitude: %f, Red: %d, Green: %d, Blue: %d\n", rms_amplitude, color.red, color.green, color.blue);

        // Sleep for 10ms
        usleep(10000); // 10ms
    }

    // Free memory
    free(audio_buffer);

    // Clean up resources
    cleanup();

    return 0;
}

