#define TCS34725_I2C_ADDR 0x29

// TCS34725 registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x90
#define TCS34725_RDATA 0x92
#define TCS34725_GDATA 0x94
#define TCS34725_BDATA 0x96

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the TCS34725 sensor
int init_tcs34725() {
    // Enable the sensor (power on and ADC enable)
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: Could not enable sensor\n");
        return -1;
    }

    // Set integration time to 154ms (ATIME = 0xEB)
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xEB) < 0) {
        fprintf(stderr, "Error: Could not set integration time\n");
        return -1;
    }

    return 0;
}

