#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define the duration of each phase in seconds
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 95040

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a relay
int set_relay_state(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO pin %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to toggle the state of a relay
int toggle_relay(int gpio_pin) {
    int current_state = gpioRead(gpio_pin);
    if (current_state == PI_HIGH) {
        return set_relay_state(gpio_pin, PI_LOW);
    } else {
        return set_relay_state(gpio_pin, PI_HIGH);
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Sunrise phase
        printf("Sunrise phase\n");
        for (int i = 0; i < SUNRISE_DURATION && program_running; ++i) {
            toggle_relay(RELAY1_PIN);
            toggle_relay(RELAY2_PIN);
            toggle_relay(RELAY3_PIN);
            toggle_relay(RELAY4_PIN);
            gpioDelay(1000000); // 1 second delay
        }

        // Daytime phase
        printf("Daytime phase\n");
        for (int i = 0; i < DAYTIME_DURATION && program_running; ++i) {
            // Do nothing, just wait
            gpioDelay(1000000); // 1 second delay
        }

        // Sunset phase
        printf("Sunset phase\n");
        for (int i = 0; i < SUNSET_DURATION && program_running; ++i) {
            toggle_relay(RELAY1_PIN);
            toggle_relay(RELAY2_PIN);
            toggle_relay(RELAY3_PIN);
            toggle_relay(RELAY4_PIN);
            gpioDelay(1000000); // 1 second delay
        }

        // Nighttime phase
        printf("Nighttime phase\n");
        for (int i = 0; i < NIGHTTIME_DURATION && program_running; ++i) {
            // Do nothing, just wait
            gpioDelay(1000000); // 1 second delay
        }
    }

    // Turn off all relays before exiting
    printf("Turning off all relays...\n");
    set_relay_state(RELAY1_PIN, PI_HIGH);
    set_relay_state(RELAY2_PIN, PI_HIGH);
    set_relay_state(RELAY3_PIN, PI_HIGH);
    set_relay_state(RELAY4_PIN, PI_HIGH);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

