#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define VIDEO_DURATION_S 5
#define LOG_FILE "/home/pi/logs/motion_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    printf("Monitoring GPIO %d for motion...\n", GPIO_PIN);

    while (running) {
        if (gpioRead(GPIO_PIN) == 0) {
            // Motion detected
            printf("Motion detected!\n");

            // Debounce
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds

            // Capture video
            time_t rawtime;
            struct tm *timeinfo;
            char filename[80];
            char command[256];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(filename, sizeof(filename), "/home/pi/videos/%Y%m%d_%H%M%S.h264", timeinfo);

            snprintf(command, sizeof(command), "raspivid -o %s -t %d", filename, VIDEO_DURATION_S * 1000); // Convert seconds to milliseconds

            int result = system(command);
            if (result == -1) {
                perror("Failed to execute raspivid command");
            } else if (WEXITSTATUS(result) != 0) {
                fprintf(stderr, "raspivid command failed with exit code %d\n", WEXITSTATUS(result));
            }

            // Log event
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            fprintf(log_file, "%s Motion detected\n", timestamp);
            fflush(log_file);

            printf("Video saved to %s\n", filename);
        }
        gpioDelay(10000); // Check every 10ms
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

