#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Scaling factor for gyroscope data (±250°/s range)
#define GYRO_SCALE 131.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    double x;
    double y;
    double z;
} gyro_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the MPU6050
int init_mpu6050() {
    int retries = 3;
    int status;

    while (retries > 0) {
        // Wake up the MPU6050 (clear sleep bit)
        status = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0);
        if (status >= 0) {
            // Configure gyroscope range to ±250°/s
            status = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0);
            if (status >= 0) {
                return 0; // Success
            } else {
                fprintf(stderr, "Error writing to GYRO_CONFIG: %d\n", status);
            }
        } else {
            fprintf(stderr, "Error writing to PWR_MGMT_1: %d\n", status);
        }

        retries--;
        gpioDelay(100); // Wait before retrying
    }

    fprintf(stderr, "Failed to initialize MPU6050 after multiple retries.\n");
    return -1; // Failure
}

// Function to read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;
    int status;

    status = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6);
    if (status != 6) {
        fprintf(stderr, "Error reading gyro data: %d\n", status);
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert to degrees per second
    data->x = (double)raw_x / GYRO_SCALE;
    data->y = (double)raw_y / GYRO_SCALE;
    data->z = (double)raw_z / GYRO_SCALE;

    return 0;
}

// Function to log data to a file
int log_data(gyro_data_t data) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", buf, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU6050 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gyro_data_t gyro_data;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Log data to file
            log_data(gyro_data);
        } else {
            fprintf(stderr, "Failed to read gyro data. Attempting to re-initialize...\n");
            // Attempt to re-initialize the sensor
            i2cClose(i2c_handle);
            gpioDelay(1000); // Wait before re-initializing
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (init_mpu6050() != 0) {
                    fprintf(stderr, "MPU6050 re-initialization failed\n");
                    terminate = 1;
                }
            }
        }

        // Delay for 10ms (100Hz sampling rate)
        gpioDelay(10);
    }

    // Close log file and I2C bus
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

