// Define GPIO pins for relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define moisture threshold
#define MOISTURE_THRESHOLD 30

// Define log file name
#define LOG_FILE "irrigation_log.txt"

// Function prototypes
int initialize_gpio();
int read_moisture_sensor();
void control_relay(int zone, int moisture);
void log_data(int moisture, int zone1_state, int zone2_state, int zone3_state, int zone4_state);
void signal_handler(int signal);

// Global variable for log file pointer
FILE *log_file = NULL;

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize relays to OFF (HIGH) state
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0; // Indicate success
}

// Function to simulate reading the moisture sensor
int read_moisture_sensor() {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Generate a random number between 0 and 100
    int moisture = rand() % 101;

    return moisture;
}

// Function to control the relay based on moisture level
void control_relay(int zone, int moisture) {
    int gpio_pin;
    int state;

    switch (zone) {
        case 1:
            gpio_pin = RELAY1_PIN;
            break;
        case 2:
            gpio_pin = RELAY2_PIN;
            break;
        case 3:
            gpio_pin = RELAY3_PIN;
            break;
        case 4:
            gpio_pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid zone number: %d\n", zone);
            return;
    }

    if (moisture < MOISTURE_THRESHOLD) {
        state = 0; // Dry, activate relay (LOW)
    } else {
        state = 1; // Wet, deactivate relay (HIGH)
    }

    // Set the GPIO pin to the appropriate state
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO pin %d\n", gpio_pin);
    }
}

// Function to log data to a file
void log_data(int moisture, int zone1_state, int zone2_state, int zone3_state, int zone4_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Moisture: %d, Zone1: %s, Zone2: %s, Zone3: %s, Zone4: %s\n",
            timestamp,
            moisture,
            zone1_state == 0 ? "ON" : "OFF",
            zone2_state == 0 ? "ON" : "OFF",
            zone3_state == 0 ? "ON" : "OFF",
            zone4_state == 0 ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Deactivate all relays
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read moisture sensor
        int moisture = read_moisture_sensor();

        // Control relays
        control_relay(1, moisture);
        control_relay(2, moisture);
        control_relay(3, moisture);
        control_relay(4, moisture);

        // Get relay states
        int zone1_state = gpioRead(RELAY1_PIN);
        int zone2_state = gpioRead(RELAY2_PIN);
        int zone3_state = gpioRead(RELAY3_PIN);
        int zone4_state = gpioRead(RELAY4_PIN);

        // Log data
        log_data(moisture, zone1_state, zone2_state, zone3_state, zone4_state);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    return 0;
}

