#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_ADDR 0x53
#define I2C_BUS 1
#define ALARM_GPIO 27
#define FREEFALL_THRESHOLD 0.2f // g
#define FREEFALL_DURATION 0.5f  // seconds
#define FREEFALL_CONFIRMATION 0.5f // seconds
#define ALARM_DURATION 5.0f      // seconds
#define POLL_INTERVAL_MS 100

// ADXL345 Registers
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37

// Global variables
int i2c_handle;
bool alarm_active = false;
FILE *log_file;

// Function prototypes
int init_i2c();
int read_acceleration(float *x, float *y, float *z);
bool detect_freefall(float x, float y, float z);
void confirm_freefall(float x, float y, float z);
void trigger_alarm();
void log_freefall(float x, float y, float z);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL345
int read_acceleration(float *x, float *y, float *z) {
    char raw_data[6];
    int16_t x_raw, y_raw, z_raw;

    if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, raw_data, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    x_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    y_raw = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    z_raw = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to g's (assuming +/- 2g range and 10-bit resolution)
    *x = (float)x_raw / 256.0f;
    *y = (float)y_raw / 256.0f;
    *z = (float)z_raw / 256.0f;

    return 0;
}

// Function to detect freefall
bool detect_freefall(float x, float y, float z) {
    return (fabs(x) < FREEFALL_THRESHOLD && fabs(y) < FREEFALL_THRESHOLD && fabs(z) < FREEFALL_THRESHOLD);
}

// Function to confirm freefall
void confirm_freefall(float x, float y, float z) {
    gpioDelay(FREEFALL_CONFIRMATION * 1000000); // Delay for confirmation period
    float x2, y2, z2;
    if (read_acceleration(&x2, &y2, &z2) == 0) {
        if (fabs(x2) < FREEFALL_THRESHOLD && fabs(y2) < FREEFALL_THRESHOLD && fabs(z2) < FREEFALL_THRESHOLD) {
            trigger_alarm();
            log_freefall(x, y, z);
        }
    }
}

// Function to trigger the alarm
void trigger_alarm() {
    if (!alarm_active) {
        gpioWrite(ALARM_GPIO, 1); // Set GPIO high
        alarm_active = true;
        gpioDelay(ALARM_DURATION * 1000000); // Delay for alarm duration
        gpioWrite(ALARM_GPIO, 0); // Set GPIO low
        alarm_active = false;
    }
}

// Function to log freefall data
void log_freefall(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set alarm GPIO as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Ensure it starts low

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    float x, y, z;

    // Main loop
    while (1) {
        if (read_acceleration(&x, &y, &z) == 0) {
            if (detect_freefall(x, y, z)) {
                confirm_freefall(x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Delay for polling interval
    }

    return 0;
}

