#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 100000      // 100ms timeout
#define MAX_PULSE_WIDTH_US 23200 // 4m range
#define MIN_PULSE_WIDTH_US 0
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static uint32_t start_tick = 0;
static uint32_t end_tick = 0;
static uint32_t last_trigger_tick = 0;

// Function prototypes
void trigger_pulse();
void echo_rising_edge(int gpio, int level, uint32_t tick);
void echo_falling_edge(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width_us);
void log_distance(double distance_cm);
void signal_handler(int signal);
void cleanup();

// Function to generate a 10us trigger pulse
void trigger_pulse() {
  gpioWrite(TRIG_PIN, 1);
  gpioDelay(10);
  gpioWrite(TRIG_PIN, 0);
}

// Function to handle rising edge of the echo pulse
void echo_rising_edge(int gpio, int level, uint32_t tick) {
  pthread_mutex_lock(&mutex);
  start_tick = tick;
  pthread_mutex_unlock(&mutex);
}

// Function to handle falling edge of the echo pulse
void echo_falling_edge(int gpio, int level, uint32_t tick) {
  pthread_mutex_lock(&mutex);
  end_tick = tick;
  pthread_mutex_unlock(&mutex);
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_width_us) {
  if (pulse_width_us < MIN_PULSE_WIDTH_US || pulse_width_us > MAX_PULSE_WIDTH_US) {
    return -1.0; // Invalid pulse width
  }
  return (double)pulse_width_us * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log distance to file
void log_distance(double distance_cm) {
  struct timespec ts;
  clock_gettime(CLOCK_REALTIME, &ts);
  uint64_t timestamp_ns = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;

  pthread_mutex_lock(&mutex);
  if (log_file != NULL) {
    fprintf(log_file, "%llu,%.2f\n", timestamp_ns, distance_cm);
    fflush(log_file); // Ensure data is written to disk immediately
  }
  pthread_mutex_unlock(&mutex);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
  running = 0;
  printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
  printf("Cleaning up...\n");
  gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL); // Disable interrupts
  if (log_file != NULL) {
    fclose(log_file);
  }
  gpioTerminate();
  pthread_mutex_destroy(&mutex);
  printf("Cleanup complete.\n");
}

int main() {
  // Initialize pigpio library
  if (gpioInitialise() < 0) {
    fprintf(stderr, "pigpio initialisation failed\n");
    return 1;
  }

  // Set GPIO modes
  gpioSetMode(TRIG_PIN, PI_OUTPUT);
  gpioSetMode(ECHO_PIN, PI_INPUT);

  // Initialize log file
  log_file = fopen("distance_log.txt", "a");
  if (log_file == NULL) {
    fprintf(stderr, "Error opening log file!\n");
    gpioTerminate();
    return 1;
  }

  // Set up signal handler for Ctrl+C
  signal(SIGINT, signal_handler);

  // Set up interrupt callbacks
  gpioSetAlertFuncEx(ECHO_PIN, echo_rising_edge, NULL);
  gpioSetAlertFuncEx(ECHO_PIN, echo_falling_edge, NULL);

  uint32_t current_tick = gpioTick();
  last_trigger_tick = current_tick;

  printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

  while (running) {
    current_tick = gpioTick();

    // Check if it's time to trigger the sensor
    if (current_tick - last_trigger_tick > 200000) { // 200ms delay
      trigger_pulse();
      last_trigger_tick = current_tick;
    }

    // Check for echo pulse
    pthread_mutex_lock(&mutex);
    uint32_t pulse_width = end_tick - start_tick;
    pthread_mutex_unlock(&mutex);

    if (pulse_width > 0) {
      double distance = calculate_distance(pulse_width);

      if (distance > 0) {
        if (distance >= MIN_DISTANCE_CM && distance <= MAX_DISTANCE_CM) {
          log_distance(distance);
        } else {
          fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
        }
      } else {
        fprintf(stderr, "Invalid pulse width: %u us\n", pulse_width);
      }

      // Reset pulse width for next measurement
      pthread_mutex_lock(&mutex);
      start_tick = 0;
      end_tick = 0;
      pthread_mutex_unlock(&mutex);
    } else {
      // Check for timeout
      if (current_tick - last_trigger_tick > TIMEOUT_US) {
        fprintf(stderr, "Timeout error: No echo received\n");
        last_trigger_tick = current_tick; // Reset trigger time to prevent immediate re-trigger
      }
    }

    gpioDelay(1000); // Delay for 1ms to reduce CPU usage
  }

  cleanup();
  return 0;
}

