#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define BUZZER_GPIO 17
#define G_PER_LSB 0.001 // 1 mg/LSB = 0.001 g/LSB

// Global variables
int i2c_handle;
double freefall_threshold = 0.2;
double impact_threshold = 1.5;
bool running = true;

// Function prototypes
int init_i2c();
int init_lis3dh();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void detect_freefall(double magnitude);
void detect_impact(double magnitude);
void activate_buzzer();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    running = false;
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Initialize I2C interface
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize LIS3DH accelerometer
int init_lis3dh() {
    // Configure CTRL_REG1: 100Hz data rate, enable all axes
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4: +/- 2g full scale
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }
    return 0;
}

// Read acceleration data from LIS3DH
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate acceleration magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    double x_g = x * G_PER_LSB;
    double y_g = y * G_PER_LSB;
    double z_g = z * G_PER_LSB;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Detect freefall
void detect_freefall(double magnitude) {
    if (magnitude < freefall_threshold) {
        printf("Freefall detected!\n");
    }
}

// Detect impact
void detect_impact(double magnitude) {
    if (magnitude > impact_threshold) {
        printf("Impact detected!\n");
        activate_buzzer();
    }
}

// Activate buzzer for 1 second
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Turn on buzzer
    gpioDelay(1000000);        // Wait for 1 second
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    double magnitude;

    // Main loop
    while (running) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);
            detect_freefall(magnitude);
            detect_impact(magnitude);
        } else {
            fprintf(stderr, "Error reading acceleration, retrying...\n");
            i2cClose(i2c_handle);
            if (init_i2c() < 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting.\n");
                running = false;
            }
            if (init_lis3dh() < 0) {
                fprintf(stderr, "Failed to re-initialize LIS3DH, exiting.\n");
                running = false;
            }
        }
        gpioDelay(10000); // 10ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

