int calculate_steps(float distance);
void stop_motors();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, stopping motors and exiting...\n");
        stop_motors();
        program_running = 0;
        exit(0);
    }
}

// Motor 1 (X-axis) step function
int motor1_step(int step) {
    if (gpioWrite(MOTOR1_IN1, step_sequence[step][0]) < 0) return -1;
    if (gpioWrite(MOTOR1_IN2, step_sequence[step][1]) < 0) return -1;
    if (gpioWrite(MOTOR1_IN3, step_sequence[step][2]) < 0) return -1;
    if (gpioWrite(MOTOR1_IN4, step_sequence[step][3]) < 0) return -1;
    return 0;
}

// Motor 2 (Y-axis) step function
int motor2_step(int step) {
    if (gpioWrite(MOTOR2_IN1, step_sequence[step][0]) < 0) return -1;
    if (gpioWrite(MOTOR2_IN2, step_sequence[step][1]) < 0) return -1;
    if (gpioWrite(MOTOR2_IN3, step_sequence[step][2]) < 0) return -1;
    if (gpioWrite(MOTOR2_IN4, step_sequence[step][3]) < 0) return -1;
    return 0;
}

// Move Motor 1 (X-axis) function
int move_motor1(int steps) {
    for (int i = 0; i < steps; i++) {
        if (motor1_step(i % 4) < 0) {
            fprintf(stderr, "Error: Failed to step motor 1.\n");
            return -1;
        }
        gpioDelay(1000); // 1000 us delay
    }
    return 0;
}

// Move Motor 2 (Y-axis) function
int move_motor2(int steps) {
    for (int i = 0; i < steps; i++) {
        if (motor2_step(i % 4) < 0) {
            fprintf(stderr, "Error: Failed to step motor 2.\n");
            return -1;
        }
        gpioDelay(1000); // 1000 us delay
    }
    return 0;
}

