#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// LIS3DH I2C address (default 0x18, can be 0x19 if SA0 is high)
#define LIS3DH_ADDR 0x18

// LIS3DH register addresses
#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG4 0x23
#define LIS3DH_OUT_X_L 0x28
#define LIS3DH_OUT_X_H 0x29
#define LIS3DH_OUT_Y_L 0x2A
#define LIS3DH_OUT_Y_H 0x2B
#define LIS3DH_OUT_Z_L 0x2C
#define LIS3DH_OUT_Z_H 0x2D

// Configuration values
#define DATA_RATE_100HZ 0x67  // 100 Hz, 12-bit, high resolution, all axes enabled
#define RANGE_2G 0x00         // ±2g range

// Global variables
int i2c_handle;
double threshold = 2.0; // Default threshold
bool shutdown_triggered = false;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int initialize_i2c(int addr);
int configure_lis3dh(int i2c_handle);
accelerometer_data_t read_accelerometer_data(int i2c_handle);
double calculate_magnitude(accelerometer_data_t data);
void log_acceleration_data(accelerometer_data_t data);
void shutdown_system();
void signal_handler(int signal);

// Function to initialize I2C
int initialize_i2c(int addr) {
    i2c_handle = i2cOpen(1, addr, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return i2c_handle;
}

// Function to configure LIS3DH
int configure_lis3dh(int i2c_handle) {
    // Configure CTRL_REG1: 100 Hz, all axes enabled
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG1, DATA_RATE_100HZ) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4: ±2g range, high resolution
    if (i2cWriteByteData(i2c_handle, LIS3DH_CTRL_REG4, RANGE_2G) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
accelerometer_data_t read_accelerometer_data(int i2c_handle) {
    accelerometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeros on error
        return data;
    }

    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Function to calculate acceleration magnitude
double calculate_magnitude(accelerometer_data_t data) {
    double x = (double)data.x;
    double y = (double)data.y;
    double z = (double)data.z;

    // Scale to g units (assuming 2g range, 12-bit resolution)
    x /= 16384.0; // 2^15
    y /= 16384.0;
    z /= 16384.0;

    return sqrt(x * x + y * y + z * z);
}

// Function to log acceleration data to file
void log_acceleration_data(accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    fprintf(fp, "%s, %d, %d, %d\n", timestamp, data.x, data.y, data.z);
    fclose(fp);
}

// Function to shutdown the system
void shutdown_system() {
    printf("Shutting down system...\n");
    system("sudo shutdown -h now");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    int opt;
    int i2c_address = LIS3DH_ADDR;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                if (i2c_address != 0x18 && i2c_address != 0x19) {
                    fprintf(stderr, "Invalid I2C address. Must be 0x18 or 0x19.\n");
                    return 1;
                }
                break;
            case 't':
                threshold = strtod(optarg, NULL);
                if (threshold <= 0) {
                    fprintf(stderr, "Threshold must be greater than 0.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(i2c_address) < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure LIS3DH
    if (configure_lis3dh(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        accelerometer_data_t data = read_accelerometer_data(i2c_handle);
        double magnitude = calculate_magnitude(data);

        if (magnitude > threshold && !shutdown_triggered) {
            log_acceleration_data(data);
            shutdown_system();
            shutdown_triggered = true; // Prevent repeated shutdowns
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup (should not reach here unless there's an error)
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

