#define BUFFER_SIZE 5

// Global variables
volatile sig_atomic_t program_running = 1;

// Circular buffer for left sensor readings
int left_buffer[BUFFER_SIZE];
int left_buffer_index = 0;

// Circular buffer for center sensor readings
int center_buffer[BUFFER_SIZE];
int center_buffer_index = 0;

