    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);

    // Set alert LED pin as output
    gpioSetMode(ALERT_LED_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int center_value = read_sensor(CENTER_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        // Update circular buffers
        update_buffer(left_buffer, &left_buffer_index, left_value);
        update_buffer(center_buffer, &center_buffer_index, center_value);
        update_buffer(right_buffer, &right_buffer_index, right_value);

        // Check if all sensors are reading 1
        if (check_buffer(center_buffer, BUFFER_SIZE)) {
            // All sensors are reading 1, move forward
            move_forward();
        } else if (check_buffer(left_buffer, BUFFER_SIZE)) {
            // Left sensor is reading 1, turn left
            turn_left();
        } else if (check_buffer(right_buffer, BUFFER_SIZE)) {
            // Right sensor is reading 1, turn right
            turn_right();
        } else {
            // All sensors are reading 0, stop
            stop();
            gpioWrite(ALERT_LED_PIN, 1); // Turn on LED
            gpioDelay(2000); // Wait for 2 seconds
            gpioWrite(ALERT_LED_PIN, 0); // Turn off LED
        }

        gpioDelay(10); // Delay for 10ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(ALERT_LED_PIN, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio

    return 0;
}

