#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x40
#define RELAY_GPIO 17
#define FIELD_THRESHOLD 5.0
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 3

// Si7210 Registers
#define SI7210_REG_FIELD_MSB 0x00
#define SI7210_REG_FIELD_LSB 0x01
#define SI7210_REG_CONFIG 0x02

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_si7210_field();
void control_relay(int state);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read magnetic field data from Si7210
int read_si7210_field() {
    int msb, lsb, retries = 0;
    int16_t raw_data;
    float field_mT;

    while (retries < MAX_RETRIES) {
        msb = i2cReadByteData(i2c_handle, SI7210_REG_FIELD_MSB);
        if (msb < 0) {
            log_event("Error reading MSB from Si7210");
            retries++;
            gpioDelay(10); // Small delay before retry
            continue;
        }

        lsb = i2cReadByteData(i2c_handle, SI7210_REG_FIELD_LSB);
        if (lsb < 0) {
            log_event("Error reading LSB from Si7210");
            retries++;
            gpioDelay(10);
            continue;
        }

        raw_data = (msb << 8) | lsb;
        field_mT = (float)raw_data / 10.0; // Conversion factor from datasheet
        return (int)field_mT; // Return the raw data
    }

    log_event("Timeout reading Si7210 data");
    return -1; // Indicate timeout error
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to log events to file
void log_event(const char *message) {
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
