#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 1024

// Global variables for graceful shutdown
int server_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int handle_client(int client_socket);
void log_event(const char *event);
void signal_handler(int signum);

// Function to log events to relay_log.txt
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened. Event: %s\n", event);
    }
}

// Function to handle client connections
int handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;

    bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
    if (bytes_received < 0) {
        perror("Error receiving data");
        log_event("Error receiving data");
        return -1;
    } else if (bytes_received == 0) {
        printf("Client disconnected\n");
        log_event("Client disconnected");
        return 0;
    }

    buffer[bytes_received] = '\0'; // Null-terminate the received data

    // Remove trailing whitespace
    size_t len = strlen(buffer);
    while (len > 0 && (buffer[len - 1] == '\n' || buffer[len - 1] == '\r')) {
        buffer[--len] = '\0';
    }

    printf("Received command: %s\n", buffer);

    if (strcasecmp(buffer, "ON") == 0) {
        gpioWrite(GPIO_PIN, 1); // Turn relay ON
        log_event("Relay ON");
        printf("Relay ON\n");
    } else if (strcasecmp(buffer, "OFF") == 0) {
        gpioWrite(GPIO_PIN, 0); // Turn relay OFF
        log_event("Relay OFF");
        printf("Relay OFF\n");
    } else {
        log_event("Invalid command received");
        fprintf(stderr, "Invalid command received: %s\n", buffer);
        const char *response = "Invalid command. Use ON or OFF.\n";
        send(client_socket, response, strlen(response), 0);
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        log_event("Received shutdown signal");

        // Turn off the relay
        gpioWrite(GPIO_PIN, 0);

        // Close the socket
        if (server_fd != -1) {
            close(server_fd);
        }

        // Close the log file
        if (log_file != NULL) {
            fclose(log_file);
        }

        // Terminate the pigpio library
        gpioTerminate();

        exit(0);
    }
}

int main() {
    int client_socket;
    struct sockaddr_in server_address, client_address;
    socklen_t client_address_len = sizeof(client_address);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Ensure relay is initially OFF

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("Error creating socket");
        log_event("Error creating socket");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Configure server address
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Error binding socket");
        log_event("Error binding socket");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("Error listening on socket");
        log_event("Error listening on socket");
        close(server_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);
    log_event("Listening for connections");

    // Accept connections and handle them
    while (1) {
        client_socket = accept(server_fd, (struct sockaddr *)&client_address, &client_address_len);
        if (client_socket < 0) {
            perror("Error accepting connection");
            log_event("Error accepting connection");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted\n");
        log_event("Connection accepted");

        if (handle_client(client_socket) != 0) {
            close(client_socket);
        }

        close(client_socket);
    }

    // The following lines will never be reached because of the infinite loop.
    close(server_fd);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

