#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0f
#define LOG_FILE "flow_log.txt"
#define POLLING_INTERVAL_MS 100

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int i2c_handle, float *flow_rate);
int crc8(const uint8_t *data, int len);
void log_data(float flow_rate1, float flow_rate2);
void control_relay(int state);
void signal_handler(int signal);
int initialize();
void cleanup();

// CRC-8 calculation (as per SLF3S datasheet)
int crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF; // Initial value
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31; // Polynomial
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read flow rate from a sensor
int read_sensor(int i2c_handle, float *flow_rate) {
    uint8_t buffer[3];
    int bytes_read;

    bytes_read = i2cReadDevice(i2c_handle, (char *)buffer, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }

    // CRC validation
    if (crc8(buffer, 2) != buffer[2]) {
        fprintf(stderr, "CRC check failed!\n");
        return -1;
    }

    // Convert raw data to flow rate (ml/min)
    int16_t raw_flow = (buffer[0] << 8) | buffer[1];
    *flow_rate = (float)raw_flow / 120.0f; // Scaling factor from datasheet

    return 0;
}

// Function to log data to file
void log_data(float flow_rate1, float flow_rate2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(fp, "%ld,%.2f,%.2f\n", timestamp_ms, flow_rate1, flow_rate2);
    fflush(fp); // Ensure data is written immediately
    fclose(fp);
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, shutting down...\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C devices
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1: %d\n", i2c_handle1);
        cleanup();
        return -1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2: %d\n", i2c_handle2);
        cleanup();
        return -1;
    }

    // Configure relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Start measurement (send command 0x00 0x06)
    if (i2cWriteByteData(i2c_handle1, 0x00, 0x06) < 0) {
        fprintf(stderr, "Error writing to I2C device 1\n");
        cleanup();
        return -1;
    }
    if (i2cWriteByteData(i2c_handle2, 0x00, 0x06) < 0) {
        fprintf(stderr, "Error writing to I2C device 2\n");
        cleanup();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // De-energize relay
    control_relay(0);

    // Close I2C devices
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    float flow_rate1, flow_rate2;
    int relay_state = 0; // 0 = off, 1 = on

    printf("Flow monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor(i2c_handle1, &flow_rate1) != 0) {
            fprintf(stderr, "Error reading sensor 1, skipping cycle.\n");
            flow_rate1 = -1.0f; // Indicate error
        }
        if (read_sensor(i2c_handle2, &flow_rate2) != 0) {
            fprintf(stderr, "Error reading sensor 2, skipping cycle.\n");
            flow_rate2 = -1.0f; // Indicate error
        }

        // Control relay based on flow rates
        if (flow_rate1 >= 0 && flow_rate2 >= 0) { // Only check if both readings were successful
            if (flow_rate1 < FLOW_THRESHOLD || flow_rate2 < FLOW_THRESHOLD) {
                relay_state = 1; // Energize relay
            } else {
                relay_state = 0; // De-energize relay
            }
            control_relay(relay_state);
        }

        // Log data
        log_data(flow_rate1, flow_rate2);

        // Wait for the next polling interval
        gpioDelay(POLLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Flow monitoring stopped.\n");
    return 0;
}

