#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <bcm2835.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN RPI_GPIO_P1_11 // GPIO 17 (BCM)
#define MOTOR_ENABLE_PIN RPI_GPIO_P1_15 // GPIO 22 (BCM)
#define MOTOR_INPUT1_PIN RPI_GPIO_P1_16 // GPIO 23 (BCM)
#define MOTOR_INPUT2_PIN RPI_GPIO_P1_18 // GPIO 24 (BCM)

// Define rain detection threshold
#define RAIN_THRESHOLD 3

// Define rain detection debounce time (in milliseconds)
#define RAIN_DEBOUNCE_TIME 600

// Define motor run time (in milliseconds)
#define MOTOR_RUN_TIME 5000

// Global variables
volatile sig_atomic_t program_running = 1;
int rain_count = 0;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
int control_motor(int enable, int input1, int input2);
int debounce_rain_detection(int rain_detected);
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_message(LOG_INFO, "Received shutdown signal.");
        program_running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (!bcm2835_init()) {
        log_message(LOG_ERR, "bcm2835_init failed. Are you running as root?");
        return 1;
    }

    bcm2835_gpio_fsel(RAIN_SENSOR_PIN, BCM2835_GPIO_FSEL_INPT);
    bcm2835_gpio_set_pud(RAIN_SENSOR_PIN, BCM2835_GPIO_PUD_UP);

    bcm2835_gpio_fsel(MOTOR_ENABLE_PIN, BCM2835_GPIO_FSEL_OUTP);
    bcm2835_gpio_fsel(MOTOR_INPUT1_PIN, BCM2835_GPIO_FSEL_OUTP);
    bcm2835_gpio_fsel(MOTOR_INPUT2_PIN, BCM2835_GPIO_FSEL_OUTP);

    return 0;
}

// Read rain sensor value
int read_rain_sensor() {
    return !bcm2835_gpio_lev(RAIN_SENSOR_PIN); // Rain detected if sensor output is LOW
}

// Control the DC motor
int control_motor(int enable, int input1, int input2) {
    char message[100];
    snprintf(message, sizeof(message), "Setting motor: ENA=%d, IN1=%d, IN2=%d", enable, input1, input2);
    log_message(LOG_INFO, message);

    if (bcm2835_gpio_write(MOTOR_ENABLE_PIN, enable ? HIGH : LOW) != 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_ENABLE_PIN");
        return 1;
    }
    if (bcm2835_gpio_write(MOTOR_INPUT1_PIN, input1 ? HIGH : LOW) != 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_INPUT1_PIN");
        return 1;
    }
    if (bcm2835_gpio_write(MOTOR_INPUT2_PIN, input2 ? HIGH : LOW) != 0) {
        log_message(LOG_ERR, "Failed to set MOTOR_INPUT2_PIN");
        return 1;
    }
    return 0;
}

// Debounce rain detection
int debounce_rain_detection(int rain_detected) {
    if (rain_detected) {
        rain_count++;
        if (rain_count >= RAIN_THRESHOLD) {
            log_message(LOG_INFO, "Rain detected, starting window close sequence.");
            return 1;
        }
    } else {
        rain_count = 0;
    }
    return 0;
}

// Log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

int main(int argc, char **argv) {
    // Open syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed.");
        closelog();
        return 1;
    }

    log_message(LOG_INFO, "Rain sensor monitoring started.");

    // Main loop
    while (program_running) {
        int rain_detected = read_rain_sensor();

        if (debounce_rain_detection(rain_detected)) {
            // Start motor
            if (control_motor(HIGH, HIGH, LOW) != 0) {
                log_message(LOG_ERR, "Failed to start motor.");
            } else {
                usleep(MOTOR_RUN_TIME * 1000); // Run motor for MOTOR_RUN_TIME milliseconds
                if (control_motor(LOW, LOW, LOW) != 0) {
                    log_message(LOG_ERR, "Failed to stop motor.");
                }
            }
            log_message(LOG_INFO, "Window close sequence complete.");
        }

        usleep(200 * 1000); // Poll every 200 milliseconds
    }

    // Stop motor and cleanup
    log_message(LOG_INFO, "Stopping motor and cleaning up.");
    control_motor(LOW, LOW, LOW); // Ensure motor is stopped

    // Close syslog
    closelog();

    // Close bcm2835 library
    bcm2835_close();

    log_message(LOG_INFO, "Rain sensor monitoring stopped.");

    return 0;
}

