#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22
#define SERVO_PIN 18

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door lock actuator control program started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Check lock button
        if (gpioRead(LOCK_BUTTON) == 0) {
            printf("Lock button pressed\n");
            gpioServo(SERVO_PIN, 2000);
            if (gpioServo(SERVO_PIN, 2000) != 0) {
                fprintf(stderr, "Error setting servo pulse width (lock)\n");
            }
            gpioDelay(200000); // Debounce delay
            while (gpioRead(LOCK_BUTTON) == 0 && !terminate) {
                gpioDelay(1000); // Wait for button release
            }
        }

        // Check unlock button
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            printf("Unlock button pressed\n");
            gpioServo(SERVO_PIN, 1000);
            if (gpioServo(SERVO_PIN, 1000) != 0) {
                fprintf(stderr, "Error setting servo pulse width (unlock)\n");
            }
            gpioDelay(200000); // Debounce delay
            while (gpioRead(UNLOCK_BUTTON) == 0 && !terminate) {
                gpioDelay(1000); // Wait for button release
            }
        }

        gpioDelay(10000); // Small delay to reduce CPU usage
    }

    // Stop the servo
    printf("Stopping servo...\n");
    gpioServo(SERVO_PIN, 0);
    gpioDelay(100000); // Give servo time to stop

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

