#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define PIR_GPIO 4
#define LED_GPIO 17
#define LOG_FILE "security_log.txt"
#define DEBOUNCE_MS 50

static volatile int running = 1;
static FILE *log_file = NULL;

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    return 0;
}

int read_pir_sensor() {
    return gpioRead(PIR_GPIO);
}

void activate_floodlight() {
    gpioWrite(LED_GPIO, 1);
}

void deactivate_floodlight() {
    gpioWrite(LED_GPIO, 0);
}

int log_event(const char *event_type, const char *timestamp, double duration) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%s", event_type, timestamp);
    if (duration >= 0) {
        fprintf(log_file, ",%.2f", duration);
    }
    fprintf(log_file, "\n");
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    struct timespec last_motion_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &last_motion_time);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            long time_diff_ms = (current_time.tv_sec - last_motion_time.tv_sec) * 1000 + (current_time.tv_nsec - last_motion_time.tv_nsec) / 1000000;

            if (time_diff_ms > DEBOUNCE_MS) {
                printf("Motion detected!\n");
                activate_floodlight();

                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[30];
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

                if (log_event("Motion Detected", timestamp, -1) != 0) {
                    fprintf(stderr, "Failed to log motion detection event\n");
                }

                gpioDelay(60000); // 60 seconds
                deactivate_floodlight();

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

                if (log_event("Motion Deactivated", timestamp, 60.0) != 0) {
                    fprintf(stderr, "Failed to log motion deactivation event\n");
                }

                clock_gettime(CLOCK_MONOTONIC, &last_motion_time);
            }
        }

        gpioDelay(100); // 100ms delay
    }

    printf("Turning off floodlight...\n");
    deactivate_floodlight();

    printf("Closing log file...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Terminating pigpio...\n");
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

