int mpr121_disable_electrode(uint8_t electrode);
int mpr121_enable_all_electrodes();
int mpr121_disable_all_electrodes();
int relay_on();
int relay_off();
void signal_handler(int signal);

// Function to initialize the MPR121
int mpr121_init() {
    // Soft reset
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_ECR, 0x80) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    delay(100); // Wait for reset

    // Configure baseline filtering (MHD, NHD, NCL, FDL)
    if (wiringPiI2CWriteReg8(i2c_fd, 0x2B, 0x01) < 0) return -1; // MHD
    if (wiringPiI2CWriteReg8(i2c_fd, 0x2C, 0x01) < 0) return -1; // NHD
    if (wiringPiI2CWriteReg8(i2c_fd, 0x2D, 0x00) < 0) return -1; // NCL
    if (wiringPiI2CWriteReg8(i2c_fd, 0x2E, 0x00) < 0) return -1; // FDL

    // Configure debounce
    if (wiringPiI2CWriteReg8(i2c_fd, 0x5B, 0x10) < 0) return -1; // CONFIG1
    if (wiringPiI2CWriteReg8(i2c_fd, 0x5C, 0x01) < 0) return -1; // CONFIG2

    // Configure FFI, SFI and CDT
    if (wiringPiI2CWriteReg8(i2c_fd, 0x5D, 0x24) < 0) return -1; // FFI
    if (wiringPiI2CWriteReg8(i2c_fd, 0x5E, 0x01) < 0) return -1; // SFI
    if (wiringPiI2CWriteReg8(i2c_fd, 0x5F, 0x01) < 0) return -1; // CDT

    // Enable auto-config with electrode range 0-11
    if (wiringPiI2CWriteReg8(i2c_fd, 0x5D, 0x24) < 0) return -1; // FFI
    if (wiringPiI2CWriteReg8(i2c_fd, 0x5E, 0x01) < 0) return -1; // SFI
    if (wiringPiI2CWriteReg8(i2c_fd, 0x5F, 0x01) < 0) return -1; // CDT

    // Enable electrode 0
    if (mpr121_enable_electrode(0) < 0) return -1;

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status(uint16_t *touch_status) {
    int lsb = wiringPiI2CReadReg8(i2c_fd, MPR121_TOUCHSTATUS_L);
    int msb = wiringPiI2CReadReg8(i2c_fd, MPR121_TOUCHSTATUS_H);

    if (lsb < 0 || msb < 0) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }

    *touch_status = ((uint16_t)msb << 8) | (uint16_t)lsb;
    return 0;
}

// Function to set the touch and release thresholds for a specific electrode
int mpr121_set_electrode_thresholds(uint8_t electrode, uint8_t touch_threshold, uint8_t release_threshold) {
    if (electrode > 11) {
        fprintf(stderr, "Error: Invalid electrode number\n");
        return -1;
    }

    char touch_reg = 0x41 + (electrode * 2);
    char release_reg = 0x42 + (electrode * 2);

    if (wiringPiI2CWriteReg8(i2c_fd, touch_reg, touch_threshold) < 0) {
        fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", electrode);
        return -1;
    }
    if (wiringPiI2CWriteReg8(i2c_fd, release_reg, release_threshold) < 0) {
        fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", electrode);
        return -1;
    }

    return 0;
}

// Function to enable a specific electrode
int mpr121_enable_electrode(uint8_t electrode) {
    if (electrode > 11) {
        fprintf(stderr, "Error: Invalid electrode number\n");
        return -1;
    }

    int ecr_value = wiringPiI2CReadReg8(i2c_fd, MPR121_ECR);
    if (ecr_value < 0) {
        fprintf(stderr, "Error: Failed to read ECR register\n");
        return -1;
    }

    ecr_value |= (1 << electrode);

    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_ECR, ecr_value) < 0) {
        fprintf(stderr, "Error: Failed to enable electrode %d\n", electrode);
        return -1;
    }

    return 0;
}

// Function to disable a specific electrode
int mpr121_disable_electrode(uint8_t electrode) {
    if (electrode > 11) {
        fprintf(stderr, "Error: Invalid electrode number\n");
        return -1;
    }

    int ecr_value = wiringPiI2CReadReg8(i2c_fd, MPR121_ECR);
    if (ecr_value < 0) {
        fprintf(stderr, "Error: Failed to read ECR register\n");
        return -1;
    }

    ecr_value &= ~(1 << electrode);

    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_ECR, ecr_value) < 0) {
        fprintf(stderr, "Error: Failed to disable electrode %d\n", electrode);
        return -1;
    }

    return 0;
}

// Function to enable all electrodes
int mpr121_enable_all_electrodes() {
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_ECR, 0x3F) < 0) {
        fprintf(stderr, "Error: Failed to enable all electrodes\n");
        return -1;
    }
    return 0;
}

// Function to disable all electrodes
int mpr121_disable_all_electrodes() {
    if (wiringPiI2CWriteReg8(i2c_fd, MPR121_ECR, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to disable all electrodes\n");
        return -1;
    }
    return 0;
}

// Function to turn the relay ON
int relay_on() {
    digitalWrite(GPIO_RELAY, HIGH);
    relay_state = true;
    printf("Relay ON\n");
    return 0;
}

// Function to turn the relay OFF
int relay_off() {
    digitalWrite(GPIO_RELAY, LOW);
    relay_state = false;
    printf("Relay OFF\n");
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Failed to initialize wiringPi\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: Failed to initialize I2C communication.\n");
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: Failed to initialize MPR121\n");
        return 1;
    }

    // Set GPIO17 as output
    pinMode(GPIO_RELAY, OUTPUT);

    // Turn relay OFF initially
    relay_off();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status;
    uint8_t last_touch_state = 0; // Store the last touch state

    // Main loop
    while (running) {
        // Read touch status
        if (mpr121_read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
            delay(100); // Wait before retrying
            continue;
        }

        // Check if electrode 0 is touched
        if ((touch_status & (1 << 0)) && !(last_touch_state & (1 << 0))) {
            // Electrode 0 touched (rising edge)
            printf("Electrode 0 touched!\n");
            relay_on();
            delay(DEBOUNCE_MS); // Debounce
        }

        last_touch_state = touch_status; // Update last touch state

        delay(50); // Small delay to avoid busy-waiting
    }

    // Cleanup
    relay_off(); // Ensure relay is OFF on exit
    close(i2c_fd); // Close I2C connection

    return 0;
}

