int read_pir_sensor();
void cleanup();

int main() {
    int server_socket, client_socket;
    struct sockaddr_in server_address, client_address;
    socklen_t client_address_len = sizeof(client_address);

    openlog("security_monitor", LOG_PID | LOG_CONS, LOG_USER);
    log_file = fopen("security.log", "a");
    if (!log_file) {
        perror("Error opening security.log");
        syslog(LOG_ERR, "Error opening security.log");
        closelog();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup_gpio() != 0) {
        cleanup();
        return 1;
    }

    if (setup_socket() < 0) {
        cleanup();
        return 1;
    }

    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        log_message(LOG_ERR, "Error creating socket");
        cleanup();
        return 1;
    }

    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(PORT);

    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        log_message(LOG_ERR, "Error binding socket");
        cleanup();
        return 1;
    }

    listen(server_socket, 5);
    log_message(LOG_INFO, "Listening on port %d", PORT);

    while (program_running) {
        client_socket = accept(server_socket, (struct sockaddr *)&client_address, &client_address_len);
        if (client_socket < 0) {
            log_message(LOG_ERR, "Error accepting connection");
