#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0f
#define SAMPLE_INTERVAL_SEC 2
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
void control_relay(float lux);
void log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read BH1750 sensor
int read_bh1750(float *lux) {
    char buf[2];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 120ms)
    gpioDelay(120000); // 120ms

    // Read 2 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Convert to lux
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2f;

    return 0;
}

// Control relay based on lux value
void control_relay(float lux) {
    if (lux < LUX_THRESHOLD) {
        gpioWrite(RELAY_GPIO, 1); // Activate relay
    } else {
        gpioWrite(RELAY_GPIO, 0); // Deactivate relay
    }
}

// Log data to file
void log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");

    // Close I2C
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Deactivate relay
    gpioWrite(RELAY_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is initially off

    float lux;
    int retries = 3; // Number of retries for I2C read

    printf("Starting main loop...\n");

    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            control_relay(lux);
            log_data(lux);
            retries = 3; // Reset retries on success
        } else {
            fprintf(stderr, "Error reading BH1750, retrying...\n");
            log_data(-1.0f); // Log error
            retries--;
            if (retries <= 0) {
                fprintf(stderr, "Too many retries, exiting...\n");
                break; // Exit loop after too many retries
            }
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Delay for sample interval
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

