#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <getopt.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_LOCK 25

// Default values
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 500

// Global variables
static volatile int running = 1;
static double scale_factor = DEFAULT_SCALE;
static double weight_threshold = DEFAULT_THRESHOLD;
static int duration_ms = DEFAULT_DURATION;

// Function prototypes
int read_hx711();
double tare_hx711();
double get_weight();
void control_solenoid(int activate);
void signal_handler(int signal);
void log_message(int priority, const char *message);

// HX711 read function
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for DOUT to go low
    int timeout = 1000000; // 1 second timeout
    while (gpioRead(HX711_DOUT) == 1 && timeout > 0) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout--;
    }

    if (timeout == 0) {
        log_message(LOG_ERR, "HX711 timeout waiting for DOUT to go low");
        return -1; // Indicate error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DOUT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Pulse SCK 1 more time to select channel A, gain 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// HX711 tare function
double tare_hx711() {
    double sum = 0.0;
    int i;

    for (i = 0; i < 10; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            log_message(LOG_ERR, "Error reading HX711 during tare");
            return -1.0; // Indicate error
        }
        sum += raw_value;
        gpioDelay(50); // Small delay between readings
    }

    return sum / 10.0;
}

// Get weight function
double get_weight() {
    double sum = 0.0;
    int i;

    for (i = 0; i < 5; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            log_message(LOG_ERR, "Error reading HX711 during weight measurement");
            return -1.0; // Indicate error
        }
        sum += raw_value;
        gpioDelay(50); // Small delay between readings
    }

    return (sum / 5.0 - tare_hx711()) * scale_factor;
}

// Solenoid control function
void control_solenoid(int activate) {
    gpioWrite(SOLENOID_LOCK, activate);
    gpioDelay(200); // 200ms delay
    gpioWrite(SOLENOID_LOCK, 0);
}

// Signal handler function
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Logging function
void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);
    syslog(priority, "%s: %s", timestamp, message);
}

int main(int argc, char *argv[]) {
