    double sum = 0.0;
    int i;

    for (i = 0; i < 5; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            log_message(LOG_ERR, "Error reading HX711 during weight measurement");
            return -1.0; // Indicate error
        }
        sum += raw_value;
        gpioDelay(50); // Small delay between readings
    }

    return (sum / 5.0 - tare_hx711()) * scale_factor;
}

