#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17

struct mosquitto *mosq = NULL;

void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    gpioWrite(GPIO_PIN, 0); // Turn off relay
    gpioTerminate();
    closelog();
    exit(0);
}

void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        syslog(LOG_ERR, "Connection error: %s", mosquitto_connack_string(result));
    }
}

void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "Disconnected from MQTT broker with code %d", rc);
}

void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strcmp(payload, "ON") == 0) {
            gpioWrite(GPIO_PIN, 1); // Turn on relay
            syslog(LOG_INFO, "Received ON command, turning relay ON");
        } else if (strcmp(payload, "OFF") == 0) {
            gpioWrite(GPIO_PIN, 0); // Turn off relay
            syslog(LOG_INFO, "Received OFF command, turning relay OFF");
        } else {
            syslog(LOG_ERR, "Invalid payload received: %s", payload);
        }
    } else {
        syslog(LOG_ERR, "Empty payload received");
    }
}

int main() {
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting relay controller...");

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pin as output and turn off the relay
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    // Initialize MQTT client
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    // Connect to MQTT broker
    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        rc = mosquitto_loop(mosq, -1, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT loop error: %s", mosquitto_strerror(rc));
            sleep(5);
        }
    }

    // Cleanup (should not reach here under normal circumstances)
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
    return 0;
}

