#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <wiringPi.h>
#include <softPwm.h>

// Define servo pins (BCM numbering)
#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

// Define PWM range (0-100)
#define PWM_RANGE 100

// Define pulse width limits (microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Function to set servo pulse width
void setServoPulse(int pin, int pulseWidth) {
    if (pulseWidth < MIN_PULSE_WIDTH) {
        pulseWidth = MIN_PULSE_WIDTH;
    } else if (pulseWidth > MAX_PULSE_WIDTH) {
        pulseWidth = MAX_PULSE_WIDTH;
    }

    softPwmWrite(pin, (int)(((float)(pulseWidth - MIN_PULSE_WIDTH) / (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH)) * PWM_RANGE));
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi.\n");
        return 1;
    }

    // Set servo pins as PWM output
    softPwmCreate(SERVO1_PIN, 0, PWM_RANGE);
    softPwmCreate(SERVO2_PIN, 0, PWM_RANGE);
    softPwmCreate(SERVO3_PIN, 0, PWM_RANGE);
    softPwmCreate(SERVO4_PIN, 0, PWM_RANGE);
    softPwmCreate(SERVO5_PIN, 0, PWM_RANGE);

    // Define servo positions (microseconds)
    int servoPositions[] = {1000, 1500, 2000, 500, 2500};
    int numServos = sizeof(servoPositions) / sizeof(servoPositions[0]);

    // Move servos to predefined positions
    for (int i = 0; i < numServos; i++) {
        int pin;
        switch (i) {
            case 0: pin = SERVO1_PIN; break;
            case 1: pin = SERVO2_PIN; break;
            case 2: pin = SERVO3_PIN; break;
            case 3: pin = SERVO4_PIN; break;
            case 4: pin = SERVO5_PIN; break;
            default: pin = -1; break; // Invalid index
        }

        if (pin != -1) {
            setServoPulse(pin, servoPositions[i]);
            printf("Servo %d (GPIO %d) moved to %d us\n", i + 1, pin, servoPositions[i]);
        } else {
            fprintf(stderr, "Error: Invalid servo index %d\n", i);
        }
    }

    // Wait for three seconds
    delay(3000);

    // Stop servos (set to 0)
    setServoPulse(SERVO1_PIN, 0);
    setServoPulse(SERVO2_PIN, 0);
    setServoPulse(SERVO3_PIN, 0);
    setServoPulse(SERVO4_PIN, 0);
    setServoPulse(SERVO5_PIN, 0);

    printf("Servos stopped.\n");

    return 0;
}

