#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <pthread.h>
#include <time.h>

// Motor A
#define MOTOR_A_PWM_PIN 17
#define MOTOR_A_DIR_PIN 18

// Motor B
#define MOTOR_B_PWM_PIN 22
#define MOTOR_B_DIR_PIN 23

// Encoder A
#define ENCODER_A_A_PIN 4
#define ENCODER_A_B_PIN 5

// Encoder B
#define ENCODER_B_A_PIN 6
#define ENCODER_B_B_PIN 12

// Encoder counts per revolution
#define ENCODER_TICKS_PER_REV 64

// Target RPM
#define TARGET_RPM 50

// PI controller parameters
#define KP 0.5
#define KI 0.1

// Stall detection parameters
#define STALL_THRESHOLD 2 // seconds

// PWM frequency
#define PWM_FREQUENCY 10000 // 10 kHz

// Global variables
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
volatile int encoder_a_stalled = 0;
volatile int encoder_b_stalled = 0;
volatile int running = 1;

// Mutexes for encoder counts
pthread_mutex_t encoder_a_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder_b_mutex = PTHREAD_MUTEX_INITIALIZER;

// PI controller state
double integral_a = 0;
double last_error_a = 0;
double integral_b = 0;
double last_error_b = 0;

// Function prototypes
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
void *encoder_monitor_thread(void *arg);
void set_motor_speed(int motor, int direction, int duty_cycle);
void pi_control(int motor, int target_rpm);
void signal_handler(int signal);
void cleanup();

// Encoder A ISR
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    if (gpio == ENCODER_A_A_PIN) {
        int b_level = gpioRead(ENCODER_A_B_PIN);
        if (level == PI_HIGH) {
            if (b_level == PI_HIGH) {
                pthread_mutex_lock(&encoder_a_mutex);
                encoder_a_count++;
                pthread_mutex_unlock(&encoder_a_mutex);
            } else {
                pthread_mutex_lock(&encoder_a_mutex);
                encoder_a_count--;
                pthread_mutex_unlock(&encoder_a_mutex);
            }
        }
    } else if (gpio == ENCODER_A_B_PIN) {
        int a_level = gpioRead(ENCODER_A_A_PIN);
        if (level == PI_HIGH) {
            if (a_level == PI_HIGH) {
                pthread_mutex_lock(&encoder_a_mutex);
                encoder_a_count++;
                pthread_mutex_unlock(&encoder_a_mutex);
            } else {
                pthread_mutex_lock(&encoder_a_mutex);
                encoder_a_count--;
                pthread_mutex_unlock(&encoder_a_mutex);
            }
        }
    }
}

// Encoder B ISR
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    if (gpio == ENCODER_B_A_PIN) {
        int b_level = gpioRead(ENCODER_B_B_PIN);
        if (level == PI_HIGH) {
            if (b_level == PI_HIGH) {
                pthread_mutex_lock(&encoder_b_mutex);
                encoder_b_count++;
                pthread_mutex_unlock(&encoder_b_mutex);
            } else {
