#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to store the relay state
static volatile int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int debounce_touch();
int toggle_relay();
int log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, turning relay OFF and exiting...\n");
        gpioWrite(RELAY_PIN, 0); // Turn relay OFF
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Initialize relay to OFF state
    gpioWrite(RELAY_PIN, 0);
    relay_state = 0; // Update global state

    return 0; // Indicate success
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to debounce the touch sensor
int debounce_touch() {
    gpioDelay(DEBOUNCE_DELAY * 1000); // Delay for debounce (microseconds)
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay state
int toggle_relay() {
    relay_state = !relay_state; // Toggle the state
    gpioWrite(RELAY_PIN, relay_state); // Write the new state to the relay
    return 0;
}

// Function to log the relay state with timestamp
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    printf("%s Relay is now %s\n", timestamp, state ? "ON" : "OFF");
    return 0;
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Touch sensor relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (read_touch_sensor() == 1) {
            if (debounce_touch() == 1) {
                toggle_relay();
                log_relay_state(relay_state);
                // Wait for touch release
                while (read_touch_sensor() == 1) {
                    gpioDelay(1000); // Sleep for 1ms
                }
            }
        }
        gpioDelay(10000); // Sleep for 10ms
    }

    return 0; // This line will never be reached due to the infinite loop
}

