#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define VALVE_GPIO 27
#define PULSES_PER_LITER 450.0
#define OPEN_THRESHOLD_LPM 5.0
#define CLOSE_THRESHOLD_LPM 4.5
#define HYSTERESIS 0.5
#define DEBOUNCE_TIME_MS 1000
#define LOG_FILE "water_flow.log"

// Global variables
static volatile int pulse_count = 0;
static volatile int solenoid_state = 1; // 0 = closed, 1 = open
static pthread_mutex_t pulse_mutex;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
void *monitor_flow(void *arg);
void control_valve(void);
void log_data(const char *message);
void signal_handler(int signal);
int initialize(void);
void cleanup(void);

// ISR for flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; (void)level; (void)tick; (void)user_data; // Unused parameters
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick < DEBOUNCE_TIME_MS * 1000) {
        return; // Debounce
    }
    last_tick = current_tick;

    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Thread function to monitor flow and control valve
void *monitor_flow(void *arg) {
    (void)arg; // Unused parameter
    while (!terminate) {
        int current_pulse_count;
        pthread_mutex_lock(&pulse_mutex);
        current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count
        pthread_mutex_unlock(&pulse_mutex);

        float flow_rate = (float)current_pulse_count / PULSES_PER_LITER;
        float flow_lpm = flow_rate * 60.0; // Convert to LPM

        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Flow Rate: %.2f LPM, Solenoid State: %s", flow_lpm, solenoid_state ? "OPEN" : "CLOSED");
        log_data(log_message);

        control_valve();

        gpioDelay(1000); // Check every 1 second
    }
    return NULL;
}

// Function to control the solenoid valve
void control_valve(void) {
    int current_solenoid_state = solenoid_state;
    float flow_rate;
    pthread_mutex_lock(&pulse_mutex);
    flow_rate = (float)pulse_count / PULSES_PER_LITER;
    pthread_mutex_unlock(&pulse_mutex);
    float flow_lpm = flow_rate * 60.0;

    if (solenoid_state == 0 && flow_lpm < CLOSE_THRESHOLD_LPM - HYSTERESIS) {
        gpioWrite(VALVE_GPIO, 1); // Open valve
        solenoid_state = 1;
        log_data("Valve OPEN");
    } else if (solenoid_state == 1 && flow_lpm > OPEN_THRESHOLD_LPM) {
        gpioWrite(VALVE_GPIO, 0); // Close valve
        solenoid_state = 0;
        log_data("Valve CLOSED");
    }

    if (current_solenoid_state != solenoid_state) {
        char log_message[256];
        snprintf(log_message, sizeof(log_message), "Valve State: %s", solenoid_state ? "OPEN" : "CLOSED");
        log_data(log_message);
    }
}

// Function to log data to file
void log_data(const char *message) {
    if (log_file != NULL) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal; // Unused parameter
    terminate = 1;
    log_data("Received signal, shutting down...");
}

// Initialization function
int initialize(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", FLOW_SENSOR_GPIO);
        cleanup();
        return 1;
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", VALVE_GPIO);
        cleanup();
        return 1;
    }

    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for GPIO%d\n", FLOW_SENSOR_GPIO);
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup(void) {
    log_data("Cleaning up...");
    gpioWrite(VALVE_GPIO, 1); // Ensure valve is open on exit
    if (log_file != NULL) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
}

int main(void) {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    pthread_t flow_thread;
    if (pthread_create(&flow_thread, NULL, monitor_flow, NULL) != 0) {
        fprintf(stderr, "Failed to create flow monitoring thread\n");
        cleanup();
        return 1;
    }

    pthread_join(flow_thread, NULL);

    cleanup();
    return 0;
}

