#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <jansson.h>

// Constants
#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18
#define SERVER_PORT 12345
#define SERVER_IP "127.0.0.1"
#define CALIBRATION_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"
#define TARGET_WEIGHT_MIN 0.0
#define TARGET_WEIGHT_MAX 100.0
#define WEIGHT_RANGE_MIN 1000
#define WEIGHT_RANGE_MAX 2000
#define TIMEOUT_ATTEMPTS 1000
#define TIMEOUT_DELAY_US 1000 // 1ms
#define STABILIZATION_DELAY_S 1

// Global variables
static volatile int running = 1;
static int socket_fd = -1;
static FILE *log_file = NULL;
static double calibration_factor = 1.0; // Default calibration factor

// Function prototypes
int initialize_gpio();
int read_hx711();
double calibrate_weight(int raw_value);
int map_weight_to_pulse_width(double target_weight);
int control_servo(int pulse_width);
int send_weight_to_server(int socket_fd, double weight);
int log_dispensing_event(double target_weight, double actual_weight, const char *error_message);
void signal_handler(int signal);
int load_calibration_factor(const char *filename);
int save_calibration_factor(const char *filename, double factor);

// HX711 read function (bit-banged)
int read_hx711() {
    int i, data = 0;
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);

    // Wait for DATA to go low
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < TIMEOUT_ATTEMPTS) {
        gpioDelay(TIMEOUT_DELAY_US);
        timeout++;
    }

    if (timeout >= TIMEOUT_ATTEMPTS) {
        fprintf(stderr, "HX711 timeout error\n");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1); // 1us pulse
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1); // 1us pulse
    }

    // 25th pulse for gain selection (channel A, gain 128)
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1); // 1us pulse
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1); // 1us pulse

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Calibration function
double calibrate_weight(int raw_value) {
    return (double)raw_value / calibration_factor;
}

// Servo control function
int control_servo(int pulse_width) {
    if (pulse_width < 1000 || pulse_width > 2000) {
        fprintf(stderr, "Invalid pulse width: %d\n", pulse_width);
        return -1;
    }
    gpioServo(SERVO_PIN, pulse_width);
    return 0;
}

// Weight mapping function
int map_weight_to_pulse_width(double target_weight) {
    if (target_weight < TARGET_WEIGHT_MIN) {
        target_weight = TARGET_WEIGHT_MIN;
    } else if (target_weight > TARGET_WEIGHT_MAX) {
        target_weight = TARGET_WEIGHT_MAX;
    }

    return (int)((target_weight - TARGET_WEIGHT_MIN) / (TARGET_WEIGHT_MAX - TARGET_WEIGHT_MIN) * (WEIGHT_RANGE_MAX - WEIGHT_RANGE_MIN) + WEIGHT_RANGE_MIN);
}

// Server communication function
int send_weight_to_server(int socket_fd, double weight) {
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "%.2f", weight);
    if (send(socket_fd, buffer, strlen(buffer), 0) < 0) {
        perror("Send failed");
        return -1;
    }
    return 0;
}

// Logging function
int log_dispensing_event(double target_weight, double actual_weight, const char *error_message) {
    json_t *root = json_object();
    json_t *timestamp = json_string(NULL);
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
    timestamp = json_string(buf);
    json_object_set_new(root, "timestamp", timestamp);

    json_t *target_weight_json = json_real(target_weight);
    json_object_set_new(root, "target_weight", target_weight_json);

    json_t *actual_weight_json = json_real(actual_weight);
    json_object_set_new(root, "actual_weight", actual_weight_json);

    json_t *error_message_json = json_string(error_message);
    json_object_set_new(root, "error_message", error_message_json);

    char *json_str = json_dumps(root, JSON_REAL_PRECISION(3));
    if (json_str == NULL) {
        fprintf(stderr, "Failed to serialize JSON\n");
        json_decref(root);
        return -1;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s\n", json_str);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not opened\n");
        free(json_str);
        json_decref(root);
        return -1;
    }

    free(json_str);
    json_decref(root);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    if (socket_fd != -1) {
        close(socket_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioServo(SERVO_PIN, 0); // Stop servo
    gpioTerminate();
    exit(0);
}

// Calibration factor loading function
int load_calibration_factor(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file, using default: %s\n", filename);
        return -1; // Use default calibration factor
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading calibration file, using default: %s\n", filename);
        fclose(fp);
        return -1; // Use default calibration factor
    }

    if (sscanf(line, "calibration_factor = %lf", &calibration_factor) != 1) {
        fprintf(stderr, "Error parsing calibration factor, using default: %s\n", filename);
        fclose(fp);
        return -1; // Use default calibration factor
    }

    fclose(fp);
    printf("Calibration factor loaded: %lf\n", calibration_factor);
    return 0;
}

// Calibration factor saving function
int save_calibration_factor(const char *filename, double factor) {
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        perror("Error opening calibration file for writing");
        return -1;
    }

    fprintf(fp, "calibration_factor = %lf\n", factor);
    fclose(fp);
    printf("Calibration factor saved: %lf\n", factor);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Load calibration factor
    if (load_calibration_factor(CALIBRATION_FILE) != 0) {
        calibration_factor = 1.0; // Default calibration factor
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        perror("Socket creation failed");
        log_dispensing_event(0.0, 0.0, "Socket creation failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = inet_addr(SERVER_IP);
    server_address.sin_port = htons(SERVER_PORT);

    if (bind(socket_fd, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Bind failed");
        log_dispensing_event(0.0, 0.0, "Bind failed");
        close(socket_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(socket_fd, 3) < 0) {
        perror("Listen failed");
        log_dispensing_event(0.0, 0.0, "Listen failed");
        close(socket_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Listening on %s:%d...\n", SERVER_IP, SERVER_PORT);

    while (running) {
        // Accept connection
        int client_socket = accept(socket_fd, NULL, NULL);
        if (client_socket < 0) {
            perror("Accept failed");
            log_dispensing_event(0.0, 0.0, "Accept failed");
            continue; // Continue listening
        }

        printf("Connection accepted\n");

        // Receive target weight
        char buffer[256];
        ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            perror("Receive failed");
            log_dispensing_event(0.0, 0.0, "Receive failed");
            close(client_socket);
            continue; // Continue listening
        }
        buffer[bytes_received] = '\0';
        double target_weight = atof(buffer);

        printf("Target weight: %.2f\n", target_weight);

        // Validate target weight
        if (target_weight < TARGET_WEIGHT_MIN || target_weight > TARGET_WEIGHT_MAX) {
            fprintf(stderr, "Invalid target weight: %.2f\n", target_weight);
            log_dispensing_event(target_weight, 0.0, "Invalid target weight");
            close(client_socket);
            continue; // Continue listening
        }

        // Dispense ingredient
        int pulse_width = map_weight_to_pulse_width(target_weight);
        if (control_servo(pulse_width) != 0) {
            fprintf(stderr, "Servo control failed\n");
            log_dispensing_event(target_weight, 0.0, "Servo control failed");
            close(client_socket);
            continue; // Continue listening
        }

        // Wait for stabilization
        sleep(STABILIZATION_DELAY_S);

        // Read actual weight
        int raw_value = read_hx711();
        if (raw_value < 0) {
            fprintf(stderr, "HX711 read failed\n");
            log_dispensing_event(target_weight, 0.0, "HX711 read failed");
            close(client_socket);
            continue; // Continue listening
        }

        double actual_weight = calibrate_weight(raw_value);
        printf("Actual weight: %.2f\n", actual_weight);

        // Send weight to server
        if (send_weight_to_server(client_socket, actual_weight) != 0) {
            fprintf(stderr, "Send to server failed\n");
            log_dispensing_event(target_weight, actual_weight, "Send to server failed");
            close(client_socket);
            continue; // Continue listening
        }

        // Log dispensing event
        if (log_dispensing_event(target_weight, actual_weight, "Success") != 0) {
            fprintf(stderr, "Logging failed\n");
        }

        // Close connection
        close(client_socket);
    }

    // Cleanup
    close(socket_fd);
    fclose(log_file);
    gpioServo(SERVO_PIN, 0); // Stop servo
    gpioTerminate();

    return 0;
}

