#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17

volatile sig_atomic_t program_running = 1;
int debounce_interval_ms = 50;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
}

int main(int argc, char *argv[]) {
    if (argc > 1) {
        if (strcmp(argv[1], "-d") == 0 && argc > 2) {
            debounce_interval_ms = atoi(argv[2]);
            if (debounce_interval_ms <= 0) {
                fprintf(stderr, "Invalid debounce interval. Using default value of %d ms.\n", debounce_interval_ms);
            }
        } else {
            fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
            return 1;
