#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <termios.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Constants
#define SERVO_PIN 1  // WiringPi pin number for GPIO18 (Physical pin 12)
#define SERVO_CHANNEL 0
#define SERVO_FREQUENCY 50 // Hz
#define SERVO_RANGE 2000 // Maximum pulse width (us)
#define SERVO_MIN 500   // Minimum pulse width (us)
#define SERVO_MAX 2500  // Maximum pulse width (us)
#define SERVO_CENTER 1500 // Center pulse width (us)
#define I2C_ADDR 0x27
#define MOTION_SENSOR_REG 0x00
#define LIGHT_SENSOR_REG 0x01

// Global variables
static volatile int keepRunning = 1;
static int angle = 90; // Initial angle
static int i2c_fd;
static struct termios orig_termios;

// Function prototypes
void signalHandler(int signal);
int setServoPulse(int channel, int pulseWidth);
int getKey();
int readSensorData(int reg);
void restoreTerminal();

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        keepRunning = 0;
    }
}

// Function to set the servo pulse width using PWM
int setServoPulse(int channel, int pulseWidth) {
    if (pulseWidth < SERVO_MIN || pulseWidth > SERVO_MAX) {
        fprintf(stderr, "Error: Pulse width out of range (%d us). Must be between %d and %d us.\n", pulseWidth, SERVO_MIN, SERVO_MAX);
        return -1;
    }

    // wiringPiPWM doesn't directly support channels, so we need to map it to a GPIO pin
    int gpioPin = 18; // Assuming GPIO18 is connected to PWM0
    pwmWrite(gpioPin, pulseWidth);

    return 0;
}

// Function to read a key from the keyboard
int getKey() {
    int character;
    struct termios tempTermios;

    // Save the current terminal settings
    if (tcgetattr(STDIN_FILENO, &orig_termios) == -1) {
        perror("tcgetattr");
        return -1;
    }

    // Set the terminal to raw mode
    tempTermios = orig_termios;
    tempTermios.c_lflag &= ~(ICANON | ECHO);
    if (tcsetattr(STDIN_FILENO, TCSANOW, &tempTermios) == -1) {
        perror("tcsetattr");
        return -1;
    }

    // Read a single character
    character = getchar();

    // Restore the original terminal settings
    if (tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios) == -1) {
        perror("tcsetattr");
        return -1;
    }

    return character;
}

// Function to read sensor data from the I2C device
int readSensorData(int reg) {
    int value = wiringPiI2CReadReg8(i2c_fd, reg);
    if (value == -1) {
        fprintf(stderr, "Error reading from I2C register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return value;
}

// Function to restore the terminal settings
void restoreTerminal() {
    if (tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios) == -1) {
        perror("tcsetattr (restore)");
    }
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing WiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(I2C_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return 1;
    }

    // Set PWM mode to mark:space
    pwmSetMode(PWM_MODE_MS);

    // Set PWM range
    pwmSetRange(SERVO_RANGE);

    // Set PWM clock divider (adjust as needed)
    pwmSetClock(192); // Adjust for 50Hz (20ms period)

    // Set PWM range for the servo channel
    pwmWrite(SERVO_PIN, SERVO_CENTER);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Restore terminal settings on exit
    atexit(restoreTerminal);

    printf("Servo control program. Press '+' to increase angle, '-' to decrease, 'q' to quit.\n");

    while (keepRunning) {
        int key = getKey();

        if (key == '+') {
            angle += 10;
            if (angle > 180) {
                angle = 180;
            }
            int pulseWidth = SERVO_MIN + (int)(((float)(angle) / 180.0) * (SERVO_MAX - SERVO_MIN));
            if (setServoPulse(SERVO_CHANNEL, pulseWidth) == -1) {
                fprintf(stderr, "Error setting servo pulse width.\n");
            }
            printf("Angle: %d\n", angle);
        } else if (key == '-') {
            angle -= 10;
            if (angle < 0) {
                angle = 0;
            }
            int pulseWidth = SERVO_MIN + (int)(((float)(angle) / 180.0) * (SERVO_MAX - SERVO_MIN));
            if (setServoPulse(SERVO_CHANNEL, pulseWidth) == -1) {
                fprintf(stderr, "Error setting servo pulse width.\n");
            }
            printf("Angle: %d\n", angle);
        } else if (key == 'q') {
            keepRunning = 0;
        } else if (key != -1) {
            // Ignore other characters
            //printf("Key: %d\n", key);
        }

        // Read sensor data
        int motion = readSensorData(MOTION_SENSOR_REG);
        int light = readSensorData(LIGHT_SENSOR_REG);

        if (motion != -1) {
            printf("Motion: %d\n", motion);
        }
        if (light != -1) {
            printf("Light: %d\n", light);
        }

        delay(100); // Small delay to prevent busy-waiting
    }

    // Stop PWM
    pwmWrite(SERVO_PIN, 0); // Set to 0 to stop the servo

    printf("Servo stopped. Exiting.\n");

    return 0;
}

