#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define SAMPLE_INTERVAL_S 5
#define LOG_FILE "motor_rpm.log"

static volatile int running = 1;
static volatile unsigned long last_tick = 0;
static FILE *log_file = NULL;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *info;
    char *buffer = malloc(sizeof(char) * 30);
    if (buffer == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    info = gmtime(&rawtime);

    strftime(buffer, 30, "%Y-%m-%dT%H:%M:%SZ", info);
    return buffer;
}

// Function to log RPM data to file
int log_rpm_data(const char *timestamp, float rpm) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to calculate RPM
float calculate_rpm(unsigned long pulse_count, float time_elapsed) {
    return (float)pulse_count / time_elapsed * 60.0;
}

// Callback function for GPIO edge detection
void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) { // Rising edge
        unsigned long current_tick = tick;
        if (last_tick != 0) {
            unsigned long diff = current_tick - last_tick;
            if (diff > DEBOUNCE_MS * 1000) { // Debounce
                last_tick = current_tick;
            }
        } else {
            last_tick = current_tick;
        }
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callback function for rising edge detection
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    unsigned long pulse_count = 0;
    time_t start_time, current_time;
    time(&start_time);

    printf("Monitoring RPM... Press Ctrl+C to exit.\n");

    while (running) {
        sleep(SAMPLE_INTERVAL_S);
        time(&current_time);
        float time_elapsed = difftime(current_time, start_time);
        float rpm = calculate_rpm(pulse_count, time_elapsed);
        pulse_count = 0; // Reset pulse count for the next interval
        time(&start_time);

        char *timestamp = get_iso8601_timestamp();
        if (timestamp != NULL) {
            printf("RPM: %.2f\n", rpm);
            if (log_rpm_data(timestamp, rpm) != 0) {
                fprintf(stderr, "Failed to log RPM data.\n");
            }
            free(timestamp);
        } else {
            fprintf(stderr, "Failed to get timestamp.\n");
        }
    }

    // Clean up and exit
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable callback
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

