#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define DEBOUNCE_DELAY_MS 50
#define LONG_PRESS_DURATION_S 10

// Global variables
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void control_relay(int state);
void cleanup_gpio();
void signal_handler(int signal);

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop
    int relay_state = 0; // 0 = OFF, 1 = ON
    int long_press_detected = 0;

    while (!terminate) {
        int touch_detected = read_touch_sensor();

        if (touch_detected) {
            if (!long_press_detected) {
                // Debounce and toggle relay
                gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
                relay_state = !relay_state;
                control_relay(relay_state);
                long_press_detected = 0; // Reset long press flag
