#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define VALVE_GPIO 18
#define VALVE_ENABLE_GPIO 23
#define FLOW_SENSOR_GPIO 24
#define PWM_FREQUENCY 1000 // Hz
#define TARGET_FLOW_RATE_MIN 0.0
#define TARGET_FLOW_RATE_MAX 100.0
#define Kp 1.0
#define LOG_FILE "flow_log.csv"

// Global variables
volatile int pulse_count = 0;
double target_flow_rate = 0.0;
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
double calculate_flow_rate();
double calculate_duty_cycle(double flow_rate);
void set_valve_position(double duty_cycle);
void log_data(double flow_rate, double duty_cycle);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int initialized;
    int valve_enabled;
    int flow_sensor_enabled;
} ProgramState;

ProgramState state = {0, 0, 0};

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = atof(optarg);
                if (target_flow_rate < TARGET_FLOW_RATE_MIN || target_flow_rate > TARGET_FLOW_RATE_MAX) {
                    fprintf(stderr, "Error: Target flow rate must be between %.2f and %.2f L/min.\n", TARGET_FLOW_RATE_MIN, TARGET_FLOW_RATE_MAX);
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
                return 1;
        }
    }

    if (target_flow_rate == 0.0) {
        fprintf(stderr, "Error: Target flow rate is required.\n");
        fprintf(stderr, "Usage: %s -t <target_flow_rate>\n", argv[0]);
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error: GPIO initialization failed.\n");
        return 1;
    }
    state.initialized = 1;

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s.\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Calculate flow rate
        double flow_rate = calculate_flow_rate();

        // Calculate duty cycle
        double duty_cycle = calculate_duty_cycle(flow_rate);

        // Set valve position
        set_valve_position(duty_cycle);

        // Log data
        log_data(flow_rate, duty_cycle);

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    cleanup();

    return 0;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set valve GPIO as output
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, 255);

    // Set valve enable GPIO as output and enable the valve
    gpioSetMode(VALVE_ENABLE_GPIO, PI_OUTPUT);
    gpioWrite(VALVE_ENABLE_GPIO, 1); // Enable valve
    state.valve_enabled = 1;

    // Set flow sensor GPIO as input and enable interrupt
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, interrupt_handler, NULL);
    state.flow_sensor_enabled = 1;

    return 0;
}

// Interrupt handler for flow sensor
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    pulse_count++;
}

// Calculate flow rate
double calculate_flow_rate() {
    // Calculate flow rate based on pulse count
    double flow_rate = (double)pulse_count * 60.0; // L/min (assuming 1 pulse per liter)
    pulse_count = 0; // Reset pulse count
    return flow_rate;
}

// Calculate duty cycle
double calculate_duty_cycle(double flow_rate) {
    // Proportional controller
    double error = target_flow_rate - flow_rate;
    double duty_cycle = Kp * error;

    // Clamp duty cycle to 0-255
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 255) {
        duty_cycle = 255;
    }

    return duty_cycle;
}

// Set valve position
void set_valve_position(double duty_cycle) {
    gpioPWM(VALVE_GPIO, (int)duty_cycle);
}

// Log data to file
void log_data(double flow_rate, double duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow_rate, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function
void cleanup() {
    // Disable valve
    if (state.valve_enabled) {
        gpioWrite(VALVE_ENABLE_GPIO, 0); // Disable valve
    }

    // Disable interrupt
    if (state.flow_sensor_enabled) {
        gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    }

    // Set PWM duty cycle to 0
    gpioPWM(VALVE_GPIO, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    if (state.initialized) {
        gpioTerminate();
    }

    printf("Cleanup complete. Exiting.\n");
}

