#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22

// Define SPI channel and speed
#define SPI_CHANNEL 0
#define SPI_SPEED 100000 // 100kHz

// Define tag validation byte
#define VALID_TAG_BYTE 0xAB

// Define log file path
#define LOG_FILE "/var/log/door_access.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rfid_tag(unsigned char *tag_data);
int validate_tag(const unsigned char *tag_data);
void engage_locks();
void disengage_locks();
void log_event(const char *event_type, const char *message);
void signal_handler(int signal);

// Function to read RFID tag data from SPI
int read_rfid_tag(unsigned char *tag_data) {
    int result;
    for (int i = 0; i < 4; ++i) {
        result = spiRead(spi_handle, tag_data + (i * 2), 2);
        if (result != 2) {
            log_event("RFID Read Failure", "SPI read failed");
            return -1; // Indicate failure
        }
    }
    return 0; // Indicate success
}

// Function to validate the RFID tag data
int validate_tag(const unsigned char *tag_data) {
    if (tag_data[0] == 0x00 && tag_data[1] == 0x00 &&
        tag_data[2] == 0x00 && tag_data[3] == 0x00 &&
        tag_data[4] == 0x00 && tag_data[5] == 0x00 &&
        tag_data[6] == 0x00 && tag_data[7] == 0x00 &&
        tag_data[8] == 0x00 && tag_data[9] == 0x00) {
        return 0; // All zeros, no tag
    }

    if (tag_data[0] == VALID_TAG_BYTE) {
        return 1; // Valid tag
    }

    return 0; // Invalid tag
}

// Function to engage the locks
void engage_locks() {
    gpioWrite(LOCK1_PIN, 1);
    gpioWrite(LOCK2_PIN, 1);
}

// Function to disengage the locks
void disengage_locks() {
    gpioWrite(LOCK1_PIN, 0);
    gpioWrite(LOCK2_PIN, 0);
    gpioDelay(5000000); // 5 seconds
    engage_locks();
}

// Function to log events to a file
void log_event(const char *event_type, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s [%s] %s\n", timestamp, event_type, message);
    fflush(log_file); // Ensure immediate write
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Internal pull-up

    // Open SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char tag_data[10];
    int button_pressed = 0;
    int button_state = 1; // Initialize to released state
    int last_button_state = 1;

    // Main loop
    while (program_running) {
        // Read RFID tag
        if (read_rfid_tag(tag_data) == 0) {
            // Validate tag
            if (validate_tag(tag_data)) {
                log_event("Access Attempt", "Valid tag read");
                printf("Valid tag read\n");

                // Check for button press
                button_state = gpioRead(BUTTON_PIN);
                if (button_state == 0 && last_button_state == 1) {
                    // Button pressed
                    button_pressed = 1;
                    log_event("Button Press", "Button pressed");
                    printf("Button pressed\n");
                }
                last_button_state = button_state;

                if (button_pressed) {
                    disengage_locks();
                    log_event("Access Granted", "Door unlocked");
                    printf("Door unlocked\n");
                    button_pressed = 0; // Reset button press
                }
            } else {
                log_event("Access Attempt", "Invalid tag read");
                printf("Invalid tag read\n");
            }
        } else {
            log_event("RFID Read Failure", "RFID read failed");
            printf("RFID read failed\n");
        }

        gpioDelay(100); // Small delay to avoid busy-waiting
    }

    // Cleanup
    engage_locks(); // Ensure locks are engaged on exit
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

