#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

// Motor 1 GPIOs
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2 GPIOs
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1 GPIOs
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2 GPIOs
#define ENCODER2_A 26
#define ENCODER2_B 19

// PID Sample Time (ms)
#define SAMPLE_TIME 100

// PWM Frequency (Hz)
#define PWM_FREQUENCY 100

// Target Speed (RPM)
#define TARGET_SPEED 60

// PI Constants
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Global Variables
static volatile int running = 1;
static volatile int encoder1_count = 0;
static volatile int encoder2_count = 0;
static pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

// Function Prototypes
void *encoder_monitor_thread(void *arg);
void signal_handler(int signal);
void set_motor_speed(int motor, int speed);
void set_motor_direction(int motor, int direction);
void log_data(int encoder1_count, int encoder2_count, double pid_output1, double pid_output2, double p1, double i1, double d1, double p2, double i2, double d2);
void update_pid(double target, double current, double *p, double *i, double *d, double *output, double dt);

// Encoder Callback Functions
void encoder1_a_callback(int gpio, int level, uint32_t tick, void *user);
void encoder1_b_callback(int gpio, int level, uint32_t tick, void *user);
void encoder2_a_callback(int gpio, int level, uint32_t tick, void *user);
void encoder2_b_callback(int gpio, int level, uint32_t tick, void *user);

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Set pull-up/down resistors (optional, adjust as needed)
    gpioSetPullUpDown(ENCODER1_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER1_B, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER2_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER2_B, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR1_ENA, 255);
    gpioSetPWMrange(MOTOR2_ENB, 255);

    // Set initial motor direction (forward)
    set_motor_direction(1, 1);
    set_motor_direction(2, 1);

    // Set initial motor speed (0%)
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);

    // Open log file
    log_file = fopen("motor_log.csv", "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0)
    {
        fprintf(log_file, "Encoder1_Count,Encoder2_Count,PID_Output1,PID_Output2,P,I,D\n");
    }
    fflush(log_file);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create encoder monitoring thread
    pthread_t encoder_thread;
    if (pthread_create(&encoder_thread, NULL, encoder_monitor_thread, NULL) != 0)
    {
        fprintf(stderr, "Failed to create encoder monitoring thread\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // PID loop
    double target_speed = TARGET_SPEED;
    double current_speed1 = 0.0;
    double current_speed2 = 0.0;
    double p1 = 0.0, i1 = 0.0, d1 = 0.0;
    double p2 = 0.0, i2 = 0.0, d2 = 0.0;
    double pid_output1 = 0.0, pid_output2 = 0.0;
    double last_time = time_time();
    double dt = 0.0;

    while (running)
    {
        // Calculate time difference
        double current_time = time_time();
        dt = current_time - last_time;
        last_time = current_time;

        // Update PID controllers
        update_pid(target_speed, current_speed1, &p1, &i1, &d1, &pid_output1, dt);
        update_pid(target_speed, current_speed2, &p2, &i2, &d2, &pid_output2, dt);

        // Set motor speeds based on PID output
        set_motor_speed(1, (int)pid_output1);
        set_motor_speed(2, (int)pid_output2);

        // Log data
        log_data(encoder1_count, encoder2_count, pid_output1, pid_output2, p1, i1, d1, p2, i2, d2);

        // Sleep for the sample time
        gpioDelay(SAMPLE_TIME * 1000); // Convert ms to us
    }

    // Stop motors and cleanup
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
    pthread_join(encoder_thread, NULL);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

void *encoder_monitor_thread(void *arg)
{
    // Set up callbacks for encoder A and B
    gpioSetAlertFuncEx(ENCODER1_A, encoder1_a_callback, NULL);
    gpioSetAlertFuncEx(ENCODER1_B, encoder1_b_callback, NULL);
    gpioSetAlertFuncEx(ENCODER2_A, encoder2_a_callback, NULL);
    gpioSetAlertFuncEx(ENCODER2_B, encoder2_b_callback, NULL);

    while (running)
    {
        // Sleep for a short period to avoid busy-waiting
        gpioDelay(10000); // 10ms
    }

    return NULL;
}

void signal_handler(int signal)
{
    printf("Caught signal %d, stopping motors...\n", signal);
    running = 0;
}

void set_motor_speed(int motor, int speed)
{
    if (motor == 1)
    {
        gpioPWM(MOTOR1_ENA, speed);
    }
    else if (motor == 2)
    {
        gpioPWM(MOTOR2_ENB, speed);
    }
    else
    {
        fprintf(stderr, "Invalid motor number: %d\n", motor);
    }
}

void set_motor_direction(int motor, int direction)
{
    if (motor == 1)
    {
        if (direction == 1) // Forward
        {
            gpioWrite(MOTOR1_IN1, 1);
            gpioWrite(MOTOR1_IN2, 0);
        }
        else if (direction == -1) // Backward
        {
            gpioWrite(MOTOR1_IN1, 0);
            gpioWrite(MOTOR1_IN2, 1);
        }
        else
        {
            gpioWrite(MOTOR1_IN1, 0);
            gpioWrite(MOTOR1_IN2, 0);
        }
    }
    else if (motor == 2)
    {
        if (direction == 1) // Forward
        {
            gpioWrite(MOTOR2_IN3, 1);
            gpioWrite(MOTOR2_IN4, 0);
        }
        else if (direction == -1) // Backward
        {
            gpioWrite(MOTOR2_IN3, 0);
            gpioWrite(MOTOR2_IN4, 1);
        }
        else
        {
            gpioWrite(MOTOR2_IN3, 0);
            gpioWrite(MOTOR2_IN4, 0);
        }
    }
    else
    {
        fprintf(stderr, "Invalid motor number: %d\n", motor);
    }
}

void log_data(int encoder1_count, int encoder2_count, double pid_output1, double pid_output2, double p1, double i1, double d1, double p2, double i2, double d2)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, encoder1_count, encoder2_count, pid_output1, pid_output2, p1, i1, d1, p2, i2, d2);
    fflush(log_file);
}

void update_pid(double target, double current, double *p, double *i, double *d, double *output, double dt)
{
    double error = target - current;
    *p = KP * error;
    *i += KI * error * dt;
    *d = KD * (error - (target - current)) / dt;
    *output = *p + *i + *d;
}

void encoder1_a_callback(int gpio, int level, uint32_t tick, void *user)
{
    static int last_level = 0;
    int current_level = gpioRead(ENCODER1_B);

    if (level == PI_HIGH && last_level == PI_LOW)
    {
        pthread_mutex_lock(&encoder_mutex);
        encoder1_count++;
        pthread_mutex_unlock(&encoder_mutex);
    }
    else if (level == PI_LOW && last_level == PI_HIGH)
    {
        pthread_mutex_lock(&encoder_mutex);
        encoder1_count--;
        pthread_mutex_unlock(&encoder_mutex);
    }

    last_level = level;
}

void encoder1_b_callback(int gpio, int level, uint32_t tick, void *user)
{
    // This callback is used to determine the direction of rotation.
    // The direction is determined by reading the state of the B pin.
    // If the A and B pins are both high or both low, the direction is forward.
    // If the A pin is high and the B pin is low, or vice versa, the direction is backward.
    // This is a simplified example and may need adjustment based on your specific setup.
    // For a more robust quadrature decoding, consider using a dedicated quadrature decoder library.
}

void encoder2_a_callback(int gpio, int level, uint32_t tick, void *user)
{
    static int last_level = 0;
    int current_level = gpioRead(ENCODER2_B);

    if (level == PI_HIGH && last_level == PI_LOW)
    {
        pthread_mutex_lock(&encoder_mutex);
        encoder2_count++;
        pthread_mutex_unlock(&encoder_mutex);
    }
    else if (level == PI_LOW && last_level == PI_HIGH)
    {
        pthread_mutex_lock(&encoder_mutex);
        encoder2_count--;
        pthread_mutex_unlock(&encoder_mutex);
    }

    last_level = level;
}

void encoder2_b_callback(int gpio, int level, uint32_t tick, void *user)
{
    // This callback is used to determine the direction of rotation.
    // The direction is determined by reading the state of the B pin.
    // If the A and B pins are both high or both low, the direction is forward.
    // If the A pin is high and the B pin is low, or vice versa, the direction is backward.
    // This is a simplified example and may need adjustment based on your specific setup.
