#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_PIN 17 // BCM GPIO 17
#define I2C_BUS 1
#define LOG_FILE "relay_log.txt"

// MPR121 Register Addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C

// Global variables
static int mpr121_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init(int fd);
int read_touch_status(int fd);
void control_relay(int pin, int state);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
        control_relay(RELAY_PIN, LOW); // Turn off relay
        if (mpr121_fd != -1) {
            close(mpr121_fd);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        exit(0);
    }
}

// MPR121 Initialization function
int mpr121_init(int fd) {
    // Soft reset
    if (wiringPiI2CWriteReg8(fd, MPR121_ECR, 0x80) < 0) {
        log_event("Error: Soft reset failed.");
        return -1;
    }
    delay(1); // Wait for reset to complete

    // Configure Electrode Configuration Register (ECR)
    if (wiringPiI2CWriteReg8(fd, MPR121_ECR, 0x00) < 0) { // Disable all electrodes initially
        log_event("Error: Failed to configure ECR.");
        return -1;
    }

    // Configure Filtering Parameters (Example values, adjust as needed)
    if (wiringPiI2CWriteReg8(fd, MPR121_CONFIG1, 0x20) < 0) { // Default value
        log_event("Error: Failed to configure CONFIG1.");
        return -1;
    }
    if (wiringPiI2CWriteReg8(fd, MPR121_CONFIG2, 0x01) < 0) { // Default value
        log_event("Error: Failed to configure CONFIG2.");
        return -1;
    }

    // Set touch and release thresholds for each electrode (example values)
    for (int i = 0; i < 12; i++) {
        if (wiringPiI2CWriteReg8(fd, 0x41 + (i * 2), 40) < 0) { // Touch threshold
            log_event("Error: Failed to set touch threshold.");
            return -1;
        }
        if (wiringPiI2CWriteReg8(fd, 0x42 + (i * 2), 20) < 0) { // Release threshold
            log_event("Error: Failed to set release threshold.");
            return -1;
        }
    }

    // Enable all electrodes (ECR = 0x10)
    if (wiringPiI2CWriteReg8(fd, MPR121_ECR, 0x10) < 0) {
        log_event("Error: Failed to enable electrodes.");
        return -1;
    }

    log_event("MPR121 initialized successfully.");
    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(int fd) {
    int touch_status_l = wiringPiI2CReadReg8(fd, MPR121_TOUCHSTATUS_L);
    int touch_status_h = wiringPiI2CReadReg8(fd, MPR121_TOUCHSTATUS_H);

    if (touch_status_l < 0 || touch_status_h < 0) {
        log_event("Error: Failed to read touch status.");
        return -1;
    }

    return (touch_status_h << 8) | touch_status_l;
}

// Function to control the relay
void control_relay(int pin, int state) {
    digitalWrite(pin, state);
    char message[100];
    sprintf(message, "Relay set to %s", state == HIGH ? "HIGH" : "LOW");
    log_event(message);
}

// Function to log events to a file
void log_event(const char *message) {
    if (log_file == NULL) return; // Check if log file is open

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file); // Ensure the log is written immediately
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Failed to initialize WiringPi. %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    mpr121_fd = wiringPiI2CSetupInterface("/dev/i2c-1", MPR121_ADDR);
    if (mpr121_fd == -1) {
        fprintf(stderr, "Error: Failed to open I2C device. %s\n", strerror(errno));
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file. %s\n", strerror(errno));
        close(mpr121_fd);
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(mpr121_fd) == -1) {
        fprintf(stderr, "Error: MPR121 initialization failed.\n");
        fclose(log_file);
        close(mpr121_fd);
        return 1;
    }

    // Set relay pin as output
    pinMode(RELAY_PIN, OUTPUT);
    control_relay(RELAY_PIN, LOW); // Initialize relay to LOW

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int touch_status = read_touch_status(mpr121_fd);
        if (touch_status == -1) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            delay(100); // Wait before retrying
            continue;
        }

        // Check if any electrode is touched
        if (touch_status > 0) {
            control_relay(RELAY_PIN, HIGH);
        } else {
            control_relay(RELAY_PIN, LOW);
        }

        delay(50); // Poll every 50ms
    }

    // Clean up resources before exiting (should not reach here if signal handler works)
    control_relay(RELAY_PIN, LOW);
    if (mpr121_fd != -1) {
        close(mpr121_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

