#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define valve activation durations (in milliseconds)
#define VALVE1_DURATION 500
#define VALVE2_DURATION 1000

// Define valve activation intervals (in seconds)
#define VALVE1_INTERVAL 5
#define VALVE2_INTERVAL 10

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void activate_valve(int gpio_pin, int duration_ms);
void log_event(int valve_number, int duration_ms);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(VALVE1_GPIO, PI_OUTPUT);
    gpioSetMode(VALVE2_GPIO, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to activate a valve for a specified duration
void activate_valve(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Activate the valve (HIGH)
    gpioDelay(duration_ms * 1000); // Delay for the specified duration (in microseconds)
    gpioWrite(gpio_pin, 0); // Deactivate the valve (LOW)
}

// Function to log an event to the log file
void log_event(int valve_number, int duration_ms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s Valve %d activated for %d ms\n", timestamp, valve_number, duration_ms);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(VALVE1_GPIO, 0); // Ensure valves are off
    gpioWrite(VALVE2_GPIO, 0);
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the log file
    log_file = fopen("valve_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Water distribution schedule started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Activate Valve 1
        activate_valve(VALVE1_GPIO, VALVE1_DURATION);
        log_event(1, VALVE1_DURATION);
        gpioDelay(VALVE1_INTERVAL * 1000000); // Delay for VALVE1_INTERVAL seconds (in microseconds)

        // Activate Valve 2
        activate_valve(VALVE2_GPIO, VALVE2_DURATION);
        log_event(2, VALVE2_DURATION);
        gpioDelay(VALVE2_INTERVAL * 1000000); // Delay for VALVE2_INTERVAL seconds (in microseconds)
    }

    // Clean up and exit
    cleanup();
    return 0;
}

