// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define TOUCH_THRESHOLD 0x30
#define RELEASE_THRESHOLD 0x10
#define FILTER_CONFIG 0x24
#define CHARGE_TIME 0x0D
#define ELECTRODE_CURRENT 0x5E

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int mpr121_configure_electrodes();
int mpr121_set_filter_and_charge();
int mpr121_set_electrode_current();
int mpr121_set_touch_thresholds();
int mpr121_set_release_thresholds();
int mpr121_enter_run_mode();
int read_touch_status(uint16_t *touch_status);
int toggle_relay();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// MPR121 initialization function
int mpr121_init() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to stop mode\n");
        return -1;
    }
    gpioDelay(100000); // 100ms

    // Configure electrodes
    if (mpr121_configure_electrodes() < 0) {
        fprintf(stderr, "Error: Failed to configure electrodes\n");
        return -1;
    }

    // Set filter and charge time
    if (mpr121_set_filter_and_charge() < 0) {
        fprintf(stderr, "Error: Failed to set filter and charge time\n");
        return -1;
    }

    // Set electrode current
    if (mpr121_set_electrode_current() < 0) {
        fprintf(stderr, "Error: Failed to set electrode current\n");
        return -1;
    }

    // Set touch thresholds
    if (mpr121_set_touch_thresholds() < 0) {
        fprintf(stderr, "Error: Failed to set touch thresholds\n");
        return -1;
    }

    // Set release thresholds
    if (mpr121_set_release_thresholds() < 0) {
        fprintf(stderr, "Error: Failed to set release thresholds\n");
        return -1;
    }

    // Enter run mode
    if (mpr121_enter_run_mode() < 0) {
        fprintf(stderr, "Error: Failed to enter run mode\n");
        return -1;
    }

    return 0;
}

// Configure electrode function
int mpr121_configure_electrodes() {
    // Example configuration (adjust as needed)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x5E + (i * 2), 0x0F) < 0) { // Set Electrode Filter
            fprintf(stderr, "Error: Failed to set electrode filter for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x5F + (i * 2), 0x0F) < 0) { // Set Electrode Filter
            fprintf(stderr, "Error: Failed to set electrode filter for electrode %d\n", i);
            return -1;
        }
    }
    return 0;
}

// Set filter and charge time function
int mpr121_set_filter_and_charge() {
    if (i2cWriteByteData(i2c_handle, FILTER_CONFIG, 0x3F) < 0) {
        fprintf(stderr, "Error: Failed to set filter config\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CHARGE_TIME, 0x0A) < 0) {
        fprintf(stderr, "Error: Failed to set charge time\n");
        return -1;
    }
    return 0;
}

// Set electrode current function
int mpr121_set_electrode_current() {
    if (i2cWriteByteData(i2c_handle, ELECTRODE_CURRENT, 0x20) < 0) {
        fprintf(stderr, "Error: Failed to set electrode current\n");
        return -1;
    }
    return 0;
}

// Set touch thresholds function
