#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define PIR_GPIO 17
#define RELAY_GPIO 18
#define UNLOCK_DURATION 500 // milliseconds
#define RATE_LIMIT 2000      // milliseconds
#define POLL_INTERVAL 50     // milliseconds

static volatile int running = 1;
static FILE *log_file = NULL;
static unsigned long last_unlock_time = 0;

void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    int pir_value, prev_pir_value = 0;
    struct timespec ts;
    unsigned long current_time;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Set pull-down resistor on PIR GPIO
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Door strike controller started. Press Ctrl+C to exit.\n");

    while (running) {
        pir_value = gpioRead(PIR_GPIO);

        if (pir_value == 1 && prev_pir_value == 0) {
            // Motion detected
            clock_gettime(CLOCK_MONOTONIC, &ts);
            current_time = (unsigned long)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);

            if (current_time - last_unlock_time > RATE_LIMIT) {
                // Rate limit check passed
                gpioWrite(RELAY_GPIO, 1); // Activate relay
                gpioDelay(UNLOCK_DURATION); // Keep relay active for UNLOCK_DURATION ms
                gpioWrite(RELAY_GPIO, 0); // Deactivate relay

                clock_gettime(CLOCK_MONOTONIC, &ts);
                current_time = (unsigned long)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
                last_unlock_time = current_time;

                fprintf(log_file, "%lu: Motion detected, door unlocked\n", current_time);
                fflush(log_file);
            } else {
                // Rate limited
                clock_gettime(CLOCK_MONOTONIC, &ts);
                current_time = (unsigned long)(ts.tv_sec * 1000 + ts.tv_nsec / 1000000);
                fprintf(log_file, "%lu: Motion detected, rate limited\n", current_time);
                fflush(log_file);
            }
        }

        prev_pir_value = pir_value;
        gpioDelay(POLL_INTERVAL); // Poll every POLL_INTERVAL ms
    }

    // Cleanup
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    fclose(log_file);
    gpioTerminate();

    printf("Door strike controller stopped.\n");
    return 0;
}

