#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

volatile sig_atomic_t shutdown_flag = 0;

void signal_handler(int signal) {
    shutdown_flag = 1;
    printf("\nCaught signal %d, shutting down...\n", signal);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR1_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR2_GPIO);
        gpioTerminate();
        return 1;
    }

    srand(time(NULL));

    signal(SIGINT, signal_handler);

    while (!shutdown_flag) {
        int num_steps = (rand() % 6) + 5; // Random number of steps between 5 and 10
        for (int i = 0; i < num_steps; i++) {
            int duty_cycle1 = rand() % 256; // Random duty cycle for motor 1
            int duty_cycle2 = rand() % 256; // Random duty cycle for motor 2
            int duration = (rand() % 151) + 50; // Random duration between 50ms and 200ms

            gpioPWM(MOTOR1_GPIO, duty_cycle1);
            gpioPWM(MOTOR2_GPIO, duty_cycle2);
            gpioDelay(duration * 1000); // Convert ms to microseconds
        }
    }

    gpioPWM(MOTOR1_GPIO, 0); // Stop motor 1
    gpioPWM(MOTOR2_GPIO, 0); // Stop motor 2

    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

