#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define SCALE_FACTOR_DEFAULT 1.0
#define OFFSET_DEFAULT 0.0
#define WEIGHT_THRESHOLD 10.0 // kg
#define CALIBRATION_SAMPLES 100
#define READ_INTERVAL_MS 500
#define READ_TIMEOUT_US 500000 // 0.5 seconds

// Global variables
static volatile int running = 1;
static double scale_factor = SCALE_FACTOR_DEFAULT;
static double offset = OFFSET_DEFAULT;
static FILE *log_file = NULL;

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value);
void control_solenoid(double weight);
void log_data(double weight);
void load_calibration_data();
void save_calibration_data();
void signal_handler(int signal);

// HX711 read function
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    gpioWrite(HX711_CLOCK_PIN, 0);

    // Wait for data line to go low
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < READ_TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= READ_TIMEOUT_US) {
        fprintf(stderr, "Error: HX711 read timeout\n");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock pulse width
    }

    // 25th pulse for gain selection (default gain = 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Weight calculation function
double calculate_weight(int raw_value) {
    return (raw_value - offset) / scale_factor;
}

// Solenoid control function
void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1); // Engage solenoid
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Disengage solenoid
    }
}

// Data logging function
void log_data(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Weight: %.2f kg\n", timestamp, weight);
    fflush(log_file); // Ensure data is written to file immediately
}

// Load calibration data from file
void load_calibration_data() {
    FILE *fp = fopen("calibration.txt", "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: calibration.txt not found, using default values\n");
        scale_factor = SCALE_FACTOR_DEFAULT;
        offset = OFFSET_DEFAULT;
        return;
    }

    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Warning: Invalid calibration data in calibration.txt, using default values\n");
        scale_factor = SCALE_FACTOR_DEFAULT;
        offset = OFFSET_DEFAULT;
    }

    fclose(fp);
}

// Save calibration data to file
void save_calibration_data() {
    FILE *fp = fopen("calibration.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration.txt for writing\n");
        return;
    }

    fprintf(fp, "%lf %lf\n", scale_factor, offset);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Load calibration data
    load_calibration_data();

    // Initialize solenoid to disengaged state
    gpioWrite(SOLENOID_PIN, 0);

    // Open log file
    log_file = fopen("weight_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open weight_log.txt for writing\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // One-time calibration
    printf("Starting one-time calibration...\n");
    double sum = 0.0;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: HX711 read failed during calibration, skipping\n");
            continue; // Skip this reading
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }
    offset = sum / CALIBRATION_SAMPLES;
    printf("Calibration complete. Offset: %.2f\n", offset);
    save_calibration_data();

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: HX711 read failed, skipping iteration\n");
            gpioDelay(READ_INTERVAL_MS); // Wait before next attempt
            continue;
        }

        double weight = calculate_weight(raw_value);
        control_solenoid(weight);
        log_data(weight);

        gpioDelay(READ_INTERVAL_MS);
    }

    // Cleanup
    gpioWrite(SOLENOID_PIN, 0); // Disengage solenoid
    fclose(log_file);
    gpioTerminate();

    return 0;
}

