// Signal handler function
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, stopping motor and exiting...");
    stop_motor();
    gpioTerminate();
    closelog();
    exit(0);
}

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to debounce the rain sensor readings
int debounce_readings(int pin) {
    int readings[DEBOUNCE_READINGS];
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        readings[i] = gpioRead(pin);
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
    }

    int sum = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        sum += readings[i];
    }

    return (sum >= RAIN_THRESHOLD) ? 1 : 0;
}

// Function to determine if it is raining based on the debounced readings
int is_raining(int readings) {
    return (readings == 1) ? 1 : 0;
}

// Function to close the window by activating the motor
void close_window() {
    log_event("Closing window...");
    gpioWrite(MOTOR_IN1_PIN, 1);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 150);
    gpioDelay(MOTOR_DURATION_S * 1000000); // Convert seconds to microseconds
    stop_motor();
    log_event("Window closed.");
}

// Function to stop the motor
void stop_motor() {
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
}

