    // Initialize syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_PWM_PIN, 1000);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Window control system started");

    // Main loop
    while (running) {
        int readings = debounce_readings(RAIN_SENSOR_PIN);
        int raining = is_raining(readings);

        if (raining) {
            close_window();
            gpioDelay(MOTOR_DELAY_S * 1000000); // Convert seconds to microseconds
        }

        gpioDelay(60000000); // Check every 60 seconds (converted to microseconds)
    }

    // Cleanup
    stop_motor();
    gpioTerminate();
    closelog();

    return 0;
}

