        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA, PI_INPUT);
    gpioSetMode(HX711_CLOCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially unlocked

    return 0;
}

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int timeout_start = gpioTick();

    // Wait for data line to go low
    while (gpioRead(HX711_DATA) == 1) {
        if (gpioTick() - timeout_start > TIMEOUT_MS * 1000) {
            fprintf(stderr, "HX711 timeout\n");
            return -1; // Timeout
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK, 1);
        gpioDelay(1); // Clock high delay
        data = data << 1;
        if (gpioRead(HX711_DATA)) {
            data++;
        }
        gpioWrite(HX711_CLOCK, 0);
        gpioDelay(1); // Clock low delay
    }

    // Pulse the clock pin 1 more time for gain 128
    gpioWrite(HX711_CLOCK, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

