#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_GPIO 16
#define RELAY_GPIO 20
#define LOG_FILE "relay_events.log"

static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log events to a file
int log_event(const char *timestamp, const char *state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "%s - Relay state: %s\n", timestamp, state);
    fclose(fp);
    return 0;
}

int main() {
    int sensor_value;
    int relay_state = 0; // 0 = OFF, 1 = ON
    char *timestamp;
    int result;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_GPIO, PI_INPUT);
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Main loop
    while (running) {
        // Read sensor value
        sensor_value = gpioRead(SENSOR_GPIO);

        if (sensor_value == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading sensor value\n");
            timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                log_event(timestamp, "ERROR");
                free(timestamp);
            }
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Toggle relay state if obstacle is detected (sensor value is LOW)
        if (sensor_value == 0) {
            relay_state = !relay_state;
            gpioWrite(RELAY_GPIO, relay_state);

            // Log the event
            timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                result = log_event(timestamp, relay_state ? "ON" : "OFF");
                if (result != 0) {
                    fprintf(stderr, "Error logging event\n");
                }
                free(timestamp);
            }
        }

        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    // Clean up GPIO resources before exiting
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF
    gpioTerminate();

    return 0;
}

