#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 17
#define BUZZER_PIN 18

// Define buzzer duration (in microseconds)
#define BUZZER_DURATION 2000000 // 2 seconds

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void activate_buzzer();
void log_motion();
void signal_handler(int signal);
void cleanup();

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read PIR sensor
        if (read_pir_sensor() == 1) {
            // Activate buzzer
            activate_buzzer();

            // Log motion
            log_motion();
        }

        // Small delay to avoid busy-waiting
        usleep(100000); // 100ms
    }

    // Cleanup and exit
    cleanup();
    printf("Motion detection stopped.\n");
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off initially

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    int pir_value = gpioRead(PIR_SENSOR_PIN);
    if (pir_value < 0) {
        fprintf(stderr, "Error reading PIR sensor value\n");
        return 0; // Return 0 to avoid unexpected behavior
    }
    return pir_value;
}

// Activate buzzer for 2 seconds
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    usleep(BUZZER_DURATION);
    gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
}

// Log motion event with timestamp
void log_motion() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s Motion detected\n", timestamp);
    fflush(log_file); // Ensure data is written to file immediately
    printf("%s Motion detected\n", timestamp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Signal received (%d).  Shutting down...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    // Turn off buzzer
    gpioWrite(BUZZER_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

