#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"
#define MAX_DURATION 3600

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int read_config(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading config file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Remove trailing newline character
    line[strcspn(line, "\n")] = 0;

    char *key = strtok(line, "=");
    char *value = strtok(NULL, "=");

    if (key == NULL || value == NULL) {
        fprintf(stderr, "Invalid config file format. Expected 'duration=<seconds>'.\n");
        return -1;
    }

    if (strcmp(key, "duration") != 0) {
        fprintf(stderr, "Invalid config file format. Expected 'duration=<seconds>'.\n");
        return -1;
    }

    char *endptr;
    long val = strtol(value, &endptr, 10);

    if (*endptr != '\0' || val < 1 || val > MAX_DURATION) {
        fprintf(stderr, "Invalid duration value. Must be between 1 and %d.\n", MAX_DURATION);
        return -1;
    }

    *duration = (int)val;
    return 0;
}

