    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int duration;
    if (read_config(CONFIG_FILE, &duration) != 0) {
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Ensure valve is off initially

    printf("Watering for %d seconds...\n", duration);

    gpioWrite(GPIO_PIN, 1); // Activate valve
    printf("Valve ON\n");
    sleep(duration);
    gpioWrite(GPIO_PIN, 0); // Deactivate valve
    printf("Valve OFF\n");

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

