#include <unistd.h>

// Define GPIO pins
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define LEFT_MOTOR_PWM_PIN 22
#define LEFT_MOTOR_DIR_PIN 23
#define RIGHT_MOTOR_PWM_PIN 24
#define RIGHT_MOTOR_DIR_PIN 25

// Define motor speeds
#define BASE_SPEED 150
#define HALF_SPEED 75

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define log file name
#define LOG_FILE "trace_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
void set_motor_speed(int motor, int speed);
void stop_motors();
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed);
void signal_handler(int signal);

// Structure to hold motor states
typedef struct {
    int left_speed;
    int right_speed;
} MotorState;

MotorState current_motor_state = {0, 0};

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensor values
        int left_sensor = read_sensor(LEFT_SENSOR_PIN);
        int middle_sensor = read_sensor(MIDDLE_SENSOR_PIN);
        int right_sensor = read_sensor(RIGHT_SENSOR_PIN);

        // Determine motor speeds based on sensor values
        int left_speed = BASE_SPEED;
        int right_speed = BASE_SPEED;

        if (left_sensor == 0 && middle_sensor == 1 && right_sensor == 1) {
            // All sensors are high, go straight
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED;
        } else if (left_sensor == 0 && middle_sensor == 1 && right_sensor == 1) {
            // Only left sensor is low, turn right
            left_speed = HALF_SPEED;
            right_speed = BASE_SPEED;
        } else if (left_sensor == 1 && middle_sensor == 1 && right_sensor == 0) {
            // Only right sensor is low, turn left
            left_speed = BASE_SPEED;
            right_speed = HALF_SPEED;
        } else {
            // All sensors are low or mixed, stop
            left_speed = 0;
            right_speed = 0;
        }

        // Set motor speeds
        set_motor_speed(0, left_speed);
        set_motor_speed(1, right_speed);

        // Log data
        log_data(left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        // Wait for 10ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Stop motors and cleanup
    stop_motors();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

