int read_sensor(int pin) {
    return gpioRead(pin);
}

// Set motor speed
void set_motor_speed(int motor, int speed) {
    int pwm_pin, dir_pin;

    if (motor == 0) {
        // Left motor
        pwm_pin = LEFT_MOTOR_PWM_PIN;
        dir_pin = LEFT_MOTOR_DIR_PIN;
    } else {
        // Right motor
        pwm_pin = RIGHT_MOTOR_PWM_PIN;
        dir_pin = RIGHT_MOTOR_DIR_PIN;
    }

    // Set direction (1 for forward, 0 for backward)
    gpioWrite(dir_pin, (speed > 0) ? 1 : 0);

    // Set PWM duty cycle (0-255)
    gpioPWM(pwm_pin, abs(speed));

    if (motor == 0) {
        current_motor_state.left_speed = speed;
    } else {
        current_motor_state.right_speed = speed;
    }
}

// Stop motors
