#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPi.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define RELAY_GPIO 23 // BCM GPIO 23
#define LUX_THRESHOLD 150.0f
#define MEASUREMENT_DELAY_MS 180
#define LOG_FILE "grow_log.txt"

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int read_bh1750(int fd, float *lux);
void control_relay(int gpio, int state);
void log_data(float lux, int relay_state);
void signal_handler(int sig);

// I2C initialization function
int init_i2c(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// BH1750 read function
int read_bh1750(int fd, float *lux) {
    uint8_t buf[2];
    int retries = 3;

    while (retries > 0) {
        // Send measurement command
        if (write(fd, &CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
            perror("Error writing to I2C device");
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }

        usleep(MEASUREMENT_DELAY_MS * 1000); // Wait for measurement

        // Read 2 bytes of data
        if (read(fd, buf, 2) != 2) {
            perror("Error reading from I2C device");
            retries--;
            usleep(10000); // 10ms delay
            continue;
        }

        // Convert data to lux
        uint16_t raw_value = (buf[0] << 8) | buf[1];
        *lux = (float)raw_value / 1.2f;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read BH1750 after multiple retries.\n");
    return -1; // Failure
}

// Relay control function
void control_relay(int gpio, int state) {
    digitalWrite(gpio, state);
}

// Logging function
void log_data(float lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Lux: %.2f, Relay: %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing WiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Set relay GPIO as output
    pinMode(RELAY_GPIO, OUTPUT);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    float lux;
    int relay_state = 0; // 0 = OFF, 1 = ON

    // Main loop
    while (!terminate) {
        if (read_bh1750(i2c_fd, &lux) == 0) {
            log_data(lux, relay_state);

            if (lux < LUX_THRESHOLD && !relay_state) {
                control_relay(RELAY_GPIO, 1); // Turn on relay
                relay_state = 1;
                log_data(lux, relay_state);
            } else if (lux >= LUX_THRESHOLD && relay_state) {
                control_relay(RELAY_GPIO, 0); // Turn off relay
                relay_state = 0;
                log_data(lux, relay_state);
            }
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    control_relay(RELAY_GPIO, 0); // Turn off relay on exit
    return 0;
}

