#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse width limits
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define servo angles
#define SERVO_LOCK_ANGLE 0
#define SERVO_UNLOCK_ANGLE 180

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set the servo pulse width
int set_servo_pulse_width(int gpio, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Invalid pulse width: %d. Must be between %d and %d.\n", pulse_width, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
        return -1; // Indicate an error
    }

    if (gpioServo(gpio, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set servo pulse width to %d.\n", pulse_width);
        return -1; // Indicate an error
    }

    return 0; // Indicate success
}

// Function to read the button state with debouncing
int read_button(int gpio) {
    int button_state = gpioRead(gpio);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay in microseconds
    return (gpioRead(gpio) == button_state) ? button_state : 1; // Return 1 if still stable, 0 otherwise
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1; // Exit with an error code
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Set pull-up resistors for buttons
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check lock button
        if (read_button(LOCK_BUTTON_PIN) == 0) {
            printf("Lock button pressed. Setting servo to lock position.\n");
            if (set_servo_pulse_width(SERVO_PIN, SERVO_MIN_PULSE_WIDTH) != 0) {
                fprintf(stderr, "Error setting servo pulse width for lock.\n");
            }
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        // Check unlock button
        if (read_button(UNLOCK_BUTTON_PIN) == 0) {
            printf("Unlock button pressed. Setting servo to unlock position.\n");
            if (set_servo_pulse_width(SERVO_PIN, SERVO_MAX_PULSE_WIDTH) != 0) {
                fprintf(stderr, "Error setting servo pulse width for unlock.\n");
            }
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        gpioDelay(10000); // Small delay to reduce CPU usage
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

