#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define pulse durations (in milliseconds)
#define MOTOR1_DURATION 200
#define MOTOR2_DURATION 300

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void pulse_motor(int pin, int duration_ms);
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and configure GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop: pulse the motors sequentially indefinitely
    while (program_running) {
        // Pulse motor 1
        pulse_motor(MOTOR1_PIN, MOTOR1_DURATION);

        // Pulse motor 2
        pulse_motor(MOTOR2_PIN, MOTOR2_DURATION);
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initializes the pigpio library and configures the GPIO pins.
int initialize_gpio() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as outputs
    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Pulses the specified motor for the given duration.
void pulse_motor(int pin, int duration_ms) {
    // Set the GPIO pin HIGH to activate the motor
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Failed to write HIGH to GPIO%d\n", pin);
        program_running = 0; // Stop the program if there's an error
        return;
    }

    // Delay for the specified duration
    gpioDelay(duration_ms * 1000); // Convert milliseconds to microseconds

    // Set the GPIO pin LOW to deactivate the motor
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Failed to write LOW to GPIO%d\n", pin);
        program_running = 0; // Stop the program if there's an error
        return;
    }
}

// Cleans up GPIO resources by setting all pins to LOW and terminating the pigpio library.
void cleanup_gpio() {
    // Set all GPIO pins to LOW
    gpioWrite(MOTOR1_PIN, 0);
    gpioWrite(MOTOR2_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();
}

// Signal handler function to catch SIGINT and SIGTERM signals.
void signal_handler(int signal) {
    printf("Caught signal %d.  Exiting gracefully.\n", signal);
    program_running = 0; // Set the flag to exit the main loop
}

