#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <zmq.h>

#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO 27
#define ZMQ_ENDPOINT "tcp://*:5555"
#define ZMQ_TOPIC "SOUND_ALERTS"

static volatile int running = 1;
static void *context = NULL;
static void *publisher = NULL;
static void *subscriber = NULL;

void signal_handler(int signal) {
    printf("Caught signal %d, exiting...\n", signal);
    running = 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  mode: sound_sensor | alarm_node\n");
        return 1;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        // Sound sensor mode
        if (gpioInitialise() < 0) {
            fprintf(stderr, "pigpio initialisation failed\n");
            return 1;
        }

        gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT);
        gpioSetPullUpDown(SOUND_SENSOR_GPIO, PI_PUD_UP);

        signal(SIGINT, signal_handler);
        signal(SIGTERM, signal_handler);

        context = zmq_ctx_new();
        if (!context) {
            fprintf(stderr, "zmq_ctx_new failed\n");
            gpioTerminate();
            return 1;
        }

        publisher = zmq_socket(context, ZMQ_PUB);
        if (!publisher) {
            fprintf(stderr, "zmq_socket (PUB) failed\n");
            zmq_ctx_destroy(context);
            gpioTerminate();
            return 1;
        }

        int rc = zmq_bind(publisher, ZMQ_ENDPOINT);
        if (rc != 0) {
            fprintf(stderr, "zmq_bind failed: %s\n", zmq_strerror(errno));
            zmq_close(publisher);
            zmq_ctx_destroy(context);
            gpioTerminate();
            return 1;
        }

        printf("Sound sensor node started, publishing to %s\n", ZMQ_ENDPOINT);

        while (running) {
            int sound_detected = gpioRead(SOUND_SENSOR_GPIO) == 0;
            if (sound_detected) {
                char message[256];
                struct timeval tv;
                gettimeofday(&tv, NULL);
                snprintf(message, sizeof(message), "%ld.%06ld: Sound detected!", tv.tv_sec, tv.tv_usec);

                zmq_msg_t zmq_message;
                zmq_msg_init_size(&zmq_message, strlen(message));
                memcpy(zmq_msg_data(&zmq_message), message, strlen(message));

                rc = zmq_msg_send(&zmq_message, publisher, 0);
                zmq_msg_close(&zmq_message);

                if (rc == -1) {
                    fprintf(stderr, "zmq_msg_send failed: %s\n", zmq_strerror(errno));
                    running = 0; // Exit on error
                } else {
                    printf("Published: %s\n", message);
                }
            }
            gpioDelay(10000); // 10ms
        }

        zmq_close(publisher);
        zmq_ctx_destroy(context);
        gpioTerminate();

        printf("Sound sensor node stopped\n");
        return 0;
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        // Alarm node mode
        if (gpioInitialise() < 0) {
            fprintf(stderr, "pigpio initialisation failed\n");
            return 1;
        }

        gpioSetMode(ALARM_LED_GPIO, PI_OUTPUT);

        signal(SIGINT, signal_handler);
        signal(SIGTERM, signal_handler);

        context = zmq_ctx_new();
        if (!context) {
            fprintf(stderr, "zmq_ctx_new failed\n");
            gpioTerminate();
            return 1;
        }

        subscriber = zmq_socket(context, ZMQ_SUB);
        if (!subscriber) {
            fprintf(stderr, "zmq_socket (SUB) failed\n");
            zmq_ctx_destroy(context);
            gpioTerminate();
            return 1;
        }

        int rc = zmq_connect(subscriber, ZMQ_ENDPOINT);
        if (rc != 0) {
            fprintf(stderr, "zmq_connect failed: %s\n", zmq_strerror(errno));
            zmq_close(subscriber);
            zmq_ctx_destroy(context);
            gpioTerminate();
            return 1;
        }

        rc = zmq_setsockopt(subscriber, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC));
        if (rc != 0) {
            fprintf(stderr, "zmq_setsockopt (ZMQ_SUBSCRIBE) failed: %s\n", zmq_strerror(errno));
            zmq_close(subscriber);
            zmq_ctx_destroy(context);
            gpioTerminate();
            return 1;
        }

        printf("Alarm node started, subscribing to %s\n", ZMQ_ENDPOINT);

        while (running) {
            zmq_msg_t zmq_message;
            zmq_msg_init(&zmq_message);

            rc = zmq_msg_recv(&zmq_message, subscriber, 0);
            if (rc == -1) {
                if (errno == EINTR) {
                    break; // Interrupted by signal, exit loop
                }
                fprintf(stderr, "zmq_msg_recv failed: %s\n", zmq_strerror(errno));
                running = 0; // Exit on error
                break;
            }

            char *message = zmq_msg_data(&zmq_message);
            size_t message_size = zmq_msg_size(&zmq_message);

            printf("Received: %s\n", message);

            gpioWrite(ALARM_LED_GPIO, 1); // Turn on LED
            gpioDelay(1000000);           // Wait 1 second
            gpioWrite(ALARM_LED_GPIO, 0); // Turn off LED

            zmq_msg_close(&zmq_message);
        }

        zmq_close(subscriber);
        zmq_ctx_destroy(context);
        gpioTerminate();

        printf("Alarm node stopped\n");
        return 0;
    } else {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        return 1;
    }
}

