        gpioSetMode(ALARM_LED_GPIO, PI_OUTPUT);

        signal(SIGINT, signal_handler);
        signal(SIGTERM, signal_handler);

        context = zmq_ctx_new();
        if (!context) {
            fprintf(stderr, "zmq_ctx_new failed\n");
            gpioTerminate();
            return 1;
        }

        subscriber = zmq_socket(context, ZMQ_SUB);
        if (!subscriber) {
            fprintf(stderr, "zmq_socket (SUB) failed\n");
            zmq_ctx_destroy(context);
            gpioTerminate();
            return 1;
        }

        int rc = zmq_connect(subscriber, ZMQ_ENDPOINT);
        if (rc != 0) {
            fprintf(stderr, "zmq_connect failed: %s\n", zmq_strerror(errno));
            zmq_close(subscriber);
            zmq_ctx_destroy(context);
            gpioTerminate();
            return 1;
        }

        rc = zmq_setsockopt(subscriber, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC));
        if (rc != 0) {
            fprintf(stderr, "zmq_setsockopt (ZMQ_SUBSCRIBE) failed: %s\n", zmq_strerror(errno));
            zmq_close(subscriber);
            zmq_ctx_destroy(context);
            gpioTerminate();
            return 1;
        }

        printf("Alarm node started, subscribing to %s\n", ZMQ_ENDPOINT);

        while (running) {
            zmq_msg_t zmq_message;
            zmq_msg_init(&zmq_message);

            rc = zmq_msg_recv(&zmq_message, subscriber, 0);
            if (rc == -1) {
                if (errno == EINTR) {
                    break; // Interrupted by signal, exit loop
                }
                fprintf(stderr, "zmq_msg_recv failed: %s\n", zmq_strerror(errno));
                running = 0; // Exit on error
                break;
            }

            char *message = zmq_msg_data(&zmq_message);
            size_t message_size = zmq_msg_size(&zmq_message);

            printf("Received: %s\n", message);

            gpioWrite(ALARM_LED_GPIO, 1); // Turn on LED
            gpioDelay(1000000);           // Wait 1 second
            gpioWrite(ALARM_LED_GPIO, 0); // Turn off LED

            zmq_msg_close(&zmq_message);
        }

        zmq_close(subscriber);
        zmq_ctx_destroy(context);
        gpioTerminate();

        printf("Alarm node stopped\n");
        return 0;
    } else {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        return 1;
    }
}

