#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <mosquitto.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define IR_RECEIVER_GPIO 17
#define MQTT_KEEPALIVE 60

// NEC timing constants (in microseconds)
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_RAPID_PULSE 10000 // Rapid pulse threshold

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;
static char *mqtt_topic = "ir/decoded";
static char *mqtt_broker = "localhost";
static int mqtt_port = 1883;
static int nec_address = 0;
static int nec_command = 0;
static int nec_extended = 0;

// Function prototypes
void signal_handler(int sig);
int init_gpio();
int init_mqtt();
void cleanup();
void ir_callback(int gpio, int level, uint32_t tick);
int decode_nec(uint32_t *pulses, int pulse_count);
int validate_checksum(uint8_t address, uint8_t command, uint8_t inverted_command);
void publish_mqtt(uint8_t address, uint8_t command, uint8_t inverted_command);
void log_message(int priority, const char *message);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    log_message(LOG_INFO, "Received signal, shutting down...");
}

// Initialize GPIO using pigpio
int init_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    gpioSetMode(IR_RECEIVER_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_RECEIVER_GPIO, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Initialize MQTT client
int init_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        log_message(LOG_ERR, "Failed to create mosquitto instance");
        return 1;
    }

    if (mosquitto_connect(mosq, mqtt_broker, mqtt_port, MQTT_KEEPALIVE) != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        mosq = NULL;
        return 1;
    }

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    log_message(LOG_INFO, "Cleaning up resources...");

    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }

    mosquitto_lib_cleanup();

    gpioTerminate();

    closelog();
}

// IR receiver callback function
void ir_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    static uint32_t pulse_buffer[100]; // Buffer for pulse timings
    static int pulse_count = 0;
    uint32_t duration;

    duration = tick - last_tick;
    last_tick = tick;

    if (duration > NEC_RAPID_PULSE) {
        // Rapid pulse detected, reset pulse buffer
        pulse_count = 0;
        return;
    }

    if (pulse_count < 100) {
        pulse_buffer[pulse_count++] = duration;
    } else {
        log_message(LOG_WARNING, "Pulse buffer overflow!");
        pulse_count = 0; // Reset buffer
        return;
    }

    if (pulse_count >= 68) { // NEC frame consists of 68 pulses
        uint32_t decoded_address, decoded_command, decoded_inverted_command;
        if (decode_nec(pulse_buffer, pulse_count)) {
            // Checksum validation
            if (validate_checksum(nec_address, nec_command, nec_inverted_command)) {
                publish_mqtt(nec_address, nec_command, nec_inverted_command);
            } else {
                char log_message_buffer[256];
                snprintf(log_message_buffer, sizeof(log_message_buffer), "Checksum failed: Address=0x%02X, Command=0x%02X, Inverted=0x%02X", nec_address, nec_command, nec_inverted_command);
                log_message(LOG_WARNING, log_message_buffer);
            }
        } else {
            log_message(LOG_WARNING, "NEC decoding failed");
        }
        pulse_count = 0; // Reset pulse count after processing
    }
}

// Decode NEC protocol
int decode_nec(uint32_t *pulses, int pulse_count) {
    if (pulse_count < 68) {
        return 0; // Not enough pulses
    }

    // Verify header
    if (pulses[0] < NEC_HEADER_MARK * 0.8 || pulses[0] > NEC_HEADER_MARK * 1.2 ||
        pulses[1] < NEC_HEADER_SPACE * 0.8 || pulses[1] > NEC_HEADER_SPACE * 1.2) {
        return 0; // Invalid header
    }

    nec_address = 0;
    nec_command = 0;
    nec_inverted_command = 0;

    // Decode address (8 bits)
    for (int i = 2; i < 10; i++) {
        if (pulses[2 * i] < NEC_BIT_MARK * 0.8 || pulses[2 * i] > NEC_BIT_MARK * 1.2) {
            return 0; // Invalid bit mark
        }
        if (pulses[2 * i + 1] > NEC_ONE_SPACE * 0.8) {
            nec_address |= (1 << (9 - i));
        }
    }

    // Decode command (8 bits)
    for (int i = 10; i < 18; i++) {
        if (pulses[2 * i] < NEC_BIT_MARK * 0.8 || pulses[2 * i] > NEC_BIT_MARK * 1.2) {
            return 0; // Invalid bit mark
        }
        if (pulses[2 * i + 1] > NEC_ONE_SPACE * 0.8) {
            nec_command |= (1 << (17 - i));
        }
    }

    // Decode inverted command (8 bits)
    for (int i = 18; i < 26; i++) {
        if (pulses[2 * i] < NEC_BIT_MARK * 0.8 || pulses[2 * i] > NEC_BIT_MARK * 1.2) {
            return 0; // Invalid bit mark
        }
        if (pulses[2 * i + 1] > NEC_ONE_SPACE * 0.8) {
            nec_inverted_command |= (1 << (25 - i));
        }
    }

    return 1; // Decoding successful
}

// Validate NEC checksum
int validate_checksum(uint8_t address, uint8_t command, uint8_t inverted_command) {
    uint8_t checksum = address ^ command;
    return (checksum == inverted_command);
}

// Publish decoded command to MQTT broker
void publish_mqtt(uint8_t address, uint8_t command, uint8_t inverted_command) {
    char payload[256];
    snprintf(payload, sizeof(payload), "{\"address\": \"0x%02X\", \"command\": \"0x%02X\", \"inverted\": \"0x%02X\"}", address, command, inverted_command);

    int ret = mosquitto_publish(mosq, NULL, mqtt_topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        char log_message_buffer[256];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "MQTT publish error: %s", mosquitto_strerror(ret));
        log_message(LOG_ERR, log_message_buffer);
    } else {
        char log_message_buffer[256];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "Published: %s", payload);
        log_message(LOG_INFO, log_message_buffer);
    }
}

// Log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:b:p:")) != -1) {
        switch (opt) {
            case 't':
                mqtt_topic = optarg;
                break;
            case 'b':
                mqtt_broker = optarg;
                break;
            case 'p':
                mqtt_port = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t topic] [-b broker] [-p port]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio()) {
        closelog();
        return 1;
    }

    // Initialize MQTT
    if (init_mqtt()) {
        cleanup();
        return 1;
    }

    // Set alert function for IR receiver
    gpioSetAlertFuncEx(IR_RECEIVER_GPIO, ir_callback, NULL);

    log_message(LOG_INFO, "IR decoder started");

    // Main loop
    while (running) {
        mosquitto_loop(mosq, 0, 1); // Non-blocking loop
        sleep(1); // Reduce CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

