#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define NUM_SENSORS 4
#define SENSOR_ADDRESSES {0x23, 0x24, 0x25, 0x26}
#define START_MEASUREMENT 0x10 // High Resolution Mode
#define LUX_SCALE_FACTOR 1.2

// Global variables
volatile sig_atomic_t terminate = 0;
int i2c_fds[NUM_SENSORS];
int udp_socket;

// Function prototypes
int init_i2c(int sensor_id);
float read_bh1750(int fd);
void send_udp_packet(const char *data);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");
    // Close I2C file descriptors
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_fds[i] != -1) {
            close(i2c_fds[i]);
        }
    }

    // Close UDP socket
    if (udp_socket != -1) {
        close(udp_socket);
    }

    printf("Cleanup complete.\n");
}

// Initialize I2C for a sensor
int init_i2c(int sensor_id) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, sensor_id) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read lux value from BH1750FVI sensor
float read_bh1750(int fd) {
    uint8_t buf[2];
    int retries = 3;

    while (retries > 0) {
        // Send start measurement command
        if (write(fd, &START_MEASUREMENT, 1) != 1) {
            perror("Error writing to I2C device");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        usleep(180000); // Wait for measurement (180ms)

        // Read 2 bytes of data
        if (read(fd, buf, 2) != 2) {
            perror("Error reading from I2C device");
            retries--;
            usleep(10000); // Wait before retrying
            continue;
        }

        // Combine bytes to form lux value
        uint16_t raw_value = (buf[0] << 8) | buf[1];
        float lux = (float)raw_value / LUX_SCALE_FACTOR;
        return lux;
    }

    fprintf(stderr, "Failed to read sensor after multiple retries.\n");
    return NAN; // Return NaN on failure
}

// Send UDP multicast packet
void send_udp_packet(const char *data) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(udp_socket, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending UDP packet");
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C file descriptors
    int sensor_addresses[NUM_SENSORS] = SENSOR_ADDRESSES;
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = init_i2c(sensor_addresses[i]);
        if (i2c_fds[i] == -1) {
            fprintf(stderr, "Failed to initialize sensor %d, skipping.\n", i + 1);
        }
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating UDP socket");
        cleanup();
        return 1;
    }

    // Configure multicast TTL
    int ttl = 1;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Error setting multicast TTL");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        char data[256] = {0}; // Buffer for sensor data
        int data_len = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_fds[i] != -1) {
                float lux = read_bh1750(i2c_fds[i]);
                if (!isnan(lux)) {
                    data_len += snprintf(data + data_len, sizeof(data) - data_len, "%d,%.2f;", i + 1, lux);
                    if (data_len >= sizeof(data)) {
                        fprintf(stderr, "Data buffer overflow, truncating.\n");
                        data_len = sizeof(data) - 1;
                        break;
                    }
                } else {
                    fprintf(stderr, "Failed to read sensor %d, skipping.\n", i + 1);
                }
            }
        }

        // Remove trailing semicolon
        if (data_len > 0) {
            data[data_len - 1] = '\0';
        }

        send_udp_packet(data);
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

