#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define FLOW_SCALE_FACTOR 0.01 // Example scaling factor (adjust based on datasheet)
#define LOG_FILE "airflow_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int flow_rate;
    float slpm;
} SensorData;

// Function prototypes
int initialize_i2c();
int read_sensor_data(unsigned char *data);
SensorData process_sensor_data(unsigned char *data);
int log_flow_rate(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data with retries
int read_sensor_data(unsigned char *data) {
    int result, retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, (char *)data, 2);
        if (result == 2) {
            return 0; // Success
        } else if (result < 0) {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
            retries++;
        } else {
            fprintf(stderr, "I2C read returned unexpected length: %d\n", result);
            return -1; // Unexpected length
        }
    }
    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure after retries
}

// Function to process sensor data
SensorData process_sensor_data(unsigned char *data) {
    SensorData sensor_data;
    int raw_flow = ((data[0] << 8) | data[1]) & 0x3FFF; // Mask to 14 bits
    sensor_data.flow_rate = raw_flow;
    sensor_data.slpm = (float)raw_flow * FLOW_SCALE_FACTOR;
    return sensor_data;
}

// Function to log flow rate
int log_flow_rate(SensorData data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Flow Rate: %d, SLPM: %.2f\n", timestamp, data.flow_rate, data.slpm);
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    unsigned char sensor_data[2];
    SensorData processed_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Process sensor data
            processed_data = process_sensor_data(sensor_data);

            // Log flow rate
            log_flow_rate(processed_data);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

