#define AS7341_F3DATAL 0x99
#define AS7341_F4DATAH 0x9A
#define AS7341_F4DATAL 0x9B
#define AS7341_F5DATAH 0x9C
#define AS7341_F5DATAL 0x9D
#define AS7341_F6DATAH 0x9E
#define AS7341_F6DATAL 0x9F
#define AS7341_F7DATAH 0xA0
#define AS7341_F7DATAL 0xA1
#define AS7341_F8DATAH 0xA2
#define AS7341_F8DATAL 0xA3
#define AS7341_CDATAH 0xA4
#define AS7341_CDATAL 0xA5
#define AS7341_NIRDATAH 0xA6
#define AS7341_NIRDATAL 0xA7

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
}

// Function to read a register from the AS7341
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to write a register to the AS7341
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the AS7341
int initialize_sensor(int handle) {
    uint8_t id;

    // Check sensor ID
    if (read_register(handle, AS7341_ID, &id) != 0) {
        fprintf(stderr, "Error reading sensor ID.\n");
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", id);
        return -1;
    }

    // Enable power and set SMUX
    if (write_register(handle, AS7341_ENABLE, 0x03) != 0) return -1; // PON and AEN
    if (write_register(handle, AS7341_CFG6, 0x03) != 0) return -1;  // SMUX = Large IR

    // Enable spectral measurement
    if (write_register(handle, AS7341_ENABLE, 0x23) != 0) return -1; // PON, AEN, SP_EN

    return 0;
}

// Function to read spectral data from the AS7341
int read_spectral_data(int handle, uint16_t spectral_data[10]) {
    uint8_t f1h, f1l, f2h, f2l, f3h, f3l, f4h, f4l, f5h, f5l, f6h, f6l, f7h, f7l, f8h, f8l, ch, nirh, nirl;

    if (read_register(handle, AS7341_F1DATAH, &f1h) != 0) return -1;
    if (read_register(handle, AS7341_F1DATAL, &f1l) != 0) return -1;
    if (read_register(handle, AS7341_F2DATAH, &f2h) != 0) return -1;
    if (read_register(handle, AS7341_F2DATAL, &f2l) != 0) return -1;
    if (read_register(handle, AS7341_F3DATAH, &f3h) != 0) return -1;
    if (read_register(handle, AS7341_F3DATAL, &f3l) != 0) return -1;
    if (read_register(handle, AS7341_F4DATAH, &f4h) != 0) return -1;
    if (read_register(handle, AS7341_F4DATAL, &f4l) != 0) return -1;
    if (read_register(handle, AS7341_F5DATAH, &f5h) != 0) return -1;
    if (read_register(handle, AS7341_F5DATAL, &f5l) != 0) return -1;
    if (read_register(handle, AS7341_F6DATAH, &f6h) != 0) return -1;
    if (read_register(handle, AS7341_F6DATAL, &f6l) != 0) return -1;
    if (read_register(handle, AS7341_F7DATAH, &f7h) != 0) return -1;
    if (read_register(handle, AS7341_F7DATAL, &f7l) != 0) return -1;
    if (read_register(handle, AS7341_F8DATAH, &f8h) != 0) return -1;
    if (read_register(handle, AS7341_F8DATAL, &f8l) != 0) return -1;
    if (read_register(handle, AS7341_CDATAH, &ch) != 0) return -1;
    if (read_register(handle, AS7341_CDATAL, &ch) != 0) return -1;
    if (read_register(handle, AS7341_NIRDATAH, &nirh) != 0) return -1;
    if (read_register(handle, AS7341_NIRDATAL, &nirl) != 0) return -1;

    spectral_data[0] = (f1h << 8) | f1l;
    spectral_data[1] = (f2h << 8) | f2l;
    spectral_data[2] = (f3h << 8) | f3l;
    spectral_data[3] = (f4h << 8) | f4l;
    spectral_data[4] = (f5h << 8) | f5l;
    spectral_data[5] = (f6h << 8) | f6l;
    spectral_data[6] = (f7h << 8) | f7l;
    spectral_data[7] = (f8h << 8) | f8l;
    spectral_data[8] = (ch << 8) | ch; // Clear
    spectral_data[9] = (nirh << 8) | nirl; // NIR

    return 0;
}

// Function to approximate lux from spectral data (simplified)
float approximate_lux(uint16_t spectral_data[10]) {
    // This is a very basic approximation.  A real implementation would
    // use a more sophisticated algorithm based on the AS7341's spectral
    // response characteristics.
    float lux = 0.0;
    for (int i = 0; i < 10; i++) {
        lux += spectral_data[i]; // Sum all spectral values
    }
    return lux / 10.0; // Average
}

// Function to log data to a file
int log_data(FILE *file, uint16_t spectral_data[10], float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(file, "%s", timestamp);
    for (int i = 0; i < 10; i++) {
        fprintf(file, ",%u", spectral_data[i]);
    }
    fprintf(file, ",%.2f\n", lux);
    fflush(file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, AS7341_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t spectral_data[10];
    float lux;

    // Main loop
    while (!terminate) {
        // Read spectral data
        if (read_spectral_data(i2c_handle, spectral_data) == 0) {
            // Approximate lux
            lux = approximate_lux(spectral_data);

            // Log data
            log_data(log_file, spectral_data, lux);
        } else {
            fprintf(stderr, "Error reading spectral data.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close resources
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

