#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x4C
#define DEFAULT_SAMPLING_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define I2C_BUS 1
#define RETRY_COUNT 3
#define RETRY_DELAY_US 10000 // 10ms

// Global variables
int i2c_handle;
FILE *data_file = NULL;
FILE *error_file = NULL;
int running = 1;

// Structure for sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int initialize_i2c(int i2c_address);
int read_sensor_data(int i2c_handle, sensor_data_t *data);
void convert_to_g(sensor_data_t *data);
int log_data(FILE *fp, sensor_data_t *data);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c(int i2c_address) {
    i2c_handle = i2cOpen(I2C_BUS, i2c_address, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Function to read sensor data with retries
int read_sensor_data(int i2c_handle, sensor_data_t *data) {
    char buf[6];
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle, 0x10, buf, 6); // Read X, Y, Z registers
        if (result == 6) {
            data->x = (int16_t)((buf[1] << 8) | buf[0]);
            data->y = (int16_t)((buf[3] << 8) | buf[2]);
            data->z = (int16_t)((buf[5] << 8) | buf[4]);
            return 0; // Success
        } else {
            log_error("I2C read failed, retrying...");
            gpioDelay(RETRY_DELAY_US);
            retries--;
        }
    }

    log_error("I2C read failed after multiple retries");
    return -1; // Failure
}

// Function to convert raw data to g-force units
void convert_to_g(sensor_data_t *data) {
    // Assuming 1g = 1000 counts (adjust as needed based on sensor datasheet)
    data->x /= 1000.0; // Convert to g
    data->y /= 1000.0; // Convert to g
    data->z /= 1000.0; // Convert to g
}

// Function to log data to CSV file
int log_data(FILE *fp, sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, data->x, data->y, data->z);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Function to log errors to log file
int log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(error_file, "%s: %s\n", timestamp, message);
    fflush(error_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int sampling_interval = DEFAULT_SAMPLING_INTERVAL;
    char *filename = DEFAULT_FILENAME;
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                sampling_interval = atoi(optarg);
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i sampling_interval] [-f filename]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log files
    data_file = fopen(filename, "w");
    if (data_file == NULL) {
        fprintf(stderr, "Failed to open data file\n");
        gpioTerminate();
        return 1;
    }

    error_file = fopen("seismic_error.log", "a");
    if (error_file == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        fclose(data_file);
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(i2c_address) != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (running) {
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            convert_to_g(&sensor_data);
            log_data(data_file, &sensor_data);
        } else {
            log_error("Failed to read sensor data");
        }

        sleep(sampling_interval);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

