#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1

int i2c_fd = -1;
int udp_socket = -1;

void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    exit(0);
}

float read_bh1750() {
    uint8_t buf[2];
    uint16_t raw_value;
    float lux;

    // Write command to start measurement
    if (write(i2c_fd, &CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1.0;
    }

    // Wait for measurement to complete (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes from the sensor
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1.0;
    }

    // Combine the bytes into a 16-bit value (big-endian)
    raw_value = (buf[0] << 8) | buf[1];

    // Convert raw value to lux
    lux = (float)raw_value / 1.2;

    return lux;
}

int main() {
    struct sockaddr_in multicast_addr;
    char lux_str[20];
    int retries = 3;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Failed to create UDP socket");
        close(i2c_fd);
        return 1;
    }

    // Configure multicast address
    memset(&multicast_addr, 0, sizeof(multicast_addr));
    multicast_addr.sin_family = AF_INET;
    multicast_addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    multicast_addr.sin_port = htons(MULTICAST_PORT);

    // Set TTL for multicast
    int ttl_val = TTL;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl_val, sizeof(ttl_val)) < 0) {
        perror("Failed to set TTL");
        close(udp_socket);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        float lux = read_bh1750();

        if (lux >= 0) {
            // Format lux value as string
            snprintf(lux_str, sizeof(lux_str), "%.2f", lux);

            // Send lux value via UDP multicast
            if (sendto(udp_socket, lux_str, strlen(lux_str), 0, (struct sockaddr *)&multicast_addr, sizeof(multicast_addr)) < 0) {
                perror("Failed to send UDP packet");
            }
            printf("Sent: %s\n", lux_str);
        } else {
            fprintf(stderr, "Failed to read lux value, retrying...\n");
            retries--;
            if (retries <= 0) {
                fprintf(stderr, "Too many retries, exiting.\n");
                break;
            }
            sleep(1);
        }

        sleep(1);
    }

    // Cleanup
    close(udp_socket);
    close(i2c_fd);

    return 0;
}

