}

int setup_uart(const char *port, speed_t baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting UART attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode
    tty.c_cc[VMIN] = 0;                              // Read returns immediately if no data is available
    tty.c_cc[VTIME] = 0;                             // No timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting UART attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_line(int fd, char *buffer, size_t buffer_size) {
    fd_set readfds;
    struct timeval timeout;
    int bytes_read = 0;
    char c;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = 0;

    int select_result = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (select_result == -1) {
        perror("Error in select");
        return -1;
    } else if (select_result == 0) {
        fprintf(stderr, "Timeout reading from UART\n");
        return 0; // Timeout
    }

    while (bytes_read < buffer_size - 1) {
        ssize_t bytes = read(fd, &c, 1);
        if (bytes == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // No data available, break the loop
                break;
            } else {
                perror("Error reading from UART");
                return -1;
            }
        } else if (bytes == 0) {
            // End of file, break the loop
            break;
        }

        buffer[bytes_read++] = c;
        if (c == '\n') {
            buffer[bytes_read] = '\0';
            return bytes_read;
        }
    }

    buffer[bytes_read] = '\0';
    return bytes_read;
}

int parse_data(const char *line, long *timestamp, float *range) {
    char *token;
    char *str = strdup(line); // Duplicate the string for strtok
