#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define UART device and baud rate
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variables
int uart_handle;
int pigpio_initialized = 0;

// Function prototypes
int initialize_pigpio();
int read_sensor(int gpio_pin);
void emergency_stop();
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int left;
    int middle;
    int right;
} sensor_data_t;

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;
    return 0;
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to handle emergency stop
void emergency_stop() {
    const char *message = "EMERGENCY STOP!\n";
    int bytes_written = gpioSerialWrite(uart_handle, message, strlen(message));
    if (bytes_written < 0) {
        fprintf(stderr, "Error writing to UART: %d\n", bytes_written);
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function
void cleanup() {
    if (pigpio_initialized) {
        gpioTerminate();
    }
    if (uart_handle >= 0) {
        gpioSerialReadClose(uart_handle);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio()) {
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Open UART device
    uart_handle = gpioSerialReadOpen(UART_DEVICE, BAUD_RATE, 8); // 8N1
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_handle);
        cleanup();
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int middle_value = read_sensor(MIDDLE_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log sensor data with timestamp
        printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left_value, middle_value, right_value);

        // Check for emergency stop condition
        if (left_value == 0 && middle_value == 0 && right_value == 0) {
            emergency_stop();
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

